	section	text

;------------------------------------------------------------------------------
; Compiler start-up: Mshrink to text+data+bss+$218e, then Malloc all free memory less $4000 as the
; work area (address bss_end+$78, size bss_end+$74); sp = bss_end+$208e. Falls into the main loop.
;------------------------------------------------------------------------------
start:
	movea.l	4(sp),a5                        ; a5 = basepage
	move.l	a5,bss_end+$ac                  ; keep the basepage
	lea	bss_end+$208e,sp                ; own stack inside the bss
	movea.l	$c(a5),a0                       ; text + data + bss lengths ...
	adda.l	$14(a5),a0
	adda.l	$1c(a5),a0
	adda.w	#$218e,a0                       ; ... plus the compiler's own work space
	pea	(a0)                            ; Mshrink new size
	pea	(a5)                            ; Mshrink block: the basepage
	clr.w	-(sp)                           ; reserved word 0
	move.w	#$4a,-(sp)                      ; GEMDOS $4a Mshrink
	trap	#1                              ; Mshrink
	pea	$ffffffff.w                     ; Malloc(-1): size of the largest free block
	move.w	#$48,-(sp)                      ; GEMDOS $48 Malloc
	trap	#1                              ; Malloc
	subi.l	#$4000,d0                       ; leave 16K for GEM and GEMDOS
	move.l	d0,bss_end+$74                  ; size of the work area
	move.l	d0,-(sp)                        ; size: all free memory less 16K
	move.w	#$48,-(sp)                      ; GEMDOS $48 Malloc
	trap	#1                              ; Malloc
	adda.w	#$18,sp                         ; drop the Mshrink and both Malloc arguments
	move.l	d0,bss_end+$78                  ; address of the work area
	bsr.w	init_gem                        ; GEM initialisation (outside this range)

;------------------------------------------------------------------------------
; Main loop, once per program: reset the progress bar, run the options dialog and file selector,
; open the .BAS file, read its 126-byte header into bas_header (version word, 'GfABASIC', then the
; 29 header longs at bss_end+$00..$70) and check it. Turns the storage bounds into the table of
; variable offsets in the runtime start-up (rt_var_type_offsets), lays out the label / PROCEDURE /
; FN tables (16 bytes per entry) in the work area, reads all lines once to collect the DATA items,
; then seeks back to the lines and compiles them one by one (compile_next_line).
;------------------------------------------------------------------------------
compile_next_program:
	st	progress_screen_offset          ; progress offset $ffff: the next line restarts the bar
	bsr.w	options_dialog                  ; dialog and file selector (outside this range)
	bsr.w	open_source_file
	lea	bas_header,a0                   ; read the 126-byte header into dat_0d17a
	moveq	#126,d0                         ; 126 bytes: version word, 'GfABASIC' and the 29 header longs
	bsr.w	read_source_bytes               ; read d0 bytes from the .BAS file to a0
	cmpi.w	#$2,bas_header                  ; version word above 2: not a GFA BASIC 2.x file
	bhi.w	error_not_gfa_basic
	cmpi.l	#$47664142,bas_magic_gfab       ; 'GfAB'
	bne.w	error_not_gfa_basic
	cmpi.l	#$41534943,bas_magic_asic       ; 'ASIC'
	bne.w	error_not_gfa_basic
	moveq	#126,d0                         ; file offset of the lines: $7e + bound 12
	add.l	bss_end+$30,d0                  ; d0 = Fseek position of the lines
	clr.w	-(sp)                           ; Fseek mode 0 (arguments stay on the stack for the second seek)
	move.w	bas_file_handle,-(sp)           ; input file handle
	move.l	d0,-(sp)                        ; Fseek offset
	move.l	bss_end+$3c,d7                  ; d7 = length of the lines (storage start - lines start)
	sub.l	bss_end+$30,d7                  ; d7 = number of bytes of line text
	lea	bss_end+$3c,a0                  ; the 9 storage bounds: float $ ...
	lea	rt_var_type_offsets,a1          ; the 9-long variable offset table in the runtime start-up
	moveq	#8,d1                           ; 9 bounds (dbra count)
	move.l	(a0),d0                         ; d0 = start of the float storage
.make_relative:
	sub.l	d0,(a0)                         ; bound made relative to the float storage
	move.l	(a0)+,d2                        ; d2 = bound relative to the float storage
	subi.l	#$8000,d2                       ; variables are addressed as d(a5) with a $8000 bias
	move.l	d2,(a1)+                        ; store it in the runtime's variable offset table
	dbra	d1,.make_relative
	move.l	-(a0),d2                        ; label storage bound back to absolute
	add.l	d0,d2                           ; + float storage start
	move.l	d2,(a0)                         ; store the label storage bound as an absolute address again
	move.l	bss_end+$78,d0                  ; work area base
	moveq	#4,d1                           ; 5 tables: label, PROCEDURE, FN, FN$ and the end
.scale_table_bounds:
	move.l	(a0),d3
	sub.l	d2,d3                           ; 4 bytes of storage per entry ...
	asl.l	#2,d3                           ; ... become 16 bytes in the compiler's table
	add.l	d0,d3                           ; rebased on the work area
	move.l	d3,(a0)+                        ; new table bound
	dbra	d1,.scale_table_bounds
	move.l	d3,bss_end+$30                  ; end of the tables: the lines are read here
	lea	bss_end+$7c,a0                  ; the 9 output region pointers bss_end+$7c..$9c all start empty
	moveq	#8,d1
.init_regions:
	move.l	d3,(a0)+                        ; every region starts at the end of the tables
	dbra	d1,.init_regions
	move.w	#$42,-(sp)                      ; Fseek to the lines
	trap	#1                              ; Fseek
	addq.l	#2,sp                           ; drop the Fseek function word; the arguments stay
	tst.l	d0
	bmi.w	error_os                        ; seek failed: file error
	movea.l	d3,a0
	move.l	d7,d0
	bsr.w	read_source_bytes
	bsr.w	link_structures
	tst.b	d7
	bmi.w	compile_next_program
	movea.l	bss_end+$80,a0                  ; DATA pass: a0 reads the lines, a1 writes the DATA items
	movea.l	a0,a1                           ; a1 = DATA write pointer, from the start of the lines
	movea.l	a0,a2                           ; a2 = top of the area to shift up (stays equal to a1)
	moveq	#0,d0
.scan_line:
	move.b	(a0),d0                         ; d0 = line length
	cmpi.b	#$1,1(a0)                       ; command 1 = DATA
	beq.s	.data_line
	cmpi.b	#$df,1(a0)                      ; $df = the last line
	beq.w	.data_done
.next_line:
	adda.w	d0,a0                           ; next line
	bra.s	.scan_line
.data_line:
	move.l	a1,d2                           ; d2 = offset of the next DATA item
	sub.l	bss_end+$7c,d2                  ; relative to the DATA region start
	tst.b	rt_data_pad_flag                ; odd item pending: the pad byte is taken back
	beq.s	.mark_labels
	subq.l	#1,d2                           ; one byte back: the new items start in the pad byte
.mark_labels:
	movea.l	bss_end+$5c,a3                  ; label table
	move.l	bss_end+$60,d1                  ; end of the label table
	sub.l	a3,d1                           ; byte size of the label table
	lsr.l	#4,d1                           ; 16 bytes per entry
	bra.s	.label_count                    ; enter the dbra loop
.label_loop:
	move.l	(a3)+,d7                        ; label's line address (low 24 bits)
	andi.l	#$ffffff,d7
	cmp.l	a0,d7                           ; label at or before this DATA line?
	bhi.s	.next_label
	tas	(a3)                            ; first DATA after it only: bit 7 marks the entry as set
	bne.s	.next_label
	move.l	d2,4(a3)                        ; entry+8 = DATA offset used by RESTORE label
.next_label:
	adda.w	#$c,a3                          ; next 16-byte entry
.label_count:
	dbra	d1,.label_loop
	move.w	d0,d1                           ; d1 = line length (not used further)
	lea	bss_end+$3d0,a3                 ; items are built at bss_end+$3d0
	movea.l	a3,a4                           ; a4 = start of this line's items
	moveq	#2,d2                           ; skip length and command bytes
.item_start:
	move.b	0(a0,d2.w),d3
	cmpi.b	#$22,d3                         ; $22 = '"': quoted item
	beq.s	.quoted_char
.item_char:
	move.b	0(a0,d2.w),d3
	cmpi.b	#$d,d3                          ; $0d ends the DATA text
	beq.s	.items_done
	cmpi.b	#$2c,d3                         ; a ',' between items becomes a NUL
	bne.s	.store_char
	moveq	#0,d3                           ; NUL separator
.store_char:
	move.b	d3,(a3)+
	addq.w	#1,d2                           ; next text byte
	bra.s	.item_start
.quoted_char:
	addq.w	#1,d2
	move.b	0(a0,d2.w),d3                   ; next character inside the quotes
	cmpi.b	#$22,d3                         ; a doubled quote stays one quote ...
	bne.s	.store_quoted
	cmpi.b	#$2c,1(a0,d2.w)                 ; ... unless the quote closes the item
	beq.s	.closing_quote
	cmpi.b	#$d,1(a0,d2.w)
	bne.s	.store_quoted                   ; a quote before the CR also closes the item
.closing_quote:
	addq.w	#1,d2                           ; step over the closing quote
	bra.s	.item_char
.store_quoted:
	cmpi.b	#$d,d3                          ; CR inside quotes also ends the text
	beq.s	.items_done
	move.b	d3,(a3)+                        ; store the character
	bra.s	.quoted_char
.items_done:
	clr.b	(a3)+                           ; NUL after the last item
	tst.b	rt_data_pad_flag                ; was the previous item odd?
	beq.s	.item_length
	move.b	(a4)+,-$1(a1)                   ; first byte fills the previous odd item's pad byte
.item_length:
	move.l	a3,d1                           ; d1 = length of the items
	sub.l	a4,d1
	btst	#$0,d1                          ; odd length: remember it and pad
	sne	rt_data_pad_flag
	beq.s	.make_room                      ; even: no pad
	addq.l	#1,d1                           ; one pad byte
.make_room:
	lea	0(a2,d1.l),a3                   ; make room: move the area above a1 up by d1
	move.l	a3,d3                           ; d3 = new top of the shifted area
	bra.s	.move_test
.move_up:
	move.w	-(a3),-(a2)                     ; shift a word up
.move_test:
	cmpa.l	a1,a2
	bhi.s	.move_up                        ; until a2 reaches a1
	movea.l	d3,a2                           ; a2 = new top
	bra.s	.copy_test
.copy_items:
	move.b	(a4)+,(a1)+                     ; copy the items to the DATA area
.copy_test:
	dbra	d1,.copy_items
	bra.w	.next_line                      ; next line
.copy_line:
	move.b	(a0)+,(a2)+                     ; not reached: copies a line (no branch leads here)
	dbra	d0,.copy_line
	moveq	#0,d2                           ; not reached
	bra.w	.next_line
.data_done:
	move.l	a1,bss_end+$80                  ; $df: DATA area ends at a1
	move.l	a1,bss_end+$84                  ; region bss_end+$84 empty, at the end of the DATA
	lea	bss_end+$88,a0                  ; regions bss_end+$88..$9c start after it
	moveq	#5,d0                           ; 6 regions (dbra count)
.set_regions:
	move.l	a2,(a0)+                        ; each starts after the DATA
	dbra	d0,.set_regions
	move.l	bss_end+$88,d0                  ; last call, reloc and break-test positions
	move.l	d0,bss_end+$a0                  ; call list position = start of the code region
	move.l	d0,bss_end+$a4
	move.l	d0,bss_end+$a8
	move.w	#$42,-(sp)                      ; Fseek back to the start of the lines
	trap	#1                              ; Fseek
	adda.w	#$a,sp                          ; drop the Fseek arguments left from $a2
	tst.l	d0
	bmi.w	error_os                        ; seek failed: file error
	bsr.w	fill_source_buffer

;------------------------------------------------------------------------------
; Compiles one line: advance the progress bar, compile_line, then append the line's code and its
; runtime-call list to the output (with a break test first when Stop is Ever).
;------------------------------------------------------------------------------
compile_next_line:
	bsr.w	show_progress_line
	bsr.w	compile_line
	move.b	option_stop_mode,d0             ; Stop option: negative = Ever
	bpl.s	.no_break_test
	cmpa.l	#bss_end+$3d0,a2                ; no code for this line: no break test
	beq.s	.no_break_test
	jmp	flush_line_with_break_test      ; flush with a jsr (a6) break test
.no_break_test:
	bsr.s	flush_line_code

;------------------------------------------------------------------------------
; Loops until the line just compiled was the last ($df), then names the output .PRG, writes it and starts again.
;------------------------------------------------------------------------------
check_program_end:
	cmpi.b	#$df,bss_end+$c05               ; current line's command: $df = program end
	bne.s	compile_next_line
	bsr.w	close_source_file               ; outside this range
	move.l	#$2e505247,d0                   ; '.PRG'
	movea.l	rsc_tree_unused,a0              ; program name
	bsr.w	file_selector                   ; set the extension (outside this range)
	dc.w	$a009                           ; Line-A Show mouse
	bsr.w	create_program_file
	bsr.w	select_runtime_routines
	bsr.w	write_program
	bsr.w	close_program_file
	dc.w	$a00a                           ; Line-A Hide mouse
	bra.w	compile_next_program            ; next program

;------------------------------------------------------------------------------
; Re-reads the screen address (Physbase) and restarts the progress bar at the top.
;------------------------------------------------------------------------------
progress_restart:
	move.w	#$2,-(sp)                       ; Physbase
	trap	#14                             ; Physbase
	addq.l	#2,sp
	move.l	d0,progress_screen_address      ; screen address for the progress bar
	clr.w	progress_screen_offset

;------------------------------------------------------------------------------
; Progress bar: inverts one 80-byte screen line (20 longs) per compiled line, from the top of the
; screen; at the end of the screen (32000) it starts again at the top.
;------------------------------------------------------------------------------
show_progress_line:
	movea.l	progress_screen_address,a0
	move.w	progress_screen_offset,d1       ; d1 = offset of the next screen line
	cmpi.w	#$7d00,d1                       ; past the end of the screen (or the $ffff start mark)
	bcc.s	progress_restart
	adda.w	d1,a0                           ; a0 = the screen line to invert
	moveq	#19,d0                          ; 20 longs = 80 bytes
.invert_line:
	not.l	(a0)+                           ; invert a long
	dbra	d0,.invert_line
	addi.w	#$50,progress_screen_offset     ; next screen line
	rts

; Long: the screen address the progress bar inverts (initial value decoded as code).
progress_screen_address:
	dc.w	$000f                           ; long: screen address (decoded as code)
	or.b	d0,d0

; Word: offset of the next screen line to invert; $ffff forces a restart.
progress_screen_offset:
	dc.w	$ffff                           ; word: offset of the next line to invert

;------------------------------------------------------------------------------
; Appends the line's code (bss_end+$3d0 up to a2) to the code region bss_end+$88 and the line's
; runtime-call position list (bss_end+$a10 up to a3) to region bss_end+$94, via the region insert
; routine open_memory_gap.
;------------------------------------------------------------------------------
flush_line_code:
	lea	bss_end+$88,a0
	move.l	a2,d0                           ; d0 = code bytes of the line
	subi.l	#bss_end+$3d0,d0
	beq.s	.done                           ; no code
	bsr.w	open_memory_gap                 ; make room for d0 bytes at the end of the code region
	lea	bss_end+$3d0,a1                 ; copy from the line's code buffer
	lsr.w	#1,d0                           ; bytes to words
	bra.s	.copy_code_test
.copy_code:
	move.w	(a1)+,(a0)+                     ; copy a word
.copy_code_test:
	dbra	d0,.copy_code
	move.l	a3,d0                           ; length of the runtime-call list
	subi.l	#bss_end+$a10,d0
	beq.s	.done
	lea	bss_end+$94,a0                  ; runtime-call list region
	bsr.w	open_memory_gap                 ; make room at the end of region a0
	lea	bss_end+$a10,a1
	lsr.w	#1,d0                           ; bytes to words
	bra.s	.copy_calls_test
.copy_calls:
	move.w	(a1)+,(a0)+                     ; copy a word
.copy_calls_test:
	dbra	d0,.copy_calls
.done:
	rts

;------------------------------------------------------------------------------
; Error exit: closes the input and output files and starts the next program; with $60 at
; bss_end+$12c it stops on an illegal instruction instead (purpose not worked out).
;------------------------------------------------------------------------------
abort_compile:
	cmpi.b	#$60,bss_end+$12c               ; $60 there: debug stop (meaning not worked out)
	beq.s	.debug_stop
	lea	bss_end+$208e,sp                ; reset the stack
	move.w	bas_file_handle,-(sp)           ; input handle
	move.w	#$3e,-(sp)                      ; GEMDOS $3e Fclose
	trap	#1                              ; Fclose
	move.w	prg_file_handle,(sp)            ; output handle
	move.w	#$3e,-(sp)                      ; GEMDOS $3e Fclose
	trap	#1                              ; Fclose
	addq.l	#6,sp                           ; drop the Fclose arguments
	bra.w	compile_next_program
.debug_stop:
	illegal

;------------------------------------------------------------------------------
; Fatal alert 'GFA-BASIC?': the file is not a GFA BASIC 2.x program.
;------------------------------------------------------------------------------
error_not_gfa_basic:
	bsr.w	compile_error_fatal             ; fatal alert with the inline text
	dc.b	'Datei ist kein GFA-BASIC',0
	dc.b	$00,$4e,$75,$42,$67,$4e,$41     ; unused bytes after the text

;------------------------------------------------------------------------------
; Command $53 (==>, a line the editor marked as a syntax error): fatal alert 'Syntax Error in
; Program'.
;------------------------------------------------------------------------------
cmd_syntax_error_line:
	bsr.w	compile_error_fatal
	dc.b	'Syntax Fehler im Programm',0

;------------------------------------------------------------------------------
; Commands that cannot be compiled (LIST, LLIST, PSAVE, LOAD, SAVE, STOP, TRON, TROFF, CONT,
; DEFLIST and the $de token): compile_error_continue shows the inline text 'xxx ???' and lets the
; user skip the line or give up. Parts of the texts are decoded as instructions.
;------------------------------------------------------------------------------
cmd_list_unsupported:
	bsr.w	compile_error_continue
	dc.b	'LIST ???',0
	dc.b	$00

;------------------------------------------------------------------------------
; LLIST: not compilable, alert 'LLIST ???'.
;------------------------------------------------------------------------------
cmd_llist_unsupported:
	bsr.w	compile_error_continue
	dc.b	'LLIST ???',0

;------------------------------------------------------------------------------
; PSAVE: not compilable, alert 'PSAVE ???'.
;------------------------------------------------------------------------------
cmd_psave_unsupported:
	bsr.w	compile_error_continue
	dc.b	'PSAVE ???',0

;------------------------------------------------------------------------------
; LOAD: not compilable, alert 'LOAD ???'.
;------------------------------------------------------------------------------
cmd_load_unsupported:
	bsr.w	compile_error_continue
	dc.b	'LOAD ???',0
	dc.b	$00

;------------------------------------------------------------------------------
; SAVE: not compilable, alert 'SAVE ???'.
;------------------------------------------------------------------------------
cmd_save_unsupported:
	bsr.w	compile_error_continue
	dc.b	'SAVE ???',0
	dc.b	$00
	bsr.w	compile_error_continue          ; token $de at the start of a line: alert '?????'
	dc.b	'?????',0

;------------------------------------------------------------------------------
; STOP: not compilable, alert 'STOP ???'.
;------------------------------------------------------------------------------
cmd_stop_unsupported:
	bsr.w	compile_error_continue
	dc.b	'STOP ???',0
	dc.b	$00

;------------------------------------------------------------------------------
; TRON: not compilable, alert 'TRON ???'.
;------------------------------------------------------------------------------
cmd_tron_unsupported:
	bsr.w	compile_error_continue
	dc.b	'TRON ???',0
	dc.b	$00

;------------------------------------------------------------------------------
; TROFF: not compilable, alert 'TROFF ???'.
;------------------------------------------------------------------------------
cmd_troff_unsupported:
	bsr.w	compile_error_continue
	dc.b	'TROFF ???',0

;------------------------------------------------------------------------------
; CONT: not compilable, alert 'CONT ???'.
;------------------------------------------------------------------------------
cmd_cont_unsupported:
	bsr.w	compile_error_continue
	dc.b	'CONT ???',0
	dc.b	$00

;------------------------------------------------------------------------------
; DEFLIST: not compilable, alert 'DEFLIST ???'.
;------------------------------------------------------------------------------
cmd_deflist_unsupported:
	bsr.w	compile_error_continue
	dc.b	'DEFLIST ???',0

;------------------------------------------------------------------------------
; Steps a2 back over a tst.w d2 at the end of the code (loops while there are more).
;------------------------------------------------------------------------------
drop_trailing_tst_d2:
	subq.l	#2,a2

;------------------------------------------------------------------------------
; Ends a condition before a following jmp abs.l: drops trailing tst.w d2; if the condition ended
; Scc d2 / ext.w d2, both become Bcc.s *+8 with the same condition, else tst.w d2 / bne.s *+8
; is added. Either way a true condition skips the 6-byte jmp the caller emits next.
; a2 = code buffer.
;------------------------------------------------------------------------------
emit_skip_if_true:
	cmpi.w	#$4a42,-$2(a2)                  ; $4a42 = tst.w d2
	beq.s	drop_trailing_tst_d2
	cmpi.w	#$4882,-$2(a2)                  ; $4882 = ext.w d2
	bne.s	.add_test
	move.w	-$4(a2),d0                      ; the instruction before ext.w d2
	move.w	d0,d1                           ; d1 = copy of it
	andi.w	#$f0ff,d0                       ; keep everything but the condition field
	cmpi.w	#$50c2,d0                       ; $50c2 = Scc d2
	bne.s	.add_test                       ; not an Scc d2: add a test
	andi.w	#$f00,d1                        ; condition field ...
	ori.w	#$6006,d1                       ; ... into $601e = Bcc.s *+8
	subq.l	#4,a2                           ; step back over Scc d2 / ext.w d2
	move.w	d1,(a2)+                        ; Bcc.s *+8 replaces them
	rts
.add_test:
	move.w	#$4a42,(a2)+                    ; tst.w d2
	move.w	#$6606,(a2)+                    ; $6606 = bne.s *+8
	rts

; Word: 2 after a RETURN, shifted right each line.
after_return_count:
	dc.w	$0000                           ; 2 after RETURN, halved each line: a PROCEDURE right after needs no END

; Byte flag: the statement calls something with side effects, so optimise_ir must not merge terms.
expr_has_side_effects:
	dc.w	$0000                           ; set by functions with side effects: no merging of repeated terms

;------------------------------------------------------------------------------
; Compiles one statement: reads the next line into bss_end+$c04 (read_source_line, a5 = its
; command token), sets a0 = IR buffer bss_end+$b0, a2 = code buffer bss_end+$3d0, a3 = runtime-call
; list bss_end+$a10 (a1 = a0), and jumps to the handler of the command token.
; IR words: below $8000 runtime routine numbers (expression operators use their token numbers),
; $ff86-$ffff operations (pushes, pops, conversions, variable reads and stores, constants).
;------------------------------------------------------------------------------
compile_line:
	asr.w	after_return_count              ; count down the RETURN mark
	clr.b	expr_has_side_effects           ; no side effects seen yet
	bsr.w	read_source_line                ; fetch the next line (outside this range)
	lea	bss_end+$b0,a0
	movea.l	a0,a1
	lea	bss_end+$3d0,a2
	lea	bss_end+$a10,a3

;------------------------------------------------------------------------------
; Command dispatch: d7 = token at a5, jumps through command_dispatch_table; also LET (token $14).
;------------------------------------------------------------------------------
dispatch_command:
	moveq	#0,d7                           ; also LET: re-dispatches on the following token
	move.b	(a5)+,d7
	add.w	d7,d7                           ; word index into the table
	move.w	command_dispatch_table(pc,d7.w),d7
	jmp	command_dispatch_table(pc,d7.w) ; jump to the command's handler

; Handler offsets for the 256 tokens that can start a line: commands $00-$bf, then $cf-$ff
; (variables $e0-$ff give an assignment, $e8/$f8 a label). Slots $c0-$ce ($63c-$659) hold code,
; not offsets: they are not command tokens. The slots from $66a on are decoded as words and code.
command_dispatch_table:
	dc.w	cmd_no_code-command_dispatch_table
	dc.w	cmd_no_code-command_dispatch_table
	dc.w	push_control_address-command_dispatch_table
	dc.w	cmd_until-command_dispatch_table
	dc.w	cmd_while-command_dispatch_table
	dc.w	cmd_wend-command_dispatch_table
	dc.w	push_control_address-command_dispatch_table
	dc.w	cmd_loop-command_dispatch_table
	dc.w	cmd_for-command_dispatch_table
	dc.w	cmd_next-command_dispatch_table
	dc.w	cmd_exit_if-command_dispatch_table
	dc.w	cmd_if-command_dispatch_table
	dc.w	cmd_else-command_dispatch_table
	dc.w	cmd_endif-command_dispatch_table
	dc.w	cmd_print-command_dispatch_table
	dc.w	cmd_print-command_dispatch_table
	dc.w	cmd_no_code-command_dispatch_table
	dc.w	cmd_poke-command_dispatch_table
	dc.w	cmd_dpoke-command_dispatch_table
	dc.w	cmd_lpoke-command_dispatch_table
	dc.w	dispatch_command-command_dispatch_table
	dc.w	cmd_end-command_dispatch_table
	dc.w	cmd_circle-command_dispatch_table
	dc.w	cmd_pcircle-command_dispatch_table
	dc.w	cmd_ellipse-command_dispatch_table
	dc.w	cmd_pellipse-command_dispatch_table
	dc.w	cmd_box-command_dispatch_table
	dc.w	cmd_pbox-command_dispatch_table
	dc.w	cmd_rbox-command_dispatch_table
	dc.w	cmd_prbox-command_dispatch_table
	dc.w	cmd_plot-command_dispatch_table
	dc.w	cmd_line-command_dispatch_table
	dc.w	cmd_draw-command_dispatch_table
	dc.w	cmd_graphmode-command_dispatch_table
	dc.w	cmd_mouse-command_dispatch_table
	dc.w	cmd_color-command_dispatch_table
	dc.w	cmd_defline-command_dispatch_table
	dc.w	cmd_deffill-command_dispatch_table
	dc.w	cmd_fill-command_dispatch_table
