; ELLIPSE / PELLIPSE with angles: the bytes here decode as table words but are code:
; move.w #$23e,d0 (ELLIPSE) or move.w #$233,d0 (PELLIPSE) at $652, then $646: replace the last IR
; word (the plain ellipse routine) by d1 = $230 and parse the two angles for routine d0.
parse_ellipse_arc:
	dc.w	opt_swap_routine_pair+2-command_dispatch_table ; code, not offsets: move.w #$23e,d0 / bra.s $646
	dc.w	assign_int_store+2-command_dispatch_table
	dc.w	rt_float_exp_range_check-command_dispatch_table

; PELLIPSE with angles (code inside the dispatch table, see parse_ellipse_arc).
parse_pellipse_arc:
	dc.w	opt_swap_routine_pair+2-command_dispatch_table ; code: move.w #$233,d0
	dc.w	$0233
	move.w	d1,-$2(a0)                      ; radii routine becomes $230 (from d1)
	bra.w	two_int_args_statement          ; two angles, then routine d0

;------------------------------------------------------------------------------
; Line flush with a break test after it (Stop Ever): flush_line_code, emit_break_test, then the end check.
;------------------------------------------------------------------------------
flush_line_with_break_test:
	bsr.w	flush_line_code                 ; append the line's code
	bsr.w	emit_break_test
	bra.w	check_program_end
	dc.w	$0000,$027a,$027a,$027a,$027a,$027a,$027a,$027a ; token table $cf-$ff continues as words: $d0-$dd File
                                                ;   Error, $de '?????'
	dc.w	$027a,$027a,$027a,$027a,$027a,$027a,$027a,$ff3e
	dc.w	$028e,$0216                     ; $df END, $e0-$e3 variable assignments, $e4-$e7 array assignments
	andi.w	#$230,-(a4)                     ; table words $0264 ($e1 string) and $0230 ($e2 integer) as code
	dc.w	$024a                           ; $e3: boolean assignment
	bchg	d4,$96e(a2)                     ; table words $096a and $096e ($e4/$e5 array assignments) as code
	dc.w	$0972,$0976,$02b4,$027a,$027a,$027a,$027a,$027a ; $e8 label, $e9-$ef File Error
	dc.w	$027a,$027a,$0210               ; $e8 label, $e9-$ef File Error
	andi.w	#$22a,(a6)+                     ; table words $025e ($f1 string) and $022a ($f2 integer) as code
	andi.w	#$97a,d4                        ; table words $0244 ($f3 boolean) and $097a ($f4 array) as code
	dc.w	$097e                           ; $f5: array assignment
	bclr	d4,d2                           ; table word $0982 ($f6 array assignment) as code
	bclr	d4,d6                           ; table word $0986 ($f7 array assignment) as code
	dc.w	$02b4,$027a,$027a,$027a,$027a,$027a,$027a,$027a

;------------------------------------------------------------------------------
; VOID expr: the value is computed and discarded ($ffd2).
;------------------------------------------------------------------------------
cmd_void:
	bsr.w	parse_expression                ; expression
	move.w	#$ffd2,(a0)+                    ; IR $ffd2: discard the value

;------------------------------------------------------------------------------
; Ends a statement: optimises the IR (optimise_ir), then generates the 68000 code for it
; (generate_code, outside this range), which also resets a0/a2/a3 for the next IR.
;------------------------------------------------------------------------------
end_statement:
	bsr.w	optimise_ir                     ; optimise the IR
	bra.w	generate_code

;------------------------------------------------------------------------------
; Assignment to a variable (dispatched from the table, tokens $e0-$e3 and $f0-$f3): d0 = the
; variable index (one or two bytes), skip '=', parse the expression and store it:
; $6cc/$6d2 float ($ffd6), $6e6/$6ec integer ($ffd5), $700/$706 boolean ($ffd4),
; $71a/$720 string ($ffd3).
;------------------------------------------------------------------------------
	move.b	(a5)+,d0                        ; $f0: two-byte index
	asl.w	#8,d0                           ; high byte of the index
	bra.s	.float_index_low
	moveq	#0,d0                           ; $e0: one-byte index
.float_index_low:
	move.b	(a5)+,d0
	move.w	d0,-(sp)                        ; keep the variable index
	addq.l	#1,a5                           ; skip '='
	bsr.w	parse_expression                ; expression
	move.w	#$ffd6,(a0)+                    ; IR $ffd6: store float variable
	move.w	(sp)+,(a0)+                     ; the variable index
	bra.s	end_statement                   ; optimise and generate the code, then return
	move.b	(a5)+,d0                        ; $f2: two-byte index
	asl.w	#8,d0                           ; high byte of the index
	bra.s	.int_index_low                  ; join the low byte
	moveq	#0,d0                           ; $e2: one-byte index
.int_index_low:
	move.b	(a5)+,d0
	move.w	d0,-(sp)                        ; keep the variable index
	addq.l	#1,a5                           ; skip a token
	bsr.w	parse_int_expression            ; integer expression

;------------------------------------------------------------------------------
; Integer assignment tail: $ffd5 store of the variable index on the stack, then end_statement.
;------------------------------------------------------------------------------
assign_int_store:
	move.w	#$ffd5,(a0)+                    ; IR $ffd5: store integer variable
	move.w	(sp)+,(a0)+                     ; the variable index
	bra.s	end_statement                   ; optimise and generate the code, then return
	move.b	(a5)+,d0                        ; $f3: two-byte index
	asl.w	#8,d0                           ; high byte of the index
	bra.s	.bool_index_low                 ; join the low byte
	moveq	#0,d0                           ; $e3: one-byte index
.bool_index_low:
	move.b	(a5)+,d0
	move.w	d0,-(sp)                        ; keep the variable index
	addq.l	#1,a5                           ; skip a token
	bsr.w	parse_bool_expression           ; boolean expression
	move.w	#$ffd4,(a0)+                    ; IR $ffd4: store boolean variable
	move.w	(sp)+,(a0)+                     ; the variable index
	bra.s	end_statement                   ; optimise and generate the code, then return
	move.b	(a5)+,d0                        ; $f1: two-byte index
	asl.w	#8,d0                           ; high byte of the index
	bra.s	.string_index_low               ; join the low byte
	moveq	#0,d0                           ; $e1: one-byte index
.string_index_low:
	move.b	(a5)+,d0
	move.w	d0,-(sp)                        ; keep the variable index
	addq.l	#1,a5                           ; skip a token
	bsr.w	parse_expression                ; expression
	move.w	#$ffd3,(a0)+                    ; IR $ffd3: store string variable
	move.w	(sp)+,(a0)+                     ; the variable index
	bra.s	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; REM, DATA and ': nothing to compile.
;------------------------------------------------------------------------------
cmd_no_code:
	rts                                     ; REM, DATA and ': no code

;------------------------------------------------------------------------------
; Fatal alert '* File Error *' for a token that cannot start a line.
;------------------------------------------------------------------------------
error_bad_file_token:
	bsr.w	compile_error_fatal             ; fatal alert '* File Error *': token that cannot start a line
	dc.b	'* File Error *',0
	dc.b	$00

;------------------------------------------------------------------------------
; END, QUIT, SYSTEM, NEW, EDIT and the program's last line: jsr $201(a6).
;------------------------------------------------------------------------------
cmd_end:
	move.w	#$201,d0                        ; END, QUIT, SYSTEM, NEW, EDIT and the last line: routine $201

;------------------------------------------------------------------------------
; Emits jsr d0(a6) for the routine number d0 straight into the code (no IR).
;------------------------------------------------------------------------------
emit_command_call:
	bra.w	emit_call_routine               ; jsr d0(a6) straight into the code

;------------------------------------------------------------------------------
; VSYNC: jsr $202(a6).
;------------------------------------------------------------------------------
cmd_vsync:
	move.w	#$202,d0
	bra.s	emit_command_call

;------------------------------------------------------------------------------
; HARDCOPY: jsr $215(a6).
;------------------------------------------------------------------------------
cmd_hardcopy:
	move.w	#$215,d0
	bra.s	emit_command_call

;------------------------------------------------------------------------------
; Reads a variable reference from the tokens: d1 = its token ($e0-$ff, low nibble the type),
; d0 = its index (one byte, or two when token bit 4 is set). a5 advances past it.
;------------------------------------------------------------------------------
read_variable_token:
	move.b	(a5)+,d1
	moveq	#0,d0
	bclr	#$4,d1                          ; bit 4: two-byte index (and bit cleared in d1)
	beq.s	.index_low
	move.b	(a5)+,-(sp)                     ; high byte via the stack ...
	move.w	(sp)+,d0                        ; ... d0 = high byte << 8
.index_low:
	move.b	(a5)+,d0                        ; low byte
	rts

;------------------------------------------------------------------------------
; Label at the start of a line ($e8/$f8): stores the current code address in the label's table
; entry, keeping its flag byte.
;------------------------------------------------------------------------------
	subq.l	#1,a5                           ; back to the token
	bsr.s	read_variable_token             ; d1 = variable token, d0 = index
	asl.l	#4,d0                           ; 16-byte entries
	movea.l	bss_end+$5c,a0                  ; label table
	adda.l	d0,a0                           ; a0 = the label's entry
	move.b	(a0),d0                         ; keep the flag byte
	move.l	bss_end+$88,(a0)                ; code address of this line
	move.b	d0,(a0)                         ; restore the flag byte
	rts

;------------------------------------------------------------------------------
; LPRINT: output to the printer ($10a), then the PRINT items.
;------------------------------------------------------------------------------
cmd_lprint:
	move.w	#$10a,(a0)+                     ; routine $10a: output to the printer
	bra.s	print_next_item

;------------------------------------------------------------------------------
; PRINT without a channel: output to the screen ($10b).
;------------------------------------------------------------------------------
print_to_screen:
	move.w	#$10b,(a0)+                     ; routine $10b: output to the screen
	bra.s	print_next_item

;------------------------------------------------------------------------------
; PRINT / ? / LOCATE (command $0e): PRINT #n selects channel n ($126), otherwise the screen.
; Then the items: ';' nothing, ',' $124 (next zone), ' $122 (new line), TAB( $127, SPC( $128,
; AT( x,y $db, USING (cmd_print_using), expressions $120 (number) or $121 (string), each
; optimised at once. A new line ($125) unless the line ends with ';' or ','.
;------------------------------------------------------------------------------
cmd_print:
	cmpi.b	#$4d,(a5)                       ; '#': channel number
	bne.s	print_to_screen
	addq.l	#1,a5                           ; skip a token
	bsr.w	parse_int_expression            ; integer expression
	cmpi.b	#$46,-$1(a5)                    ; no more after the channel
	bne.s	.channel_selected
	subq.l	#1,a5                           ; step back so the terminator is read again
.channel_selected:
	move.w	#$126,(a0)+                     ; routine $126: select channel

;------------------------------------------------------------------------------
; Next PRINT item.
;------------------------------------------------------------------------------
print_next_item:
	move.b	(a5)+,d0                        ; d0 = next token
	cmpi.b	#$22,d0                         ; $22 = ';'
	beq.s	print_after_separator

;------------------------------------------------------------------------------
; PRINT separators ' and ','.
;------------------------------------------------------------------------------
print_separator:
	cmpi.b	#$57,d0                         ; $57 = ' (new line)
	beq.s	.new_line
	cmpi.b	#$21,d0                         ; $21 = ','
	bne.s	print_item
	move.w	#$124,(a0)+                     ; routine $124: next print zone
	bra.s	print_after_separator
.new_line:
	move.w	#$122,(a0)+                     ; routine $122: new line

;------------------------------------------------------------------------------
; After a separator: ends the statement without a new line when nothing follows.
;------------------------------------------------------------------------------
print_after_separator:
	cmpi.b	#$46,(a5)                       ; line ends after the separator: no new line
	bne.s	print_next_item
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; One PRINT item: end, TAB(, SPC(, USING, AT( or an expression.
;------------------------------------------------------------------------------
print_item:
	cmpi.b	#$46,d0                         ; end of the statement
	beq.s	print_new_line
	cmpi.b	#$a1,d0                         ; $a1 = TAB(
	beq.s	print_tab
	cmpi.b	#$a2,d0                         ; $a2 = SPC(
	beq.s	print_spc
	cmpi.b	#$a3,d0                         ; $a3 = USING
	beq.s	cmd_print_using
	cmpi.b	#$59,d0                         ; $59 = AT(
	beq.s	print_at
	subq.l	#1,a5                           ; back to the token: an expression
	bsr.w	parse_expression                ; expression
	tst.b	d6                              ; d6 negative = string
	bmi.s	print_string_item
	move.w	#$120,(a0)+                     ; routine $120: print a number
	bsr.w	optimise_ir                     ; optimise this item's IR now
	subq.l	#1,a5                           ; re-read the terminator

;------------------------------------------------------------------------------
; Back to the next PRINT item.
;------------------------------------------------------------------------------
print_loop:
	bra.s	print_next_item

;------------------------------------------------------------------------------
; PRINT a string ($121).
;------------------------------------------------------------------------------
print_string_item:
	move.w	#$121,(a0)+                     ; routine $121: print a string
	bsr.w	optimise_ir                     ; optimise the IR
	subq.l	#1,a5                           ; re-read the terminator
	bra.s	print_loop

;------------------------------------------------------------------------------
; PRINT ends with a new line ($125).
;------------------------------------------------------------------------------
print_new_line:
	move.w	#$125,(a0)+                     ; routine $125: new line
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; TAB(n) ($127).
;------------------------------------------------------------------------------
print_tab:
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$127,(a0)+                     ; routine $127: TAB
	bra.s	print_loop

;------------------------------------------------------------------------------
; SPC(n) ($128).
;------------------------------------------------------------------------------
print_spc:
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$128,(a0)+                     ; routine $128: SPC
	bra.s	print_loop

;------------------------------------------------------------------------------
; AT(x,y) ($db).
;------------------------------------------------------------------------------
print_at:
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	#$db,(a0)+                      ; routine $db: AT
	bra.s	print_loop

;------------------------------------------------------------------------------
; PRINT USING format$;items: $1ab, then $1ac/$1ad per item, $1ae or $1af at the end.
;------------------------------------------------------------------------------
cmd_print_using:
	bsr.w	parse_expression                ; format string
	move.w	#$1ab,(a0)+                     ; routine $1ab: set the USING format
.using_item:
	cmpi.b	#$46,-$1(a5)                    ; end of statement: new line
	beq.s	.using_new_line
	cmpi.b	#$22,-$1(a5)                    ; ';': no new line
	beq.s	.using_no_new_line
	bsr.w	parse_expression                ; expression
	tst.w	d6                              ; d6 negative: string
	bmi.s	.using_string
	move.w	#$1ac,(a0)+                     ; routine $1ac: number with USING
	bra.s	.using_item
.using_string:
	move.w	#$1ad,(a0)+                     ; routine $1ad: string with USING
	bra.s	.using_item
.using_no_new_line:
	move.w	#$1ae,(a0)+                     ; routine $1ae: end without new line
	bra.w	end_statement                   ; optimise and generate the code, then return
.using_new_line:
	move.w	#$1af,(a0)+                     ; routine $1af: end with new line
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; WRITE without a channel: screen ($10b).
;------------------------------------------------------------------------------
write_to_screen:
	move.w	#$10b,(a0)+                     ; routine $10b
	bra.s	write_items

;------------------------------------------------------------------------------
; WRITE [#n,] items: numbers $120, strings $dc (quoted), $dd between items, a new line ($125)
; unless the line ends with ';'.
;------------------------------------------------------------------------------
cmd_write:
	cmpi.b	#$4d,(a5)+                      ; '#': channel
	bne.s	write_to_screen
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$126,(a0)+                     ; routine $126

;------------------------------------------------------------------------------
; WRITE items.
;------------------------------------------------------------------------------
write_items:
	subq.l	#1,a5                           ; back to the token after the channel
	cmpi.b	#$46,(a5)+                      ; end of statement next?
	beq.w	print_new_line
.write_item:
	bsr.w	parse_expression                ; expression
	tst.w	d6                              ; d6 negative: string
	bmi.s	.write_string
	move.w	#$120,(a0)+                     ; routine $120: number
.write_separator:
	bsr.w	optimise_ir                     ; optimise the IR
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	beq.w	print_new_line
	cmpi.b	#$22,-$1(a5)                    ; ';': end without a new line
	beq.w	end_statement                   ; end the statement, no new line
	move.w	#$dd,(a0)+                      ; routine $dd: item separator
	bra.s	.write_item
.write_string:
	move.w	#$dc,(a0)+                      ; routine $dc: quoted string
	bra.s	.write_separator

;------------------------------------------------------------------------------
; Pushes the current code address (code region end + bytes in the line buffer) onto the control
; stack at bss_end+$9c (one long per entry; bit 31 set = a forward jmp to patch).
;------------------------------------------------------------------------------
push_control_address:
	movea.l	bss_end+$9c,a4
	move.l	bss_end+$88,d7                  ; code region end ...
	add.l	a2,d7                           ; ... + the line buffer position ...
	subi.l	#bss_end+$3d0,d7                ; ... - the buffer start: the current code address
	move.l	d7,(a4)+                        ; push it
	move.l	a4,bss_end+$9c                  ; new control stack top
	rts

;------------------------------------------------------------------------------
; UNTIL cond: break test (Stop loop), condition, then a branch back to the REPEAT taken while
; false: Scc d2/ext.w d2 turn into the inverted Bcc; moveq #0,d2 (always false) gives a plain
; branch, moveq #-1,d2 none. Short, word or (inverted Bcc.s over) jmp abs.l. Then patches the
; EXIT IFs of the loop.
;------------------------------------------------------------------------------
cmd_until:
	addq.l	#4,a5                           ; skip the 4-byte link
	bsr.w	loop_break_test                 ; break test if Stop is Loop
	bsr.w	parse_bool_expression           ; condition
	bsr.w	end_statement                   ; generate the condition's code
	bsr.w	find_loop_start                 ; d0 = REPEAT address
	moveq	#103,d7                         ; $67 = beq
	cmpi.w	#$4882,-$2(a2)                  ; ext.w d2?
	bne.s	.strip_test
	move.w	-$4(a2),d2                      ; the instruction before ext.w d2
	andi.w	#$f0ff,d2                       ; drop the condition field
	cmpi.w	#$50c2,d2                       ; Scc d2?
	bne.s	.strip_test
	move.b	-$4(a2),d7                      ; its condition ...
	addi.b	#$10,d7                         ; ... as Bcc ($5x -> $6x) ...
	bchg	#$0,d7                          ; ... inverted
	subq.l	#4,a2                           ; drop Scc d2 / ext.w d2
	bra.s	.branch_back
.strip_test:
	cmpi.w	#$4a42,-(a2)                    ; drop tst.w d2
	beq.s	.strip_test
	move.w	(a2),d2                         ; d2 = the last instruction left
	cmpi.w	#$7400,d2                       ; moveq #0,d2: never true
	beq.w	emit_branch_back
	cmpi.w	#$74ff,d2                       ; moveq #-1,d2: always true, no branch
	beq.s	close_control_entries
	addq.l	#2,a2                           ; keep it
	move.w	#$4a42,(a2)+                    ; tst.w d2
.branch_back:
	move.l	a2,d1                           ; d1 = this address
	subi.l	#bss_end+$3d0,d1                ; relative to the line buffer
	add.l	bss_end+$88,d1                  ; + code region end: absolute code address
	sub.l	d0,d1                           ; d1 = displacement back
	neg.l	d1
	subq.w	#2,d1                           ; less 2 for the PC offset of the branch
	cmpi.l	#$ffff8000,d1                   ; beyond a word displacement
	bcs.s	emit_branch_long_cc
	cmpi.w	#$ff80,d1                       ; beyond a byte displacement
	bcs.s	emit_branch_word_cc
	move.b	d7,(a2)+                        ; Bcc.s opcode byte

;------------------------------------------------------------------------------
; Emits the branch displacement byte d1 (opcode byte already written).
;------------------------------------------------------------------------------
emit_branch_byte:
	move.b	d1,(a2)+
	bra.s	close_control_entries           ; close EXIT IF entries, then return

;------------------------------------------------------------------------------
; Emits the opcode byte d7 with a zero byte: a word displacement follows.
;------------------------------------------------------------------------------
emit_branch_word_cc:
	move.b	d7,(a2)+
	clr.b	(a2)+                           ; displacement 0: word follows

;------------------------------------------------------------------------------
; Emits the word displacement d1.
;------------------------------------------------------------------------------
emit_branch_word:
	move.w	d1,(a2)+
	bra.s	close_control_entries           ; close EXIT IF entries, then return

;------------------------------------------------------------------------------
; Too far for a word: inverted Bcc.s over a jmp abs.l back.
;------------------------------------------------------------------------------
emit_branch_long_cc:
	bchg	#$0,d7                          ; invert the condition back ...
	move.b	d7,(a2)+
	move.b	#$6,(a2)+                       ; ... Bcc.s *+8 over the jmp
	bra.s	emit_jmp_back

;------------------------------------------------------------------------------
; Patches a forward jmp (control-stack entry d0) to the current code address.
;------------------------------------------------------------------------------
patch_forward_jump:
	move.l	a2,d1                           ; current code address
	subi.l	#bss_end+$3d0,d1                ; relative to the line buffer
	add.l	bss_end+$88,d1                  ; + code region end: absolute code address
	movea.l	d0,a0                           ; a0 = just past the jmp operand
	bset	#$1f,d1                         ; bit 31: an address to convert later
	move.l	d1,-(a0)                        ; into the jmp operand

;------------------------------------------------------------------------------
; Pops control-stack entries with bit 31 set (EXIT IF jumps) and patches them to the current
; address; stops at (and pops) the first plain entry, returned in d0.
;------------------------------------------------------------------------------
close_control_entries:
	movea.l	bss_end+$9c,a0
	move.l	-(a0),d0                        ; pop an entry
	move.l	a0,bss_end+$9c                  ; new control stack top
	tst.l	d0                              ; bit 31: a forward jump to patch
	bmi.s	patch_forward_jump
	rts

;------------------------------------------------------------------------------
; d0 = the innermost loop's start address on the control stack (skipping forward-jump entries);
; a0 = its slot.
;------------------------------------------------------------------------------
find_loop_start:
	movea.l	bss_end+$9c,a0
.skip_forward:
	move.l	-(a0),d0
	bmi.s	.skip_forward                   ; skip forward-jump entries
	rts

;------------------------------------------------------------------------------
; LOOP: break test (Stop Loop), then a branch back to the DO.
;------------------------------------------------------------------------------
cmd_loop:
	bsr.w	loop_break_test                 ; break test if Stop is Loop
	bsr.s	find_loop_start                 ; d0 = loop start

;------------------------------------------------------------------------------
; Branch back to address d0: bra.s, bra.w or jmp abs.l.
;------------------------------------------------------------------------------
emit_branch_back:
	move.l	d0,d1
	sub.l	bss_end+$88,d1                  ; relative to the code region end
	subq.l	#2,d1                           ; displacement
	cmpi.l	#$ffff8000,d1                   ; beyond a word displacement: jmp abs.l
	bcs.s	emit_jmp_back
	cmpi.w	#$ff80,d1                       ; beyond a byte displacement: bra.w
	bcs.s	.branch_word
	move.b	#$60,(a2)+                      ; bra.s
	bra.s	emit_branch_byte
.branch_word:
	move.w	#$6000,(a2)+                    ; bra.w
	bra.s	emit_branch_word

;------------------------------------------------------------------------------
; Emits a marked jmp abs.l, then closes the loop's EXIT IF entries.
;------------------------------------------------------------------------------
emit_jmp_back:
	bsr.s	emit_jmp_marked
	bra.s	close_control_entries           ; close EXIT IF entries, then return

;------------------------------------------------------------------------------
; jmp abs.l to address d0 with bit 31 set (an address to convert).
;------------------------------------------------------------------------------
emit_jmp_marked:
	bset	#$1f,d0                         ; bit 31: address to convert
	bra.s	emit_jmp_abs                    ; jmp abs.l d0, then return

;------------------------------------------------------------------------------
; GOTO label: break test (Stop Loop), jmp abs.l to the label; undefined label: runtime ERROR 20.
;------------------------------------------------------------------------------
cmd_goto:
	bsr.w	loop_break_test                 ; break test if Stop is Loop
	bsr.w	read_variable_token             ; d1 = variable token, d0 = index
	pea	(a0)                            ; keep a0
	move.l	d0,d2                           ; d2 = label index
	asl.l	#4,d2                           ; label table entry
	movea.l	bss_end+$5c,a0                  ; label table
	tst.l	0(a0,d2.l)                      ; label defined?
	movea.l	(sp)+,a0                        ; restore a0
	bne.s	emit_jmp_abs                    ; defined: jmp abs.l with the label index as operand, resolved later
	moveq	#20,d0                          ; no: runtime ERROR 20
	bra.w	emit_runtime_error

;------------------------------------------------------------------------------
; Emits jmp abs.l d0 (with its relocation entry).
;------------------------------------------------------------------------------
emit_jmp_abs:
	move.w	#$4ef9,(a2)+                    ; $4ef9 = jmp abs.l

;------------------------------------------------------------------------------
; Writes long d0 at a2 and adds its position to the relocation list (region bss_end+$98) as
; the distance from the previous one: a word, or a long with its top byte $ff.
;------------------------------------------------------------------------------
emit_reloc_long:
	move.l	a2,d1                           ; d1 = operand position in the line buffer
	move.l	d0,(a2)+                        ; write the long
	subi.l	#bss_end+$3d0,d1                ; relative to the buffer start
	add.l	bss_end+$88,d1                  ; + code region end: offset of the long in the code
	move.l	bss_end+$a4,d2                  ; previous relocated position
	move.l	d1,bss_end+$a4                  ; now the last relocated position
	sub.l	d2,d1                           ; d1 = distance from the previous one
	cmpi.l	#$7fff,d1                       ; distance fits a word?
	pea	(a0)                            ; keep a0 (flags unchanged)
	bcs.s	.short_distance
	moveq	#4,d0                           ; 4 bytes in the list
	bsr.s	add_reloc_entry
	move.l	d1,(a0)                         ; the long distance
	st	(a0)                            ; $ff top byte marks a long distance
	movea.l	(sp)+,a0                        ; restore a0
	rts
.short_distance:
	moveq	#2,d0                           ; 2 bytes in the list
	bsr.s	add_reloc_entry
	move.w	d1,(a0)                         ; the word distance
	movea.l	(sp)+,a0                        ; restore a0
	rts

;------------------------------------------------------------------------------
; Makes room for d0 bytes at the end of the relocation list region (a0 = where to write).
;------------------------------------------------------------------------------
add_reloc_entry:
	movem.l	d1/a1-a3,-(sp)
	lea	bss_end+$98,a0                  ; relocation list region
	bsr.w	open_memory_gap                 ; make room at the end of region a0
	movem.l	(sp)+,d1/a1-a3
	rts

;------------------------------------------------------------------------------
; EXIT IF cond: condition, then beq over a jmp out of the loop (FOR loops first call $1c1 to
; drop the FOR frame). The jmp is pushed on the control stack with bit 31 and the loop type, and
; patched at the loop end.
;------------------------------------------------------------------------------
cmd_exit_if:
	addq.l	#5,a5                           ; skip the link and the IF token
	bsr.w	parse_bool_expression           ; condition
	bsr.w	end_statement                   ; optimise and generate the code
	movea.l	bss_end+$9c,a0                  ; control stack top
	move.b	-$4(a0),d0                      ; loop type of the innermost entry
	andi.w	#$7f,d0
	beq.s	.plain_loop
	move.w	#$670a,(a2)+                    ; $670a = beq.s *+12 (over the call and the jmp)
	move.w	d0,-(sp)                        ; keep the loop type
	move.w	#$1c1,d0                        ; routine $1c1: drop the FOR frame
	bsr.w	emit_call_routine               ; jsr d0(a6) into the code
	move.w	(sp)+,d0                        ; restore it
	bra.s	.push_exit
.plain_loop:
	move.w	#$6706,(a2)+                    ; $6706 = beq.s *+8
.push_exit:
	movea.l	bss_end+$9c,a4                  ; control stack top
	move.l	bss_end+$88,d7                  ; code region end
	add.l	a2,d7                           ; address of the jmp operand + 4
	subi.l	#bss_end+$3ca,d7                ; - buffer start + 6: the address just after the jmp
	move.l	d7,(a4)+                        ; push it
	ori.b	#$80,d0                         ; forward-jump mark
	move.b	d0,-$4(a4)                      ; loop type and mark in the entry's top byte
	move.l	a4,bss_end+$9c                  ; new control stack top
	bra.w	emit_jmp_abs                    ; jmp abs.l d0, then return

;------------------------------------------------------------------------------
; WHILE cond: loop start pushed, then as IF: a jmp out patched at WEND.
;------------------------------------------------------------------------------
cmd_while:
	bsr.w	push_control_address            ; loop start for WEND

;------------------------------------------------------------------------------
; IF cond: condition, skip-if-true, then a jmp to ELSE/ENDIF pushed on the control stack.
;------------------------------------------------------------------------------
cmd_if:
	addq.l	#4,a5                           ; skip the link
	bsr.w	parse_bool_expression           ; condition
	bsr.w	end_statement                   ; optimise and generate the code
	bsr.w	emit_skip_if_true

;------------------------------------------------------------------------------
; Emits a jmp abs.l to be patched later and pushes its end address on the control stack.
;------------------------------------------------------------------------------
emit_jmp_pushed:
	bsr.w	emit_jmp_abs                    ; jmp abs.l to be patched ...
	bra.w	push_control_address            ; ... its address on the control stack

;------------------------------------------------------------------------------
; WEND: marks the WHILE's jmp for patching, then branches back like LOOP.
;------------------------------------------------------------------------------
cmd_wend:
	bsr.w	find_loop_start                 ; d0 = loop start
	st	(a0)                            ; mark the WHILE's jmp as to patch
	bra.w	cmd_loop

;------------------------------------------------------------------------------
; ENDIF: patches the IF's (or ELSE's) jmp to here.
;------------------------------------------------------------------------------
cmd_endif:
	movea.l	bss_end+$9c,a0
	movea.l	-(a0),a4                        ; a4 = the IF's entry
	move.l	a0,bss_end+$9c                  ; pop it
	bra.s	patch_jump_here

;------------------------------------------------------------------------------
; ELSE: a jmp to ENDIF, then the IF's jmp patched to here.
;------------------------------------------------------------------------------
cmd_else:
	movea.l	bss_end+$9c,a0
	move.l	-(a0),-(sp)                     ; IF's entry
	move.l	a0,bss_end+$9c                  ; pop it
	bsr.s	emit_jmp_pushed                 ; jmp to ENDIF
	movea.l	(sp)+,a4                        ; a4 = the IF's entry

;------------------------------------------------------------------------------
; Patches the jmp ending at entry a4 to the current code address (bit 31 set).
;------------------------------------------------------------------------------
patch_jump_here:
	move.l	bss_end+$88,d0
	add.l	a2,d0                           ; + line buffer position
	subi.l	#bss_end+$3d0,d0                ; - buffer start: the current code address
	bset	#$1f,d0                         ; bit 31: an address to convert
	move.l	d0,-(a4)                        ; into the jmp operand before the entry's address
	rts

;------------------------------------------------------------------------------
; RETURN: jmp $1fe(a6), and marks after_return_count.
;------------------------------------------------------------------------------
cmd_return:
	move.w	#$2,after_return_count          ; mark: a PROCEDURE may follow without END
	move.w	#$1fe,d0                        ; routine $1fe: RETURN

;------------------------------------------------------------------------------
; Emits jmp d0(a6) (opcode from jmp_a6_template) and records it in the runtime-call list.
;------------------------------------------------------------------------------
emit_runtime_jmp:
	move.w	jmp_a6_template,(a2)+           ; $4eee = jmp d16(a6)
	bra.w	emit_recorded_routine_word

;------------------------------------------------------------------------------
; Template instruction jmp 1(a6): its first word $4eee is copied.
;------------------------------------------------------------------------------
jmp_a6_template:
	jmp	1(a6)                           ; template: only its first word ($4eee) is used

;------------------------------------------------------------------------------
; SLPOKE addr,n: routine $13a.
;------------------------------------------------------------------------------
cmd_slpoke:
	move.w	#$13a,d0
	bra.s	two_int_args_statement

;------------------------------------------------------------------------------
; SDPOKE addr,n: routine $138.
;------------------------------------------------------------------------------
cmd_sdpoke:
	move.w	#$138,d0
	bra.s	two_int_args_statement

;------------------------------------------------------------------------------
; SPOKE addr,n: routine $136.
;------------------------------------------------------------------------------
cmd_spoke:
	move.w	#$136,d0
	bra.s	two_int_args_statement

;------------------------------------------------------------------------------
; LPOKE addr,n: routine $134.
;------------------------------------------------------------------------------
cmd_lpoke:
	move.w	#$134,d0
	bra.s	two_int_args_statement

;------------------------------------------------------------------------------
; DPOKE addr,n: routine $132.
;------------------------------------------------------------------------------
cmd_dpoke:
	move.w	#$132,d0
	bra.s	two_int_args_statement

;------------------------------------------------------------------------------
; POKE addr,n: routine $130.
;------------------------------------------------------------------------------
cmd_poke:
	move.w	#$130,d0

;------------------------------------------------------------------------------
; Two integer arguments and routine d0, then end_statement.
;------------------------------------------------------------------------------
two_int_args_statement:
	bsr.s	parse_two_int_args              ; two integers and routine d0
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; PLOT x,y: routine $224.
;------------------------------------------------------------------------------
cmd_plot:
	move.w	#$224,d0
	bra.s	two_int_args_statement

;------------------------------------------------------------------------------
; FILL x,y: routine $246.
;------------------------------------------------------------------------------
cmd_fill:
	move.w	#$246,d0
	bra.s	two_int_args_statement

;------------------------------------------------------------------------------
; Two integer arguments then routine d0: int expr, $fff8 push, int expr, $fff5 pop, d0.
;------------------------------------------------------------------------------
parse_two_int_args:
	move.w	d0,-(sp)                        ; keep the routine number
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	(sp)+,(a0)+                     ; routine d0 after the two arguments
	rts

;------------------------------------------------------------------------------
; LINE x1,y1,x2,y2: $226 then $228.
;------------------------------------------------------------------------------
cmd_line:
	move.w	#$228,d0

;------------------------------------------------------------------------------
; Two points: $226 for the first, routine d0 for the second.
;------------------------------------------------------------------------------
parse_two_points:
	move.w	d0,-(sp)                        ; keep the second point's routine
	move.w	#$226,d0                        ; routine $226: first point x,y
	bsr.s	parse_two_int_args              ; two integers and routine d0
	move.w	(sp)+,d0                        ; routine d0 for the second point
	bra.s	two_int_args_statement

;------------------------------------------------------------------------------
; BOX: $22a.
;------------------------------------------------------------------------------
cmd_box:
	move.w	#$22a,d0
	bra.s	parse_two_points

;------------------------------------------------------------------------------
; PBOX: $239.
;------------------------------------------------------------------------------
cmd_pbox:
	move.w	#$239,d0
	bra.s	parse_two_points

;------------------------------------------------------------------------------
; RBOX: $235.
;------------------------------------------------------------------------------
cmd_rbox:
	move.w	#$235,d0
	bra.s	parse_two_points

;------------------------------------------------------------------------------
; PRBOX: $237.
;------------------------------------------------------------------------------
cmd_prbox:
	move.w	#$237,d0
	bra.s	parse_two_points

;------------------------------------------------------------------------------
; CIRCLE x,y,r[,a1,a2]: $23b, or $22f and $1c6 for an arc.
;------------------------------------------------------------------------------
cmd_circle:
	move.w	#$226,d0                        ; routine $226: centre x,y
	bsr.s	parse_two_int_args              ; two integers and routine d0
	bsr.w	parse_int_expression            ; integer expression
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	bne.s	.circle_arc
	move.w	#$23b,(a0)+                     ; routine $23b: full circle
	bra.w	end_statement                   ; optimise and generate the code, then return
.circle_arc:
	move.w	#$22f,(a0)+                     ; routine $22f: radius, then the angles
	move.w	#$1c6,d0                        ; routine $1c6: arc
	bra.s	two_int_args_statement

;------------------------------------------------------------------------------
; ELLIPSE x,y,rx,ry[,a1,a2]: $23c, or via parse_ellipse_arc.
;------------------------------------------------------------------------------
cmd_ellipse:
	move.w	#$226,d0                        ; routine $226: centre x,y
	bsr.s	parse_two_int_args              ; two integers and routine d0
	move.w	#$23c,d0                        ; routine $23c: radii
	bsr.s	parse_two_int_args              ; two integers and routine d0
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	beq.w	end_statement
	move.w	#$230,d1                        ; $230: the radii routine of the arc form
	bra.w	parse_ellipse_arc

;------------------------------------------------------------------------------
; PCIRCLE x,y,r[,a1,a2]: $22c, or $22f and $1c4.
;------------------------------------------------------------------------------
cmd_pcircle:
	move.w	#$226,d0                        ; routine $226: centre x,y
	bsr.w	parse_two_int_args              ; two integers and routine d0
	bsr.w	parse_int_expression            ; integer expression
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	bne.s	.pcircle_pie
	move.w	#$22c,(a0)+                     ; routine $22c: full disc
	bra.w	end_statement                   ; optimise and generate the code, then return
.pcircle_pie:
	move.w	#$22f,(a0)+                     ; routine $22f
	move.w	#$1c4,d0                        ; routine $1c4: pie
	bra.w	two_int_args_statement

;------------------------------------------------------------------------------
; PELLIPSE x,y,rx,ry[,a1,a2]: $22e, or via parse_pellipse_arc.
;------------------------------------------------------------------------------
cmd_pellipse:
	move.w	#$226,d0                        ; routine $226: centre x,y
	bsr.w	parse_two_int_args              ; two integers and routine d0
	move.w	#$22e,d0                        ; routine $22e: radii
	bsr.w	parse_two_int_args              ; two integers and routine d0
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	beq.w	end_statement
	move.w	#$230,d1                        ; $230: the radii routine of the arc form
	bra.w	parse_pellipse_arc

;------------------------------------------------------------------------------
; FOR var=start TO|DOWNTO limit [STEP step]: stores the start value, emits the limit test
; routine ($13d / $152 integer, $142 / $153 float), pushes the loop start on the control stack
; with the loop type in its top byte (8 int, $c int with STEP, $e float, $18 float with STEP;
; bit 0 of the low byte = DOWNTO).
;------------------------------------------------------------------------------
cmd_for:
	addq.l	#4,a5                           ; skip the link
	bsr.w	read_variable_token             ; d1 = variable token, d0 = index
	move.w	d0,d7                           ; d7 = the variable index
	addq.l	#1,a5                           ; skip '='
	cmpi.b	#$e2,d1                         ; $e2 = integer variable
	bne.s	for_float
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$ffd5,(a0)+                    ; store integer
	move.w	d7,(a0)+                        ; the variable index
	cmpi.b	#$49,-$1(a5)                    ; $49 = DOWNTO
	beq.s	for_int_downto

;------------------------------------------------------------------------------
; Integer FOR limit (and STEP), then the loop entry.
;------------------------------------------------------------------------------
for_int_limit:
	bsr.w	parse_int_expression            ; integer expression
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	bne.s	for_int_step
	move.w	#$ffac,(a0)+                    ; IR $ffac: integer FOR variable
	move.w	d7,(a0)+                        ; the variable index
	move.w	#$13d,(a0)+                     ; routine $13d: integer limit, step 1

;------------------------------------------------------------------------------
; end_statement, then pushes the loop start; a4 = the entry, type byte set by the caller.
;------------------------------------------------------------------------------
for_push_loop:
	bsr.w	end_statement                   ; optimise and generate the code
	bsr.w	push_control_address            ; push the current address
	subq.l	#4,a4                           ; a4 = the new entry
	move.b	#$8,(a4)                        ; loop type 8: integer, step 1
	rts

;------------------------------------------------------------------------------
; Integer FOR with DOWNTO: bit 0 of the entry.
;------------------------------------------------------------------------------
for_int_downto:
	bsr.s	for_int_limit                   ; limit, then the loop entry
	bset	#$0,3(a4)                       ; DOWNTO
	rts

;------------------------------------------------------------------------------
; Integer FOR with STEP: $152, type $c.
;------------------------------------------------------------------------------
for_int_step:
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	#$ffac,(a0)+                    ; IR $ffac
	move.w	d7,(a0)+                        ; the variable index
	move.w	#$152,(a0)+                     ; routine $152: integer with STEP
	bsr.s	for_push_loop                   ; end the statement and push the loop
	move.b	#$c,(a4)                        ; loop type $c
	rts

;------------------------------------------------------------------------------
; Float FOR variable.
;------------------------------------------------------------------------------
for_float:
	bsr.w	parse_expression                ; expression
	move.w	#$ffd6,(a0)+                    ; store float
	move.w	d7,(a0)+                        ; the variable index
	cmpi.b	#$49,-$1(a5)                    ; $49 = DOWNTO
	beq.s	for_float_downto

;------------------------------------------------------------------------------
; Float FOR limit (and STEP).
;------------------------------------------------------------------------------
for_float_limit:
	bsr.w	parse_expression                ; expression
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	bne.s	for_float_step
	move.w	#$ffa8,(a0)+                    ; IR $ffa8: float FOR variable
	move.w	d7,(a0)+                        ; the variable index
	move.w	#$142,(a0)+                     ; routine $142: float limit, step 1
	bsr.s	for_push_loop
	move.b	#$e,(a4)                        ; loop type $e
	rts

;------------------------------------------------------------------------------
; Float FOR with DOWNTO.
;------------------------------------------------------------------------------
for_float_downto:
	bsr.s	for_float_limit                 ; limit, then the loop entry
	bset	#$0,3(a4)                       ; DOWNTO
	rts

;------------------------------------------------------------------------------
; Float FOR with STEP: $153, type $18.
;------------------------------------------------------------------------------
for_float_step:
	move.w	#$fff9,(a0)+                    ; IR $fff9: push float
	bsr.w	parse_expression                ; expression
	move.w	#$fff6,(a0)+                    ; IR $fff6: pop float
	move.w	#$ffa8,(a0)+                    ; IR $ffa8
	move.w	d7,(a0)+                        ; the variable index
	move.w	#$153,(a0)+                     ; routine $153: float with STEP
	bsr.w	for_push_loop
	move.b	#$18,(a4)                       ; loop type $18
	rts

;------------------------------------------------------------------------------
; NEXT: break test, patches the loop's EXIT IFs to just past the NEXT code (10 bytes on), emits
; the step routine for the loop type, then a 6-byte branch back to the FOR's test.
;------------------------------------------------------------------------------
cmd_next:
	bsr.w	loop_break_test                 ; break test if Stop is Loop
	adda.w	#$a,a2                          ; EXIT IFs go past the call and the branch
	bsr.w	close_control_entries           ; close EXIT IF entries
	suba.w	#$a,a2                          ; back to the real code position
	addq.l	#4,bss_end+$9c                  ; FOR entry back on the stack
	movea.l	bss_end+$9c,a0                  ; a0 = control stack top
	move.b	-$4(a0),d1                      ; d1 = loop type
	bclr	#$0,-(a0)                       ; DOWNTO bit
	bne.s	.count_down
	move.w	#$13f,d0                        ; $13f: integer up, step 1
	subq.b	#8,d1                           ; type 8: integer, step 1?
	beq.s	.emit_step
	move.w	#$141,d0                        ; $141: integer with STEP
	subq.b	#4,d1                           ; type $c: integer with STEP?
	beq.s	.emit_step
	move.w	#$144,d0                        ; $144: float up, step 1
	subq.b	#2,d1                           ; type $e: float, step 1?
	beq.s	.emit_step
	move.w	#$146,d0                        ; $146: float with STEP
	bra.s	.emit_step
.count_down:
	move.w	#$140,d0                        ; $140: integer down, step 1
	subq.b	#8,d1                           ; type 8: integer?
	beq.s	.emit_step
	move.w	#$145,d0                        ; $145: float down, step 1
.emit_step:
	bsr.w	emit_call_routine               ; jsr d0(a6) into the code
	movea.l	bss_end+$9c,a0                  ; control stack top
	move.l	-(a0),d0                        ; pop the FOR entry
	move.l	a0,bss_end+$9c                  ; new control stack top
	andi.l	#$ffffff,d0                     ; drop the type byte: the loop address
	move.l	d0,d1                           ; d1 = displacement ...
	sub.l	bss_end+$88,d1                  ; ... from the code region end
	subq.l	#6,d1                           ; back to the FOR's test
	cmpi.l	#$ffff8000,d1                   ; beyond a word displacement: jmp abs.l
	bcs.w	emit_jmp_marked
	cmpi.w	#$ff80,d1                       ; beyond a byte displacement: bra.w
	bcs.s	.branch_word
	move.b	#$60,(a2)+                      ; bra.s + 2 nops
	move.b	d1,(a2)+                        ; displacement byte
	move.l	#$4e714e71,(a2)+                ; two nops pad the branch to 6 bytes
	rts
.branch_word:
	move.w	#$6000,(a2)+                    ; bra.w + nop
	move.w	d1,(a2)+                        ; displacement word
	move.w	#$4e71,(a2)+                    ; nop pads the branch to 6 bytes
	rts

;------------------------------------------------------------------------------
; OUT dev,byte ($1c2) or OUT #n,byte ($126, $123).
;------------------------------------------------------------------------------
cmd_out:
	cmpi.b	#$4d,(a5)                       ; '#' (channel) follows?
	beq.s	.out_channel
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	#$1c2,(a0)+                     ; routine $1c2: OUT dev,byte
	bra.w	end_statement                   ; optimise and generate the code, then return
.out_channel:
	addq.l	#1,a5                           ; skip a token
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$126,(a0)+                     ; select channel
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$123,(a0)+                     ; routine $123: OUT #n,byte
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; SETCOLOR n,c or SETCOLOR n,r,g,b, compiled as XBIOS 7 (Setcolor): the colour word ($ffa7/
; $ffa6/$ffa5 combine r,g,b) is pushed before the register number, then $ffce 7, $ffd0 with 6
; bytes of arguments.
;------------------------------------------------------------------------------
cmd_setcolor:
	movea.l	sp,a3                           ; a3 = stack mark
	pea	(a0)                            ; keep the IR start
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$ffd8,(a0)+                    ; IR $ffd8: push integer as a word argument
	movea.l	(sp)+,a1                        ; a1 = start of the register number's IR
.hold_first:
	move.w	-(a0),-(sp)                     ; hold the register number's IR on the stack
	cmpa.l	a0,a1                           ; until all its IR words are held
	bne.s	.hold_first
	bsr.w	parse_int_expression            ; integer expression
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	beq.s	.one_colour                     ; one value after the register: the colour word
	move.w	#$ffa7,(a0)+                    ; IR $ffa7
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$ffa6,(a0)+                    ; IR $ffa6
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$ffa5,(a0)+                    ; IR $ffa5
	bra.s	.restore_first
.one_colour:
	move.w	#$ffd8,(a0)+                    ; IR $ffd8: push word argument
.restore_first:
	move.w	(sp)+,(a0)+                     ; the register number's IR after the colour
	cmpa.l	sp,a3                           ; until the stack mark
	bne.s	.restore_first
	move.w	#$ffce,(a0)+                    ; IR $ffce: integer constant 7 (Setcolor)
	move.l	#$7,(a0)+                       ; the constant 7
	move.w	#$ffd8,(a0)+                    ; IR $ffd8: push word argument
	move.w	#$ffd0,(a0)+                    ; IR $ffd0: XBIOS call
	move.w	#$6,(a0)+                       ; 6 bytes of arguments
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; Assignment to an array element (tokens $e4-$e7, $f4-$f7): d0 = store operation $ffa0 float,
; $ff9f string, $ff9e integer, $ff9d boolean; subscripts as integers, '=', expression.
;------------------------------------------------------------------------------
	moveq	#-96,d0                         ; $ffa0: store float array element ($e4)
	bra.s	.array_index_byte
	moveq	#-97,d0                         ; $ff9f: store string array element ($e5)
	bra.s	.array_index_byte
	moveq	#-98,d0                         ; $ff9e: store integer array element ($e6)
	bra.s	.array_index_byte
	moveq	#-99,d0                         ; $ff9d: store boolean array element ($e7)
	bra.s	.array_index_byte
	moveq	#-96,d0                         ; $ffa0: float array, two-byte index ($f4)
	bra.s	.array_index_high
	moveq	#-97,d0                         ; $ff9f: string array, two-byte index ($f5)
	bra.s	.array_index_high
	moveq	#-98,d0                         ; $ff9e: integer array, two-byte index ($f6)
	bra.s	.array_index_high
	moveq	#-99,d0                         ; $ff9d: boolean array, two-byte index ($f7)
.array_index_high:
	move.w	(a5)+,d1                        ; two-byte index
	asl.w	#8,d1                           ; the word's low byte becomes the high byte; why a word is read is
                                                ;   unclear
	bra.s	.array_index_low
.array_index_byte:
	moveq	#0,d1                           ; one-byte index: high byte 0
.array_index_low:
	move.b	(a5)+,d1                        ; low byte of the index
	bsr.w	parse_subscripts                ; subscripts, d7 = count
	addq.l	#1,a5                           ; skip '='
	movem.w	d0-d1,-(sp)                     ; keep the store operation and the index
	bsr.w	parse_expression                ; expression
	movem.w	(sp)+,d0-d1                     ; restore them
	bsr.w	emit_array_store
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; INPUT variables, one by one up to the end of the statement.
;------------------------------------------------------------------------------
parse_input_variables:
	bsr.s	parse_input_variable
	cmpi.b	#$46,(a5)+                      ; end of statement next?
	bne.s	parse_input_variables
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; INPUT into a float variable: $c7, store $ffd6.
;------------------------------------------------------------------------------
input_float_variable:
	move.w	#$c7,(a0)+                      ; routine $c7: input a number
	move.w	#$ffd6,(a0)+                    ; IR $ffd6: store float variable
	move.w	d1,(a0)+                        ; the variable index
	rts

;------------------------------------------------------------------------------
; INPUT into a string: $c5 (INPUT) or $c6 (LINE INPUT), store $ffd3.
;------------------------------------------------------------------------------
input_string_variable:
	cmpi.b	#$3a,bss_end+$c05               ; $3a = INPUT (not LINE INPUT)
	beq.s	.input_string
	move.w	#$c6,(a0)+                      ; routine $c6: LINE INPUT string
	bra.s	.input_string_store
.input_string:
	move.w	#$c5,(a0)+                      ; routine $c5: INPUT string
.input_string_store:
	move.w	#$ffd3,(a0)+                    ; IR $ffd3: store string variable
	move.w	d1,(a0)+                        ; the variable index
	rts

;------------------------------------------------------------------------------
; INPUT into an integer: $c8, store $ffd5.
;------------------------------------------------------------------------------
input_int_variable:
	move.w	#$c8,(a0)+                      ; routine $c8: input integer
	move.w	#$ffd5,(a0)+                    ; IR $ffd5: store integer variable
	move.w	d1,(a0)+                        ; the variable index
	rts

;------------------------------------------------------------------------------
; INPUT into a boolean: $c9, store $ffd4.
;------------------------------------------------------------------------------
input_bool_variable:
	move.w	#$c9,(a0)+                      ; routine $c9: input boolean
	move.w	#$ffd4,(a0)+                    ; IR $ffd4: store boolean variable
	move.w	d1,(a0)+                        ; the variable index
	rts

;------------------------------------------------------------------------------
; One INPUT variable: routine by type ($c7 float, $c5/$c6 string, $c8 integer, $c9 boolean) then
; the store, for arrays with the subscripts parsed first.
;------------------------------------------------------------------------------
parse_input_variable:
	move.b	(a5)+,d0                        ; d0 = variable token
	moveq	#0,d1
	move.b	(a5)+,d1                        ; d1 = index, low byte
	cmpi.b	#$f0,d0                         ; $f0-$ff: two-byte index
	bcs.s	.by_type
	asl.w	#8,d1                           ; high byte of the index
	move.b	(a5)+,d1                        ; low byte
.by_type:
	andi.w	#$7,d0                          ; type: 0 float 1 $ 2 % 3 ! 4-7 arrays
	beq.s	input_float_variable
	subq.w	#2,d0                           ; type 1 string, type 2 integer
	bmi.s	input_string_variable
	beq.s	input_int_variable
	subq.w	#2,d0                           ; type 3 boolean, type 4 float array
	bmi.s	input_bool_variable
	beq.s	.float_array
	subq.w	#2,d0                           ; type 5 string array, type 6 integer array
	bmi.s	.string_array
	beq.s	.int_array
	move.w	#$c9,-(sp)                      ; type 7 boolean array: $c9 input boolean
	moveq	#-99,d0                         ; $ff9d: store boolean element
	bra.s	array_store_after_routine
.int_array:
	move.w	#$c8,-(sp)                      ; $c8: input integer
	moveq	#-98,d0                         ; $ff9e: store integer element
	bra.s	array_store_after_routine
.float_array:
	move.w	#$c7,-(sp)                      ; $c7: input a number
	moveq	#-96,d0                         ; $ffa0: store float element
	bra.s	array_store_after_routine
.string_array:
	move.w	#$c5,-(sp)                      ; $c5: INPUT string
	cmpi.b	#$3a,bss_end+$c05               ; INPUT, not LINE INPUT?
	beq.s	.line_input_array
	move.w	#$c6,(sp)                       ; $c6: LINE INPUT string
.line_input_array:
	moveq	#-97,d0                         ; $ff9f: store string element

;------------------------------------------------------------------------------
; Array target: subscripts first, then the routine (on the stack) and the store.
;------------------------------------------------------------------------------
array_store_after_routine:
	bsr.s	parse_subscripts                ; subscripts, d7 = count
	move.w	(sp)+,(a0)+                     ; the input routine after the subscripts
	bra.s	emit_store_index_count

;------------------------------------------------------------------------------
; Emits the array store d0 (index d1, d7 subscripts) with the conversion its type needs: $ffff
; for integer, $fffd for boolean.
;------------------------------------------------------------------------------
emit_array_store:
	cmpi.w	#$ffa0,d0                       ; float element: no conversion
	beq.s	emit_store_index_count
	cmpi.w	#$ff9f,d0                       ; string element: no conversion
	beq.s	emit_store_index_count
	move.w	#$ffff,(a0)+                    ; IR $ffff: float to integer
	cmpi.w	#$ff9e,d0                       ; integer element: just the integer conversion
	beq.s	emit_store_index_count
	move.w	#$fffd,-$2(a0)                  ; IR $fffd: float to boolean

;------------------------------------------------------------------------------
; Writes the store operation d0, index d1 and subscript count d7.
;------------------------------------------------------------------------------
emit_store_index_count:
	move.w	d0,(a0)+                        ; store operation
	move.w	d1,(a0)+                        ; array index
	move.w	d7,(a0)+                        ; subscript count
	rts

;------------------------------------------------------------------------------
; Parses array subscripts up to ')' ($20), each an integer pushed with $fff8; d7 = their count.
; Keeps d0/d1.
;------------------------------------------------------------------------------
parse_subscripts:
	move.w	d1,-(sp)                        ; keep d1
	move.w	d0,-(sp)                        ; keep d0
	moveq	#0,d7                           ; no subscripts yet
.next_subscript:
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	addq.w	#1,d7                           ; count it
	cmpi.b	#$20,-$1(a5)                    ; ')' reached?
	bne.s	.next_subscript
	move.w	(sp)+,d0                        ; restore d0
	move.w	(sp)+,d1                        ; restore d1
	rts

;------------------------------------------------------------------------------
; DIM of a float array ($ffa4).
;------------------------------------------------------------------------------
dim_float_array:
	move.w	#$ffa4,d1                       ; IR $ffa4: DIM float array

;------------------------------------------------------------------------------
; One DIM array: dimensions, IR d1; loops over ','.
;------------------------------------------------------------------------------
dim_array:
	bsr.w	parse_array_element             ; array, dimensions and DIM IR d1
	cmpi.b	#$46,(a5)+                      ; end of statement next?
	beq.w	end_statement

;------------------------------------------------------------------------------
; DIM arrays: per array its type selects $ffa4 float, $ffa3 string, $ffa2 integer, $ffa1 boolean.
;------------------------------------------------------------------------------
cmd_dim:
	move.b	(a5)+,d7                        ; d7 = array token
	move.w	d7,d6                           ; d6 = copy for the type
	add.w	d7,d7                           ; doubled (not used further here)
	andi.w	#$3,d6                          ; array type: 4 float 5 $ 6 % 7 !
	beq.s	dim_float_array
	subq.w	#2,d6
	bmi.s	.dim_string
	beq.s	.dim_int
	move.w	#$ffa1,d1                       ; IR $ffa1: DIM boolean array
	bra.s	dim_array
.dim_string:
	move.w	#$ffa3,d1                       ; IR $ffa3: DIM string array
	bra.s	dim_array
.dim_int:
	move.w	#$ffa2,d1                       ; IR $ffa2: DIM integer array
	bra.s	dim_array

;------------------------------------------------------------------------------
; SETTIME time$,date$: routine $16a.
;------------------------------------------------------------------------------
cmd_settime:
	bsr.w	parse_expression                ; expression
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	bsr.w	parse_expression                ; expression
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
	move.w	#$16a,(a0)+                     ; routine $16a
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; CHDIR path$: routine $16c.
;------------------------------------------------------------------------------
cmd_chdir:
	move.w	#$16c,d0
	bra.s	string_arg_statement

;------------------------------------------------------------------------------
; MKDIR path$: routine $16d.
;------------------------------------------------------------------------------
cmd_mkdir:
	move.w	#$16d,d0
	bra.s	string_arg_statement

;------------------------------------------------------------------------------
; RMDIR path$: routine $16e.
;------------------------------------------------------------------------------
cmd_rmdir:
	move.w	#$16e,d0
	bra.s	string_arg_statement

;------------------------------------------------------------------------------
; KILL file$: routine $16f.
;------------------------------------------------------------------------------
cmd_kill:
	move.w	#$16f,d0
	bra.s	string_arg_statement

;------------------------------------------------------------------------------
; CHAIN file$: routine $95.
;------------------------------------------------------------------------------
cmd_chain:
	move.w	#$95,d0

;------------------------------------------------------------------------------
; One expression and routine d0, then end_statement.
;------------------------------------------------------------------------------
string_arg_statement:
	move.w	d0,-(sp)                        ; keep the routine number
	bsr.w	parse_expression                ; expression
	move.w	(sp)+,(a0)+                     ; the routine after the argument
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; RUN: jsr $12f(a6).
;------------------------------------------------------------------------------
cmd_run:
	move.w	#$12f,d0
	bra.w	emit_call_routine               ; jsr d0(a6) into the code, then return

;------------------------------------------------------------------------------
; Integer expression then end_statement (MONITOR and ERROR arguments).
;------------------------------------------------------------------------------
int_arg_end_statement:
	bsr.w	parse_int_expression            ; integer expression
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; MONITOR [n]: lea $70(a4),a0 and an illegal instruction.
;------------------------------------------------------------------------------
cmd_monitor:
	cmpi.b	#$46,(a5)                       ; end of statement next?
	beq.s	.emit_trap
	bsr.s	int_arg_end_statement           ; the argument's code first
.emit_trap:
	move.l	monitor_code_template,(a2)+     ; lea $70(a4),a0 from the template ...
	move.w	#$4afc,(a2)+                    ; ... and illegal: the debugger's trap
	rts

;------------------------------------------------------------------------------
; Template instruction lea $70(a4),a0, copied by cmd_monitor.
;------------------------------------------------------------------------------
monitor_code_template:
	lea	$70(a4),a0                      ; template only: lea $70(a4),a0

;------------------------------------------------------------------------------
; Compile-time errors become run-time ones: emits moveq #d0,d0 and a call of the ERROR routine
; $10f.
;------------------------------------------------------------------------------
emit_runtime_error:
	move.b	#$70,(a2)+                      ; $70xx = moveq #d0,d0
	move.b	d0,(a2)+
	bra.s	emit_error_call

;------------------------------------------------------------------------------
; ERROR n: routine $10f.
;------------------------------------------------------------------------------
cmd_error:
	bsr.s	int_arg_end_statement

;------------------------------------------------------------------------------
; Call of the ERROR routine $10f.
;------------------------------------------------------------------------------
emit_error_call:
	move.w	#$10f,d0                        ; routine $10f: ERROR
	bra.w	emit_call_routine               ; jsr d0(a6) into the code, then return

;------------------------------------------------------------------------------
; PUT x,y,a$[,mode] (command $84): $170 or $171.
;------------------------------------------------------------------------------
cmd_put_block:
	bsr.s	parse_two_word_args             ; PUT x,y,a$[,mode]
	bsr.w	parse_expression                ; expression
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	beq.s	.put_no_mode
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$ffd9,(a0)+                    ; IR $ffd9: pop address
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	#$170,(a0)+                     ; routine $170: with mode
	bra.w	end_statement                   ; optimise and generate the code, then return
.put_no_mode:
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	#$171,(a0)+                     ; routine $171
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; Three integer word arguments ($ffd8 each).
;------------------------------------------------------------------------------
parse_three_word_args:
	bsr.w	parse_two_word_args

;------------------------------------------------------------------------------
; Two integer word arguments.
;------------------------------------------------------------------------------
parse_two_word_args:
	bsr.w	parse_word_arg

;------------------------------------------------------------------------------
; One integer word argument: int expression, $ffd8.
;------------------------------------------------------------------------------
parse_word_arg:
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$ffd8,(a0)+                    ; IR $ffd8: push as a word argument
	rts

;------------------------------------------------------------------------------
; GET x1,y1,x2,y2,a$ (command $82): $172.
;------------------------------------------------------------------------------
cmd_get_block:
	bsr.s	parse_three_word_args           ; GET x1,y1,x2,y2,a$
	bsr.w	parse_expression                ; expression
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	#$ff9c,(a0)+                    ; IR $ff9c: result variable follows
	move.w	#$172,(a0)+                     ; routine $172
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; PAUSE n: routine $176.
;------------------------------------------------------------------------------
cmd_pause:
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$176,(a0)+                     ; routine $176
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; NAME old$ AS new$: routine $175.
;------------------------------------------------------------------------------
cmd_name:
	bsr.w	parse_expression                ; expression
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	bsr.w	parse_expression                ; expression
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
	move.w	#$175,(a0)+                     ; routine $175
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; SPRITE a$[,x,y]: $173, or $174 to remove it.
;------------------------------------------------------------------------------
cmd_sprite:
	bsr.w	parse_expression                ; expression
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	beq.s	.sprite_off
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	#$ffd9,(a0)+                    ; IR $ffd9: pop address
	move.w	#$173,(a0)+                     ; routine $173: SPRITE a$,x,y
	bra.w	end_statement                   ; optimise and generate the code, then return
.sprite_off:
	move.w	#$174,(a0)+                     ; routine $174: SPRITE a$
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; SGET a$: routine $15d.
;------------------------------------------------------------------------------
cmd_sget:
	bsr.w	parse_expression                ; expression
	move.w	#$15d,(a0)+                     ; routine $15d
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; SPUT a$: routine $15e.
;------------------------------------------------------------------------------
cmd_sput:
	bsr.w	parse_expression                ; expression
	move.w	#$15e,(a0)+                     ; routine $15e
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; LINE INPUT: skips the INPUT token, then as INPUT.
;------------------------------------------------------------------------------
cmd_line_input:
	addq.l	#1,a5                           ; skip INPUT

;------------------------------------------------------------------------------
; INPUT / LINE INPUT [#n,] ["prompt" ,|;] variables: channel or screen, the prompt printed
; ($121, then $c4 after ',' to drop the '?'), then each variable via parse_input_variable.
;------------------------------------------------------------------------------
cmd_input:
	cmpi.b	#$4d,(a5)                       ; '#' (channel) follows?
	bne.s	.to_screen
	addq.l	#1,a5                           ; skip a token
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$126,(a0)+                     ; routine $126
	bra.s	.variables
.to_screen:
	move.w	#$10b,(a0)+                     ; routine $10b
	cmpi.b	#$e0,(a5)                       ; a variable comes first: no prompt
	bcc.s	.variables
	bsr.w	parse_expression                ; expression
	move.w	#$121,(a0)+                     ; routine $121
	cmpi.b	#$21,-$1(a5)                    ; ',' follows?
	bne.s	.variables
	move.w	#$c4,(a0)+                      ; routine $c4: no '?' after the prompt
.variables:
	bra.w	parse_input_variables

;------------------------------------------------------------------------------
; FILESELECT path$,name$,result$: routine $cb.
;------------------------------------------------------------------------------
cmd_fileselect:
	bsr.w	parse_expression                ; expression
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	bsr.w	parse_expression                ; expression
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	bsr.w	parse_expression                ; expression
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
	move.w	#$cb,(a0)+                      ; routine $cb: FILESELECT
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; ALERT type,text$,default,buttons$,var: routine $ca, then the button number stored in var
; (converted for its type; array elements get their subscripts parsed after the call's IR).
;------------------------------------------------------------------------------
cmd_alert:
	movea.l	sp,a3                           ; a3 = stack mark
	pea	(a0)                            ; keep the IR start
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_expression                ; expression
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_expression                ; expression
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
	move.w	#$ff9c,(a0)+                    ; IR $ff9c: result variable follows
	move.w	#$ca,(a0)+                      ; routine $ca
	movea.l	(sp)+,a1                        ; a1 = IR start
	bsr.w	read_variable_token             ; d1 = variable token, d0 = index
	btst	#$2,d1                          ; array element?
	bne.s	.hold_call
	andi.b	#$3,d1                          ; type bits
	beq.s	.store_float                    ; type 0: float
	subq.b	#2,d1                           ; type 2: integer
	beq.s	.store_int
	move.w	#$fffb,(a0)+                    ; IR $fffb: integer to boolean
	moveq	#-44,d1                         ; $ffd4: store boolean
.emit_store:
	move.w	d1,(a0)+                        ; store operation
	move.w	d0,(a0)+                        ; variable index
	bra.w	end_statement                   ; optimise and generate the code, then return
.store_int:
	moveq	#-43,d1                         ; $ffd5: store integer
	bra.s	.emit_store
.store_float:
	move.w	#$fffe,(a0)+                    ; IR $fffe: integer to float
	moveq	#-42,d1                         ; $ffd6: store float
	bra.s	.emit_store
.hold_call:
	move.w	-(a0),-(sp)                     ; hold the call's IR on the stack
	cmpa.l	a0,a1                           ; until all the call's IR is held
	bne.s	.hold_call
	bsr.w	parse_subscripts                ; subscripts, d7 = count
.restore_call:
	move.w	(sp)+,(a0)+
	cmpa.l	sp,a3                           ; until the stack mark
	bne.s	.restore_call
	andi.b	#$3,d1                          ; type bits
	beq.s	.element_float                  ; float element
	subq.b	#2,d1                           ; type 2: integer element
	beq.s	.element_int
	move.w	#$fffb,(a0)+                    ; IR $fffb: integer to boolean
	moveq	#-99,d1                         ; $ff9d: store boolean element
.emit_element_store:
	move.w	d1,(a0)+                        ; store operation
	move.w	d0,(a0)+                        ; array index
	move.w	d7,(a0)+                        ; subscript count
	bra.w	end_statement                   ; optimise and generate the code, then return
.element_float:
	move.w	#$fffe,(a0)+                    ; IR $fffe: integer to float
	moveq	#-96,d1                         ; $ffa0: store float element
	bra.s	.emit_element_store
.element_int:
	moveq	#-98,d1                         ; $ff9e: store integer element
	bra.s	.emit_element_store

;------------------------------------------------------------------------------
; DEFMOUSE n ($277) or DEFMOUSE a$ ($278).
;------------------------------------------------------------------------------
cmd_defmouse:
	bsr.w	parse_expression                ; expression
	tst.w	d6                              ; d6 negative: string
	bmi.s	.mouse_string
	move.w	#$ffff,(a0)+                    ; IR $ffff: float to integer
	move.w	#$277,(a0)+                     ; routine $277: DEFMOUSE n
	bra.w	end_statement                   ; optimise and generate the code, then return
.mouse_string:
	move.w	#$278,(a0)+                     ; routine $278: DEFMOUSE a$
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; DEFNUM n: routine $200.
;------------------------------------------------------------------------------
cmd_defnum:
	move.w	#$200,d0
	bra.s	int_arg_statement

;------------------------------------------------------------------------------
; GRAPHMODE n: routine $276.
;------------------------------------------------------------------------------
cmd_graphmode:
	move.w	#$276,d0
	bra.s	int_arg_statement

;------------------------------------------------------------------------------
; COLOR n: routine $13c.
;------------------------------------------------------------------------------
cmd_color:
	move.w	#$13c,d0

;------------------------------------------------------------------------------
; Integer expression and routine d0, then end_statement.
;------------------------------------------------------------------------------
int_arg_statement:
	move.w	d0,-(sp)                        ; keep the routine number
	bsr.w	parse_int_expression            ; integer expression
	move.w	(sp)+,(a0)+                     ; the routine after the argument
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; GEMSYS [n]: $217 alone, $216 with n.
;------------------------------------------------------------------------------
cmd_gemsys:
	move.w	#$217,d0
	cmpi.b	#$46,(a5)                       ; no argument: routine $217
	beq.s	emit_routine_end_statement
	move.w	#$216,d0                        ; routine $216: GEMSYS n
	bra.s	int_arg_statement

;------------------------------------------------------------------------------
; VDISYS [n]: $219 alone, $218 with n.
;------------------------------------------------------------------------------
cmd_vdisys:
	move.w	#$219,d0
	cmpi.b	#$46,(a5)                       ; end of statement next?
	beq.s	emit_routine_end_statement
	move.w	#$218,d0                        ; routine $218: VDISYS n
	bra.s	int_arg_statement

;------------------------------------------------------------------------------
; DEFLINE style,width,begin,end: $220, $221, then both ends with $222.
;------------------------------------------------------------------------------
cmd_defline:
	move.w	#$220,d0
	bsr.s	parse_optional_int_arg          ; optional integer argument
	move.w	#$221,d0
	bsr.s	parse_optional_int_arg          ; optional integer argument
	pea	(a0)                            ; keep the IR position
	moveq	#-8,d0                          ; begin and end styles go as a pair
	bsr.s	parse_optional_int_arg          ; optional integer argument
	cmpa.l	(sp),a0                         ; nothing parsed: no end styles
	beq.s	defline_no_ends
	pea	(a0)                            ; keep the IR position
	moveq	#-11,d0                         ; $fff5: pop integer for the end style
	bsr.s	parse_optional_int_arg          ; optional integer argument
	cmpa.l	(sp)+,a0                        ; nothing parsed: no end styles
	beq.s	defline_no_ends
	addq.l	#4,sp                           ; drop the saved position
	move.w	#$222,d0                        ; routine $222: line ends

;------------------------------------------------------------------------------
; Routine d0 then end_statement.
;------------------------------------------------------------------------------
emit_routine_end_statement:
	move.w	d0,(a0)+
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; DEFLINE without both end styles: their IR is dropped.
;------------------------------------------------------------------------------
defline_no_ends:
	movea.l	(sp)+,a0                        ; drop the end styles' IR
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; DEFFILL colour,style,pattern: $273, $274, $275.
;------------------------------------------------------------------------------
cmd_deffill:
	move.w	#$273,d0
	bsr.s	parse_optional_int_arg          ; optional integer argument
	move.w	#$274,d0
	bsr.s	parse_optional_int_arg          ; optional integer argument
	move.w	#$275,d0
	bsr.s	parse_optional_int_arg          ; optional integer argument
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; DEFMARK colour,type,size: $26a, $26b, $223.
;------------------------------------------------------------------------------
cmd_defmark:
	move.w	#$26a,d0
	bsr.s	parse_optional_int_arg          ; optional integer argument
	move.w	#$26b,d0
	bsr.s	parse_optional_int_arg          ; optional integer argument
	move.w	#$223,d0
	bsr.s	parse_optional_int_arg          ; optional integer argument
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; One optional argument: nothing when the statement ends or the next token is ','; else an
; integer expression ($ffff) and routine d0, or routine $279 for a string.
;------------------------------------------------------------------------------
parse_optional_int_arg:
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	beq.s	.no_argument
	cmpi.b	#$46,(a5)                       ; end of statement next?
	beq.s	.no_argument
	cmpi.b	#$21,(a5)                       ; ',' follows?
	beq.s	.skip_comma
	move.w	d0,-(sp)                        ; keep the routine number
	bsr.w	parse_expression                ; expression
	tst.w	d6                              ; d6 negative: string
	bmi.s	.string_argument
	move.w	#$ffff,(a0)+                    ; IR $ffff: float to integer
	move.w	(sp)+,(a0)+                     ; the routine after the argument
	rts
.skip_comma:
	addq.l	#1,a5                           ; skip a token
.no_argument:
	rts
.string_argument:
	addq.l	#2,sp                           ; drop the routine number
	move.w	#$279,(a0)+                     ; routine $279: string pattern
	rts

;------------------------------------------------------------------------------
; DEFTEXT colour,attr,angle,height,font: $26c, $26d, $26e, $248, $26f.
;------------------------------------------------------------------------------
cmd_deftext:
	move.w	#$26c,d0
	bsr.s	parse_optional_int_arg          ; optional integer argument
	move.w	#$26d,d0
	bsr.s	parse_optional_int_arg          ; optional integer argument
	move.w	#$26e,d0
	bsr.s	parse_optional_int_arg          ; optional integer argument
	move.w	#$248,d0
	bsr.s	parse_optional_int_arg          ; optional integer argument
	move.w	#$26f,d0
	bsr.s	parse_optional_int_arg          ; optional integer argument
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; ERASE a(): routine $90.
;------------------------------------------------------------------------------
cmd_erase:
	bsr.w	parse_array_name                ; array name
	move.w	#$90,(a0)+                      ; routine $90: ERASE
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; ARRAYFILL a(),x: $91 float, $92 integer, $93 boolean.
;------------------------------------------------------------------------------
cmd_arrayfill:
	bsr.w	read_variable_token             ; d1 = variable token, d0 = index
	move.w	d0,-(sp)                        ; keep the array index
	addq.l	#2,a5                           ; skip ')' and ','
	andi.b	#$3,d1                          ; array type
	beq.s	.fill_float
	subq.b	#2,d1                           ; type 2: integer
	beq.s	.fill_int
	bsr.w	parse_bool_expression           ; condition
	move.w	#$93,d0                         ; routine $93: boolean array
	move.w	#$ff98,(a0)+                    ; IR $ff98: boolean array
.emit_fill:
	move.w	(sp)+,(a0)+                     ; array index
	move.w	d0,(a0)+                        ; fill routine
	bra.w	end_statement                   ; optimise and generate the code, then return
.fill_int:
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$ff99,(a0)+                    ; IR $ff99: integer array
	move.w	#$92,d0                         ; routine $92: integer array
	bra.s	.emit_fill
.fill_float:
	bsr.w	parse_expression                ; expression
	move.w	#$ff9b,(a0)+                    ; IR $ff9b: float array
	move.w	#$91,d0                         ; routine $91: float array
	bra.s	.emit_fill

;------------------------------------------------------------------------------
; LSET a$=b$: routine $8c.
;------------------------------------------------------------------------------
cmd_lset:
	move.w	#$8c,d0
	bra.s	two_string_args_statement

;------------------------------------------------------------------------------
; RSET a$=b$: routine $8d.
;------------------------------------------------------------------------------
cmd_rset:
	move.w	#$8d,d0

;------------------------------------------------------------------------------
; Two string arguments and routine d0.
;------------------------------------------------------------------------------
two_string_args_statement:
	move.w	d0,-(sp)                        ; keep the routine number
	bsr.w	parse_expression                ; expression
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	bsr.w	parse_expression                ; expression
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
	move.w	(sp)+,(a0)+                     ; the routine after both arguments
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; MID$(a$,n[,m])=b$ as a command: $8f or $8e.
;------------------------------------------------------------------------------
cmd_mid:
	bsr.w	parse_expression                ; MID$(a$,n[,m])=b$
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	cmpi.b	#$45,(a5)                       ; $45 = '=' (no length)
	beq.s	.no_length
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	addq.l	#1,a5                           ; skip '='
	bsr.w	parse_expression                ; expression
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	#$ff9c,(a0)+                    ; IR $ff9c: result variable follows
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
	move.w	#$8f,(a0)+                      ; routine $8f: with length
	bra.w	end_statement                   ; optimise and generate the code, then return
.no_length:
	addq.l	#1,a5                           ; skip '='
	bsr.w	parse_expression                ; expression
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
	move.w	#$8e,(a0)+                      ; routine $8e: without length
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; CLOSE [#n]: $99 or $9a (all).
;------------------------------------------------------------------------------
cmd_close:
	cmpi.b	#$46,(a5)+                      ; end of statement next?
	beq.s	.close_all
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$99,(a0)+                      ; routine $99: CLOSE #n
	bra.w	end_statement                   ; optimise and generate the code, then return
.close_all:
	move.w	#$9a,d0                         ; routine $9a: close all
	bra.w	emit_call_routine               ; jsr d0(a6) into the code, then return

;------------------------------------------------------------------------------
; OPEN mode$,#n,file$[,len]: $97 or $96.
;------------------------------------------------------------------------------
cmd_open:
	bsr.w	parse_expression                ; expression
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	addq.l	#1,a5                           ; skip '#'
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_expression                ; expression
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	beq.s	.no_record_length
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$ffd9,(a0)+                    ; IR $ffd9: pop address
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
	move.w	#$97,(a0)+                      ; routine $97: OPEN with record length
	bra.w	end_statement                   ; optimise and generate the code, then return
.no_record_length:
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
	move.w	#$96,(a0)+                      ; routine $96
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; GET #n[,rec] (command $81): $a1 or $a2.
;------------------------------------------------------------------------------
cmd_get_record:
	addq.l	#1,a5                           ; skip '#'
	bsr.w	parse_int_expression            ; integer expression
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	beq.s	.no_record
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	#$a1,(a0)+                      ; routine $a1: GET #n,rec
	bra.w	end_statement                   ; optimise and generate the code, then return
.no_record:
	move.w	#$a2,(a0)+                      ; routine $a2: GET #n
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; PUT #n[,rec] (command $83): $a8 or $a7.
;------------------------------------------------------------------------------
cmd_put_record:
	addq.l	#1,a5                           ; skip '#'
	bsr.w	parse_int_expression            ; integer expression
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	beq.s	.no_record
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	#$a8,(a0)+                      ; routine $a8: PUT #n,rec
	bra.w	end_statement                   ; optimise and generate the code, then return
.no_record:
	move.w	#$a7,(a0)+                      ; routine $a7: PUT #n
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; BGET #n,addr,len: routine $aa.
;------------------------------------------------------------------------------
cmd_bget:
	move.w	#$aa,d0
	bra.s	parse_channel_two_ints

;------------------------------------------------------------------------------
; BPUT #n,addr,len: routine $ab.
;------------------------------------------------------------------------------
cmd_bput:
	move.w	#$ab,d0

;------------------------------------------------------------------------------
; #n selected ($126), then two integers and routine d0.
;------------------------------------------------------------------------------
parse_channel_two_ints:
	move.w	d0,-(sp)                        ; keep the routine number
	addq.l	#1,a5                           ; skip '#'
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$126,(a0)+                     ; select channel
	move.w	(sp)+,d0                        ; restore it
	bra.w	two_int_args_statement

;------------------------------------------------------------------------------
; BSAVE file$,addr,len: routine $ae.
;------------------------------------------------------------------------------
cmd_bsave:
	bsr.w	parse_expression                ; expression
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	move.w	#$fff4,d0                       ; IR $fff4 in place of a routine: pops the string
	bsr.w	parse_two_int_args              ; two integers and routine d0
	move.w	#$ae,(a0)+                      ; routine $ae
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; BLOAD file$[,addr]: $ac or $ad.
;------------------------------------------------------------------------------
cmd_bload:
	bsr.w	parse_expression                ; expression
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	beq.s	.no_address
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
	move.w	#$ac,(a0)+                      ; routine $ac
	bra.w	end_statement                   ; optimise and generate the code, then return
.no_address:
	move.w	#$ad,(a0)+                      ; routine $ad
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; SEEK #n,pos: routine $af.
;------------------------------------------------------------------------------
cmd_seek:
	move.w	#$af,d0
	addq.l	#1,a5                           ; skip '#'
	bra.w	two_int_args_statement

;------------------------------------------------------------------------------
; RELSEEK #n,pos: routine $b0.
;------------------------------------------------------------------------------
cmd_relseek:
	move.w	#$b0,d0
	addq.l	#1,a5                           ; skip '#'
	bra.w	two_int_args_statement

;------------------------------------------------------------------------------
; CHDRIVE n: routine $b6.
;------------------------------------------------------------------------------
cmd_chdrive:
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$b6,(a0)+                      ; routine $b6
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; BMOVE src,dst,len: routine $b8.
;------------------------------------------------------------------------------
cmd_bmove:
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	moveq	#-12,d0                         ; IR $fff4 in place of a routine: a second pop
	bsr.w	parse_two_int_args              ; two integers and routine d0
	move.w	#$b8,(a0)+                      ; routine $b8
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; RESERVE n: routine $b9.
;------------------------------------------------------------------------------
cmd_reserve:
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$b9,(a0)+                      ; routine $b9
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; HIDEM: jsr $208(a6).
;------------------------------------------------------------------------------
cmd_hidem:
	move.w	#$208,d0
	bra.w	emit_call_routine               ; jsr d0(a6) into the code, then return

;------------------------------------------------------------------------------
; SHOWM: jsr $209(a6).
;------------------------------------------------------------------------------
cmd_showm:
	move.w	#$209,d0
	bra.w	emit_call_routine               ; jsr d0(a6) into the code, then return

;------------------------------------------------------------------------------
; READ variables, one by one.
;------------------------------------------------------------------------------
cmd_read:
	bsr.s	parse_read_variable
	cmpi.b	#$46,(a5)+                      ; end of statement next?
	bne.s	cmd_read
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; READ into a float variable: $7a, store $ffd6.
;------------------------------------------------------------------------------
read_float_variable:
	move.w	#$7a,(a0)+                      ; routine $7a: READ number
	move.w	#$ffd6,(a0)+                    ; IR $ffd6: store float variable
	move.w	d1,(a0)+                        ; the variable index
	rts

;------------------------------------------------------------------------------
; READ into a string: $6d, store $ffd3.
;------------------------------------------------------------------------------
read_string_variable:
	move.w	#$6d,(a0)+                      ; routine $6d: READ string
	move.w	#$ffd3,(a0)+                    ; IR $ffd3: store string variable
	move.w	d1,(a0)+                        ; the variable index
	rts

;------------------------------------------------------------------------------
; READ into an integer: $7c, store $ffd5.
;------------------------------------------------------------------------------
read_int_variable:
	move.w	#$7c,(a0)+                      ; routine $7c: READ integer
	move.w	#$ffd5,(a0)+                    ; IR $ffd5: store integer variable
	move.w	d1,(a0)+                        ; the variable index
	rts

;------------------------------------------------------------------------------
; READ into a boolean: $7b, store $ffd4.
;------------------------------------------------------------------------------
read_bool_variable:
	move.w	#$7b,(a0)+                      ; routine $7b: READ boolean
	move.w	#$ffd4,(a0)+                    ; IR $ffd4: store boolean variable
	move.w	d1,(a0)+                        ; the variable index
	rts

;------------------------------------------------------------------------------
; One READ variable: routine by type ($7a float, $6d string, $7c integer, $7b boolean) then the
; store; array elements parse their subscripts first.
;------------------------------------------------------------------------------
parse_read_variable:
	move.b	(a5)+,d0                        ; d0 = variable token
	moveq	#0,d1
	move.b	(a5)+,d1                        ; d1 = index, low byte
	cmpi.b	#$f0,d0                         ; $f0-$ff: two-byte index
	bcs.s	.by_type
	asl.w	#8,d1                           ; high byte of the index
	move.b	(a5)+,d1                        ; low byte
.by_type:
	andi.w	#$7,d0                          ; type: 0 float 1 $ 2 % 3 ! 4-7 arrays
	beq.s	read_float_variable
	subq.w	#2,d0                           ; type 1 string, type 2 integer
	bmi.s	read_string_variable
	beq.s	read_int_variable
	subq.w	#2,d0                           ; type 3 boolean, type 4 float array
	bmi.s	read_bool_variable
	beq.s	.float_array
	subq.w	#2,d0                           ; type 5 string array, type 6 integer array
	bmi.s	.string_array
	beq.s	.int_array
	move.w	#$7b,-(sp)                      ; type 7 boolean array: $7b READ boolean
	moveq	#-99,d0                         ; $ff9d: store boolean element
	bra.s	.emit
.int_array:
	move.w	#$7c,-(sp)                      ; $7c: READ integer
	moveq	#-98,d0                         ; $ff9e: store integer element
	bra.s	.emit
.float_array:
	move.w	#$7a,-(sp)                      ; $7a: READ number
	moveq	#-96,d0                         ; $ffa0: store float element
	bra.s	.emit
.string_array:
	move.w	#$6d,-(sp)                      ; $6d: READ string
	moveq	#-97,d0                         ; $ff9f: store string element
.emit:
	bra.w	array_store_after_routine

;------------------------------------------------------------------------------
; RESTORE [label]: straight code, move.l #offset,$ae2(a4) with the label's DATA offset (entry+8),
; or clr.l $ae2(a4).
;------------------------------------------------------------------------------
cmd_restore:
	cmpi.b	#$46,(a5)                       ; end of statement next?
	beq.s	.no_label
	bsr.w	read_variable_token             ; d1 = variable token, d0 = index
	asl.l	#4,d0                           ; 16-byte entries
	movea.l	bss_end+$5c,a0                  ; label table
	move.l	8(a0,d0.l),d0                   ; label's DATA offset
	beq.s	.no_label
	move.w	#$297c,(a2)+                    ; $297c = move.l #imm,d16(a4)
	move.l	d0,(a2)+                        ; the DATA offset
	move.w	#$ae2,(a2)+                     ; $ae2(a4) = DATA pointer
	rts
.no_label:
	move.l	#$42ac0ae2,(a2)+                ; clr.l $ae2(a4)
	rts

;------------------------------------------------------------------------------
; MENU KILL: jsr $bc(a6).
;------------------------------------------------------------------------------
cmd_menu_kill:
	move.w	#$bc,d0
	bra.w	emit_call_routine               ; jsr d0(a6) into the code, then return

;------------------------------------------------------------------------------
; MENU OFF: jsr $bd(a6).
;------------------------------------------------------------------------------
cmd_menu_off:
	move.w	#$bd,d0
	bra.w	emit_call_routine               ; jsr d0(a6) into the code, then return

;------------------------------------------------------------------------------
; MENU KILL, MENU OFF, MENU m$() ($ba) or MENU n,x ($bb).
;------------------------------------------------------------------------------
cmd_menu:
	move.b	(a5),d0                         ; d0 = next token
	cmpi.b	#$b0,d0                         ; $b0 = KILL
	beq.s	cmd_menu_kill
	cmpi.b	#$af,d0                         ; $af = OFF
	beq.s	cmd_menu_off
	cmpi.b	#$e5,d0                         ; $e5 = string array
	beq.s	.one_byte_index
	cmpi.b	#$f5,d0                         ; $f5 = string array, two-byte index
	beq.s	.two_byte_index
.menu_item:
	move.w	#$bb,d0                         ; routine $bb: MENU n,x
	bra.w	two_int_args_statement
.two_byte_index:
	cmpi.b	#$20,3(a5)                      ; ')' after the two-byte index?
	bra.s	.check_close
.one_byte_index:
	cmpi.b	#$20,2(a5)                      ; array name followed by ')': MENU m$()
.check_close:
	bne.s	.menu_item
	bsr.w	read_variable_token             ; d1 = variable token, d0 = index
	move.w	#$ff9a,(a0)+                    ; IR $ff9a: string array
	move.w	d0,(a0)+                        ; the array index
	move.w	#$ba,(a0)+                      ; routine $ba: set up the menu bar
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; ON MENU (command $8b): $d0, or $1f2 with a timeout.
;------------------------------------------------------------------------------
cmd_on_menu:
	addq.l	#1,a5                           ; skip a token
	cmpi.b	#$46,(a5)                       ; end of statement next?
	beq.s	.menu_event
	move.w	#$1f2,d0                        ; routine $1f2: ON MENU t
	bra.w	int_arg_statement
.menu_event:
	move.w	#$d0,d0                         ; routine $d0: ON MENU
	bra.w	emit_call_routine               ; jsr d0(a6) into the code, then return

;------------------------------------------------------------------------------
; ON ERROR|BREAK|MENU ... GOSUB proc: straight code storing the procedure address in the
; runtime's handler slot (move.l #proc,d16(a4)), or clr.l when there is no GOSUB:
; $b3c ERROR, $b38 BREAK, $b4a MENU, $b4e MENU KEY, $b5e MENU MESSAGE, $b52 MENU BUTTON.
; ON MENU IBOX/OBOX/BUTTON with arguments call $cd/$ce/$cc with the procedure in d7.
;------------------------------------------------------------------------------
cmd_on_event:
	cmpi.b	#$97,(a5)+                      ; $97 = ERROR
	bne.s	.not_error
	move.w	#$b3c,d0                        ; ON ERROR slot
.check_gosub:
	cmpi.b	#$4c,(a5)+                      ; $4c = GOSUB
	bne.s	.clear_handler
.emit_handler:
	move.w	d0,-(sp)                        ; keep the slot offset
	bsr.w	lookup_procedure                ; procedure defined?
	beq.s	.no_procedure
	move.w	#$297c,(a2)+                    ; move.l #proc,d16(a4)
	bsr.w	emit_reloc_long                 ; long d0 with a relocation entry
	move.b	#$1,-$4(a2)                     ; top byte 1: the long is a procedure index to resolve
	move.w	(sp)+,(a2)+                     ; the slot offset after the long
	rts
.no_procedure:
	move.w	(sp)+,d0                        ; restore the slot offset
.clear_handler:
	move.w	#$42ac,(a2)+                    ; $42ac = clr.l d16(a4)
	move.w	d0,(a2)+                        ; the slot offset
	rts
.break_cont:
	move.l	#$50ec0b38,d0                   ; ON BREAK CONT: loads st $b38(a4) into d0 and emits nothing
	rts
.not_error:
	cmpi.b	#$99,-$1(a5)                    ; $99 = BREAK
	bne.s	.menu_kind
	cmpi.b	#$9a,(a5)                       ; $9a = CONT
	beq.s	.break_cont
	move.w	#$b38,d0                        ; ON BREAK slot
	bra.s	.check_gosub
.menu_gosub:
	move.w	#$b4a,d0                        ; ON MENU GOSUB slot
	bra.s	.emit_handler
.menu_key:
	move.w	#$b4e,d0                        ; ON MENU KEY slot
.skip_token:
	addq.l	#1,a5                           ; skip a token
	bra.s	.emit_handler
.menu_message:
	move.w	#$b5e,d0                        ; ON MENU MESSAGE slot
	bra.s	.skip_token
.menu_kind:
	move.b	(a5)+,d0
	cmpi.b	#$4c,d0                         ; $4c = GOSUB
	beq.s	.menu_gosub
	cmpi.b	#$aa,d0                         ; $aa = KEY
	beq.s	.menu_key
	cmpi.b	#$ab,d0                         ; $ab = BUTTON
	beq.s	.menu_button
	cmpi.b	#$ae,d0                         ; $ae = MESSAGE
	beq.s	.menu_message
	move.w	d0,-(sp)                        ; IBOX/OBOX: n,x,y,w,h
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$ffd8,(a0)+                    ; IR $ffd8: push word argument
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$ffd8,(a0)+                    ; IR $ffd8: push word argument
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
	move.w	#$ffd9,(a0)+                    ; IR $ffd9: pop address
	bsr.w	end_statement                   ; optimise and generate the code
	bsr.w	lookup_procedure                ; procedure token, Z set if undefined
	beq.s	.box_no_procedure
	move.w	#$2e3c,(a2)+                    ; $2e3c = move.l #imm,d7
	bsr.w	emit_reloc_long                 ; long d0 with a relocation entry
	move.b	#$1,-$4(a2)                     ; top byte 1: procedure index to resolve
.box_call:
	move.w	#$cd,d0                         ; routine $cd: IBOX ($ac even) ...
	lsr.w	(sp)+                           ; bit 0 of the IBOX/OBOX token picks the routine
	bcc.w	emit_call_routine
	move.w	#$ce,d0                         ; ... $ce: OBOX
	bra.w	emit_call_routine               ; jsr d0(a6) into the code, then return
.box_no_procedure:
	move.w	#$7e00,(a2)+                    ; $7e00 = moveq #0,d7
	bra.s	.box_call
.menu_button:
	cmpi.b	#$4c,(a5)                       ; GOSUB next: a handler slot
	beq.s	.button_gosub
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$ffd8,(a0)+                    ; IR $ffd8: push word argument
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$ffd8,(a0)+                    ; IR $ffd8: push word argument
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	bsr.w	end_statement                   ; optimise and generate the code
	bsr.s	lookup_procedure                ; procedure token, Z set if undefined
	beq.s	.button_no_procedure
	move.w	#$2e3c,(a2)+                    ; move.l #proc,d7
	bsr.w	emit_reloc_long                 ; long d0 with a relocation entry
	move.b	#$1,-$4(a2)                     ; top byte 1: procedure index to resolve
.button_call:
	move.w	#$cc,d0                         ; routine $cc: ON MENU BUTTON
	bra.w	emit_call_routine               ; jsr d0(a6) into the code, then return
.button_no_procedure:
	move.w	#$7e00,(a2)+                    ; $7e00 = moveq #0,d7: no procedure
	bra.s	.button_call
.button_gosub:
	move.w	#$b52,d0                        ; ON MENU BUTTON GOSUB slot
	bra.w	.skip_token

;------------------------------------------------------------------------------
; Reads a procedure token; d0 = its index, Z clear when its PROCEDURE table entry is defined.
;------------------------------------------------------------------------------
lookup_procedure:
	bsr.w	read_variable_token             ; d1 = variable token, d0 = index
	move.l	d0,d2                           ; d2 = procedure index
	asl.l	#4,d2                           ; 16-byte entries
	pea	(a0)                            ; keep a0
	movea.l	bss_end+$60,a0                  ; PROCEDURE table
	tst.l	0(a0,d2.l)                      ; entry defined? (sets Z)
	movea.l	(sp)+,a0                        ; restore a0, flags unchanged
	rts

;------------------------------------------------------------------------------
; ON n GOSUB p1,p2,...: moveq #count,d7 (patched afterwards), call $cf, then the procedure
; addresses as longs (0 for undefined ones).
;------------------------------------------------------------------------------
cmd_on_gosub:
	bsr.w	parse_int_expression            ; integer expression
	bsr.w	end_statement                   ; optimise and generate the code
	move.w	#$7e00,(a2)+                    ; moveq #0,d7: count filled in below
	move.l	a2,d6                           ; d6 = just past the moveq
	move.w	#$cf,d0                         ; routine $cf: ON GOSUB
	bsr.w	emit_call_routine               ; jsr d0(a6) into the code
	moveq	#0,d7                           ; no procedures yet
.next_procedure:
	addq.w	#1,d7                           ; count this one
	bsr.s	lookup_procedure                ; procedure token, Z set if undefined
	beq.s	.undefined_procedure
	bsr.w	emit_reloc_long                 ; long d0 with a relocation entry
	move.b	#$1,-$4(a2)                     ; top byte 1: procedure index to resolve
.next_separator:
	cmpi.b	#$21,(a5)+                      ; ',' follows?
	beq.s	.next_procedure
	exg	d6,a2                           ; a2 = just past the moveq
	move.b	d7,-(a2)                        ; count into the moveq
	exg	d6,a2                           ; a2 back to the end of the code
	rts
.undefined_procedure:
	clr.l	(a2)+                           ; undefined procedure: address 0
	bra.s	.next_separator

;------------------------------------------------------------------------------
; CLS [#n]: $10d, or $10e with a channel.
;------------------------------------------------------------------------------
cmd_cls:
	cmpi.b	#$46,(a5)+                      ; end of statement next?
	beq.s	cls_screen
	move.w	#$10e,d0                        ; routine $10e: CLS #n

;------------------------------------------------------------------------------
; Integer argument and routine d0 (window commands).
;------------------------------------------------------------------------------
int_arg_statement_window:
	bra.w	int_arg_statement

;------------------------------------------------------------------------------
; CLS of the screen: jsr $10d(a6).
;------------------------------------------------------------------------------
cls_screen:
	move.w	#$10d,d0                        ; routine $10d: CLS
	bra.w	emit_call_routine               ; jsr d0(a6) into the code, then return

;------------------------------------------------------------------------------
; CLEARW n: routine $d6.
;------------------------------------------------------------------------------
cmd_clearw:
	move.w	#$d6,d0
	bra.s	int_arg_statement_window

;------------------------------------------------------------------------------
; FULLW n: routine $d2.
;------------------------------------------------------------------------------
cmd_fullw:
	move.w	#$d2,d0
	bra.s	int_arg_statement_window

;------------------------------------------------------------------------------
; CLOSEW n: routine $d5.
;------------------------------------------------------------------------------
cmd_closew:
	move.w	#$d5,d0
	bra.s	int_arg_statement_window

;------------------------------------------------------------------------------
; OPENW n[,x,y]: $d3 or $d4.
;------------------------------------------------------------------------------
cmd_openw:
	bsr.w	parse_int_expression            ; integer expression
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	beq.s	.openw_one
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
	move.w	#$d3,(a0)+                      ; routine $d3: OPENW n,x,y
	bra.w	end_statement                   ; optimise and generate the code, then return
.openw_one:
	move.w	#$d4,(a0)+                      ; routine $d4: OPENW n
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; INFOW n,a$: routine $d8.
;------------------------------------------------------------------------------
cmd_infow:
	move.w	#$d8,-(sp)                      ; routine number on the stack
	bra.s	window_text_statement

;------------------------------------------------------------------------------
; TITLEW n,a$: routine $d9.
;------------------------------------------------------------------------------
cmd_titlew:
	move.w	#$d9,-(sp)                      ; routine number on the stack

;------------------------------------------------------------------------------
; Window number and string, then the routine on the stack.
;------------------------------------------------------------------------------
window_text_statement:
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_expression                ; expression
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	(sp)+,(a0)+                     ; the routine after the arguments
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; DIR [mask$ [TO file$]]: $181, $182, $183.
;------------------------------------------------------------------------------
cmd_dir:
	cmpi.b	#$46,(a5)                       ; end of statement next?
	beq.s	.dir_plain
	bsr.w	parse_expression                ; expression
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	beq.s	.dir_mask
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	bsr.w	parse_expression                ; expression
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
	move.w	#$183,(a0)+                     ; routine $183: DIR mask$ TO file$
	bra.w	end_statement                   ; optimise and generate the code, then return
.dir_plain:
	move.w	#$181,d0                        ; routine $181: DIR
	bra.w	emit_call_routine               ; jsr d0(a6) into the code, then return
.dir_mask:
	move.w	#$182,(a0)+                     ; routine $182: DIR mask$
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; FILES [mask$ [TO file$]]: $184, $185, $186.
;------------------------------------------------------------------------------
cmd_files:
	cmpi.b	#$46,(a5)                       ; end of statement next?
	beq.s	.files_plain
	bsr.w	parse_expression                ; expression
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	beq.s	.files_mask
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	bsr.w	parse_expression                ; expression
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
	move.w	#$186,(a0)+                     ; routine $186
	bra.w	end_statement                   ; optimise and generate the code, then return
.files_plain:
	move.w	#$184,d0
	bra.w	emit_call_routine               ; jsr d0(a6) into the code, then return
.files_mask:
	move.w	#$185,(a0)+                     ; routine $185
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; CLEAR: jsr $154(a6).
;------------------------------------------------------------------------------
cmd_clear:
	move.w	#$154,d0
	bra.w	emit_call_routine               ; jsr d0(a6) into the code, then return

;------------------------------------------------------------------------------
; TEXT x,y,a$ (command $27): $187, numbers through STR$ ($41).
;------------------------------------------------------------------------------
cmd_text:
	move.w	#$226,d0
	bsr.w	parse_two_int_args              ; two integers and routine d0
	bsr.w	parse_expression                ; expression
	tst.w	d6                              ; d6 negative: string
	bmi.s	.text_string
	move.w	#$41,(a0)+                      ; routine $41 (STR$) for a number
.text_string:
	move.w	#$187,(a0)+                     ; routine $187: TEXT x,y,a$
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; TEXT x,y,len,a$ (command $2f): $188.
;------------------------------------------------------------------------------
cmd_text_length:
	move.w	#$226,d0
	bsr.w	parse_two_int_args              ; two integers and routine d0
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_expression                ; expression
	tst.w	d6                              ; d6 negative: string
	bmi.s	.text_length_string
	move.w	#$41,(a0)+                      ; routine $41
.text_length_string:
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	#$188,(a0)+                     ; routine $188: TEXT x,y,len,a$
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; DRAW [TO] x,y [TO x,y ...]: points as words, $ff8a or $ff89 with the byte count.
;------------------------------------------------------------------------------
cmd_draw:
	moveq	#0,d7                           ; d7 = argument bytes; bit 15 = TO first
	cmpi.b	#$47,(a5)                       ; $47 = TO first
	bne.s	.next_point
	bset	#$f,d7                          ; TO first
	addq.l	#1,a5                           ; skip a token
.next_point:
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$ffd8,(a0)+                    ; IR $ffd8: push word argument
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$ffd8,(a0)+                    ; IR $ffd8: push word argument
	addq.b	#4,d7                           ; 4 bytes of arguments per point
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	bne.s	.next_point
	moveq	#-118,d0                        ; IR $ff8a: DRAW
	bclr	#$f,d7                          ; TO first?
	beq.s	.emit_draw
	moveq	#-119,d0                        ; IR $ff89: DRAW TO
.emit_draw:
	move.w	d0,(a0)+                        ; DRAW operation
	move.w	d7,(a0)+                        ; argument bytes
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; FIELD #n,len AS a$,...: $1a3 then $180 per field.
;------------------------------------------------------------------------------
cmd_field:
	addq.l	#1,a5                           ; skip '#'
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$1a3,(a0)+                     ; routine $1a3: FIELD #n
.next_field:
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_expression                ; expression
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	#$180,(a0)+                     ; routine $180: one field len AS a$
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	bne.s	.next_field
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; A list of variables separated by ',': IR (d7 - type) and the index for each (CLR, LOCAL).
;------------------------------------------------------------------------------
parse_variable_list:
	bsr.w	read_variable_token             ; d1 = variable token, d0 = index
	andi.w	#$3,d1                          ; type bits
	move.w	d7,d2                           ; d2 = base IR word ...
	sub.w	d1,d2                           ; ... minus the type
	move.w	d2,(a0)+                        ; IR word
	move.w	d0,(a0)+                        ; variable index
	cmpi.b	#$21,(a5)+                      ; ',' follows?
	beq.s	parse_variable_list
	rts

;------------------------------------------------------------------------------
; CLR vars: IR $ff97 - type per variable.
;------------------------------------------------------------------------------
cmd_clr:
	moveq	#-105,d7                        ; IR $ff97-type: CLR
	bsr.s	parse_variable_list
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; LOCAL vars: IR $ff93 - type per variable.
;------------------------------------------------------------------------------
cmd_local:
	moveq	#-109,d7                        ; IR $ff93-type: LOCAL
	bsr.s	parse_variable_list
	bra.w	end_statement                   ; optimise and generate the code, then return

; Byte flag: the CALL has a string argument.
call_has_string_args:
	dc.w	$0000

;------------------------------------------------------------------------------
; CALL addr[,args]: arguments pushed as longs in reverse order; strings through $12e (their
; address), $12d when there was one; then IR $ff8b with the argument count.
;------------------------------------------------------------------------------
cmd_call:
	st	expr_has_side_effects           ; CALL has side effects: no merging of terms
	sf	call_has_string_args            ; no string argument yet
	clr.w	-(sp)                           ; argument count on the stack
	movea.l	sp,a3                           ; a3 = address of the count
	pea	(a0)                            ; keep the IR start
	bsr.w	parse_int_expression            ; integer expression
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	beq.s	.no_args
.hold_ir:
	movea.l	(sp)+,a1                        ; a1 = start of the last argument's IR
.hold_word:
	move.w	-(a0),-(sp)                     ; hold its IR on the stack (reverses the argument order)
	cmpa.l	a0,a1
	bne.s	.hold_word                      ; until all of it is held
	cmpi.b	#$46,(a5)                       ; end of statement next?
	beq.s	.restore_test
	pea	(a0)                            ; keep the IR start
	addq.w	#1,(a3)                         ; count the argument
	bsr.w	parse_expression                ; expression
	tst.w	d6                              ; d6 negative: string
	bpl.s	.numeric_arg
	move.w	#$12e,(a0)+                     ; routine $12e: string as address
	st	call_has_string_args            ; a string argument seen
	bra.s	.hold_ir
.numeric_arg:
	move.w	#$ffff,(a0)+                    ; IR $ffff: float to integer
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bra.s	.hold_ir
.restore_word:
	move.w	(sp)+,(a0)+                     ; restore the held IR
.restore_test:
	cmpa.l	a3,sp                           ; until the count's slot
	bne.s	.restore_word
	tst.b	call_has_string_args            ; any string arguments?
	beq.s	.emit_call
	move.w	#$12d,(a0)+                     ; routine $12d
.emit_call:
	move.w	#$ff8b,(a0)+                    ; IR $ff8b: CALL, count follows
	move.w	(sp)+,(a0)+                     ; argument count
	bra.w	end_statement                   ; optimise and generate the code, then return
.no_args:
	move.w	#$ff8b,(a0)+                    ; IR $ff8b
	clr.w	(a0)+                           ; no arguments
	addq.l	#6,sp                           ; drop the IR start and the count
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; SOUND ch,vol,note,oct[,dur] or SOUND ch,vol,#period[,dur]: routine $18d-$191 by the number
; of arguments, $196 alone; a duration becomes a PAUSE ($176).
;------------------------------------------------------------------------------
cmd_sound:
	cmpi.b	#$46,(a5)                       ; end of statement next?
	beq.s	sound_end
	bsr.w	parse_int_expression            ; integer expression
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	beq.s	sound_one_arg
	move.w	#$ffd8,(a0)+                    ; IR $ffd8: push word argument
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$ffd8,(a0)+                    ; IR $ffd8: push word argument
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	beq.s	sound_two_args
	cmpi.b	#$4d,(a5)                       ; '#' (channel) follows?
	beq.s	sound_period
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	beq.s	sound_three_args
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	#$ffd9,(a0)+                    ; IR $ffd9: pop address
	move.w	#$190,(a0)+                     ; routine $190

;------------------------------------------------------------------------------
; Optional duration after SOUND / WAVE: PAUSE ($176).
;------------------------------------------------------------------------------
sound_duration:
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	beq.w	end_statement
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$176,(a0)+                     ; routine $176: PAUSE
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; SOUND / WAVE with nothing more: routine $196.
;------------------------------------------------------------------------------
sound_end:
	move.w	#$196,(a0)+                     ; routine $196
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; SOUND ch: routine $18d.
;------------------------------------------------------------------------------
sound_one_arg:
	move.w	#$18d,(a0)+                     ; routine $18d
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; SOUND ch,vol: routine $18e.
;------------------------------------------------------------------------------
sound_two_args:
	move.w	#$ffd9,(a0)+                    ; IR $ffd9: pop address
	move.w	#$18e,(a0)+                     ; routine $18e
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; SOUND ch,vol,note: routine $18f.
;------------------------------------------------------------------------------
sound_three_args:
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	#$18f,(a0)+                     ; routine $18f
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; SOUND ch,vol,#period: routine $191.
;------------------------------------------------------------------------------
sound_period:
	addq.l	#1,a5                           ; skip '#'
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$ffd9,(a0)+                    ; IR $ffd9: pop address
	move.w	#$191,(a0)+                     ; routine $191
	bra.s	sound_duration

;------------------------------------------------------------------------------
; WAVE voices,env,form,dur[,pause]: $192-$195, then $196 or the PAUSE.
;------------------------------------------------------------------------------
cmd_wave:
	cmpi.b	#$46,(a5)                       ; end of statement next?
	beq.s	sound_end
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$192,(a0)+                     ; routine $192
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	beq.s	sound_end
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$193,(a0)+                     ; routine $193
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	beq.s	sound_end
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$194,(a0)+                     ; routine $194
	cmpi.b	#$46,-$1(a5)                    ; statement ended?
	beq.s	sound_end
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$195,(a0)+                     ; routine $195
	bra.w	sound_duration

;------------------------------------------------------------------------------
; POLYLINE n,x(),y() [OFFSET x,y]: routine $197.
;------------------------------------------------------------------------------
cmd_polyline:
	move.w	#$197,d0
	bra.s	parse_polygon

;------------------------------------------------------------------------------
; POLYFILL: routine $198.
;------------------------------------------------------------------------------
cmd_polyfill:
	move.w	#$198,d0
	bra.s	parse_polygon

;------------------------------------------------------------------------------
; POLYMARK: routine $199.
;------------------------------------------------------------------------------
cmd_polymark:
	move.w	#$199,d0

;------------------------------------------------------------------------------
; Count, x() and y() arrays, the OFFSET (or $ffcc 0), then the routine on the stack.
;------------------------------------------------------------------------------
parse_polygon:
	move.w	d0,-(sp)                        ; keep the routine number
	movea.l	sp,a3                           ; a3 = stack mark
	pea	(a0)                            ; keep the IR start
	bsr.w	parse_int_expression            ; integer expression
	bsr.w	parse_array_name                ; array name
	addq.l	#1,a5                           ; skip a token
	move.w	#$19a,(a0)+                     ; routine $19a between the arrays
	bsr.w	parse_array_name                ; array name
	cmpi.b	#$46,(a5)+                      ; end of statement next?
	bne.s	.with_offset
	move.w	#$ffcc,(a0)+                    ; no OFFSET: IR $ffcc 0
	clr.l	(a0)+                           ; constant 0
	addq.l	#4,sp                           ; drop the IR start
.emit_routine:
	move.w	(sp)+,(a0)+                     ; the routine
	bra.w	end_statement                   ; optimise and generate the code, then return
.with_offset:
	movea.l	(sp)+,a1                        ; a1 = IR start
.hold_word:
	move.w	-(a0),-(sp)                     ; hold the IR on the stack
	cmpa.l	a0,a1
	bne.s	.hold_word                      ; until all of it is held
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$ffd8,(a0)+                    ; IR $ffd8: push word argument
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$ffd8,(a0)+                    ; IR $ffd8: push word argument
.restore_word:
	move.w	(sp)+,(a0)+                     ; restore the held IR
	cmpa.l	a3,sp
	bne.s	.restore_word                   ; until the stack mark
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	bra.s	.emit_routine

;------------------------------------------------------------------------------
; MOUSE mx,my,mk: $240 then the three variables stored.
;------------------------------------------------------------------------------
cmd_mouse:
	move.w	#$240,(a0)+                     ; routine $240: read the mouse
	move.w	#$fff9,(a0)+                    ; IR $fff9: push float
	bsr.s	parse_result_variable
	addq.l	#1,a5                           ; skip ','
	bsr.s	parse_result_variable
	addq.l	#1,a5                           ; skip ','
	bsr.s	parse_result_variable
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; MOUSE result into a float variable: $ff9c $fffe $ffd6.
;------------------------------------------------------------------------------
mouse_float_variable:
	move.w	#$ff9c,(a0)+                    ; IR $ff9c: result variable follows
	move.w	#$fffe,(a0)+                    ; IR $fffe: integer to float
	move.w	#$ffd6,(a0)+                    ; IR $ffd6: store float variable
	move.w	d1,(a0)+                        ; the variable index
	rts

;------------------------------------------------------------------------------
; MOUSE result into an integer variable: $ff9c $ffd5.
;------------------------------------------------------------------------------
mouse_int_variable:
	move.w	#$ff9c,(a0)+                    ; IR $ff9c: result variable follows
	move.w	#$ffd5,(a0)+                    ; IR $ffd5: store integer variable
	move.w	d1,(a0)+                        ; the variable index
	rts

;------------------------------------------------------------------------------
; MOUSE result into a boolean variable: $ff9c $fffb $ffd4.
;------------------------------------------------------------------------------
mouse_bool_variable:
	move.w	#$ff9c,(a0)+                    ; IR $ff9c: result variable follows
	move.w	#$fffb,(a0)+                    ; IR $fffb: integer to boolean
	move.w	#$ffd4,(a0)+                    ; IR $ffd4: store boolean variable
	move.w	d1,(a0)+                        ; the variable index
	rts

;------------------------------------------------------------------------------
; Stores a routine result into the variable that follows (MOUSE): $ff9c then the store for
; its type, with the conversion from integer.
;------------------------------------------------------------------------------
parse_result_variable:
	move.b	(a5)+,d0                        ; d0 = variable token
	moveq	#0,d1
	move.b	(a5)+,d1                        ; d1 = index, low byte
	cmpi.b	#$f0,d0                         ; $f0-$ff: two-byte index
	bcs.s	.by_type
	asl.w	#8,d1                           ; high byte of the index
	move.b	(a5)+,d1                        ; low byte
.by_type:
	andi.w	#$7,d0                          ; type: 0 float 1 $ 2 % 3 ! 4-7 arrays
	beq.s	mouse_float_variable
	subq.w	#3,d0                           ; types 1 and 2: integer store
	bmi.s	mouse_int_variable
	beq.s	mouse_bool_variable             ; type 3: boolean store
	subq.w	#3,d0                           ; types 4 and 5: float element
	bmi.s	.string_array
	beq.s	.int_array                      ; type 6: integer element; type 7 falls through
.string_array:
	move.w	#$ff9c,(a0)+                    ; float element store (types 4, 5 and 7 come here)
	bsr.w	parse_subscripts                ; subscripts, d7 = count
	move.w	#$fffe,(a0)+                    ; IR $fffe: integer to float
	move.w	#$ffa0,(a0)+                    ; IR $ffa0: store float element
	move.w	d1,(a0)+                        ; array index
	move.w	d7,(a0)+                        ; subscript count
	rts
.int_array:
	move.w	#$ff9c,(a0)+                    ; IR $ff9c: result variable follows
	bsr.w	parse_subscripts                ; subscripts, d7 = count
	move.w	#$ff9e,(a0)+                    ; IR $ff9e: store integer element
	move.w	d1,(a0)+                        ; array index
	move.w	d7,(a0)+                        ; subscript count
	rts
	move.w	#$ff9c,(a0)+                    ; not reached: a boolean element store
	bsr.w	parse_subscripts                ; subscripts, d7 = count
	move.w	#$fffb,(a0)+                    ; IR $fffb: integer to boolean
	move.w	#$ff9d,(a0)+                    ; IR $ff9d: store boolean element
	move.w	d1,(a0)+
	move.w	d7,(a0)+
	rts

;------------------------------------------------------------------------------
; FORM INPUT n,a$ ($19b) or FORM INPUT n AS a$ ($19c).
;------------------------------------------------------------------------------
cmd_form_input:
	addq.l	#1,a5                           ; skip a token
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	cmpi.b	#$21,-$1(a5)                    ; ',' follows?
	sne	-(sp)                           ; ',' or AS?
	bsr.w	parse_expression                ; expression
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	#$19b,(a0)+                     ; routine $19b: FORM INPUT n,a$
	tst.b	(sp)+                           ; ',' form: routine $19b stays
	beq.w	end_statement
	move.w	#$19c,-$2(a0)                   ; routine $19c: FORM INPUT n AS a$
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; EXEC mode,file$,cmd$,env$: via parse_exec with routine $b7.
;------------------------------------------------------------------------------
cmd_exec:
	move.w	#$b7,d7
	bsr.w	parse_exec
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; RESUME ($1a0), RESUME NEXT ($1be) or RESUME label: lea label,a0 and $1a1 ($1a2 when the
; label's flag byte is set); undefined label: runtime ERROR 20.
;------------------------------------------------------------------------------
cmd_resume:
	cmpi.b	#$46,(a5)                       ; end of statement next?
	beq.s	.resume_plain
	cmpi.b	#$e0,(a5)                       ; token below $e0: NEXT
	bcs.s	.resume_next
	bsr.w	read_variable_token             ; d1 = variable token, d0 = index
	move.l	a0,d6                           ; keep a0
	move.l	d0,d2                           ; d2 = label index
	asl.l	#4,d2                           ; 16-byte entries
	movea.l	bss_end+$5c,a0                  ; label table
	adda.l	d2,a0                           ; a0 = the label's entry
	move.w	#$1a1,d7                        ; $1a2 when the flag byte is set
	tst.b	(a0)                            ; flag byte set?
	bne.s	.emit_resume_label
	tst.l	(a0)                            ; label defined?
	movea.l	d6,a0                           ; restore a0, flags unchanged
	beq.s	.undefined_label
	move.w	#$1a2,d7                        ; routine $1a1: RESUME label
.emit_resume_label:
	move.w	d7,-(sp)                        ; keep the routine
	move.w	#$41f9,(a2)+                    ; $41f9 = lea abs.l,a0
	bsr.w	emit_reloc_long                 ; long d0 with a relocation entry
	move.w	(sp)+,d0                        ; the routine
	bra.w	emit_call_routine               ; jsr d0(a6) into the code, then return
.resume_plain:
	move.w	#$1a0,d0                        ; routine $1a0: RESUME
	bra.w	emit_call_routine               ; jsr d0(a6) into the code, then return
.resume_next:
	move.w	#$1be,d0                        ; routine $1be: RESUME NEXT
	bra.w	emit_call_routine               ; jsr d0(a6) into the code, then return
.undefined_label:
	moveq	#20,d0                          ; runtime ERROR 20
	bra.w	emit_runtime_error

; Long: the GOSUB's procedure index, kept during the argument parse.
gosub_procedure_entry:
	dc.w	$0000,$0000

; Three longs: the parameter types still to check (shifted 2 bits per argument).
gosub_parameter_types:
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000

;------------------------------------------------------------------------------
; GOSUB / @ proc[(args)]: checks the arguments against the procedure's parameter types (2 bits
; each in entry+4..+15: 0 float, 1 string, 2 integer, 3 boolean), pushes them, then lea proc,a0
; and routine $204. Errors become runtime ERRORs: 19 undefined, 45 wrong count, 42 missing
; argument, 46 string for a number, 47 number for a string.
;------------------------------------------------------------------------------
cmd_gosub:
	bsr.w	read_variable_token             ; d1 = variable token, d0 = index
	move.l	a0,d6                           ; keep a0
	move.l	d0,d2                           ; d2 = procedure index
	asl.l	#4,d2                           ; 16-byte entries
	movea.l	bss_end+$60,a0                  ; PROCEDURE table
	adda.l	d2,a0                           ; a0 = its entry
	tst.l	(a0)                            ; defined?
	beq.s	.undefined
	tst.b	(a0)                            ; parameter count
	bne.s	.with_params
	cmpi.b	#$46,(a5)+                      ; end of statement next?
	bne.s	.wrong_count
	movea.l	d6,a0                           ; restore a0
.emit_gosub:
	move.w	#$41f9,(a2)+                    ; $41f9 = lea abs.l,a0
	bsr.w	emit_reloc_long                 ; long d0 with a relocation entry
	move.b	#$1,-$4(a2)                     ; top byte 1: procedure index to resolve
	move.w	#$204,d0                        ; routine $204: GOSUB
	bra.w	emit_call_routine               ; jsr d0(a6) into the code, then return
.undefined:
	moveq	#19,d0                          ; runtime ERROR 19: procedure not defined
	bra.s	.emit_error
.wrong_count:
	moveq	#45,d0                          ; runtime ERROR 45: wrong number of arguments
.emit_error:
	movea.l	d6,a0                           ; restore a0
	bra.w	emit_runtime_error
.missing_args:
	moveq	#42,d0                          ; runtime ERROR 42: arguments missing
	bra.s	.emit_error
.with_params:
	cmpi.b	#$46,(a5)+                      ; end of statement next?
	beq.s	.missing_args
	move.l	d0,gosub_procedure_entry        ; keep the procedure index
	moveq	#0,d7
	move.b	(a0),d7                         ; d7 = parameter count
	movem.l	4(a0),d0-d2                     ; d0-d2 = the parameter type bits
	movea.l	d6,a0                           ; restore a0
.next_param:
	moveq	#0,d3                           ; d3 = next parameter's type
	add.l	d2,d2                           ; shift the 96-bit type field left ...
	addx.l	d1,d1
	addx.l	d0,d0
	addx.w	d3,d3                           ; ... its top bit into d3
	add.l	d2,d2                           ; and the second bit
	addx.l	d1,d1
	addx.l	d0,d0
	addx.w	d3,d3                           ; d3 = type 0-3
	movem.l	d0-d2,gosub_parameter_types     ; keep the remaining types
	tst.w	d3                              ; type 0: float
	beq.s	.float_param
	subq.w	#2,d3                           ; type 1 string, type 2 integer
	bmi.s	.string_param
	beq.s	.int_param
	bsr.w	parse_expression                ; type 3: boolean expression
	move.w	#$fffd,(a0)+                    ; IR $fffd: float to boolean
	move.w	#$ff88,(a0)+                    ; IR $ff88: push boolean
.check_numeric:
	tst.w	d6                              ; d6 negative: string
	bpl.s	.param_done
	moveq	#46,d0                          ; runtime ERROR 46: a string for a number
	bra.s	.error_exit
.param_done:
	movem.l	gosub_parameter_types(pc),d0-d2 ; the remaining types
	subq.w	#1,d7                           ; one parameter fewer
	beq.s	.params_done
	cmpi.b	#$21,-$1(a5)                    ; ',' follows?
	beq.s	.next_param
	moveq	#45,d0                          ; runtime ERROR 45: too few arguments
.error_exit:
	bra.w	emit_runtime_error
.params_done:
	moveq	#42,d0                          ; runtime ERROR 42 if more arguments follow
	cmpi.b	#$46,(a5)                       ; end of statement next?
	bne.s	.error_exit
	bsr.w	end_statement                   ; optimise and generate the code
	move.l	gosub_procedure_entry(pc),d0    ; the procedure index
	bra.w	.emit_gosub
.float_param:
	bsr.w	parse_expression                ; expression
	move.w	#$fff9,(a0)+                    ; IR $fff9: push float
	bra.s	.check_numeric
.int_param:
	bsr.w	parse_expression                ; expression
	move.w	#$ffff,(a0)+                    ; IR $ffff: float to integer
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bra.s	.check_numeric
.string_param:
	bsr.w	parse_expression                ; expression
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	tst.w	d6                              ; d6 negative: string
	bmi.s	.param_done
	moveq	#47,d0                          ; runtime ERROR 47: a number for a string
	bra.s	.error_exit

;------------------------------------------------------------------------------
; PROCEDURE name[(params)]: an END call first unless a RETURN came just before, then the
; procedure's address in its table entry and pops of the parameters into their variables
; ($ff8f - type) in reverse order.
;------------------------------------------------------------------------------
cmd_procedure:
	moveq	#0,d5                           ; d5 = offset of the procedure's code
	tst.w	after_return_count              ; RETURN just before?
	bne.s	.set_address
	move.w	#$201,(a0)+                     ; routine $201: END before the procedure
	moveq	#4,d5                           ; procedure starts after the 4-byte END call
.set_address:
	bsr.w	read_variable_token             ; d1 = variable token, d0 = index
	asl.l	#4,d0                           ; 16-byte entries
	move.l	a0,d6                           ; keep a0
	movea.l	bss_end+$60,a0                  ; PROCEDURE table
	adda.l	d0,a0                           ; a0 = its entry
	moveq	#0,d7
	move.b	(a0),d7                         ; d7 = parameter count
	move.l	bss_end+$88,(a0)                ; code address of the procedure ...
	add.l	d5,(a0)                         ; ... past the END call
	move.b	d7,(a0)                         ; restore the count byte (Z = no parameters)
	movea.l	d6,a0                           ; restore a0, flags unchanged
	beq.s	.done                           ; no parameters
	addq.l	#1,a5                           ; skip '('
.read_param:
	bsr.w	read_variable_token             ; d1 = variable token, d0 = index
	movem.w	d0-d1,-(sp)                     ; hold index and type
	cmpi.b	#$21,(a5)+                      ; ',' follows?
	beq.s	.read_param
.emit_pops:
	movem.w	(sp)+,d0-d1                     ; pop them in reverse order
	andi.w	#$3,d1                          ; type bits
	moveq	#-113,d2                        ; $ff8f ...
	sub.w	d1,d2                           ; ... minus the type: pop a parameter
	move.w	d2,(a0)+                        ; IR word
	move.w	d0,(a0)+                        ; variable index
	subq.w	#1,d7                           ; next parameter
	bne.s	.emit_pops
.done:
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; SWAP a(),b(): routine $15a.
;------------------------------------------------------------------------------
cmd_swap_arrays:
	bsr.w	parse_array_name                ; array name
	move.w	#$19a,(a0)+                     ; routine $19a
	addq.l	#1,a5                           ; skip ','
	bsr.w	parse_array_name                ; array name
	move.w	#$15a,(a0)+                     ; routine $15a: SWAP a(),b()
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; BITBLT s(),d(),p(): routine $19f.
;------------------------------------------------------------------------------
cmd_bitblt:
	bsr.w	parse_array_name                ; array name
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	addq.l	#1,a5                           ; skip ','
	bsr.w	parse_array_name                ; array name
	move.w	#$19a,(a0)+                     ; routine $19a
	addq.l	#1,a5                           ; skip ','
	bsr.w	parse_array_name                ; array name
	move.w	#$ff9c,(a0)+                    ; IR $ff9c: result variable follows
	move.w	#$19f,(a0)+                     ; routine $19f: BITBLT
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; SWAP with token $9a: routine $1aa (purpose not worked out).
;------------------------------------------------------------------------------
cmd_swap_pointer:
	addq.l	#1,a5                           ; skip a token
	bsr.w	parse_int_expression            ; integer expression
	bsr.w	parse_array_name                ; array name
	move.w	#$1aa,(a0)+                     ; routine $1aa
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; Command token $98 ('*'): integer, string, routine $1a8 (purpose not worked out).
;------------------------------------------------------------------------------
cmd_pointer_store:
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_expression                ; expression
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
	move.w	#$1a8,(a0)+                     ; routine $1a8
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; Command token $99 ('*'): integer, string, routine $1a9 (purpose not worked out).
;------------------------------------------------------------------------------
cmd_pointer_store_string:
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_expression                ; expression
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
	move.w	#$1a9,(a0)+                     ; routine $1a9
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; SWAP a,b: two simple variables are swapped by straight code (lea of both, then move.l/move.w
; exchanges copied from the templates at $1f10); strings call $15b; anything else goes through
; the variable addresses and $1a4/$1a6/$1a7/$15b.
;------------------------------------------------------------------------------
cmd_swap:
	move.l	a5,d7                           ; d7 = position of the first variable
	bsr.w	read_variable_token             ; d1 = variable token, d0 = index
	cmpi.b	#$21,(a5)+                      ; ',' follows?
	bne.w	swap_by_address                 ; not two variables: through their addresses
	move.w	d0,-(sp)                        ; keep the first index
	bsr.w	read_variable_token             ; d1 = variable token, d0 = index
	move.w	(sp)+,d2                        ; d2 = first index
	cmpi.b	#$46,(a5)                       ; end of statement next?
	bne.w	swap_by_address                 ; not two simple variables: through their addresses
	movem.w	d0/d2,(a0)                      ; second and first index into the IR buffer as scratch
	andi.w	#$3,d1                          ; type bits
	beq.s	swap_float_variables            ; type 0: float
	subq.w	#2,d1                           ; type 1 string, type 2 integer
	bmi.s	swap_string_variables
	beq.s	swap_int_variables
	move.l	bss_end+$48,d0                  ; type 3 boolean: start of the boolean storage
	move.w	(a0)+,d1                        ; second variable's index
	mulu.w	#$2,d1                          ; 2 bytes per boolean
	bsr.w	emit_lea_var_offset             ; its lea into a0
	move.l	bss_end+$48,d0                  ; boolean storage
	move.w	(a0)+,d1                        ; first variable's index
	mulu.w	#$2,d1                          ; 2 bytes per boolean
	bsr.w	emit_lea_offset_a1              ; its lea into a1

;------------------------------------------------------------------------------
; Copies the word swap from swap_word_template into the code.
;------------------------------------------------------------------------------
emit_swap_word:
	move.l	swap_word_template(pc),(a2)+    ; move.w (a0),d0 / move.w (a1),(a0)
	move.w	swap_word_template_end(pc),(a2)+ ; move.w d0,(a1)
	rts

;------------------------------------------------------------------------------
; SWAP of two integer variables: lea of both, long swap.
;------------------------------------------------------------------------------
swap_int_variables:
	move.l	bss_end+$44,d0                  ; integer storage
	move.w	(a0)+,d1                        ; second variable's index
	mulu.w	#$4,d1                          ; 4 bytes per integer
	bsr.w	emit_lea_var_offset             ; its lea into a0
	move.l	bss_end+$44,d0                  ; integer storage
	move.w	(a0)+,d1                        ; first variable's index
	mulu.w	#$4,d1                          ; 4 bytes per integer
	bsr.w	emit_lea_offset_a1              ; its lea into a1

;------------------------------------------------------------------------------
; Copies the long swap from swap_long_template into the code.
;------------------------------------------------------------------------------
emit_swap_long:
	move.l	swap_long_template(pc),(a2)+    ; move.l (a0),d0 / move.l (a1),(a0)+
	move.w	swap_long_template_end(pc),(a2)+ ; move.l d0,(a1)+
	rts

;------------------------------------------------------------------------------
; SWAP of two float variables: lea of both, long then word swap.
;------------------------------------------------------------------------------
swap_float_variables:
	move.l	bss_end+$3c,d0                  ; float storage
	bsr.w	emit_lea_var_6byte              ; lea of the 6-byte float into a0
	move.l	bss_end+$3c,d0                  ; float storage
	bsr.w	emit_lea_var_a1                 ; lea of the other into a1
	bsr.s	emit_swap_long                  ; swap the first 4 bytes ...
	bra.s	emit_swap_word                  ; ... then the last 2

;------------------------------------------------------------------------------
; SWAP of two strings: descriptors in a0/a1, then jsr $15b(a6).
;------------------------------------------------------------------------------
swap_string_variables:
	bsr.w	emit_lea_string_var             ; first string descriptor into a0
	bsr.w	emit_lea_string_var_a1          ; second into a1
	move.w	#$15b,d0                        ; routine $15b: swap strings
	bra.w	emit_call_routine               ; jsr d0(a6) into the code, then return

;------------------------------------------------------------------------------
; SWAP not of two simple variables: variable addresses, then $1a4/$15b/$1a6/$1a7 by type.
;------------------------------------------------------------------------------
swap_by_address:
	movea.l	d7,a5                           ; back to the first variable
	andi.w	#$3,d1                          ; type bits
	beq.s	.swap_float                     ; type 0: float
	subq.w	#2,d1                           ; type 1 string, type 2 integer
	bmi.s	.swap_strings
	beq.s	.swap_int
	bsr.w	parse_variable_address          ; boolean: the first address
	move.w	#$fff9,(a0)+                    ; IR $fff9: push float
	bsr.w	parse_variable_address          ; the second address
	move.w	#$fff6,(a0)+                    ; IR $fff6: pop float
	move.w	#$1a7,(a0)+                     ; routine $1a7: swap booleans
	bra.w	end_statement                   ; optimise and generate the code, then return
.swap_int:
	move.w	#$1a6,-(sp)                     ; routine $1a6: swap integers
	bra.s	.emit_pair
.swap_float:
	move.w	#$1a4,-(sp)                     ; routine $1a4: swap floats
.emit_pair:
	bsr.w	parse_variable_address          ; variable address
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_variable_address          ; variable address
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
	move.w	(sp)+,(a0)+                     ; the routine
	bra.w	end_statement                   ; optimise and generate the code, then return
.swap_strings:
	bsr.w	parse_variable_address          ; variable address
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	bsr.w	parse_variable_address          ; variable address
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
	move.w	#$15b,(a0)+                     ; routine $15b: swap strings
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; Template: move.l (a0),d0 / move.l (a1),(a0)+ (copied, not executed).
;------------------------------------------------------------------------------
swap_long_template:
	move.l	(a0),d0                         ; templates: move.l (a0),d0 / move.l (a1),(a0)+ / move.l d0,(a1)+
	move.l	(a1),(a0)+

;------------------------------------------------------------------------------
; Template: move.l d0,(a1)+.
;------------------------------------------------------------------------------
swap_long_template_end:
	move.l	d0,(a1)+

;------------------------------------------------------------------------------
; Template: move.w (a0),d0 / move.w (a1),(a0).
;------------------------------------------------------------------------------
swap_word_template:
	move.w	(a0),d0                         ; templates: move.w (a0),d0 / move.w (a1),(a0) / move.w d0,(a1)
	move.w	(a1),(a0)

;------------------------------------------------------------------------------
; Template: move.w d0,(a1).
;------------------------------------------------------------------------------
swap_word_template_end:
	move.w	d0,(a1)

;------------------------------------------------------------------------------
; DEFFN name[(params)]=expr: the function body is compiled in place and jumped over: the line's
; code starts with bra.w over it; the FN entry gets the body's address; ends with jmp $1fe(a6).
;------------------------------------------------------------------------------
cmd_deffn:
	move.w	#$ffa9,(a0)+                    ; IR $ffa9: placeholder word, later the bra.w
	move.w	#$ffa9,(a0)+                    ; IR $ffa9: placeholder for its displacement
	bsr.w	read_variable_token             ; d1 = variable token, d0 = index
	asl.l	#4,d0                           ; 16-byte entries
	move.l	a0,d6                           ; keep a0
	andi.w	#$f,d1                          ; type nibble of the FN token
	asl.w	#2,d1                           ; long index
	lea	bss_end+$3c,a0                  ; the 9 storage bound pointers, by type
	movea.l	0(a0,d1.w),a0                   ; a0 = the table for this token type
	adda.l	d0,a0                           ; a0 = the FN entry
	moveq	#0,d7
	move.b	(a0),d7                         ; d7 = parameter count
	move.l	bss_end+$88,(a0)                ; code address of the body ...
	addq.l	#4,(a0)                         ; ... after the 4-byte bra.w
	move.b	d7,(a0)                         ; restore the count byte (Z = no parameters)
	movea.l	d6,a0                           ; restore a0
	addq.l	#1,a5                           ; skip '(' or '='
	beq.s	.body                           ; no parameters (Z from the count)
.read_param:
	bsr.w	read_variable_token             ; d1 = variable token, d0 = index
	movem.w	d0-d1,-(sp)                     ; hold index and type
	cmpi.b	#$21,(a5)+                      ; ',' follows?
	beq.s	.read_param
.emit_pops:
	movem.w	(sp)+,d0-d1                     ; pop them in reverse order
	andi.w	#$3,d1                          ; type bits
	moveq	#-113,d2                        ; $ff8f ...
	sub.w	d1,d2                           ; ... minus the type: pop a parameter
	move.w	d2,(a0)+                        ; IR word
	move.w	d0,(a0)+                        ; variable index
	subq.w	#1,d7                           ; next parameter
	bne.s	.emit_pops
	addq.l	#1,a5                           ; skip '='
.body:
	bsr.w	parse_expression                ; expression
	bsr.w	end_statement                   ; optimise and generate the code
	move.w	#$1fe,d0                        ; routine $1fe: return from the FN
	bsr.w	emit_runtime_jmp
	move.w	#$6000,bss_end+$3d0             ; bra.w over the body
	move.l	a2,d0                           ; d0 = body length ...
	subi.l	#bss_end+$3d2,d0                ; ... from the displacement word
	move.w	d0,bss_end+$3d2                 ; the bra.w displacement
	rts

;------------------------------------------------------------------------------
; OPTION BASE 0|1 ($168/$169) or OPTION "x" with U0-U3 (Stop never / break test here / loop /
; ever), T+ (Trapv), B+ (Bombs), E+ (Errors).
;------------------------------------------------------------------------------
cmd_option:
	cmpi.b	#$b6,(a5)+                      ; $b6 = BASE
	bne.s	.option_string                  ; no: OPTION "string"
	move.b	(a5),d0                         ; the 0/1 token
	lsr.b	#1,d0                           ; bit 0 = 1?
	bcc.s	.base_zero
	move.w	#$169,d0                        ; routine $169: OPTION BASE 1
	bra.w	emit_call_routine               ; jsr d0(a6) into the code, then return
.base_zero:
	move.w	#$168,d0                        ; routine $168: OPTION BASE 0
	bra.w	emit_call_routine               ; jsr d0(a6) into the code, then return
.option_string:
	moveq	#0,d0
	move.b	(a5)+,d0                        ; skip a byte (string token or length; not checked)
	move.b	(a5)+,d0                        ; d0 = option letter
	move.b	(a5)+,d1                        ; d1 = its argument
	andi.b	#$df,d0                         ; upper case
	cmpi.b	#$55,d0                         ; 'U'
	beq.s	.option_u
	cmpi.b	#$54,d0                         ; 'T'
	beq.s	.option_t
	cmpi.b	#$42,d0                         ; 'B'
	beq.s	.option_b
	cmpi.b	#$45,d0                         ; 'E'
	beq.s	.option_e
	rts                                     ; unknown letter: ignored
.option_b:
	cmpi.b	#$2b,d1                         ; '+'?
	seq	option_bombs                    ; Bombs on with '+', off otherwise
	rts
.option_e:
	cmpi.b	#$2b,d1                         ; '+'?
	seq	option_errors                   ; Errors on with '+', off otherwise
	rts
.option_t:
	cmpi.b	#$2b,d1                         ; '+'?
	seq	option_trapv                    ; Trapv on with '+', off otherwise
	rts
.option_u:
	cmpi.b	#$30,d1                         ; '0'
	beq.s	.stop_never
	cmpi.b	#$31,d1                         ; '1'
	beq.s	.stop_here
	cmpi.b	#$32,d1                         ; '2'
	beq.s	.stop_loop
	cmpi.b	#$33,d1                         ; '3'
	beq.s	.stop_ever
.stop_here:
	bra.w	emit_break_test                 ; U1 (or any other digit): a break test here
.stop_never:
	sf	option_stop_mode                ; U0: Stop never
	rts
.stop_loop:
	move.b	#$1,option_stop_mode            ; U2: Stop loop
	rts
.stop_ever:
	st	option_stop_mode                ; U3: Stop ever
	rts

; Byte flag: OPTION "T+" (Trapv).
option_trapv:
	dc.b	$00

; Byte: Stop mode, 0 never, 1 loop, -1 ever (OPTION "U0".."U3" and the dialog).
option_stop_mode:
	dc.b	$00                             ; 0 never, 1 loop, -1 ever

; Byte flag: OPTION "B+" (Bombs).
option_bombs:
	dc.b	$00

; Byte flag: OPTION "E+" (Errors).
option_errors:
	dc.b	$00

;------------------------------------------------------------------------------
; With Stop Loop: emit_break_test (loops, GOTO, NEXT).
;------------------------------------------------------------------------------
loop_break_test:
	tst.b	option_stop_mode                ; Stop Loop: break test at loops and GOTOs
	bgt.s	emit_break_test
	rts

;------------------------------------------------------------------------------
; Appends jsr (a6) (break test) to the code region and records its position in region
; bss_end+$8c as the distance from the previous one: a word, or a long with bit 31 set.
;------------------------------------------------------------------------------
emit_break_test:
	movem.l	a0-a3,-(sp)                     ; keep the buffer pointers
	lea	bss_end+$88,a0                  ; code region
	moveq	#2,d0                           ; 2 bytes
	bsr.w	open_memory_gap                 ; make room at the end of region a0
	move.w	break_test_template(pc),(a0)    ; jsr (a6) at the end of the code
	move.l	bss_end+$a8,d0                  ; d0 = previous break test position
	move.l	a0,bss_end+$a8                  ; this one is the last now
	sub.l	a0,d0                           ; d0 = distance ...
	neg.l	d0                              ; ... from the previous one
	cmpi.l	#$7fff,d0
	bcs.s	.short_distance
	bset	#$1f,d0                         ; bit 31 marks a long distance
	move.l	d0,-(sp)                        ; keep it
	moveq	#4,d0                           ; 4 bytes
	lea	bss_end+$8c,a0                  ; break test list region
	bsr.w	open_memory_gap                 ; make room at the end of region a0
	move.l	(sp)+,(a0)+                     ; the long distance
	bra.s	.done
.short_distance:
	move.w	d0,-(sp)                        ; keep it
	moveq	#2,d0                           ; 2 bytes
	lea	bss_end+$8c,a0                  ; break test list region
	bsr.w	open_memory_gap                 ; make room at the end of region a0
	move.w	(sp)+,(a0)+                     ; the word distance
.done:
	movem.l	(sp)+,a0-a3                     ; restore the buffer pointers
	rts

;------------------------------------------------------------------------------
; Template instruction jsr (a6) (the break test), copied by emit_break_test.
;------------------------------------------------------------------------------
break_test_template:
	jsr	(a6)                            ; template: jsr (a6)

;------------------------------------------------------------------------------
; INC var: integer variable $ffc6, float variable $ffc5 straight on the variable; array
; elements through their address ($ffc4 integer, $ffc3 other). Code generated at once.
;------------------------------------------------------------------------------
cmd_inc:
	bsr.w	read_variable_token             ; d1 = variable token, d0 = index
	move.w	#$ffc6,d2                       ; IR $ffc6: INC integer variable
	cmpi.b	#$e2,d1                         ; $e2 = integer variable
	beq.s	emit_var_op_direct
	moveq	#-60,d2                         ; $ffc4: INC integer element by address
	cmpi.b	#$e6,d1                         ; $e6 = integer array
	beq.s	inc_dec_by_address
	moveq	#-61,d2                         ; $ffc3: INC anything else by address
	cmpi.b	#$e0,d1                         ; $e0 = float variable
	bne.s	inc_dec_by_address
	move.w	#$ffc5,d2                       ; $ffc5: INC float variable

;------------------------------------------------------------------------------
; INC/DEC straight on a simple variable: IR d2 and the index, code generated at once.
;------------------------------------------------------------------------------
emit_var_op_direct:
	move.w	d2,(a0)+                        ; IR word
	move.w	d0,(a0)+                        ; variable index
	bra.w	generate_code                   ; code at once, without the optimiser

;------------------------------------------------------------------------------
; INC/DEC through the variable's address.
;------------------------------------------------------------------------------
inc_dec_by_address:
	lea	bss_end+$c06,a5                 ; re-read the line from its first operand
	move.w	d2,-(sp)                        ; keep the IR word
	bsr.w	parse_variable_address          ; variable address
	move.w	(sp)+,(a0)+                     ; the INC/DEC IR word
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; DEC var: $ffc2 integer, $ffc1 float, through the address $ffbf float element, $ffc0 other.
;------------------------------------------------------------------------------
cmd_dec:
	bsr.w	read_variable_token             ; d1 = variable token, d0 = index
	move.w	#$ffc2,d2                       ; IR $ffc2: DEC integer variable
	cmpi.b	#$e2,d1                         ; $e2 = integer variable
	beq.s	emit_var_op_direct
	move.w	#$ffc1,d2                       ; $ffc1: DEC float variable
	cmpi.b	#$e0,d1                         ; $e0 = float variable
	beq.s	emit_var_op_direct
	moveq	#-65,d2                         ; $ffbf: DEC float element by address
	cmpi.b	#$e4,d1                         ; $e4 = float array
	beq.s	inc_dec_by_address
	moveq	#-64,d2                         ; $ffc0: DEC anything else by address
	bra.s	inc_dec_by_address

;------------------------------------------------------------------------------
; ADD var,n: variable address pushed, value (integer for %/! variables), then $ffbc / $ffbb.
; SUB, MUL, DIV follow the same way ($ffb8/$ffb7, $ffb4/$ffb3, $ffb0/$ffaf).
;------------------------------------------------------------------------------
cmd_add:
	move.b	(a5),-(sp)                      ; keep the variable token
	bsr.s	parse_variable_address          ; variable address
	move.w	#$fff8,(a0)+                    ; push the address
	btst	#$1,(sp)+                       ; token bit 1: % or ! variable
	beq.s	.add_float
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$ffd9,(a0)+                    ; IR $ffd9: pop the address
	move.w	#$ffbc,(a0)+                    ; IR $ffbc
	bra.w	end_statement                   ; optimise and generate the code, then return
.add_float:
	bsr.w	parse_expression                ; expression
	move.w	#$ffd9,(a0)+                    ; IR $ffd9: pop address
	move.w	#$ffbb,(a0)+                    ; IR $ffbb
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; SUB var,n: $ffb8 integer value, $ffb7 float.
;------------------------------------------------------------------------------
cmd_sub:
	move.b	(a5),-(sp)                      ; keep the variable token
	bsr.s	parse_variable_address          ; variable address
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	btst	#$1,(sp)+                       ; token bit 1: % or ! variable
	beq.s	.sub_float
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$ffd9,(a0)+                    ; IR $ffd9: pop address
	move.w	#$ffb8,(a0)+                    ; IR $ffb8
	bra.w	end_statement                   ; optimise and generate the code, then return
.sub_float:
	bsr.w	parse_expression                ; expression
	move.w	#$ffd9,(a0)+                    ; IR $ffd9: pop address
	move.w	#$ffb7,(a0)+                    ; IR $ffb7
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; Variable address for ADD/SUB/MUL/DIV/SWAP: parse_varptr without its $fffe.
;------------------------------------------------------------------------------
parse_variable_address:
	bsr.w	parse_varptr
	subq.l	#2,a0                           ; drop the trailing $fffe
	rts

;------------------------------------------------------------------------------
; MUL var,n: $ffb4 for %/! variables, $ffb3 float.
;------------------------------------------------------------------------------
cmd_mul:
	move.b	(a5),-(sp)                      ; keep the variable token
	bsr.s	parse_variable_address          ; variable address
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_expression                ; expression
	move.w	#$ffd9,(a0)+                    ; IR $ffd9: pop address
	moveq	#-77,d0                         ; $ffb3: MUL float
	btst	#$1,(sp)+                       ; token bit 1: % or ! variable
	beq.s	.mul_emit
	moveq	#-76,d0                         ; $ffb4: MUL integer
.mul_emit:
	move.w	d0,(a0)+                        ; the operator
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; DIV var,n: $ffb0 for %/! variables, $ffaf float.
;------------------------------------------------------------------------------
cmd_div:
	move.b	(a5),-(sp)                      ; keep the variable token
	bsr.s	parse_variable_address          ; variable address
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_expression                ; expression
	move.w	#$ffd9,(a0)+                    ; IR $ffd9: pop address
	moveq	#-81,d0                         ; $ffaf: DIV float
	btst	#$1,(sp)+                       ; token bit 1: % or ! variable
	beq.s	.div_emit
	moveq	#-80,d0                         ; $ffb0: DIV integer
.div_emit:
	move.w	d0,(a0)+                        ; the operator
	bra.w	end_statement                   ; optimise and generate the code, then return

;------------------------------------------------------------------------------
; Expression parser: operator precedence over the token stream at a5, writing IR at a0.
; Each token's priority comes from token_priority_table ($ff operand or function: its handler
; runs at once; 0 ends the expression; else a binary operator). Before an operator its left
; operand is pushed ($fff9 float, $ffff/$fff8 integer for AND..EQV, $fff7 string). Ends past the
; terminator (callers look at -1(a5)). Exit: d6 = result type (negative = string). Keeps d7, a3.
;------------------------------------------------------------------------------
parse_expression:
	move.w	d7,-(sp)                        ; keep the caller's d7
	pea	(a3)
	moveq	#0,d6                           ; d6 = 0: numeric so far
	pea	$4646.w                         ; sentinel: priority 0, token $46 (end)
.next_token:
	moveq	#0,d7
	move.b	(a5)+,d7                        ; next token
	move.b	token_priority_table(pc,d7.w),d5 ; its priority
	bmi.s	.operand                        ; $ff: operand or function
.compare_priority:
	cmp.b	(sp),d5                         ; stacked operator binds at least as tight?
	bls.s	.pop_operator
	move.b	d7,-(sp)                        ; stack token and priority
	move.b	d5,-(sp)
	cmpi.b	#$4,d5                          ; priority 4: AND OR XOR IMP EQV
	beq.s	.push_int
	cmpi.b	#$3c,d5                         ; $3c: string compare
	beq.s	.push_string
	cmpi.b	#$41,d5                         ; $41: string +
	beq.s	.push_string
	move.w	#$fff9,(a0)+                    ; IR $fff9: push float
	bra.s	.next_token
.push_int:
	move.w	#$ffff,(a0)+                    ; IR $ffff, $fff8: integer and push
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bra.s	.next_token
.push_string:
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	bra.s	.next_token
.pop_operator:
	addq.l	#2,sp                           ; pop the stacked operator ...
	moveq	#0,d4                           ; d4 = ...
	move.b	(sp)+,d4                        ; ... the stacked operator's token
	exg	d4,d7                           ; handler gets the operator token in d7
	bsr.s	call_token_handler              ; ... and run its handler
	exg	d4,d7                           ; d7 = the current token again
	bra.s	.compare_priority
.operand:
	bsr.s	call_token_handler              ; operand or function: handler now
	bra.s	.next_token

;------------------------------------------------------------------------------
; Jumps to the expression handler of token d7 (from token_handler_table).
;------------------------------------------------------------------------------
call_token_handler:
	move.w	d7,d0                           ; d7 = token
	add.w	d0,d0                           ; word index
	lea	token_handler_table,a2          ; handler table, offsets from $233e
	adda.w	0(a2,d0.w),a2                   ; a2 = handler address
	jmp	(a2)                            ; handler gets d7 = token

; One byte per expression token: binary operator priority (4 AND..EQV, $1e +/-, $28 * /, $32 ^,
; $23 MOD DIV, $0a compares, $3c string compares, $41 string +), 0 a terminator, $ff an operand
; or function, $f7 tokens that may not appear. Decoded as code and words up to $230b.
token_priority_table:
	dc.w	$0404,$0404,$041e
	dc.b	$1e
	dc.b	'((2##',10,10,10,10,10,10,10,10,'<<<<<<<<A'
	dc.b	$ff,$ff,$ff,$00,$00,$00,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff
	dc.b	$0a,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff
	dc.b	$ff,$ff,$ff,$00,$ff,$ff,$ff,$ff,$00,$00,$00,$00,$00,$00,$00,$00
	dc.b	$00,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$00,$ff,$00,$00,$08,$ff
	dc.b	$ff,$ff,$ff,$00,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$00
	dc.b	$00,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$00
	dc.b	$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff
	dc.b	$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$00,$00,$ff,$ff
	dc.b	$00,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$00,$00,$00
	dc.b	$00,$00,$00,$00,$ff,$ff,$ff,$ff,$ff,$00,$ff,$ff,$ff,$ff,$ff,$ff
	dc.b	$ff,$ff,$ff,$ff,$f7,$f7,$f7,$f7,$f7,$f7,$f7,$f7,$f7,$f7,$f7,$f7
	dc.b	$f7,$f7,$f7,$f7,$f7,$f7,$f7,$f7,$f7,$f7,$ff,$ff,$ff,$ff,$ff,$ff
	dc.b	$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff
	dc.b	$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff,$ff
	dc.b	$ff,$ff,$ff,$58,$8f,$26,$5f,$3e,$1f,$4e,$75,$61,$06,$30,$fc,$00
	dc.b	$1e,$4e,$75

;------------------------------------------------------------------------------
; One operand for a sign: the next token's handler; a following '^' ($9) is applied first.
;------------------------------------------------------------------------------
parse_signed_operand:
	move.b	(a5)+,d7                        ; d7 = operand token
	bsr.w	call_token_handler
	cmpi.b	#$9,(a5)                        ; '^' binds tighter than the sign
	beq.s	.power
	rts
.power:
	addq.l	#1,a5                           ; skip a token
	move.w	#$fff9,(a0)+                    ; push float
	moveq	#0,d7                           ; next operand ...
	move.b	(a5)+,d7                        ; ... token
	bsr.w	call_token_handler
	moveq	#9,d7                           ; routine 9: power
	bra.w	emit_float_operator

; Handler offsets from $233e for the 256 expression tokens; decoded as code up to $253d.
token_handler_table:
	dc.w	$0220,$0220,$0220,$0220,$0220,$0212,$0212,$0212
	dc.w	$0212,$0212,$0212,$0212,$0230,$0230,$0230,$0230
	dc.w	$0230,$0230,$0230,$0230,$0240,$0240,$0240,$0240
	dc.w	$0240,$0240,$0240,$0240,$0238,$ffde,$ffd6,$0298
	dc.w	$0200,$0200,$0200,$fe68,$0250,$0250,$0250,$0250
	dc.w	$0250,$0250,$0250,$0250,$0250,$0230,$0200,$0250
	dc.w	$0250,$0250,$025a,$025a,$025a,$02a4,$02be,$02be
	dc.w	$02c8,$0358,$029e,$04d4,$029e,$04d4,$04d4,$04ea
	dc.w	$0200,$029e,$036c,$050c,$0526,$0200,$ffce,$0200
	dc.w	$0200,$0200,$0200,$0200,$0200,$0200,$0250,$02da
	dc.w	$0358,$0358,$0358,$02c8,$027e,$02d4,$024a,$0200
	dc.w	$0290,$0200,$0200,$0212,$03b0,$02be,$0366,$0582
	dc.w	$0200,$025a,$036c,$036c,$029e,$029e,$029e,$02be
	dc.w	$02be,$02a4,$02a4,$02a4,$0200,$0200,$036c,$036c
	dc.w	$036c,$0258,$0258,$0258,$0258,$0658,$0658,$0200
	dc.w	$0200,$035e,$048e,$0488,$0200,$0452,$02c8,$029e
	dc.w	$036c,$03c0,$03d6,$0544,$0366,$025a,$02ae,$05a0
	dc.w	$05a4,$05a8,$0200,$0200,$0306,$030c,$0312,$0318
	dc.w	$033c,$032a,$0330,$0336,$031e,$0324,$0342,$0200
	dc.w	$035e,$0200,$0200,$021a,$0604,$0200,$06d0,$06d0
	dc.w	$03f0,$0200,$0200,$0200,$0290,$0290,$0260,$0200
	dc.w	$0200,$0352,$0200,$0200,$0200,$0200,$0200,$0200
	dc.w	$0200,$025a,$025a,$03ec,$03ec,$035e,$0200,$0630
	dc.w	$02de,$02e8,$02f0,$02f4,$02e2,$02de,$0358,$0358
	dc.w	$0448,$0200,$035e,$0260,$0200,$0200,$0200,$0200
	dc.w	$0200,$0200,$0200,$0200,$0200,$0200,$0200,$0200
	dc.w	$0200,$0200,$0200,$0200,$0200,$0200,$0200,$03a4
	dc.w	$03a6,$03a4,$03a6,$03a4,$03a6,$03a4,$0562,$03a6
	dc.w	$037c,$0376,$0390,$039a,$0414,$040c,$0402,$03f8
	dc.w	$0200,$0200,$0200,$0200,$0200,$0200,$0200,$0200
	dc.w	$037c,$0376,$0390,$039a,$0414,$040c,$0402,$03f8
	dc.w	$0200,$0200,$0200,$0200,$0200,$0200,$0200,$0200
	dc.w	$6100,$2604                     ; tokens that cannot appear in an expression: fatal '* FN Error *'
	dc.b	'* FN Error *',0
	dc.b	$00

;------------------------------------------------------------------------------
; Binary float operator ($5,$6,$7,$8 +,-,*,/; $9 ^; $a MOD; $b DIV; $5b \): $fff6 pops the left
; operand, then routine d7 (the token).
;------------------------------------------------------------------------------
emit_float_operator:
	move.w	#$fff6,(a0)+                    ; IR $fff6: pop float
	move.w	d7,(a0)+                        ; the operator
	rts
	move.w	#$26,d7                         ; FIX( compiles as TRUNC( ($26)
	bra.s	parse_float_function
	move.w	#$ffff,(a0)+                    ; AND OR XOR IMP EQV: right operand to integer ...
	move.w	#$fff5,(a0)+                    ; ... pop the left integer ...
	move.w	d7,(a0)+                        ; ... the operator ...
	move.w	#$fffe,(a0)+                    ; ... integer result to float
	rts
	bsr.s	emit_float_operator             ; numeric compares: pop, compare ...
	move.w	#$fffc,(a0)+                    ; IR $fffc: boolean result to float
	rts

;------------------------------------------------------------------------------
; String operator: $fff4 pops the left string, then routine d7 (string + = token $1c).
;------------------------------------------------------------------------------
emit_string_operator:
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
	move.w	d7,(a0)+                        ; the operator
	rts
	bsr.s	emit_string_operator            ; string compares ($14-$1b): pop, compare, boolean to float
	move.w	#$fffc,(a0)+                    ; IR $fffc: boolean to float
	moveq	#-1,d6                          ; d6 = -1 here, as the code is
	rts
	st	expr_has_side_effects           ; RANDOM(: side effect

;------------------------------------------------------------------------------
; Float function of one argument (SGN( INT( ... SQR(): expression, then routine d7.
;------------------------------------------------------------------------------
parse_float_function:
	bsr.w	parse_expression                ; expression
	move.w	d7,(a0)+
	rts
	addq.l	#1,a5                           ; INP( EOF( LOF( LOC(: skip '#'

;------------------------------------------------------------------------------
; Integer function (PEEK( DPEEK( LPEEK( INP( DFREE( INP?( OUT?(): side-effect flag, integer
; argument, routine d7, integer result to float.
;------------------------------------------------------------------------------
parse_int_function:
	st	expr_has_side_effects
	bsr.s	parse_int_expression            ; integer expression
	move.w	d7,(a0)+                        ; the routine
	move.w	#$fffe,(a0)+                    ; IR $fffe: integer to float
	rts

;------------------------------------------------------------------------------
; Integer expression: parse_expression then $ffff (float to integer).
;------------------------------------------------------------------------------
parse_int_expression:
	bsr.w	parse_expression                ; expression
	move.w	#$ffff,(a0)+                    ; IR $ffff: float to integer
	rts

;------------------------------------------------------------------------------
; Condition: parse_expression then $fffd (float to boolean).
;------------------------------------------------------------------------------
parse_bool_expression:
	bsr.w	parse_expression                ; expression
	move.w	#$fffd,(a0)+                    ; IR $fffd: float to boolean
	rts

;------------------------------------------------------------------------------
; RND(x): the argument's IR is dropped (pea/movea of a0), then routine d7; $25be FRE( POS(
; LPOS( do the same and add $fffe.
;------------------------------------------------------------------------------
parse_rnd_function:
	st	expr_has_side_effects
	pea	(a0)                            ; the argument is parsed ...
	bsr.w	parse_expression                ; expression
	movea.l	(sp)+,a0                        ; ... and its IR dropped
	move.w	d7,(a0)+                        ; the routine
	rts
	bsr.s	parse_rnd_function
	move.w	#$fffe,(a0)+                    ; IR $fffe: integer to float
	rts
	bsr.s	parse_int_function              ; NOT: integer operand of the whole rest, routine $1f
	subq.l	#1,a5                           ; re-read the terminator
	rts
	bsr.s	parse_function_argument         ; LEFT$( RIGHT$( STR$( MKS$( ...: d6 = -1, a string result
	moveq	#-1,d6
	rts

;------------------------------------------------------------------------------
; Function of one expression: expression, routine d7, d6 = 0 (VAL( CVS( CVF( CVD().
;------------------------------------------------------------------------------
parse_function_argument:
	bsr.w	parse_expression                ; expression
	move.w	d7,(a0)+                        ; the routine
	moveq	#0,d6                           ; d6 = 0: numeric result
	rts
	st	expr_has_side_effects           ; EXIST(: side effect, boolean result to float
	bsr.s	parse_function_argument
	move.w	#$fffc,(a0)+                    ; IR $fffc: boolean to float
	moveq	#0,d6                           ; numeric result
	rts
	bsr.s	parse_function_argument         ; LEN( ASC( VAL?( CVI( CVL(: integer result to float
	move.w	#$fffe,(a0)+                    ; IR $fffe: integer to float
	moveq	#0,d6                           ; numeric result
	rts
	st	expr_has_side_effects           ; TIME$ INKEY$ DATE$: no argument, string result
	move.w	d7,(a0)+                        ; the routine
	moveq	#-1,d6                          ; string result
	rts
	st	expr_has_side_effects           ; RND: side effect
	move.w	d7,(a0)+                        ; PI: just the routine
	rts

;------------------------------------------------------------------------------
; Constants as float literals ($ffef + 6 bytes): $260c 0 / FALSE, $2610 TRUE (-1), $2616 1,
; $261e 2, $2622 3.
;------------------------------------------------------------------------------
	moveq	#0,d1                           ; d1 = 0: exponent 0 is 0.0 (d0 left as it is)
	bra.s	.emit_constant
	moveq	#1,d0                           ; -1.0: sign bit, exponent $200
	ror.l	#1,d0                           ; $80000000: the sign bit
	bra.s	.float_power_zero
	moveq	#0,d0                           ; 1.0: no fraction bits
.float_power_zero:
	move.w	#$200,d1                        ; exponent $200
	bra.s	.emit_constant
	moveq	#0,d0                           ; 2.0: no fraction bits
	bra.s	.exponent_one
	moveq	#1,d0                           ; 3.0: fraction .1, exponent $201
	ror.l	#2,d0
.exponent_one:
	move.w	#$201,d1                        ; exponent $201
.emit_constant:
	move.w	#$ffef,(a0)+                    ; IR $ffef: float constant
	move.l	d0,(a0)+                        ; sign and fraction
	move.w	d1,(a0)+                        ; fraction low bits and exponent
	rts

;------------------------------------------------------------------------------
; System arrays INTIN, INTOUT, PTSIN, PTSOUT, ADDRIN, ADDROUT, GB, GINTIN, GINTOUT, CONTRL,
; GCONTRL, WINDTAB: IR $ffae with the array's offset in the runtime variables, as a float.
;------------------------------------------------------------------------------
	move.w	#$11aa,d0                       ; runtime variable offset $11aa
	bra.s	.emit_address
	move.w	#$12aa,d0                       ; runtime variable offset $12aa
	bra.s	.emit_address
	move.w	#$13aa,d0                       ; runtime variable offset $13aa
	bra.s	.emit_address
	move.w	#$15aa,d0                       ; runtime variable offset $15aa
	bra.s	.emit_address
	move.w	#$1142,d0                       ; runtime variable offset $1142
	bra.s	.emit_address
	move.w	#$116a,d0                       ; runtime variable offset $116a
	bra.s	.emit_address
	move.w	#$2c,d0                         ; runtime variable offset $2c
	bra.s	.emit_address
	move.w	#$10f2,d0                       ; runtime variable offset $10f2
	bra.s	.emit_address
	move.w	#$111a,d0                       ; runtime variable offset $111a
	bra.s	.emit_address
	move.w	#$1192,d0                       ; runtime variable offset $1192
	bra.s	.emit_address
	move.w	#$10e6,d0                       ; runtime variable offset $10e6
.emit_address:
	move.w	#$ffae,(a0)+                    ; IR $ffae: runtime address constant
	move.w	d0,(a0)+                        ; the offset
	move.w	#$fffe,(a0)+                    ; IR $fffe: integer to float
	rts
	move.w	#$af2,d0                        ; runtime variable offset $af2
	bra.s	.emit_address
	st	expr_has_side_effects           ; TIMER MOUSEX MOUSEY MOUSEK CRSLIN CRSCOL: side effect
	move.w	d7,(a0)+                        ; BASEPAGE ERR HIMEM VDIBASE: routine, integer result to float
	move.w	#$fffe,(a0)+                    ; IR $fffe: integer to float
	rts
	st	expr_has_side_effects           ; INPUT$( DIR$(: side effect
	bsr.w	parse_int_expression            ; CHR$( MKI$( MKL$( HEX$( OCT$( BIN$( SPACE$(: integer argument
	move.w	d7,(a0)+
	moveq	#-1,d6
	rts

;------------------------------------------------------------------------------
; Variable reads: $26a4 string ($fff2, d6 = -1), $26aa float ($fff3), $26be integer ($fff1 then
; $fffe), $26c8 boolean ($fff0 then $fffc).
;------------------------------------------------------------------------------
	moveq	#-14,d0                         ; IR $fff2: read string variable
	moveq	#-1,d6                          ; string result
	bra.s	emit_variable_read
	moveq	#-13,d0                         ; IR $fff3: read float variable

;------------------------------------------------------------------------------
; Emits IR d0 and the variable index that follows (two bytes when token bit 4, in d7, is set).
;------------------------------------------------------------------------------
emit_variable_read:
	move.w	d0,(a0)+
	moveq	#0,d0                           ; index high byte 0
	lsr.b	#5,d7                           ; carry = bit 4: two-byte index
	bcc.s	.index_low
	move.b	(a5)+,d0                        ; high byte of the index
	asl.w	#8,d0
.index_low:
	move.b	(a5)+,d0                        ; low byte
	move.w	d0,(a0)+                        ; the index
	rts
	moveq	#-15,d0                         ; IR $fff1: read integer variable
	bsr.s	emit_variable_read
	move.w	#$fffe,(a0)+                    ; IR $fffe: integer to float
	rts
	moveq	#-16,d0                         ; IR $fff0: read boolean variable
	bsr.s	emit_variable_read
	move.w	#$fffc,(a0)+                    ; IR $fffc: boolean to float
	rts
	addq.l	#1,a5                           ; $d7 $d9 $db $dd: skip the pad byte
	move.w	#$ffef,(a0)+                    ; IR $ffef: the 6-byte number
	move.l	(a5)+,(a0)+                     ; sign and fraction
	move.w	(a5)+,(a0)+                     ; fraction low bits and exponent
	rts
	st	expr_has_side_effects           ; POINT(: side effect
	bsr.s	parse_two_int_function
	move.w	#$fffe,(a0)+                    ; IR $fffe: integer to float
	moveq	#0,d6
	rts

;------------------------------------------------------------------------------
; Two integer arguments, routine d7, string result (STRING$(n,c), POINT( via $26de).
;------------------------------------------------------------------------------
parse_two_int_function:
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	d7,(a0)+                        ; the routine
	moveq	#-1,d6                          ; string result
	rts
	bsr.w	parse_int_expression            ; STRING$(n,a$): integer, string, routine
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_expression                ; expression
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	d7,(a0)+                        ; the routine
	moveq	#-1,d6                          ; string result
	rts
	bsr.w	parse_expression                ; EVEN( ODD(; $271e FATAL: boolean result to float
	move.w	d7,(a0)+
	move.w	#$fffc,(a0)+                    ; IR $fffc: boolean to float
	rts

;------------------------------------------------------------------------------
; Array element reads: $2726 boolean ($ffeb, $fffc), $2730 integer ($ffec, $fffe), $273a string
; ($ffed, d6 = -1), $2742 float ($ffee).
;------------------------------------------------------------------------------
	moveq	#-21,d1                         ; IR $ffeb: read boolean element
	bsr.s	parse_array_element
	move.w	#$fffc,(a0)+                    ; IR $fffc: boolean to float
	rts
	moveq	#-20,d1                         ; IR $ffec: read integer element
	bsr.s	parse_array_element
	move.w	#$fffe,(a0)+                    ; IR $fffe: integer to float
	rts
	moveq	#-19,d1                         ; IR $ffed: read string element
	bsr.s	parse_array_element
	moveq	#-1,d6                          ; string result
	rts
	moveq	#-18,d1                         ; IR $ffee: read float element

;------------------------------------------------------------------------------
; Array element: index from the tokens (two bytes when token bit 4 is set), then
; parse_element_subscripts: IR d1, index, subscript count d7.
;------------------------------------------------------------------------------
parse_array_element:
	moveq	#0,d0
	lsr.b	#5,d7                           ; carry = token bit 4: two-byte index
	bcc.s	.index_low
	move.b	(a5)+,d0                        ; high byte of the index
	asl.w	#8,d0
.index_low:
	move.b	(a5)+,d0                        ; low byte

;------------------------------------------------------------------------------
; Subscripts up to ')', each an integer pushed with $fff8 (the last push dropped), then IR d1,
; d0, d7.
;------------------------------------------------------------------------------
parse_element_subscripts:
	move.w	d1,-(sp)                        ; keep the IR word
	move.w	d0,-(sp)                        ; keep the index
	moveq	#0,d7                           ; no subscripts yet
.next_subscript:
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	addq.w	#1,d7                           ; count it
	cmpi.b	#$20,-$1(a5)                    ; ')' reached?
	bne.s	.next_subscript
	subq.l	#2,a0                           ; drop the last push
	move.w	(sp)+,d0
	move.w	(sp)+,d1
	move.w	d1,(a0)+                        ; IR word
	move.w	d0,(a0)+                        ; index
	move.w	d7,(a0)+                        ; subscript count
	rts

;------------------------------------------------------------------------------
; '*' variable: address of the variable ($ffea - type), as a float.
;------------------------------------------------------------------------------
parse_variable_pointer:
	moveq	#-22,d2                         ; $ffea - type: variable address
	bsr.s	parse_array_reference
	move.w	#$fffe,(a0)+                    ; IR $fffe: integer to float
	rts
	bsr.s	parse_array_name                ; DIM?(: routine $94
	move.w	#$94,(a0)+                      ; routine $94
	addq.l	#1,a5                           ; skip ')'
	move.w	#$fffe,(a0)+                    ; IR $fffe: integer to float
	rts

;------------------------------------------------------------------------------
; Array name (a() in ERASE, ARRAYFILL ...): IR $ff9f - type and the index.
;------------------------------------------------------------------------------
parse_array_name:
	move.w	#$ff9f,d2

;------------------------------------------------------------------------------
; IR d2 - type and the variable index; token bit 2 (array) skips the '(' after it.
;------------------------------------------------------------------------------
parse_array_reference:
	moveq	#0,d0
	move.b	(a5)+,d1                        ; d1 = variable token
	move.b	(a5)+,d0                        ; d0 = index, low byte
	btst	#$4,d1                          ; bit 4: two-byte index
	beq.s	.index_done
	asl.w	#8,d0                           ; high byte of the index
	move.b	(a5)+,d0                        ; low byte
.index_done:
	btst	#$2,d1                          ; bit 2: an array
	beq.s	.emit
	addq.l	#1,a5                           ; skip a token
.emit:
	andi.w	#$7,d1                          ; type
	sub.w	d1,d2                           ; IR word minus the type
	move.w	d2,(a0)+                        ; IR word
	move.w	d0,(a0)+                        ; index
	rts
	bsr.s	parse_variable_pointer          ; ARRPTR(: address, skip ')'
	addq.l	#1,a5                           ; skip ')'
	rts

;------------------------------------------------------------------------------
; VARPTR(: variable address, as a float, then skips the next token (')' or ',').
;------------------------------------------------------------------------------
parse_varptr:
	bsr.s	parse_variable_reference
	move.w	#$fffe,(a0)+                    ; IR $fffe: integer to float
	addq.l	#1,a5                           ; skip ')' or ','
	rts

;------------------------------------------------------------------------------
; Address of a variable: $ffe2 string, $ffea - type simple, $ffe5 - type array element with
; its subscripts.
;------------------------------------------------------------------------------
parse_variable_reference:
	moveq	#0,d0
	move.b	(a5)+,d1                        ; d1 = variable token
	move.b	(a5)+,d0                        ; d0 = index, low byte
	btst	#$4,d1                          ; bit 4: two-byte index
	beq.s	.index_done
	asl.w	#8,d0                           ; high byte of the index
	move.b	(a5)+,d0                        ; low byte
.index_done:
	andi.w	#$7,d1                          ; type
	btst	#$2,d1                          ; bit 2: an array element
	bne.s	.element
	cmpi.b	#$1,d1                          ; type 1: string
	bne.s	.simple
	move.w	#$ffe2,(a0)+                    ; IR $ffe2: string variable address
	move.w	d0,(a0)+                        ; index
	rts
.simple:
	moveq	#-22,d2                         ; $ffea ...
	sub.w	d1,d2                           ; ... minus the type
	move.w	d2,(a0)+                        ; IR word
	move.w	d0,(a0)+                        ; index
	rts
.element:
	moveq	#-27,d2                         ; $ffe5 ...
	sub.w	d1,d2                           ; ... minus the type
	move.w	d2,d1                           ; d1 = IR word for the element
	bra.w	parse_element_subscripts

;------------------------------------------------------------------------------
; String functions with arguments: $2802 LEFT$( RIGHT$( MID$(a$,n), $2818 MID$(a$,n,m),
; $283a INSTR(a$,b$), $2854 INSTR(n,a$,b$), $2872 INSTR(a$,b$,n).
;------------------------------------------------------------------------------
	bsr.w	parse_expression                ; expression
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
	move.w	d7,(a0)+                        ; the routine
	moveq	#-1,d6                          ; string result
	rts
	bsr.w	parse_expression                ; expression
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
	move.w	d7,(a0)+                        ; the routine
	moveq	#-1,d6                          ; string result
	rts
	bsr.w	parse_expression                ; expression
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	bsr.w	parse_expression                ; expression
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
.emit_int_result:
	move.w	d7,(a0)+                        ; the routine
	move.w	#$fffe,(a0)+                    ; IR $fffe: integer to float
	moveq	#0,d6                           ; numeric result
	rts
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bsr.w	parse_expression                ; expression
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	bsr.w	parse_expression                ; expression
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	bra.s	.emit_int_result
	bsr.w	parse_expression                ; expression
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	bsr.w	parse_expression                ; expression
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$ffd9,(a0)+                    ; IR $ffd9: pop address
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
	bra.s	.emit_int_result

;------------------------------------------------------------------------------
; String literal: IR $ffd7, length word, the characters, padded to an even address; d6 = -1.
;------------------------------------------------------------------------------
	move.w	#$ffd7,(a0)+                    ; IR $ffd7: string literal
	moveq	#0,d0
	move.b	(a5)+,d0                        ; d0 = length
	move.w	d0,(a0)+                        ; length word
	bra.s	.copy_test
.copy_char:
	move.b	(a5)+,(a0)+                     ; copy a character
.copy_test:
	dbra	d0,.copy_char
	move.l	a0,d0                           ; round a0 up ...
	addq.l	#1,d0
	andi.b	#$fe,d0                         ; ... to an even address
	movea.l	d0,a0
	moveq	#-1,d6                          ; string result
	rts
	st	expr_has_side_effects           ; INPUT$(n,#c): side effect
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	addq.l	#1,a5                           ; skip a token
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$fff5,(a0)+                    ; IR $fff5: pop integer
	move.w	d7,(a0)+                        ; the routine
	moveq	#-1,d6                          ; string result
	rts

;------------------------------------------------------------------------------
; BIOS( XBIOS( GEMDOS( ($ffd1/$ffd0/$ffcf): arguments with L: ($8a, long) or W: ($8b) / plain
; (word), pushed in reverse; then the IR, the argument byte count, $fffe.
;------------------------------------------------------------------------------
	moveq	#-47,d0                         ; IR $ffd1: BIOS
	bra.s	.trap_call
	moveq	#-48,d0                         ; IR $ffd0: XBIOS
	bra.s	.trap_call
	moveq	#-49,d0                         ; IR $ffcf: GEMDOS
.trap_call:
	st	expr_has_side_effects
	move.w	d0,-(sp)                        ; keep the trap IR
	clr.w	-(sp)                           ; argument byte count
	movea.l	sp,a3                           ; a3 = its address
.next_arg:
	cmpi.b	#$8a,(a5)+                      ; $8a = L:
	seq	d7                              ; d7 = long argument
	beq.s	.check_end
	cmpi.b	#$8b,-(a5)                      ; $8b = W:
	bne.s	.check_end
	addq.l	#1,a5                           ; skip a token
.check_end:
	cmpi.b	#$20,-$1(a5)                    ; ')' ends the list
	beq.s	.restore_args
	pea	(a0)                            ; keep the IR start
	bsr.w	parse_int_expression            ; integer expression
	tst.b	d7                              ; long?
	beq.s	.word_arg
	move.w	#$fff8,(a0)+                    ; long argument
	addq.w	#4,(a3)                         ; 4 bytes
	bra.s	.hold_arg
.word_arg:
	move.w	#$ffd8,(a0)+                    ; word argument
	addq.w	#2,(a3)                         ; 2 bytes
.hold_arg:
	movea.l	(sp)+,a1                        ; a1 = start of this argument's IR
.hold_word:
	move.w	-(a0),-(sp)                     ; hold it on the stack (reverses the order)
	cmpa.l	a0,a1
	bne.s	.hold_word                      ; until all of it is held
	bra.s	.next_arg
.restore_args:
	cmpa.l	sp,a3                           ; until the count's slot
	beq.s	.emit_trap
	move.w	(sp)+,(a0)+                     ; restore the held IR
	bra.s	.restore_args
.emit_trap:
	move.w	(sp)+,d0                        ; d0 = byte count
	move.w	(sp)+,(a0)+                     ; the trap IR
	move.w	d0,(a0)+                        ; byte count
	move.w	#$fffe,(a0)+                    ; IR $fffe: integer to float
	rts
	st	expr_has_side_effects           ; C:addr(args): routine token+1, address, arguments as longs
	move.w	d7,-(sp)                        ; keep the token
	addq.w	#1,d7                           ; routine token+1
	move.w	d7,(a0)+                        ; that routine
	clr.w	-(sp)                           ; argument count
	movea.l	sp,a3                           ; a3 = its address
	pea	(a0)                            ; keep the IR start
	bsr.w	parse_int_expression            ; integer expression
	st	d7                              ; d7 set: arguments are longs
	cmpi.b	#$20,(a5)                       ; ')' reached?
	bne.s	.hold_arg                       ; arguments: hold the address and go on as for a trap call
	addq.l	#6,sp                           ; drop the IR start and the count
	addq.l	#1,a5                           ; skip ')'
	move.w	(sp)+,(a0)+                     ; the token
	clr.w	(a0)+                           ; argument count 0
	move.w	#$fffe,(a0)+                    ; IR $fffe: integer to float
	rts

;------------------------------------------------------------------------------
; EXEC(mode,file$,cmd$,env$) and the EXEC command: integer, three strings, routine d7.
;------------------------------------------------------------------------------
parse_exec:
	st	expr_has_side_effects
	bsr.w	parse_int_expression            ; integer expression
	move.w	#$ffd8,(a0)+                    ; IR $ffd8: push word argument
	bsr.w	parse_expression                ; expression
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	bsr.w	parse_expression                ; expression
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	bsr.w	parse_expression                ; expression
	move.w	d7,(a0)+                        ; the routine
	moveq	#0,d6                           ; numeric result
	rts

;------------------------------------------------------------------------------
; MIN( MAX(: numbers pairwise with $fff9/$fff6, strings with routine d7+2 and $fff7/$fff4.
;------------------------------------------------------------------------------
	bsr.w	parse_expression                ; expression
	cmpi.b	#$20,-$1(a5)                    ; ')' reached?
	beq.s	.done
	tst.b	d6                              ; d6 negative: string
	beq.s	.next_number
	addq.w	#2,d7                           ; string MIN/MAX: routine d7+2
.next_string:
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	bsr.w	parse_expression                ; expression
	move.w	#$fff4,(a0)+                    ; IR $fff4: pop string
	move.w	d7,(a0)+                        ; the routine
	cmpi.b	#$20,-$1(a5)                    ; ')' reached?
	bne.s	.next_string
.done:
	rts
.next_number:
	move.w	#$fff9,(a0)+                    ; IR $fff9: push float
	bsr.w	parse_expression                ; expression
	move.w	#$fff6,(a0)+                    ; IR $fff6: pop float
	move.w	d7,(a0)+                        ; the routine
	cmpi.b	#$20,-$1(a5)                    ; ')' reached?
	bne.s	.next_number
	rts

;------------------------------------------------------------------------------
; Runs of not.w d6 ($4646): a token stream of $46 (end) bytes; a5 is pointed here after an FN
; error so the parser unwinds. Then from $2a0e the FN / @ function call handler.
;------------------------------------------------------------------------------
	not.w	d6                              ; $4646: two $46 end tokens

;------------------------------------------------------------------------------
; Fake token stream: each not.w d6 is $4646, two $46 end tokens.
;------------------------------------------------------------------------------
end_token_stream:
	not.w	d6
	not.w	d6
	not.w	d6
	not.w	d6
	not.w	d6
	not.w	d6
	not.w	d6
	not.w	d6
	not.w	d6
	not.w	d6
	not.w	d6
	not.w	d6
	not.w	d6
	not.w	d6
	not.w	d6
	not.w	d6
	not.w	d6
	not.w	d6
	not.w	d6
	not.w	d6
	not.w	d6
	not.w	d6
	not.w	d6
	not.w	d6
	not.w	d6
	not.w	d6
	st	expr_has_side_effects           ; FN / @ call: side effect
	bsr.w	read_variable_token             ; d1 = variable token, d0 = index
	move.w	d0,-(sp)                        ; keep the index
	move.l	a0,d6                           ; keep a0
	move.l	d0,d2                           ; d2 = index
	asl.l	#4,d2                           ; 16-byte entries
	andi.w	#$1,d1                          ; odd type: FN$ (string)
	beq.s	.numeric_fn
	move.w	#$ff86,-(sp)                    ; IR $ff86: string FN call
	move.w	#$ffff,-(sp)                    ; d6 = -1 afterwards: string result
	movea.l	bss_end+$68,a0                  ; FN$ table
	bra.s	.check_entry
.numeric_fn:
	move.w	#$ff87,-(sp)                    ; IR $ff87: numeric FN call
	clr.w	-(sp)                           ; d6 = 0 afterwards: numeric result
	movea.l	bss_end+$64,a0                  ; FN table
.check_entry:
	adda.l	d2,a0
	tst.l	(a0)                            ; defined?
	beq.s	.undefined
	tst.b	(a0)                            ; has parameters?
	bne.s	.with_params
	cmpi.b	#$9d,(a5)                       ; $9d = '(' with no parameters: error 45
	beq.s	.unexpected_args
	movea.l	d6,a0                           ; restore a0
.emit_fn:
	move.w	(sp)+,d6                        ; d6 = result type
	move.w	(sp)+,(a0)+                     ; call IR word
	move.w	(sp)+,(a0)+                     ; FN index
	rts
.undefined:
	moveq	#19,d0                          ; error 19: undefined
	bra.s	.emit_error
.unexpected_args:
	moveq	#45,d0                          ; error 45: arguments for an FN without parameters
.emit_error:
	lea	bss_end+$3d0,a0                 ; rewrite the line as ERROR d0
	move.w	#$ffa9,(a0)+                    ; IR $ffa9
	move.w	#$ffa9,(a0)+                    ; IR $ffa9
	move.w	#$ffce,(a0)+                    ; IR $ffce: integer constant
	move.l	d0,(a0)+                        ; the error number
	move.w	#$10f,(a0)+                     ; routine $10f
	lea	end_token_stream(pc),a5         ; a5 = $46 run: end the parse
	move.w	(sp)+,d6                        ; d6 = result type
	tst.l	(sp)+                           ; drop the IR word and the index
	rts
.missing_args:
	moveq	#42,d0                          ; error 42: arguments missing
	bra.s	.emit_error
.with_params:
	cmpi.b	#$9d,(a5)+                      ; '(' must follow
	bne.s	.missing_args
	moveq	#0,d7
	move.b	(a0),d7                         ; parameter count
	movem.l	4(a0),d0-d2                     ; 96 bits of 2-bit parameter types
	movea.l	d6,a0                           ; restore a0
.next_param:
	moveq	#0,d3
	add.l	d2,d2                           ; next type into d3
	addx.l	d1,d1
	addx.l	d0,d0
	addx.w	d3,d3
	add.l	d2,d2
	addx.l	d1,d1
	addx.l	d0,d0
	addx.w	d3,d3
	movem.l	d0-d2,-(sp)                     ; keep the remaining types
	tst.w	d3
	beq.s	.float_param
	subq.w	#2,d3                           ; type 1 string, type 2 integer
	bmi.s	.string_param
	beq.s	.int_param
	bsr.w	parse_expression                ; type 3: boolean
	move.w	#$fffd,(a0)+                    ; IR $fffd: float to boolean
	move.w	#$ff88,(a0)+                    ; IR $ff88: push boolean
.check_numeric:
	tst.w	d6                              ; d6 negative: string
	bpl.s	.param_done
	moveq	#46,d0                          ; error 46: string for a number
	bra.s	.error_exit
.param_done:
	movem.l	(sp)+,d0-d2
	subq.w	#1,d7                           ; one parameter fewer
	beq.s	.params_done
	cmpi.b	#$21,-$1(a5)                    ; ',' follows?
	beq.s	.next_param
	moveq	#45,d0                          ; error 45: too many arguments
.error_exit:
	movem.l	(sp)+,d1-d3                     ; drop the remaining types
	bra.w	.emit_error
.params_done:
	moveq	#42,d0                          ; error 42: too few
	cmpi.b	#$20,-$1(a5)                    ; ')' reached?
	bne.s	.error_exit
	bra.w	.emit_fn
.float_param:
	bsr.w	parse_expression                ; expression
	move.w	#$fff9,(a0)+                    ; IR $fff9: push float
	bra.s	.check_numeric
.int_param:
	bsr.w	parse_expression                ; expression
	move.w	#$ffff,(a0)+                    ; IR $ffff: float to integer
	move.w	#$fff8,(a0)+                    ; IR $fff8: push integer
	bra.s	.check_numeric
.string_param:
	bsr.w	parse_expression                ; expression
	move.w	#$fff7,(a0)+                    ; IR $fff7: push string
	tst.w	d6                              ; d6 negative: string
	bmi.s	.param_done
	moveq	#47,d0                          ; error 47: a number for a string
	bra.s	.error_exit

;------------------------------------------------------------------------------
; Constant folding: unpacked float (d0 fraction with leading 1, d1 low bits, d2 exponent and
; sign) to a 32-bit integer in d0, rounded; d4 = -1 when it does not fit.
;------------------------------------------------------------------------------
const_float_to_int:
	moveq	#0,d4                           ; fits so far
	addi.w	#$200,d1                        ; round at the first dropped bit
	bcc.s	.unbias
	addq.l	#1,d0                           ; carry into the fraction
	bcc.s	.unbias
	roxr.l	#1,d0                           ; fraction overflowed: shift back
	roxr.w	#1,d1
	addq.w	#1,d2                           ; exponent one up
.unbias:
	subi.w	#$200,d2                        ; unbias the exponent
	bmi.s	.below_one
	subi.w	#$1f,d2                         ; 31 or more: too big
	bpl.s	.too_big
	neg.w	d2                              ; shift count = 31 - exponent
	lsr.l	d2,d0                           ; integer part
	tst.l	d2                              ; sign in bit 31 of d2
	bpl.s	.done
	neg.l	d0                              ; negative
.done:
	rts
.below_one:
	moveq	#0,d0                           ; below 1: 0
	rts
.too_big:
	bne.s	.overflow                       ; exponent above 31: overflow
	tst.l	d2                              ; exponent 31: only -2^31 fits
	bpl.s	.overflow
	cmpi.l	#$80000000,d0                   ; -2^31 is the one value that fits
	bne.s	.overflow
	tst.w	d1                              ; low fraction bits left: does not fit
	bmi.s	.overflow
	rts
.overflow:
	moveq	#-1,d4                          ; does not fit
	rts

;------------------------------------------------------------------------------
; Unpacks a 6-byte GFA float (d0 high long, d1 low word): d2 = exponent (sign in bit 31),
; d1 = low fraction bits, d0 bit 31 = the implicit 1. Zero exponent: all zero.
;------------------------------------------------------------------------------
const_float_unpack:
	move.l	d0,d2                           ; sign into bit 31 of d2
	move.w	d1,d2                           ; exponent in the low word
	andi.w	#$3ff,d2                        ; 10-bit exponent
	beq.s	const_float_zero
	andi.w	#$fc00,d1                       ; fraction bits only
	bset	#$1f,d0                         ; the implicit 1
	rts

;------------------------------------------------------------------------------
; Zero result: d0 = d1 = d2 = 0.
;------------------------------------------------------------------------------
const_float_zero:
	moveq	#0,d0
	moveq	#0,d1
	moveq	#0,d2
	rts

;------------------------------------------------------------------------------
; Packs d0/d1/d2 back to a 6-byte float, rounding at bit 9 of d1.
;------------------------------------------------------------------------------
const_float_pack:
	tst.w	d2
	beq.s	const_float_zero
	addi.w	#$200,d1                        ; round
	bcc.s	.set_sign
	addq.l	#1,d0                           ; carry into the fraction
	bcc.s	.set_sign
	roxr.l	#1,d0                           ; overflowed: shift back
	roxr.w	#1,d1
	addq.w	#1,d2                           ; exponent one up
.set_sign:
	andi.w	#$3ff,d2                        ; 10-bit exponent
	andi.w	#$fc00,d1                       ; fraction bits
	or.w	d2,d1                           ; exponent into the low word
	tst.l	d2                              ; negative?
	bmi.s	.done
	bclr	#$1f,d0                         ; positive: clear the sign bit
.done:
	rts

;------------------------------------------------------------------------------
; Integer d0 to an unpacked float: normalised, d2 = exponent ($21f down).
;------------------------------------------------------------------------------
const_int_to_float:
	moveq	#0,d1
	move.l	d0,d2                           ; sign into d2
	move.w	#$21f,d2                        ; exponent for bit 31
	tst.l	d0
	bpl.s	.normalise
	neg.l	d0                              ; magnitude
	bmi.s	.done                           ; $80000000 stays as it is
.normalise:
	add.l	d0,d0                           ; shift up ...
	dbmi	d2,.normalise                   ; ... until bit 31 is set
	subq.w	#1,d2                           ; exponent correction
.done:
	rts

;------------------------------------------------------------------------------
; IR optimiser for the statement in bss_end+$b0..a0 (end marked $1234 $1234).
; First, unless expr_has_side_effects: X push X pop op (a term used twice) becomes X $ffaa op,
; and X*X -> square ($151), X+X -> double ($147), X/X -> 1, X-X -> 0. Then passes of
; optimise_ir_op over every operation until a pass changes nothing (d7).
;------------------------------------------------------------------------------
optimise_ir:
	move.l	#$12341234,(a0)                 ; end marker
	tst.b	expr_has_side_effects
	bne.w	.pass
	lea	bss_end+$b0,a1                  ; a1 = start of a candidate term
.next_start:
	cmpa.l	a0,a1
	beq.w	.pass
	movea.l	a1,a2                           ; a2 scans from it
.find_push:
	move.w	(a2)+,d0                        ; IR word; operations are negative
	bpl.s	.find_test
	cmpi.w	#$fff9,d0                       ; a float push ends the first term
	beq.s	.compare_terms
.find_test:
	cmpa.l	a2,a0                           ; end of the IR?
	bne.s	.find_push
	bra.s	.pass
.advance_start:
	addq.l	#2,a1                           ; try the next start
	bra.s	.next_start
.compare_terms:
	movea.l	a1,a3                           ; a3 = the first term
	movea.l	a2,a4                           ; a4 = after the push
.compare_loop:
	cmpi.w	#$fff6,(a3)                     ; compare the term with what follows the push
	beq.s	.compare_end
	cmpm.w	(a3)+,(a4)+
	beq.s	.compare_loop
.compare_end:
	cmpa.l	a2,a3                           ; first term matched up to the push?
	bne.s	.advance_start
	cmpi.w	#$fff6,-$2(a4)                  ; second copy ends at the pop?
	bne.s	.advance_start
	cmpi.w	#$8,(a4)                        ; 8: X/X
	beq.s	.one
	cmpi.w	#$7,(a4)                        ; 7: X*X
	beq.s	.square
	cmpi.w	#$6,(a4)                        ; 6: X+X
	beq.s	.double
	cmpi.w	#$5,(a4)                        ; 5: X-X
	beq.s	.zero
	move.w	#$ffaa,-$2(a3)                  ; IR $ffaa: reuse the value
.move_down:
	move.w	(a4)+,(a3)+                     ; close the gap
.move_test:
	cmpa.l	a0,a4
	bcs.s	.move_down
	movea.l	a3,a0                           ; new end of the IR
	bra.s	optimise_ir                     ; optimise the IR, then return
.square:
	move.w	#$151,-$2(a3)                   ; routine $151: square
.drop_op:
	addq.l	#2,a4                           ; skip the operator
	bra.s	.move_test
.double:
	move.w	#$147,-$2(a3)                   ; routine $147: times two
	bra.s	.drop_op
.one:
	movea.l	a1,a3                           ; constant 1.0
	move.w	#$ffef,(a3)+
	clr.l	(a3)+                           ; 1.0: no fraction bits ...
	move.w	#$200,(a3)+                     ; ... exponent $200
	bra.s	.drop_op
.zero:
	movea.l	a1,a3                           ; constant 0.0
	move.w	#$ffef,(a3)+
	clr.l	(a3)+                           ; 0.0: no fraction bits ...
	clr.w	(a3)+                           ; ... exponent 0
	bra.s	.drop_op
.pass:
	lea	bss_end+$b0,a1                  ; start of the IR
	moveq	#0,d7                           ; nothing changed yet
.scan:
	cmpa.l	a0,a1                           ; end of the IR?
	bcc.s	.pass_done
.scan_word:
	move.w	(a1)+,d0                        ; next word
	bpl.s	.scan                           ; operands and routine numbers: step on
	bsr.s	optimise_ir_op                  ; an operation: run its rule
	cmpa.l	a0,a1                           ; more IR?
	bcs.s	.scan_word
.pass_done:
	tst.w	d7                              ; d7 set: something changed, another pass
	bne.s	.pass
	rts

;------------------------------------------------------------------------------
; Runs the optimiser rule for the IR operation d0 (index = not d0); a1 points after it. Rules
; that rewrite set d7 = -1.
;------------------------------------------------------------------------------
optimise_ir_op:
	not.w	d0                              ; index = not d0
	add.w	d0,d0                           ; word index
	move.w	optimise_op_table(pc,d0.w),d0
	jmp	optimise_op_table(pc,d0.w)      ; jump to the rule

; Rule offsets for the operations $ffff (index 0) down to $ff84; most only step over the
; operation's operands.
optimise_op_table:
	dc.w	opt_rule_float_to_int-optimise_op_table
	dc.w	opt_rule_int_to_float-optimise_op_table
	dc.w	opt_no_change-optimise_op_table
	dc.w	opt_bool_to_float-optimise_op_table
	dc.w	opt_no_change-optimise_op_table
	dc.w	opt_no_change-optimise_op_table
	dc.w	opt_push_float-optimise_op_table
	dc.w	opt_push_int-optimise_op_table
	dc.w	opt_no_change-optimise_op_table
	dc.w	opt_no_change-optimise_op_table
	dc.w	opt_no_change-optimise_op_table
	dc.w	opt_no_change-optimise_op_table
