	dc.w	opt_error_bad_operation-optimise_op_table
	dc.w	opt_error_bad_operation-optimise_op_table

;------------------------------------------------------------------------------
; Optimiser rule for $ff85/$ff84 (decoded as data): bsr.w compile_error_fatal with the inline
; text '* Opt Err *'; these operations should never reach the optimiser.
;------------------------------------------------------------------------------
opt_error_bad_operation:
	bsr.w	compile_error_fatal             ; $ff85/$ff84: fatal '* Opt Err *'
	dc.b	'* Opt Err *',0

;------------------------------------------------------------------------------
; Optimiser rule (decoded as data): addq.l #2,a1 steps over one operand word, then the rts at
; opt_return_unchanged.
;------------------------------------------------------------------------------
opt_step_over_word:
	addq.l	#2,a1                           ; $5489 = addq.l #2,a1: step over a word, then the rts below

;------------------------------------------------------------------------------
; Optimiser code decoded as data: rts (no change), then the integer forms used after $fffe
; (integer to float) by opt_rule_int_to_float: a float function on a converted integer becomes the
; integer routine followed by $fffe ($147 -> $149 and $4e -> $129 only when $ffff follows,
; $28 -> $12b, $1e -> $12a), d7 = -1.
;------------------------------------------------------------------------------
opt_return_unchanged:
	rts                                     ; rts | after $147: $149 | rts | $4e: $129 | cmpi.w #$ffff,2(a1)

;------------------------------------------------------------------------------
; After an int-to-float conversion ($fffe): the float routine is replaced by its integer version, routine $149.
;------------------------------------------------------------------------------
opt_use_int_routine_149:
	move.w	#$149,d0
	bra.s	opt_check_int_routine_store

opt_rule_keep:
	rts

;------------------------------------------------------------------------------
; After $fffe: the float routine is replaced by routine $129.
;------------------------------------------------------------------------------
opt_use_int_routine_129:
	move.w	#$129,d0

opt_check_int_routine_store:
	cmpi.w	#$ffff,2(a1)
	beq.s	opt_put_int_routine
	rts

;------------------------------------------------------------------------------
; After $fffe: the float routine is replaced by routine $12b.
;------------------------------------------------------------------------------
opt_use_int_routine_12b:
	move.w	#$12b,d0

;------------------------------------------------------------------------------
; Writes the integer routine d0 over the float one and marks the IR changed ($fffe, d7 = -1).
;------------------------------------------------------------------------------
opt_put_int_routine:
	move.w	d0,-$2(a1)
	move.w	#$fffe,(a1)                     ; move.w #$fffe,(a1) / moveq #-1,d7 / rts | $1e: $12a, bra.s back
	moveq	#-1,d7
	rts

;------------------------------------------------------------------------------
; After $fffe: the float routine is replaced by routine $12a.
;------------------------------------------------------------------------------
opt_use_int_routine_12a:
	move.w	#$12a,d0
	bra.s	opt_put_int_routine

;------------------------------------------------------------------------------
; Optimiser rule for $ffff (float to integer), decoded as data: $ffff $fffe cancel
; (ir_drop_previous_pair); before $ffd2 (discard) the $ffff goes (ir_drop_previous_word).
;------------------------------------------------------------------------------
opt_rule_float_to_int:
	cmpi.w	#$fffe,(a1)                     ; cmpi.w #$fffe,(a1): drop both | cmpi.w #$ffd2,(a1): drop $ffff | rts
	beq.s	ir_drop_previous_pair
	cmpi.w	#$ffd2,(a1)                     ; $ffd2 (VOID): no conversion needed
	beq.s	ir_drop_previous_word
	rts

;------------------------------------------------------------------------------
; Optimiser rule for $fffe (integer to float), decoded as data: before $120 (print a number) it
; becomes print integer $156; $fffe $ffff cancel; before $ffd2 it goes; $fffe $fffd becomes
; $fffb; before $ffcd see opt_int_to_float_const_op; before $fff9 the rule at $339a (next
; range); before $4e/$1e/$28/$147 the integer forms in opt_return_unchanged.
;------------------------------------------------------------------------------
opt_rule_int_to_float:
	cmpi.w	#$120,(a1)                      ; cmpi.w #$120,(a1): print integer $156, drop $fffe | cmpi.w #$ffff,(a1)
	bne.s	.to_float_next
	move.w	#$156,(a1)
	bra.s	ir_drop_previous_word
.to_float_next:
	cmpi.w	#$ffff,(a1)                     ; $fffe $ffff: both go
	beq.s	ir_drop_previous_pair           ; beq: drop both | $ffd2: drop $fffe | $fffd: becomes $fffb | cmpi.w
	cmpi.w	#$ffd2,(a1)
	beq.s	ir_drop_previous_word
	cmpi.w	#$fffd,(a1)                     ; $fffe $fffd: integer to boolean ($fffb)
	beq.s	.to_bool
	cmpi.w	#$ffcd,(a1)                     ; $ffcd: float constant operation
	beq.w	opt_int_to_float_const_op
	cmpi.w	#$fff9,(a1)                     ; $fff9: float push
	beq.w	opt_int_to_float_push
	cmpi.w	#$4e,(a1)                       ; SQR(
	beq.s	opt_use_int_routine_129
	cmpi.w	#$1e,(a1)                       ; negate
	beq.s	opt_use_int_routine_12a
	cmpi.w	#$28,(a1)                       ; ABS(
	beq.s	opt_use_int_routine_12b
	cmpi.w	#$147,(a1)                      ; $147: $149 | $151: no change | rts | move.w #$fffb,-2(a1) ...
	beq.s	opt_use_int_routine_149
	cmpi.w	#$151,(a1)
	beq.s	opt_rule_keep
	rts
.to_bool:
	move.w	#$fffb,-$2(a1)
	bra.s	ir_drop_word

;------------------------------------------------------------------------------
; Removes the IR word before a1.
;------------------------------------------------------------------------------
ir_drop_previous_word:
	subq.l	#2,a1

;------------------------------------------------------------------------------
; Removes the IR word at a1.
;------------------------------------------------------------------------------
ir_drop_word:
	moveq	#2,d0
	bra.s	ir_drop_bytes

;------------------------------------------------------------------------------
; Removes the IR word before a1 and the one at it.
;------------------------------------------------------------------------------
ir_drop_previous_pair:
	subq.l	#2,a1

;------------------------------------------------------------------------------
; Removes 4 bytes of IR at a1.
;------------------------------------------------------------------------------
ir_drop_pair:
	moveq	#4,d0

;------------------------------------------------------------------------------
; Removes d0 bytes of IR at a1 (moving the rest and the end marker down) and sets d7 = -1.
;------------------------------------------------------------------------------
ir_drop_bytes:
	pea	(a1)                            ; keep a1
	moveq	#-1,d7                          ; d7 = -1: something changed
	suba.l	d0,a0                           ; the IR end moves down
	lea	0(a1,d0.l),a3                   ; a3 = first byte kept
	move.l	a0,d0                           ; d0 = words to move
	sub.l	a1,d0
	lsr.w	#1,d0
	bra.s	.move_test
.move_down:
	move.w	(a3)+,(a1)+                     ; move a word down
.move_test:
	dbra	d0,.move_down
	move.l	(a3),(a1)                       ; the $1234 end marker too
	movea.l	(sp)+,a1                        ; restore a1

;------------------------------------------------------------------------------
; No change.
;------------------------------------------------------------------------------
opt_float_const_done:
	rts

;------------------------------------------------------------------------------
; After a float constant ($ffef): $ffff folds it to an integer constant ($ffce); a push whose
; operand ends in a pop becomes a constant operation ($ffcd); negate flips its sign.
;------------------------------------------------------------------------------
opt_float_const:
	addq.l	#6,a1                           ; past the 6 bytes
	cmpi.w	#$ffff,(a1)                     ; $ffff: float to integer
	beq.s	.fold_to_int
	cmpi.w	#$fff9,(a1)                     ; $fff9: push float
	beq.s	.push_const
	cmpi.w	#$ffcd,(a1)                     ; $ffcd: constant operation
	beq.w	opt_float_const_then_op
	cmpi.w	#$ffcb,(a1)                     ; $ffcb: float-variable operation
	beq.w	opt_float_const_then_var_op
	cmpi.w	#$1e,(a1)                       ; $1e: negate
	bne.s	opt_float_const_done
	bchg	#$7,-$6(a1)                     ; negate: flip the sign bit
	bra.s	ir_drop_word                    ; drop the negate
.fold_to_int:
	move.w	-(a1),d1                        ; d1 = fraction low bits and exponent
	move.l	-(a1),d0                        ; d0 = sign and fraction
	bsr.w	const_float_unpack
	bsr.w	const_float_to_int              ; to an integer
	tst.w	d4                              ; does not fit?
	bmi.s	.fold_overflow
	move.w	#$ffce,-$2(a1)                  ; IR $ffce: integer constant
	move.l	d0,(a1)+                        ; the integer
	bra.s	ir_drop_pair                    ; drop the $ffff and the spare word
.fold_overflow:
	bsr.w	compile_error_fatal             ; fatal '* Opt Err 2 *'
	dc.b	'* Opt Err 2 *',0
.push_const:
	bsr.w	ir_find_operand_end
	cmpi.w	#$fff6,-(a2)                    ; the operand ends with a float pop?
	bne.s	opt_fold_done
	move.l	-(a1),-(sp)                     ; last 4 bytes of the constant
	move.w	-(a1),-(sp)                     ; and its first word
	subq.w	#2,a1                           ; back to the $ffef
	suba.w	#$c,a2                          ; end of the move
.move_down:
	move.w	$a(a1),(a1)+                    ; move the operand's IR down over the constant
	cmpa.l	a1,a2                           ; until the pop is reached
	bcc.s	.move_down
	move.w	#$ffcd,(a1)+                    ; IR $ffcd: operation with a float constant
	move.w	(sp)+,(a1)+                     ; the constant again, first word ...
	move.l	(sp)+,(a1)+                     ; ... and the rest
	bra.w	ir_drop_pair                    ; drop 4 bytes after it

;------------------------------------------------------------------------------
; Steps over a word, no change.
;------------------------------------------------------------------------------
opt_float_const_op_skip:
	addq.l	#2,a1

;------------------------------------------------------------------------------
; No change.
;------------------------------------------------------------------------------
opt_float_const_op_done:
	rts

;------------------------------------------------------------------------------
; $ffcd with a power of two (fraction zero): * or reciprocal by 1 goes, by 2 becomes $147, other
; powers $ffab (exponent add).
;------------------------------------------------------------------------------
opt_float_const_op:
	tst.l	(a1)+                           ; high fraction bits zero?
	bne.s	opt_float_const_op_skip
	move.w	(a1),d0                         ; exponent word
	andi.w	#$3ff,d0                        ; exponent bits only
	cmp.w	(a1)+,d0                        ; low fraction bits zero too?
	bne.s	opt_float_const_op_done
	cmpi.w	#$180,d0                        ; power far below 1: left alone
	bls.s	opt_float_const_op_done
	cmpi.w	#$280,d0                        ; power far above 1: left alone
	bcc.s	opt_float_const_op_done
	subi.w	#$200,d0                        ; d0 = the power of two
	cmpi.w	#$7,(a1)                        ; 7 = *
	beq.s	.power_of_two
	neg.b	d0                              ; the reverse divide uses the negative power
	cmpi.w	#$11b,(a1)                      ; $11b: divide reversed
	bne.s	opt_float_const_op_done
.power_of_two:
	ext.w	d0
	beq.s	.times_one                      ; 2^0: times one
	cmpi.b	#$1,d0                          ; 2^1: times two
	beq.s	.times_two
	subq.l	#8,a1                           ; back to the $ffcd
	move.w	#$ffab,(a1)+                    ; IR $ffab: scale by 2^d0
	move.w	d0,(a1)+                        ; the power
	moveq	#6,d0                           ; drop the rest: 6 bytes
.drop:
	bra.w	ir_drop_bytes
.times_one:
	subq.l	#8,a1                           ; back to the $ffcd
	moveq	#10,d0                          ; drop the whole operation: 10 bytes
	bra.s	.drop
.times_two:
	subq.l	#8,a1                           ; back to the $ffcd
	move.w	#$147,(a1)+                     ; routine $147: times two
	moveq	#8,d0                           ; drop the rest: 8 bytes
	bra.s	.drop

;------------------------------------------------------------------------------
; No change.
;------------------------------------------------------------------------------
opt_fold_done:
	rts

;------------------------------------------------------------------------------
; Float constant then '/' by a constant: the two constants swap places and the routine becomes
; $11b.
;------------------------------------------------------------------------------
opt_float_const_then_op:
	cmpi.w	#$8,6(a1)                       ; operator 8 '/' after the second constant?
	bne.s	opt_fold_done
	movem.w	-$6(a1),d0-d6                   ; d0-d2 first constant, d3 $ffcd, d4-d6 second constant
	movem.w	d4-d6,-$6(a1)                   ; second constant first ...
	movem.w	d0-d2,(a1)                      ; ... then the first after the $ffcd
	move.w	#$11b,6(a1)                     ; routine $11b: divide reversed
	moveq	#-1,d7                          ; changed
	rts

;------------------------------------------------------------------------------
; Float constant before a float-variable operation ($ffcb): reordered to the variable read and
; a constant operation, the operator swapped through float_const_op_table.
;------------------------------------------------------------------------------
opt_float_const_then_var_op:
	movem.w	-$6(a1),d0-d5                   ; d0-d2 constant, d3 $ffcb, d4 variable index, d5 operator
	lea	float_const_op_table(pc),a2
	moveq	#21,d6                          ; 22 entries
.find_op:
	cmp.w	(a2)+,d5                        ; look for the operator
	dbeq	d6,.find_op
	bne.s	.done                           ; no constant form: left alone
	move.w	#$fff3,-$8(a1)                  ; IR $fff3: read the float variable
	move.w	d4,-$6(a1)                      ; its index
	move.w	#$ffcd,-$4(a1)                  ; IR $ffcd: constant operation
	movem.w	d0-d2,-$2(a1)                   ; the constant
	move.w	$2a(a2),4(a1)                   ; the swapped-operand operator (+$2c)
	lea	bss_end+$b0,a1                  ; restart the scan from the start (d7 not set)
.done:
	rts

;------------------------------------------------------------------------------
; Integer constant ($ffce) pushed and popped: becomes the constant operation $ffcc.
;------------------------------------------------------------------------------
opt_int_const:
	addq.l	#4,a1                           ; past the constant
	cmpi.w	#$fff8,(a1)                     ; integer push next?
	bne.s	opt_fold_done
	bsr.w	ir_find_operand_end
	cmpi.w	#$fff5,-(a2)                    ; the operand ends with an integer pop?
	bne.s	opt_fold_done
	move.l	-(a1),-(sp)                     ; keep the constant
	subq.w	#2,a1                           ; back to the $ffce
	suba.w	#$a,a2                          ; end of the move
.move_down:
	move.w	8(a1),(a1)+                     ; move the operand's IR down
	cmpa.l	a1,a2                           ; until the pop is reached
	bcc.s	.move_down
	move.w	#$ffcc,(a1)+                    ; IR $ffcc: integer constant operation
	move.l	(sp)+,(a1)+                     ; the constant
	bra.w	ir_drop_pair                    ; drop 4 bytes after it

;------------------------------------------------------------------------------
; $ffcc: steps over its long constant.
;------------------------------------------------------------------------------
opt_int_const_op:
	addq.l	#4,a1

;------------------------------------------------------------------------------
; No change.
;------------------------------------------------------------------------------
opt_push_float_done:
	rts

;------------------------------------------------------------------------------
; Float push of a variable ($fff3) or of a constant followed by a pop and an operator in
; float_const_op_table: becomes $ffcb / $ffcd with the operator.
;------------------------------------------------------------------------------
opt_push_float:
	cmpi.w	#$fff3,(a1)                     ; push of a float variable?
	beq.w	opt_push_float_var
	cmpi.w	#$ffef,(a1)                     ; push of a float constant?
	bne.s	opt_push_float_done
	cmpi.w	#$fff6,8(a1)                    ; followed by a float pop?
	bne.s	opt_push_float_done
	move.w	$a(a1),d0                       ; d0 = the operator
	lea	float_const_op_table(pc),a2
	moveq	#21,d1                          ; 22 operators
.find_op:
	cmp.w	(a2)+,d0                        ; look it up
	dbeq	d1,.find_op
	bne.s	opt_push_float_done             ; no constant form: left alone
	move.w	#$ffcd,-$2(a1)                  ; $ffcd replaces the push
	move.l	2(a1),(a1)+                     ; the constant moved up a word ...
	move.w	2(a1),(a1)+                     ; ... and its last word
	move.w	$2a(a2),(a1)+                   ; the operator from the second half (+$2c)
	bra.w	ir_drop_pair                    ; drop the 4 bytes left over

; 22 float operators that have a constant form, then the same 22 with the operands swapped
; (+$2c). Decoded as instructions.
float_const_op_table:
	dc.w	$0006,$0007,$011b,$0008,$011d,$000b,$011c,$000a
	dc.w	$0013,$000c,$0012,$000f,$0011,$000d,$0010,$000e
	dc.w	$002d,$005b,$0143,$0153,$0009,$00de,$0006,$0007
	dc.w	$0008,$011b,$000b,$011d,$000a,$011c,$0013,$000c
	dc.w	$0011,$000d,$0012,$000f,$000d,$000f,$002d,$011d
	dc.w	$0153,$0143,$00de,$0009

;------------------------------------------------------------------------------
; Integer push: of a variable ($fff1, rule in the next range) or of a constant then pop and
; an operator: POKE family $130-$13b take bit 0 flipped, others via int_const_op_table.
;------------------------------------------------------------------------------
opt_push_int:
	cmpi.w	#$fff1,(a1)
	beq.w	opt_swap_int_operands_var       ; integer variable push: the swap rule
	cmpi.w	#$ffce,(a1)                     ; integer constant?
	bne.s	.done
	cmpi.w	#$fff5,6(a1)                    ; followed by an integer pop?
	beq.s	.const_op
.done:
	rts
.const_op:
	move.w	8(a1),d0                        ; d0 = the routine
	cmpi.w	#$130,d0                        ; POKE family $130-$13b?
	bcs.s	.search_table
	cmpi.w	#$13b,d0
	bhi.s	.search_table
	eori.w	#$1,d0                          ; bit 0 flipped: its constant form
	bra.s	.emit_const_op
.search_table:
	lea	int_const_op_table(pc),a2
	moveq	#44,d1                          ; 45 routines
.find_op:
	cmp.w	(a2)+,d0                        ; look it up
	dbeq	d1,.find_op
	bne.s	.done                           ; no constant form: left alone
	move.w	$58(a2),d0                      ; its constant form (+$5a)
.emit_const_op:
	move.w	#$ffcc,-$2(a1)                  ; $ffcc replaces the push
	move.l	2(a1),(a1)+                     ; the constant
	move.w	d0,(a1)+                        ; the routine
	bra.w	ir_drop_pair                    ; drop the 4 bytes left over

; 45 integer routines (operators, graphics $224-$243 ...) and at +$5a the variant taking a
; constant. Decoded as instructions.
int_const_op_table:
	dc.w	$0000,$0001,$0002,$0003,$0004,$0110,$0111,$0112
	dc.w	$0113,$0114,$0115,$0116,$0117,$0118,$0119,$005c
	dc.w	$0241,$0224,$0225,$0226,$0227,$0228,$0229,$022a
	dc.w	$022b,$0239,$023a,$0235,$0236,$0237,$0238,$0230
	dc.w	$0231,$023c,$023d,$022e,$022d,$0233,$0234,$023e
	dc.w	$023f,$0242,$0243,$013e,$0152,$0000,$0001,$0002
	dc.w	$0110,$0004,$0003,$0111,$0113,$0112,$0114,$0115
	dc.w	$0118,$0119,$0116,$0117,$0241,$005c,$0225,$0224
	dc.w	$0227,$0226,$0229,$0228,$022b,$022a,$023a,$0239
	dc.w	$0236,$0235,$0238,$0237,$0231,$0230,$023d,$023c
	dc.w	$022d,$022e,$0234,$0233,$023f,$023e,$0243,$0242
	dc.w	$0152,$013e

;------------------------------------------------------------------------------
; After $fffc (boolean to float): print number becomes print boolean ($157); $fffc $ffff
; becomes $fffa.
;------------------------------------------------------------------------------
opt_bool_to_float:
	cmpi.w	#$120,(a1)                      ; $120: print a number?
	bne.s	.bool_to_int
	move.w	#$157,(a1)                      ; routine $157: print a boolean
	bra.w	ir_drop_previous_word           ; drop the $fffc
.bool_to_int:
	cmpi.w	#$ffff,(a1)                     ; $ffff next?
	bne.s	opt_no_change
	move.w	#$fffa,(a1)                     ; IR $fffa: boolean to integer
	bra.w	ir_drop_previous_word           ; drop the $fffc

;------------------------------------------------------------------------------
; No change.
;------------------------------------------------------------------------------
opt_no_change:
	rts

;------------------------------------------------------------------------------
; Steps over one operand word.
;------------------------------------------------------------------------------
opt_skip_word:
	addq.l	#2,a1
	rts

;------------------------------------------------------------------------------
; Steps over two operand words.
;------------------------------------------------------------------------------
opt_skip_long:
	addq.l	#4,a1

;------------------------------------------------------------------------------
; No operand.
;------------------------------------------------------------------------------
opt_skip_none:
	rts

;------------------------------------------------------------------------------
; Steps over a string literal (length word, characters, pad).
;------------------------------------------------------------------------------
opt_skip_string:
	move.w	(a1)+,d1                        ; length word
	addq.w	#1,d1                           ; rounded up ...
	andi.w	#$fffe,d1                       ; ... to even
	adda.w	d1,a1                           ; step over the characters
	rts

;------------------------------------------------------------------------------
; From a1, finds the end of the pushed operand: walks the IR keeping the stack depth in d6
; (bytes) with ir_stack_effect_table until it drops to zero; a2 = past that operation. Stops
; at the $1234 end marker.
;------------------------------------------------------------------------------
ir_find_operand_end:
	movea.l	a1,a2                           ; a2 walks the IR
	moveq	#0,d6                           ; stack depth 0
.next_word:
	move.w	(a2)+,d1                        ; next word
	bmi.s	.operation
	cmpi.w	#$1234,d1                       ; end marker?
	bne.s	.next_word
	rts
.operation:
	not.w	d1                              ; index = not d1
	add.w	d1,d1                           ; word index
	move.w	ir_stack_effect_table(pc,d1.w),d1
	jsr	ir_stack_effect_table(pc,d1.w)  ; apply its stack effect
	tst.w	d6                              ; bytes still pushed?
	bgt.s	.next_word                      ; yes: go on
	rts

; Stack effect / operand skip per IR operation, offsets from $31a0.
ir_stack_effect_table:
	dc.w	.no_effect-ir_stack_effect_table
	dc.w	.no_effect-ir_stack_effect_table
	dc.w	.no_effect-ir_stack_effect_table
	dc.w	.no_effect-ir_stack_effect_table
	dc.w	.no_effect-ir_stack_effect_table
	dc.w	.no_effect-ir_stack_effect_table
