	dc.w	.end_found-ir_stack_effect_table
	dc.w	.no_effect-ir_stack_effect_table
	dc.w	.no_effect-ir_stack_effect_table
.end_found:
	moveq	#0,d6                           ; an operation that ends the statement: stop
	rts
.skip_three:
	addq.l	#2,a2
.skip_two:
	addq.l	#2,a2
.skip_one:
	addq.l	#2,a2
.no_effect:
	rts
.skip_string:
	move.w	(a2)+,d1                        ; string length
	addq.w	#1,d1                           ; rounded up ...
	andi.w	#$fffe,d1                       ; ... to even
	adda.w	d1,a2                           ; step over the characters
	rts
.push_float:
	addq.w	#8,d6                           ; float push: 8 + 4 = 12 bytes
.push_long:
	addq.w	#4,d6                           ; long push: 4 bytes
	rts
.pop_float:
	subq.w	#8,d6                           ; float pop: 12 bytes
.pop_long:
	subq.w	#4,d6                           ; long pop: 4 bytes
	rts
.push_word:
	addq.w	#2,d6                           ; word push: 2 bytes
	rts
.pop_counted:
	sub.w	(a2)+,d6                        ; pop the counted bytes
	rts
.pop_longs:
	move.w	(a2)+,d0                        ; count of longs
	asl.w	#2,d0                           ; 4 bytes each
	sub.w	d0,d6                           ; popped
	rts
.skip_two_words:
	addq.l	#4,a2                           ; two operand words
	rts
.pop_args:
	move.l	(a2)+,d0                        ; d0 low word = argument count
	subq.w	#1,d0                           ; less one
	asl.w	#2,d0                           ; 4 bytes each
	sub.w	d0,d6                           ; popped
	rts
.pop_args_all:
	move.l	(a2)+,d0                        ; d0 low word = argument count
	asl.w	#2,d0                           ; 4 bytes each
	sub.w	d0,d6                           ; popped
	rts

;------------------------------------------------------------------------------
; Integer converted to float, then a float constant operation: when the constant is a whole
; number the operation becomes the integer one ($ffcc) from float_to_int_op_table.
;------------------------------------------------------------------------------
opt_int_to_float_const_op:
	cmpi.w	#$ffff,$a(a1)                   ; $ffff after the operation?
	beq.s	.const_op
	cmpi.w	#$fffc,$a(a1)                   ; or $fffc?
	beq.s	.const_op
.done:
	rts
.const_op:
	move.w	8(a1),d0                        ; d0 = the operator
	lea	float_to_int_op_table,a2
	moveq	#10,d1                          ; 11 operators
.find_op:
	cmp.w	(a2)+,d0                        ; look it up
	dbeq	d1,.find_op
	bne.s	.done                           ; no integer form: left alone
	move.w	$14(a2),-(sp)                   ; keep its integer form (+$16)
	move.l	2(a1),d0                        ; constant: sign and fraction ...
	move.w	6(a1),d1                        ; ... and the exponent word
	bsr.w	const_float_unpack
	bsr.w	const_float_to_int              ; to an integer
	move.l	d0,-(sp)                        ; keep it
	bsr.w	const_int_to_float              ; and back to a float
	bsr.w	const_float_pack                ; packed
	move.l	(sp)+,d3                        ; d3 = the integer
	move.w	(sp)+,d4                        ; d4 = the integer routine
	move.w	6(a1),d5                        ; the original exponent word
	andi.w	#$3ff,d5                        ; exponent 0: zero is whole
	beq.s	.emit_int_const_op
	cmp.l	2(a1),d0                        ; same fraction back: a whole number?
	bne.s	.done
	cmp.w	d5,d1                           ; same exponent?
	bne.s	.done
.emit_int_const_op:
	move.w	#$ffcc,-$2(a1)                  ; $ffcc over the $fffe
	move.l	d3,(a1)+                        ; the integer
	move.w	d4,(a1)+                        ; the integer routine
	moveq	#6,d0                           ; 6 bytes of IR to drop ...
	cmpi.w	#$fffc,4(a1)                    ; ... unless $fffc follows
	bne.w	ir_drop_bytes
	moveq	#4,d0                           ; then only 4
	bra.w	ir_drop_bytes

; Compiler, IR optimiser data: 11 float routines that have an integer form ($6 add, $11a, $5,
; the compares $c-$13), then their integer routines at +$16 ($111 add ... $119) and at +$2c
; the integer routines taking the operands the other way round (for $ffc9). Decoded as
; instructions in the first pass.
float_to_int_op_table:
	dc.w	$0006,$011a,$0005,$0013,$000c,$000f,$0012,$000d
	dc.w	$0011,$000e,$0010,$0111,$0112,$0113,$0114,$0115
	dc.w	$0117,$0116,$0119,$0118,$0119,$0117,$0111,$0113
	dc.w	$0112,$0114,$0115,$0119,$0118,$0117,$0116,$0117
	dc.w	$0119

;------------------------------------------------------------------------------
; IR optimiser rule for $fffe (int to float): $fffe $fff9 $fff1 var $fffe $fff6 op, an integer
; expression and an integer variable combined by a float operator from float_to_int_op_table,
; becomes $ffc9 var int-op: the integer routine with the variable as operand. A following $fffc
; is kept; a following $ffff (back to integer) is dropped as well. a1 points after the $fffe.
;------------------------------------------------------------------------------
opt_int_to_float_push:
	cmpi.w	#$fff1,2(a1)                    ; next: load of an integer variable ($fff1)?
	bne.s	.done                           ; no: leave the IR
	cmpi.w	#$fffe,6(a1)                    ; then converted to float ($fffe) ...
	bne.s	.done
	cmpi.w	#$fff6,8(a1)                    ; ... and popped as the first operand into d3-d5 ($fff6)
	bne.s	.done
	cmpi.w	#$ffff,$c(a1)                   ; result converted straight back to integer ($ffff)?
	beq.s	.to_int_next                    ; yes: the conversion can go as well
	cmpi.w	#$fffc,$c(a1)                   ; or the result goes on as a bool converted ($fffc)
	bne.s	.done
	move.w	$a(a1),d0                       ; d0 = the float routine applied
	lea	float_to_int_op_table(pc),a2    ; look it up among the 11 float routines with an integer form
	moveq	#10,d1                          ; 11 entries
.find_op:
	cmp.w	(a2)+,d0                        ; compare with the next float routine
	dbeq	d1,.find_op                     ; until found or the 11 are done
	bne.s	.done                           ; no integer form: leave the IR
	move.w	#$ffc9,-$2(a1)                  ; the $fffe becomes $ffc9: integer variable as operand
	move.w	4(a1),(a1)+                     ; variable number
	move.w	$2a(a2),(a1)+                   ; the integer-variable routine (entry + $2c)
	move.w	#$fffc,(a1)+                    ; the $fffc stays after it
	moveq	#8,d0                           ; drop the 8 bytes left over
	bra.w	ir_drop_bytes                   ; remove them and mark the IR changed
.done:
	rts
.to_int_next:
	move.w	$a(a1),d0                       ; d0 = the float routine applied
	lea	float_to_int_op_table(pc),a2    ; look it up among the 11 float routines with an integer form
	moveq	#10,d1                          ; 11 entries
.find_op_int:
	cmp.w	(a2)+,d0                        ; compare with the next float routine
	dbeq	d1,.find_op_int                 ; until found or the 11 are done
	bne.s	.done                           ; no integer form: leave the IR
	move.w	#$ffc9,-$2(a1)                  ; the $fffe becomes $ffc9: integer variable as operand
	move.w	4(a1),(a1)+                     ; variable number
	move.w	$2a(a2),(a1)+                   ; the integer-variable routine (entry + $2c)
	moveq	#10,d0                          ; drop 10 bytes: the rest of the pattern and the $ffff
	bra.w	ir_drop_bytes                   ; remove them and mark the IR changed

;------------------------------------------------------------------------------
; IR optimiser rule for $fff1 (load integer variable): var $fff8 (pushed), the other operand,
; then $fff5 (popped into d1) and the operation: the load and push go, and the $fff5 becomes
; $ffc9 var, so the other operand is computed first and the variable read as its operand.
; a1 points after the $fff1.
;------------------------------------------------------------------------------
opt_int_var:
	addq.l	#2,a1                           ; step over the variable number
	cmpi.w	#$fff8,(a1)                     ; pushed straight away ($fff8)?
	beq.s	.push_var
.done:
	rts
.push_var:
	bsr.w	ir_find_operand_end             ; a2 = past the operand pushed on top of it
	cmpi.w	#$fff5,-(a2)                    ; is the operation before a2 the pop into d1 ($fff5)?
	bne.s	.done                           ; no: leave the IR
	move.w	-(a1),-(sp)                     ; keep the variable number
	subq.w	#2,a1                           ; a1 back to the $fff1
	subq.l	#8,a2                           ; a2 = last word to move: the end of the operand
.move_down:
	move.w	6(a1),(a1)+                     ; move the operand down over $fff1 var $fff8 (6 bytes)
	cmpa.l	a1,a2                           ; up to the $fff5
	bcc.s	.move_down
	move.w	#$ffc9,(a1)+                    ; the $fff5 becomes $ffc9 ...
	move.w	(sp)+,(a1)+                     ; ... with the variable number
	bra.w	ir_drop_pair                    ; remove the two words left over, mark the IR changed

;------------------------------------------------------------------------------
; System array address ($ffae): a following constant add ($ffcc $111) is folded into it; a
; push/pop of it becomes $ffad.
;------------------------------------------------------------------------------
opt_system_array:
	moveq	#0,d0                           ; d0 = the system variable offset (word operand)
	move.w	(a1)+,d0                        ; a1 = past the operand
	cmpi.w	#$ffcc,(a1)                     ; next: an integer constant operand ($ffcc)?
	bne.s	.check_push
	cmpi.w	#$111,6(a1)                     ; with an add ($111): fold the constant into the offset
	beq.s	.fold_offset
.check_push:
	cmpi.w	#$fff8,(a1)                     ; pushed straight away ($fff8)?
	beq.s	.push_address
.done:
	rts
.fold_offset:
	add.l	2(a1),d0                        ; offset + constant
	cmpi.l	#$7fff,d0                       ; still a positive word offset?
	bhi.s	.check_push                     ; no: leave the add
	move.w	d0,-$2(a1)                      ; store the new offset
	moveq	#8,d0                           ; drop $ffcc, the long and $111 (8 bytes)
	bra.w	ir_drop_bytes                   ; remove them and mark the IR changed
.push_address:
	bsr.w	ir_find_operand_end             ; a2 = past the operand pushed on top of it
	cmpi.w	#$fff5,-(a2)                    ; is the operation before a2 the pop into d1 ($fff5)?
	bne.s	.done                           ; no: leave the IR
	move.w	-(a1),-(sp)                     ; keep the offset
	subq.w	#2,a1                           ; a1 back to the $ffae
	subq.l	#8,a2                           ; a2 = last word to move: the end of the operand
.move_down:
	move.w	6(a1),(a1)+                     ; move the operand down over $ffae n $fff8 (6 bytes)
	cmpa.l	a1,a2                           ; up to the $fff5
	bcc.s	.move_down
	move.w	#$ffad,(a1)+                    ; the $fff5 becomes $ffad: system variable address into d1
	move.w	(sp)+,(a1)+                     ; with the offset
	bra.w	ir_drop_pair                    ; remove the two words left over, mark the IR changed

;------------------------------------------------------------------------------
; IR optimiser rule for $fff3 (load float variable): var $fff9 (pushed), the other operand,
; then $fff6 (popped into d3-d5): the load and push go, and the $fff6 becomes $ffcb var, the
; variable loaded straight into d3-d5 after the other operand. a1 points after the $fff3.
;------------------------------------------------------------------------------
opt_float_var:
	addq.l	#2,a1                           ; step over the variable number
	cmpi.w	#$fff9,(a1)                     ; pushed straight away ($fff9)?
	beq.s	.push_var
.done:
	rts
.push_var:
	bsr.w	ir_find_operand_end             ; a2 = past the operand pushed on top of it
	cmpi.w	#$fff6,-(a2)                    ; is the operation before a2 the pop into d3-d5 ($fff6)?
	bne.s	.done                           ; no: leave the IR
	move.w	-(a1),-(sp)                     ; keep the variable number
	subq.w	#2,a1                           ; a1 back to the $fff3
	subq.l	#8,a2                           ; a2 = last word to move: the end of the operand
.move_down:
	move.w	6(a1),(a1)+                     ; move the operand down over $fff3 var $fff9 (6 bytes)
	cmpa.l	a1,a2                           ; up to the $fff6
	bcc.s	.move_down
	move.w	#$ffcb,(a1)+                    ; the $fff6 becomes $ffcb: float variable into d3-d5
	move.w	(sp)+,(a1)+                     ; with the variable number
	bra.w	ir_drop_pair                    ; remove the two words left over, mark the IR changed

;------------------------------------------------------------------------------
; IR optimiser rule for $fff3 (load float variable) followed by $fff6 (pop into d3-d5) and a
; float operator from float_const_op_table: becomes $ffcb var with the operator taking its
; operands the other way round. a1 points after the $fff3.
;------------------------------------------------------------------------------
opt_push_float_var:
	cmpi.w	#$fff6,4(a1)                    ; the load is followed by the pop into d3-d5?
	bne.s	opt_pattern_no_match
	move.w	6(a1),d0                        ; d0 = the float routine after it
	lea	float_const_op_table(pc),a2     ; look it up among the 22 float operators
	moveq	#21,d1                          ; 22 entries
.find_op:
	cmp.w	(a2)+,d0                        ; compare with the next operator
	dbeq	d1,.find_op                     ; until found or all 22 are done
	bne.s	opt_pattern_no_match            ; not one of them: leave the IR
	move.w	#$ffcb,-$2(a1)                  ; the $fff3 becomes $ffcb: float variable into d3-d5
	move.w	2(a1),(a1)+                     ; variable number
	move.w	$2a(a2),(a1)+                   ; the operator with the operands swapped (entry + $2c)
	bra.w	ir_drop_pair                    ; remove the two words left over, mark the IR changed

;------------------------------------------------------------------------------
; IR optimiser: shared rts for the pattern tests at opt_push_float_var and
; opt_swap_int_operands_var when the IR does not match.
;------------------------------------------------------------------------------
opt_pattern_no_match:
	rts

;------------------------------------------------------------------------------
; IR optimiser. a1 points at an IR word whose operand (2(a1)) is an integer variable; when it
; is followed by $fff5 (pop int into d1) and a routine number, the sequence becomes $ffc9 var
; routine: the variable is used as the second operand directly, with the routine swapped for
; its reversed form. Ends in ir_drop_pair after a rewrite, returns unchanged otherwise.
;------------------------------------------------------------------------------
opt_swap_int_operands_var:
	cmpi.w	#$fff5,4(a1)                    ; next IR $fff5 = pop int into d1?
	bne.s	opt_pattern_no_match
	move.w	6(a1),d0                        ; d0 = routine number that uses d0 and d1
	cmpi.w	#$130,d0                        ; routines $130-$13b are pairs that differ only in bit 0
	bcs.s	opt_lookup_swapped_routine
	cmpi.w	#$13b,d0
	bhi.s	opt_lookup_swapped_routine

;------------------------------------------------------------------------------
; Routines $130-$13b (POKE family): the reversed form is the pair member with bit 0 flipped.
;------------------------------------------------------------------------------
opt_swap_routine_pair:
	eori.w	#$1,d0                          ; pair member with the operands the other way round
	bra.s	opt_emit_int_var_operand

;------------------------------------------------------------------------------
; Other routines: the reversed form from int_const_op_table (45 routines, reversed at +$5a).
;------------------------------------------------------------------------------
opt_lookup_swapped_routine:
	lea	int_const_op_table(pc),a2       ; 45 routine numbers with a reversed-operand counterpart
	moveq	#44,d1
.find_routine:
	cmp.w	(a2)+,d0
	dbeq	d1,.find_routine
	bne.s	opt_pattern_no_match            ; no reversed form: leave the IR as it is
	move.w	$58(a2),d0                      ; reversed routine from the second half of the table (+$5a)

;------------------------------------------------------------------------------
; Writes $ffc9 var routine over the pattern (d0 = routine) and drops the two words left over.
;------------------------------------------------------------------------------
opt_emit_int_var_operand:
	move.w	#$ffc9,-$2(a1)                  ; IR $ffc9: int variable as the second operand of the next routine
	move.w	2(a1),(a1)+                     ; variable number
	move.w	d0,(a1)+                        ; reversed routine number
	bra.w	ir_drop_pair

;------------------------------------------------------------------------------
; Compiler, code generator. Turns the IR from bss_end+$b0 up to a0 into 68000 code at
; bss_end+$3d0 (a2). Words $0000-$0280 are runtime routine numbers, words $ff83-$ffff (not.w +
; $280 = index $280-$2fc) are IR operations; each is dispatched through codegen_dispatch_table.
; a1 reads the IR, a3 writes the list of runtime call positions at bss_end+$a10 (see
; emit_call_routine). Called once per statement.
;------------------------------------------------------------------------------
generate_code:
	lea	bss_end+$b0,a1                  ; a1 = IR start
	lea	bss_end+$3d0,a2                 ; a2 = generated code buffer
	lea	bss_end+$a10,a3                 ; a3 = list of runtime call positions
	move.w	#$1234,(a0)                     ; end marker after the IR
.next_ir:
	cmpa.l	a0,a1                           ; all IR words done?
	bcc.s	.done
	move.w	(a1)+,d0                        ; next IR word
	bpl.s	.routine_number                 ; positive: runtime routine number
	not.w	d0                              ; IR operation $ffff.. -> index $280..
	addi.w	#$280,d0
	bpl.s	.check_range
.bad_ir:
	bsr.w	compile_error_fatal             ; internal error "* Mk 1 *" (fatal alert, does not return)
	dc.b	'* Mk 1 *',0
	dc.b	$00
.routine_number:
	cmpi.w	#$280,d0
	bhi.s	.bad_ir
.check_range:
	cmpi.w	#$2fc,d0
	bhi.s	.bad_ir
	add.w	d0,d0                           ; word index into the dispatch table
	move.w	codegen_dispatch_table(pc,d0.w),d1
	jsr	codegen_dispatch_table(pc,d1.w) ; handler gets d0 = index*2, a1 past the IR word
	bra.s	.next_ir                        ; until the IR is done
.done:
	rts                                     ; a2 = end of the code, a3 = end of the call list

; Compiler data: offsets of the code generator handlers, index 0-$27f by
; runtime routine number, $280 up by IR operation ($ffff first). Most routine
; numbers go to emit_call_routine_index (a plain jsr routine(a6)).
codegen_dispatch_table:
	dc.w	emit_int_and-codegen_dispatch_table ; routine $0: emit_int_and
	dc.w	emit_int_or-codegen_dispatch_table ; routine $1: emit_int_or
	dc.w	emit_int_xor-codegen_dispatch_table ; routine $2: emit_int_xor
	dc.w	emit_int_imp-codegen_dispatch_table ; routine $3: emit_int_imp
	dc.w	emit_int_eqv-codegen_dispatch_table ; routine $4: emit_int_eqv
	dc.w	emit_call_routine_index-codegen_dispatch_table
	dc.w	emit_call_routine_index-codegen_dispatch_table
	dc.w	emit_call_routine_index-codegen_dispatch_table
	dc.w	emit_call_routine_index-codegen_dispatch_table
