	dc.w	emit_call_routine_index-codegen_dispatch_table
	dc.w	emit_compare_routine-codegen_dispatch_table ; routine $c: emit_compare_routine
	dc.w	emit_compare_routine-codegen_dispatch_table ; routine $d: emit_compare_routine
	dc.w	emit_compare_routine_swapped-codegen_dispatch_table ; routine $e: emit_compare_routine_swapped
	dc.w	emit_compare_routine-codegen_dispatch_table ; routine $f: emit_compare_routine
	dc.w	emit_compare_routine_swapped-codegen_dispatch_table ; routine $10: emit_compare_routine_swapped
	dc.w	emit_compare_routine-codegen_dispatch_table ; routine $11: emit_compare_routine
