	rts

;------------------------------------------------------------------------------
; Template word move.w d2,-(sp), copied by .emit_push_bool_word.
;------------------------------------------------------------------------------
tpl_move_w_d2_push:
	move.w	d2,-(sp)                        ; template word $3f02 (move.w d2,-(sp)), copied, not executed

;------------------------------------------------------------------------------
; IR $fffc: jsr routine $10c (bool d2 to float).
;------------------------------------------------------------------------------
emit_call_routine_10c:
	move.w	#$10c,d0                        ; IR $fffc: jsr routine $10c(a6)
	bra.s	emit_call_routine

;------------------------------------------------------------------------------
; Routine $5b: emitted as a call of routine 11.
;------------------------------------------------------------------------------
emit_call_routine_0b:
	moveq	#11,d0                          ; routine $5b is emitted as a call of routine 11
	bra.s	emit_call_routine

;------------------------------------------------------------------------------
; IR $ffff: float d0-d2 to long d0 (routine $f1).
;------------------------------------------------------------------------------
emit_float_to_int:
	move.w	#$f1,d0                         ; IR $ffff: routine $f1 = float d0-d2 to long d0
	bra.s	emit_call_routine               ; call it

;------------------------------------------------------------------------------
; IR $fffe: long d0 to float d0-d2 (routine $f0); followed by a float store ($ffd6) it becomes
; routine $fe with the variable in a0, converting and storing in one call.
;------------------------------------------------------------------------------
emit_int_to_float:
	move.w	#$f0,d0                         ; IR $fffe: routine $f0 = long d0 to float d0-d2
	cmpi.w	#$ffd6,(a1)                     ; followed by a float store ($ffd6)?
	bne.s	emit_call_routine               ; no: a plain call of the conversion
	addq.l	#2,a1                           ; consume the $ffd6
	move.w	#$fe,d0                         ; routine $fe converts and stores at the variable in one call
	bra.w	emit_float_var_call             ; lea the float variable,a0 then the call

;------------------------------------------------------------------------------
; Routine $55: emitted as a call of routine $54 (index - 2, then /2).
;------------------------------------------------------------------------------
emit_call_previous_routine:
	subq.w	#2,d0                           ; call the routine one below this index

;------------------------------------------------------------------------------
; Compiler: default handler, d0 = routine number * 2. Falls into
; emit_call_routine.
;------------------------------------------------------------------------------
emit_call_routine_index:
	lsr.w	#1,d0                           ; d0 = routine number

;------------------------------------------------------------------------------
; Compiler: emits jsr d0(a6) and records the position of its displacement
; word in the call list (a3) as a delta from the previous one; a delta of
; $7fff or more is written as two words, the first with $ff in its high byte.
; The copier replaces each displacement (the routine number) by the routine's
; offset from a6.
;------------------------------------------------------------------------------
emit_call_routine:
	move.w	#$4eae,(a2)+                    ; $4eae = jsr d16(a6)

;------------------------------------------------------------------------------
; Second half of emit_call_routine: records the displacement word about to be written at a2
; and writes the routine number d0 into it. Also used for other words that hold a routine
; number (no jsr in front).
;------------------------------------------------------------------------------
emit_recorded_routine_word:
	move.l	a2,d1                           ; offset of the word in the output program
	subi.l	#bss_end+$3d0,d1                ; minus the code buffer start
	add.l	bss_end+$88,d1                  ; plus the code written to the file so far
	move.l	bss_end+$a0,d2                  ; previous recorded position
	move.l	d1,bss_end+$a0
	sub.l	d2,d1                           ; delta from the previous one
	cmpi.l	#$7fff,d1
	bcs.s	.store_delta
	swap	d1                              ; large delta: high word first, tagged $ff..
	ori.w	#$ff00,d1
	move.w	d1,(a3)+
	swap	d1
.store_delta:
	move.w	d1,(a3)+
	move.w	d0,(a2)+                        ; the routine number as the displacement

;------------------------------------------------------------------------------
; Handler that generates nothing (routine $1d, IR $ffd2).
;------------------------------------------------------------------------------
emit_nothing:
	rts                                     ; routine $1d and IR $ffd2 generate no code

;------------------------------------------------------------------------------
; IR $fffd: tst.w d2 (sets the flags from a bool).
