; IR $fffb: integer d0 to bool d2: move.l d0,d2 / sne d2 / ext.w d2.
;------------------------------------------------------------------------------
emit_int_to_bool:
	move.w	#$2400,(a2)+                    ; IR $fffb: $2400 = move.l d0,d2
	move.w	#$56c2,(a2)+                    ; $56c2 = sne d2
	move.w	tpl_ext_w_d2,(a2)+              ; ext.w d2 (template below)
	rts

;------------------------------------------------------------------------------
; Template word ext.w d2.
;------------------------------------------------------------------------------
tpl_ext_w_d2:
	ext.w	d2                              ; template word $4882 (ext.w d2)

;------------------------------------------------------------------------------
; IR $fffa: bool d2 to integer d0 (0 or -1).
;------------------------------------------------------------------------------
emit_bool_to_int:
	move.l	#$70004a42,(a2)+                ; IR $fffa: moveq #0,d0 / tst.w d2
	move.l	#$670270ff,(a2)+                ; beq.s *+4 / moveq #-1,d0
	rts

;------------------------------------------------------------------------------
; IR $fff8: push the integer d0.
;------------------------------------------------------------------------------
emit_push_long_d0:
	move.w	#$2f00,(a2)+                    ; IR $fff8: $2f00 = move.l d0,-(sp)
	rts

