;------------------------------------------------------------------------------
emit_push_float:
	move.l	#$48e7e000,(a2)+                ; IR $fff9: movem.l d0-d2,-(sp)
	rts

;------------------------------------------------------------------------------
; IR $fff7: push the address a0.
;------------------------------------------------------------------------------
emit_pea_a0:
	move.w	#$4850,(a2)+                    ; IR $fff7: $4850 = pea (a0)
	rts

;------------------------------------------------------------------------------
; IR $fff6: pop a float into d3-d5 (second operand).
;------------------------------------------------------------------------------
emit_pop_float_d3_d5:
	move.l	#$4cdf0038,(a2)+                ; IR $fff6: movem.l (sp)+,d3-d5
	rts

;------------------------------------------------------------------------------
; IR $fff5: pop an integer into d1; before AND or OR the pop and the operation become one
; instruction and the routine word is consumed.
;------------------------------------------------------------------------------
emit_pop_int_d1:
	cmpi.w	#$0,(a1)                        ; IR $fff5: next routine 0 (AND)?
	beq.s	.and_pop
	cmpi.w	#$1,(a1)                        ; next routine 1 (OR)?
	beq.s	.or_pop
	move.w	#$221f,(a2)+                    ; $221f = move.l (sp)+,d1
	rts
.and_pop:
	move.w	#$c09f,(a2)+                    ; $c09f = and.l (sp)+,d0, the AND routine is consumed
	addq.l	#2,a1
	rts
.or_pop:
	move.w	#$809f,(a2)+                    ; $809f = or.l (sp)+,d0
	addq.l	#2,a1
	rts

;------------------------------------------------------------------------------
; IR $fff4: pop an address into a1.
;------------------------------------------------------------------------------
emit_pop_a1:
