;------------------------------------------------------------------------------
emit_int_and:
	move.w	#$c081,(a2)+                    ; routine 0: $c081 = and.l d1,d0
	rts

;------------------------------------------------------------------------------
; Routine 3 (IMP): eor.l d0,d1 / not.l d1 / or.l d1,d0, ending in emit_int_or.
;------------------------------------------------------------------------------
emit_int_imp:
	move.l	#$b1814681,(a2)+                ; routine 3: eor.l d0,d1 / not.l d1, then or.l d1,d0

;------------------------------------------------------------------------------
