; Routine $28 (ABS of a float): bclr #31,d2.
;------------------------------------------------------------------------------
emit_float_abs:
	move.l	#$882001f,(a2)+                 ; routine $28: bclr #31,d2 (clear the float sign)
	rts

;------------------------------------------------------------------------------
; Routine $1e (negate a float): bchg #31,d2.
;------------------------------------------------------------------------------
emit_float_neg:
	move.l	#$842001f,(a2)+                 ; routine $1e: bchg #31,d2 (flip the float sign)
	rts

;------------------------------------------------------------------------------
; IR $ffd1 (BIOS): trap #13, then the stack cleanup for the byte count in the IR.
;------------------------------------------------------------------------------
emit_trap13:
	move.w	#$4e4d,(a2)+                    ; IR $ffd1: trap #13, then the stack cleanup
	bra.s	emit_stack_cleanup

;------------------------------------------------------------------------------
; IR $ffd0 (XBIOS): trap #14, then the stack cleanup.
;------------------------------------------------------------------------------
emit_trap14:
	move.w	#$4e4e,(a2)+                    ; IR $ffd0: trap #14
	bra.s	emit_stack_cleanup

;------------------------------------------------------------------------------
; IR $ffcf (GEMDOS): trap #1, then the stack cleanup.
;------------------------------------------------------------------------------
emit_trap1:
	move.w	#$4e41,(a2)+                    ; IR $ffcf: trap #1

;------------------------------------------------------------------------------
; Compiler: reads the parameter byte count from the IR and emits the stack
; cleanup: nothing for 0, addq.l #2/4/6/8,sp from the template table below,
; otherwise lea n(sp),sp.
;------------------------------------------------------------------------------
emit_stack_cleanup:
	move.w	(a1)+,d0                        ; d0 = bytes of parameters
	beq.s	tbl_addq_sp
	cmpi.w	#$8,d0
	bhi.s	.lea_sp
	move.w	tbl_addq_sp(pc,d0.w),(a2)+      ; addq.l #n,sp template word for n = 2..8
	rts
.lea_sp:
	move.w	#$defc,(a2)+                    ; $defc = adda.w #n,sp
	move.w	d0,(a2)+

;------------------------------------------------------------------------------
; Template words: addq.l #2/#4/#6/#8,sp at tbl_addq_sp + 2..8 (the rts serves the count 0).
;------------------------------------------------------------------------------
tbl_addq_sp:
	rts                                     ; rts, then template words addq.l #2/#4/#6/#8,sp (not executed)
	addq.l	#2,sp                           ; template: addq.l #2,sp
	addq.l	#4,sp                           ; template: addq.l #4,sp

;------------------------------------------------------------------------------
; Template word addq.l #6,sp (also an entry of tbl_addq_sp).
;------------------------------------------------------------------------------
tpl_addq_l_6_sp:
	addq.l	#6,sp                           ; template: addq.l #6,sp
	addq.l	#8,sp                           ; template: addq.l #8,sp

;------------------------------------------------------------------------------
; Routine $9c (call of the machine code at the address in d0): movea.l d0,a0 / jsr (a0), the
; stack cleanup from the IR, then movem.l (sp)+,a3-a6.
;------------------------------------------------------------------------------
emit_call_address_d0:
	move.l	#$20404e90,(a2)+                ; routine $9c: movea.l d0,a0 / jsr (a0)
	bsr.s	emit_stack_cleanup              ; stack cleanup from the IR count
	move.l	#$4cdf7800,(a2)+                ; movem.l (sp)+,a3-a6
	rts
	movem.l	a3-a6,-(sp)                     ; template movem.l a3-a6,-(sp), not executed

;------------------------------------------------------------------------------
; Routine $9d: movem.l a3-a6,-(sp), before a machine code call.
;------------------------------------------------------------------------------
emit_save_a3_a6:
	move.l	#$48e7001e,(a2)+                ; routine $9d: movem.l a3-a6,-(sp)
	rts

;------------------------------------------------------------------------------
; Template: pea d16(sp).
;------------------------------------------------------------------------------
tpl_pea_sp_offset:
	pea	$14(sp)                         ; template: pea d16(sp)

;------------------------------------------------------------------------------
; Template: pea (sp).
;------------------------------------------------------------------------------
tpl_pea_sp:
	pea	(sp)                            ; template: pea (sp)

;------------------------------------------------------------------------------
; Template: movea.l sp,a2.
;------------------------------------------------------------------------------
tpl_movea_sp_a2:
	movea.l	sp,a2                           ; template: movea.l sp,a2

;------------------------------------------------------------------------------
; Template: move.w #n,-(sp).
;------------------------------------------------------------------------------
tpl_move_w_imm_push:
	move.w	#$0,-(sp)                       ; template: move.w #n,-(sp)

;------------------------------------------------------------------------------
; Compiler, IR $ff8b: call of the address in d0 with the parameters on the
; stack and their count: movea.l sp,a2; pea n*4(sp) or pea (sp); movem.l
; a2-a6,-(sp); move.w #n,-(sp); movea.l d0,a0; jsr (a0); addq.l #6,sp;
; movem.l (sp),a3-a7.
;------------------------------------------------------------------------------
emit_call_with_arg_count:
	move.w	tpl_movea_sp_a2(pc),(a2)+
	move.l	tpl_move_w_imm_push(pc),d0      ; d0 high word = $3f3c (move.w #imm,-(sp))
	move.w	(a1)+,d0                        ; d0 low word = number of parameters
	asl.w	#2,d0                           ; byte size of the long parameters
	beq.s	.pea_sp
	move.w	tpl_pea_sp_offset(pc),(a2)+
	move.w	d0,(a2)+
	bra.s	.save_regs
.pea_sp:
	move.w	tpl_pea_sp(pc),(a2)+
.save_regs:
	move.l	#$48e7003e,(a2)+                ; movem.l a2-a6,-(sp)
	lsr.w	#2,d0
	move.l	d0,(a2)+                        ; move.w #count,-(sp)
	move.l	#$20404e90,(a2)+                ; movea.l d0,a0 / jsr (a0)
	move.w	tpl_addq_l_6_sp(pc),(a2)+
	move.l	#$4cd7f800,(a2)+                ; movem.l (sp),a3-a7
	rts

;------------------------------------------------------------------------------
; Template: move.l (a0),-(sp).
;------------------------------------------------------------------------------
tpl_push_long_a0:
	move.l	(a0),-(sp)                      ; template: move.l (a0),-(sp)

;------------------------------------------------------------------------------
; Routine $12e: move.l (a0),-(sp).
;------------------------------------------------------------------------------
emit_push_long_at_a0:
	move.w	tpl_push_long_a0(pc),(a2)+      ; routine $12e: move.l (a0),-(sp)
	rts

;------------------------------------------------------------------------------
; IR $ff85/$ff84: should not occur; fatal internal error "* Mk 2 *".
;------------------------------------------------------------------------------
codegen_error_mk2:
	bsr.w	compile_error_fatal             ; IR $ff85/$ff84: internal error "* Mk 2 *"
	dc.b	'* Mk 2 *',0
	dc.b	$00

;------------------------------------------------------------------------------
; IR $ffc5: lea float var,a0 / jsr routine $14e.
;------------------------------------------------------------------------------
emit_float_var_call_14e:
	move.w	#$14e,d0                        ; IR $ffc5: lea float var,a0 / jsr routine $14e
	bra.s	emit_float_var_call

;------------------------------------------------------------------------------
; IR $ffc1: lea float var,a0 / jsr routine $14f.
;------------------------------------------------------------------------------
emit_float_var_call_14f:
	move.w	#$14f,d0                        ; IR $ffc1: lea float var,a0 / jsr routine $14f
	bra.s	emit_float_var_call

;------------------------------------------------------------------------------
; IR $ffd6: store d0-d2 in a float variable (lea var,a0 / routine $e1).
;------------------------------------------------------------------------------
emit_store_float_var:
	move.w	#$e1,d0                         ; IR $ffd6: routine $e1 = pack d0-d2 and store at (a0)
	bra.s	emit_float_var_call

;------------------------------------------------------------------------------
; IR $fff3: load a float variable into d0-d2 (routine $e0). Followed by $ffff it becomes
; routine $df (load as integer), by $ffd6 a direct copy, by routine $120 routine $155.
;------------------------------------------------------------------------------
emit_load_float_var:
	move.w	#$e0,d0                         ; IR $fff3: routine $e0 = load float at (a0) into d0-d2
	cmpi.w	#$ffff,2(a1)                    ; converted to int straight away ($ffff)?
	bne.s	.check_store
	move.w	#$df,d0                         ; routine $df loads and converts in one call
	bra.s	.emit_and_skip
.check_store:
	cmpi.w	#$ffd6,2(a1)                    ; stored to a float variable straight away?
	beq.w	emit_copy_float_var             ; copy one float variable to another
	cmpi.w	#$120,2(a1)                     ; followed by routine $120?
	bne.s	emit_float_var_call
	move.w	#$155,d0                        ; routine $155 replaces both
.emit_and_skip:
	bsr.s	emit_float_var_call
	addq.l	#2,a1
	rts

;------------------------------------------------------------------------------
; Compiler: emits lea float var,a0 (variable number from the IR) then a call
; of routine d0.
;------------------------------------------------------------------------------
emit_float_var_call:
	move.w	d0,-(sp)                        ; keep the routine number
	bsr.s	emit_lea_float_var              ; lea float var,a0 (variable number from the IR)
	move.w	(sp)+,d0                        ; routine number back
	bra.w	emit_call_routine               ; jsr routine(a6)

;------------------------------------------------------------------------------
; Address of a float variable (number from the IR) into a0.
;------------------------------------------------------------------------------
emit_lea_float_var:
	move.l	bss_end+$3c,d0                  ; offset of the float variables (6 bytes each)
	bra.s	emit_lea_var_6byte

;------------------------------------------------------------------------------
; IR $ffac: address of an integer variable into a0.
;------------------------------------------------------------------------------
emit_lea_int_var:
	move.l	bss_end+$44,d0                  ; IR $ffac: int variables, 4 bytes each
	move.w	(a1)+,d1                        ; d1 = variable number
	mulu.w	#$4,d1                          ; * 4 bytes
	bra.s	emit_lea_var_offset             ; lea d16(a5),a0 for it

;------------------------------------------------------------------------------
; IR $fff2: address of a string descriptor into a0; pushed straight away ($fff7) it becomes
; pea var.
;------------------------------------------------------------------------------
emit_lea_string_var:
	move.l	bss_end+$40,d0                  ; IR $fff2: string descriptors, 6 bytes each
	cmpi.w	#$fff7,2(a1)                    ; pushed ($fff7) straight away?
	beq.w	emit_pea_string_var

;------------------------------------------------------------------------------
; Address of a 6-byte variable (float or descriptor; d0 = type offset, number from the IR)
; into a0.
;------------------------------------------------------------------------------
emit_lea_var_6byte:
	move.w	(a1)+,d1                        ; variable number * 6
	mulu.w	#$6,d1

;------------------------------------------------------------------------------
; Compiler: d0 = type offset, d1 = offset in the type. Emits lea d16(a5),a0
; when it fits (a5 = variables + $8000), else movea.l a5,a0 / adda.l #n,a0.
;------------------------------------------------------------------------------
emit_lea_var_offset:
	add.l	d1,d0                           ; d0 = offset of the variable from the variable base
	cmpi.l	#$fff9,d0                       ; beyond the reach of d16(a5) (offset - $8000 > $7ff9)?
	bhi.s	emit_lea_var_long               ; variables are addressed as d(a5) with a $8000 bias
	subi.w	#$8000,d0                       ; d16 = offset - $8000 (a5 points $8000 into the variables)
	move.w	#$41ed,(a2)+                    ; $41ed = lea d16(a5),a0
	move.w	d0,(a2)+                        ; the displacement
	rts

;------------------------------------------------------------------------------
; The long form of a variable address: movea.l a5,a0 / adda.l #offset-$8000,a0.
;------------------------------------------------------------------------------
emit_lea_var_long:
	move.l	#$204dd1fc,(a2)+                ; movea.l a5,a0 / adda.l #imm,a0
	subi.l	#$8000,d0                       ; a5 is biased by $8000: take it off the offset
	move.l	d0,(a2)+                        ; the long offset
	rts

;------------------------------------------------------------------------------
; IR $ffc2: subtract 1 from an integer variable (trapv when on).
;------------------------------------------------------------------------------
emit_dec_int_var:
	move.w	#$53ad,d0                       ; IR $ffc2: subq.l #1,d16(a5) or subq.l #1,(a0)
	move.w	#$5390,d7                       ; (a0) form for a far variable
	bra.s	emit_int_var_op_trapv

;------------------------------------------------------------------------------
; IR $ffc6: add 1 to an integer variable (trapv when on).
;------------------------------------------------------------------------------
emit_inc_int_var:
	move.w	#$52ad,d0                       ; IR $ffc6: addq.l #1,d16(a5) or addq.l #1,(a0)
	move.w	#$5290,d7                       ; (a0) form for a far variable

;------------------------------------------------------------------------------
; Emits d0 / d7 for the integer variable from the IR, then trapv when Trapv is on.
;------------------------------------------------------------------------------
emit_int_var_op_trapv:
	bsr.w	emit_int_var_access             ; emit it with the variable offset from the IR
	bra.w	emit_trapv_if_enabled           ; trapv after it when Trapv is on

;------------------------------------------------------------------------------
; Integer variable then $fff8: move.l var,-(sp) in place of a load and a push.
;------------------------------------------------------------------------------
emit_push_int_var:
	pea	(a2)                            ; IR $fff1 then $fff8: push an int variable
	bsr.w	emit_move_int_var_d0            ; move.l var,d0, whose 4 or 8 bytes are then rewritten
	addq.l	#2,a1                           ; consume the $fff8
	move.l	a2,d0                           ; bytes emitted for the load
	sub.l	(sp)+,d0                        ; minus the start
	subq.w	#4,d0                           ; 4 bytes written: the short d16(a5) form
	beq.s	.short_form
	move.w	#$2f10,-$2(a2)                  ; long form: move.l (a0),-(sp) after the lea
	rts
.short_form:
	move.w	#$2f2d,-$4(a2)                  ; $2f2d = move.l d16(a5),-(sp)
	rts

;------------------------------------------------------------------------------
; Integer variable then $ffd8: move.w var+2,-(sp) (the low word) in place of a load and a push.
;------------------------------------------------------------------------------
emit_push_int_var_word:
	pea	(a2)                            ; IR $fff1 then $ffd8: push the low word of an int variable
	bsr.w	emit_move_int_var_d0
	addq.l	#2,a1                           ; consume the $ffd8
	move.l	a2,d0                           ; bytes emitted for the load
	sub.l	(sp)+,d0                        ; minus the start
	subq.w	#4,d0                           ; 4 bytes written: the short d16(a5) form
	beq.s	.short_form
	addq.l	#2,-$6(a2)                      ; long form: address + 2, move.w (a0),-(sp)
	move.w	#$3f10,-$2(a2)
	rts
.short_form:
	move.w	#$3f2d,-$4(a2)                  ; $3f2d = move.w d16(a5),-(sp), offset + 2 for the low word
	addq.w	#2,-$2(a2)
	rts

;------------------------------------------------------------------------------
; IR $fff1: load an integer variable into d0. Stored straight into another integer variable
; it becomes one move.l d16(a5),d16(a5); pushed it becomes a push of the variable.
;------------------------------------------------------------------------------
emit_load_int_var:
	cmpi.w	#$ffd5,2(a1)                    ; IR $fff1: stored to an int variable straight away ($ffd5)?
	bne.s	.check_push
	pea	(a2)                            ; start of this code
	bsr.s	emit_move_int_var_d0            ; move.l var,d0
	addq.l	#2,a1                           ; consume the $ffd5
	bsr.s	emit_store_int_var              ; emit the store too
	move.l	(sp)+,d0                        ; start of this code
	addq.l	#8,d0                           ; + 8 bytes
	cmpa.l	d0,a2                           ; both short forms (8 bytes)?
	bne.s	.done
	move.w	#$2b6d,-$8(a2)                  ; $2b6d = move.l d16(a5),d16(a5), one instruction for a%=b%
	move.w	-(a2),d0                        ; the store's displacement ...
	move.w	d0,-$2(a2)                      ; ... becomes the second displacement of the move; a2 back 2 bytes
.done:
	rts
.check_push:
	cmpi.w	#$fff8,2(a1)                    ; pushed as a long ($fff8)?
	beq.s	emit_push_int_var               ; yes: move.l var,-(sp)
	cmpi.w	#$ffd8,2(a1)                    ; pushed as a word ($ffd8)?
	beq.s	emit_push_int_var_word          ; yes: move.w var+2,-(sp)

;------------------------------------------------------------------------------
; move.l var,d0 for the integer variable from the IR.
;------------------------------------------------------------------------------
emit_move_int_var_d0:
	move.w	#$202d,d0                       ; $202d = move.l d16(a5),d0; $2010 = move.l (a0),d0
	move.w	#$2010,d7
	bra.s	emit_int_var_access             ; emit it with the variable offset from the IR

;------------------------------------------------------------------------------
; IR $ffd5: store d0 in an integer variable.
;------------------------------------------------------------------------------
emit_store_int_var:
	move.w	#$2b40,d0                       ; IR $ffd5: $2b40 = move.l d0,d16(a5); $2080 = move.l d0,(a0)
	move.w	#$2080,d7

;------------------------------------------------------------------------------
; Compiler: d0 = opcode with d16(a5), d7 = the same with (a0). Emits d0 and
; the offset of the variable from the IR, or, when the offset does not fit,
; the long lea and the (a0) form. emit_var_access takes d6 = type offset and
; d5 = size.
;------------------------------------------------------------------------------
emit_int_var_access:
	move.l	bss_end+$44,d6                  ; int variables, 4 bytes each
	moveq	#4,d5                           ; 4 bytes each

;------------------------------------------------------------------------------
; Emits d0 with the variable's d16(a5) displacement, or the long lea and d7 (the (a0) form)
; when the offset does not fit. d6 = type offset, d5 = size, variable number from the IR.
;------------------------------------------------------------------------------
emit_var_access:
	move.w	d0,(a2)+                        ; the opcode in d16(a5) form
	move.w	(a1)+,d0                        ; variable number
	mulu.w	d5,d0                           ; * size
	add.l	d6,d0                           ; + type offset = offset of the variable
	cmpi.l	#$fff9,d0                       ; fits a d16(a5)?
	bhi.s	.long_offset
	subi.w	#$8000,d0                       ; d16 = offset - $8000 (a5 is biased by $8000)
	move.w	d0,(a2)+                        ; the displacement
	rts
.long_offset:
	subq.l	#2,a2                           ; drop the opcode, emit the long lea instead
	bsr.w	emit_lea_var_long               ; movea.l a5,a0 / adda.l #offset,a0
	move.w	d7,(a2)+                        ; then the (a0) form of the opcode
	rts

;------------------------------------------------------------------------------
; IR $fff0: load a bool variable into d2.
;------------------------------------------------------------------------------
emit_load_bool_var:
	move.w	#$342d,d0                       ; IR $fff0: $342d = move.w d16(a5),d2; $3410 = move.w (a0),d2
	move.w	#$3410,d7

;------------------------------------------------------------------------------
; Emits d0 / d7 for the bool variable from the IR (2 bytes each).
;------------------------------------------------------------------------------
emit_bool_var_access:
	move.l	bss_end+$48,d6                  ; bool variables, 2 bytes each
	moveq	#2,d5
	bra.s	emit_var_access                 ; emit it with the variable offset from the IR

;------------------------------------------------------------------------------
; IR $ffd4: store d2 in a bool variable.
;------------------------------------------------------------------------------
emit_store_bool_var:
	move.w	#$3b42,d0                       ; IR $ffd4: $3b42 = move.w d2,d16(a5); $3082 = move.w d2,(a0)
	move.w	#$3082,d7
	bra.s	emit_bool_var_access            ; emit it with the variable offset from the IR

;------------------------------------------------------------------------------
; Consumes the $ffd4 store word, then clears the bool variable.
;------------------------------------------------------------------------------
emit_clear_bool_var_skip:
	addq.l	#2,a1                           ; consume the $ffd4 too

;------------------------------------------------------------------------------
; IR $ff94: clear a bool variable (FALSE).
;------------------------------------------------------------------------------
emit_clear_bool_var:
	move.w	#$426d,d0                       ; IR $ff94: $426d = clr.w d16(a5); $4250 = clr.w (a0)
	move.w	#$4250,d7
	bra.s	emit_bool_var_access            ; emit it with the variable offset from the IR

;------------------------------------------------------------------------------
; Float constant tested as a bool: moveq #0/#-1,d2, or clr.w var when it is stored to a bool
; variable. a1 points at the constant.
;------------------------------------------------------------------------------
emit_bool_constant:
	addq.l	#4,a1                           ; float constant used as a bool: skip the mantissa
	move.w	(a1)+,d0                        ; exponent word
	addq.l	#2,a1                           ; step over the IR word after it
	andi.w	#$3ff,d0                        ; zero exponent: the value is 0 (FALSE)
	bne.s	.true
	cmpi.w	#$ffd4,(a1)                     ; stored to a bool variable: clr.w var instead
	beq.s	emit_clear_bool_var_skip        ; yes: emit clr.w var
	move.w	#$7400,(a2)+                    ; $7400 = moveq #0,d2
	rts
.true:
	move.w	#$74ff,(a2)+                    ; $74ff = moveq #-1,d2
	rts

;------------------------------------------------------------------------------
; Compiler, IR $ffef: float constant (mantissa long, exponent word in the IR)
; into d0-d2: move.l #mantissa,d0; move.w #low,d1; moveq/move.l #exp,d2.
; A constant that is stored straight away or tested as a bool goes to
; emit_store_float_constant / emit_bool_constant.
;------------------------------------------------------------------------------
emit_float_constant:
	cmpi.w	#$ffd6,6(a1)                    ; stored to a float variable straight away?
	beq.w	emit_store_float_constant
	cmpi.w	#$fffd,6(a1)                    ; tested as a bool?
	beq.s	emit_bool_constant
	moveq	#0,d2                           ; d2 = sign: 0 positive
	move.l	(a1)+,d0                        ; d0 = mantissa, sign in bit 31
	bpl.s	.positive
	moveq	#-1,d2                          ; d2 = -1: negative (bit 31 is the float sign)
.positive:
	bset	#$1f,d0                         ; hidden top bit of the mantissa
	move.w	(a1)+,d1                        ; d1 = mantissa low bits and exponent
	move.w	d1,d2
	andi.w	#$3ff,d2                        ; d2 = exponent (10 bits), sign in the high word
	beq.s	.zero
	andi.w	#$fc00,d1                       ; d1 keeps the mantissa bits only
	bsr.w	emit_move_imm_d0                ; move.l #mantissa,d0
	move.w	d1,d0                           ; move.w #low mantissa,d1
	bsr.w	emit_move_w_imm_d1
	move.l	d2,d0                           ; moveq/move.l #exponent and sign,d2
	bra.w	emit_move_imm_d2                ; (returns from there)
.zero:
	move.w	#$7400,(a2)+                    ; zero: moveq #0,d2 (exponent 0 is the value 0)
	rts

;------------------------------------------------------------------------------
; IR $ffe5: address of a string array descriptor into d0.
;------------------------------------------------------------------------------
emit_varptr_string_array:
	move.l	bss_end+$50,d1                  ; IR $ffe5: address of a string array descriptor into d0
	bra.s	emit_varptr_6byte               ; 6-byte descriptor

;------------------------------------------------------------------------------
; IR $ffe4: address of an integer array descriptor into d0.
;------------------------------------------------------------------------------
emit_varptr_int_array:
	move.l	bss_end+$54,d1                  ; IR $ffe4: int array descriptor
	bra.s	emit_varptr_6byte               ; 6-byte descriptor

;------------------------------------------------------------------------------
; IR $ffe3: address of a bool array descriptor into d0.
;------------------------------------------------------------------------------
emit_varptr_bool_array:
	move.l	bss_end+$58,d1                  ; IR $ffe3: bool array descriptor
	bra.s	emit_varptr_6byte               ; 6-byte descriptor

;------------------------------------------------------------------------------
; IR $ffe6: address of a float array descriptor into d0.
;------------------------------------------------------------------------------
emit_varptr_float_array:
	move.l	bss_end+$4c,d1                  ; IR $ffe6: float array descriptor
	bra.s	emit_varptr_6byte               ; 6-byte descriptor

;------------------------------------------------------------------------------
; IR $ffe9: address of a string descriptor into d0.
;------------------------------------------------------------------------------
emit_varptr_string_var:
	move.l	bss_end+$40,d1                  ; IR $ffe9: string variable descriptor
	bra.s	emit_varptr_6byte               ; 6-byte descriptor

;------------------------------------------------------------------------------
; IR $ffe8: address of an integer variable into d0.
;------------------------------------------------------------------------------
emit_varptr_int_var:
	moveq	#4,d0                           ; IR $ffe8: int variable, 4 bytes
	move.l	bss_end+$44,d1
	bra.s	emit_varptr                     ; emit with size 4

;------------------------------------------------------------------------------
; IR $ffe7: address of a bool variable into d0.
;------------------------------------------------------------------------------
emit_varptr_bool_var:
	moveq	#2,d0                           ; IR $ffe7: bool variable, 2 bytes
	move.l	bss_end+$48,d1
	bra.s	emit_varptr                     ; emit with size 2

;------------------------------------------------------------------------------
; IR $ffea: address of a float variable into d0.
;------------------------------------------------------------------------------
emit_varptr_float_var:
	move.l	bss_end+$3c,d1                  ; IR $ffea: float variable

;------------------------------------------------------------------------------
; Address of a 6-byte variable into d0 (d1 = type offset).
;------------------------------------------------------------------------------
emit_varptr_6byte:
	moveq	#6,d0                           ; float variables and descriptors: 6 bytes

;------------------------------------------------------------------------------
; Compiler: address of a variable into d0 (d0 = size, d1 = type offset):
; lea d16(a5),a0 / move.l a0,d0, or pea d16(a5) when it is pushed next;
; too far for d16: move.l #offset,d0 / add.l a5,d0.
;------------------------------------------------------------------------------
emit_varptr:
	mulu.w	(a1)+,d0                        ; variable number * size
	add.l	d1,d0                           ; + type offset
	subi.l	#$8000,d0                       ; minus the $8000 bias of a5
	cmpi.l	#$7ff8,d0                       ; beyond d16 reach?
	bhi.s	emit_varptr_long                ; yes: move.l #offset,d0 / add.l a5,d0
	cmpi.w	#$fff8,(a1)                     ; pushed straight away ($fff8)?
	beq.s	.push_address
	move.w	tpl_lea_a5_a0,(a2)+             ; lea d16(a5),a0
	move.w	d0,(a2)+                        ; the displacement
	move.w	tpl_move_l_a0_d0,(a2)+          ; move.l a0,d0
	rts
.push_address:
	move.w	tpl_pea_a5,(a2)+                ; pea d16(a5)
	move.w	d0,(a2)+                        ; the displacement
	addq.l	#2,a1                           ; consume the $fff8
	rts

;------------------------------------------------------------------------------
; Template: lea d16(a5),a0.
;------------------------------------------------------------------------------
tpl_lea_a5_a0:
	lea	1(a5),a0                        ; template: lea d16(a5),a0

;------------------------------------------------------------------------------
; Template: pea d16(a5).
;------------------------------------------------------------------------------
tpl_pea_a5:
	pea	1(a5)                           ; template: pea d16(a5)

;------------------------------------------------------------------------------
; Template: move.l a0,d0.
;------------------------------------------------------------------------------
tpl_move_l_a0_d0:
	move.l	a0,d0                           ; template: move.l a0,d0

;------------------------------------------------------------------------------
; Variable address out of d16 reach: move.l #offset,d0 / add.l a5,d0.
;------------------------------------------------------------------------------
emit_varptr_long:
	bsr.w	emit_move_imm_d0                ; move.l #offset,d0
	move.w	#$d08d,(a2)+                    ; $d08d = add.l a5,d0
	rts

;------------------------------------------------------------------------------
; IR $ffc8: should not occur; fatal internal error "* B! *".
;------------------------------------------------------------------------------
codegen_error_b:
	bsr.w	compile_error_fatal             ; IR $ffc8: internal error "* B! *"
	dc.b	'* B! *',0
	dc.b	$00

;------------------------------------------------------------------------------
; IR $ffcb: load a float variable into d3-d5 (lea var,a0 / routine $12c).
;------------------------------------------------------------------------------
emit_load_float_var_d3_d5:
	move.l	bss_end+$3c,d0                  ; IR $ffcb: lea float var,a0 / jsr routine $12c (load into d3-d5)
	bsr.w	emit_lea_var_6byte              ; lea float var,a0 with the number from the IR
	move.w	#$12c,d0                        ; routine $12c loads (a0) into d3-d5
	bra.w	emit_call_routine               ; jsr routine(a6)

;------------------------------------------------------------------------------
; moveq/move.l #d0,d3.
;------------------------------------------------------------------------------
emit_move_imm_d3:
	moveq	#3,d7                           ; d7 = register d3
	bra.s	emit_move_l_imm_reg             ; moveq or move.l #n,d3

;------------------------------------------------------------------------------
; moveq/move.l #d0,d5.
;------------------------------------------------------------------------------
emit_move_imm_d5:
	moveq	#5,d7                           ; d7 = register d5
	bra.s	emit_move_l_imm_reg             ; moveq or move.l #n,d5

;------------------------------------------------------------------------------
; IR $ffcc: integer constant as the second operand: folded into the next routine when it can
; be (fold_int_constant_op), else move.l #n,d1.
;------------------------------------------------------------------------------
emit_int_constant_d1:
	move.l	(a1)+,d0                        ; IR $ffcc: int constant as the second operand
	bsr.w	fold_int_constant_op            ; folded into the next routine when it can be (no return then)
	moveq	#1,d7                           ; otherwise move.l #n,d1
	bra.s	emit_move_l_imm_reg

;------------------------------------------------------------------------------
; moveq/move.l #d0,d2.
;------------------------------------------------------------------------------
emit_move_imm_d2:
	moveq	#2,d7                           ; d7 = register d2
	bra.s	emit_move_l_imm_reg             ; moveq or move.l #n,d2

;------------------------------------------------------------------------------
; Compiler, IR $ffce: int constant (long in the IR) into d0, or pushed as a
; long or word, or stored to an int variable, depending on the next IR word.
;------------------------------------------------------------------------------
emit_int_constant:
	move.l	(a1)+,d0                        ; d0 = the constant
	cmpi.w	#$fff8,(a1)                     ; pushed as a long?
	beq.s	.push_long
	cmpi.w	#$ffd5,(a1)                     ; stored to an int variable?
	beq.w	emit_store_int_constant
	cmpi.w	#$ffd8,(a1)                     ; pushed as a word?
	bne.s	emit_move_imm_d0
	addq.l	#2,a1                           ; consume the $ffd8
	tst.w	d0                              ; zero: clr.w -(sp)
	beq.s	.push_zero_word
	move.w	#$3f3c,(a2)+                    ; $3f3c = move.w #n,-(sp)
	move.w	d0,(a2)+                        ; the word
	rts
.push_zero_word:
	move.w	#$4267,(a2)+                    ; $4267 = clr.w -(sp)
	rts
.push_long:
	addq.l	#2,a1                           ; consume the $fff8
	tst.l	d0                              ; zero: clr.l -(sp)
	beq.s	.push_zero_long
	cmpi.l	#$7fff,d0                       ; fits a sign-extended word?
	bgt.s	.pea_long
	cmpi.l	#$ffff8000,d0                   ; (bottom of the word range)
	blt.s	.pea_long
	move.w	#$4878,(a2)+                    ; $4878 = pea n.w (sign-extended)
	move.w	d0,(a2)+                        ; the word
	rts
.pea_long:
	move.w	#$4879,(a2)+                    ; $4879 = pea n.l
	move.l	d0,(a2)+                        ; the long
	rts
.push_zero_long:
	move.w	#$42a7,(a2)+                    ; $42a7 = clr.l -(sp)
	rts

;------------------------------------------------------------------------------
; moveq/move.l #d0,d0.
;------------------------------------------------------------------------------
emit_move_imm_d0:
	moveq	#0,d7                           ; d7 = register d0

;------------------------------------------------------------------------------
; Compiler: d0 = value, d7 = data register. Emits moveq #n,Dd7 for -128..127,
; otherwise move.l #n,Dd7. emit_move_w_imm_reg (d1, d4) does the same with
; move.w.
;------------------------------------------------------------------------------
emit_move_l_imm_reg:
	cmpi.l	#$80,d0                         ; above 127: move.l #n
	bge.s	emit_move_l_imm_long
	cmpi.l	#$ffffff80,d0                   ; below -128: move.l #n
	blt.s	emit_move_l_imm_long

;------------------------------------------------------------------------------
; moveq #d0,Dd7.
;------------------------------------------------------------------------------
emit_moveq_reg:
	add.w	d7,d7                           ; $70 + register*2 = moveq high byte
	ori.b	#$70,d7
	move.b	d7,(a2)+                        ; opcode byte
	move.b	d0,(a2)+                        ; the 8-bit value
	rts

;------------------------------------------------------------------------------
; move.l #d0,Dd7.
;------------------------------------------------------------------------------
emit_move_l_imm_long:
	ror.w	#7,d7                           ; register into bits 9-11
	ori.w	#$203c,d7                       ; $203c = move.l #imm,d0
	move.w	d7,(a2)+                        ; the opcode
	move.l	d0,(a2)+                        ; the 32-bit value
	rts

;------------------------------------------------------------------------------
; moveq/move.w #d0,d4.
;------------------------------------------------------------------------------
emit_move_w_imm_d4:
	moveq	#4,d7                           ; d7 = register d4
	bra.s	emit_move_w_imm_reg             ; moveq or move.w #n,d4

;------------------------------------------------------------------------------
; moveq/move.w #d0,d1.
;------------------------------------------------------------------------------
emit_move_w_imm_d1:
	moveq	#1,d7                           ; d7 = register d1

;------------------------------------------------------------------------------
; moveq #n,Dd7 for -128..127, otherwise move.w #n,Dd7 (d0 = value, d7 = register).
;------------------------------------------------------------------------------
emit_move_w_imm_reg:
	cmpi.w	#$80,d0                         ; above 127: move.w #n
	bge.s	.move_word
	cmpi.w	#$ff80,d0                       ; -128..127: moveq #n (the full long is set, harmless here)
	bge.s	emit_moveq_reg
.move_word:
	ror.w	#7,d7                           ; register into bits 9-11
	ori.w	#$303c,d7                       ; $303c = move.w #imm,d0
	move.w	d7,(a2)+                        ; the opcode
	move.w	d0,(a2)+                        ; the 16-bit value
	rts

;------------------------------------------------------------------------------
; IR $ffcd: float constant (from the IR) into d3-d5 as the second operand.
;------------------------------------------------------------------------------
emit_float_constant_d3_d5:
	moveq	#0,d2                           ; IR $ffcd: float constant into d3-d5 (second operand)
	move.l	(a1)+,d0                        ; d0 = mantissa, sign in bit 31
	bpl.s	.positive                       ; positive: d2 = 0
	moveq	#-1,d2                          ; negative: d2 = -1 (sign in bit 31)
.positive:
	bset	#$1f,d0                         ; hidden top bit of the mantissa
	move.w	(a1)+,d1                        ; d1 = mantissa low bits and exponent
	move.w	d1,d2                           ; (copied for the exponent)
	andi.w	#$3ff,d2                        ; d2 = exponent (10 bits), sign in the high word
	beq.s	.zero                           ; exponent 0: the value 0
	andi.w	#$fc00,d1                       ; d1 keeps the mantissa bits only
	bsr.w	emit_move_imm_d3                ; move.l #mantissa,d3
	move.w	d1,d0                           ; the low mantissa word ...
	bsr.s	emit_move_w_imm_d4              ; ... into d4 (move.w #n,d4)
	move.l	d2,d0                           ; exponent and sign ...
	bra.w	emit_move_imm_d5                ; ... into d5
.zero:
	move.w	#$7a00,(a2)+                    ; $7a00 = moveq #0,d5
	rts

;------------------------------------------------------------------------------
; IR $ffa4: float array with routines $159 (several indices) / $158 (one).
;------------------------------------------------------------------------------
emit_float_array_call_158:
	move.w	#$159,d2                        ; IR $ffa4: float array, routines $159 (several indices) / $158 (one)
	move.w	#$158,d3
	bra.s	emit_float_array_call           ; (float array descriptors)

;------------------------------------------------------------------------------
; IR $ffa3: string array with routines $159 / $158.
;------------------------------------------------------------------------------
emit_string_array_call_158:
	move.w	#$159,d2                        ; IR $ffa3: string array, routines $159/$158
	move.w	#$158,d3
	bra.s	emit_string_array_call          ; (string array descriptors)

;------------------------------------------------------------------------------
; IR $ffa2: integer array with routines $159 / $158.
;------------------------------------------------------------------------------
emit_int_array_call_158:
	move.w	#$159,d2                        ; IR $ffa2: int array, routines $159/$158
	move.w	#$158,d3
	bra.s	emit_int_array_call             ; (int array descriptors)

;------------------------------------------------------------------------------
; IR $ffa1: bool array with routines $159 / $158.
;------------------------------------------------------------------------------
emit_bool_array_call_158:
	move.w	#$159,d2                        ; IR $ffa1: bool array, routines $159/$158
	move.w	#$158,d3
	bra.s	emit_bool_array_call            ; (bool array descriptors)

;------------------------------------------------------------------------------
; IR $ffa0: float array with routines $161 / $160.
;------------------------------------------------------------------------------
emit_float_array_call_160:
	move.w	#$161,d2                        ; IR $ffa0: float array, routines $161/$160
	move.w	#$160,d3
	bra.s	emit_float_array_call           ; (float array descriptors)

;------------------------------------------------------------------------------
; IR $ff9f: string array with routines $167 / $166.
;------------------------------------------------------------------------------
emit_string_array_call_166:
	move.w	#$167,d2                        ; IR $ff9f: string array, routines $167/$166
	move.w	#$166,d3
	bra.s	emit_string_array_call          ; (string array descriptors)

;------------------------------------------------------------------------------
; IR $ff9e: integer array with routines $163 / $162.
;------------------------------------------------------------------------------
emit_int_array_call_162:
	move.w	#$163,d2                        ; IR $ff9e: int array, routines $163/$162
	move.w	#$162,d3
	bra.s	emit_int_array_call             ; (int array descriptors)

;------------------------------------------------------------------------------
; IR $ff9d: bool array with routines $165 / $164.
;------------------------------------------------------------------------------
emit_bool_array_call_164:
	move.w	#$165,d2                        ; IR $ff9d: bool array, routines $165/$164
	move.w	#$164,d3
	bra.s	emit_bool_array_call            ; (bool array descriptors)

;------------------------------------------------------------------------------
; IR $ffeb: bool array element (routines $109 / $108).
;------------------------------------------------------------------------------
emit_bool_array_element:
	move.w	#$109,d2                        ; IR $ffeb: bool array element, routines $109/$108
	move.w	#$108,d3                        ; one index: routine $108

;------------------------------------------------------------------------------
; Array call on a bool array descriptor (d2/d3 = routines).
;------------------------------------------------------------------------------
emit_bool_array_call:
	move.l	bss_end+$58,d0                  ; bool array descriptors
	bra.s	emit_array_call

;------------------------------------------------------------------------------
; IR $ffec: integer array element (routines $107 / $106).
;------------------------------------------------------------------------------
emit_int_array_element:
	move.w	#$107,d2                        ; IR $ffec: int array element, routines $107/$106
	move.w	#$106,d3                        ; one index: routine $106

;------------------------------------------------------------------------------
; Array call on an integer array descriptor (d2/d3 = routines).
;------------------------------------------------------------------------------
emit_int_array_call:
	move.l	bss_end+$54,d0                  ; int array descriptors
	bra.s	emit_array_call                 ; emit the array call

;------------------------------------------------------------------------------
; IR $ffed: string array element (routines $105 / $104).
;------------------------------------------------------------------------------
emit_string_array_element:
	move.w	#$105,d2                        ; IR $ffed: string array element, routines $105/$104
	move.w	#$104,d3                        ; one index: routine $104

;------------------------------------------------------------------------------
; Array call on a string array descriptor (d2/d3 = routines).
;------------------------------------------------------------------------------
emit_string_array_call:
	move.l	bss_end+$50,d0                  ; string array descriptors
	bra.s	emit_array_call                 ; emit the array call

;------------------------------------------------------------------------------
; IR $ffee: float array element (routines $103 / $102).
;------------------------------------------------------------------------------
emit_float_array_element:
	move.w	#$103,d2                        ; IR $ffee: float array element, routines $103/$102
	move.w	#$102,d3                        ; one index: routine $102

;------------------------------------------------------------------------------
; Array call on a float array descriptor (d2/d3 = routines).
;------------------------------------------------------------------------------
emit_float_array_call:
	move.l	bss_end+$4c,d0                  ; float array descriptors

;------------------------------------------------------------------------------
; Compiler: d0 = array type offset, d2 = routine for several indices, d3 =
; routine for one index. Emits lea descriptor,a1, then moveq #indices,d7 and
; jsr d2(a6), or jsr d3(a6) for one index.
;------------------------------------------------------------------------------
emit_array_call:
	bsr.w	emit_lea_var_a1                 ; lea descriptor,a1 (array number from the IR, 6 bytes each)
	move.w	d3,d0                           ; one-index routine by default
	move.w	(a1)+,d1                        ; d1 = number of indices
	cmpi.w	#$1,d1                          ; a single index?
	beq.s	.call                           ; yes: no index count needed
	move.b	#$7e,(a2)+                      ; $7e = moveq #n,d7
	move.b	d1,(a2)+                        ; the index count
	move.w	d2,d0                           ; the several-index routine
.call:
	bra.w	emit_call_routine               ; jsr routine(a6)

;------------------------------------------------------------------------------
; Routine $111 (integer +): add.l d1,d0, trapv when on.
;------------------------------------------------------------------------------
emit_int_add:
	move.w	#$d081,(a2)+                    ; routine $111: $d081 = add.l d1,d0
	bra.s	emit_trapv_if_enabled           ; trapv after it when Trapv is on

;------------------------------------------------------------------------------
; Routine $113 (integer reverse -): sub.l d1,d0 / neg.l d0, trapv when on.
;------------------------------------------------------------------------------
emit_int_reverse_sub:
	bsr.s	emit_int_sub                    ; routine $113: sub.l d1,d0 then neg.l d0
	move.w	#$4480,(a2)+                    ; $4480 = neg.l d0
	bra.s	emit_trapv_if_enabled           ; trapv after it when Trapv is on

;------------------------------------------------------------------------------
; Routine $112 (integer -): sub.l d1,d0, trapv when on.
;------------------------------------------------------------------------------
emit_int_sub:
	move.w	#$9081,(a2)+                    ; routine $112: $9081 = sub.l d1,d0

;------------------------------------------------------------------------------
; Emits trapv when the Trapv option is on.
;------------------------------------------------------------------------------
emit_trapv_if_enabled:
	tst.b	option_trapv                    ; Trapv option on?
	beq.s	.done                           ; no: done
	move.w	#$4e76,(a2)+                    ; $4e76 = trapv
.done:
	rts

;------------------------------------------------------------------------------
; Routine $130 (POKE): movea.l d1,a0 / move.b d0,(a0).
;------------------------------------------------------------------------------
emit_poke_byte:
	move.l	#$20411080,(a2)+                ; routine $130: movea.l d1,a0 / move.b d0,(a0)
	rts

;------------------------------------------------------------------------------
; Routine $131: movea.l d0,a0 / move.b d1,(a0) (operands the other way round).
;------------------------------------------------------------------------------
emit_poke_byte_swapped:
	move.l	#$20401081,(a2)+                ; routine $131: movea.l d0,a0 / move.b d1,(a0)
	rts

;------------------------------------------------------------------------------
; Routine $132 (DPOKE): movea.l d1,a0 / move.w d0,(a0).
;------------------------------------------------------------------------------
emit_poke_word:
	move.l	#$20413080,(a2)+                ; routine $132: movea.l d1,a0 / move.w d0,(a0)
	rts

;------------------------------------------------------------------------------
; Routine $133: movea.l d0,a0 / move.w d1,(a0).
;------------------------------------------------------------------------------
emit_poke_word_swapped:
	move.l	#$20403081,(a2)+                ; routine $133: movea.l d0,a0 / move.w d1,(a0)
	rts

;------------------------------------------------------------------------------
; Routine $134 (LPOKE): movea.l d1,a0 / move.l d0,(a0).
;------------------------------------------------------------------------------
emit_poke_long:
	move.l	#$20412080,(a2)+                ; routine $134: movea.l d1,a0 / move.l d0,(a0)
	rts

;------------------------------------------------------------------------------
; Routine $135: movea.l d0,a0 / move.l d1,(a0).
;------------------------------------------------------------------------------
emit_poke_long_swapped:
	move.l	#$20402081,(a2)+                ; routine $135: movea.l d0,a0 / move.l d1,(a0)
	rts

;------------------------------------------------------------------------------
; Routine $116 (integer <): cmp.l d1,d0 / slt d2.
;------------------------------------------------------------------------------
emit_int_cmp_lt:
	moveq	#93,d1                          ; routine $116: $5d = slt
	bra.s	emit_int_cmp_d1

;------------------------------------------------------------------------------
; Routine $117 (integer <=): cmp.l d1,d0 / sle d2.
;------------------------------------------------------------------------------
emit_int_cmp_le:
	moveq	#95,d1                          ; routine $117: $5f = sle
	bra.s	emit_int_cmp_d1

;------------------------------------------------------------------------------
; Routine $119 (integer >=): cmp.l d1,d0 / sge d2.
;------------------------------------------------------------------------------
emit_int_cmp_ge:
	moveq	#92,d1                          ; routine $119: $5c = sge
	bra.s	emit_int_cmp_d1

;------------------------------------------------------------------------------
; Routine $118 (integer >): cmp.l d1,d0 / sgt d2.
;------------------------------------------------------------------------------
emit_int_cmp_gt:
	moveq	#94,d1                          ; routine $118: $5e = sgt
	bra.s	emit_int_cmp_d1

;------------------------------------------------------------------------------
; Routine $115 (integer <>): cmp.l d1,d0 / sne d2.
;------------------------------------------------------------------------------
emit_int_cmp_ne:
	moveq	#86,d1                          ; routine $115: $56 = sne
	bra.s	emit_int_cmp_d1

;------------------------------------------------------------------------------
; Routine $114 (integer =): cmp.l d1,d0 / seq d2.
;------------------------------------------------------------------------------
emit_int_cmp_eq:
	moveq	#87,d1                          ; routine $114: $57 = seq

;------------------------------------------------------------------------------
; cmp.l d1,d0 then Scc d2 / ext.w d2 with the condition byte in d1.
;------------------------------------------------------------------------------
emit_int_cmp_d1:
	move.w	#$b081,(a2)+                    ; $b081 = cmp.l d1,d0

;------------------------------------------------------------------------------
; Scc d2 / ext.w d2 (d1 = the Scc opcode's high byte), then skip_bool_test_ir.
;------------------------------------------------------------------------------
emit_scc_d2:
	move.b	d1,(a2)+                        ; Scc d2 with the condition byte in d1
	move.b	#$c2,(a2)+                      ; $c2: Scc into d2
	move.w	#$4882,(a2)+                    ; ext.w d2: bool result in d2

;------------------------------------------------------------------------------
; After a compare (bool already in d2): drops a following $fffc $fffd pair or a lone $fffd.
;------------------------------------------------------------------------------
skip_bool_test_ir:
	cmpi.w	#$fffc,(a1)                     ; IR $fffc $fffd after a compare: both are not needed
	bne.s	.check_fffd
	cmpi.w	#$fffd,2(a1)
	bne.s	.done
	addq.l	#4,a1
	rts
.check_fffd:
	cmpi.w	#$fffd,(a1)                     ; a bare tst.w d2 ($fffd) is not needed either
	bne.s	.done
	addq.l	#2,a1
.done:
	rts

;------------------------------------------------------------------------------
; Compare routines $e, $10, $16, $18: call the routine one below.
;------------------------------------------------------------------------------
emit_compare_routine_swapped:
	subq.w	#2,d0                           ; call the routine one below (operands the other way round)

;------------------------------------------------------------------------------
; Float compare routines ($c-$1b): jsr routine(a6), then skip_bool_test_ir.
;------------------------------------------------------------------------------
emit_compare_routine:
	bsr.w	emit_call_routine_index         ; float compare routine, result in d2
	bra.s	skip_bool_test_ir

;------------------------------------------------------------------------------
; Integer compare with a constant: slt.
;------------------------------------------------------------------------------
emit_int_const_cmp_lt:
	moveq	#93,d1
	bra.s	emit_int_const_cmp

;------------------------------------------------------------------------------
; Integer compare with a constant: sle.
;------------------------------------------------------------------------------
emit_int_const_cmp_le:
	moveq	#95,d1
	bra.s	emit_int_const_cmp

;------------------------------------------------------------------------------
; Integer compare with a constant: sge.
;------------------------------------------------------------------------------
emit_int_const_cmp_ge:
	moveq	#92,d1
	bra.s	emit_int_const_cmp

;------------------------------------------------------------------------------
; Integer compare with a constant: sgt.
;------------------------------------------------------------------------------
emit_int_const_cmp_gt:
	moveq	#94,d1
	bra.s	emit_int_const_cmp

;------------------------------------------------------------------------------
; Integer compare with a constant: sne.
;------------------------------------------------------------------------------
emit_int_const_cmp_ne:
	moveq	#86,d1
	bra.s	emit_int_const_cmp

;------------------------------------------------------------------------------
; Integer compare with a constant: seq.
;------------------------------------------------------------------------------
emit_int_const_cmp_eq:
	moveq	#87,d1

;------------------------------------------------------------------------------
; Compiler: compare of d0 with a constant (in d0 here), d1 = Scc condition:
; tst.l d0, subq/addq #n,d0 for 1..8 / -8..-1, otherwise cmpi.l #n,d0; then
; Scc d2 and ext.w d2.
;------------------------------------------------------------------------------
emit_int_const_cmp:
	tst.l	d0
	beq.s	.tst
	cmpi.l	#$8,d0
	bls.s	.subq
	cmpi.l	#$fffffff8,d0
	bcc.s	.addq
	move.w	#$c80,(a2)+                     ; $0c80 = cmpi.l #imm,d0
	move.l	d0,(a2)+
	bra.s	emit_scc_d2
.tst:
	move.w	#$4a80,(a2)+                    ; $4a80 = tst.l d0
	bra.s	emit_scc_d2                     ; then Scc d2
.subq:
	move.w	#$5180,d2                       ; $5180 = subq.l #n,d0
	bra.s	.quick                          ; quick form
.addq:
	move.w	#$5080,d2                       ; $5080 = addq.l #n,d0 (negative constant)
	neg.l	d0                              ; n = -constant
.quick:
	andi.w	#$7,d0                          ; quick value 8 is 0 in the opcode
	ror.w	#7,d0                           ; value into bits 9-11
	or.w	d2,d0                           ; with the opcode
	move.w	d0,(a2)+                        ; store it
	bra.s	emit_scc_d2                     ; then Scc d2

;------------------------------------------------------------------------------
; Compiler: d0 = int constant that will be the second operand. If the next
; IR word is an int routine that can take an immediate (compare, AND, OR,
; add, subtract), emits it with the constant and returns to the caller's
; caller; otherwise puts the routine word back and returns normally.
;------------------------------------------------------------------------------
fold_int_constant_op:
	move.w	(a1)+,d1                        ; d1 = the routine after the constant
	move.l	(sp)+,d7                        ; return address: dropped if the constant is folded
	cmpi.w	#$114,d1                        ; routine $114-$119: int compares
	beq.s	emit_int_const_cmp_eq
	cmpi.w	#$115,d1
	beq.s	emit_int_const_cmp_ne
	cmpi.w	#$116,d1
	beq.s	emit_int_const_cmp_lt
	cmpi.w	#$117,d1
	beq.s	emit_int_const_cmp_le
	cmpi.w	#$119,d1
	beq.s	emit_int_const_cmp_ge
	cmpi.w	#$118,d1
	beq.s	emit_int_const_cmp_gt
	cmpi.w	#$0,d1                          ; routine 0: AND
	beq.s	.and_const
	cmpi.w	#$1,d1                          ; routine 1: OR
	beq.s	emit_or_l_imm
	cmpi.w	#$111,d1                        ; routine $111: add
	beq.s	emit_add_imm
	cmpi.w	#$112,d1                        ; routine $112: subtract
	beq.s	emit_sub_imm
	cmpi.w	#$113,d1                        ; routine $113: reverse subtract
	beq.s	emit_reverse_sub_imm
	move.l	d7,-(sp)                        ; not foldable: normal return, routine word unread
	subq.l	#2,a1                           ; un-read the routine word
	rts
.moveq_zero:
	move.w	#$7000,(a2)+                    ; AND with 0: moveq #0,d0
	rts
.and_const:
	tst.l	d0                              ; AND with 0?
	beq.s	.moveq_zero
	move.w	#$280,(a2)+                     ; $0280 = andi.l #imm,d0

;------------------------------------------------------------------------------
; Writes the long constant d0 and returns to the caller's caller.
;------------------------------------------------------------------------------
emit_long_operand:
	move.l	d0,(a2)+                        ; the 32-bit constant

;------------------------------------------------------------------------------
; Shared return of fold_int_constant_op.
;------------------------------------------------------------------------------
fold_int_constant_done:
	rts                                     ; back to the caller's caller (routine consumed)

;------------------------------------------------------------------------------
; OR with a constant: ori.l #n,d0 (nothing for 0).
;------------------------------------------------------------------------------
emit_or_l_imm:
	tst.l	d0                              ; OR with 0 generates nothing
	beq.s	fold_int_constant_done
	move.w	#$80,(a2)+                      ; $0080 = ori.l #imm,d0
	bra.s	emit_long_operand               ; the constant follows

;------------------------------------------------------------------------------
; Add a constant: addq.l for 1..8, otherwise addi.l #n,d0.
;------------------------------------------------------------------------------
emit_add_imm:
	cmpi.l	#$8,d0                          ; 1..8 (as unsigned): addq
	bls.s	emit_addq_d0
	move.w	#$680,(a2)+                     ; $0680 = addi.l #imm,d0
	bra.s	emit_long_operand               ; the constant follows

;------------------------------------------------------------------------------
; Subtract a constant: subq.l for 1..8, otherwise subi.l #n,d0.
;------------------------------------------------------------------------------
emit_sub_imm:
	cmpi.l	#$8,d0                          ; 1..8 (as unsigned): subq
	bls.s	.subq
	move.w	#$480,(a2)+                     ; $0480 = subi.l #imm,d0
	bra.s	emit_long_operand               ; the constant follows
.subq:
	move.w	#$5180,d1                       ; $5180 = subq.l #n,d0
	bra.s	emit_quick_d0                   ; quick form

;------------------------------------------------------------------------------
; addq.l #n,d0 (n = 1..8 in d0).
;------------------------------------------------------------------------------
emit_addq_d0:
	move.w	#$5080,d1                       ; $5080 = addq.l #n,d0

;------------------------------------------------------------------------------
; Quick add or subtract: d1 = opcode, d0 = 1..8 (nothing for 0), trapv when on.
;------------------------------------------------------------------------------
emit_quick_d0:
	tst.w	d0                              ; adding or subtracting 0 generates nothing
	beq.s	fold_int_constant_done
	andi.w	#$7,d0                          ; quick value 8 is 0 in the opcode
	ror.w	#7,d0                           ; value into bits 9-11
	or.w	d1,d0                           ; with the opcode
	move.w	d0,(a2)+                        ; store it
	bra.w	emit_trapv_if_enabled           ; trapv after it when Trapv is on

;------------------------------------------------------------------------------
; Reverse subtract of a constant: subtract, then neg.l d0.
;------------------------------------------------------------------------------
emit_reverse_sub_imm:
	bsr.s	emit_sub_imm                    ; subtract, then negate

;------------------------------------------------------------------------------
; Routine $12a (integer negate): neg.l d0, trapv when on.
;------------------------------------------------------------------------------
emit_int_neg:
	move.w	#$4480,(a2)+                    ; routine $12a: $4480 = neg.l d0
	bra.w	emit_trapv_if_enabled

;------------------------------------------------------------------------------
; Compiler, IR $ffc9: an int variable as the second operand of the next
; routine (2(a1)): add/sub/AND/OR/compare straight from the variable, or
; move.l var,d1 for any other routine.
;------------------------------------------------------------------------------
emit_int_var_operand:
	move.w	#$222d,d0                       ; $222d = move.l d16(a5),d1; $2210 = move.l (a0),d1
	move.w	#$2210,d7
	move.w	2(a1),d1                        ; d1 = the routine that uses the variable
	cmpi.w	#$0,d1                          ; routine 0: AND
	beq.s	emit_and_int_var
	cmpi.w	#$1,d1                          ; routine 1: OR
	beq.s	emit_or_int_var
	cmpi.w	#$112,d1                        ; routine $112: subtract
	beq.s	emit_sub_int_var
	cmpi.w	#$113,d1                        ; routine $113: reverse subtract
	beq.s	emit_reverse_sub_int_var
	cmpi.w	#$114,d1                        ; routines $114-$119: compares
	beq.s	emit_int_var_cmp_eq
	cmpi.w	#$115,d1
	beq.s	emit_int_var_cmp_ne
	cmpi.w	#$116,d1
	beq.s	emit_int_var_cmp_lt
	cmpi.w	#$117,d1
	beq.s	emit_int_var_cmp_le
	cmpi.w	#$119,d1
	beq.s	emit_int_var_cmp_ge
	cmpi.w	#$118,d1
	beq.s	emit_int_var_cmp_gt
	cmpi.w	#$111,d1                        ; not one of these: plain move.l var,d1 (routine read next)
	bne.w	emit_int_var_access
	move.w	#$d0ad,d0                       ; routine $111: $d0ad = add.l d16(a5),d0
	move.w	#$d090,d7                       ; (a0) form for a far variable

;------------------------------------------------------------------------------
; Emits d0 / d7 for the variable, consumes the routine word, trapv when on.
;------------------------------------------------------------------------------
emit_int_var_arith_trapv:
	bsr.s	emit_int_var_access_skip        ; emit it and skip the routine word
	bra.w	emit_trapv_if_enabled           ; then trapv when Trapv is on

;------------------------------------------------------------------------------
; Routine $112 with an integer variable: sub.l var,d0.
;------------------------------------------------------------------------------
emit_sub_int_var:
	move.w	#$90ad,d0                       ; routine $112: $90ad = sub.l d16(a5),d0
	move.w	#$9090,d7                       ; (a0) form for a far variable
	bra.s	emit_int_var_arith_trapv        ; emit it and skip the routine, trapv when on

;------------------------------------------------------------------------------
; Routine $113 with an integer variable: sub.l var,d0, then emit_float_neg, which writes
; bchg #31,d2 rather than neg.l d0.
;------------------------------------------------------------------------------
emit_reverse_sub_int_var:
	bsr.s	emit_sub_int_var                ; sub.l var,d0 ...
	bra.w	emit_float_neg                  ; routine $113: emits bchg #31,d2 here, where $12a emits neg.l d0

;------------------------------------------------------------------------------
; Routine 0 with an integer variable: and.l var,d0.
;------------------------------------------------------------------------------
emit_and_int_var:
	move.w	#$c0ad,d0                       ; routine 0: $c0ad = and.l d16(a5),d0
	move.w	#$c090,d7                       ; (a0) form for a far variable

;------------------------------------------------------------------------------
; Emits d0 / d7 for the integer variable and consumes the routine word.
;------------------------------------------------------------------------------
emit_int_var_access_skip:
	bsr.w	emit_int_var_access             ; the opcode with the variable offset from the IR
	addq.l	#2,a1                           ; skip the routine word
	rts

;------------------------------------------------------------------------------
; Routine 1 with an integer variable: or.l var,d0.
;------------------------------------------------------------------------------
emit_or_int_var:
	move.w	#$80ad,d0                       ; routine 1: $80ad = or.l d16(a5),d0
	move.w	#$8090,d7                       ; (a0) form for a far variable
	bra.s	emit_int_var_access_skip        ; emit it and skip the routine word

;------------------------------------------------------------------------------
; Compare with an integer variable: slt.
;------------------------------------------------------------------------------
emit_int_var_cmp_lt:
	moveq	#93,d1                          ; $5d = slt
	bra.s	emit_int_var_cmp                ; compare with the variable

;------------------------------------------------------------------------------
; Compare with an integer variable: sle.
;------------------------------------------------------------------------------
emit_int_var_cmp_le:
	moveq	#95,d1                          ; $5f = sle
	bra.s	emit_int_var_cmp                ; compare with the variable

;------------------------------------------------------------------------------
; Compare with an integer variable: sge.
;------------------------------------------------------------------------------
emit_int_var_cmp_ge:
	moveq	#92,d1                          ; $5c = sge
	bra.s	emit_int_var_cmp                ; compare with the variable

;------------------------------------------------------------------------------
; Compare with an integer variable: sgt.
;------------------------------------------------------------------------------
emit_int_var_cmp_gt:
	moveq	#94,d1                          ; $5e = sgt
	bra.s	emit_int_var_cmp                ; compare with the variable

;------------------------------------------------------------------------------
; Compare with an integer variable: sne.
;------------------------------------------------------------------------------
emit_int_var_cmp_ne:
	moveq	#86,d1                          ; $56 = sne
	bra.s	emit_int_var_cmp                ; compare with the variable

;------------------------------------------------------------------------------
; Compare with an integer variable: seq.
;------------------------------------------------------------------------------
emit_int_var_cmp_eq:
	moveq	#87,d1                          ; $57 = seq

;------------------------------------------------------------------------------
; cmp.l var,d0 then Scc d2 / ext.w d2 (d1 = condition byte).
;------------------------------------------------------------------------------
emit_int_var_cmp:
	move.b	d1,-(sp)                        ; keep the condition
	move.w	#$b0ad,d0                       ; $b0ad = cmp.l d16(a5),d0
	move.w	#$b090,d7                       ; $b090 = cmp.l (a0),d0
	bsr.s	emit_int_var_access_skip        ; emit it and skip the routine word
	move.b	(sp)+,d1                        ; condition back
	bra.w	emit_scc_d2                     ; Scc d2 / ext.w d2

;------------------------------------------------------------------------------
; Compiler, IR $ffae: address of a runtime system variable d16(a4) into d0
; (lea d(a4),a0 / move.l a0,d0); followed by routine $32/$33/$34 the read is
; done directly: moveq #0,d0 + move.b/move.w d(a4),d0, or move.l d(a4),d0.
;------------------------------------------------------------------------------
emit_sysvar_address:
	cmpi.w	#$32,2(a1)                      ; routine $32: byte read of the address
	beq.s	.peek_byte
	cmpi.w	#$33,2(a1)                      ; routine $33: word read
	beq.s	.peek_word
	cmpi.w	#$34,2(a1)                      ; routine $34: long read
	beq.s	.peek_long
	move.w	#$41ec,(a2)+                    ; $41ec = lea d16(a4),a0
	move.w	(a1)+,(a2)+                     ; the offset
	move.w	#$2008,(a2)+                    ; move.l a0,d0
	rts
.peek_long:
	move.w	#$202c,d0                       ; $202c = move.l d16(a4),d0
	bra.s	emit_a4_access                  ; emit it and skip the routine word
.peek_byte:
	move.w	#$102c,d0                       ; $102c = move.b d16(a4),d0
	bra.s	.clear_d0                       ; byte and word reads clear d0 first
.peek_word:
	move.w	#$302c,d0                       ; $302c = move.w d16(a4),d0
.clear_d0:
	move.w	#$7000,(a2)+                    ; moveq #0,d0 first

;------------------------------------------------------------------------------
; Emits the opcode d0 with the d16(a4) offset from the IR and consumes the routine word.
;------------------------------------------------------------------------------
emit_a4_access:
	move.w	d0,(a2)+                        ; the opcode
	move.w	(a1)+,(a2)+                     ; the d16(a4) offset
	addq.l	#2,a1                           ; skip the routine word
	rts

;------------------------------------------------------------------------------
; System variable then POKE: move.b d0,d16(a4).
;------------------------------------------------------------------------------
emit_poke_byte_sysvar:
	move.w	#$1940,d0                       ; $1940 = move.b d0,d16(a4)
	bra.s	emit_a4_access                  ; emit it and skip the routine word

;------------------------------------------------------------------------------
; System variable then DPOKE: move.w d0,d16(a4).
;------------------------------------------------------------------------------
emit_poke_word_sysvar:
	move.w	#$3940,d0                       ; $3940 = move.w d0,d16(a4)
	bra.s	emit_a4_access                  ; emit it and skip the routine word

;------------------------------------------------------------------------------
; System variable then LPOKE: move.l d0,d16(a4).
;------------------------------------------------------------------------------
emit_poke_long_sysvar:
	move.w	#$2940,d0                       ; $2940 = move.l d0,d16(a4)
	bra.s	emit_a4_access                  ; emit it and skip the routine word

;------------------------------------------------------------------------------
; IR $ffad: address of a system variable into d1 (lea d(a4),a0 / move.l a0,d1); followed by
; routine $130/$132/$134 the write goes straight to d(a4).
;------------------------------------------------------------------------------
emit_sysvar_address_d1:
	cmpi.w	#$130,2(a1)                     ; IR $ffad: followed by routine $130/$132/$134 (write)?
	beq.s	emit_poke_byte_sysvar
	cmpi.w	#$132,2(a1)                     ; routine $132: word write
	beq.s	emit_poke_word_sysvar
	cmpi.w	#$134,2(a1)                     ; routine $134: long write
	beq.s	emit_poke_long_sysvar
	move.w	#$41ec,(a2)+                    ; lea d16(a4),a0 / move.l a0,d1
	move.w	(a1)+,(a2)+                     ; the offset
	move.w	#$2208,(a2)+                    ; $2208 = move.l a0,d1
	rts

;------------------------------------------------------------------------------
; IR $ffab: moveq #n,d3 / jsr routine $148 (power of two applied to the float: exponent add).
;------------------------------------------------------------------------------
emit_moveq_d3_call_148:
	move.w	(a1)+,d0                        ; IR $ffab: moveq #n,d3 / jsr routine $148
	move.b	#$76,(a2)+                      ; $76 = moveq #n,d3
	move.b	d0,(a2)+                        ; n
	move.w	#$148,d0                        ; then routine $148
	bra.w	emit_call_routine

;------------------------------------------------------------------------------
; Integer constant (d0) stored straight into an integer variable: move.l #n,var, or clr.l var
; for 0.
;------------------------------------------------------------------------------
emit_store_int_constant:
	move.l	d0,-(sp)                        ; constant then $ffd5: store it straight into the int variable
	beq.s	.zero
	addq.l	#2,a1                           ; consume the $ffd5
	move.w	#$2b7c,d0                       ; $2b7c = move.l #imm,d16(a5); $20bc = move.l #imm,(a0)
	move.w	#$20bc,d7
	pea	(a2)                            ; start of this code
	bsr.w	emit_int_var_access             ; the opcode with the variable offset
	move.l	(sp)+,d0                        ; start of this code
	addq.l	#4,d0                           ; short form: opcode and offset only so far
	cmpa.l	d0,a2
	beq.s	.short_form
	move.l	(sp)+,(a2)+                     ; long form: the constant follows the opcode
	rts
.short_form:
	move.w	-(a2),d0                        ; constant between the opcode and the offset
	move.l	(sp)+,(a2)+                     ; insert the constant ...
	move.w	d0,(a2)+                        ; ... then the offset after it
	rts
.zero:
	addq.l	#4,sp                           ; drop the constant: zero is a clr.l
	addq.l	#2,a1                           ; consume the $ffd5

;------------------------------------------------------------------------------
; IR $ff95: clear an integer variable.
;------------------------------------------------------------------------------
emit_clear_int_var:
	move.w	#$42ad,d0                       ; IR $ff95: $42ad = clr.l d16(a5); $4290 = clr.l (a0)
	move.w	#$4290,d7
	bra.w	emit_int_var_access             ; emit it with the variable offset from the IR

;------------------------------------------------------------------------------
; IR $ff97: store the float 0 in a variable.
;------------------------------------------------------------------------------
emit_clear_float_var:
	moveq	#0,d1                           ; IR $ff97: store the float 0 into a variable
	move.l	d1,-(sp)                        ; mantissa 0 ...
	move.w	d1,-(sp)                        ; ... exponent 0
	bra.s	emit_store_float_const_var      ; store it

;------------------------------------------------------------------------------
; Float constant then $ffd6: stores the constant straight into the variable.
;------------------------------------------------------------------------------
emit_store_float_constant:
	move.l	(a1)+,-(sp)                     ; mantissa and exponent of the constant
	move.w	(a1)+,d1                        ; d1 = mantissa low bits and exponent
	move.w	d1,-(sp)                        ; (pushed)
	addq.l	#2,a1                           ; skip the $ffd6 store word

;------------------------------------------------------------------------------
; Stores the float constant on the stack (long, word) in the float variable from the IR:
; move.l #m,(a0)+ / move.w #n,(a0), or one clr.w of the exponent word for 0.
;------------------------------------------------------------------------------
emit_store_float_const_var:
	pea	(a2)                            ; start of this code
	bsr.w	emit_lea_float_var              ; lea float var,a0 (variable number from the IR)
	move.l	(sp)+,d2                        ; d2 = start of this code
	move.w	(sp)+,d1                        ; d1 = low word
	move.l	(sp)+,d0                        ; d0 = mantissa long
	addq.l	#4,d2                           ; d2 = end of a short lea (4 bytes)
	move.w	d1,d3                           ; exponent bits ...
	andi.w	#$3ff,d3                        ; value zero?
	beq.s	.zero
	move.w	#$20fc,(a2)+                    ; $20fc = move.l #imm,(a0)+
	move.l	d0,(a2)+                        ; the mantissa long
	move.w	#$30bc,(a2)+                    ; $30bc = move.w #imm,(a0)
	move.w	d1,(a2)+                        ; the low word
	rts
.zero:
	cmp.l	a2,d2                           ; was the lea the short form?
	beq.s	.short_form
	move.w	#$4250,-$2(a2)                  ; long form: clr.w (a0) at address + 4
	addq.l	#4,-$6(a2)                      ; ... with the adda.l offset raised by 4
	rts
.short_form:
	move.w	#$426d,-$4(a2)                  ; clr.w d16(a5) at offset + 4 (exponent word 0 = value 0)
	addq.w	#4,-$2(a2)                      ; ... with the offset raised by 4
	rts

;------------------------------------------------------------------------------
; Float variable copied to a float variable ($fff3 var $ffd6 var): lea source,a1 / lea
; destination,a0 / move.l (a1)+,(a0)+ / move.w (a1),(a0). For a source out of d16 reach the
; opcode fix-up is applied to the IR (a1) instead of the code, so that case is wrong.
;------------------------------------------------------------------------------
emit_copy_float_var:
	pea	(a2)                            ; float variable to float variable: lea source,a0
	bsr.w	emit_lea_float_var
	move.l	(sp)+,d0                        ; start of this code
	addq.l	#4,d0                           ; + 4: end of a short lea
	cmpa.l	d0,a2                           ; was the source lea the short form?
	beq.s	.short_form
	addq.b	#2,-$8(a1)                      ; long form: +2 to the opcode bytes makes a0 into a1, but at -8(a1),
	addq.b	#2,-$6(a1)                      ; -6(a1): the IR pointer, not a2, so the code is not changed
	bra.s	.emit_copy
.short_form:
	addq.b	#2,-$4(a2)                      ; $41ed + $0200 = $43ed: the source lea now loads a1
.emit_copy:
	addq.l	#2,a1                           ; consume the $ffd6
	bsr.w	emit_lea_float_var              ; lea destination,a0
	move.l	#$20d93091,(a2)+                ; move.l (a1)+,(a0)+ / move.w (a1),(a0)
	rts

;------------------------------------------------------------------------------
; IR $ffaa: copy d0-d2 to d3-d5.
;------------------------------------------------------------------------------
emit_copy_float_d3_d5:
	move.l	#$26003801,(a2)+                ; IR $ffaa: move.l d0,d3 / move.l d1,d4 / move.l d2,d5
	move.w	#$2a02,(a2)+                    ; $2a02 = move.l d2,d5
	rts

;------------------------------------------------------------------------------
; IR $ffa9: move.l d0,d1.
;------------------------------------------------------------------------------
emit_move_d0_d1:
	move.w	#$2200,(a2)+                    ; IR $ffa9: $2200 = move.l d0,d1
	rts

;------------------------------------------------------------------------------
; IR $ffa7: push the low byte of d0.
;------------------------------------------------------------------------------
emit_push_byte_d0:
	move.w	#$1f00,(a2)+                    ; IR $ffa7: $1f00 = move.b d0,-(sp)
	rts

;------------------------------------------------------------------------------
; IR $ffa6: asl.b #4,d0 / move.b d0,1(sp) (a nibble into the pushed byte).
;------------------------------------------------------------------------------
emit_merge_nibble:
	move.w	tpl_asl_b_4_d0,(a2)+            ; IR $ffa6: asl.b #4,d0 / move.b d0,1(sp)
	move.l	#$1f400001,(a2)+                ; $1f400001 = move.b d0,1(sp)
	rts

;------------------------------------------------------------------------------
; IR $ffa5: or.w d0,(sp).
;------------------------------------------------------------------------------
emit_or_w_d0_sp:
	move.w	#$8157,(a2)+                    ; IR $ffa5: $8157 = or.w d0,(sp)
	rts

;------------------------------------------------------------------------------
; Template: asl.b #4,d0.
;------------------------------------------------------------------------------
tpl_asl_b_4_d0:
	asl.b	#4,d0                           ; template: asl.b #4,d0

;------------------------------------------------------------------------------
; String constant followed by routine $121: emit_inline_string_alt, then consume the $121.
;------------------------------------------------------------------------------
emit_inline_string_skip:
	bsr.s	emit_inline_string_alt          ; the string constant
	addq.l	#2,a1                           ; consume the routine $121 too
	rts

;------------------------------------------------------------------------------
; Compiler: string constant whose next IR word is routine $121. d7 = length:
; 0 emits nothing, 1 emits moveq #char,d0 + routine $123, longer ones routine
; $e7 (even) or $e8 (odd length) with the text inline.
;------------------------------------------------------------------------------
emit_inline_string_alt:
	cmpi.w	#$1,d7                          ; length 0: nothing
	bmi.s	.done                           ; (negative cannot happen)
	beq.s	.one_char                       ; length 1: one character
	move.w	#$e7,d0                         ; routine $e7 with the text inline (even length)
	btst	#$0,d7                          ; odd length?
	beq.s	emit_routine_with_string        ; no: $e7
	move.w	#$e8,d0                         ; odd: routine $e8
	bra.s	emit_routine_with_string        ; jsr, length word and text
.done:
	rts
.one_char:
	move.w	#$123,d0                        ; routine $123 with the character in d0
	bra.s	emit_moveq_d0_char_call         ; moveq #c,d0 / jsr routine $123

;------------------------------------------------------------------------------
; Compiler, IR $ffd7: string constant. d7 = length from the IR, the text
; follows in words. Empty: lea $ad2(a4),a0; one char: moveq #c,d0 + routine
; $42; otherwise jsr routine $e2 (even length) / $e3 (odd) followed by
; [len.w][chars] inline.
;------------------------------------------------------------------------------
emit_inline_string:
	move.w	(a1)+,d7                        ; d7 = string length
	move.w	d7,d0                           ; words of text
	addq.w	#1,d0
	andi.w	#$fffe,d0
	cmpi.w	#$121,0(a1,d0.w)                ; routine $121 after the text?
	beq.s	emit_inline_string_skip         ; yes: emitted the other way
	cmpi.w	#$1,d7                          ; length 0?
	bmi.s	emit_empty_string               ; yes: lea of the empty string
	beq.s	emit_one_char_string            ; length 1: moveq #c,d0 and routine $42
	move.w	#$e2,d0                         ; routine $e2 for even lengths
	btst	#$0,d7                          ; odd length?
	beq.s	emit_routine_with_string        ; no: $e2
	move.w	#$e3,d0                         ; odd: routine $e3

;------------------------------------------------------------------------------
; jsr routine d0, then the length word and the text inline after it (d7 = length).
;------------------------------------------------------------------------------
emit_routine_with_string:
	bsr.s	emit_call_routine_jump          ; jsr routine(a6)
	move.w	d7,(a2)+                        ; length word after the jsr
	subq.w	#1,d7                           ; words of text - 1 for the dbra
	lsr.w	#1,d7                           ; (length + 1) / 2 words
.copy_chars:
	move.w	(a1)+,(a2)+                     ; the text words from the IR (pad byte as it is there)
	dbra	d7,.copy_chars
	rts

;------------------------------------------------------------------------------
; Empty string constant: lea $ad2(a4),a0.
;------------------------------------------------------------------------------
emit_empty_string:
	move.l	tpl_lea_ad2_a4_a0,(a2)+         ; lea $ad2(a4),a0 (empty string in the runtime variables)
	rts

;------------------------------------------------------------------------------
; Template: lea $ad2(a4),a0.
;------------------------------------------------------------------------------
tpl_lea_ad2_a4_a0:
	lea	$ad2(a4),a0                     ; template: lea $ad2(a4),a0

;------------------------------------------------------------------------------
; bra to emit_call_routine (in short reach of its callers).
;------------------------------------------------------------------------------
emit_call_routine_jump:
	bra.w	emit_call_routine

;------------------------------------------------------------------------------
; One-character string constant: moveq #c,d0 / jsr routine $42.
;------------------------------------------------------------------------------
emit_one_char_string:
	move.w	#$42,d0                         ; routine $42 with the character in d0

;------------------------------------------------------------------------------
; moveq #c,d0 (the character from the IR) and a call of routine d0.
;------------------------------------------------------------------------------
emit_moveq_d0_char_call:
	move.b	#$70,(a2)+                      ; moveq #char,d0
	move.b	(a1),(a2)+                      ; the character (first byte of the text word)
	addq.l	#2,a1                           ; step over the text word
	bra.s	emit_call_routine_jump          ; jsr routine(a6)

;------------------------------------------------------------------------------
; IR $ffc7: should not occur; fatal internal error "*$*".
;------------------------------------------------------------------------------
codegen_error_dollar:
	bsr.w	compile_error_fatal             ; IR $ffc7: internal error "*$*"
	dc.w	$2a24,$2a00

;------------------------------------------------------------------------------
; IR $ff96: lea string var,a0 / jsr routine $177.
;------------------------------------------------------------------------------
emit_string_var_call_177:
	bsr.w	emit_lea_string_var             ; IR $ff96: lea string var,a0 / jsr routine $177
	move.w	#$177,d0                        ; routine $177
	bra.w	emit_call_routine               ; jsr routine(a6)

;------------------------------------------------------------------------------
; IR $ffd3: string assignment: lea string var,a1 / jsr routine $e6.
;------------------------------------------------------------------------------
emit_string_assign:
	bsr.s	emit_lea_string_var_a1          ; IR $ffd3: lea string var,a1 / jsr routine $e6
	move.w	#$e6,d0                         ; routine $e6 assigns a string
	bra.w	emit_call_routine               ; jsr routine(a6)

;------------------------------------------------------------------------------
; lea string var,a1 (number from the IR).
;------------------------------------------------------------------------------
emit_lea_string_var_a1:
	move.l	bss_end+$40,d0                  ; string descriptors, 6 bytes each

;------------------------------------------------------------------------------
; lea var,a1 for a 6-byte variable (d0 = type offset, number from the IR).
;------------------------------------------------------------------------------
emit_lea_var_a1:
	move.w	(a1)+,d1                        ; variable number * 6
	mulu.w	#$6,d1

;------------------------------------------------------------------------------
; lea d16(a5),a1 or the long movea.l a5,a1 / adda.l form (d0 + d1 = offset).
;------------------------------------------------------------------------------
emit_lea_offset_a1:
	add.l	d1,d0                           ; d0 = offset of the variable
	cmpi.l	#$ffff,d0                       ; fits a d16 displacement? (bound $ffff, the others use $fff9)
	bhi.s	.long_offset                    ; no: the long form
	subi.w	#$8000,d0                       ; minus the $8000 bias of a5
	move.w	#$43ed,(a2)+                    ; $43ed = lea d16(a5),a1
	move.w	d0,(a2)+                        ; the displacement
	rts
.long_offset:
	move.l	#$224dd3fc,(a2)+                ; movea.l a5,a1 / adda.l #imm,a1
	subi.l	#$8000,d0                       ; minus the $8000 bias
	move.l	d0,(a2)+                        ; the long offset
	rts

;------------------------------------------------------------------------------
; Routine $149: add.l d0,d0 (integer times 2), trapv when on.
;------------------------------------------------------------------------------
emit_add_d0_d0:
	move.w	tpl_add_l_d0_d0,(a2)+           ; routine $149: add.l d0,d0, trapv when on
	bra.w	emit_trapv_if_enabled           ; trapv after it when Trapv is on

;------------------------------------------------------------------------------
; IR $ffe2: move.l descriptor,d0: the string's address from its descriptor.
;------------------------------------------------------------------------------
emit_load_string_pointer:
	move.w	#$202d,d0                       ; IR $ffe2: move.l string descriptor,d0 (its address long)
	move.w	#$2010,d7                       ; $2010 = move.l (a0),d0 for a far variable
	move.l	bss_end+$40,d6                  ; string descriptors ...
	moveq	#6,d5                           ; ... 6 bytes each
	bra.w	emit_var_access                 ; the address long is the descriptor's first long

;------------------------------------------------------------------------------
; IR $ffde: bool array with routines $270 (several indices) / $271 (one).
