emit_bool_array_call_270:
	move.w	#$270,d2                        ; IR $ffde: bool array, routines $270/$271
	move.w	#$271,d3                        ; one index: routine $271
	bra.w	emit_bool_array_call            ; emit the array call

;------------------------------------------------------------------------------
; IR $ffe1: float array with routines $264 / $265.
