	bra.w	emit_call_routine               ; jsr routine(a6)

;------------------------------------------------------------------------------
; IR words of the add/subtract group that should not occur: fatal "* Mkadd *".
;------------------------------------------------------------------------------
codegen_error_mkadd:
	bsr.w	compile_error_fatal             ; unused IR words of the add/sub group: "* Mkadd *"
	dc.b	'* Mkadd *',0

;------------------------------------------------------------------------------
; IR $ffca: lea string var,a1.
;------------------------------------------------------------------------------
emit_lea_string_desc_a1:
	move.l	bss_end+$40,d0                  ; IR $ffca: lea string var,a1
	move.w	(a1)+,d1                        ; d1 = variable number
	mulu.w	#$6,d1                          ; * 6 bytes
	add.l	d1,d0                           ; d0 = offset of the descriptor
	cmpi.l	#$fff9,d0                       ; beyond d16 reach?
	bhi.s	.long_offset                    ; yes: the long form
	subi.w	#$8000,d0                       ; minus the $8000 bias of a5
	move.w	#$43ed,(a2)+                    ; $43ed = lea d16(a5),a1
	move.w	d0,(a2)+                        ; the displacement
	rts
.long_offset:
	move.l	#$224dd3fc,(a2)+                ; movea.l a5,a1 / adda.l #offset,a1
	subi.l	#$8000,d0                       ; minus the $8000 bias
	move.l	d0,(a2)+                        ; the long offset
	rts

;------------------------------------------------------------------------------
; String descriptor pushed: pea d16(a5) (d0 = type offset, number from the IR); out of d16
; reach only the long lea is emitted.
;------------------------------------------------------------------------------
emit_pea_string_var:
	move.w	(a1)+,d1                        ; string variable pushed: pea d16(a5)
	mulu.w	#$6,d1                          ; * 6 bytes
	add.l	d1,d0                           ; + type offset (in d0)
	cmpi.l	#$fff9,d0                       ; beyond d16 reach?
	bhi.w	emit_lea_var_long               ; yes: movea.l a5,a0 / adda.l (the pea is left out)
	subi.w	#$8000,d0                       ; minus the $8000 bias of a5
	move.w	#$486d,(a2)+                    ; $486d = pea d16(a5)
	move.w	d0,(a2)+                        ; the displacement
	addq.l	#2,a1                           ; skip the $fff7 push word
	rts

;------------------------------------------------------------------------------
; IR $ff9c: pop an integer into d0.
;------------------------------------------------------------------------------
emit_pop_long_d0:
	move.w	#$201f,(a2)+                    ; IR $ff9c: $201f = move.l (sp)+,d0
	rts

