; Routine $c4: st $86e(a4) (sets a runtime flag; its use is not worked out here).
;------------------------------------------------------------------------------
emit_set_flag_86e:
	move.l	#$50ec086e,(a2)+                ; routine $c4: $50ec086e = st $86e(a4) (a runtime flag)
	rts

;------------------------------------------------------------------------------
; IR $ff9b: address of a float array descriptor into a0 (a1 before routine $19a).
;------------------------------------------------------------------------------
emit_float_array_descriptor:
	move.l	bss_end+$4c,d0                  ; IR $ff9b: lea float array descriptor
	bra.s	emit_array_descriptor           ; lea it

;------------------------------------------------------------------------------
; IR $ff9a: address of a string array descriptor.
;------------------------------------------------------------------------------
emit_string_array_descriptor:
	move.l	bss_end+$50,d0                  ; IR $ff9a
	bra.s	emit_array_descriptor           ; lea it

;------------------------------------------------------------------------------
; IR $ff99: address of an integer array descriptor.
;------------------------------------------------------------------------------
emit_int_array_descriptor:
	move.l	bss_end+$54,d0                  ; IR $ff99
	bra.s	emit_array_descriptor           ; lea it

;------------------------------------------------------------------------------
; IR $ff98: address of a bool array descriptor.
;------------------------------------------------------------------------------
emit_bool_array_descriptor:
	move.l	bss_end+$58,d0                  ; IR $ff98

;------------------------------------------------------------------------------
; Array descriptor address (d0 = type offset): into a1 and routine $19a consumed when that
; routine follows, else into a0.
;------------------------------------------------------------------------------
emit_array_descriptor:
	cmpi.w	#$19a,2(a1)                     ; routine $19a next: lea into a1, else into a0
	bne.w	emit_lea_var_6byte              ; not $19a: lea descriptor,a0
	bsr.w	emit_lea_var_a1                 ; lea descriptor,a1
	addq.l	#2,a1                           ; consume the routine word (routine $19a not called)
	rts

;------------------------------------------------------------------------------
; Template: movem.l (sp)+,d0-d2.
;------------------------------------------------------------------------------
tpl_movem_pop_d0_d2:
	movem.l	(sp)+,d0-d2                     ; template: movem.l (sp)+,d0-d2

;------------------------------------------------------------------------------
; Template: move.l (sp)+,d0.
;------------------------------------------------------------------------------
tpl_pop_l_d0:
	move.l	(sp)+,d0                        ; template: move.l (sp)+,d0

;------------------------------------------------------------------------------
; Template: movea.l (sp)+,a1.
;------------------------------------------------------------------------------
tpl_pop_a1:
	movea.l	(sp)+,a1                        ; template: movea.l (sp)+,a1

;------------------------------------------------------------------------------
; Template: move.w (sp)+,d2.
;------------------------------------------------------------------------------
tpl_pop_w_d2:
	move.w	(sp)+,d2                        ; template: move.w (sp)+,d2

;------------------------------------------------------------------------------
; IR $ff8d: move.l (sp)+,d0, then lea int var,a0 / jsr routine $17e.
;------------------------------------------------------------------------------
emit_pop_int_var_call_17e:
	move.w	tpl_pop_l_d0(pc),(a2)+          ; IR $ff8d: move.l (sp)+,d0, then lea int var + routine $17e
	move.w	#$17e,-(sp)                     ; routine number for the end
	bra.s	emit_int_var_routine            ; lea the variable, then the call

;------------------------------------------------------------------------------
; IR $ff91: lea int var,a0 / jsr routine $17a.
;------------------------------------------------------------------------------
emit_int_var_call_17a:
	move.w	#$17a,-(sp)                     ; IR $ff91: lea int var + routine $17a

;------------------------------------------------------------------------------
; lea int var,a0 and the routine on the stack.
;------------------------------------------------------------------------------
emit_int_var_routine:
	move.l	bss_end+$44,d0
	moveq	#4,d1                           ; 4 bytes each
	bra.s	emit_var_routine                ; lea the variable, then the call

;------------------------------------------------------------------------------
; IR $ff8c: move.w (sp)+,d2, then lea bool var,a0 / jsr routine $17f.
;------------------------------------------------------------------------------
emit_pop_bool_var_call_17f:
	move.w	tpl_pop_w_d2(pc),(a2)+          ; IR $ff8c: move.w (sp)+,d2, then lea bool var + routine $17f
	move.w	#$17f,-(sp)                     ; routine number for the end
	bra.s	emit_bool_var_routine           ; lea the variable, then the call

;------------------------------------------------------------------------------
; IR $ff90: lea bool var,a0 / jsr routine $17b.
;------------------------------------------------------------------------------
emit_bool_var_call_17b:
	move.w	#$17b,-(sp)                     ; IR $ff90: lea bool var + routine $17b

;------------------------------------------------------------------------------
; lea bool var,a0 and the routine on the stack.
;------------------------------------------------------------------------------
emit_bool_var_routine:
	move.l	bss_end+$48,d0
	moveq	#2,d1                           ; 2 bytes each
	bra.s	emit_var_routine                ; lea the variable, then the call

;------------------------------------------------------------------------------
; IR $ff8f: movem.l (sp)+,d0-d2, then lea float var,a0 / jsr routine $17c.
;------------------------------------------------------------------------------
emit_pop_float_var_call_17c:
	move.l	tpl_movem_pop_d0_d2(pc),(a2)+   ; IR $ff8f: movem.l (sp)+,d0-d2, then lea float var + routine $17c
	move.w	#$17c,-(sp)                     ; routine number for the end
	bra.s	emit_float_var_routine          ; lea the variable, then the call

;------------------------------------------------------------------------------
; IR $ff93: lea float var,a0 / jsr routine $178.
;------------------------------------------------------------------------------
emit_float_var_call_178:
	move.w	#$178,-(sp)                     ; IR $ff93: lea float var + routine $178

