; lea float var,a0 and the routine on the stack.
;------------------------------------------------------------------------------
emit_float_var_routine:
	move.l	bss_end+$3c,d0
	bra.s	emit_6byte_var_routine          ; 6 bytes each

;------------------------------------------------------------------------------
; IR $ff8e: movea.l (sp)+,a1, then lea string var,a0 / jsr routine $17d.
;------------------------------------------------------------------------------
emit_pop_string_var_call_17d:
	move.w	tpl_pop_a1(pc),(a2)+            ; IR $ff8e: movea.l (sp)+,a1, then lea string var + routine $17d
	move.w	#$17d,-(sp)                     ; routine number for the end
	bra.s	emit_string_var_routine         ; lea the variable, then the call

;------------------------------------------------------------------------------
; IR $ff92: lea string var,a0 / jsr routine $179.
;------------------------------------------------------------------------------
emit_string_var_call_179:
