;------------------------------------------------------------------------------
; lea string var,a0 and the routine on the stack.
;------------------------------------------------------------------------------
emit_string_var_routine:
	move.l	bss_end+$40,d0                  ; string descriptors

;------------------------------------------------------------------------------
; lea of a 6-byte variable and the routine on the stack (d0 = type offset).
;------------------------------------------------------------------------------
emit_6byte_var_routine:
	moveq	#6,d1                           ; 6 bytes each

;------------------------------------------------------------------------------
; lea var,a0 (d0 = type offset, d1 = size, number from the IR), then jsr of the routine number
; the caller pushed.
;------------------------------------------------------------------------------
emit_var_routine:
	mulu.w	(a1)+,d1                        ; d1 = variable number * size
	bsr.w	emit_lea_var_offset             ; lea d16(a5),a0 or the long form
	move.w	(sp)+,d0                        ; routine number pushed by the caller
	bra.w	emit_call_routine               ; jsr routine(a6)

;------------------------------------------------------------------------------
; IR $ff89: moveq #n/4,d7 / jsr routine $19e.
;------------------------------------------------------------------------------
emit_moveq_d7_call_19e:
	move.w	#$19e,d0                        ; IR $ff89: moveq #n/4,d7 / jsr routine $19e
	bra.s	emit_moveq_d7_call              ; emit it

;------------------------------------------------------------------------------
; IR $ff8a: moveq #n/4,d7 / jsr routine $19d.
;------------------------------------------------------------------------------
emit_moveq_d7_call_19d:
	move.w	#$19d,d0                        ; IR $ff8a: moveq #n/4,d7 / jsr routine $19d

;------------------------------------------------------------------------------
; moveq #count,d7 (byte count from the IR / 4) and a call of routine d0.
;------------------------------------------------------------------------------
emit_moveq_d7_call:
	move.w	(a1)+,d1                        ; d1 = byte count from the IR
	lsr.w	#2,d1                           ; / 4 = long count
	move.b	#$7e,(a2)+                      ; $7e = moveq #n,d7
	move.b	d1,(a2)+                        ; n
	bra.w	emit_call_routine               ; jsr routine(a6)

;------------------------------------------------------------------------------
; Template: add.l d0,d0 (the word after it is not part of it).
;------------------------------------------------------------------------------
tpl_add_l_d0_d0:
	add.l	d0,d0                           ; template: add.l d0,d0 (the next line is not part of it)
	move.l	(a0),d0

;------------------------------------------------------------------------------
; IR $ff86: label address with tag $0300 for routine $204.
;------------------------------------------------------------------------------
emit_label_address_300:
	move.w	#$300,-(sp)                     ; IR $ff86: tag word $0300
	bra.s	emit_label_address_call_204     ; lea label,a0 with the tag, then routine $204

;------------------------------------------------------------------------------
; IR $ff87: label address with tag $0200 for routine $204.
;------------------------------------------------------------------------------
emit_label_address_200:
	move.w	#$200,-(sp)                     ; IR $ff87: tag word $0200

;------------------------------------------------------------------------------
; lea label,a0 with a relocated address long whose high word is replaced by the tag on the
; stack, then jsr routine $204 (the tag tells routine $204 what to do with the label).
;------------------------------------------------------------------------------
emit_label_address_call_204:
	move.w	#$41f9,(a2)+                    ; $41f9 = lea abs.l,a0
	move.w	(a1)+,d0                        ; label number
	bsr.w	emit_reloc_long                 ; writes the label address long (another range)
	move.w	(sp)+,-$4(a2)                   ; high word of the address replaced by the tag
	move.w	#$204,d0                        ; jsr routine $204
	bra.w	emit_call_routine               ; jsr routine(a6)

;------------------------------------------------------------------------------
; Compiler: walks the runtime routine table (runtime_routine_table, entries of two words:
; routine number + offset in its block, 0 + offset of a routine reference, negative + block
; length with bit 15 set when the block is included) and writes, for every entry of an
; included block, its offset in the output runtime to the word table at bss_end+$b0 (index =
; routine number). Exit: runtime_length = total length of the included runtime.
;------------------------------------------------------------------------------
build_runtime_offset_table:
	lea	rt_last_return,a0               ; one word before the table, the loop skips it
	lea	bss_end+$b0,a1                  ; routine number -> offset table
	moveq	#0,d7                           ; d7 = output offset of the current block
.skip_reference:
	addq.l	#2,a0                           ; step over a reference entry's offset word
.next_entry:
	move.w	(a0)+,d0                        ; d0 = routine number, 0 or the block-end flag
	ble.s	.entry_end                      ; 0 = reference, negative = block end
	move.w	(a0)+,d1                        ; offset of the entry in its block (flag bit cleared)
	andi.w	#$7fff,d1                       ; offset of the entry in its block
	add.w	d7,d1                           ; + offset of the block in the output runtime
	add.w	d0,d0                           ; word index by routine number
	move.w	d1,0(a1,d0.w)                   ; table[routine] = output offset
	bra.s	.next_entry                     ; next entry of the block
.entry_end:
	beq.s	.skip_reference                 ; reference entry: skip its offset word
	move.w	(a0)+,d1                        ; block length, bit 15 = included
	cmpa.l	a4,a0                           ; end of the table?
	beq.s	.done                           ; end marker reached: done
	bclr	#$f,d1                          ; block not included: it takes no space
	beq.s	.next_entry                     ; not included: the output offset stays
	add.w	d1,d7                           ; included: the next block starts after this one
	bra.s	.next_entry                     ; next block
.done:
	move.l	d7,runtime_length               ; d7 = runtime bytes in the program
	rts

;------------------------------------------------------------------------------
; Compiler: d0 = routine number, a3 = flag bytes by routine number ($ff = not
; yet marked). Marks the block that holds the routine as included (bit 15 of
; its length and bit 7 of each entry offset) and recursively every routine
; referenced in that block. Fatal "* L? - Restart *" if the number is not in
; the table.
;------------------------------------------------------------------------------
mark_runtime_routine:
	tst.b	0(a3,d0.w)                      ; already handled?
	bmi.s	.mark                           ; $ff: not marked yet
	rts                                     ; already marked: nothing to do
.mark:
	clr.b	0(a3,d0.w)                      ; marked now (stops the recursion)
	lea	rt_program_start,a0             ; a0 = start of the current block in the compiler's runtime copy
	lea	runtime_routine_table,a1        ; a1 = table entries, a0 follows the blocks
.next_block:
	movea.l	a1,a2                           ; a2 = first entry of this block
.scan_block:
	move.w	(a1)+,d1                        ; d1 = routine number, 0 or negative
	bpl.s	.check_number                   ; negative = end of this block
	move.w	(a1)+,d1                        ; d1 = block length (flag in bit 15)
	cmpa.l	a4,a1                           ; past the end of the table?
	beq.s	.not_found                      ; yes: the routine number does not exist
	andi.w	#$7fff,d1                       ; next block starts after this one
	adda.w	d1,a0                           ; a0 = start of the next block
	bra.s	.next_block                     ; scan the next block
.check_number:
	addq.l	#2,a1                           ; step over the entry's offset word
	cmp.w	d0,d1                           ; entry for the wanted routine?
	bne.s	.scan_block                     ; no: next entry
	movea.l	a2,a1                           ; found: a1 back to the block's first entry
.mark_entries:
	move.w	(a1)+,d0                        ; d0 = routine number, 0 or the end flag
	bne.s	.flag_entry                     ; nonzero = entry point, 0 = reference
	move.w	(a1)+,d1                        ; d1 = offset of the reference in the block
	movem.l	a0-a1,-(sp)                     ; keep the block pointers over the recursion
	move.w	0(a0,d1.w),d0                   ; routine number held in the reference word
	bsr.s	mark_runtime_routine            ; mark that routine too
	movem.l	(sp)+,a0-a1                     ; pointers back
	bra.s	.mark_entries                   ; next entry
.flag_entry:
	bset	#$7,(a1)                        ; bit 15 of the offset/length word: included
	addq.l	#2,a1                           ; next entry
	tst.w	d0                              ; stop after the block end entry
	bpl.s	.mark_entries                   ; a routine entry: go on
	rts                                     ; block end flagged: done
.not_found:
	bsr.w	compile_error_fatal             ; fatal error, the message follows
	dc.b	'* L? - Restart *',0
	dc.b	$00

;------------------------------------------------------------------------------
; Compiler: decides which runtime blocks go into the program. Clears the
; include flags, marks routines 1-3, $1b8 and $1bb when their options are on,
; and every routine called by the generated code (call list bss_end+$90 to
; $94, code at bss_end+$84); builds the offset table, then turns the address
; list bss_end+$94 to $98 into offsets in the output program.
;------------------------------------------------------------------------------
select_runtime_routines:
	lea	runtime_routine_table_offsets,a0 ; a0 = the table's offset/length words
	lea	bas_file_handle,a1              ; (the table ends at bas_file_handle)
.clear_flags:
	bclr	#$7,(a0)                        ; clear the included bit of every table entry
	addq.l	#4,a0                           ; next entry (two words)
	cmpa.l	a1,a0                           ; up to the end of the table
	bcs.s	.clear_flags                    ; until all are cleared
	lea	bss_end+$b0,a0                  ; a3 = flag bytes by routine number
	movea.l	a0,a3                           ; (also the flag bytes)
	lea	bas_file_handle,a4              ; a4 = end of the runtime routine table
	moveq	#-1,d0                          ; d0 = $ffffffff
	move.w	#$c0,d1                         ; 193 longs
.fill_needed:
	move.l	d0,(a0)+                        ; 772 bytes of $ff: nothing marked yet
	dbra	d1,.fill_needed                 ; until all are set
	moveq	#1,d0                           ; routines 1, 2 and 3 are always included
	bsr.w	mark_runtime_routine            ; routine 1: the start-up
	moveq	#2,d0                           ; routine 2: runtime errors
	bsr.w	mark_runtime_routine            ; mark it
	moveq	#3,d0                           ; routine 3
	bsr.w	mark_runtime_routine            ; mark it
	tst.b	option_errors                   ; option flag set by dialog object 13
	beq.s	.check_flag_c                   ; off: no error handler
	move.w	#$1b8,d0                        ; routine $1b8 for the Errors option
	bsr.w	mark_runtime_routine            ; mark it
.check_flag_c:
	tst.b	option_bombs                    ; option flag set by dialog object 17
	beq.s	.scan_calls                     ; off: no bomb handler
	move.w	#$1bb,d0                        ; routine $1bb for the Bombs option
	bsr.w	mark_runtime_routine            ; mark it
.scan_calls:
	movea.l	bss_end+$84,a0                  ; a0 = generated code, a1/a2 = runtime call list
	movea.l	bss_end+$90,a1                  ; call list start
	movea.l	bss_end+$94,a2                  ; call list end
	bra.s	.calls_loop                     ; walk the list
.next_call:
	moveq	#0,d0                           ; zero-extended delta
	move.w	(a1)+,d0                        ; delta to the next jsr displacement word
	bpl.s	.call_short_delta               ; one word: a delta below $7fff
	andi.w	#$ff,d0                         ; two-word delta: $ff in the high byte of the first
	swap	d0                              ; high word of the delta
	move.w	(a1)+,d0                        ; low word
.call_short_delta:
	adda.l	d0,a0                           ; a0 = address of the next displacement word
	move.w	(a0),d0                         ; routine number in the displacement word
	movem.l	a0-a2,-(sp)                     ; keep the walk pointers over the recursion
	bsr.w	mark_runtime_routine            ; mark the called routine and what it calls
	movem.l	(sp)+,a0-a2                     ; pointers back
.calls_loop:
	cmpa.l	a2,a1                           ; end of the call list?
	bne.s	.next_call                      ; no: next call
	bsr.w	build_runtime_offset_table      ; offsets of the included routines
	move.l	runtime_length,d7               ; d7 = runtime length: the code starts after it
	movea.l	bss_end+$84,a0                  ; a0 = code, a1/a2 = list of address longs to relocate
	movea.l	bss_end+$94,a1                  ; address list start
	movea.l	bss_end+$98,a2                  ; address list end
	bra.s	.relocs_loop                    ; walk the list
.next_reloc:
	moveq	#0,d0                           ; zero-extended delta
	move.w	(a1)+,d0                        ; d0 = delta to the next address long
	bpl.s	.reloc_short_delta              ; one word: a delta below $7fff
	andi.w	#$ff,d0                         ; two words: $ff tag in the high byte
	swap	d0                              ; high word of the delta
	move.w	(a1)+,d0                        ; low word
.reloc_short_delta:
	adda.l	d0,a0                           ; a0 = address of the next address long
	move.l	(a0),d0                         ; 24-bit value of the address long
	andi.l	#$ffffff,d0                     ; d0 = its 24-bit value
	move.b	(a0),d1                         ; top byte negative: already an address in the code
	bmi.s	.absolute                       ; yes: a code address, only rebased
	andi.w	#$f,d1                          ; else the low nibble is a name table type
	asl.l	#2,d1                           ; * 4: pointer index
	lea	bss_end+$5c,a3                  ; table of that type (16 bytes per name)
	movea.l	0(a3,d1.w),a3                   ; a3 = start of that name table
	asl.l	#4,d0                           ; line address of the name
	move.l	0(a3,d0.l),d0                   ; d0 = entry's line address (label or procedure)
	andi.l	#$ffffff,d0                     ; low 24 bits
.absolute:
	sub.l	bss_end+$84,d0                  ; offset from the code start, after the runtime
	add.l	d7,d0                           ; + runtime length: offset in the program text
	move.l	d0,(a0)                         ; the address long becomes a text offset
.relocs_loop:
	cmpa.l	a2,a1                           ; end of the address list?
	bcs.s	.next_reloc                     ; no: next one
	rts

; Long: length of the runtime included in the program (the offset of the generated code).
runtime_length:
	dc.w	$0000,$0000                     ; length of the included runtime (output offset of the code)

;------------------------------------------------------------------------------
; Fatal "Read Error" (the text follows the bsr, decoded as code).
;------------------------------------------------------------------------------
error_read:
	bsr.w	compile_error_fatal             ; fatal "Read Error"
	dc.b	'Lesefehler',0
	dc.b	$00

;------------------------------------------------------------------------------
; Compiler: Fopen of the .BAS file named at bss_end+$3d0 for reading; handle into
; bas_file_handle. "Read Error" on failure.
;------------------------------------------------------------------------------
open_source_file:
	clr.w	-(sp)                           ; mode 0: read only
	pea	bss_end+$3d0                    ; file name
	move.w	#$3d,-(sp)                      ; GEMDOS $3d
	trap	#1                              ; Fopen
	addq.l	#8,sp                           ; drop the arguments
	tst.l	d0                              ; error code?
	bmi.s	error_read                      ; yes: "Read Error"
	move.w	d0,bas_file_handle              ; keep the handle
	rts

;------------------------------------------------------------------------------
; Compiler: Fcreate of the program file named at bss_end+$3d0; handle into prg_file_handle.
; "Write Error" on failure.
;------------------------------------------------------------------------------
create_program_file:
	clr.w	-(sp)                           ; attributes 0
	pea	bss_end+$3d0                    ; file name
	move.w	#$3c,-(sp)                      ; GEMDOS $3c
	trap	#1                              ; Fcreate
	addq.l	#8,sp                           ; drop the arguments
	tst.l	d0                              ; error code?
	bmi.s	error_write                     ; yes: "Write Error"
	move.w	d0,prg_file_handle              ; keep the handle
	rts

;------------------------------------------------------------------------------
; Closes the .PRG file.
;------------------------------------------------------------------------------
close_program_file:
	move.w	prg_file_handle,d0              ; d0 = handle of the .PRG
	bra.s	close_file                      ; close it

;------------------------------------------------------------------------------
; Closes the .BAS file.
;------------------------------------------------------------------------------
close_source_file:
	move.w	bas_file_handle,d0              ; d0 = handle of the .BAS

;------------------------------------------------------------------------------
; Fclose of handle d0; "Error while closing File" on failure.
;------------------------------------------------------------------------------
close_file:
	move.w	d0,-(sp)                        ; handle
	move.w	#$3e,-(sp)                      ; GEMDOS $3e
	trap	#1                              ; Fclose
	addq.l	#4,sp                           ; drop the arguments
	tst.l	d0                              ; error code?
	bmi.s	error_close                     ; "Error while closing File"
	rts

;------------------------------------------------------------------------------
; Compiler: Fread of d0 bytes from the source file to a0. "End of File ???"
; when fewer come back, "OS-ERROR" on an error code.
;------------------------------------------------------------------------------
read_source_bytes:
	pea	(a0)                            ; buffer address
	move.l	d0,-(sp)                        ; byte count (kept on the stack for the check)

;------------------------------------------------------------------------------
; Fread of the source with the buffer and count already on the stack.
;------------------------------------------------------------------------------
read_source_handle:
	move.w	bas_file_handle,-(sp)           ; file handle
	move.w	#$3f,-(sp)                      ; GEMDOS $3f
	trap	#1                              ; Fread
	addq.l	#4,sp                           ; drop the function number and handle
	cmp.l	(sp)+,d0                        ; all bytes read?
	addq.l	#4,sp                           ; drop the buffer address
	bne.s	error_end_of_file               ; short read or error
	rts

;------------------------------------------------------------------------------
; Short read: "OS-ERROR" for an error code, else "End of File ???".
;------------------------------------------------------------------------------
error_end_of_file:
	tst.l	d0                              ; negative: an error code
	bmi.s	error_os                        ; yes: "OS-ERROR"
	bsr.w	compile_error_fatal
	dc.b	'EOF - Fileende ???',0
	dc.b	$00

;------------------------------------------------------------------------------
; Fatal "OS-ERROR".
;------------------------------------------------------------------------------
error_os:
	bsr.w	compile_error_fatal             ; fatal error, the message follows
	dc.b	'OS-ERROR',0
	dc.b	$00

;------------------------------------------------------------------------------
; Fatal "Write Error".
;------------------------------------------------------------------------------
error_write:
	bsr.w	compile_error_fatal             ; fatal error, the message follows
	dc.b	'Schreibfehler',0

;------------------------------------------------------------------------------
; Fatal "Error while closing File".
;------------------------------------------------------------------------------
error_close:
	bsr.w	compile_error_fatal             ; fatal error, the message follows
	dc.b	'Fehler beim Dateischlie'
	dc.b	$9e,$65,$6e,$00,$00

;------------------------------------------------------------------------------
; Compiler: reads the next 4000 bytes of the source into bss_end+$d04 and sets the read
; position bss_end+$1ca4 to the version word of the header (bas_header) masked with $f3fc:
; the version is at most 2, so that is always 0, the start of the buffer.
;------------------------------------------------------------------------------
fill_source_buffer:
	pea	bss_end+$d04                    ; buffer
	pea	$fa0                            ; 4000 bytes
	move.w	bas_file_handle,-(sp)           ; file handle
	move.w	#$3f,-(sp)                      ; GEMDOS $3f
	trap	#1                              ; Fread
	adda.w	#$c,sp                          ; drop the arguments
	lea	bas_header_ref_base,a0          ; dat_0d15f+$1b = dat_0d17a
	move.w	$1b(a0),d1                      ; the version word (at most 2, so the masked value is 0)
	andi.w	#$f3fc,d1                       ; mask: the result is always 0
	move.w	d1,bss_end+$1ca4                ; read position = start of the new buffer
	tst.l	d0                              ; read error?
	bmi.s	error_os                        ; yes: "OS-ERROR"
	rts

;------------------------------------------------------------------------------
; Compiler: copies the next source line (first byte = its length) from the
; read buffer to bss_end+$c04, refilling the buffer when the line crosses its
; end. Exit: a5 = bss_end+$c05 (after the length byte).
;------------------------------------------------------------------------------
read_source_line:
	lea	bss_end+$d04,a0                 ; a0 = read buffer
	lea	bss_end+$c04,a5                 ; a5 = line buffer
	move.w	bss_end+$1ca4,d0                ; d0 = read position in the buffer
	move.w	#$fa0,d1                        ; buffer used up?
	cmp.w	d1,d0                           ; position past the end?
	bcs.s	.copy_line                      ; no: copy the line
	bsr.s	fill_source_buffer              ; read the next 4000 bytes
	bra.s	read_source_line                ; and start again
.copy_line:
	moveq	#0,d7                           ; d7 = line length byte
	move.b	0(a0,d0.w),d7                   ; line length in bytes
	lsr.w	#1,d7                           ; in words
	subq.w	#1,d7                           ; - 1 for the dbcc
.copy_word:
	move.w	0(a0,d0.w),(a5)+                ; copy the line word by word
	addq.w	#2,d0                           ; next word
.check_end:
	cmp.w	d1,d0                           ; end of the buffer?
	dbcc	d7,.copy_word                   ; until the line is copied or the buffer ends
	bcs.s	.done                           ; line complete
	bsr.s	fill_source_buffer              ; line continues in the next 4000 bytes
	move.w	#$fa0,d1                        ; (fill_source_buffer changed d1)
	moveq	#0,d0                           ; go on from the buffer start
	lea	bss_end+$d04,a0                 ; a0 = read buffer
	bra.s	.check_end                      ; go on copying
.done:
	move.w	d0,bss_end+$1ca4                ; new read position
	lea	bss_end+$c05,a5                 ; a5 = the line's command token
	rts
	movem.l	d0-d7/a1-a6,-(sp)               ; unreferenced: Cconws of the text at a0, all registers kept
	pea	(a0)                            ; text
	move.w	#$9,-(sp)                       ; GEMDOS 9
	trap	#1                              ; Cconws
	addq.l	#6,sp                           ; drop the arguments
	movem.l	(sp)+,d0-d7/a1-a6               ; registers back
	rts

; Long: end of the work area (set by init_gem).
memory_end:
	dc.w	$0000,$0000                     ; end of the compiler's Malloc block

;------------------------------------------------------------------------------
; Fatal "Out of Memory".
;------------------------------------------------------------------------------
error_out_of_memory:
	bsr.w	compile_error_fatal             ; fatal error, the message follows
	dc.b	'Speicher voll',0

;------------------------------------------------------------------------------
; Compiler: a0 = address of a pointer in the table that ends at bss_end+$a0, d0 = bytes.
; Moves everything from that pointer up to bss_end+$9c up by d0 (rt_copy_bytes_backward) and
; adds d0 to that pointer and all later ones. Exit: a0 = gap start, d0 = size. "Out of Memory"
; past memory_end.
;------------------------------------------------------------------------------
open_memory_gap:
	movea.l	a0,a2                           ; a2 = the region pointer
	move.l	(a2),d2                         ; d2 = its address: the gap goes here
	move.l	d0,d3                           ; d3 = gap size
	movea.l	bss_end+$9c,a0                  ; a0 = end of all regions
	lea	0(a0,d0.l),a1                   ; new end
	cmpa.l	memory_end(pc),a1               ; past the end of the work area?
	bcc.s	error_out_of_memory             ; yes: "Out of Memory"
	move.l	a0,d0                           ; bytes to move: region end - gap start
	sub.l	d2,d0                           ; (d2 = gap start)
	jsr	rt_copy_bytes_backward          ; block move (another range)
	lea	bss_end+$a0,a0                  ; end of the region pointers
.adjust_pointers:
	add.l	d3,(a2)+                        ; this pointer and all later ones move up
	cmpa.l	a0,a2                           ; all done?
	bne.s	.adjust_pointers                ; no: next pointer
	movea.l	d2,a0                           ; a0 = gap start
	move.l	d3,d0                           ; d0 = gap size
	rts

; Byte: set for a fatal error (Abort button only).
fatal_error_flag:
	dc.w	$0000

;------------------------------------------------------------------------------
; Compiler: fatal error. Called with bsr, the NUL-terminated message follows the call. Saves
; all registers, shows "[1][Compiling error |message][ Abort ]" and restarts at abort_compile.
; Does not return.
;------------------------------------------------------------------------------
compile_error_fatal:
	movem.l	d0-d7/a0-sp,bss_end+$ffff2e3c   ; registers to text-$40: the command line area of the basepage
	st	fatal_error_flag                ; fatal: only an Abort button
	lea	str_button_abort(pc),a2         ; button text
	bra.s	show_compile_error              ; show it

;------------------------------------------------------------------------------
; Compiler: error with [Continue|Abort] buttons; message inline after the bsr. Continue goes
; on at compile_next_line, Abort at abort_compile. Does not return.
;------------------------------------------------------------------------------
compile_error_continue:
	lea	str_buttons_continue_abort(pc),a2 ; button texts
	sf	fatal_error_flag                ; not fatal

;------------------------------------------------------------------------------
; Builds the alert text from the message after the bsr and the buttons in a2, shows it, and
; continues at compile_next_line or abort_compile.
;------------------------------------------------------------------------------
show_compile_error:
	lea	alert_message_buffer(pc),a0     ; a0 = text after "[1][Compiling error |"
	movea.l	(sp)+,a1                        ; message address = return address
.copy_message:
	move.b	(a1)+,(a0)+                     ; copy the message ...
	bne.s	.copy_message                   ; ... up to its NUL
	subq.l	#1,a0                           ; back onto the NUL
.copy_buttons:
	move.b	(a2)+,(a0)+                     ; append the buttons ...
	bne.s	.copy_buttons                   ; ... with their NUL
	moveq	#1,d0                           ; form_alert default button 1
	lea	str_alert_compiling_error(pc),a0 ; the whole alert text
	bsr.w	form_alert_call                 ; show it, d0 = button pressed
	lea	bss_end+$208e,sp                ; reset the compiler stack
	tst.b	fatal_error_flag                ; fatal error?
	bne.w	abort_compile                   ; yes: abort
	subq.w	#1,d0
	bne.w	abort_compile
	bra.w	compile_next_line

; Alert buttons: [Continue|Abort].
str_buttons_continue_abort:
	dc.b	'][Weiter|Abbruch]',0

; Alert button: [ Abort ].
str_button_abort:
	dc.b	'][Abbruch]',0

; Start of the alert text; the message and buttons are appended after it.
str_alert_compiling_error:
	dc.b	'[1][Fehler beim compilieren|'

; Buffer for the message and the buttons.
alert_message_buffer:
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00
	dc.b	$00,$00,$00,$00,$00

; Long: address of resource tree 0.
rsc_tree_file_box:
	dc.w	$0000,$0000                     ; address of resource tree 0 (drawn behind the file selector)

; Long: address of resource tree 1.
rsc_tree_options:
	dc.w	$0000,$0000                     ; address of resource tree 1 (the options dialog)

; Long: address of resource tree 2.
rsc_tree_unused:
	dc.w	$0000,$0000                     ; address of resource tree 2 (not used in this range)

; Name of the resource file.
str_rsc_name:
	dc.b	'gfa_bcom.rsc',0                ; text "gfa_bcom.rsc" decoded as code
	dc.b	$00

;------------------------------------------------------------------------------
; Compiler: appl_init, rsrc_load("gfa_bcom.rsc"), rsrc_gaddr of trees 0, 2
; and 1, then selects the default buttons 18, 10, 6 and 14 of the options
; dialog.
;------------------------------------------------------------------------------
init_gem:
	move.l	bss_end+$78,d0                  ; work area address ...
	add.l	bss_end+$74,d0                  ; ... + its size
	move.l	d0,memory_end                   ; memory_end = Malloc block + its size
	moveq	#10,d0                          ; AES 10 appl_init
	bsr.w	aes_call                        ; (AES global array filled)
	move.l	#str_rsc_name,aes_addrin        ; addrin[0] = resource file name
	moveq	#110,d0                         ; AES 110 rsrc_load
	bsr.w	aes_call                        ; load the dialogs
	moveq	#0,d1                           ; type 0: R_TREE
	moveq	#0,d0                           ; tree 0
	bsr.w	rsrc_gaddr_call                 ; AES 112 rsrc_gaddr(R_TREE, 0)
	move.l	a0,rsc_tree_file_box            ; the file box drawn behind the selector
	moveq	#0,d1                           ; type 0: R_TREE
	moveq	#2,d0                           ; tree 2
	bsr.w	rsrc_gaddr_call                 ; AES 112 rsrc_gaddr
	move.l	a0,rsc_tree_unused              ; keep its address
	moveq	#0,d1                           ; type 0: R_TREE
	moveq	#1,d0                           ; tree 1
	bsr.w	rsrc_gaddr_call                 ; AES 112 rsrc_gaddr
	move.l	a0,rsc_tree_options             ; the options dialog

;------------------------------------------------------------------------------
; Selects the default buttons 18, 10, 6 and 14 of the tree in a0.
;------------------------------------------------------------------------------
preselect_option_buttons:
	move.l	a0,aes_addrin                   ; objc_change works on the options tree
	moveq	#18,d0                          ; object 18 selected

;------------------------------------------------------------------------------
; Selects object d0, then 10, 6 and 14.
;------------------------------------------------------------------------------
preselect_button_10:
	bsr.w	select_object                   ; (also re-entered with another object in d0)
	moveq	#10,d0                          ; object 10 selected
	bsr.w	select_object                   ; set its state
	moveq	#6,d0                           ; object 6 selected

;------------------------------------------------------------------------------
; Selects object d0, then 14.
;------------------------------------------------------------------------------
preselect_button_14:
	bsr.w	select_object                   ; (also re-entered with another object in d0)
	moveq	#14,d0                          ; object 14 selected
	bra.w	select_object                   ; set its state and return

;------------------------------------------------------------------------------
; Compiler: shows the options dialog (form_center, objc_draw, form_do) and reads the buttons
; into the option flags: obj 17 -> option_bombs, obj 9 -> option_trapv, obj 13 ->
; option_errors, obj 4/5 -> option_stop_mode ($ff / 1). Exit button 20 quits (appl_exit,
; Pterm0). Then the file selector for *.BAS and the default program name (.BAS name with
; .PRG) in default_file_name.
;------------------------------------------------------------------------------
options_dialog:
	clr.w	aes_intin                       ; graf_mouse(ARROW)
	moveq	#78,d0                          ; AES 78 graf_mouse
	bsr.w	aes_call                        ; arrow pointer
	move.l	rsc_tree_options(pc),aes_addrin ; addrin[0] = the options tree
	moveq	#54,d0                          ; AES 54 form_center
	bsr.w	aes_call                        ; centre the dialog
	movem.w	aes_intout_x,d0-d3              ; d0-d3 = its rectangle
	move.l	#$3,aes_intin                   ; objc_draw from object 0, depth 3
	movem.w	d0-d3,aes_intin_clip_xy         ; clip = the rectangle from form_center
	moveq	#42,d0                          ; AES 42 objc_draw
	bsr.w	aes_call                        ; draw the dialog
	clr.w	aes_intin                       ; no editable start object
	moveq	#50,d0                          ; AES 50 form_do
	bsr.w	aes_call                        ; run the dialog, d0 = exit object
	cmpi.w	#$14,d0                         ; object 20: quit
	beq.w	.quit                           ; yes: leave the compiler
	movea.l	rsc_tree_options(pc),a0         ; a0 = the options tree
	move.w	$1a2(a0),d0                     ; ob_state of object 17 (tree + 17*24 + 10)
	sne	option_bombs                    ; Bombs option on?
	move.w	$e2(a0),d0                      ; ob_state of object 9: Trapv
	sne	option_trapv                    ; Trapv option on?
	move.w	$142(a0),d0                     ; ob_state of object 13
	sne	option_errors                   ; Errors option on?
	move.w	$6a(a0),d0                      ; ob_state of object 4: Stop $ff
	sne	option_stop_mode                ; Stop option: $ff = Ever (object 4 selected)
	bne.s	.options_done                   ; Ever: done
	move.w	$82(a0),d0                      ; ob_state of object 5: Stop 1
	beq.s	.options_done                   ; neither: Stop mode 0
	move.b	#$1,option_stop_mode            ; object 5: Stop mode 1
.options_done:
	moveq	#19,d0                          ; deselect exit button 19
	bsr.w	deselect_object                 ; clear its selected state for the next time
	movea.l	rsc_tree_file_box(pc),a0        ; a0 = the tree drawn behind the selector
	clr.b	default_file_name               ; no default name for the source
	move.l	#$2e424153,d0                   ; '.BAS'
	bsr.w	file_selector                   ; choose the .BAS file
	lea	bss_end+$498,a0                 ; name chosen in the file selector
	lea	default_file_name(pc),a1        ; default program name built here
.copy_name:
	move.b	(a0)+,d0                        ; next character of the source name
	cmpi.b	#$2e,d0                         ; '.'?
	bne.s	.store_char                     ; no: keep it
	moveq	#0,d0                           ; the extension is cut off: end of the copy
.store_char:
	move.b	d0,(a1)+                        ; store the character
	bne.s	.copy_name                      ; until the NUL
	move.b	#$2e,-$1(a1)                    ; extension .PRG
	move.b	#$50,(a1)+                      ; 'P'
	move.b	#$52,(a1)+                      ; 'R'
	move.b	#$47,(a1)+                      ; 'G'
	clr.b	(a1)+                           ; NUL
	rts
.quit:
	moveq	#19,d0                          ; AES 19 appl_exit
	bsr.w	aes_call                        ; close the AES session
	clr.w	-(sp)                           ; GEMDOS 0
	trap	#1                              ; Pterm0

;------------------------------------------------------------------------------
; Clears object d0's state (deselected).
;------------------------------------------------------------------------------
deselect_object:
	moveq	#0,d1                           ; state 0: normal
	bra.s	set_object_state                ; set it

;------------------------------------------------------------------------------
; Sets object d0's state to selected.
;------------------------------------------------------------------------------
select_object:
	moveq	#1,d1                           ; state 1: selected

;------------------------------------------------------------------------------
; Compiler: objc_change(tree in addrin, object d0, clip 0,0,640,400, state
; d1, no redraw).
;------------------------------------------------------------------------------
set_object_state:
	move.w	d0,aes_intin                    ; intin[0] = object
	clr.l	aes_intin_clip_xy               ; clip x, y = 0
	move.l	#$2800190,aes_intin_clip_wh     ; clip w = 640, h = 400
	move.w	d1,aes_intout_x                 ; intin[6] = new state
	clr.w	aes_intout_y                    ; intin[7] = 0: no redraw
	moveq	#47,d0                          ; AES 47 objc_change
	bra.s	aes_call                        ; call it

;------------------------------------------------------------------------------
; rsrc_gaddr(type d1, index d0). Exit: a0 = address.
;------------------------------------------------------------------------------
rsrc_gaddr_call:
	move.w	d1,aes_intin                    ; intin[0] = type d1, intin[1] = index d0
	move.w	d0,aes_intin_index              ; (intin[1])
	moveq	#112,d0                         ; AES 112 rsrc_gaddr

;------------------------------------------------------------------------------
; Compiler: AES call with opcode d0. contrl[1..3] come from the 3-byte table at
; rt_aes_control_table + opcode*3 (the runtime's AES table). Exit: a0 = addrout[0], d0 =
; intout[0].
;------------------------------------------------------------------------------
aes_call:
	lea	aes_control(pc),a1              ; a1 = contrl
	move.w	d0,(a1)+                        ; contrl[0] = opcode
	lea	rt_aes_control_table,a0         ; table of 3 bytes per AES opcode
	adda.w	d0,a0                           ; opcode * 3 ...
	add.w	d0,d0                           ; (opcode * 2)
	adda.w	d0,a0                           ; ... entry for the opcode
	moveq	#0,d0                           ; byte values zero-extended
	move.b	(a0)+,d0                        ; contrl[1] = intin count
	move.w	d0,(a1)+                        ; (stored)
	move.b	(a0)+,d0                        ; contrl[2] = intout count
	move.w	d0,(a1)+                        ; (stored)
	move.b	(a0)+,d0                        ; contrl[3] = addrin count
	move.w	d0,(a1)+                        ; (stored)
	dc.w	$a009                           ; Line-A Show mouse
	move.l	#aes_parameter_block,d1         ; AES parameter block
	move.w	#$c8,d0                         ; $c8 = AES
	trap	#2                              ; AES/VDI
	dc.w	$a00a                           ; Line-A Hide mouse
	movea.l	aes_addrout,a0                  ; a0 = addrout[0]
	move.w	aes_intout,d0                   ; d0 = intout[0]
	rts

;------------------------------------------------------------------------------
; form_alert(default button d0, text a0). Exit: d0 = button.
;------------------------------------------------------------------------------
form_alert_call:
	move.l	a0,aes_addrin                   ; a0 = alert text, d0 = default button
	move.w	d0,aes_intin                    ; intin[0] = default button
	moveq	#52,d0                          ; AES 52 form_alert
	bra.s	aes_call                        ; call it

; The AES parameter block.
aes_parameter_block:
	dc.l	aes_control
	dc.l	aes_global
	dc.l	aes_intin
	dc.l	aes_intout
	dc.l	aes_addrin
	dc.l	aes_addrout

; AES contrl array.
aes_control:
	dc.w	$0000,$0000,$0000,$0000,$0000

; AES global array.
aes_global:
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000

; AES intin array (intin[0]).
aes_intin:
	dc.w	$0000

; intin[1].
aes_intin_index:
	dc.w	$0000

; intin[2..3] (objc_draw clip x, y).
aes_intin_clip_xy:
	dc.w	$0000,$0000

; intin[4] (objc_draw clip w).
aes_intin_clip_wh:
	dc.w	$0000

; AES intout array (intout[0]; objc_change also uses these words as intin[5..7]).
aes_intout:
	dc.w	$0000                           ; intout; objc_change also uses these words as intin[5..7]

; intout[1].
aes_intout_x:
	dc.w	$0000

; intout[2..4].
aes_intout_y:
	dc.w	$0000,$0000,$0000

; AES addrin array (addrin[0]).
aes_addrin:
	dc.w	$0000,$0000

; addrin[1].
aes_addrin_name:
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000

; AES addrout array.
aes_addrout:
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000

; Default file name for the file selector (the .PRG name after the source is chosen).
default_file_name:
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000

;------------------------------------------------------------------------------
; Compiler: d0 = extension (4 chars), a0 = tree drawn behind the selector.
; fsel_input with path "\*"+extension at bss_end+$3d0 and the name from
; default_file_name; Cancel restarts the compiler. Exit: bss_end+$3d0 = full
; file name, mouse busy, screen cleared.
;------------------------------------------------------------------------------
file_selector:
	move.w	#$5c2a,bss_end+$3d0             ; '\*' then the extension
	move.l	d0,bss_end+$3d2                 ; the extension after '\*'
	clr.b	bss_end+$3d6                    ; NUL after it
	lea	bss_end+$498,a1                 ; name field for fsel_input
	lea	default_file_name(pc),a2        ; from the default name
.copy_name:
	move.b	(a2)+,(a1)+                     ; copy it ...
	bne.s	.copy_name                      ; ... with its NUL
	move.l	a0,aes_addrin                   ; addrin[0] = the box tree
	moveq	#54,d0                          ; form_center
	bsr.w	aes_call                        ; centre it
	movem.w	aes_intout_x(pc),d0-d3          ; d0-d3 = its rectangle
	moveq	#2,d1                           ; (y of the root object)
	movea.l	aes_addrin(pc),a0               ; a0 = tree
	move.w	d1,$12(a0)                      ; y of the root object = 2
	move.l	#$3,aes_intin                   ; objc_draw from object 0, depth 3
	movem.w	d0-d3,aes_intin_clip_xy         ; clip = its rectangle
	moveq	#42,d0                          ; objc_draw
	bsr.w	aes_call                        ; draw the box
	move.l	#bss_end+$3d0,aes_addrin        ; addrin[0] = path
	move.l	#bss_end+$498,aes_addrin_name   ; addrin[1] = file name
	moveq	#90,d0                          ; AES 90 fsel_input
	bsr.w	aes_call                        ; file selector
	tst.w	aes_intout_x                    ; Cancel?
	beq.w	restart_compiler                ; Cancel: start again
	lea	bss_end+$3d0,a0                 ; join the path and the name
.find_last_slash:
	movea.l	a0,a1                           ; a1 = after the last '\' so far
.scan_char:
	move.b	(a0)+,d0                        ; next character
	beq.s	.append_name                    ; end of the path
	cmpi.b	#$5c,d0                         ; '\'?
	bne.s	.scan_char                      ; no: next character
	bra.s	.find_last_slash                ; yes: remember the position after it
.append_name:
	lea	bss_end+$498,a0                 ; the chosen name ...
.copy_char:
	move.b	(a0)+,(a1)+                     ; ... replaces the wildcard after the last '\'
	bne.s	.copy_char                      ; up to its NUL
	move.w	#$2,aes_intin                   ; graf_mouse(BUSY_BEE)
	moveq	#78,d0                          ; AES 78 graf_mouse
	bsr.w	aes_call                        ; busy bee
	pea	str_clear_screen                ; clear the screen
	move.w	#$9,-(sp)                       ; GEMDOS 9
	trap	#1                              ; Cconws
	addq.l	#6,sp                           ; drop the arguments
	rts

;------------------------------------------------------------------------------
; Text ESC E (clear the screen), decoded as code.
;------------------------------------------------------------------------------
str_clear_screen:
	move.b	d5,0(a5)                        ; text ESC E decoded as code

;------------------------------------------------------------------------------
; File selector cancelled: reset the stack and start again.
;------------------------------------------------------------------------------
restart_compiler:
	lea	bss_end+$208e,sp                ; reset the compiler stack
	bra.w	compile_next_program            ; back to the options dialog

; The 28-byte .PRG header, its lengths filled in by write_program.
prg_header:
	dc.w	$601a,$0000,$0001,$0000,$0000,$0000,$0001,$0000 ; $601a and the header longs, decoded as code (filled in
                                                ;   by write_program)
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000

;------------------------------------------------------------------------------
; Compiler: writes the .PRG: the header (text = runtime + code, data, BSS =
; variables + 20798), each included runtime block with its routine number
; words replaced by offsets from a6 (restored afterwards), the generated code
; with its runtime calls patched, the data, and the GEMDOS relocation table.
;------------------------------------------------------------------------------
write_program:
	lea	prg_header(pc),a0               ; a0 = program header
	move.l	runtime_length(pc),d0           ; text length = runtime + generated code
	add.l	bss_end+$88,d0                  ; + end of the code ...
	sub.l	bss_end+$84,d0                  ; ... - start of the code
	move.l	d0,2(a0)                        ; ph_tlen
	move.l	bss_end+$80,d0                  ; data parts
	sub.l	bss_end+$7c,d0                  ; data part 1 length (DATA items)
	move.l	bss_end+$8c,d1                  ; data part 2: the region bss_end+$88 to $8c ...
	sub.l	bss_end+$88,d1                  ; (region end - code end)
	move.l	d1,rt_data_length_patch+2       ; patch the start-up's subi.l #n,d0 with this length
	add.l	d1,d0                           ; + data part 1
	move.l	d0,6(a0)                        ; ph_dlen
	move.l	rt_var_storage_end,d0           ; variable storage + 20798 = BSS length
	sub.l	rt_var_type_offsets,d0          ; - start: length of the variables
	addi.l	#$513e,d0                       ; + 20798 bytes of runtime variables
	move.l	d0,$a(a0)                       ; ph_blen
	moveq	#28,d0                          ; 28-byte program header
	bsr.w	write_bytes                     ; write the header
	lea	rt_program_start,a0             ; a0 = first runtime block
	lea	runtime_routine_table,a1        ; a1 = its table entries
	lea	bas_file_handle,a2              ; a2 = end of the table
	lea	bss_end+$b0,a5                  ; a5 = routine number -> offset table
	move.w	4(a5),d0                        ; offset of routine 2 becomes the base: a6 points at it
	move.w	#$300,d1                        ; 769 words
	movea.l	a5,a3                           ; a3 walks the offset table
.rebase_offsets:
	sub.w	d0,(a3)+                        ; offsets relative to routine 2
	dbra	d1,.rebase_offsets              ; all entries
	addi.w	#$100,d0                        ; start-up lea d(a5),a6 gets basepage + $100 + offset
	move.w	d0,rt_set_runtime_base+2        ; patch the start-up's lea $100(a5),a6
.next_block:
	movea.l	a0,a3                           ; a3 = start of this block
	movea.l	a1,a4                           ; a4 = its first entry
.find_block_end:
	tst.l	(a1)+                           ; walk to the block's end entry
	bpl.s	.find_block_end                 ; (negative long: the end entry)
	moveq	#0,d0                           ; zero-extended length
	move.w	-$2(a1),d0                      ; d0 = length word with the flag
	bclr	#$f,d0                          ; block length and included flag
	adda.w	d0,a0                           ; a0 = next block (Z from the bclr: not included)
	beq.s	.blocks_loop                    ; not included: skip
	movem.l	a0-a2,-(sp)                     ; keep the block pointers
	moveq	#0,d1                           ; d1 = number of patched words
.patch_refs:
	move.w	(a4)+,d2                        ; next entry word
	bmi.s	.write_block                    ; block end: write the block
	bne.s	.next_entry                     ; nonzero entry = entry point, nothing to patch
	move.w	(a4),d3                         ; offset of a reference word in the block
	move.w	0(a3,d3.w),d4                   ; d4 = routine number in the reference word
	move.w	d4,-(sp)                        ; keep the original routine number
	pea	0(a3,d3.w)                      ; keep its address too
	add.w	d4,d4                           ; word index
	move.w	0(a5,d4.w),0(a3,d3.w)           ; replace it by that routine's offset
	addq.w	#1,d1                           ; count it
.next_entry:
	addq.l	#2,a4                           ; step over the offset word
	bra.s	.patch_refs                     ; next entry
.write_block:
	movea.l	a3,a0                           ; a0 = block start, d0 = length
	move.w	d1,-(sp)                        ; keep the count
	bsr.w	write_bytes                     ; write the block
	move.w	(sp)+,d1                        ; count back
	bra.s	.restore_loop                   ; restore the patched words
.restore_ref:
	movea.l	(sp)+,a0                        ; a0 = address of a patched word
	move.w	(sp)+,(a0)                      ; put the routine number back
.restore_loop:
	dbra	d1,.restore_ref                 ; all of them
	movem.l	(sp)+,a0-a2                     ; block pointers back
.blocks_loop:
	cmpa.l	a2,a1                           ; end of the table?
	bcs.s	.next_block                     ; no: next block
	movea.l	bss_end+$84,a0                  ; patch the generated code's jsr d(a6) displacements
	movea.l	bss_end+$90,a1                  ; call list start
	movea.l	bss_end+$94,a2                  ; call list end
	bra.s	.calls_loop                     ; walk the list
.patch_call:
	moveq	#0,d0                           ; zero-extended delta
	move.w	(a1)+,d0                        ; d0 = delta to the next displacement word
	bpl.s	.short_delta                    ; one word: a delta below $7fff
	andi.w	#$ff,d0                         ; two words: $ff tag in the high byte
	swap	d0                              ; high word of the delta
	move.w	(a1)+,d0                        ; low word
.short_delta:
	adda.l	d0,a0                           ; a0 = address of the displacement word
	move.w	(a0),d0                         ; d0 = routine number
	add.w	d0,d0                           ; word index
	move.w	0(a5,d0.w),(a0)                 ; replace it by the routine's offset from a6
.calls_loop:
	cmpa.l	a2,a1                           ; end of the list?
	bcs.s	.patch_call                     ; no: next call
	movea.l	bss_end+$84,a0                  ; generated code
	move.l	bss_end+$88,d0                  ; end of the code
	sub.l	a0,d0                           ; length
	bsr.w	write_bytes                     ; write it
	movea.l	bss_end+$7c,a0                  ; data part 1
	move.l	bss_end+$80,d0                  ; end of part 1
	sub.l	a0,d0                           ; length
	bsr.w	write_bytes                     ; write it
	movea.l	bss_end+$88,a0                  ; data part 2
	move.l	bss_end+$8c,d0                  ; end of part 2
	sub.l	a0,d0                           ; length
	bsr.w	write_bytes                     ; write it
	movem.l	bss_end+$94,a3-a4               ; relocation list
	cmpa.l	a4,a3                           ; no addresses to relocate?
	beq.s	.no_relocs                      ; then the long 0
	move.w	(a3)+,d0                        ; d0 = offset of the first address long
	bpl.s	.first_reloc                    ; one word: below $7fff
	andi.w	#$ff,d0                         ; two words: $ff tag in the high byte
	swap	d0                              ; high word
	move.w	(a3)+,d0                        ; low word
.first_reloc:
	add.l	runtime_length(pc),d0           ; first long: offset of the first address in the text
	bsr.s	write_long                      ; write it
	bra.s	.relocs_loop                    ; then the fixup bytes
.next_reloc:
	moveq	#0,d7                           ; zero-extended delta
	move.w	(a3)+,d7                        ; d7 = distance to the next address long
	bpl.s	.reloc_delta                    ; one word: below $7fff
	andi.w	#$ff,d7                         ; two words: $ff tag in the high byte
	swap	d7                              ; high word
	move.w	(a3)+,d7                        ; low word
.reloc_delta:
	divu.w	#$fe,d7                         ; GEMDOS fixups: 1 = skip 254 bytes, else the distance
	move.l	d7,d6                           ; d6 = remainder
	swap	d6                              ; (in the low word)
	tst.w	d6                              ; remainder 0?
	bne.s	.skip_loop                      ; no: d7 bytes of 1, then the remainder
	subq.w	#1,d7                           ; a multiple of 254: one 1 less ...
	move.w	#$fe,d6                         ; ... and 254 as the last byte
	bra.s	.skip_loop                      ; write them
.write_skip:
	moveq	#1,d0                           ; fixup byte 1: skip 254 bytes
	bsr.s	write_byte                      ; write it
.skip_loop:
	dbra	d7,.write_skip                  ; as many as needed
	move.b	d6,d0                           ; the remaining distance
	bsr.s	write_byte                      ; write it
.relocs_loop:
	cmpa.l	a4,a3                           ; end of the address list?
	bcs.s	.next_reloc                     ; no: next one
	moveq	#0,d0                           ; end of the fixup bytes
	bsr.s	write_byte                      ; write it
	bra.s	.write_end                      ; and the closing long
.no_relocs:
	moveq	#0,d0                           ; first long 0: no relocation
	bsr.s	write_long                      ; write it
.write_end:
	moveq	#0,d0                           ; then a zero long after the table

;------------------------------------------------------------------------------
; Writes the long d0 to the program file.
;------------------------------------------------------------------------------
write_long:
	lea	write_buffer,a0                 ; a0 = the 4-byte buffer
	move.l	d0,(a0)                         ; the long
	moveq	#4,d0                           ; 4 bytes
	bra.s	write_bytes                     ; write them

;------------------------------------------------------------------------------
; Writes the byte d0 to the program file.
;------------------------------------------------------------------------------
write_byte:
	lea	write_buffer,a0                 ; a0 = the buffer
	move.b	d0,(a0)                         ; the byte
	moveq	#1,d0                           ; 1 byte

;------------------------------------------------------------------------------
; Compiler: Fwrite of d0 bytes from a0 to the program file (nothing for 0).
; Fatal "SAVEPROG - write error" if not all are written.
;------------------------------------------------------------------------------
write_bytes:
	pea	(a0)                            ; buffer
	move.l	d0,-(sp)                        ; byte count (kept on the stack for the check)
	beq.s	.check                          ; nothing to write: the check passes
	move.w	prg_file_handle,-(sp)           ; file handle
	move.w	#$40,-(sp)                      ; GEMDOS $40
	trap	#1                              ; Fwrite
	addq.l	#4,sp                           ; drop the function number and handle
.check:
	cmp.l	(sp)+,d0                        ; all bytes written?
	bne.s	.error                          ; no: error
	addq.l	#4,sp                           ; drop the buffer address
	rts
.error:
	addq.l	#4,sp                           ; drop the buffer address
	bsr.w	compile_error_fatal             ; fatal error, the message follows
	dc.b	'SAVEPROG - write error',0
	dc.b	$00

; Write buffer for write_long / write_byte.
write_buffer:
	dc.w	$0000,$0000
	dc.b	'06/02/86'

; Long: line address of the structure that was left open.
structure_error_line:
	dc.w	$0000,$0000

;------------------------------------------------------------------------------
; Compiler: walks the source lines from bss_end+$30 ([len][token]...; token
; $df ends the program), clears the name tables bss_end+$5c-$6c and links
; the structures: REPEAT/UNTIL, WHILE/WEND, DO/LOOP, FOR/NEXT, IF/ELSE/ENDIF,
; EXIT, PROCEDURE/RETURN, LOCAL, DEFFN and labels. Open structures are kept
; on the stack as line address with the token in the top byte; the 4 address
; bytes at 2(line) of a linked command get the partner line. Exit: d7 = 0,
; or -1 after a structure error alert.
;------------------------------------------------------------------------------
link_structures:
	movea.l	bss_end+$5c,a0                  ; start of the name tables (labels first)
	movea.l	bss_end+$6c,a1                  ; end of the tables
.clear_tables:
	cmpa.l	a0,a1                           ; all cleared?
	beq.s	.start_scan                     ; yes: scan the lines
	clr.l	(a0)+                           ; clear a long
	bra.s	.clear_tables                   ; next one
.start_scan:
	movea.l	bss_end+$30,a0                  ; a0 = first source line
	clr.l	-(sp)                           ; stack bottom marker
	moveq	#0,d0                           ; d0 = index for the class table

;------------------------------------------------------------------------------
; Linker loop: dispatches the structure commands, skips the others.
;------------------------------------------------------------------------------
link_next_line:
	move.b	1(a0),d0                        ; command token of the line
	cmpi.b	#$df,d0                         ; end of the program
	beq.s	link_end_of_program             ; yes: check that nothing is left open
	move.b	structure_token_class(pc,d0.w),d1 ; structure class of the token
	bpl.w	link_dispatch                   ; a structure command: its handler

;------------------------------------------------------------------------------
; Steps to the next line.
;------------------------------------------------------------------------------
link_skip_line:
	move.b	(a0),d0                         ; next line
	adda.w	d0,a0                           ; a0 += line length
	bra.s	link_next_line                  ; next line

;------------------------------------------------------------------------------
; Program end: checks for structures still open.
;------------------------------------------------------------------------------
link_end_of_program:
	bra.w	link_check_unclosed             ; every structure must be closed

; Data: one byte per command token, the handler offset in structure_handler_offsets or $ff
; for none. Partly decoded as code.
structure_token_class:
	dc.w	$ffff,$0002,$0406,$080a,$0c0e   ; one byte per command token: handler offset in the table, $ff = none
	move.b	(a2),d0                         ; (table bytes decoded as code)
	move.b	(a6),d2                         ; (table bytes decoded as code)
	dc.w	$ffff,$ffff,$ffff,$ffff,$ffff,$ffff,$ffff,$ffff
	dc.w	$ffff,$ffff,$ffff,$ffff,$ffff,$ffff,$ff18
	move.b	(a4)+,d5                        ; (table bytes decoded as code)
	dc.w	$1eff,$ffff,$ffff,$ffff,$ffff,$ffff,$ffff,$ffff
	dc.w	$ffff,$ffff,$ffff,$ffff,$ffff,$ffff,$ffff,$ffff
	dc.w	$ffff,$ffff,$ffff,$ffff,$ffff,$ffff,$ffff,$ffff
	dc.w	$ffff,$ffff,$ffff,$ffff,$ffff,$24ff,$ffff,$ffff
	dc.w	$ffff,$ffff,$ffff,$ffff,$ffff,$ffff,$ffff,$ffff
	dc.w	$ff26,$ffff,$ffff,$ffff,$ff28,$ffff,$ffff,$ffff
	dc.w	$ffff,$ffff,$ffff,$ffff,$ffff,$ffff,$ffff,$ffff
	dc.w	$ffff,$ffff,$ffff,$ffff,$ffff,$ffff,$ffff,$ffff
	dc.w	$ffff,$ffff,$ffff,$ffff,$ffff,$ffff,$ffff,$ffff
	dc.w	$ffff,$ffff,$ffff,$ffff,$ffff,$ffff,$ffff,$ffff
	dc.w	$ffff,$ffff,$ffff,$ffff,$ffff,$ffff,$ffff,$ffff
	dc.w	$ffff,$ffff,$ffff,$ffff,$ffff,$20ff,$ffff,$ffff
	dc.w	$ffff,$ffff,$ffff,$ffff,$ffff,$22ff,$ffff,$ffff
	dc.w	$ffff

;------------------------------------------------------------------------------
; Jumps to the structure handler for class d1.
;------------------------------------------------------------------------------
link_dispatch:
	andi.w	#$ff,d1                         ; class byte = word offset in the handler table
	move.w	structure_handler_offsets(pc,d1.w),d1 ; d1 = handler offset from link_push_open
	jmp	link_push_open(pc,d1.w)         ; run the handler

; Data: 20 handler offsets from link_push_open (REPEAT, UNTIL, WHILE, WEND, DO, LOOP, FOR,
; NEXT, IF, ELSE, ENDIF, EXIT, PROCEDURE, RETURN, LOCAL, DEFFN, labels).
structure_handler_offsets:
	dc.w	$0000,$0008,$0050,$0058,$0000,$0032,$0050,$0088 ; 20 handler offsets from loc_0530e, decoded as code up
                                                ;   to $530c
	dc.w	$012a,$0000,$010e,$00f2,$01b4,$fec0,$fec0,$01ea
	dc.w	$01fa,$0202,$0256,$0262,$023e

;------------------------------------------------------------------------------
; Structure handlers, entered through structure_handler_offsets: open structures are pushed
; with the token in the top byte; closing ones link the line addresses at 2(line).
;------------------------------------------------------------------------------
link_push_open:
	move.l	a0,-(sp)                        ; REPEAT/DO/IF: push the line with its token
	move.b	d0,(sp)                         ; token in the top byte
	bra.w	link_skip_line                  ; next line
.until_exit:
	cmpi.b	#$82,(sp)                       ; UNTIL: EXIT inside the REPEAT ($82) waiting?
	bne.s	.until_repeat                   ; no: the REPEAT itself
	movea.l	(sp)+,a1                        ; a1 = the EXIT line
	move.b	(a0),d0                         ; d0 = UNTIL line length
	move.l	a0,2(a1)                        ; EXIT jumps to the line after UNTIL
	add.l	d0,2(a1)                        ; + length: the line after UNTIL
	bra.s	.until_exit                     ; more EXITs?
.until_repeat:
	cmpi.b	#$2,(sp)                        ; REPEAT ($02) open?
	bne.w	structure_error_jump            ; no: structure error
.link_after_open:
	movea.l	(sp)+,a1                        ; a1 = the opening line
	move.b	(a1),d0                         ; UNTIL/LOOP gets the line after REPEAT/DO
	adda.w	d0,a1                           ; the line after it
	move.l	a1,2(a0)                        ; into the closing line's address long
	bra.w	link_skip_line                  ; next line
.loop_exit:
	cmpi.b	#$86,(sp)                       ; LOOP: EXIT inside the DO ($86) waiting?
	bne.s	.loop_do                        ; no: the DO itself
	movea.l	(sp)+,a1                        ; a1 = the EXIT line
	move.b	(a0),d0                         ; d0 = LOOP line length
	move.l	a0,2(a1)                        ; EXIT jumps to the line after LOOP
	add.l	d0,2(a1)                        ; (+ length)
	bra.s	.loop_exit                      ; more EXITs?
.loop_do:
	cmpi.b	#$6,(sp)                        ; DO ($06) open?
	beq.s	.link_after_open                ; yes: link it
	bra.w	structure_error_jump            ; no: structure error
	move.l	a0,-(sp)                        ; WHILE/FOR: push the line with its token
	move.b	d0,(sp)                         ; token in the top byte
	bra.w	link_skip_line                  ; next line
.wend_exit:
	cmpi.b	#$84,(sp)                       ; WEND: EXIT inside the WHILE ($84) waiting?
	bne.s	.wend_while                     ; no: the WHILE itself
	movea.l	(sp)+,a1                        ; a1 = the EXIT line
	move.b	(a0),d0                         ; d0 = WEND line length
	move.l	a0,2(a1)                        ; EXIT jumps to the line after WEND
	add.l	d0,2(a1)                        ; (+ length)
	bra.s	.wend_exit                      ; more EXITs?
.wend_while:
	cmpi.b	#$4,(sp)                        ; WHILE ($04) open?
	bne.w	structure_error_jump            ; no: structure error
	movea.l	(sp)+,a1                        ; a1 = the WHILE line
	move.l	a1,2(a0)                        ; WEND gets the WHILE line
	move.b	(a0),d0                         ; d0 = WEND line length
	lea	0(a0,d0.w),a2                   ; a2 = the line after WEND
	move.l	a2,2(a1)                        ; WHILE gets the line after WEND
	bra.w	link_skip_line                  ; next line
.next_exit:
	cmpi.b	#$88,(sp)                       ; NEXT: EXIT inside the FOR ($88) waiting?
	bne.s	.next_for                       ; no: the FOR itself
	movea.l	(sp)+,a1                        ; a1 = the EXIT line
	move.b	(a0),d0                         ; d0 = NEXT line length
	move.l	a0,2(a1)                        ; EXIT jumps to the line after NEXT
	add.l	d0,2(a1)                        ; (+ length)
	move.b	6(a0),d0                        ; loop variable token: int or float
	andi.b	#$f,d0                          ; type nibble: 0 = float
	beq.s	.next_exit_float                ; float: type $14
	move.b	#$8,2(a1)                       ; type byte $08 in the EXIT's address long
	bra.s	.next_exit                      ; more EXITs?
.next_exit_float:
	move.b	#$14,2(a1)                      ; type byte $14 for a float loop variable
	bra.s	.next_exit                      ; more EXITs?
.next_for:
	cmpi.b	#$8,(sp)                        ; FOR ($08) open?
	bne.w	structure_error_jump            ; no: structure error
	movea.l	(sp)+,a1                        ; a1 = the FOR line
	move.w	6(a0),d1                        ; same loop variable as the FOR?
	cmp.w	6(a1),d1                        ; compare with the FOR's variable token
	bne.w	structure_error_jump            ; different: structure error
	move.b	8(a0),d0                        ; second index byte of the NEXT ...
	cmp.b	8(a1),d0                        ; ... and of the FOR
	beq.s	.link_for_next                  ; same: link them
	cmpi.w	#$f000,d1                       ; index below $f000 must match in both bytes
	bcc.s	structure_error_jump            ; 2-byte index differs: structure error
.link_for_next:
	move.b	(a0),d0                         ; d0 = NEXT line length
	lea	0(a0,d0.w),a2                   ; a2 = the line after NEXT
	move.l	a2,2(a1)                        ; FOR gets the line after NEXT
	move.b	(a1),d0                         ; d0 = FOR line length
	lea	0(a1,d0.w),a2                   ; a2 = the line after FOR
	move.l	a2,2(a0)                        ; NEXT gets the line after FOR
	bra.w	link_skip_line                  ; next line
	cmpi.b	#$b,(sp)                        ; ENDIF: IF or ELSE open?
	beq.s	.link_endif                     ; IF: link it
	cmpi.b	#$c,(sp)                        ; ELSE ($0c) open?
	bne.s	structure_error_jump            ; no: structure error
.link_endif:
	movea.l	(sp)+,a1                        ; a1 = the IF or ELSE line
	move.b	(a0),d0                         ; d0 = ENDIF line length
	lea	0(a0,d0.w),a2                   ; a2 = the line after ENDIF
	move.l	a2,2(a1)                        ; IF/ELSE gets the line after ENDIF
	bra.w	link_skip_line                  ; next line
	cmpi.b	#$b,(sp)                        ; ELSE: IF open?
	bne.s	structure_error_jump            ; no: structure error
	movea.l	(sp)+,a1                        ; a1 = the IF line
	move.b	(a0),d0                         ; d0 = ELSE line length
	lea	0(a0,d0.w),a2                   ; a2 = the line after ELSE
	move.l	a2,2(a1)                        ; IF gets the line after ELSE
	move.l	a0,-(sp)                        ; push the ELSE line ...
	move.b	#$c,(sp)                        ; ELSE stays open as $0c
	bra.w	link_skip_line                  ; next line
	move.b	(sp),d1                         ; EXIT: innermost REPEAT/WHILE/DO/FOR?
	andi.b	#$7f,d1                         ; type without the EXIT bit
	cmpi.b	#$2,d1                          ; REPEAT?
	beq.s	.mark_exit                      ; yes
	cmpi.b	#$4,d1                          ; WHILE?
	beq.s	.mark_exit                      ; yes
	cmpi.b	#$6,d1                          ; DO?
	beq.s	.mark_exit                      ; yes
	cmpi.b	#$8,d1                          ; FOR?
	bne.s	structure_error_jump            ; none of them: structure error
.mark_exit:
	move.l	a0,-(sp)                        ; push the EXIT line ...
	ori.b	#$80,d1                         ; push the EXIT as that type + $80
	move.b	d1,(sp)                         ; ... with its tag
	bra.w	link_skip_line                  ; next line

;------------------------------------------------------------------------------
; Branch to structure_error (in short reach of the handlers).
;------------------------------------------------------------------------------
structure_error_jump:
	bra.s	structure_error                 ; (the alert)

;------------------------------------------------------------------------------
; End of the program: any structure still on the stack is a structure error (the line is kept
; in structure_error_line); otherwise checks the GOTO and RESUME targets.
;------------------------------------------------------------------------------
link_check_unclosed:
	move.b	(sp),d0                         ; anything still open at the end?
	beq.s	.all_closed                     ; marker reached: nothing open
	move.l	(sp)+,d1                        ; d1 = the open line with its token
	andi.l	#$ffffff,d1                     ; line address only
	move.l	d1,structure_error_line         ; remembered for the error
	andi.b	#$7f,d0                         ; type without the EXIT bit
	cmpi.b	#$2,d0                          ; REPEAT without UNTIL
	beq.s	structure_error                 ; (error)
	cmpi.b	#$4,d0                          ; WHILE without WEND
	beq.s	structure_error                 ; (error)
	cmpi.b	#$6,d0                          ; DO without LOOP
	beq.s	structure_error                 ; (error)
	cmpi.b	#$8,d0                          ; FOR without NEXT
	beq.s	structure_error                 ; (error)
	cmpi.b	#$b,d0                          ; IF without ENDIF
	beq.s	structure_error                 ; (error)
	cmpi.b	#$c,d0                          ; ELSE without ENDIF
	beq.s	structure_error                 ; (error)
	cmpi.b	#$2b,d0                         ; PROCEDURE without RETURN
	beq.s	structure_error                 ; (error)
	bra.s	structure_error                 ; every case ends in the same error
.all_closed:
	addq.l	#4,sp                           ; drop the marker
	bra.w	check_goto_targets              ; all closed: check GOTOs and RESUMEs

;------------------------------------------------------------------------------
; Structure error: shows the alert, drops the open structures down to the zero marker and
; returns d7 = -1. Also holds the PROCEDURE, RETURN and label handlers.
;------------------------------------------------------------------------------
structure_error:
	lea	cant_compile_alert,a0           ; structure error alert (text in another range)
	moveq	#1,d0                           ; default button 1
	bsr.w	form_alert_call                 ; show the alert
.clear_stack:
	tst.l	(sp)+                           ; drop the open structures down to the marker
	bne.s	.clear_stack                    ; until the zero marker is dropped
	moveq	#-1,d7                          ; error result
	rts                                     ; back to the main loop with d7 = -1
.error:
	bra.s	structure_error_jump            ; (the alert)
	tst.l	(sp)                            ; PROCEDURE: nothing may be open
	bne.s	.error                          ; yes: structure error
	pea	(a0)                            ; push the PROCEDURE line ...
	move.b	d0,(sp)                         ; ... with its token $2b
	moveq	#0,d1                           ; d1 = name index
	lea	2(a0),a2                        ; a2 = the name token
	move.b	(a2)+,d0                        ; d0 = name token
	move.b	(a2)+,d1                        ; index (low byte)
	cmpi.b	#$f0,d0                         ; name token: $e0+type, $f0+ with a 2-byte index
	bcs.s	.proc_index                     ; 1-byte index
	asl.w	#8,d1                           ; 2-byte index: high byte first
	move.b	(a2)+,d1                        ; low byte
.proc_index:
	asl.l	#4,d1                           ; * 16 bytes per entry
	movea.l	bss_end+$60,a1                  ; procedure table, 16 bytes per name
	adda.l	d1,a1                           ; a1 = its entry
	tst.l	(a1)                            ; defined twice?
	bne.s	.error                          ; yes: structure error
	move.l	a0,(a1)                         ; entry = the PROCEDURE line
	cmpi.b	#$46,(a2)+                      ; no parameters ('F')?
	beq.s	link_continue                   ; yes: done
	bra.w	store_parameter_types           ; store the parameter types
	cmpi.b	#$2b,(sp)                       ; RETURN: closes the PROCEDURE
	bne.s	.return_error                   ; no: structure error
	addq.l	#4,sp                           ; drop it
	bra.w	link_skip_line                  ; next line
.return_error:
	bra.w	structure_error_jump            ; (the alert)
	moveq	#0,d1                           ; label with a 1-byte index
	move.b	2(a0),d1                        ; index
	bra.s	.label_index                    ; find its entry
	moveq	#0,d1                           ; label with a 2-byte index
	move.b	2(a0),d1                        ; high byte of the index
	asl.w	#8,d1                           ; (shifted up)
	move.b	3(a0),d1                        ; low byte
.label_index:
	asl.l	#4,d1                           ; * 16 bytes per entry
	movea.l	bss_end+$5c,a1                  ; label table, 16 bytes per name
	adda.l	d1,a1                           ; a1 = its entry
	tst.l	(a1)                            ; defined twice?
	bne.s	structure_error_branch          ; yes: structure error
	move.l	a0,(a1)                         ; line after the label
	move.b	(a0),d0                         ; d0 = label line length
	add.l	d0,(a1)                         ; (+ length)
	lea	-$4(sp),a2                      ; look for an open PROCEDURE ...
.find_procedure:
	addq.l	#4,a2                           ; next stacked entry
	tst.b	(a2)                            ; stack marker: not in a procedure
	beq.s	link_continue                   ; done
	cmpi.b	#$2b,(a2)                       ; PROCEDURE ($2b)?
	bne.s	.find_procedure                 ; no: look further down
	move.b	#$1,(a1)                        ; label inside a procedure: flag byte 1

;------------------------------------------------------------------------------
; Next line after a handler.
;------------------------------------------------------------------------------
link_continue:
	moveq	#0,d0                           ; d0 cleared for the next class lookup
	bra.w	link_skip_line                  ; next line
	nop                                     ; nop after the bra, never reached
	lea	-$4(sp),a2                      ; unreferenced: PROCEDURE open check
.find_procedure:
	addq.l	#4,a2                           ; next stacked entry
	tst.b	(a2)                            ; stack marker reached?
	beq.s	structure_error_branch          ; yes: structure error
	cmpi.b	#$2b,(a2)                       ; PROCEDURE ($2b)?
	bne.s	.find_procedure                 ; no: look further down
	bra.w	link_skip_line                  ; next line

;------------------------------------------------------------------------------
; Branch to structure_error_jump (in short reach). Also holds the LOCAL and DEFFN handlers.
;------------------------------------------------------------------------------
structure_error_branch:
	bra.w	structure_error_jump            ; (the alert)
	cmpi.b	#$2b,(sp)                       ; LOCAL: only inside a PROCEDURE
	beq.w	link_skip_line                  ; yes: fine
	bra.w	structure_error_jump            ; no: structure error
	moveq	#0,d1                           ; DEFFN: register the function
	movea.l	a0,a2                           ; a2 = the function line
	addq.l	#2,a2                           ; step over length and token
	move.b	(a2)+,d7                        ; d7 = name token
	btst	#$4,d7                          ; bit 4: 2-byte index
	beq.s	.fn_index                       ; 1-byte index
	move.b	(a2)+,d1                        ; high byte of the index
	asl.w	#8,d1                           ; (shifted up)
.fn_index:
	move.b	(a2)+,d1                        ; low byte
	asl.l	#4,d1                           ; * 16 bytes per entry
	andi.w	#$f,d7                          ; type nibble selects the name table
	asl.w	#2,d7                           ; * 4: pointer index
	lea	bss_end+$3c,a1                  ; bounds of the name tables
	movea.l	0(a1,d7.w),a1                   ; a1 = the table of this type
	adda.l	d1,a1                           ; a1 = its entry
	tst.l	(a1)                            ; defined twice?
	bne.s	.fn_defined_twice               ; yes: structure error
	move.l	a0,(a1)                         ; entry = the DEFFN line
	cmpi.b	#$45,(a2)+                      ; no parameters ('E')?
	beq.w	link_skip_line                  ; yes: done
	bra.w	store_parameter_types           ; store the parameter types
.fn_defined_twice:
	movea.l	(sp)+,a0                        ; (drop a stacked line)
	bra.w	structure_error_jump            ; structure error

;------------------------------------------------------------------------------
; Compiler: after linking, checks every GOTO and every RESUME label: the
; lines between the GOTO and its label (from the label to the next RETURN
; for RESUME) must hold as many FOR/PROCEDURE as NEXT/RETURN, else the
; structure error. Exit: d7 = 0.
;------------------------------------------------------------------------------
check_goto_targets:
	movea.l	bss_end+$30,a0                  ; a0 = first source line
	moveq	#0,d0                           ; d0 = line length
.next_line:
	move.b	(a0),d0                         ; line length
	move.b	1(a0),d1                        ; command token
	cmpi.b	#$df,d1                         ; $df: end of the program
	beq.s	.done                           ; yes: all checked
	cmpi.b	#$2d,d1                         ; $2d: GOTO
	beq.s	.goto                           ; yes: check it
	cmpi.b	#$87,d1                         ; $87: RESUME
	beq.s	.resume                         ; yes: check it
.skip_line:
	adda.w	d0,a0                           ; next line
	bra.s	.next_line                      ; go on
.done:
	moveq	#0,d7                           ; no error
	rts                                     ; return
.resume:
	cmpi.b	#$e0,2(a0)                      ; RESUME with a label (not NEXT or a number)?
	bcs.s	.skip_line                      ; no: nothing to check
	bra.w	.resume_label                   ; check the label
.goto:
	moveq	#0,d3                           ; d3 = label index
	lea	2(a0),a1                        ; a1 = the label token
	move.b	(a1)+,d1                        ; d1 = label token
	btst	#$4,d1                          ; bit 4: 2-byte index
	beq.s	.label_index                    ; 1-byte index
	move.b	(a1)+,d3                        ; high byte
	asl.w	#8,d3                           ; (shifted up)
.label_index:
	move.b	(a1)+,d3                        ; low byte
	asl.l	#4,d3                           ; * 16 bytes per entry
	add.l	bss_end+$5c,d3                  ; label table entry
	movea.l	d3,a1                           ; a1 = its entry
	move.l	(a1),d3                         ; d3 = line after the label
	andi.l	#$ffffff,d3                     ; (24 bits)
	movea.l	d3,a1                           ; a1 = that line
	beq.s	.skip_line                      ; label not defined: skip
	cmpa.l	a0,a1                           ; GOTO to its own line?
	beq.s	.skip_line                      ; yes: nothing to check
	pea	(a0)                            ; keep the GOTO line
	cmpa.l	a0,a1                           ; scan from the lower line to the higher one
	bhi.s	.scan_between                   ; the label is after the GOTO
	exg	a1,a0                           ; before it: swap the bounds
.scan_between:
	moveq	#0,d7                           ; d7 = open minus closed
	moveq	#0,d2                           ; (zero-extended line lengths)
.scan_line:
	move.b	(a0),d2                         ; d2 = line length
	move.b	1(a0),d1                        ; d1 = command token
	cmpi.b	#$8,d1                          ; FOR
	beq.s	.count_open                     ; FOR: one more open
	cmpi.b	#$9,d1                          ; NEXT
	beq.s	.count_next                     ; NEXT: one closed
	cmpi.b	#$2b,d1                         ; PROCEDURE
	beq.s	.count_open                     ; PROCEDURE: one more open
	cmpi.b	#$2e,d1                         ; RETURN
	beq.s	.count_close                    ; RETURN: one closed
.scan_next:
	adda.w	d2,a0                           ; next line
	cmpa.l	a1,a0                           ; reached the upper bound?
	bcs.s	.scan_line                      ; no: go on
.scan_done:
	movea.l	(sp)+,a0                        ; a0 = the GOTO line again
	tst.l	d7                              ; balanced: fine
	beq.s	.skip_line                      ; yes: next line
	clr.l	-(sp)                           ; stack marker for the error routine
	bra.w	structure_error_jump            ; structure error
.count_open:
	addq.l	#1,d7                           ; one more open
	bra.s	.scan_next                      ; next line
.count_close:
	subq.l	#1,d7                           ; one closed
	bra.s	.scan_next                      ; next line
.count_next:
	subq.l	#1,d7                           ; one closed
	bpl.s	.scan_next                      ; not below zero: go on
	bra.s	.scan_done                      ; a NEXT before its FOR: error
.resume_label:
	moveq	#0,d3                           ; d3 = label index
	lea	2(a0),a1                        ; a1 = the label token
	move.b	(a1)+,d1                        ; d1 = label token
	btst	#$4,d1                          ; bit 4: 2-byte index
	beq.s	.resume_index                   ; 1-byte index
	move.b	(a1)+,d3                        ; high byte
	asl.w	#8,d3                           ; (shifted up)
.resume_index:
	move.b	(a1)+,d3                        ; low byte
	asl.l	#4,d3                           ; * 16 bytes per entry
	add.l	bss_end+$5c,d3                  ; + label table
	movea.l	d3,a1                           ; a1 = its entry
	move.l	(a1),d3                         ; d3 = line after the label
	movea.l	d3,a1                           ; a1 = that line
	beq.w	.skip_line                      ; not defined: nothing to check
	moveq	#0,d7                           ; d7 = open minus closed
	moveq	#0,d2                           ; (zero-extended line lengths)
.resume_scan:
	move.b	(a1),d2                         ; d2 = line length
	move.b	1(a1),d1                        ; d1 = command token
	cmpi.b	#$8,d1                          ; FOR?
	beq.s	.resume_open                    ; yes: one more open
	cmpi.b	#$9,d1                          ; NEXT?
	beq.s	.resume_close                   ; yes: one closed
	cmpi.b	#$2b,d1                         ; PROCEDURE?
	beq.s	.resume_end                     ; yes: end of the scan
	cmpi.b	#$2e,d1                         ; RETURN?
	beq.s	.resume_end                     ; yes: end of the scan
	cmpi.b	#$df,d1                         ; end of the program?
	beq.s	.resume_end                     ; yes: end of the scan
.resume_next:
	adda.w	d2,a1                           ; next line
	bra.s	.resume_scan                    ; go on
.resume_end:
	tst.l	d7                              ; balanced?
	beq.w	.skip_line                      ; yes: next line
	clr.l	-(sp)                           ; stack marker for the error routine
	bra.w	structure_error_jump            ; structure error
.resume_open:
	addq.l	#1,d7                           ; one more open
	bra.s	.resume_next                    ; next line
.resume_close:
	subq.l	#1,d7                           ; one closed
	bpl.s	.resume_next                    ; not below zero: go on
	bra.s	.resume_end                     ; unbalanced

;------------------------------------------------------------------------------
; Compiler: a2 = parameter list of a PROCEDURE/DEFFN line (name tokens
; separated by $21), a1 = its name table entry. Stores the parameter count
; at (a1) and the 2-bit types of the parameters, first in the top bits, as
; a 96-bit value at 4(a1).
;------------------------------------------------------------------------------
store_parameter_types:
	moveq	#0,d0                           ; d0 = parameter count
	moveq	#0,d1                           ; d1-d3 = 96 bits of types
	moveq	#0,d2                           ; (clear)
	moveq	#0,d3                           ; (clear)
.next_param:
	move.b	(a2)+,d4                        ; parameter name token
	cmpi.b	#$f0,d4                         ; 2-byte index?
	bcs.s	.add_type                       ; no
	addq.l	#1,a2                           ; step over the second index byte
.add_type:
	addq.l	#1,a2                           ; step over the index byte
	addq.w	#1,d0                           ; count it
	andi.w	#$3,d4                          ; low 2 bits of the token: the type
	add.l	d3,d3                           ; shift the 96 bits left by 2 ...
	addx.l	d2,d2                           ; (carry into d2)
	addx.l	d1,d1                           ; (carry into d1)
	add.l	d3,d3                           ; (second bit)
	addx.l	d2,d2                           ; (carry into d2)
	addx.l	d1,d1                           ; (carry into d1)
	or.w	d4,d3                           ; insert the type in the low bits
	cmpi.b	#$21,(a2)+                      ; $21 = another parameter
	beq.s	.next_param                     ; yes: next one
	move.b	d0,(a1)                         ; parameter count
	neg.w	d0                              ; 48 slots of 2 bits ...
	addi.w	#$30,d0                         ; ... minus those used: shifts still needed
.align_words:
	cmpi.w	#$10,d0                         ; shift the bits to the top, 16 at a time
	bcs.s	.shift_loop                     ; fewer than 16: shift by twos
	exg	d1,d2                           ; 16 slots (32 bits) at a time ...
	exg	d2,d3                           ; ... by moving the longs up
	subi.w	#$10,d0                         ; 16 slots done
	bra.s	.align_words                    ; again
.shift_two:
	add.l	d3,d3                           ; shift the 96 bits left by 2
	addx.l	d2,d2                           ; (carry into d2)
	addx.l	d1,d1                           ; (carry into d1)
	add.l	d3,d3                           ; (second bit)
	addx.l	d2,d2                           ; (carry into d2)
	addx.l	d1,d1                           ; (carry into d1)
.shift_loop:
	dbra	d0,.shift_two                   ; for each remaining slot
	movem.l	d1-d3,4(a1)                     ; the types, first parameter in the top bits
	bra.w	link_continue                   ; next line

;------------------------------------------------------------------------------
; Runtime (copied into compiled programs, never run by the compiler). Routine 1, the first
; block and the program entry. a5 = basepage, a6 = text + offset of routine 2 (patched),
; a4 = BSS start (runtime variables), a5 = variables + $8000. Mshrink, Line-A init, GEM init
; (rt_gem_init), Malloc of all but 16K for the string heap, variable type bases to $70(a4),
; then rt_run and routine 3. Runtime calls are jsr n(a6) with n the routine number, replaced
; by the copier.
;------------------------------------------------------------------------------
rt_program_start:
	bra.s	rt_startup                      ; routine 1: the program starts here

; Runtime data: ESC E ESC f ESC v (clear the screen, cursor off, wrap on), decoded as code.
rt_str_init_screen:
	dc.w	$1b45,$1b66,$1b76,$0000,$0000   ; ESC E ESC f ESC v (clear, cursor off, wrap on), decoded as code

;------------------------------------------------------------------------------
; Runtime start-up: a5 = basepage from the stack.
;------------------------------------------------------------------------------
rt_startup:
	movea.l	4(sp),a5                        ; a5 = basepage

;------------------------------------------------------------------------------
; Runtime start-up: lea $100(a5),a6, its displacement patched by write_program so that a6
; points at routine 2; then Mshrink to text + data + BSS, a4 = BSS start.
;------------------------------------------------------------------------------
rt_set_runtime_base:
	lea	$100(a5),a6                     ; displacement patched by write_program: a6 = routine base
	movea.l	$c(a5),a0                       ; text + data + BSS + $100: program size for Mshrink
	adda.l	$14(a5),a0                      ; + data length
	adda.l	$1c(a5),a0                      ; + BSS length
	adda.w	#$100,a0                        ; + the basepage
	pea	(a0)                            ; size to keep
	pea	(a5)                            ; block = the basepage
	clr.w	-(sp)                           ; reserved word
	move.w	#$4a,-(sp)                      ; GEMDOS $4a
	trap	#1                              ; Mshrink
	movea.l	$18(a5),a4                      ; a4 = BSS start
	move.l	$10(a5),$ade(a4)                ; data segment address
	move.l	$14(a5),d0                      ; data segment length

;------------------------------------------------------------------------------
; Runtime start-up: subi.l #n,d0 with n patched by write_program (the length of the second
; data part): $ae6(a4) = length of the DATA items. Then the stack at the BSS end, a5 =
; variables + $8000, Line-A init, GEM init, the string heap and the variable type bases.
;------------------------------------------------------------------------------
rt_data_length_patch:
	subi.l	#$2b67,d0                       ; immediate patched by write_program (second data part length)
	move.b	rt_data_pad_flag(pc),d1         ; one byte less when the flag is set
	beq.s	.store_data_length              ; no pad byte
	subq.l	#1,d0                           ; one less
.store_data_length:
	move.l	d0,$ae6(a4)                     ; length of the DATA items
	move.l	$1c(a5),d0                      ; stack at the BSS end
	lea	0(a4,d0.l),sp                   ; sp = end of the BSS
	lea	$31fe(a4),a5                    ; a5 = variables + $8000 (d16(a5) reaches 64K)
	adda.l	#$8000,a5                       ; (the $8000 bias)
	dc.w	$a000                           ; Line-A Initialise
	addq.l	#8,a0                           ; Line-A variable table + 8
	lea	rn_mouse_show_intin_patch(a6),a1 ; operand of routine $11e
	move.l	a0,2(a1)                        ; into routine $11e's move.l operand
	jsr	rn_gem_init(a6)                 ; GEM init
	pea	$ffffffff.w                     ; Malloc(-1): largest free block
	move.w	#$48,-(sp)                      ; GEMDOS $48
	trap	#1                              ; Malloc
	subi.l	#$4000,d0                       ; keep 16K for the system
	move.l	d0,$6c(a4)                      ; size of the string heap
	move.l	d0,-(sp)                        ; that size
	move.w	#$48,-(sp)                      ; GEMDOS $48
	trap	#1                              ; Malloc
	move.l	d0,$68(a4)                      ; string heap start
	movea.l	d0,a3                           ; a3 = string area bottom
	move.l	d0,$58(a4)                      ; string area start
	add.l	$6c(a4),d0                      ; + size
	move.l	d0,$64(a4)                      ; string area top
	move.l	d0,$60(a4)                      ; free space top
	lea	rt_var_type_offsets(pc),a0      ; 9 offsets of the variable types, set by the compiler
	lea	$70(a4),a1                      ; the 9 variable type bases at $70(a4)
	moveq	#8,d1                           ; 9 longs
.set_var_bases:
	move.l	(a0)+,d0                        ; offset from a5 ...
	add.l	a5,d0                           ; ... + a5
	move.l	d0,(a1)+                        ; = base address of the type
	dbra	d1,.set_var_bases               ; all 9
	movem.l	a3-sp,rn_saved_registers(a6)    ; registers saved in routine 4 (a data block)
	jsr	rn_bombs_install(a6)            ; routine $1bc: install the handlers

;------------------------------------------------------------------------------
; Runtime routine $12f (RUN), also the end of the start-up: restores the start-up registers,
; graphics defaults (routine $244), clears the screen, sets the first word of each of the 101
; 6-byte entries at $888(a4) to -1, empties the procedure stack (a3 = $5c(a4)), CLEAR
; (routine $154), then routine 3: the program.
;------------------------------------------------------------------------------
rt_run:
	lea	rn_saved_registers(a6),a0       ; routine $12f: restore the start-up registers
	movem.l	(a0),a3-sp                      ; a3-a7 as at the start
	jsr	rn_graphics_defaults(a6)        ; routine $244: graphics defaults
	pea	rt_str_init_screen(pc)          ; clear screen, cursor off, wrap on
	move.w	#$9,-(sp)                       ; GEMDOS 9
	trap	#1                              ; Cconws
	addq.l	#6,sp                           ; drop the arguments
	moveq	#100,d0                         ; 101 entries of 6 bytes at $888(a4) set to -1
	lea	$878(a4),a0                     ; (the 101-entry table at $888(a4))
	moveq	#-1,d1                          ; d1 = $ffff
.clear_table:
	move.w	d1,(a0)+                        ; first word of the entry = -1
	addq.l	#4,a0                           ; skip the rest of the 6-byte entry
	dbra	d0,.clear_table                 ; all 101
	move.l	a3,$5c(a4)                      ; procedure stack empty: a3 = string area bottom
	jsr	rn_clear(a6)                    ; routine $154: CLEAR
	jmp	rn_runtime_routine_table(a6)    ; routine 3

; Runtime data: byte set by the compiler when the DATA items end with an odd pad byte.
rt_data_pad_flag:
	dc.w	$0000

; Runtime data: 9 longs set by the compiler, the start offsets of the variable types from a5
; (float, string, int, bool, the four arrays, the end).
rt_var_type_offsets:
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000 ; start offsets of the variable types from a5 (set by
                                                ;   the compiler)
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000

; Runtime data: the last of the 9 offsets, the end of the variable storage.
rt_var_storage_end:
	dc.w	$0000,$0000

;------------------------------------------------------------------------------
; Runtime routine $79 (BASEPAGE): d0 = a0 = basepage address (routine 1 is at basepage + $100).
;------------------------------------------------------------------------------
rt_basepage:
	lea	rn_program_start(a6),a0         ; a0 = text start (basepage + $100)
	suba.w	#$100,a0                        ; back to the basepage
	move.l	a0,d0                           ; d0 = basepage address
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $c2: d0 = a4 + the BSS length (basepage + $1c): the end of the BSS.
;------------------------------------------------------------------------------
rt_bss_end:
	lea	rn_program_start(a6),a0         ; a0 = text start (basepage + $100)
	move.l	a4,d0                           ; BSS start ...
	add.l	-$e4(a0),d0                     ; ... + BSS length (basepage + $1c)
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $b5 (HIMEM): d0 = end of the string heap block ($68(a4) + $6c(a4)).
;------------------------------------------------------------------------------
rt_himem:
	move.l	$68(a4),d0                      ; string heap block address ...
	add.l	$6c(a4),d0                      ; ... + its size
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $58 (FRE): string garbage collection (routine $203), then d0 = free string
; space ($60(a4) - a3).
;------------------------------------------------------------------------------
rt_fre:
	jsr	rn_string_garbage_collect(a6)   ; garbage collection first
	move.l	$60(a4),d0                      ; free space top ...
	sub.l	a3,d0                           ; ... - the string area bottom
	rts                                     ; return

; Runtime data: 26 offsets in a4 of the GEM arrays; rt_gem_init writes their addresses from
; (a4) on (the AES and VDI parameter blocks). Decoded as code to $5899.
rt_gem_array_offsets:
	dc.w	$02e4,$02f0,$074a,$0772,$079a,$07c2,$02cc,$030e ; 26 offsets in a4 of the GEM arrays, decoded as code to
                                                ;   $5899
	dc.w	$040e,$060e,$070e,$10e6,$02f0,$10f2,$111a,$1142
	dc.w	$116a,$1192,$11aa,$13aa,$12aa,$15aa

;------------------------------------------------------------------------------
; Runtime, called by Supexec: sets conterm bit 3, so Bconin returns the shift state too.
;------------------------------------------------------------------------------
rt_set_conterm_bit3:
	bset	#$3,$484.w                      ; conterm, conterm bit 3: Bconin returns the shift state too
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $21e: GEM init. Sets conterm bit 3 (Supexec), finds the shift-state byte
; (rt_find_shift_state_byte), builds the GEM parameter pointers at (a4), appl_init,
; graf_mouse, graf_handle, v_opnvwk, then the window system (routine $214).
;------------------------------------------------------------------------------
rt_gem_init:
	pea	rt_set_conterm_bit3(pc)         ; set conterm bit 3 ...
	move.w	#$26,-(sp)                      ; XBIOS $26 in supervisor mode
	trap	#14                             ; Supexec
	addq.l	#6,sp                           ; drop the arguments
	jsr	rn_find_shift_state_byte(a6)    ; address of the shift-state byte
	lea	rt_gem_array_offsets(pc),a1     ; 26 offsets
	lea	(a4),a0                         ; pointers written from (a4) on
	moveq	#25,d0                          ; 26 entries
.set_pointers:
	movea.l	a4,a2                           ; a2 = a4 ...
	adda.w	(a1)+,a2                        ; ... + offset
	move.l	a2,(a0)+                        ; the pointer
	dbra	d0,.set_pointers                ; all 26
	moveq	#10,d0                          ; AES 10 appl_init
	jsr	rn_aes_call(a6)                 ; call it
	move.w	$772(a4),$2f4(a4)               ; ap_id
	clr.w	$74a(a4)                        ; intin[0] = 0
	moveq	#78,d0                          ; AES 78 graf_mouse
	jsr	rn_aes_call(a6)                 ; arrow pointer
	moveq	#77,d0                          ; AES 77 graf_handle
	jsr	rn_aes_call(a6)                 ; d0 = VDI handle of the screen
	move.w	d0,$2d8(a4)                     ; VDI handle
	moveq	#100,d0                         ; v_opnvwk: work_in 1 x10, 2
	lea	$30e(a4),a0                     ; intin from $30e(a4)
	moveq	#9,d1                           ; 10 words
.set_intin:
	move.w	#$1,(a0)+                       ; work_in[0..9] = 1
	dbra	d1,.set_intin                   ; all 10
	move.w	#$2,(a0)                        ; work_in[10] = 2: raster coordinates
	moveq	#0,d2                           ; no ptsin
	moveq	#11,d1                          ; 11 intin words
	jsr	rn_vdi_call_intin_ptsin(a6)     ; VDI 100 v_opnvwk with 11 intin words
	move.w	$2d8(a4),$119e(a4)              ; handle of the virtual workstation

;------------------------------------------------------------------------------
; Runtime routine $a3: jumps to routine $214, the window system start (also the end of
; rt_gem_init).
;------------------------------------------------------------------------------
rt_window_start_jump:
	jmp	rn_window_system_init(a6)       ; routine $214: window system start
	rts                                     ; first word of the next block, not an entry

;------------------------------------------------------------------------------
; Runtime: v_clsvwk (VDI 101) and appl_exit (AES 19).
;------------------------------------------------------------------------------
rt_gem_exit:
	moveq	#101,d0                         ; VDI 101
	bsr.s	rt_vdi_call                     ; close the workstation
	moveq	#19,d0                          ; AES 19
	bra.s	rt_aes_call                     ; call it and return

;------------------------------------------------------------------------------
; Runtime, called by Supexec: clears conterm bit 3.
;------------------------------------------------------------------------------
rt_clear_conterm_bit3:
	bclr	#$3,$484.w                      ; conterm
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routines $201/$207 (END and the program end): closes GEM, routine $1bd (removes the
; handlers), clears conterm bit 3 and ends with Pterm0.
;------------------------------------------------------------------------------
rt_end_program:
	bsr.s	rt_gem_exit                     ; routines $201/$207: program end
	jsr	rn_bombs_remove(a6)             ; routine $1bd
	pea	rt_clear_conterm_bit3(pc)       ; clear conterm bit 3 ...
	move.w	#$26,-(sp)                      ; XBIOS $26 in supervisor mode
	trap	#14                             ; Supexec
	clr.w	(sp)                            ; Pterm0
	trap	#1                              ; GEMDOS
	dc.w	$01ba                           ; word $01ba after Pterm0: a routine number word the copier patches

;------------------------------------------------------------------------------
; Runtime routine $21b: AES call, d0 = opcode, contrl[1..3] from rt_aes_control_table (3
; bytes per opcode). Shows the mouse first (routine $11f). Exit: d0 = intout[0].
;------------------------------------------------------------------------------
rt_aes_call:
	lea	$2e4(a4),a1                     ; a1 = contrl
	move.w	d0,(a1)+                        ; contrl[0] = opcode
	lea	rt_aes_control_table(pc),a0     ; 3 bytes per opcode
	adda.w	d0,a0                           ; opcode * 3 ...
	add.w	d0,d0                           ; (opcode * 2)
	adda.w	d0,a0                           ; ... entry for the opcode
	moveq	#0,d0                           ; byte values zero-extended
	move.b	(a0)+,d0                        ; contrl[1] = intin count
	move.w	d0,(a1)+                        ; (stored)
	move.b	(a0)+,d0                        ; contrl[2] = intout count
	move.w	d0,(a1)+                        ; (stored)
	move.b	(a0)+,d0                        ; contrl[3] = addrin count
	move.w	d0,(a1)+                        ; (stored)
	jsr	rn_mouse_show(a6)               ; routine $11f first
	moveq	#0,d1                           ; d1 = a4: the AES parameter block
	add.l	a4,d1                           ; (the address)
	move.w	#$c8,d0                         ; $c8 = AES, parameter block at a4
	trap	#2                              ; AES/VDI
	move.w	$772(a4),d0                     ; d0 = intout[0]
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $13c (COLOR): VDI 17 vsl_color with intin[0] = d0.
;------------------------------------------------------------------------------
rt_color:
	moveq	#17,d1                          ; VDI 17 vsl_color

;------------------------------------------------------------------------------
; Runtime routine $242: VDI call d1 with intin[0] = d0.
;------------------------------------------------------------------------------
rt_vdi_call_opcode_d1:
	exg	d0,d1                           ; d0 = opcode, d1 = value

;------------------------------------------------------------------------------
; Runtime routine $243: VDI call d0 with intin[0] = d1.
;------------------------------------------------------------------------------
rt_vdi_call_intin_d1:
	move.w	d1,$30e(a4)                     ; intin[0] = value
	moveq	#1,d1                           ; 1 intin word
	bra.s	rt_vdi_call_counts              ; call it

;------------------------------------------------------------------------------
; Runtime routine $276 (GRAPHMODE): VDI 32 vswr_mode with intin[0] = d0.
;------------------------------------------------------------------------------
rt_graphmode:
	moveq	#32,d3                          ; VDI 32 vswr_mode

;------------------------------------------------------------------------------
; Runtime routine $21f: VDI call d3 with intin[0] = d0.
;------------------------------------------------------------------------------
rt_vdi_call_opcode_d3:
	exg	d0,d3                           ; d0 = opcode, d3 = value

;------------------------------------------------------------------------------
; Runtime routine $21d: VDI call d0 with intin[0] = d3.
;------------------------------------------------------------------------------
rt_vdi_call_intin_d3:
	move.w	d3,$30e(a4)                     ; intin[0] = value
	moveq	#1,d1                           ; 1 intin word
	bra.s	rt_vdi_call_counts              ; call it

;------------------------------------------------------------------------------
; Runtime routine $21c: VDI call d0 with no intin and no ptsin. Exit: d0 = intout[0].
;------------------------------------------------------------------------------
rt_vdi_call:
	moveq	#0,d1                           ; no intin

;------------------------------------------------------------------------------
; Runtime: VDI call d0 with d1 intin words and no ptsin.
;------------------------------------------------------------------------------
rt_vdi_call_counts:
	moveq	#0,d2                           ; no ptsin

;------------------------------------------------------------------------------
; Runtime routine $21a: VDI call d0 with d1 intin words and d2 ptsin pairs; hides the mouse
; first (routine $15f). Exit: d0 = intout[0].
;------------------------------------------------------------------------------
rt_vdi_call_intin_ptsin:
	move.w	d0,$2cc(a4)                     ; contrl[0] = opcode
	move.w	d1,$2d2(a4)                     ; contrl[3] = intin count
	move.w	d2,$2ce(a4)                     ; contrl[1] = ptsin count
	jsr	rn_hidem(a6)                    ; routine $15f first
	moveq	#24,d1                          ; d1 = a4 + 24: the VDI parameter block
	add.l	a4,d1                           ; (the address)
	moveq	#115,d0                         ; $73 = VDI
	trap	#2                              ; AES/VDI
	move.w	$60e(a4),d0                     ; d0 = intout[0]
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $218 (VDISYS n): VDI call n with the program's VDISYS arrays.
;------------------------------------------------------------------------------
rt_vdisys_opcode:
	move.w	d0,$1192(a4)                    ; intin[0] of the VDISYS arrays = opcode

;------------------------------------------------------------------------------
; Runtime routine $219 (VDISYS): VDI call with the VDISYS parameter block (a4 + 68) as the
; program set it; hides the mouse once first (routine $205).
;------------------------------------------------------------------------------
rt_vdisys:
	jsr	rn_mouse_hide(a6)               ; hide the mouse once
	moveq	#68,d1                          ; d1 = a4 + 68: the VDISYS parameter block
	add.l	a4,d1                           ; (the address)
	moveq	#115,d0                         ; $73 = VDI
	trap	#2                              ; AES/VDI
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $216 (GEMSYS n): AES call n with the program's GEMSYS arrays; for opcodes
; 10-125 contrl[1..3] come from rt_aes_control_table first.
;------------------------------------------------------------------------------
rt_gemsys_opcode:
	lea	$10e6(a4),a1                    ; a1 = the GEMSYS contrl
	move.w	d0,(a1)+                        ; contrl[0] = opcode
	cmpi.w	#$a,d0                          ; below 10: contrl as the program set it
	bcs.s	rt_aes_call_block
	cmpi.w	#$7d,d0                         ; above 125: the same
	bhi.s	rt_aes_call_block
	lea	rt_aes_control_table(pc),a0     ; 3 bytes per opcode
	adda.w	d0,a0                           ; opcode * 3 ...
	add.w	d0,d0                           ; (opcode * 2)
	adda.w	d0,a0                           ; ... entry for the opcode

;------------------------------------------------------------------------------
; Runtime: the rest of rt_gemsys_opcode (contrl[1..3] from the table). The AES table itself:
; 3 bytes per opcode from this address, opcode 10 at $59ea.
;------------------------------------------------------------------------------
rt_aes_control_table:
	moveq	#0,d0                           ; code, and 3 bytes per AES opcode from here: opcode 10 is at $59ea
	move.b	(a0)+,d0                        ; contrl[1] = intin count
	move.w	d0,(a1)+                        ; (stored)
	move.b	(a0)+,d0                        ; contrl[2] = intout count
	move.w	d0,(a1)+                        ; (stored)
	move.b	(a0)+,d0                        ; contrl[3] = addrin count
	move.w	d0,(a1)+                        ; (stored)

;------------------------------------------------------------------------------
; Runtime routine $217 (GEMSYS): AES call with the GEMSYS parameter block (a4 + 44) as the
; program set it; routine $206 first.
;------------------------------------------------------------------------------
rt_aes_call_block:
	jsr	rn_mouse_show_if_hidden(a6)     ; routine $217 enters here, routine $206 first
	moveq	#44,d1                          ; d1 = a4 + 44: the GEMSYS parameter block
	add.l	a4,d1                           ; (the address)
	move.w	#$c8,d0                         ; $c8 = AES
	trap	#2                              ; AES/VDI
	rts                                     ; return
	dc.w	$0001,$0002,$0101,$0201,$0100,$0101,$0201,$0101 ; AES opcode table bytes from here to $5b45, decoded as
                                                ;   code
	dc.w	$0101,$0000,$0000,$0000,$0000,$0000,$0100,$0001
	dc.w	$0003,$0500,$0505,$0000,$0101,$0201,$0010,$0701
	dc.w	$0201,$0000,$0000,$0000,$0000,$0000,$0101,$0102
	dc.w	$0101,$0201,$0102,$0101,$0101,$0201,$0101,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0201,$0101,$0101
	dc.w	$0601,$0104,$0101,$0103,$0102,$0101,$0402,$0108
	dc.w	$0101,$0000,$0000,$0000,$0101,$0109,$0101,$0101
	dc.w	$0101,$0100,$0005,$0100,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0403,$0008,$0300,$0601,$0008,$0100
	dc.w	$0801,$0004,$0101,$0301,$0100,$0500,$0101,$0100
	dc.w	$0500,$0001,$0100,$0101,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0002,$0200,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0501
	dc.w	$0005,$0100,$0101,$0001,$0100,$0205,$0006,$0100
	dc.w	$0201,$0001,$0100,$0605,$0000,$0000,$0001,$0100
	dc.w	$0100,$0201,$0002,$0101,$0101,$0100,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0001,$0203,$0102
	dc.w	$0101,$0101,$0101,$0001,$0100,$0102

;------------------------------------------------------------------------------
; Runtime routine $1c9: finds the TOS shift-state byte. Pauses the IKBD (Bconout 4,$13),
; sets each shift state with Kbshift and searches $a01-$7fff for a byte that follows all 16,
; writes that address into routine $1c8's operand, restores the state and resumes the IKBD
; ($11).
;------------------------------------------------------------------------------
rt_find_shift_state_byte:
	moveq	#19,d0                          ; IKBD $13: pause output
	bsr.s	rt_ikbd_send                    ; send it
	moveq	#-1,d6                          ; Kbshift(-1): read the state
	bsr.s	rt_kbshift                      ; (Kbshift)
	move.w	d0,d5                           ; d5 = the state, restored at the end
	move.w	#$a00,d7                        ; search from $a11 on
.toggle_state:
	moveq	#15,d6                          ; state 15: all four shift keys
	bsr.s	rt_kbshift                      ; set it
.scan_memory:
	addq.w	#1,d7                           ; next address
	bmi.s	.restore                        ; past $8017: not found
	movea.w	d7,a0                           ; a0 = the address
	cmp.b	(a0),d6                         ; does it hold the state?
	beq.s	.compare_state                  ; yes: try the other states
	bra.s	.scan_memory                    ; no: next address
.next_state:
	bsr.s	rt_kbshift                      ; set state d6
	movea.w	d7,a0                           ; a0 = the candidate
	cmp.b	(a0),d6                         ; does it follow?
.compare_state:
	dbne	d6,.next_state                  ; down to state 0 or a mismatch
	bne.s	.toggle_state                   ; mismatch: go on searching
	lea	rn_break_kbshift(a6),a0         ; patch the address into routine $1c8
	move.w	d7,2(a0)                        ; the address into routine $1c8's operand
.restore:
	move.w	d5,d6                           ; the original state
	bsr.s	rt_kbshift                      ; set it back
	moveq	#17,d0                          ; IKBD $11: resume output

;------------------------------------------------------------------------------
; Runtime: Bconout(4, d0): a byte to the IKBD.
;------------------------------------------------------------------------------
rt_ikbd_send:
	move.w	d0,-(sp)                        ; Bconout(4 = IKBD, d0)
	move.w	#$4,-(sp)                       ; device 4: IKBD
	move.w	#$3,-(sp)                       ; BIOS 3
	trap	#13                             ; Bconout
	addq.l	#6,sp                           ; drop the arguments
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime: Kbshift(d6). Exit: d0 = the old state.
;------------------------------------------------------------------------------
rt_kbshift:
	move.w	d6,-(sp)                        ; Kbshift(d6)
	move.w	#$b,-(sp)                       ; BIOS 11
	trap	#13                             ; Kbshift
	addq.l	#4,sp                           ; drop the arguments
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $12c: load the float at (a0)+ into d3-d5. Floats in registers: d0 =
; mantissa (top bit set), d1.w = low mantissa bits, d2.w = exponent (bias $200, 0 = value 0),
; sign in bit 31 of d2; second operand in d3-d5. Stored floats are 6 bytes: long + word,
; exponent in the low 10 bits, sign in bit 31, top mantissa bit implied.
;------------------------------------------------------------------------------
rt_float_load_d3_d5:
	move.l	(a0)+,d3                        ; mantissa long, sign in bit 31
	move.w	(a0)+,d4                        ; low word: mantissa bits and exponent
	move.l	d3,d5                           ; d5 = sign ...
	move.w	d4,d5                           ; d5 = exponent
	andi.w	#$3ff,d5                        ; ... and the 10-bit exponent
	sub.w	d5,d4                           ; d4 = mantissa bits only
	bset	#$1f,d3                         ; implied top bit
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $df: loads the float at (a0) and returns through routine $f1, giving the
; long in d0.
;------------------------------------------------------------------------------
rt_float_load_to_long:
	pea	rn_float_to_long(a6)            ; return through routine $f1

;------------------------------------------------------------------------------
; Runtime routine $e0: loads the float at (a0)+ into d0-d2.
;------------------------------------------------------------------------------
rt_float_load:
	move.l	(a0)+,d0                        ; mantissa long, sign in bit 31
	move.w	(a0)+,d1                        ; low word: mantissa bits and exponent

;------------------------------------------------------------------------------
; Runtime routine $f2: unpacks the stored form d0.l/d1.w into d0-d2.
;------------------------------------------------------------------------------
rt_float_unpack:
	move.l	d0,d2                           ; d2 = sign ...
	move.w	d1,d2                           ; ... and the low word
	andi.w	#$3ff,d2                        ; keep the 10-bit exponent
	sub.w	d2,d1                           ; d1 = mantissa bits only
	bset	#$1f,d0                         ; implied top bit
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $e1: rounds d0-d2 and stores it as 6 bytes at (a0)+. Underflow stores 0,
; overflow the largest value.
;------------------------------------------------------------------------------
rt_float_store:
	addi.w	#$200,d1                        ; round the mantissa at the stored precision
	bcc.s	.check_range                    ; no carry: in range?
	addq.l	#1,d0                           ; carry into the long
	bcc.s	.check_range                    ; no carry out
	roxr.l	#1,d0                           ; mantissa overflowed: shift it back ...
	roxr.w	#1,d1                           ; (low word)
	addq.w	#1,d2                           ; ... and raise the exponent
.check_range:
	cmpi.w	#$3ff,d2                        ; exponent in range?
	bhi.s	.out_of_range                   ; no: zero or the largest value
	andi.w	#$fc00,d1                       ; keep the 6 mantissa bits of the low word
	or.w	d2,d1                           ; + the exponent
	tst.l	d2                              ; negative?
	bmi.s	.store                          ; yes: the sign stays in bit 31
	bclr	#$1f,d0                         ; positive: clear the implied bit
.store:
	move.l	d0,(a0)+                        ; store the long
	move.w	d1,(a0)+                        ; and the word
	rts                                     ; return
.out_of_range:
	tst.w	d2                              ; exponent negative: underflow
	bpl.s	.store_max                      ; positive: overflow
	clr.l	(a0)+                           ; zero
	clr.w	(a0)+                           ; (6 bytes)
	rts                                     ; return
.store_max:
	move.l	#$7fffffff,(a0)+                ; largest positive value
	move.w	#$ffff,(a0)+                    ; (low word, exponent $3ff)
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime: float add with the first operand zero: the result is the second.
;------------------------------------------------------------------------------
rt_float_add_second_result:
	move.l	d3,d0                           ; first operand zero: result = second
	move.w	d4,d1                           ; (low word)
	move.l	d5,d2                           ; (exponent and sign)

;------------------------------------------------------------------------------
; Runtime: float add with the second operand zero or too small: the result is the first.
;------------------------------------------------------------------------------
rt_float_add_first_result:
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $11a: d0-d2 = d0-d2 - d3-d5.
;------------------------------------------------------------------------------
rt_float_sub:
	bchg	#$1f,d5                         ; negate the second operand
	bra.s	rt_float_add                    ; and add

;------------------------------------------------------------------------------
; Runtime routine 5: d0-d2 = d3-d5 - d0-d2.
;------------------------------------------------------------------------------
rt_float_reverse_sub:
	bchg	#$1f,d2                         ; negate the first operand

;------------------------------------------------------------------------------
; Runtime routine 6: d0-d2 = d0-d2 + d3-d5. Aligns the smaller mantissa, adds or subtracts
; the 48-bit mantissas by the signs and normalises a difference.
;------------------------------------------------------------------------------
rt_float_add:
	move.w	d2,d6                           ; d6 = first exponent
	beq.s	rt_float_add_second_result      ; first is zero: the result is the second
	tst.w	d5                              ; second zero?
	beq.s	rt_float_add_first_result       ; yes: the result is the first
	sub.w	d5,d6                           ; exponent difference
	bpl.s	.align                          ; first larger: align the second
	exg	d0,d3                           ; larger operand into d0-d2
	exg	d1,d4                           ; (low words)
	exg	d2,d5                           ; (exponents and signs)
	neg.w	d6                              ; positive difference
.align:
	cmpi.w	#$10,d6                         ; shift the smaller mantissa right by the difference
	bcs.s	.align_small                    ; below 16 bits
	cmpi.w	#$20,d6                         ; 32 bits or more?
	bcc.s	.align_32                       ; yes
	andi.w	#$f,d6                          ; 16-31: shift by the rest after moving a word
	lsr.l	d6,d3                           ; mantissa long right
	move.w	d3,d4                           ; its low word into d4
	clr.w	d3                              ; and the long shifted 16 more
	swap	d3                              ; (high word to the low word)
	bra.s	.add_or_sub                     ; add or subtract
.align_32:
	cmpi.w	#$30,d6                         ; more than 48 bits: the smaller operand is lost
	bhi.s	rt_float_add_first_result       ; (the result is the larger operand)
	andi.w	#$f,d6                          ; 32-48: shift by the rest after moving a long
	lsr.l	d6,d3                           ; mantissa long right
	swap	d3                              ; (high word down)
	move.w	d3,d4                           ; into d4
	moveq	#0,d3                           ; nothing left in the long
	bra.s	.add_or_sub                     ; add or subtract
.align_small:
	swap	d4                              ; d4 low word into the high half
	move.w	d3,d4                           ; d3's low word below it
	lsr.l	d6,d3                           ; mantissa long right
	ror.l	d6,d4                           ; bits shifted out of d3 come in on top
	swap	d4                              ; d4 = the new low word
.add_or_sub:
	eor.l	d2,d5                           ; same signs: add the mantissas
	bmi.s	.subtract                       ; different signs: subtract
	add.w	d4,d1                           ; add the low words
	addx.l	d3,d0                           ; and the longs with the carry
	bcc.s	.add_exit                       ; no carry out
	roxr.l	#1,d0                           ; carry: shift it in ...
	roxr.w	#1,d1                           ; (low word)
	addq.w	#1,d2                           ; ... and raise the exponent
.add_exit:
	rts                                     ; return
.subtract:
	sub.w	d4,d1                           ; subtract the low words
	subx.l	d3,d0                           ; and the longs with the borrow
	bcc.s	rt_float_normalise_flags        ; no borrow: normalise
	bchg	#$1f,d2                         ; the result's sign is the other one
	neg.w	d1                              ; negate the mantissa ...
	negx.l	d0                              ; (long with the borrow)

;------------------------------------------------------------------------------
; Runtime routine $f6: normalises d0-d2 with the flags already set from d0 (N set: done, Z
; set: the high long is zero).
;------------------------------------------------------------------------------
rt_float_normalise_flags:
	bmi.s	rt_normalise_done               ; routine $f6 enters here
	beq.s	rt_normalise_low_word           ; high long zero: try the low word
.shift_left:
	add.w	d1,d1                           ; shift left one bit ...
	addx.l	d0,d0                           ; (into the long)
	dbmi	d2,.shift_left                  ; ... decrementing the exponent, until the top bit is set

;------------------------------------------------------------------------------
; Runtime: the shift that ended the normalise loop lowers the exponent too; below 0 the
; result is 0.
;------------------------------------------------------------------------------
rt_normalise_last_shift:
	subq.w	#1,d2                           ; the last shift
	bmi.s	rt_float_zero                   ; exponent underflow: zero

;------------------------------------------------------------------------------
; Runtime: shared return of the normalise routines.
;------------------------------------------------------------------------------
rt_normalise_done:
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $f5: normalises d0-d2 (sets the flags from d0, then rt_float_normalise_flags);
; a normalised value with a negative exponent becomes 0.
;------------------------------------------------------------------------------
rt_float_normalise:
	tst.l	d0                              ; routine $f5: normalise d0-d2
	bge.s	rt_float_normalise_flags        ; top bit clear: normalise
	tst.w	d2                              ; exponent negative?
	bmi.s	rt_float_zero                   ; yes: zero
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime: normalise with the high long zero: the low word moves up 32 bits first.
;------------------------------------------------------------------------------
rt_normalise_low_word:
	move.w	d1,d0                           ; low word into the high word
	beq.s	rt_float_zero                   ; all zero: the value 0
	swap	d0                              ; (high half)
	moveq	#0,d1                           ; low word now empty
	subi.w	#$20,d2                         ; 32 bits less
	tst.l	d0                              ; already normalised?
	bmi.s	rt_normalise_done               ; yes: done
.shift_long:
	add.l	d0,d0                           ; shift left one bit ...
	dbmi	d2,.shift_long                  ; ... until the top bit is set
	bra.s	rt_normalise_last_shift         ; finish the exponent

;------------------------------------------------------------------------------
; Runtime routine $fd: exponent check of d0-d2: above $3ff a negative exponent word gives 0,
; a positive one an overflow (rt_float_overflow).
;------------------------------------------------------------------------------
rt_float_check_range:
	cmpi.w	#$3ff,d2                        ; routine $fd: exponent above $3ff is out of range
	bhi.s	.exponent_bad                   ; out of range
	rts                                     ; return
.exponent_bad:
	tst.w	d2                              ; negative: underflow to 0, else overflow
	bpl.s	rt_float_overflow               ; positive: overflow

;------------------------------------------------------------------------------
; Runtime: d0-d2 = 0.
;------------------------------------------------------------------------------
rt_float_zero:
	moveq	#0,d0                           ; the value 0
	moveq	#0,d1                           ; (low word)
	moveq	#0,d2                           ; (exponent 0)
	rts                                     ; return

; Runtime routine $1b6 (data): byte nonzero = no Overflow error; the next byte is set when an
; overflow happens meanwhile.
rt_overflow_flags:
	dc.b	$00                             ; routine $1b6: byte nonzero = no overflow error; $1b7: set on overflow

; Runtime routine $1b7 (data): byte set on an overflow while errors are off.
rt_overflow_seen_flag:
	dc.b	$00

;------------------------------------------------------------------------------
; Runtime: float overflow. When routine $1b6's byte is set, sets $1b7 and returns the largest
; value, otherwise error 1 (Overflow).
;------------------------------------------------------------------------------
rt_float_overflow:
	pea	(a0)                            ; keep a0
	lea	rt_overflow_flags(pc),a0        ; a0 = the two flag bytes
	tst.b	(a0)+                           ; overflow errors wanted?
	beq.s	.error                          ; yes: error 1
	st	(a0)                            ; no: note the overflow in the second byte
	moveq	#-1,d0                          ; largest value
	moveq	#-1,d1                          ; (low word)
	move.l	#$3ff,d2                        ; exponent $3ff, positive
	movea.l	(sp)+,a0                        ; a0 back
	rts                                     ; return
.error:
	moveq	#1,d0                           ; error 1: Overflow
	movea.l	(sp)+,a0                        ; a0 back
	jmp	rn_error_entry(a6)              ; routine 2: runtime error, d0 = GFA error number

;------------------------------------------------------------------------------
; Runtime: float multiply with a zero operand: the result is 0.
;------------------------------------------------------------------------------
rt_float_mul_zero:
	moveq	#0,d2                           ; the value 0
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $151: d0-d2 = d0-d2 squared (falls into routine 7).
;------------------------------------------------------------------------------
rt_float_square:
	move.l	d0,d3                           ; second operand = the first
	move.w	d1,d4                           ; (low word)
	move.l	d2,d5                           ; (exponent and sign)

;------------------------------------------------------------------------------
; Runtime routine 7: d0-d2 = d0-d2 * d3-d5, from 16-bit mulu partial products of the 48-bit
; mantissas (the lowest product is left out).
;------------------------------------------------------------------------------
rt_float_mul:
	tst.w	d5                              ; second operand zero?
	beq.s	rt_float_mul_zero               ; yes: the result is 0
	tst.w	d2                              ; first operand zero?
	beq.s	rt_float_mul_zero               ; yes: the result is 0
	tst.l	d5                              ; second operand negative?
	bpl.s	.mul_exponent                   ; no: the sign stays
	bchg	#$1f,d2                         ; yes: flip the result's sign
.mul_exponent:
	add.w	d5,d2                           ; sum of the exponents minus the bias
	subi.w	#$1ff,d2                        ; (1.0 is $80000000 with exponent $200)
	move.w	d3,d5                           ; 48x48-bit product from 16-bit mulu pieces
	mulu.w	d0,d5                           ; low word of x * low word of y
	swap	d3                              ; d3.w = high word of y
	mulu.w	d3,d1                           ; low bits of x * high word of y
	add.l	d5,d1                           ; + the first product
	swap	d0                              ; d0.w = high word of x
	mulu.w	d0,d4                           ; high word of x * low bits of y
	move.w	d3,d5                           ; d5 = high word of y ...
	mulu.w	d0,d5                           ; ... * high word of x: the top product
	moveq	#0,d6                           ; (for the carries)
	addx.l	d6,d5                           ; carry of the first sum into the top
	add.l	d4,d1                           ; + the third product
	addx.l	d6,d5                           ; its carry into the top
	move.w	d3,d6                           ; d6 = high word of y
	swap	d3                              ; d3.w = low word of y
	move.w	d0,d7                           ; d7 = high word of x
	swap	d0                              ; d0.w = low word of x
	mulu.w	d6,d0                           ; low word of x * high word of y
	mulu.w	d7,d3                           ; low word of y * high word of x
	add.l	d3,d0                           ; sum of the two cross products
	bcc.s	.mul_no_carry                   ; no carry
	addi.l	#$10000,d5                      ; carry: one more at bit 16 of the top
.mul_no_carry:
	swap	d1                              ; middle word ...
	add.w	d0,d1                           ; ... + low half of the cross products
	clr.w	d0                              ; high half of the cross products ...
	swap	d0                              ; (into the low word)
	addx.l	d5,d0                           ; ... + the top product: d0 = top 32 bits
	bmi.s	.mul_check                      ; normalised already
	swap	d1                              ; one bit left to normalise:
	add.l	d1,d1                           ; low word up one bit
	swap	d1                              ; (back)
	addx.l	d0,d0                           ; into the long
	subq.w	#1,d2                           ; and the exponent one lower
.mul_check:
	cmpi.w	#$3ff,d2                        ; exponent in range?
	bhi.s	.mul_overflow                   ; no
	rts                                     ; return
.mul_overflow:
	jmp	rn_float_check_range(a6)        ; underflow to 0 or overflow

;------------------------------------------------------------------------------
; Runtime: error 0, Division by zero.
;------------------------------------------------------------------------------
rt_float_div_by_zero:
	moveq	#0,d0                           ; error 0: Division by zero
	jmp	rn_error_entry(a6)              ; runtime error

;------------------------------------------------------------------------------
; Runtime: float divide with the dividend zero: the result is 0.
;------------------------------------------------------------------------------
rt_float_div_zero_dividend:
	rts                                     ; dividend 0: the result is 0

;------------------------------------------------------------------------------
; Runtime routine 8: d0-d2 = d3-d5 / d0-d2 (swaps the operands, then routine $11b).
;------------------------------------------------------------------------------
rt_float_reverse_div:
	exg	d0,d3                           ; swap the operands ...
	exg	d1,d4                           ; (low words)
	exg	d2,d5                           ; (exponents and signs)

;------------------------------------------------------------------------------
; Runtime routine $11b: d0-d2 = d0-d2 / d3-d5. Three 16-bit quotient digits by divu of the
; remainder by the divisor's top word, each corrected against the full divisor. Error 0 for a
; zero divisor.
;------------------------------------------------------------------------------
rt_float_div:
	tst.w	d5                              ; divisor zero?
	beq.s	rt_float_div_by_zero            ; yes: error 0
	tst.w	d2                              ; dividend zero?
	beq.s	rt_float_div_zero_dividend      ; yes: the result is 0
	tst.l	d5                              ; divisor negative?
	bpl.s	.div_exponent                   ; no: the sign stays
	bchg	#$1f,d2                         ; yes: flip the result's sign
.div_exponent:
	sub.w	d5,d2                           ; difference of the exponents ...
	addi.w	#$200,d2                        ; ... + the bias
	lsr.l	#1,d0                           ; dividend right one bit, so the first digit fits a word
	roxr.w	#1,d1                           ; (low word)
	andi.b	#$fe,d4                         ; divisor low word even
	move.l	d3,d5                           ; d5 = top word of the divisor
	swap	d5                              ; (in the low word)
	divu.w	d5,d0                           ; three 16-bit quotient digits with divu and correction
	move.w	d0,-(sp)                        ; keep the first quotient digit
	move.w	d0,d6                           ; digit * divisor (divu did the top word):
	move.w	d0,d7                           ; (copy for the low part)
	move.w	d1,d0                           ; remainder: the divu remainder and the next word
	moveq	#0,d1                           ; (next word: 0)
	mulu.w	d3,d6                           ; digit * the divisor's second word
	mulu.w	d4,d7                           ; digit * its third word
	swap	d7                              ; (its high half)
	add.w	d7,d6                           ; the two products lined up
	bcc.s	.div_first_ok                   ; no carry
	addi.l	#$10000,d6                      ; carry into the high word
.div_first_ok:
	swap	d7                              ; (low half of the low product)
	sub.w	d7,d1                           ; remainder - digit * divisor
	subx.l	d6,d0                           ; (the long)
	bcc.s	.div_second                     ; not negative: the digit is right
.div_fix_first:
	subq.w	#1,(sp)                         ; digit one too large
	add.w	d4,d1                           ; add the divisor back
	addx.l	d3,d0                           ; (the long)
	bcc.s	.div_fix_first                  ; until the remainder is positive again
.div_second:
	divu.w	d5,d0                           ; second digit
	bvs.s	.div_overflow_first             ; overflow: digit $ffff
	move.w	d0,-(sp)                        ; keep the second digit
	move.w	d0,d6                           ; digit * divisor (divu did the top word):
	move.w	d0,d7                           ; (copy for the low part)
	move.w	d1,d0                           ; remainder: the divu remainder and the next word
	moveq	#0,d1                           ; (next word: 0)
	mulu.w	d3,d6                           ; digit * the divisor's second word
	mulu.w	d4,d7                           ; digit * its third word
	swap	d7                              ; (its high half)
	add.w	d7,d6                           ; the two products lined up
	bcc.s	.div_second_ok                  ; no carry
	addi.l	#$10000,d6                      ; carry into the high word
.div_second_ok:
	swap	d7                              ; (low half of the low product)
	sub.w	d7,d1                           ; remainder - digit * divisor
	subx.l	d6,d0                           ; (the long)
	bcc.s	.div_third                      ; not negative: the digit is right
.div_fix_second:
	subq.w	#1,(sp)                         ; digit one too large
	add.w	d4,d1                           ; add the divisor back
	addx.l	d3,d0                           ; (the long)
	bcc.s	.div_fix_second                 ; until the remainder is positive again
.div_third:
	divu.w	d5,d0                           ; third digit
	bvs.s	.div_overflow_second            ; overflow: digit $ffff
	move.w	d0,-(sp)                        ; keep the third digit
	move.w	d0,d6                           ; digit * divisor (divu did the top word):
	move.w	d0,d7                           ; (copy for the low part)
	move.w	d1,d0                           ; remainder for the rounding test
	moveq	#0,d1                           ; (next word: 0)
	mulu.w	d3,d6                           ; digit * the divisor's second word
	mulu.w	d4,d7                           ; digit * its third word
	swap	d7                              ; (its high half)
	add.w	d7,d6                           ; the two products lined up
	bcc.s	.div_third_ok                   ; no carry
	addi.l	#$10000,d6                      ; carry into the high word
.div_third_ok:
	swap	d7                              ; (low half of the low product)
	sub.w	d7,d1                           ; remainder - digit * divisor
	subx.l	d6,d0                           ; (the long)
	bcc.s	.div_result                     ; not negative: the digit is right
	subq.w	#1,(sp)                         ; digit one too large
.div_result:
	move.w	(sp)+,d1                        ; d1 = third digit
	move.l	(sp)+,d0                        ; d0 = first and second digits ...
	swap	d0                              ; ... in the right order
	jmp	rn_float_normalise_flags(a6)    ; normalise (routine $f6)
.div_overflow_first:
	move.w	#$ffff,-(sp)                    ; digit $ffff
	move.l	d3,d6                           ; remainder -= divisor * $ffff:
	move.w	d4,d7                           ; (divisor * $10000 - divisor)
	sub.w	d3,d7                           ; (low words)
	subx.w	d5,d6                           ; (high words with the borrow)
	bcc.s	.div_adjust                     ; no borrow
	subi.l	#$10000,d5                      ; (borrow into the top word)
.div_adjust:
	sub.w	d7,d1                           ; subtract it
	subx.l	d6,d0                           ; (the long)
	swap	d0                              ; remainder for the third digit
	move.w	d1,d0                           ; (next word)
	moveq	#0,d1                           ; (low word: 0)
	bra.s	.div_third                      ; third digit
.div_overflow_second:
	move.w	#$ffff,-(sp)                    ; digit $ffff
	bra.s	.div_result                     ; finish

;------------------------------------------------------------------------------
; Runtime: d0-d2 = d0-d2 * 10 (x + x/4 with the exponent raised by 3).
;------------------------------------------------------------------------------
rt_float_mul10:
	tst.w	d2                              ; d0-d2 * 10: x + x/4, exponent + 3
	beq.s	.done                           ; zero stays zero
	addq.w	#3,d2                           ; * 8 by the exponent ...
	move.l	d0,d3                           ; ... + a quarter (x * 1.25 * 8 = x * 10)
	move.w	d1,d4                           ; (low word)
	lsr.l	#1,d3                           ; x / 2
	roxr.w	#1,d4                           ; (low word)
	lsr.l	#1,d3                           ; x / 4
	roxr.w	#1,d4                           ; (low word)
	add.w	d4,d1                           ; add it
	addx.l	d3,d0                           ; (the long)
	bcc.s	.done                           ; no carry: done
	roxr.l	#1,d0                           ; carry: shift it in ...
	roxr.w	#1,d1                           ; (low word)
	addq.w	#1,d2                           ; ... and raise the exponent
.done:
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime: mantissa d0:d1 = d0:d1 * 10 + the digit in the low nibble of d4 (d3 used).
;------------------------------------------------------------------------------
rt_mantissa_mul10_add:
	andi.w	#$f,d4                          ; mantissa d0:d1 = d0:d1 * 10 + digit d4
	add.w	d1,d1                           ; * 2
	addx.l	d0,d0                           ; (the long)
	move.l	d0,d3                           ; d3:d4 = 2x + digit
	add.w	d1,d4                           ; (low word + digit)
	bcc.s	.no_carry                       ; no carry
	addq.l	#1,d3                           ; carry into the long
.no_carry:
	add.w	d1,d1                           ; * 4 ...
	addx.l	d0,d0                           ; (the long)
	add.w	d1,d1                           ; * 8
	addx.l	d0,d0                           ; (the long)
	add.w	d4,d1                           ; 8x + 2x + digit
	addx.l	d3,d0                           ; (the long)
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $f4, the decimal part of VAL: reads a number from the text at a0 (spaces,
; sign, digits, point, E exponent) into d0-d2; a0 after it. d2 = -1 for no number or an
; overflow (overflow errors are off meanwhile).
;------------------------------------------------------------------------------
rt_text_to_float:
	moveq	#0,d0                           ; mantissa 0
	moveq	#0,d1                           ; (low word)
	moveq	#0,d2                           ; sign and exponent 0
	moveq	#0,d6                           ; d6 = decimal exponent
	move.w	#$ff00,rn_overflow_flags(a6)    ; overflow errors off, none seen
.skip_spaces:
	move.b	(a0)+,d4                        ; next character
	cmpi.b	#$20,d4                         ; space?
	beq.s	.skip_spaces                    ; yes: skip it
	cmpi.b	#$2b,d4                         ; '+'?
	beq.s	.next_char                      ; yes: skip it
	cmpi.b	#$2d,d4                         ; '-'?
	bne.s	.check_point                    ; no: the number starts
	bset	#$1f,d2                         ; negative
.next_char:
	move.b	(a0)+,d4                        ; next character
.check_point:
	cmpi.b	#$2e,d4                         ; '.'?
	beq.s	.frac_digits                    ; yes: the fraction digits
	subi.b	#$30,d4                         ; digit value
	cmpi.b	#$9,d4                          ; not a digit?
	bhi.w	.bad_number                     ; no number
	move.b	d4,d1                           ; first digit
.int_digits:
	move.b	(a0)+,d4                        ; next character
	cmpi.b	#$30,d4                         ; below '0'?
	bcs.s	.check_fraction                 ; end of the integer digits
	cmpi.b	#$39,d4                         ; above '9'?
	bhi.s	.check_fraction                 ; end of the integer digits
	cmpi.l	#$fffffff,d0                    ; mantissa full: count the digit as a power of ten
	bcc.s	.ignore_digit                   ; yes: ignore it
	bsr.s	rt_mantissa_mul10_add           ; mantissa * 10 + digit
	bra.s	.int_digits                     ; next digit
.ignore_digit:
	addq.w	#1,d6                           ; one more power of ten
	bra.s	.int_digits                     ; next digit
.check_fraction:
	cmpi.b	#$2e,d4                         ; '.'?
	bne.s	.check_exponent                 ; no: the exponent
.frac_digits:
	move.b	(a0)+,d4                        ; next character
	cmpi.b	#$30,d4                         ; below '0'?
	bcs.s	.check_exponent                 ; end of the fraction
	cmpi.b	#$39,d4                         ; above '9'?
	bhi.s	.check_exponent                 ; end of the fraction
	cmpi.l	#$fffffff,d0                    ; mantissa full?
	bcc.s	.frac_next                      ; yes: ignore the digit
	bsr.w	rt_mantissa_mul10_add           ; mantissa * 10 + digit
	subq.w	#1,d6                           ; one power of ten less
.frac_next:
	bra.s	.frac_digits                    ; next digit
.check_exponent:
	cmpi.b	#$45,d4                         ; 'E'?
	beq.s	.exponent_sign                  ; yes
	cmpi.b	#$65,d4                         ; 'e'?
	bne.s	.build_float                    ; no: the number is complete
.exponent_sign:
	move.b	(a0)+,d4                        ; character after the E
	cmpi.b	#$2b,d4                         ; '+'?
	beq.s	.exponent_char                  ; yes: skip it
	cmpi.b	#$2d,d4                         ; '-'?
	bne.s	.exponent_first                 ; no: perhaps a digit
	bset	#$1f,d6                         ; negative exponent
.exponent_char:
	move.b	(a0)+,d4                        ; next character
	cmpi.b	#$30,d4                         ; below '0'?
	bcs.s	.no_exponent                    ; not an exponent
	cmpi.b	#$39,d4                         ; up to '9'?
	ble.s	.exponent_first                 ; a digit
.no_exponent:
	subq.w	#1,a0                           ; back to the character
	bclr	#$1f,d6                         ; no exponent sign after all
	bra.s	.build_float                    ; finish
.exponent_first:
	subi.b	#$30,d4                         ; digit value
	cmpi.b	#$9,d4                          ; not a digit?
	bhi.s	.build_float                    ; no exponent: finish
	ext.w	d4                              ; d4 = exponent so far
.exponent_digits:
	moveq	#0,d5                           ; (zero-extended digit)
	move.b	(a0)+,d5                        ; next character
	subi.b	#$30,d5                         ; digit value
	cmpi.b	#$9,d5                          ; not a digit?
	bhi.s	.exponent_end                   ; end of the exponent
	mulu.w	#$a,d4                          ; exponent * 10 ...
	add.w	d5,d4                           ; ... + digit
	cmpi.w	#$3e8,d4                        ; exponent above 1000: not a number
	ble.s	.exponent_digits                ; no: next digit
	bra.s	.bad_number                     ; too large
.exponent_end:
	tst.l	d6                              ; negative exponent?
	bpl.s	.add_exponent                   ; no
	neg.w	d4                              ; yes: negate it
.add_exponent:
	add.w	d4,d6                           ; + the digits' power of ten
.build_float:
	subq.l	#1,a0                           ; a0 back onto the character after the number
	move.w	#$22f,d2                        ; integer mantissa: exponent bias + 47
	jsr	rn_float_normalise(a6)          ; normalise the integer mantissa
	tst.w	d6                              ; negative power of ten?
	bmi.s	.scale_down                     ; yes: divide
	subq.w	#1,d6                           ; power 0?
	bmi.s	.check_overflow                 ; yes: done
.scale_up:
	bsr.w	rt_float_mul10                  ; * 10 ...
	dbra	d6,.scale_up                    ; ... d6 times
	jsr	rn_float_normalise(a6)          ; normalise
	bra.s	.check_overflow                 ; check for an overflow
.scale_down:
	movem.l	d0-d2,-(sp)                     ; keep the mantissa
	bsr.s	rt_float_load_one               ; divide by 10^n: build 10^n, then routine 8
	not.w	d6                              ; count - 1 for the dbra
.power_loop:
	bsr.w	rt_float_mul10                  ; * 10 ...
	dbra	d6,.power_loop                  ; ... to build 10^n
	movem.l	(sp)+,d3-d5                     ; the number as the dividend
	jsr	rn_float_reverse_div(a6)        ; number / 10^n
.check_overflow:
	move.w	rn_overflow_flags(a6),d3        ; d3 low byte = overflow seen
	tst.b	d3                              ; any?
	beq.s	.done                           ; no: done
.bad_number:
	moveq	#-1,d2                          ; no number or an overflow: d2 = -1
.done:
	clr.w	rn_overflow_flags(a6)           ; overflow errors on again
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime: d0-d2 = 1.0.
;------------------------------------------------------------------------------
rt_float_load_one:
	moveq	#1,d0                           ; d0-d2 = 1.0
	ror.l	#1,d0                           ; $80000000
	moveq	#0,d1                           ; low word 0
	move.l	#$200,d2                        ; exponent $200: 1.0
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime: rt_float_to_digits for an exponent out of range: a negative exponent word gives
; the digits of 0, otherwise the largest value is converted.
;------------------------------------------------------------------------------
rt_float_digits_out_of_range:
	tst.w	d2                              ; negative exponent word?
	bmi.w	rt_float_digits_zero            ; yes: digits of 0
	move.w	#$3ff,d2                        ; else the largest value
	moveq	#-1,d1                          ; (low word)
	moveq	#-1,d0                          ; (mantissa)

;------------------------------------------------------------------------------
; Runtime routine $f7: converts d0-d2 to sign + 11 digits + E + sign + 3 digits in
; rt_digit_buffer. Exit: a0 = buffer, d0 = decimal exponent.
;------------------------------------------------------------------------------
rt_float_to_digits:
	lea	rt_digit_buffer(pc),a0          ; a0 = digit buffer
	lea	$c(a0),a1                       ; a1 = end of the 11 digits (after the sign)
	moveq	#32,d3                          ; sign ' '
	tst.w	d2                              ; zero?
	beq.s	.store_sign                     ; yes: positive
	tst.l	d2                              ; negative?
	bpl.s	.store_sign                     ; no
	moveq	#45,d3                          ; sign '-'
.store_sign:
	move.b	d3,(a0)+                        ; store the sign
	moveq	#0,d6                           ; d6 = decimal exponent
	cmpi.w	#$3ff,d2                        ; exponent out of range?
	bhi.s	rt_float_digits_out_of_range    ; yes: zero or the largest value
	cmpi.w	#$200,d2                        ; value below 1?
	bmi.s	.small                          ; yes: scale it up
	movem.l	d0-d2,-(sp)                     ; keep the number
	move.w	d2,d7                           ; d7 = its exponent
	bsr.s	rt_float_load_one               ; build a power of ten above it
.count_digits:
	bsr.w	rt_float_mul10                  ; * 10
	addq.w	#1,d6                           ; one more digit
	cmp.w	d2,d7                           ; still not above the number?
	bcc.s	.count_digits                   ; go on
	movem.l	(sp)+,d3-d5                     ; the number as the dividend
	move.w	d6,-(sp)                        ; keep the count
	jsr	rn_float_reverse_div(a6)        ; number / 10^n: below 1
	move.w	(sp)+,d6                        ; count back
.small:
	tst.w	d2                              ; zero?
	beq.w	rt_float_digits_zero            ; yes: digits of 0
.scale_up:
	bsr.w	rt_float_mul10                  ; * 10 ...
	subq.w	#1,d6                           ; ... one power less
	cmpi.w	#$200,d2                        ; until it is 1 or more
	bcs.s	.scale_up                       ; (below 1: again)
.align:
	cmpi.w	#$203,d2                        ; exponent $203: the units digit fills the top 4 bits
	beq.s	.round                          ; reached: round
	lsr.l	#1,d0                           ; shift right ...
	roxr.w	#1,d1                           ; (low word)
	addq.w	#1,d2                           ; ... raising the exponent
	bra.s	.align                          ; again
.round:
	addi.w	#$370,d1                        ; round at the last of the 11 digits
	bcc.s	rt_float_digits_loop            ; no carry: the digits
	addq.l	#1,d0                           ; carry into the long
	cmpi.l	#$9fffffff,d0                   ; the first digit still below 10?
	bcs.s	rt_float_digits_loop            ; yes: the digits

;------------------------------------------------------------------------------
; Runtime: the digits rounded past 9.99...: they become 1.000... and the decimal exponent is
; raised.
;------------------------------------------------------------------------------
rt_digits_round_up:
	move.l	#$10000000,d0                   ; 9.99... rounded up to 1.0
	moveq	#0,d1                           ; (low word)
	addq.w	#1,d6                           ; and the exponent one higher

;------------------------------------------------------------------------------
; Runtime: writes the digits of d0:d1 (the units digit in the top 4 bits) into the buffer up
; to a1, then E, the sign and 3 digits of the exponent d6. Exit: a0 = rt_digit_buffer.
;------------------------------------------------------------------------------
rt_float_digits_loop:
	move.l	d0,d3                           ; next digit from the top 4 bits
	rol.l	#4,d3                           ; top 4 bits into the low nibble
	andi.b	#$f,d3                          ; (digit value)
	ori.b	#$30,d3                         ; as ASCII
	move.b	d3,(a0)+                        ; store the digit
	andi.l	#$fffffff,d0                    ; remove it
	moveq	#0,d4                           ; add no digit
	bsr.w	rt_mantissa_mul10_add           ; fraction * 10
	cmpa.l	a1,a0                           ; all 11 digits done?
	bne.s	rt_float_digits_loop            ; no: next digit
	move.b	#$45,(a0)+                      ; 'E'
	moveq	#43,d3                          ; '+'
	move.w	d6,d0                           ; d0 = decimal exponent for the caller
	tst.w	d6                              ; negative?
	bpl.s	.store_exponent_sign            ; no
	neg.w	d6                              ; magnitude
	moveq	#45,d3                          ; '-'
.store_exponent_sign:
	move.b	d3,(a0)+                        ; store the exponent sign
	ext.l	d6                              ; (zero-extended)
	divu.w	#$64,d6                         ; hundreds
	ori.b	#$30,d6                         ; as ASCII
	move.b	d6,(a0)+                        ; store
	clr.w	d6                              ; remainder ...
	swap	d6                              ; (into the low word)
	divu.w	#$a,d6                          ; tens
	ori.b	#$30,d6                         ; as ASCII
	move.b	d6,(a0)+                        ; store
	swap	d6                              ; units (remainder)
	ori.b	#$30,d6                         ; as ASCII
	move.b	d6,(a0)+                        ; store
	lea	rt_digit_buffer(pc),a0          ; a0 = the digit buffer
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime: the digits of the value 0.
;------------------------------------------------------------------------------
rt_float_digits_zero:
	moveq	#0,d0                           ; mantissa 0
	moveq	#0,d1                           ; (low word)
	moveq	#0,d2                           ; (exponent)
	moveq	#0,d6                           ; decimal exponent 0
	bra.s	rt_float_digits_loop            ; the digits (all 0)

;------------------------------------------------------------------------------
; Runtime: rounds the digit string at a0 to rt_digit_count digits (the DEFNUM setting).
;------------------------------------------------------------------------------
rt_round_digit_string:
	move.w	rt_digit_count(pc),d1           ; the DEFNUM digit count

;------------------------------------------------------------------------------
; Runtime routine $1c3: rounds the digit string at a0 (sign, 11 digits, E...) to d1 digits;
; the digits after them become '0'.
;------------------------------------------------------------------------------
rt_round_digits_count_d1:
	pea	(a1)                            ; keep a1
	cmpi.w	#$b,d1                          ; 11 digits or more: nothing to round
	bcc.s	.done                           ; yes: done
	lea	1(a0,d1.w),a1                   ; a1 = the first digit dropped
	move.b	(a1),d2                         ; d2 = that digit
	cmpi.b	#$35,d2                         ; below '5'?
	bcs.s	.fill_zeros                     ; yes: just replace the rest by zeros
.carry:
	move.b	-(a1),d2                        ; previous digit ...
	addq.b	#1,d2                           ; ... + 1
	cmpi.b	#$30,d2                         ; the sign position passed (carry out of the top)?
	bls.s	.carry_out                      ; yes: becomes 1000...
	cmpi.b	#$39,d2                         ; still a digit?
	bls.s	.store_digit                    ; yes: store it
	move.b	#$30,(a1)                       ; '9' + 1: '0' and carry on
	bra.s	.carry                          ; next digit up
.carry_out:
	move.w	d0,d6                           ; decimal exponent
	addq.l	#1,a0                           ; (digit position)
	movea.l	(sp)+,a1                        ; a1 back: the digit loop ends there
	bra.w	rt_digits_round_up              ; write 1 and zeros, exponent + 1
.store_digit:
	move.b	d2,(a1)                         ; store the rounded digit
	lea	1(a0,d1.w),a1                   ; from the first dropped digit ...
.fill_zeros:
	move.b	#$30,(a1)+                      ; ... digits become '0'
	cmpi.b	#$45,(a1)                       ; up to the 'E'
	bne.s	.fill_zeros                     ; until there
.done:
	movea.l	(sp)+,a1                        ; a1 back
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $f8 (STR$ of a float): d0-d2 to text in rt_number_string_buffer, plain or
; with E for exponents outside -5..10. Exit: a0 = text, d0 = length.
;------------------------------------------------------------------------------
rt_float_to_string:
	pea	(a1)                            ; keep a1
	jsr	rn_float_to_digits(a6)          ; the digits and the decimal exponent d0
	bsr.s	rt_round_digit_string           ; rounded to the DEFNUM count
	lea	rt_number_string_buffer(pc),a1  ; a1 = output text
	moveq	#11,d1                          ; d1 = digits kept
	cmpi.b	#$20,(a0)+                      ; positive (space)?
	beq.s	.strip_zeros                    ; yes: no sign in the text
	move.b	-$1(a0),(a1)+                   ; the '-'
.strip_zeros:
	cmpi.b	#$30,-$1(a0,d1.w)               ; drop trailing zeros
	dbne	d1,.strip_zeros                 ; (counting down)
	tst.w	d1                              ; no digits left?
	beq.s	.zero                           ; yes: "0"
	cmpi.w	#$a,d0                          ; exponent above 10?
	bgt.s	.exponent_form                  ; yes: E form
	cmpi.w	#$fffb,d0                       ; below -5?
	blt.s	.exponent_form                  ; yes: E form
	tst.w	d0                              ; 1 or more?
	bpl.s	.copy_digit                     ; yes: digits from the start
	move.b	#$30,(a1)+                      ; "0."
	move.b	#$2e,(a1)+                      ; (the point)
	move.w	d0,d2                           ; zeros after the point ...
	neg.w	d2                              ; (- exponent ...
	subq.w	#2,d2                           ; ... - 1)
	bmi.s	.copy_digit                     ; none
.lead_zeros:
	move.b	#$30,(a1)+                      ; '0'
	dbra	d2,.lead_zeros                  ; for each
.copy_digit:
	move.b	(a0)+,(a1)+                     ; copy a digit
	subq.w	#1,d1                           ; one less left
	beq.s	.trail_zeros                    ; no more: pad with zeros to the point
	dbra	d0,.copy_digit                  ; until the integer digits are done
	move.b	#$2e,(a1)+                      ; then the point
	bra.s	.copy_digit                     ; and the rest
.trail_zeros:
	subq.w	#1,d0                           ; integer digits still missing?
	bmi.s	.terminate                      ; no: done
	move.b	#$30,(a1)+                      ; '0'
	bra.s	.trail_zeros                    ; again
.zero:
	move.b	#$30,(a1)+                      ; the text "0"
.terminate:
	clr.b	(a1)                            ; NUL
	lea	rt_number_string_buffer(pc),a0  ; a0 = text
	suba.l	a0,a1                           ; length ...
	move.l	a1,d0                           ; ... into d0
	movea.l	(sp)+,a1                        ; a1 back
	rts                                     ; return
.exponent_form:
	move.b	(a0)+,(a1)+                     ; first digit
	move.b	#$2e,(a1)+                      ; '.'
	move.b	(a0)+,(a1)+                     ; second digit
	subq.w	#3,d1                           ; (two digits copied, one for the dbra)
	bmi.s	.copy_exponent                  ; no more
.copy_mantissa:
	move.b	(a0)+,(a1)+                     ; the other digits
	dbra	d1,.copy_mantissa               ; (each)
.copy_exponent:
	lea	rt_exponent_text(pc),a0         ; the 'E', sign and 3 digits
	move.b	(a0)+,(a1)+                     ; 'E'
	move.b	(a0)+,(a1)+                     ; sign
	move.b	(a0)+,d0                        ; hundreds digit
	cmpi.b	#$30,d0                         ; '0'?
	beq.s	.exponent_tail                  ; yes: left out
	move.b	d0,(a1)+                        ; store it
.exponent_tail:
	move.b	(a0)+,(a1)+                     ; tens
	move.b	(a0)+,(a1)+                     ; units
	bra.s	.terminate                      ; finish

; Runtime data: the digit buffer, sign and 11 digits.
rt_digit_buffer:
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000

; Runtime data: E, the exponent sign and 3 digits, after the digit buffer.
rt_exponent_text:
	dc.w	$0000,$0000,$0000

; Runtime data: the text built by rt_float_to_string.
rt_number_string_buffer:
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000

; Runtime data: number of significant digits printed (DEFNUM), 11.
rt_digit_count:
	dc.w	$000b                           ; significant digits printed, 11

;------------------------------------------------------------------------------
; Runtime routine $200 (DEFNUM n): sets the digit count; below 3 is ignored.
;------------------------------------------------------------------------------
rt_defnum:
	cmpi.w	#$3,d0                          ; routine $200: set the digit count (d0 >= 3)
	bcs.s	.done                           ; fewer than 3: ignored
	lea	rt_digit_count(pc),a0           ; the digit count
	move.w	d0,(a0)                         ; set it
.done:
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $f3: rounds d0-d2 into the stored 6-byte form in d0/d1 (no store); overflow
; error through routine $fd.
;------------------------------------------------------------------------------
rt_float_round_packed:
	addi.w	#$200,d1                        ; round at the stored precision
	bcc.s	.check_range                    ; no carry: in range?
	addq.l	#1,d0                           ; carry into the long
	bcc.s	.check_range                    ; no carry out
	roxr.l	#1,d0                           ; mantissa overflowed: shift it back ...
	roxr.w	#1,d1                           ; (low word)
	addq.w	#1,d2                           ; ... and raise the exponent
.check_range:
	cmpi.w	#$3ff,d2                        ; exponent in range?
	bhi.s	.overflow                       ; no: zero or overflow
	andi.w	#$fc00,d1                       ; keep the 6 mantissa bits of the low word
	or.w	d2,d1                           ; + the exponent
	tst.l	d2                              ; negative?
	bmi.s	.packed                         ; yes: the sign stays in bit 31
	bclr	#$1f,d0                         ; positive: clear the implied bit
.packed:
	rts                                     ; return
.overflow:
	jmp	rn_float_check_range(a6)        ; underflow to 0 or overflow

;------------------------------------------------------------------------------
; Runtime routine $24 (SGN): nonzero becomes +/-1.0.
;------------------------------------------------------------------------------
rt_float_sgn:
	tst.w	d2                              ; zero?
	beq.s	.sgn_done                       ; yes: SGN = 0
	move.l	#$80000000,d0                   ; 1.0 ...
	moveq	#0,d1                           ; (low word)
	move.w	#$200,d2                        ; exponent $200, sign kept in the high word
.sgn_done:
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $27 (FRAC): the fraction of d0-d2 (with its sign).
;------------------------------------------------------------------------------
rt_float_frac:
	addi.w	#$200,d1                        ; round at the stored precision
	bcc.s	.frac_round                     ; no carry
	addq.l	#1,d0                           ; carry into the long
	bcc.s	.frac_round                     ; no carry out
	roxr.l	#1,d0                           ; mantissa overflowed: shift it back ...
	roxr.w	#1,d1                           ; (low word)
	addq.w	#1,d2                           ; ... and raise the exponent
.frac_round:
	andi.w	#$fc00,d1                       ; drop the bits below the stored precision
	subi.w	#$200,d2                        ; d2 = integer bits - 1
	bcs.s	.frac_small                     ; below 1: the number is its own fraction
	cmpi.w	#$2f,d2                         ; 47 or more integer bits?
	bcc.s	.frac_zero                      ; yes: no fraction
.frac_shift:
	add.w	d1,d1                           ; shift the integer bits out ...
	addx.l	d0,d0                           ; (the long)
	dbra	d2,.frac_shift                  ; ... one by one
	move.w	#$1ff,d2                        ; what is left is below 1
	jmp	rn_float_normalise(a6)          ; normalise it
.frac_small:
	addi.w	#$200,d2                        ; exponent back
	rts                                     ; return
.frac_zero:
	moveq	#0,d2                           ; the value 0
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $b4 (ODD): d2 = -1 if d0-d2 is odd.
;------------------------------------------------------------------------------
rt_float_odd:
	bsr.s	rt_float_test_units_bit         ; Z clear: odd
	sne	d2                              ; d2 = -1 for odd
	ext.w	d2                              ; (word)
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $b3 (EVEN): d2 = -1 if d0-d2 is even.
;------------------------------------------------------------------------------
rt_float_even:
	bsr.s	rt_float_test_units_bit         ; Z set: even
	seq	d2                              ; d2 = -1 for even
	ext.w	d2                              ; (word)
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime (copied into compiled programs, never run by the compiler). Routine $fc: tests the units bit of d0-d2 (Z clear
; if
; the integer part is odd).
;------------------------------------------------------------------------------
rt_float_test_units_bit:
	addi.w	#$200,d1                        ; round at the stored precision
	bcc.s	.rounded                        ; no carry
	addq.l	#1,d0                           ; carry into the long
	bcc.s	.rounded                        ; no carry out
	roxr.l	#1,d0                           ; mantissa overflowed: shift it back ...
	roxr.w	#1,d1                           ; (low word)
	addq.w	#1,d2                           ; ... and raise the exponent
.rounded:
	move.w	d2,d7                           ; d7 = position of the units bit from the top
	subi.w	#$200,d7                        ; (exponent - $200)
	bcs.s	.no_bit                         ; below 1: even (Z set)
	cmpi.w	#$1f,d7                         ; in the high long?
	bhi.s	.low_word                       ; no: in the low word
	not.w	d7                              ; bit number 31 - position (mod 32)
	btst	d7,d0                           ; test it
	rts                                     ; return
.low_word:
	cmpi.w	#$30,d7                         ; beyond the 48 bits?
	bcc.s	.no_bit                         ; yes: even
	not.w	d7                              ; bit number from the top of the word
	swap	d1                              ; low word in the high half
	btst	d7,d1                           ; test it
	rts                                     ; return
.no_bit:
	moveq	#0,d7                           ; Z set: even
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime (copied into compiled programs, never run by the compiler). Routine $26 (TRUNC): clears the fraction bits of
; d0-d2
; with the masks at rt_trunc_mask_table.
;------------------------------------------------------------------------------
rt_float_trunc:
	addi.w	#$200,d1                        ; round at the stored precision
	bcc.s	.rounded                        ; no carry
	addq.l	#1,d0                           ; carry into the long
	bcc.s	.rounded                        ; no carry out
	roxr.l	#1,d0                           ; mantissa overflowed: shift it back ...
	roxr.w	#1,d1                           ; (low word)
	addq.w	#1,d2                           ; ... and raise the exponent
.rounded:
	move.w	d2,d3                           ; d3 = integer bits - 1
	subi.w	#$200,d3                        ; (exponent - $200)
	bcs.s	rt_trunc_zero                   ; below 1: 0
	cmpi.w	#$2f,d3                         ; 47 or more: no fraction bits
	bpl.s	rt_trunc_done                   ; nothing to clear
	add.w	d3,d3                           ; word index into the mask table
	cmpi.w	#$40,d3                         ; 32 or more integer bits?
	bpl.s	rt_trunc_mask_low_word          ; mask the low word only
	cmpi.w	#$20,d3                         ; 16 or more?
	bpl.s	rt_trunc_mask_low_long          ; clear d1, mask d0's low word
	moveq	#0,d1                           ; fewer than 16: d1 cleared ...
	move.w	d1,d0                           ; ... and d0's low word too
	swap	d0                              ; high word into the low word
	and.w	rt_trunc_mask_table(pc,d3.w),d0 ; keep its integer bits
	swap	d0                              ; back

;------------------------------------------------------------------------------
; Runtime: shared return of TRUNC.
;------------------------------------------------------------------------------
rt_trunc_done:
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime: TRUNC with 17-32 integer bits: low word cleared, the mask on d0's low word.
;------------------------------------------------------------------------------
rt_trunc_mask_low_long:
	moveq	#0,d1                           ; low word cleared
	and.w	rt_int_floor(pc,d3.w),d0        ; (the table, $20 bytes after rt_int_floor)
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime: TRUNC with 33-47 integer bits: the mask on the low word.
;------------------------------------------------------------------------------
rt_trunc_mask_low_word:
	and.w	rt_trunc_done(pc,d3.w),d1       ; (the table, $40 bytes after rt_trunc_done)
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime: TRUNC of a number below 1: the value 0.
;------------------------------------------------------------------------------
rt_trunc_zero:
	moveq	#0,d2                           ; the value 0
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $25 (INT): TRUNC, minus 1 for a negative number with a fraction.
;------------------------------------------------------------------------------
rt_float_int:
	tst.l	d2                              ; routine $25 (INT): TRUNC, minus 1 for a negative with a fraction
	bpl.s	rt_float_trunc                  ; positive: INT = TRUNC
	move.l	d0,d4                           ; keep the number
	move.w	d1,d5                           ; (low word)
	move.l	d2,d6                           ; (exponent and sign)
	bsr.s	rt_float_trunc                  ; TRUNC it

;------------------------------------------------------------------------------
; Runtime: second half of INT: when TRUNC changed the negative number, adds -1.0.
;------------------------------------------------------------------------------
rt_int_floor:
	cmp.l	d0,d4                           ; any fraction cut off?
	bne.s	.floor                          ; yes: one lower
	cmp.w	d1,d5                           ; (low word)
	bne.s	.floor                          ; (low word differs)
	cmp.w	d2,d6                           ; (exponent)
	bne.s	.floor                          ; (exponent differs)
	rts                                     ; whole number: done
.floor:
	move.l	#$80000000,d3                   ; -1.0 ...
	moveq	#0,d4                           ; (low word)
	move.l	#$ffff0200,d5                   ; (sign bit set, exponent $200)
	jmp	rn_float_add(a6)                ; routine 6: add -1.0

; Runtime data: TRUNC masks, words with 1 to 16 top bits set; also reached $20 and $40 bytes
; after rt_int_floor and rt_trunc_done. Decoded as code in the first pass.
rt_trunc_mask_table:
	dc.w	$8000,$c000,$e000,$f000,$f800,$fc00,$fe00,$ff00 ; mask words $0000,$8000..$ffff, decoded as code to
                                                ;   $630f
	dc.w	$ff80,$ffc0,$ffe0,$fff0,$fff8,$fffc,$fffe,$ffff ; mask words $0000,$8000..$ffff, decoded as code to
                                                ;   $630f

; Runtime routine $fe: long d0 to float, stored at (a0) through routine $e1. Kept as data
; (dc.w); the words decode as pea $e1(a6).
rt_long_to_float_store:
	dc.w	$486e,$00e1                     ; pea $e1(a6): return through the store routine, then into $f0

; Runtime routine $f0: long d0 to float d0-d2. Kept as data (dc.w).
rt_long_to_float:
	dc.w	$7200,$2400,$6734,$6a04,$4480,$6b28,$0c80,$0000 ; moveq #0,d1 / move.l d0,d2 / beq zero / bpl / neg.l d0
                                                ;   / bmi (-2^31)
	dc.w	$ffff,$6214,$343c,$020f,$4a40,$6002,$d040,$5bca ; moveq #0,d1 / move.l d0,d2 / beq zero / bpl / neg.l d0
                                                ;   / bmi (-2^31)
	dc.w	$fffc,$4840,$3001,$4e75,$343c,$021e,$d080,$5bca ; (cont.) swap d0 / move.w d1,d0 / rts / move.w #$21e,d2
                                                ;   / add.l d0,d0
	dc.w	$fffc,$4e75,$343c,$021f,$4e75,$08c0,$001f,$4e75 ; (cont.) swap d0 / move.w d1,d0 / rts / move.w #$21e,d2
                                                ;   / add.l d0,d0

; Runtime routine $f1: float d0-d2 to long d0, truncated after rounding at the stored
; precision; error 2 (Number not integer -2147483648 .. 2147483647) when out of range. Kept as
; data (dc.w).
rt_float_to_long:
	dc.w	$0641,$0200,$640a,$5280,$6406,$e290,$e251,$5242 ; addi.w #$200,d1 (round) / bcc / addq.l #1,d0 / bcc /
                                                ;   roxr / roxr / addq
	dc.w	$0442,$0200,$6b12,$0442,$001f,$6a10,$4442,$e4a8 ; addi.w #$200,d1 (round) / bcc / addq.l #1,d0 / bcc /
                                                ;   roxr / roxr / addq
	dc.w	$4a82,$6a02,$4480,$4e75,$7000,$4e75,$6612,$4a82 ; (cont.) tst.l d2 / bpl / neg.l d0 / rts / moveq #0,d0
                                                ;   / rts / bne error
	dc.w	$6a0e,$0c80,$8000,$0000,$6606,$4a41,$6b02,$4e75 ; (cont.) tst.l d2 / bpl / neg.l d0 / rts / moveq #0,d0
                                                ;   / rts / bne error
	dc.w	$7002,$4eee,$0002               ; (cont.) moveq #2,d0 / jmp 2(a6): error 2, number not an integer

; Runtime float compares, result in d2 (-1 true, 0 false). Routine $2d (==): both mantissas
; shifted right 4 bits with rounding and the low words dropped, then the = test. Kept as
; data (dc.w).
rt_float_compare_approx_eq:
	dc.w	$e888,$6402,$5280,$e88b,$6402,$5283,$7200,$7800 ; lsr.l #4 and round both mantissas, clear the low
                                                ;   words, then =

; Runtime routine $13 (=): equality of d0-d2 and d3-d5 in the compare form. Kept as data.
rt_float_compare_eq:
	dc.w	$6110,$b841,$6606,$b680,$6602,$ba42,$57c2,$4882 ; bsr rt_float_to_compare_form / cmp d1,d4 / d0,d3 /
                                                ;   d2,d5 / seq d2
	dc.w	$4e75                           ; bsr rt_float_to_compare_form / cmp d1,d4 / d0,d3 / d2,d5 / seq d2

;------------------------------------------------------------------------------
; Runtime: both operands into a form that compares as integers: negatives get their exponent
; word and mantissa negated, zero becomes all zero bits.
;------------------------------------------------------------------------------
rt_float_to_compare_form:
	tst.l	d2                              ; negatives as two's complement, zero as all zero
	bpl.s	.first_ok                       ; positive: as it is
	neg.w	d2                              ; negative: exponent word negated ...
	neg.w	d1                              ; ... and the mantissa negated
	negx.l	d0                              ; (the long)
.first_ok:
	tst.w	d2                              ; zero?
	bne.s	.second                         ; no
	moveq	#0,d0                           ; zero: all bits zero
	moveq	#0,d1                           ; (low word)
.second:
	tst.l	d5                              ; second operand negative?
	bpl.s	.second_ok                      ; no
	neg.w	d5                              ; negative: exponent word negated ...
	neg.w	d4                              ; ... and the mantissa negated
	negx.l	d3                              ; (the long)
.second_ok:
	tst.w	d5                              ; zero?
	bne.s	.done                           ; no
	moveq	#0,d3                           ; zero: all bits zero
	moveq	#0,d4                           ; (low word)
.done:
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $c (<>): d2 = -1 if d0-d2 and d3-d5 differ.
;------------------------------------------------------------------------------
rt_float_compare_ne:
	bsr.s	rt_float_to_compare_form        ; signed forms
	cmp.w	d2,d5                           ; exponents differ?
	bne.s	.ne_result                      ; yes: not equal
	cmp.l	d0,d3                           ; mantissas differ?
	bne.s	.ne_result                      ; yes: not equal
	cmp.w	d1,d4                           ; low words
.ne_result:
	sne	d2                              ; d2 = -1 if different
	ext.w	d2                              ; (word)
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $11 (>): d2 = -1 if d0-d2 > d3-d5.
;------------------------------------------------------------------------------
rt_float_compare_gt:
	exg	d0,d3                           ; swap the operands: x > y is y < x
	exg	d1,d4                           ; (low words)
	exg	d2,d5                           ; (exponents and signs)

;------------------------------------------------------------------------------
; Runtime routine $12 (<): d2 = -1 if d0-d2 < d3-d5.
;------------------------------------------------------------------------------
rt_float_compare_lt:
	bsr.s	rt_float_to_compare_form        ; signed forms
	cmp.w	d5,d2                           ; exponents differ?
	bne.s	rt_compare_signed_result        ; yes: signed compare decides
	cmp.l	d3,d0                           ; mantissas differ?
	bne.s	rt_compare_unsigned_result      ; yes: unsigned compare decides
	cmp.w	d4,d1                           ; low words

;------------------------------------------------------------------------------
; Runtime: compare result from an unsigned mantissa compare (scs).
;------------------------------------------------------------------------------
rt_compare_unsigned_result:
	scs	d2                              ; d2 = -1 if below (unsigned)
	ext.w	d2                              ; (word)
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime: compare result from a signed exponent compare (slt).
;------------------------------------------------------------------------------
rt_compare_signed_result:
	slt	d2                              ; d2 = -1 if less (signed exponent)
	ext.w	d2                              ; (word)
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $d (>=): d2 = -1 if d0-d2 >= d3-d5.
;------------------------------------------------------------------------------
rt_float_compare_ge:
	exg	d0,d3                           ; swap the operands: x >= y is y <= x
	exg	d1,d4                           ; (low words)
	exg	d2,d5                           ; (exponents and signs)

;------------------------------------------------------------------------------
; Runtime routine $f (<=): d2 = -1 if d0-d2 <= d3-d5.
;------------------------------------------------------------------------------
rt_float_compare_le:
	bsr.s	rt_float_to_compare_form        ; signed forms
	cmp.w	d5,d2                           ; exponents differ?
	bne.s	rt_compare_signed_result        ; yes: signed compare decides
	cmp.l	d3,d0                           ; mantissas differ?
	bne.s	rt_compare_unsigned_result      ; yes: unsigned compare decides
	cmp.w	d4,d1                           ; low words
	bne.s	rt_compare_unsigned_result      ; differ: unsigned compare decides
	moveq	#-1,d2                          ; equal: TRUE
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $f9: unsigned byte d0 to float d0-d2.
;------------------------------------------------------------------------------
rt_byte_to_float:
	moveq	#0,d1                           ; low mantissa word 0
	move.l	#$207,d2                        ; exponent for an 8-bit integer
	asl.w	#8,d0                           ; byte into the top of the word
	bne.s	rt_word_to_float_normalise      ; nonzero: normalise
	moveq	#0,d2                           ; zero
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $fb: signed word d0 to float d0-d2.
;------------------------------------------------------------------------------
rt_word_to_float:
	ext.l	d0                              ; sign-extend
	bpl.s	rt_uword_to_float               ; positive: as unsigned
	jmp	rn_long_to_float(a6)            ; negative: the long conversion

;------------------------------------------------------------------------------
; Runtime routine $fa: unsigned word d0 to float d0-d2.
;------------------------------------------------------------------------------
rt_uword_to_float:
	moveq	#0,d1                           ; low mantissa word 0
	move.l	#$20f,d2                        ; exponent for a 16-bit integer
	tst.w	d0                              ; zero?
	bne.s	rt_word_to_float_normalise      ; no: normalise
	moveq	#0,d2                           ; zero
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime: one left shift of the normalise loop below.
;------------------------------------------------------------------------------
rt_word_to_float_shift:
	add.w	d0,d0                           ; shift left ...

;------------------------------------------------------------------------------
; Runtime: normalises the word in d0 into d0-d2 (d2 = exponent for its top bit, d1 = 0).
;------------------------------------------------------------------------------
rt_word_to_float_normalise:
	dbmi	d2,rt_word_to_float_shift       ; ... until the top bit is set, the exponent one lower each time
	swap	d0                              ; word into the top of the mantissa
	move.w	d1,d0                           ; (low word from d1 = 0)
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime routine $a: MOD with the operands swapped (d3-d5 MOD d0-d2).
;------------------------------------------------------------------------------
rt_float_reverse_mod:
	exg	d0,d3                           ; swap the operands
	exg	d1,d4                           ; (low words)
	exg	d2,d5                           ; (exponents and signs)

;------------------------------------------------------------------------------
; Runtime routine $11c (MOD): d0-d2 MOD d3-d5 = x - TRUNC(x/y)*y.
;------------------------------------------------------------------------------
rt_float_mod:
	movem.l	d0-d2,-(sp)                     ; keep x
	movem.l	d3-d5,-(sp)                     ; keep y
	jsr	rn_float_div(a6)                ; x / y
	jsr	rn_float_trunc(a6)              ; TRUNC
	movem.l	(sp)+,d3-d5                     ; y back
	jsr	rn_float_mul(a6)                ; * y
	movem.l	(sp)+,d3-d5                     ; x back
	jmp	rn_float_reverse_sub(a6)        ; x - that

;------------------------------------------------------------------------------
; Runtime routine $11d (DIV): TRUNC(d0-d2 / d3-d5).
;------------------------------------------------------------------------------
rt_float_div_trunc:
	jsr	rn_float_div(a6)                ; d0-d2 / d3-d5
	jmp	rn_float_trunc(a6)              ; TRUNC it

;------------------------------------------------------------------------------
; Runtime routine $b: TRUNC(d3-d5 / d0-d2).
;------------------------------------------------------------------------------
rt_float_reverse_div_trunc:
	jsr	rn_float_reverse_div(a6)        ; d3-d5 / d0-d2
	jmp	rn_float_trunc(a6)              ; TRUNC it

;------------------------------------------------------------------------------
; Runtime: EXP with |x / ln 2| of 512 or more: 0 for a negative x, else error 1 (Overflow).
;------------------------------------------------------------------------------
rt_exp_out_of_range:
	tst.l	d2                              ; EXP of a large negative number is 0
	bpl.s	.exp_overflow                   ; positive: overflow
	moveq	#0,d2                           ; the value 0
	rts                                     ; return
.exp_overflow:
	moveq	#1,d0                           ; error 1: Overflow
	jmp	rn_error_entry(a6)              ; runtime error

;------------------------------------------------------------------------------
; Runtime routine $2f (EXP): x / ln 2 split into an integer part n and a fraction f; 2^f by
; the rational form 1 + 2f / (9.9546 - f + 0.0347 f^2 - 617.97 / (f^2 + 87.417)), then n
; added to the exponent.
;------------------------------------------------------------------------------
rt_float_exp:
	move.l	#$b17217f7,d3                   ; ln 2
	move.w	#$d1df,d4                       ; (low word)
	move.l	#$1ff,d5                        ; (exponent)
	jsr	rn_float_div(a6)                ; x / ln 2

rt_float_exp_range_check:
	cmpi.w	#$20a,d2                        ; |x / ln 2| 512 or more?
	bcc.s	rt_exp_out_of_range             ; yes: 0 or overflow
	moveq	#0,d4                           ; d4 = integer part

;------------------------------------------------------------------------------
; Runtime: second part of EXP: splits d0-d2 into the integer part d4 (signed) and the
; fraction, then the 2^f approximation.
;------------------------------------------------------------------------------
rt_exp_split:
	move.w	d2,d3                           ; d3 = integer bits - 1
	subi.w	#$200,d3                        ; (exponent - $200)
	bmi.s	.exp_poly                       ; below 1: no integer part
.exp_int_part:
	add.w	d1,d1                           ; shift the integer bits ...
	addx.l	d0,d0                           ; (the long)
	addx.w	d4,d4                           ; ... into d4
	dbra	d3,.exp_int_part                ; each
	tst.l	d2                              ; negative?
	bpl.s	.exp_frac                       ; no
	neg.w	d4                              ; negative integer part
.exp_frac:
	move.w	#$1ff,d2                        ; the fraction left below 1
	tst.l	d0                              ; normalised?
	bmi.s	.exp_poly                       ; yes
	bne.s	.exp_normalise                  ; the high long is not zero: normalise
	move.w	d1,d0                           ; low word up
	bne.s	.exp_word                       ; nonzero
	moveq	#0,d2                           ; fraction 0
	bra.s	.exp_poly                       ; to the polynomial
.exp_word:
	swap	d0                              ; (into the high word)
	moveq	#0,d1                           ; low word empty
	subi.w	#$20,d2                         ; 32 bits less
	tst.w	d0                              ; normalised?
	bmi.s	.exp_poly                       ; yes
.exp_normalise:
	add.w	d1,d1                           ; shift left ...
	addx.l	d0,d0                           ; (the long)
	dbmi	d2,.exp_normalise               ; ... until the top bit is set
	subq.w	#1,d2                           ; (the last shift)
.exp_poly:
	move.w	d4,-(sp)                        ; keep the integer part
	movem.l	d0-d2,-(sp)                     ; keep f, the fraction
	move.l	#$9f46063a,d3                   ; 9.9545957821 ...
	move.w	#$104e,d4                       ; (low word)
	move.l	#$203,d5                        ; (exponent)
	jsr	rn_float_reverse_sub(a6)        ; A = 9.9546 - f
	movem.l	(sp),d3-d5                      ; f
	movem.l	d0-d2,-(sp)                     ; keep A
	move.l	d3,d0                           ; f ...
	move.w	d4,d1                           ; (low word)
	move.l	d5,d2                           ; (exponent)
	jsr	rn_float_mul(a6)                ; ... squared
	movem.l	d0-d2,-(sp)                     ; keep f^2
	move.l	#$aed5c231,d3                   ; 87.417497202 ...
	move.w	#$7986,d4                       ; (low word)
	move.l	#$206,d5                        ; (exponent)
	jsr	rn_float_add(a6)                ; f^2 + 87.4175
	move.l	#$9a7e39a9,d3                   ; 617.97226953 ...
	move.w	#$fa90,d4                       ; (low word)
	move.l	#$209,d5                        ; (exponent)
	jsr	rn_float_reverse_div(a6)        ; Q = 617.972 / (f^2 + 87.4175)
	movem.l	(sp)+,d3-d5                     ; f^2
	movem.l	d0-d2,-(sp)                     ; keep Q
	move.l	#$8df4dff9,d0                   ; 0.034657359 (ln 2 / 20) ...
	move.w	#$74b2,d1                       ; (low word)
	move.l	#$1fb,d2                        ; (exponent)
	jsr	rn_float_mul(a6)                ; * f^2
	movem.l	(sp)+,d3-d5                     ; Q
	jsr	rn_float_sub(a6)                ; 0.0347 f^2 - Q
	movem.l	(sp)+,d3-d5                     ; A
	jsr	rn_float_add(a6)                ; + A
	movem.l	(sp)+,d3-d5                     ; f
	addq.w	#1,d5                           ; 2f
	jsr	rn_float_reverse_div(a6)        ; 2f / (A + 0.0347 f^2 - Q)
	move.l	#$80000000,d3                   ; 1.0 ...
	moveq	#0,d4                           ; (low word)
	move.l	#$200,d5                        ; (exponent)
	jsr	rn_float_add(a6)                ; + 1: 2^f
	add.w	(sp)+,d2                        ; add the integer part to the exponent
	jmp	rn_float_check_range(a6)        ; range check (0 or overflow)

;------------------------------------------------------------------------------
; Runtime routine $2a (COS): SIN with the quadrant count started at 1 (3 for a negative x).
;------------------------------------------------------------------------------
rt_float_cos:
	moveq	#1,d3                           ; COS: quadrant offset 1 ...
	tst.l	d2                              ; negative x?
	bpl.s	rt_sin_quadrant                 ; no
	moveq	#3,d3                           ; ... or 3 for a negative x
	bra.s	rt_sin_quadrant                 ; common part

;------------------------------------------------------------------------------
; Runtime routine $29 (SIN): quadrant count 4.
;------------------------------------------------------------------------------
rt_float_sin:
	moveq	#4,d3                           ; SIN: quadrant offset 4 (0 mod 4)

;------------------------------------------------------------------------------
; Runtime: common part of SIN and COS. x / (pi/2) gives the quadrant (added to the count on
; the stack) and a fraction t; odd quadrants use 1 - t, quadrant bit 1 negates. sin(t * pi/2)
; by an odd polynomial in t (6 terms), clamped to 1.
;------------------------------------------------------------------------------
rt_sin_quadrant:
	move.w	d3,-(sp)                        ; keep the quadrant count
	move.l	#$c90fdaa2,d3                   ; pi/2
	move.w	#$21db,d4                       ; (low word)
	move.l	#$200,d5                        ; (exponent)
	jsr	rn_float_div(a6)                ; x / (pi/2)
	moveq	#0,d3                           ; d3 = integer part (quadrants)
	cmpi.w	#$200,d2                        ; below 1?
	bcs.s	.trig_reflect                   ; yes: no whole quadrants
	subi.w	#$200,d2                        ; integer bits - 1
.trig_int_part:
	add.w	d1,d1                           ; shift the integer bits ...
	addx.l	d0,d0                           ; (the long)
	addx.w	d3,d3                           ; ... into d3
	dbra	d2,.trig_int_part               ; each
	addi.w	#$200,d2                        ; exponent of the fraction below 1
	add.w	d3,(sp)                         ; quadrants added to the count
	tst.l	d0                              ; normalised?
	bmi.s	.trig_reflect                   ; yes
	bne.s	.trig_normalise                 ; the high long is not zero: normalise
	move.w	d1,d0                           ; low word up
	bne.s	.trig_word                      ; nonzero
	moveq	#1,d0                           ; fraction 0: a tiny value instead
.trig_word:
	swap	d0                              ; (into the high word)
	moveq	#0,d1                           ; low word empty
	subi.w	#$20,d2                         ; 32 bits less
	tst.l	d0                              ; normalised?
	bmi.s	.trig_reflect                   ; yes
.trig_normalise:
	add.w	d1,d1                           ; shift left ...
	addx.l	d0,d0                           ; (the long)
	dbmi	d2,.trig_normalise              ; ... until the top bit is set
	subq.w	#1,d2                           ; (the last shift)
.trig_reflect:
	lsr.w	(sp)                            ; odd quadrant?
	bcc.s	.trig_poly                      ; no: the fraction as it is
	move.l	#$80000000,d3                   ; 1.0 ...
	moveq	#0,d4                           ; (low word)
	move.l	d2,d5                           ; ... with the sign of x
	move.w	#$200,d5                        ; (exponent $200)
	bchg	#$1f,d2                         ; - x
	jsr	rn_float_add(a6)                ; 1 - fraction
.trig_poly:
	movem.l	d0-d2,-(sp)                     ; keep t
	jsr	rn_float_square(a6)             ; t^2
	movem.l	d0-d2,-(sp)                     ; keep t^2
	move.l	#$e56473ee,d3                   ; -3.418213e-6 ...
	move.w	#$2da8,d4                       ; (low word)
	move.l	#$ffff01ed,d5                   ; (exponent, negative)
	jsr	rn_float_mul(a6)                ; * t^2
	move.l	#$a7fffd54,d3                   ; + 0.000160217 ...
	move.w	#$978a,d4                       ; (low word)
	move.l	#$1f3,d5                        ; (exponent)
	jsr	rn_float_add(a6)                ; add
	movem.l	(sp),d3-d5                      ; t^2
	jsr	rn_float_mul(a6)                ; * t^2
	move.l	#$99684726,d3                   ; - 0.00468162 ...
	move.w	#$40b3,d4                       ; (low word)
	move.l	#$ffff01f8,d5                   ; (exponent, negative)
	jsr	rn_float_add(a6)                ; add
	movem.l	(sp),d3-d5                      ; t^2
	jsr	rn_float_mul(a6)                ; * t^2
	move.l	#$a335de02,d3                   ; + 0.0796926 ...
	move.w	#$b34c,d4                       ; (low word)
	move.l	#$1fc,d5                        ; (exponent)
	jsr	rn_float_add(a6)                ; add
	movem.l	(sp),d3-d5                      ; t^2
	jsr	rn_float_mul(a6)                ; * t^2
	move.l	#$a55de71c,d3                   ; - 0.645964 ...
	move.w	#$556a,d4                       ; (low word)
	move.l	#$ffff01ff,d5                   ; (exponent, negative)
	jsr	rn_float_add(a6)                ; add
	movem.l	(sp)+,d3-d5                     ; t^2
	jsr	rn_float_mul(a6)                ; * t^2
	move.l	#$c90fdaa2,d3                   ; + pi/2 ...
	move.w	#$21db,d4                       ; (low word)
	move.l	#$200,d5                        ; (exponent)
	jsr	rn_float_add(a6)                ; add
	movem.l	(sp)+,d3-d5                     ; t
	jsr	rn_float_mul(a6)                ; * t: sin(t * pi/2)
	cmpi.w	#$200,d2                        ; 1 or more?
	bne.s	.trig_sign                      ; no
	move.l	#$80000000,d0                   ; clamp to 1.0
	moveq	#0,d1                           ; (low word)
.trig_sign:
	lsr.w	(sp)+                           ; quadrant bit 1: lower half of the circle
	bcc.s	.trig_done                      ; no: positive
	bchg	#$1f,d2                         ; negate
.trig_done:
	rts                                     ; return

;------------------------------------------------------------------------------
; Runtime: error 6, Logarithm only for numbers greater than zero.
;------------------------------------------------------------------------------
rt_log_error:
	moveq	#6,d0                           ; error 6: Logarithm only for numbers greater than zero
	jmp	rn_error_entry(a6)              ; runtime error

;------------------------------------------------------------------------------
; Runtime routine $30 (LOG): natural logarithm. With m the mantissa in 0.5..1 and e the
; exponent: z = (m - sqrt2/2)/(m + sqrt2/2), ln(m*sqrt2) = z (0.1076 z^2 + 1.2187 + 1.0919 /
; (1.3976 - z^2)), plus (2(e - $1ff) - 1) * ln 2 / 2.
;------------------------------------------------------------------------------
rt_float_log:
	tst.l	d2                              ; negative?
	bmi.s	rt_log_error                    ; error 6
	tst.w	d2                              ; zero?
	beq.s	rt_log_error                    ; error 6
	move.w	d2,-(sp)                        ; keep the exponent
	move.w	#$1ff,d2                        ; m = mantissa in 0.5..1
	move.l	#$b504f333,d3                   ; sqrt(2)/2
	move.w	#$fdaa,d4                       ; (low word)
	move.l	#$1ff,d5                        ; (exponent: 0.7071)
	jsr	rn_float_add(a6)                ; m + sqrt(2)/2
	movem.l	d0-d2,-(sp)                     ; keep it
	move.l	#$b504f333,d3                   ; sqrt(2) ...
	move.w	#$fdaa,d4                       ; (low word)
	move.l	#$200,d5                        ; (exponent)
	jsr	rn_float_sub(a6)                ; m + 0.7071 - 1.4142 = m - 0.7071
	movem.l	(sp)+,d3-d5                     ; m + 0.7071
	jsr	rn_float_div(a6)                ; z = (m - 0.7071) / (m + 0.7071)
	movem.l	d0-d2,-(sp)                     ; keep z
	jsr	rn_float_square(a6)             ; z^2
	movem.l	d0-d2,-(sp)                     ; keep z^2
	move.l	#$dc73cc06,d3                   ; 0.10764274 ...
	move.w	#$249c,d4                       ; (low word)
	move.l	#$1fc,d5                        ; (exponent)
	jsr	rn_float_mul(a6)                ; * z^2
	move.l	#$9bff5d76,d3                   ; + 1.21873062 ...
	move.w	#$9253,d4                       ; (low word)
	move.l	#$200,d5                        ; (exponent)
	jsr	rn_float_add(a6)                ; add
	movem.l	(sp)+,d3-d5                     ; z^2
	movem.l	d0-d2,-(sp)                     ; keep that
	move.l	#$b2e33d74,d0                   ; 1.39755982 ...
	move.w	#$6432,d1                       ; (low word)
	move.l	#$200,d2                        ; (exponent)
	jsr	rn_float_sub(a6)                ; - z^2
	move.l	#$8bc26b2a,d3                   ; 1.09187069 ...
	move.w	#$a087,d4                       ; (low word)
	move.l	#$200,d5                        ; (exponent)
	jsr	rn_float_reverse_div(a6)        ; 1.0919 / (1.3976 - z^2)
	movem.l	(sp)+,d3-d5                     ; the first part
	jsr	rn_float_add(a6)                ; add
	movem.l	(sp)+,d3-d5                     ; z
	jsr	rn_float_mul(a6)                ; * z: ln(m * sqrt 2)
	move.w	(sp)+,d3                        ; the exponent
	movem.l	d0-d2,-(sp)                     ; keep the result so far
	moveq	#0,d0                           ; (zero-extended)
	move.w	d3,d0                           ; d0 = exponent ...
	subi.l	#$1ff,d0                        ; ... - $1ff
	add.l	d0,d0                           ; * 2
	subq.l	#1,d0                           ; - 1
	jsr	rn_long_to_float(a6)            ; to a float
	move.l	#$b17217f7,d3                   ; ln 2 / 2
	move.w	#$d1df,d4                       ; (low word)
	move.l	#$1fe,d5                        ; (exponent)
	jsr	rn_float_mul(a6)                ; (2(e - $1ff) - 1) * ln 2 / 2
	movem.l	(sp)+,d3-d5                     ; ln(m * sqrt 2)
	jmp	rn_float_add(a6)                ; + that = LOG(x)

;------------------------------------------------------------------------------
; Runtime (copied into compiled programs, never run by the compiler). Routine $31 (LOG10): LOG(x) * 1/ln 10.
;------------------------------------------------------------------------------
rt_log10:
	jsr	rn_float_log(a6)                ; LOG(x) (routine $30)
	move.l	#$de5bd8a9,d3                   ; d3-d5 = 0.4343 = 1/ln 10
	move.w	#$39f7,d4
	move.l	#$1fe,d5
	jmp	rn_float_mul(a6)                ; float multiply: LOG(x) / ln 10

;------------------------------------------------------------------------------
; Runtime: SQR(0) returns 0 unchanged. 67ee raises error 5 for a negative argument.
;------------------------------------------------------------------------------
rt_sqr_of_zero:
	rts                                     ; SQR(0) = 0

rt_sqr_negative_error:
	moveq	#5,d0                           ; error 5: Square root only for positive numbers
	jmp	rn_error_entry(a6)              ; raise error 5

;------------------------------------------------------------------------------
; Runtime (copied into compiled programs, never run by the compiler). Routine $4e (SQR): halves the exponent, then three
; Newton
; steps from (m+1)/2.
;------------------------------------------------------------------------------
rt_sqr:
	tst.l	d2                              ; d2 bit 31 = sign of the argument
	bmi.s	rt_sqr_negative_error           ; negative: error 5
	tst.w	d2                              ; exponent 0: the argument is 0
	beq.s	rt_sqr_of_zero                  ; SQR(0) = 0
	move.w	d2,d4                           ; d4 = biased exponent
	move.w	#$200,d2                        ; reduced argument: mantissa with exponent $200, in [1,2)
	sub.w	d2,d4                           ; d4 = unbiased exponent
	asr.w	#1,d4                           ; halved: the result's exponent
	bcc.s	.sqr_iterate                    ; even exponent: the mantissa stays in [1,2)
	addq.w	#1,d4                           ; odd: round the halved exponent up ...
	subq.w	#1,d2                           ; ... and take the mantissa into [0.5,1)
.sqr_iterate:
	move.w	d4,-(sp)                        ; keep the result exponent
	movem.l	d0-d2,-(sp)                     ; push the reduced argument a
	move.l	#$80000000,d3                   ; d3-d5 = 1.0
	moveq	#0,d4
	move.l	#$200,d5
	jsr	rn_float_add(a6)                ; float add: a + 1
	subq.w	#1,d2                           ; / 2: first estimate (a + 1) / 2
	movem.l	(sp),d3-d5                      ; d3-d5 = a
	movem.l	d0-d2,-(sp)                     ; push the estimate x
	jsr	rn_float_reverse_div(a6)        ; float divide (d3-d5 / d0-d2): a / x
	movem.l	(sp)+,d3-d5                     ; d3-d5 = x
	jsr	rn_float_add(a6)                ; x + a / x
	subq.w	#1,d2                           ; / 2: second estimate
	movem.l	(sp),d3-d5                      ; d3-d5 = a
	movem.l	d0-d2,-(sp)                     ; push the estimate x
	jsr	rn_float_reverse_div(a6)        ; a / x
	movem.l	(sp)+,d3-d5                     ; d3-d5 = x
	jsr	rn_float_add(a6)                ; x + a / x
	subq.w	#1,d2                           ; / 2: third estimate
	movem.l	(sp),d3-d5                      ; d3-d5 = a
	movem.l	d0-d2,-(sp)                     ; push the estimate x
	jsr	rn_float_reverse_div(a6)        ; a / x
	movem.l	(sp)+,d3-d5                     ; d3-d5 = x
	jsr	rn_float_add(a6)                ; x + a / x
	subq.w	#1,d2                           ; / 2: fourth and last estimate
	subi.w	#$18,d1                         ; trims $18 off the low mantissa word (rounding correction)
	bcc.s	.sqr_done
	subq.l	#1,d0                           ; borrow into the high mantissa long
.sqr_done:
	lea	$c(sp),sp                       ; drop the pushed argument
	add.w	(sp)+,d2                        ; exponent + the halved exponent of the argument
	rts

;------------------------------------------------------------------------------
; Runtime (copied into compiled programs, never run by the compiler). Routine $2b (TAN): SIN(x) / COS(x).
;------------------------------------------------------------------------------
rt_tan:
	movem.l	d0-d2,-(sp)                     ; keep x
	jsr	rn_float_cos(a6)                ; COS(x) (routine $2a)
	move.l	d0,d3                           ; d3-d5 = COS(x)
	move.w	d1,d4
	move.l	d2,d5
	movem.l	(sp)+,d0-d2                     ; d0-d2 = x again
	movem.l	d3-d5,-(sp)                     ; keep COS(x)
	jsr	rn_float_sin(a6)                ; SIN(x) (routine $29)
	movem.l	(sp)+,d3-d5                     ; d3-d5 = COS(x)
	jmp	rn_float_div(a6)                ; float divide (d0-d2 / d3-d5): SIN / COS

;------------------------------------------------------------------------------
; Runtime (copied into compiled programs, never run by the compiler). Routine $2c (ATN): reduces |x| > 1 to 1/x and
; large
; arguments by tan(pi/12), then a rational polynomial; adds pi/6 or pi/2 back.
;------------------------------------------------------------------------------
rt_atn:
	move.l	d2,-(sp)                        ; keep x: its sign (bit 31) and exponent (low word)
	ext.l	d2                              ; exponent word extended: the sign bit gone, |x|
	cmpi.w	#$200,d2                        ; |x| >= 1?
	bcs.s	.atn_reduce                     ; below 1: no reciprocal
	move.l	#$80000000,d3                   ; d3-d5 = 1.0
	moveq	#0,d4
	move.l	#$200,d5
	jsr	rn_float_reverse_div(a6)        ; float divide: 1 / |x|
.atn_reduce:
	moveq	#0,d7                           ; d7 = 0: no pi/6 to add
	cmpi.w	#$1fe,d2                        ; exponent below $1fe (under 0.25): straight to the polynomial
	bcs.s	.atn_poly
	bne.s	.atn_large                      ; 0.5 and over: reduce
	cmpi.l	#$8930be0d,d0                   ; mantissa below 2 - SQR(3) = TAN(pi/12)?
	bcs.s	.atn_poly                       ; yes: straight to the polynomial
.atn_large:
	move.l	#$ddb3d742,d3                   ; d3-d5 = SQR(3) = 1.732
	move.w	#$c303,d4
	move.l	#$200,d5
	jsr	rn_float_add(a6)                ; float add: t + SQR(3)
	move.l	#$80000000,d3                   ; d3-d5 = 4.0
	moveq	#0,d4
	move.l	#$202,d5
	jsr	rn_float_reverse_div(a6)        ; float divide: 4 / (t + SQR(3))
	move.l	#$ddb3d742,d3                   ; d3-d5 = SQR(3)
	move.w	#$c303,d4
	move.l	#$200,d5
	jsr	rn_float_reverse_sub(a6)        ; SQR(3) - 4/(t + SQR(3)) = TAN(ATN(t) - pi/6)
	moveq	#-1,d7                          ; d7 = -1: pi/6 to add back
.atn_poly:
	move.w	d7,-(sp)                        ; keep the pi/6 flag
	movem.l	d0-d2,-(sp)                     ; push t
	jsr	rn_float_square(a6)             ; float square: t^2
	movem.l	d0-d2,-(sp)                     ; push t^2
	move.l	#$b1c556a9,d3                   ; d3-d5 = 1.389 (rational polynomial constant)
	move.w	#$ac78,d4
	move.l	#$200,d5
	jsr	rn_float_add(a6)                ; t^2 + 1.389
	move.l	#$f8304c74,d3                   ; d3-d5 = 0.2424
	move.w	#$2ffc,d4
	move.l	#$1fd,d5
	jsr	rn_float_reverse_div(a6)        ; 0.2424 / (t^2 + 1.389)
	move.l	#$8d83bb11,d3                   ; d3-d5 = 2.211
	move.w	#$902b,d4
	move.l	#$201,d5
	jsr	rn_float_reverse_sub(a6)        ; 2.211 - the quotient
	movem.l	(sp),d3-d5                      ; d3-d5 = t^2
	jsr	rn_float_add(a6)                ; + t^2
	move.l	#$95024eee,d3                   ; d3-d5 = 1.164
	move.w	#$a068,d4
	move.l	#$200,d5
	jsr	rn_float_reverse_div(a6)        ; 1.164 / the sum
	move.l	#$db585095,d3                   ; d3-d5 = 0.4284
	move.w	#$2b0c,d4
	move.l	#$1fe,d5
	jsr	rn_float_add(a6)                ; + 0.4284
	movem.l	(sp)+,d3-d5                     ; d3-d5 = t^2
	movem.l	d0-d2,-(sp)                     ; push the sum
	move.l	#$8ea9d4ab,d0                   ; d0-d2 = 0.01741
	move.w	#$ddc7,d1
	move.l	#$1fa,d2
	jsr	rn_float_mul(a6)                ; float multiply: 0.01741 * t^2
	movem.l	(sp)+,d3-d5                     ; d3-d5 = the sum
	jsr	rn_float_reverse_sub(a6)        ; float subtract: sum - 0.01741 * t^2
	movem.l	(sp)+,d3-d5                     ; d3-d5 = t
	jsr	rn_float_mul(a6)                ; * t: ATN(t)
	tst.w	(sp)+                           ; pi/6 flag set?
	bpl.s	.atn_quadrant
	move.l	#$860a91c1,d3                   ; d3-d5 = pi/6
	move.w	#$3c1b,d4
	move.l	#$1ff,d5
	jsr	rn_float_add(a6)                ; + pi/6
.atn_quadrant:
	cmpi.w	#$200,2(sp)                     ; saved exponent: |x| was >= 1?
	bcs.s	.atn_sign                       ; no: keep the result
	move.l	#$c90fdaa2,d3                   ; d3-d5 = pi/2
	move.w	#$21db,d4
	move.l	#$200,d5
	jsr	rn_float_reverse_sub(a6)        ; pi/2 - result (ATN(x) = pi/2 - ATN(1/x))
.atn_sign:
	tst.l	(sp)+                           ; saved d2: x negative?
	bpl.s	.atn_done
	bchg	#$1f,d2                         ; negate the result
.atn_done:
	rts

rt_power_one:
	moveq	#1,d0                           ; d0-d2 = 1.0 (x^0)
	ror.l	#1,d0
	moveq	#0,d1
	move.l	#$200,d2
	rts

;------------------------------------------------------------------------------
; Runtime: ^ with a zero base. d2 = the exponent's sign and exponent word: a negative
; exponent raises error 0 (division by zero), otherwise the result is 0.
;------------------------------------------------------------------------------
rt_power_zero_base:
	tst.l	d2                              ; 0^negative: error 0, else 0
	bmi.s	.error
	moveq	#0,d2                           ; result 0
	rts
	rts                                     ; unreachable second rts
.error:
	moveq	#0,d0                           ; error 0: division by zero
	jmp	rn_error_entry(a6)              ; raise error d0

;------------------------------------------------------------------------------
; Runtime (copied into compiled programs, never run by the compiler). Routine $de: power with the operands swapped.
; Routine 9
; at $6a24: d0-d2 = d3-d5 ^ d0-d2. Integer exponents 1..256 by repeated
; squaring, otherwise EXP(LOG(base)*exponent); a negative base needs an
; integer exponent (error 6 otherwise). Base saved at dat_06b2c.
;------------------------------------------------------------------------------
rt_power_swapped:
	exg	d0,d3                           ; the operands arrive the other way round: swap ...
	exg	d1,d4                           ; ... all three ...
	exg	d2,d5                           ; ... registers, then fall into ^

rt_power:
	tst.w	d2                              ; exponent (d0-d2) zero?
	beq.s	rt_power_one                    ; x^0 = 1
	tst.w	d5                              ; base (d3-d5) zero?
	beq.s	rt_power_zero_base              ; 0^y
	lea	dat_power_base_save(pc),a0      ; save the base
	movem.l	d3-d5,(a0)
	tst.w	d1                              ; exponent a small whole number?
	bne.s	.general                        ; low mantissa word set: not a small whole number
	tst.w	d0                              ; low word of the high mantissa long set: not either
	bne.s	.general                        ; general case
	cmpi.w	#$200,d2                        ; below 1.0: general case
	bcs.s	.general
	cmpi.w	#$208,d2                        ; 512 or over: general case
	bhi.s	.general
	movem.l	d0-d2,-(sp)                     ; keep the exponent
	jsr	rn_float_frac(a6)               ; FRAC: a fraction left?
	tst.w	d2
	bne.s	.use_log
	movem.l	(sp)+,d0-d2                     ; d0-d2 = exponent again
	swap	d0                              ; d0.w = top 16 mantissa bits
	subi.w	#$20f,d2                        ; shift count $20f - exponent ...
	neg.w	d2                              ; ...
	lsr.w	d2,d0                           ; d0.w = the exponent as an integer n
	move.l	d2,-(sp)                        ; keep the sign word (d2 bit 31) for the reciprocal
	move.w	d0,-(sp)                        ; n on the stack: its bits are used up by the squaring
	subq.w	#2,d0                           ; n = 2?
	beq.s	.power_of_two                   ; yes: one square
	lsr.w	(sp)                            ; n / 2, the low bit out
	beq.s	.power_of_one                   ; n = 1: the base itself
	bcs.s	.odd_power                      ; odd: start from the base
	bsr.s	rt_power_one                    ; even: start from 1.0
	bra.s	.square_loop
.odd_power:
	movem.l	(a0),d0-d2                      ; partial result = base
.square_loop:
	movem.l	d0-d2,-(sp)                     ; push the partial result
	movem.l	(a0),d0-d2                      ; d0-d2 = current power of the base
.square:
	jsr	rn_float_square(a6)             ; float square
	lsr.w	$c(sp)                          ; next bit of n
	bcc.s	.square                         ; bit clear: square again
	beq.s	.power_done                     ; no bits left: last multiply
	movem.l	d0-d2,(a0)                      ; keep the current power of the base
	movem.l	(sp)+,d3-d5                     ; d3-d5 = partial result
	jsr	rn_float_mul(a6)                ; partial * power
	bra.s	.square_loop                    ; next bit
.power_done:
	movem.l	(sp)+,d3-d5                     ; d3-d5 = partial result
	jsr	rn_float_mul(a6)                ; partial * power
	addq.l	#2,sp                           ; drop n
	tst.l	(sp)+                           ; exponent negative?
	bmi.s	.reciprocal                     ; yes: 1 / result
	rts
.general:
	movem.l	d0-d2,-(sp)                     ; push the exponent
.use_log:
	movem.l	(a0),d0-d2                      ; d0-d2 = base
	tst.l	d2                              ; negative base: needs a whole exponent
	bmi.s	.negative_base
	jsr	rn_float_log(a6)                ; LOG(base)
	movem.l	(sp)+,d3-d5
	jsr	rn_float_mul(a6)                ; * exponent
	jmp	rn_float_exp(a6)                ; EXP
.power_of_one:
	movem.l	(a0),d0-d2                      ; result = base (x^1)
	bra.s	.check_negative
.power_of_two:
	movem.l	(a0),d0-d2                      ; d0-d2 = base
	jsr	rn_float_square(a6)             ; float square (x^2)
.check_negative:
	addq.l	#2,sp                           ; drop n
	tst.l	(sp)+                           ; exponent negative?
	bpl.s	.done                           ; no: done
.reciprocal:
	move.l	#$80000000,d3                   ; negative exponent: 1 / result (routine 8)
	moveq	#0,d4
	move.l	#$200,d5
	jmp	rn_float_reverse_div(a6)
.negative_base:
	movem.l	(sp),d0-d2                      ; d0-d2 = exponent
	jsr	rn_float_frac(a6)               ; FRAC(exponent)
	tst.w	d2                              ; a fraction left: error 6
	bne.s	.error_negative
	movem.l	(sp),d0-d2                      ; exponent again
	jsr	rn_float_test_units_bit(a6)     ; routine $fc: odd exponent? (flag byte before dat_06b2c)
	sne	-$1(a0)                         ; odd exponent: flag byte at 6b13 set
	movem.l	(a0),d0-d2                      ; d0-d2 = base
	ext.l	d2                              ; exponent word extended: sign gone, |base|
	jsr	rn_float_log(a6)                ; LOG(|base|)
	movem.l	(sp)+,d3-d5                     ; d3-d5 = exponent
	jsr	rn_float_mul(a6)                ; * exponent
	jsr	rn_float_exp(a6)                ; EXP
	tst.b	-(a0)                           ; odd exponent flag set?
	bpl.s	.done                           ; even: the result stays positive
	bchg	#$1f,d2                         ; odd: negative result
.done:
	rts
.error_negative:
	moveq	#6,d0                           ; error 6: no fractional power of a negative number
	jmp	rn_error_entry(a6)              ; raise error d0
	dc.w	$0000                           ; zero word; its low byte is the odd-exponent flag

; Data: 12 bytes where the ^ (power) routine above keeps the base (d3-d5) while it works; the
; word before it (6b12) is its sign flag. Not code.
dat_power_base_save:
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000 ; zero bytes: save area, not code

;------------------------------------------------------------------------------
; Runtime: float * 2 (routine $147). d0-d2 unpacked float (d2.w exponent, 0 = zero): adds 1 to
; the exponent unless the value is zero.
;------------------------------------------------------------------------------
rt_float_double:
	tst.w	d2                              ; d2.w = exponent; zero stays zero
	beq.s	.zero
	addq.w	#1,d2                           ; * 2
.zero:
	rts

;------------------------------------------------------------------------------
; Runtime: float / 2 (routine $14d). Subtracts 1 from the exponent in d2; an exponent that
; goes below 0 gives 0.
;------------------------------------------------------------------------------
rt_float_halve:
	subq.w	#1,d2                           ; / 2
	bpl.s	.halve_done
	moveq	#0,d2                           ; exponent went negative: result 0
.halve_done:
	rts

;------------------------------------------------------------------------------
; Runtime: float * 2^d3 (routine $148). Adds d3.w to the exponent in d2 unless the value is
; zero; an exponent that goes negative gives 0.
;------------------------------------------------------------------------------
rt_float_scale_pow2:
	tst.w	d2                              ; zero stays zero
	beq.s	.scale_done
	add.w	d3,d2                           ; exponent + d3
	bpl.s	.scale_done
	moveq	#0,d2                           ; underflow: 0
.scale_done:
	rts

;------------------------------------------------------------------------------
; Runtime: integer d0 / 2, rounded (routine $150): shifts right and adds the bit shifted out.
;------------------------------------------------------------------------------
rt_int_halve_round:
	lsr.l	#1,d0                           ; halve
	bcc.s	.round_done
	addq.l	#1,d0                           ; round up the half
.round_done:
	rts

;------------------------------------------------------------------------------
; Runtime: integer d0 * 2^d3 (routine $14a; d3 >= 0, error 89 on overflow) or d0 / 2^-d3
; rounded (d3 < 0).
;------------------------------------------------------------------------------
rt_int_shift_pow2:
	tst.w	d3                              ; d3 negative: shift right
	bmi.s	.right
	asl.l	d3,d0                           ; d0 * 2^d3
	bvc.s	.shift_done
	moveq	#89,d0                          ; overflow: error 89 (no text for it in the message list)
	jmp	rn_error_entry(a6)              ; raise error d0 (2(a6) = 09dc8)
.right:
	neg.w	d3
	asr.l	d3,d0                           ; d0 / 2^-d3
	bcc.s	.shift_done
	addq.l	#1,d0                           ; round up the half
.shift_done:
	rts

;------------------------------------------------------------------------------
; Runtime: FOR with integer variable, no STEP. d0 = limit, a0 = the variable's address.
; Pushes [limit.l][address.l with type byte 4 in its top byte] on the control stack (a3) and
; saves a3 in 4(a6). When the stack would reach $60(a4) it calls the string garbage
; collector ($203(a6) = 084ec) once, then raises error 91 (FOR error).
;------------------------------------------------------------------------------
rt_for_int:
	movea.l	$60(a4),a1                      ; a1 = top limit of the control stack
	subq.l	#8,a1                           ; 8 bytes needed
	cmpa.l	a1,a3                           ; a3 = control stack pointer
	bcc.s	rt_for_int_stack_full

rt_for_int_push:
	move.l	d0,(a3)+                        ; limit
	move.l	a0,(a3)+                        ; variable address
	move.b	#$4,-$4(a3)                     ; top byte of the address = entry type 4 (integer FOR)
	move.l	a3,rn_saved_registers(a6)       ; save the control stack pointer
	rts

rt_for_int_stack_full:
	jsr	rn_string_garbage_collect(a6)   ; full: string garbage collection (08504)
	movea.l	$60(a4),a1                      ; a1 = top limit of the control stack again
	subq.l	#8,a1
	cmpa.l	a1,a3                           ; room now?
	bcs.s	rt_for_int_push                 ; room now
	moveq	#91,d0                          ; error 91 FOR error
	jmp	rn_error_entry(a6)              ; raise error d0

;------------------------------------------------------------------------------
; Runtime: FOR with integer variable and STEP. d0 = step, d1 = limit, a0 = the variable's address.
; Pushes [limit][step][address with type byte 8] on the control stack (a3), as at 6b5c.
;------------------------------------------------------------------------------
rt_for_int_step_swapped:
	exg	d0,d1                           ; entry d0 = step, d1 = limit: swapped, then pushed

rt_for_int_step:
	movea.l	$60(a4),a1                      ; a1 = top limit of the control stack
	suba.w	#$c,a1                          ; 12 bytes needed
	cmpa.l	a1,a3                           ; room?
	bcc.s	.full_step                      ; no: garbage collect first
	move.l	d0,(a3)+                        ; limit
	move.l	d1,(a3)+                        ; step
	move.l	a0,(a3)+                        ; variable address
	move.b	#$8,-$4(a3)                     ; entry type 8 (integer FOR with STEP)
	move.l	a3,rn_saved_registers(a6)       ; save the control stack pointer
	rts
.full_step:
	jsr	rn_string_garbage_collect(a6)   ; full: string garbage collection (08504)
	movea.l	$60(a4),a1                      ; a1 = top limit again
	suba.w	#$c,a1
	cmpa.l	a1,a3                           ; room now?
	bcs.s	rt_for_int_push                 ; yes: push the entry
	moveq	#91,d0                          ; error 91 FOR error
	jmp	rn_error_entry(a6)              ; raise error d0

;------------------------------------------------------------------------------
; Runtime: NEXT of an integer FOR without STEP. Called as jsr; the 6-byte jmp back to the loop
; follows the call. Pops the variable address, adds 1 and compares with the limit: inside the
; loop the entry stays and it returns to the jmp; past the limit the entry is dropped
; (a3 saved in 4(a6)) and it returns 6 bytes later, after the jmp.
;------------------------------------------------------------------------------
rt_next_int:
	movea.l	-(a3),a0                        ; a0 = variable address
	move.l	(a0),d0                         ; d0 = variable value
	addq.l	#1,d0                           ; + 1
	move.l	d0,(a0)                         ; store it
	cmp.l	-(a3),d0                        ; compare with the limit
	bgt.s	.exit_up                        ; past the limit: leave the loop
	addq.l	#8,a3                           ; keep the entry
	rts                                     ; back to the jmp to the loop start
.exit_up:
	movea.l	(sp)+,a0                        ; return address
	addq.l	#6,a0                           ; skip the 6-byte jmp after the call
	move.l	a3,rn_saved_registers(a6)       ; entry dropped
	jmp	(a0)                            ; continue after the loop

;------------------------------------------------------------------------------
; Runtime: NEXT of an integer FOR ... DOWNTO: as 6bc0 but subtracts 1 and leaves when below
; the limit.
;------------------------------------------------------------------------------
rt_next_int_downto:
	movea.l	-(a3),a0                        ; a0 = variable address
	move.l	(a0),d0                         ; d0 = variable value
	subq.l	#1,d0                           ; - 1
	move.l	d0,(a0)                         ; store it
	cmp.l	-(a3),d0                        ; compare with the limit
	blt.s	.exit_down                      ; below the limit: leave the loop
	addq.l	#8,a3                           ; keep the entry
	rts                                     ; back to the jmp to the loop start
.exit_down:
	movea.l	(sp)+,a0                        ; return address
	addq.l	#6,a0                           ; skip the 6-byte jmp after the call
	move.l	a3,rn_saved_registers(a6)       ; entry dropped
	jmp	(a0)                            ; continue after the loop

;------------------------------------------------------------------------------
; Runtime: NEXT of an integer FOR with STEP: adds the step; a positive step leaves above the
; limit, a negative step below it. Returns to the jmp or 6 bytes after it as 6bc0.
;------------------------------------------------------------------------------
rt_next_int_step:
	movea.l	-(a3),a0                        ; a0 = variable address
	move.l	(a0),d0                         ; d0 = variable value
	move.l	-(a3),d1                        ; d1 = step
	bmi.s	.negative                       ; negative step
	add.l	d1,d0                           ; + step
	move.l	d0,(a0)                         ; store it
	cmp.l	-(a3),d0                        ; compare with the limit
	bgt.s	.exit                           ; above the limit: leave the loop
.loop:
	adda.w	#$c,a3                          ; keep the 12-byte entry
	rts                                     ; back to the jmp to the loop start
.negative:
	add.l	d1,d0                           ; + negative step
	move.l	d0,(a0)                         ; store it
	cmp.l	-(a3),d0                        ; compare with the limit
	bge.s	.loop                           ; still >= limit: loop again
.exit:
	movea.l	(sp)+,a0                        ; leave: skip the jmp after the call
	addq.l	#6,a0
	move.l	a3,rn_saved_registers(a6)
	jmp	(a0)

;------------------------------------------------------------------------------
; Runtime: PEEK(d0) through Supexec, so any address can be read: rt_peek_super does the read.
; Exit d0 = the byte, zero-extended.
;------------------------------------------------------------------------------
rt_peek:
	movea.l	d0,a2                           ; a2 = address
	pea	rt_peek_super(pc)               ; routine to run in supervisor mode
	move.w	#$26,-(sp)                      ; XBIOS 38 Supexec
	trap	#14                             ; Supexec
	addq.l	#6,sp                           ; drop the Supexec arguments
	rts                                     ; d0 = the byte

;------------------------------------------------------------------------------
; Runtime: the supervisor part of PEEK: d0 = byte at (a2).
;------------------------------------------------------------------------------
rt_peek_super:
	moveq	#0,d0                           ; byte zero-extended
	move.b	(a2),d0                         ; read the byte in supervisor mode
	rts

;------------------------------------------------------------------------------
; Runtime: DPEEK(d0) through Supexec. Exit d0 = the word, zero-extended.
;------------------------------------------------------------------------------
rt_dpeek:
	movea.l	d0,a2                           ; a2 = address
	pea	rt_dpeek_super(pc)              ; routine to run in supervisor mode
	move.w	#$26,-(sp)                      ; XBIOS 38 Supexec
	trap	#14                             ; Supexec
	addq.l	#6,sp                           ; drop the Supexec arguments
	rts                                     ; d0 = the word

;------------------------------------------------------------------------------
; Runtime: the supervisor part of DPEEK: d0 = word at (a2).
;------------------------------------------------------------------------------
rt_dpeek_super:
	moveq	#0,d0                           ; word zero-extended
	move.w	(a2),d0                         ; read the word in supervisor mode
	rts

;------------------------------------------------------------------------------
; Runtime: TIMER: reads _hz_200 ($4ba) through Supexec. 6c4e is LPEEK(d0), the same read
; from the address in d0.
;------------------------------------------------------------------------------
rt_timer:
	lea	$4ba.w,a2                       ; _hz_200, a2 = _hz_200 (200 Hz counter): TIMER
	bra.s	rt_lpeek_supexec

;------------------------------------------------------------------------------
; Runtime: LPEEK(d0) (routine $34): the long at address d0, read through Supexec.
;------------------------------------------------------------------------------
rt_lpeek:
	movea.l	d0,a2                           ; LPEEK: a2 = address

;------------------------------------------------------------------------------
; Runtime: runs rt_lpeek_super through Supexec (XBIOS 38) with the address in a2: d0 = the
; long there. Shared by TIMER and LPEEK.
;------------------------------------------------------------------------------
rt_lpeek_supexec:
	pea	rt_lpeek_super(pc)              ; routine to run in supervisor mode
	move.w	#$26,-(sp)                      ; XBIOS 38 Supexec
	trap	#14                             ; Supexec
	addq.l	#6,sp                           ; drop the Supexec arguments
	rts                                     ; d0 = the long

;------------------------------------------------------------------------------
; Runtime: the supervisor part of TIMER/LPEEK: d0 = long at (a2).
;------------------------------------------------------------------------------
rt_lpeek_super:
	move.l	(a2),d0                         ; read the long in supervisor mode
	rts

;------------------------------------------------------------------------------
; Runtime: SPOKE (routine $136): d1 = address, d0 = value; swaps them and falls into 6c64
; (routine $137, d0 = address, d1 = value), which writes the byte through Supexec.
;------------------------------------------------------------------------------
rt_spoke:
	exg	d0,d1                           ; d0 = address, d1 = value

rt_spoke_address_d0:
	movea.l	d0,a2                           ; a2 = address
	move.l	d1,d7                           ; d7 = value
	pea	rt_spoke_super(pc)
	move.w	#$26,-(sp)                      ; XBIOS 38 Supexec
	trap	#14                             ; Supexec
	addq.l	#6,sp                           ; drop the Supexec arguments
	rts

;------------------------------------------------------------------------------
; Runtime: the supervisor part of SPOKE: byte d7 to (a2).
;------------------------------------------------------------------------------
rt_spoke_super:
	move.b	d7,(a2)                         ; write the byte in supervisor mode
	rts

;------------------------------------------------------------------------------
; Runtime: SDPOKE (routine $138): d1 = address, d0 = value; swaps them and falls into 6c7c
; (routine $139, d0 = address, d1 = value), which writes the word through Supexec.
;------------------------------------------------------------------------------
rt_sdpoke:
	exg	d0,d1                           ; d0 = address, d1 = value

rt_sdpoke_address_d0:
	movea.l	d0,a2                           ; a2 = address
	move.l	d1,d7                           ; d7 = value
	pea	rt_sdpoke_super(pc)             ; routine to run in supervisor mode
	move.w	#$26,-(sp)                      ; XBIOS 38 Supexec
	trap	#14                             ; Supexec
	addq.l	#6,sp                           ; drop the Supexec arguments
	rts

;------------------------------------------------------------------------------
; Runtime: the supervisor part of SDPOKE: word d7 to (a2).
;------------------------------------------------------------------------------
rt_sdpoke_super:
	move.w	d7,(a2)                         ; write the word in supervisor mode
	rts

;------------------------------------------------------------------------------
; Runtime: SLPOKE (routine $13a): d1 = address, d0 = value; swaps them and falls into 6c94
; (routine $13b, d0 = address, d1 = value), which writes the long through Supexec.
;------------------------------------------------------------------------------
rt_slpoke:
	exg	d0,d1                           ; d0 = address, d1 = value

rt_slpoke_address_d0:
	movea.l	d0,a2                           ; a2 = address
	move.l	d1,d7                           ; d7 = value
	pea	rt_slpoke_super(pc)             ; routine to run in supervisor mode
	move.w	#$26,-(sp)                      ; XBIOS 38 Supexec
	trap	#14                             ; Supexec
	addq.l	#6,sp                           ; drop the Supexec arguments
	rts

;------------------------------------------------------------------------------
; Runtime: the supervisor part of SLPOKE: long d7 to (a2).
;------------------------------------------------------------------------------
rt_slpoke_super:
	move.l	d7,(a2)                         ; write the long in supervisor mode
	rts

;------------------------------------------------------------------------------
; Runtime: PRINT of an integer d0: converts it to float ($f0(a6) = 06316) and prints that
; ($120(a6), the entry at 6cc8).
;------------------------------------------------------------------------------
rt_print_int:
	jsr	rn_long_to_float(a6)            ; integer to float (0632e)
	jmp	rn_print_float(a6)              ; print the float (06ce0)

;------------------------------------------------------------------------------
; Runtime: PRINT of a boolean in d2: prints 0 for 0, -1 otherwise.
;------------------------------------------------------------------------------
rt_print_bool:
	tst.w	d2                              ; d2 = the boolean
	bne.s	rt_print_bool_true
	moveq	#48,d0                          ; '0'

;------------------------------------------------------------------------------
; Runtime: prints the character in d0 (jmp $123(a6) = rt_print_char).
;------------------------------------------------------------------------------
rt_print_bool_char:
	jmp	rn_print_char(a6)               ; print character d0 (06d62)

;------------------------------------------------------------------------------
; Runtime: prints -1 (TRUE).
;------------------------------------------------------------------------------
rt_print_bool_true:
	moveq	#45,d0                          ; '-'
	bsr.s	rt_print_bool_char
	moveq	#49,d0                          ; '1'
	bra.s	rt_print_bool_char              ; and print it

;------------------------------------------------------------------------------
; Runtime: PRINT of a float variable: a0 = its address. Unpacks it ($e0(a6) = 05b9a); 6cc8
; ($120(a6)) prints the float in d0-d2: formats it ($f8(a6) = 060da, text at a0, length d0)
; and prints the text ($211(a6) = 06d52).
;------------------------------------------------------------------------------
rt_print_float_var:
	jsr	rn_float_load(a6)               ; unpack the float at a0 into d0-d2 (05bb2)

rt_print_float:
	jsr	rn_float_to_string(a6)          ; format the float (060f2): text at a0, length d0
	ext.l	d0                              ; length to a long count
	movea.l	a0,a1                           ; a1 = text
	jmp	rn_print_text(a6)               ; print d0 characters from a1 (06d6a)

;------------------------------------------------------------------------------
; Runtime: PRINT of a string: a0 = its descriptor. $212(a6) (085ca) gives a1 = text and
; d0 = length; $211(a6) prints them.
;------------------------------------------------------------------------------
rt_print_string:
	jsr	rn_string_text_len_212(a6)      ; a1 = text, d0 = length of the string at a0 (085ca)
	jmp	rn_print_text(a6)               ; print d0 characters from a1 (06d6a)

;------------------------------------------------------------------------------
; Runtime: TAB(d0) in PRINT. Compares d0 (0..255) with the column of the current channel
; (byte $24c(a4) + channel number $228(a4)): when the column is already past it prints CR LF
; ($125(a6) = 06d44) and then d0 spaces, otherwise d0 - column spaces (SPC, $128(a6)).
;------------------------------------------------------------------------------
rt_print_tab:
	andi.w	#$ff,d0                         ; the TAB column
	lea	$24c(a4),a0                     ; column bytes of the channels
	adda.w	$228(a4),a0                     ; + current channel number (may be negative)
	moveq	#0,d1
	move.b	(a0),d1                         ; d1 = column of the channel
	cmp.w	d1,d0
	bcs.s	.newline                        ; already past the column: new line first
	sub.w	d1,d0                           ; spaces still needed
	bra.s	.spaces
.newline:
	move.w	d0,-(sp)
	jsr	rn_print_crlf(a6)               ; print CR LF (06d5c)
	move.w	(sp)+,d0
.spaces:
	jmp	rn_print_spc(a6)                ; SPC d0 (06d1a)
	btst	d0,-(a4)                        ; word $0124, not code: TAB ends at the jmp before

;------------------------------------------------------------------------------
; Runtime: SPC(d0) ($128(a6)): prints d0 spaces, 16 at a time from dat_sixteen_spaces.
; (The word at 6d00 is not code: TAB ends at the jmp before it.)
;------------------------------------------------------------------------------
rt_print_spc:
	subi.w	#$10,d0                         ; more than 16 left?
	bcs.s	.rest
	move.w	d0,-(sp)
	moveq	#16,d0                          ; 16 spaces
	bsr.s	rt_print_space_block
	move.w	(sp)+,d0
	bra.s	rt_print_spc                    ; next block
.rest:
	addi.w	#$10,d0                         ; the rest
	ext.l	d0                              ; count to a long
	bra.s	rt_print_space_block            ; print them

;------------------------------------------------------------------------------
; Runtime: the comma in PRINT: prints spaces up to the next multiple of 16 of the character
; count $86e(a4) (1..16 spaces).
;------------------------------------------------------------------------------
rt_print_comma:
	move.w	$86e(a4),d0                     ; character count
	not.w	d0                              ; - count - 1 ...
	andi.l	#$f,d0                          ; spaces to the next multiple of 16
	addq.l	#1,d0                           ; 1..16 spaces

;------------------------------------------------------------------------------
; Runtime: prints d0 characters of dat_sixteen_spaces ($211(a6)).
;------------------------------------------------------------------------------
rt_print_space_block:
	lea	dat_sixteen_spaces(pc),a1       ; the 16 spaces
	jmp	rn_print_text(a6)               ; print d0 characters from a1 (06d6a)

;------------------------------------------------------------------------------
; Data: 16 spaces (16 times $2020, decoded as move.l -(a0),d0).
;------------------------------------------------------------------------------
dat_sixteen_spaces:
	move.l	-(a0),d0                        ; $2020 = two spaces
	move.l	-(a0),d0
	move.l	-(a0),d0
	move.l	-(a0),d0
	move.l	-(a0),d0
	move.l	-(a0),d0
	move.l	-(a0),d0
	move.l	-(a0),d0

;------------------------------------------------------------------------------
; Runtime: prints one space. 6d44 ($125(a6)) prints CR LF.
;------------------------------------------------------------------------------
rt_print_space:
	moveq	#32,d0                          ; ' '
	bra.s	rt_print_char

;------------------------------------------------------------------------------
; Runtime: prints CR LF (routine $125): CR through rt_print_char, then falls into it with LF.
;------------------------------------------------------------------------------
rt_print_crlf:
	moveq	#13,d0                          ; CR
	bsr.s	rt_print_char
	moveq	#10,d0                          ; LF

;------------------------------------------------------------------------------
; Runtime: print one character ($123(a6)): d0 = the character. It is put in the one-byte
; buffer at 06e04 ($210(a6)) and printed by the next entry.
; 6d52 ($211(a6)): print d0.l characters from a1 on the current channel $228(a4). Adds the
; count to $87e(a4), keeps the channel's column byte at $24c(a4)+channel (CR = 0, BS - 1,
; LF no change, others + 1), then writes:
;   channel >= 0: GEMDOS handle, Fwrite (error 37 Disk full on a short write)
;   channel -7 (LPRINT): Fwrite to handle -3 (PRN:)
;   channel -6..-1: BIOS device 0..5 by Bconout, the mouse hidden first ($205(a6) = 09d26);
;   CON: and the raw screen go to the GEM window text output ($d7(a6) = 0b160) when $b36(a4) is set.
;------------------------------------------------------------------------------
rt_print_char:
	lea	rn_print_char_buffer(a6),a1     ; the one-byte print buffer (06e1c)
	move.b	d0,(a1)                         ; character into the buffer
	moveq	#1,d0                           ; one character

rt_print_text:
	add.w	d0,$86e(a4)                     ; $211(a6) enters here: a1 = text, d0.l = count
	move.w	$228(a4),d6                     ; d6 = current channel
	lea	$24c(a4),a0                     ; column byte of the channel
	adda.w	d6,a0
	move.b	(a0),d7                         ; d7 = column
	movea.l	a1,a2                           ; a2 scans the text
	move.l	d0,d1                           ; d1 = count
	moveq	#8,d3                           ; d3 = BS
	moveq	#10,d5                          ; d5 = LF
	moveq	#13,d4                          ; d4 = CR
	bra.s	.next                           ; count the characters
.column:
	move.b	(a2)+,d2                        ; next character
	cmp.b	d5,d2                           ; LF: column unchanged
	beq.s	.next
	cmp.b	d3,d2                           ; backspace: column - 1
	bne.s	.count
	subq.b	#2,d7                           ; BS: - 2, then + 1 below
.count:
	addq.b	#1,d7                           ; column + 1
	cmp.b	d4,d2                           ; CR: column 0
	bne.s	.next
	moveq	#0,d7                           ; CR: column 0
.next:
	dbra	d1,.column                      ; count low word
	subi.l	#$10000,d1                      ; and the high word
	bpl.s	.column
	move.b	d7,(a0)                         ; store the new column
	tst.w	d6                              ; channel >= 0: GEMDOS file handle
	bpl.s	.fwrite
	addq.w	#6,d6                           ; -6..-1 become BIOS devices 0..5
	bmi.s	.printer                        ; -7 (LPRINT): handle -3
	bsr.s	rt_gem_text_redirect            ; CON:/screen to the GEM window?
	pea	(a3)                            ; keep a3
	movea.l	a1,a3                           ; a3 = text
	move.l	d0,d7                           ; d7 = count
	jsr	rn_mouse_hide(a6)               ; hide the mouse once (09d32)
	bra.s	.bconout_next
.bconout:
	moveq	#0,d0                           ; next character, zero-extended
	move.b	(a3)+,d0
	move.w	d0,-(sp)                        ; character
	move.w	d6,-(sp)                        ; BIOS device
	move.w	#$3,-(sp)                       ; BIOS 3 Bconout
	trap	#13                             ; Bconout
	addq.l	#6,sp                           ; drop the Bconout arguments
.bconout_next:
	dbra	d7,.bconout                     ; count low word
	subi.l	#$10000,d7                      ; and the high word
	bpl.s	.bconout
	movea.l	(sp)+,a3                        ; restore a3
	rts
.printer:
	moveq	#-3,d6                          ; GEMDOS handle -3 (PRN:)
.fwrite:
	pea	(a1)                            ; buffer address
	move.l	d0,-(sp)                        ; count
	beq.s	.check                          ; nothing to write
	move.w	d6,-(sp)
	move.w	#$40,-(sp)                      ; GEMDOS $40 Fwrite
	trap	#1                              ; Fwrite
	addq.l	#4,sp                           ; drop handle and function, count and buffer stay
.check:
	cmp.l	(sp)+,d0                        ; all written?
	addq.l	#4,sp                           ; drop the buffer address
	bne.s	.error
	rts
.error:
	tst.l	d0                              ; a GEMDOS error stays as it is
	bmi.s	.raise
	moveq	#37,d0                          ; short write: error 37 Disk full
.raise:
	jmp	rn_error_entry(a6)

;------------------------------------------------------------------------------
; Runtime: for BIOS devices 2 (CON:) and 5 (screen), when $b36(a4) is set, drops the return
; address and goes to the GEM window text output ($d7(a6) = 0b160) instead of Bconout.
;------------------------------------------------------------------------------
rt_gem_text_redirect:
	tst.w	$b36(a4)                        ; GEM window text output on?
	beq.s	.no_gem
	cmpi.w	#$2,d6                          ; CON:
	beq.s	.gem
	cmpi.w	#$5,d6                          ; raw screen
	bne.s	.no_gem
.gem:
	addq.l	#4,sp                           ; drop the return address
	jmp	rn_window_print_text(a6)        ; GEM window text output (0b2ae)
.no_gem:
	rts

; Data/runtime: the word at 6e04 ($3039) is the one-byte print buffer ($210(a6), only its
; first byte is used). 6e06 (routine $202) is VSYNC: XBIOS 37 Vsync.
rt_print_char_buffer:
	dc.w	$3039                           ; $3039 = the print buffer byte; VSYNC is at 6e06

rt_vsync:
	move.w	#$25,-(sp)                      ; XBIOS 37 Vsync
	trap	#14                             ; Vsync
	addq.l	#2,sp                           ; drop the function number
	rts

;------------------------------------------------------------------------------
; Runtime: HARDCOPY: XBIOS Scrdmp.
;------------------------------------------------------------------------------
rt_hardcopy:
	move.w	#$14,-(sp)                      ; XBIOS 20 Scrdmp
	trap	#14                             ; Scrdmp
	addq.l	#2,sp                           ; drop the function number
	rts

;------------------------------------------------------------------------------
; Runtime: a condition as a float: d2 = 0 stays 0.0, anything else gives -1.0
; (d0 = $80000000, d1 = 0, d2 = $ffff0200: exponent $200, sign bit 31).
;------------------------------------------------------------------------------
rt_bool_to_float:
	tst.w	d2                              ; d2 = 0: false, 0.0
	bne.s	.true
	rts                                     ; 0.0 as it is
.true:
	move.l	#$80000000,d0                   ; -1.0: exponent $200, sign bit set
	moveq	#0,d1                           ; low mantissa word 0
	move.l	#$ffff0200,d2                   ; sign bit set, exponent $200
	rts

;------------------------------------------------------------------------------
; Runtime: integer square root of d0 (Newton's method with divu). Exit d0 = the root;
; 0 gives 0, a negative number error 5 (Square root only for positive numbers).
;------------------------------------------------------------------------------
rt_int_sqr:
	move.l	d0,d1                           ; negative or zero
	ble.s	.not_positive
	moveq	#1,d2                           ; first guess: grow d2, shrink d1
.guess:
	cmp.l	d2,d1                           ; guess: double d2, halve d1 until d2 >= d1
	bls.s	.iterate
	add.l	d2,d2                           ; d2 * 2
	lsr.l	#1,d1                           ; d1 / 2
	bra.s	.guess
.iterate:
	add.l	d1,d2                           ; d2 = (guess + d0/guess) / 2
	lsr.l	#1,d2
	move.l	d0,d1
	divu.w	d2,d1                           ; d1 = d0 / guess
	bvs.s	.result                         ; quotient too large: done
	cmp.w	d1,d2                           ; converged
	bls.s	.result                         ; guess no larger than the quotient: done
	swap	d1                              ; keep the quotient word only
	clr.w	d1                              ; ...
	swap	d1                              ; ... d1 = quotient
	bra.s	.iterate                        ; next step
.result:
	moveq	#0,d0                           ; d0 = the root
	move.w	d2,d0
.sqrt_done:
	rts
.not_positive:
	beq.s	.sqrt_done                      ; zero: SQR(0) = 0
	moveq	#5,d0                           ; error 5 Square root only for positive numbers
	jmp	rn_error_entry(a6)              ; raise error d0

;------------------------------------------------------------------------------
; Runtime: ABS of the integer d0.
;------------------------------------------------------------------------------
rt_int_abs:
	tst.l	d0                              ; negative?
	bpl.s	.abs_done
	neg.l	d0                              ; make it positive
.abs_done:
	rts

;------------------------------------------------------------------------------
; Runtime: INC of a float variable. 6e6c (routine $1bf) takes the address in d0; 6e6e
; (routine $14e) takes it in a0. Unpacks the 6-byte float, adds 1 ($14b(a6) = 06eb6) and packs it
; back (sign in bit 31 of the first long).
;------------------------------------------------------------------------------
rt_inc_float_at_d0:
	movea.l	d0,a0                           ; a0 = the float variable

rt_inc_float_var:
	move.l	(a0)+,d0                        ; d0 = sign and high mantissa
	move.w	(a0),d1                         ; d1 = low mantissa and exponent
	move.l	d0,d2                           ; d2 = sign in bit 31
	move.w	d1,d2                           ; d2.w = last word
	andi.w	#$3ff,d2                        ; exponent
	sub.w	d2,d1                           ; d1 = low mantissa bits only
	bset	#$1f,d0                         ; implicit top bit
	jsr	rn_float_add_one(a6)            ; add 1 (06ece)
	andi.w	#$fc00,d1                       ; exponent back into the low word
	or.w	d2,d1
	tst.l	d2
	bmi.s	.store
	bclr	#$1f,d0                         ; positive: clear the top bit
.store:
	move.w	d1,(a0)
	move.l	d0,-(a0)
	rts                                     ; a0 back at the variable

;------------------------------------------------------------------------------
; Runtime: DEC of a float variable. 6e98 (routine $1c0) takes the address in d0; 6e9a
; (routine $14f) takes it in a0. Negates it in memory, runs the INC ($14e(a6) = 06e6e) and
; negates it back.
;------------------------------------------------------------------------------
rt_dec_float_at_d0:
	movea.l	d0,a0                           ; a0 = the float variable

rt_dec_float_var:
	bchg	#$7,(a0)                        ; negate it in memory
	jsr	rn_inc_float_var(a6)            ; INC (presumably 06e6c)
	bchg	#$7,(a0)                        ; negate it back
	rts

;------------------------------------------------------------------------------
; Runtime: subtracts 1 from the unpacked float d0-d2: flips the sign, adds 1 ($14b(a6)) and
; flips it back.
;------------------------------------------------------------------------------
rt_float_sub_one:
	bchg	#$1f,d2                         ; flip the sign
	jsr	rn_float_add_one(a6)            ; add 1 (06ece)
	bchg	#$1f,d2
	rts

;------------------------------------------------------------------------------
; Runtime: adds 1 to the unpacked float d0-d2 ($14b(a6)). d0:d1 mantissa with bit 31 of d0
; set, d2.w exponent (bias $200 = 1.0), bit 31 of d2 the sign. With the exponent below $200
; (|x| < 1) it calls the general float add (6(a6) = 05c00) with 1.0 in d3-d5; at $230 and above
; the 1 is below the mantissa and nothing changes; otherwise the bit for 1 is added to (or for
; a negative number subtracted from) the mantissa directly, renormalising.
;------------------------------------------------------------------------------
rt_float_add_one:
	moveq	#0,d4                           ; d4 = the bit for 1
	move.l	d2,d3                           ; d3 = sign and exponent
	bmi.s	.negative                       ; negative number: subtract
	not.w	d3                              ; bit number of the units bit in d0
	cmpi.w	#$200,d2                        ; |x| < 1: general add
	bcs.s	.general
	bset	d3,d4                           ; bit for 1 in the high mantissa long
	cmpi.w	#$220,d2                        ; units bit in d1?
	bcc.s	.low_word
	add.l	d4,d0                           ; add 1
	bcs.s	.carry                          ; carry out: renormalise
.inc_done:
	rts
.low_word:
	cmpi.w	#$230,d2                        ; 1 below the mantissa: unchanged
	bcc.s	.inc_done
	swap	d4                              ; bit for 1 in the low word
	add.w	d4,d1
	bcc.s	.inc_done                       ; no carry: done
	addq.l	#1,d0                           ; carry into the high long
	bcc.s	.inc_done                       ; no carry: done
.carry:
	roxr.l	#1,d0                           ; shift the carry back in
	roxr.w	#1,d1
	addq.w	#1,d2                           ; exponent + 1
	rts
.general:
	move.l	#$80000000,d3                   ; 1.0 in d3-d5
	moveq	#0,d4
	move.l	#$200,d5
	jmp	rn_float_add(a6)                ; float add (05c18)
.negative:
	not.w	d3                              ; negative number: |x| - 1
	cmpi.w	#$200,d2                        ; |x| < 1: general add of 1.0
	bcs.s	.general
	bset	d3,d4                           ; bit for 1
	cmpi.w	#$220,d2                        ; units bit in d1?
	bcc.s	.neg_low_word
	sub.l	d4,d0                           ; subtract 1
	bpl.s	.normalise                      ; top bit gone: renormalise
	rts                                     ; top bit still set: done
.neg_low_word:
	cmpi.w	#$230,d2                        ; 1 below the mantissa: unchanged
	bcc.s	.inc_done
	sub.w	d4,d1                           ; subtract 1 from the low word
	bcc.s	.inc_done                       ; no borrow: done
	subq.l	#1,d0                           ; borrow from the high long
	bmi.s	.inc_done                       ; top bit still set: done
.normalise:
	bne.s	.shift                          ; result zero?
	tst.w	d1
	bne.s	.shift
	moveq	#0,d2                           ; 0.0
	rts
.shift:
	add.w	d1,d1                           ; shift left until the top bit is set
	addx.l	d0,d0
	dbmi	d2,.shift
	subq.w	#1,d2                           ; exponent - 1
	rts

;------------------------------------------------------------------------------
; Runtime: FOR with float variable, no STEP: d0-d2 = the limit, a0 = the variable's address.
; Pushes [limit 10 bytes][address with type byte $a] on the control stack; error 12 when it is
; full even after garbage collection ($203(a6)).
;------------------------------------------------------------------------------
rt_for_float:
	movea.l	$60(a4),a1                      ; a1 = top limit of the control stack
	suba.w	#$e,a1                          ; 14 bytes needed
	cmpa.l	a1,a3                           ; room?
	bcc.s	rt_for_float_stack_full         ; no: garbage collect first

;------------------------------------------------------------------------------
; Runtime: pushes a 14-byte float FOR entry: limit d0-d2 (a zero limit gets its sign
; cleared) and the variable address a0 with type byte $a. Shared by the two FOR entries.
;------------------------------------------------------------------------------
rt_for_float_push:
	move.l	d0,(a3)+                        ; limit mantissa
	move.w	d1,(a3)+                        ; limit low mantissa word
	tst.w	d2                              ; zero exponent: clear the sign too
	bne.s	.sign_ok
	moveq	#0,d2
.sign_ok:
	move.l	d2,(a3)+                        ; limit sign and exponent
	move.l	a0,(a3)+                        ; variable address
	move.b	#$a,-$4(a3)                     ; entry type $a (float FOR)
	rts

rt_for_float_stack_full:
	jsr	rn_string_garbage_collect(a6)   ; full: string garbage collection (08504)
	movea.l	$60(a4),a1                      ; a1 = top limit again
	suba.w	#$e,a1
	cmpa.l	a1,a3                           ; room now?
	bcs.s	rt_for_float_push               ; yes: push the entry
	moveq	#12,d0                          ; error 12
	jmp	rn_error_entry(a6)              ; raise error d0

;------------------------------------------------------------------------------
; Runtime: FOR with float variable and STEP: d0-d2 = step, d3-d5 = limit (swapped
; first), a0 = the variable's address. Pushes 20 bytes and the address with type byte $14.
;------------------------------------------------------------------------------
rt_for_float_step_swapped:
	exg	d0,d3                           ; swap the two floats
	exg	d1,d4
	exg	d2,d5

;------------------------------------------------------------------------------
; Runtime: FOR with float variable and STEP (routine $143): d0-d2 = limit, d3-d5 = step,
; a0 = the variable's address (6f6e, routine $153, takes them the other way round and swaps).
; Pushes [limit 10][step 10][address with type byte $14] on the control stack. When it is full
; it garbage-collects, then re-tests for 28 bytes and on success goes to the no-STEP push
; (6f42), which stores only a 14-byte entry: an inconsistency in the original. Error 12 if
; still full.
;------------------------------------------------------------------------------
rt_for_float_step:
	movea.l	$60(a4),a1                      ; a1 = top limit of the control stack
	suba.w	#$18,a1                         ; 24 bytes needed
	cmpa.l	a1,a3                           ; room?
	bcc.s	.full_step                      ; no: garbage collect first
	tst.w	d2                              ; zero limit: clear its sign too
	bne.s	.limit_sign_ok
	moveq	#0,d2
.limit_sign_ok:
	tst.w	d5                              ; zero step: clear its sign too
	bne.s	.push_step
	moveq	#0,d5
.push_step:
	move.l	d0,(a3)+                        ; limit
	move.w	d1,(a3)+
	move.l	d2,(a3)+
	move.l	d3,(a3)+                        ; step
	move.w	d4,(a3)+
	move.l	d5,(a3)+
	move.l	a0,(a3)+                        ; variable address
	move.b	#$14,-$4(a3)                    ; entry type $14 (float FOR with STEP)
	rts
.full_step:
	jsr	rn_string_garbage_collect(a6)   ; full: string garbage collection
	movea.l	$60(a4),a1
	suba.w	#$1c,a1                         ; 28 bytes: not the 24 tested above
	cmpa.l	a1,a3                           ; room now?
	bcs.s	rt_for_float_push               ; to the no-STEP push: only 14 bytes stored
	moveq	#12,d0                          ; error 12
	jmp	rn_error_entry(a6)              ; raise error d0

;------------------------------------------------------------------------------
; Runtime: NEXT of a float FOR ... DOWNTO (routine $145): subtracts 1 from the variable (adds
; 1 with the sign flipped, $14b(a6)), compares with the limit, packs it back. Returns to the jmp
; after the call while in the loop (entry kept), 6 bytes later when done (entry dropped).
;------------------------------------------------------------------------------
rt_next_float_downto:
	movea.l	-(a3),a0                        ; a0 = the float variable
	move.l	(a0)+,d0                        ; d0 = sign and high mantissa
	move.w	(a0),d1                         ; d1 = low mantissa and exponent
	move.l	d0,d2                           ; d2 = sign ...
	not.l	d2                              ; d2 = inverted sign in bit 31
	move.w	d1,d2                           ; d2.w = last word
	bset	#$1f,d0                         ; implicit top bit
	andi.w	#$3ff,d2                        ; d2.w = exponent
	sub.w	d2,d1                           ; d1 = low mantissa bits only
	jsr	rn_float_add_one(a6)            ; add 1 with the sign flipped: subtract 1
	tst.w	d2                              ; result zero?
	beq.s	.zero
	bchg	#$1f,d2                         ; sign back
	move.l	-(a3),d5                        ; d3-d5 = the limit
	bchg	#$1f,d5                         ; limit compared with its sign flipped as well
	move.w	-(a3),d4
	move.l	-(a3),d3
	tst.l	d2                              ; result positive after the flip back?
	bpl.s	rt_next_float_inc_neg           ; negative value: compare the other way
	bra.s	rt_next_float_inc_cmp           ; positive: compare
.zero:
	tst.l	-(a3)                           ; zero: compare the limit's sign
	subq.l	#6,a3                           ; a3 at the start of the entry
	ble.s	rt_next_float_inc_done          ; limit <= 0: still in the loop

;------------------------------------------------------------------------------
; Runtime: NEXT float: loop finished, return 6 bytes later (past the jmp back).
;------------------------------------------------------------------------------
rt_next_float_inc_loop:
	addq.l	#6,(sp)                         ; loop finished: return past the jmp
	bra.s	rt_next_float_inc_store

;------------------------------------------------------------------------------
; Runtime: NEXT of a float FOR without STEP (routine $144): adds 1 ($14b(a6)), compares with
; the limit on the control stack and packs the result back into the variable. Still in the
; loop: a3 restored (entry kept) and back to the jmp; finished: 6 bytes later, entry dropped.
;------------------------------------------------------------------------------
rt_next_float:
	movea.l	-(a3),a0                        ; a0 = the float variable
	move.l	(a0)+,d0                        ; d0 = sign and high mantissa
	move.w	(a0),d1                         ; d1 = low mantissa and exponent
	move.l	d0,d2                           ; d2 = sign ...
	move.w	d1,d2                           ; d2.w = last word
	bset	#$1f,d0                         ; implicit top bit
	andi.w	#$3ff,d2                        ; d2.w = exponent
	sub.w	d2,d1                           ; d1 = low mantissa bits only
	jsr	rn_float_add_one(a6)            ; add 1 (06ece)
	move.l	-(a3),d5                        ; d3-d5 = the limit
	move.w	-(a3),d4
	move.l	-(a3),d3
	tst.l	d2                              ; negative value?
	bmi.s	rt_next_float_inc_neg           ; yes: compare the other way

;------------------------------------------------------------------------------
; Runtime: NEXT float: compares the new value d0-d2 with the limit d3-d5 for a positive value;
; above the limit the loop is finished.
;------------------------------------------------------------------------------
rt_next_float_inc_cmp:
	tst.l	d5                              ; negative limit: past it
	bmi.s	rt_next_float_inc_loop
	cmp.w	d5,d2                           ; compare exponents, then mantissas
	bne.s	rt_next_float_inc_test          ; exponents differ
	cmp.l	d3,d0
	bne.s	rt_next_float_inc_test          ; high mantissas differ
	cmp.w	d4,d1                           ; low mantissa words

rt_next_float_inc_test:
	bhi.s	rt_next_float_inc_loop          ; above the limit: loop finished

;------------------------------------------------------------------------------
; Runtime: NEXT float still in the loop: a3 back up over the 14-byte entry, so it stays.
;------------------------------------------------------------------------------
rt_next_float_inc_done:
	adda.w	#$e,a3                          ; still in the loop: keep the 14-byte entry

rt_next_float_inc_store:
	addi.w	#$200,d1                        ; round at bit 9 of the low word
	bcs.s	rt_next_float_round_carry

;------------------------------------------------------------------------------
; Runtime: packs d0-d2 back into the 6-byte variable at a0-4: exponent into the low 10 bits of
; the last word, sign into bit 31 of the first long.
;------------------------------------------------------------------------------
rt_next_float_pack:
	andi.w	#$fc00,d1                       ; exponent into the low 10 bits
	or.w	d2,d1
	tst.l	d2                              ; positive: clear the top bit
	bmi.s	.positive
	bclr	#$1f,d0
.positive:
	move.w	d1,(a0)                         ; store the float
	move.l	d0,-(a0)
	rts

;------------------------------------------------------------------------------
; Runtime: rounding carried out of the mantissa: shift right and raise the exponent.
;------------------------------------------------------------------------------
rt_next_float_round_carry:
	addq.l	#1,d0                           ; round into the high long
	bcc.s	rt_next_float_pack
	roxr.l	#1,d0                           ; overflow: shift and exponent + 1
	roxr.w	#1,d1
	addq.w	#1,d2
	bra.s	rt_next_float_pack

rt_next_float_inc_neg:
	tst.l	d5                              ; both negative: compare the other way
	bpl.s	rt_next_float_inc_done          ; positive limit: below it, still in the loop
	cmp.w	d2,d5                           ; compare exponents, then mantissas, reversed
	bne.s	rt_next_float_inc_test
	cmp.l	d0,d3
	bne.s	rt_next_float_inc_test
	cmp.w	d1,d4
	bra.s	rt_next_float_inc_test

;------------------------------------------------------------------------------
; Runtime: NEXT of a float FOR with STEP (routine $146): adds the step (d3-d5 from the stack)
; with the float add (6(a6)), then compares with the limit, the direction set by the sign of
; the step. Returns as 6ff4.
;------------------------------------------------------------------------------
rt_next_float_step:
	movea.l	-(a3),a0                        ; a0 = the float variable
	move.l	(a0)+,d0                        ; d0 = sign and high mantissa
	move.w	(a0),d1                         ; d1 = low mantissa and exponent
	move.l	d0,d2                           ; d2 = sign ...
	move.w	d1,d2                           ; d2.w = last word
	bset	#$1f,d0                         ; implicit top bit
	andi.w	#$3ff,d2                        ; d2.w = exponent
	sub.w	d2,d1                           ; d1 = low mantissa bits only
	move.l	-(a3),d5                        ; d3-d5 = the step
	smi	-(sp)                           ; keep the step's sign
	move.w	-(a3),d4
	move.l	-(a3),d3
	jsr	rn_float_add(a6)                ; float add (05c18)
	move.l	-(a3),d5                        ; d3-d5 = the limit
	move.w	-(a3),d4
	move.l	-(a3),d3
	tst.w	d2                              ; result zero?
	beq.s	.zero
	tst.b	(sp)+                           ; positive step
	bpl.s	rt_next_float_step_up
	bchg	#$1f,d5                         ; negative step: compare reversed
	tst.l	d2                              ; positive result: compare reversed
	bpl.s	rt_next_float_step_neg
	bra.s	rt_next_float_step_cmp
.zero:
	tst.b	(sp)+                           ; drop the step's sign flag (sets the flags)
	bsr.s	rt_neg_step_if_plus             ; positive step: negate the limit's sign/exponent long
	tst.l	d5                              ; limit <= 0: still in the loop
	ble.s	rt_next_float_step_done

rt_next_float_step_loop:
	addq.l	#6,(sp)                         ; loop finished: return past the jmp
	bra.s	rt_next_float_step_store        ; pack the variable

rt_next_float_step_up:
	tst.l	d2                              ; negative result?
	bmi.s	rt_next_float_step_neg          ; yes: compare the other way

rt_next_float_step_cmp:
	tst.l	d5                              ; negative limit: finished
	bmi.s	rt_next_float_step_loop
	cmp.w	d5,d2                           ; compare exponents, then mantissas
	bne.s	rt_next_float_step_test
	cmp.l	d3,d0
	bne.s	rt_next_float_step_test
	cmp.w	d4,d1

rt_next_float_step_test:
	bhi.s	rt_next_float_step_loop         ; above the limit: loop finished

;------------------------------------------------------------------------------
; Runtime: NEXT float with STEP still in the loop: a3 back up over the 24-byte entry.
;------------------------------------------------------------------------------
rt_next_float_step_done:
	adda.w	#$18,a3                         ; still in the loop: keep the 24-byte entry

rt_next_float_step_store:
	addi.w	#$200,d1                        ; round at bit 9 of the low word
	bcs.s	rt_next_float_round_carry       ; carry out: renormalise

rt_next_float_step_pack:
	andi.w	#$fc00,d1                       ; exponent into the low 10 bits
	or.w	d2,d1
	tst.l	d2                              ; positive: clear the top bit
	bmi.s	.positive
	bclr	#$1f,d0
.positive:
	move.w	d1,(a0)                         ; store the float
	move.l	d0,-(a0)
	rts

;------------------------------------------------------------------------------
; Runtime: negates d5 when the flags show a positive step (bmi skips).
;------------------------------------------------------------------------------
rt_neg_step_if_plus:
	bmi.s	.done                           ; negative: unchanged
	neg.l	d5                              ; negate d5
.done:
	rts
	roxr.w	#1,d1                           ; unreachable: never jumped to
	addq.w	#1,d2
	bra.s	rt_next_float_step_pack

rt_next_float_step_neg:
	tst.l	d5                              ; positive limit: still in the loop
	bpl.s	rt_next_float_step_done
	cmp.w	d2,d5                           ; compare exponents, then mantissas, reversed
	bne.s	rt_next_float_step_test
	cmp.l	d0,d3
	bne.s	rt_next_float_step_test
	cmp.w	d1,d4
	bra.s	rt_next_float_step_test

;------------------------------------------------------------------------------
; Runtime: channel errors: 70f2 raises error 23 (File # wrong), 70f6 error 24 (File not open).
;------------------------------------------------------------------------------
rt_error_file_number_wrong:
	moveq	#23,d0                          ; error 23 File # wrong
	bra.s	rt_raise_channel_error

rt_error_file_not_open:
	moveq	#24,d0                          ; error 24 File not open

rt_raise_channel_error:
	jmp	rn_error_entry(a6)              ; raise error d0

;------------------------------------------------------------------------------
; Runtime: selects channel #d0 for output/input ($126(a6)): d0 below 100 (else error 23 File #
; wrong), its handle from the table at $7fc(a4) (0 = error 24 File not open) into $228(a4) and
; $22a(a4); clears the character count $86c(a4).
; 7110: selects the printer (LPRINT, channel -7); 7114 ($10b(a6)): the screen (channel -4).
;------------------------------------------------------------------------------
rt_select_channel:
	cmpi.w	#$64,d0                         ; channel numbers 0..99
	bcc.s	rt_error_file_number_wrong      ; above 99: error 23
	lea	$7ec(a4),a0                     ; channel table: one handle byte each
	adda.w	d0,a0                           ; + channel number
	move.b	(a0),d0                         ; 0 = not open
	beq.s	rt_error_file_not_open          ; not open: error 24
	ext.w	d0                              ; handle or device code to a word
	bra.s	rt_set_output_channel           ; make it current

rt_select_printer:
	moveq	#-7,d0                          ; LPRINT: channel -7
	bra.s	rt_set_output_channel

rt_select_screen:
	moveq	#-4,d0                          ; PRINT: screen, channel -4 (CON:)

;------------------------------------------------------------------------------
; Runtime: makes d0 the current output and input channel ($228(a4), $22a(a4)) and clears the
; character count $86c(a4).
;------------------------------------------------------------------------------
rt_set_output_channel:
	move.w	d0,$228(a4)                     ; current output channel
	move.w	d0,$22a(a4)
	clr.l	$86c(a4)                        ; clear the character count
	rts

;------------------------------------------------------------------------------
; Runtime: OUT d1,d0: prints the byte d0 on BIOS device d1 (channel d1 - 6).
;------------------------------------------------------------------------------
rt_out:
	subq.w	#6,d1                           ; BIOS device - 6 = channel
	move.w	d1,$228(a4)                     ; the channel to print on
	jmp	rn_print_char(a6)               ; print character d0 (06d62)

;------------------------------------------------------------------------------
; Runtime: CLS: selects the screen ($10b(a6)) and prints ESC E.
;------------------------------------------------------------------------------
rt_cls:
	jsr	rn_select_screen(a6)            ; select the screen (0712c)

;------------------------------------------------------------------------------
; Runtime: prints the 2 bytes at dat_esc_e (ESC E, clear screen) on the current channel.
;------------------------------------------------------------------------------
rt_cls_print_esc_e:
	lea	dat_esc_e(pc),a1                ; ESC E
	moveq	#2,d0                           ; 2 characters
	jmp	rn_print_text(a6)               ; print them (06d6a)

; Data and code: 713c-713d are ESC E ($1b,$45); the listing decodes them with the next word
; as one move.b. 713e is CLS #n: jsr $126(a6) (select channel #d0, bytes 4eae 0126) then
; bra rt_cls_print_esc_e.
dat_esc_e:
	dc.w	$1b45                           ; ESC E, then 713e: jsr $126(a6) (select channel #d0)

;------------------------------------------------------------------------------
; Runtime: CLS #n (routine $10e): selects channel #d0 ($126(a6)) and prints ESC E there.
;------------------------------------------------------------------------------
rt_cls_channel:
	jsr	rn_select_channel(a6)
	bra.s	rt_cls_print_esc_e              ; print ESC E

;------------------------------------------------------------------------------
; Runtime: BPUT: prints d0 bytes from address d1 on the current channel ($211(a6)).
;------------------------------------------------------------------------------
rt_bput:
	movea.l	d1,a1                           ; a1 = address, d0 = count
	jmp	rn_print_text(a6)               ; write them (06d6a)

;------------------------------------------------------------------------------
; Runtime: BGET: reads d0 bytes to address d1 from the current channel (d6) through $18c(a6)
; (not identified in this range).
;------------------------------------------------------------------------------
rt_bget:
	movea.l	d1,a1                           ; a1 = address
	move.w	$228(a4),d6                     ; d6 = current channel
	jmp	rn_input_string_read(a6)        ; read d0 bytes to a1 (not identified)

;------------------------------------------------------------------------------
; Runtime: POS (routine $a4): d0 = the column of the screen channel, the byte at $248(a4)
; (column bytes at $24c(a4) + channel, channel -4).
;------------------------------------------------------------------------------
rt_pos:
	moveq	#0,d0                           ; POS: column of the screen channel
	move.b	$248(a4),d0
	rts

;------------------------------------------------------------------------------
; Runtime: LPOS (routine $a5): d0 = the column of the printer channel, the byte at $245(a4)
; (channel -7).
;------------------------------------------------------------------------------
rt_lpos:
	moveq	#0,d0                           ; LPOS: column of the printer channel
	move.b	$245(a4),d0
	rts

; Data: the number of the channel opened by rt at 7166 for BLOAD/BSAVE/DIR TO ($189(a6));
; negative = none open.
dat_temp_channel:
	dc.w	$ffff

;------------------------------------------------------------------------------
; Runtime: opens a temporary channel ($18a(a6)): a0 = the file name descriptor, d1 = the mode
; letter ('I' or 'O'). Builds a 1-character mode string at $ae2(a4) with its descriptor at
; $ad8(a4), takes the highest free channel number (99 down) into dat_temp_channel, opens it
; ($96(a6), presumably OPEN at 071b0) and selects it ($126(a6)).
;------------------------------------------------------------------------------
rt_open_temp_channel:
	lea	$ad2(a4),a1                     ; build the mode string here
	move.b	d1,(a1)                         ; the mode letter
	move.l	a1,6(a1)                        ; descriptor: address
	move.w	#$1,$a(a1)                      ; descriptor: length 1
	addq.l	#6,a1                           ; a1 = the mode descriptor
	lea	$7ec(a4),a2                     ; channel table
	moveq	#99,d1                          ; highest channel number
.free:
	tst.b	0(a2,d1.w)                      ; free channel?
	dbeq	d1,.free                        ; search 99 down for a free entry
	move.w	d1,rn_dat_temp_channel(a6)      ; dat_temp_channel
	jsr	rn_open(a6)                     ; OPEN (presumably 071b0)
	move.w	dat_temp_channel(pc),d0         ; select the channel (07114)
	jmp	rn_select_channel(a6)           ; select it (07114)

;------------------------------------------------------------------------------
; Runtime: closes the temporary channel ($18b(a6)) when one is open: tas marks it closed,
; then CLOSE ($99(a6) = 07314).
;------------------------------------------------------------------------------
rt_close_temp_channel_if_open:
	move.w	dat_temp_channel(pc),d0         ; the temporary channel
	tas	rn_dat_temp_channel(a6)         ; mark it closed; was it open?
	bmi.s	.done
	jmp	rn_close(a6)                    ; CLOSE #d0 (0732c)
.done:
	rts

;------------------------------------------------------------------------------
; Runtime: OPEN errors: 71a6 raises error 23 (File # wrong), 71aa error 22 (File already open).
;------------------------------------------------------------------------------
rt_open_error_number_wrong:
	moveq	#23,d0                          ; error 23 File # wrong
	bra.s	rt_open_raise_error

rt_open_error_already_open:
	moveq	#22,d0                          ; error 22 File already open

rt_open_raise_error:
	jmp	rn_error_entry(a6)              ; raise error d0

;------------------------------------------------------------------------------
; Runtime: OPEN mode$,#n,name$[,len] ($96(a6)). Entry a1 = mode descriptor, d1 = channel
; number, a0 = name descriptor; d0 = record length (71b0 sets the default 128, 71b4 takes d0)
; kept at $30e(a4). Errors 23 (number > 100) and 22 (already open). A name of 4 characters or
; more that starts with a device in dat_device_names gives the channel code -7..-1; otherwise
; the file is opened by mode letter: O Fcreate, I Fopen read, U Fopen read/write,
; A Fopen read/write + Fseek to the end, R Fopen read/write or Fcreate (random file);
; any other letter error 21.
;------------------------------------------------------------------------------
rt_open:
	move.w	#$80,d0                         ; default record length 128

rt_open_record_length:
	move.w	d0,$30e(a4)                     ; record length
	move.w	d1,d5                           ; d5 = channel number
	move.l	a0,d6                           ; d6 = name descriptor
	movea.l	a1,a0                           ; a0 = mode descriptor
	jsr	rn_string_text_len_212(a6)      ; the mode string
	tst.w	d0                              ; empty mode string?
	beq.s	.mode                           ; yes: mode 0, error 21 later
	move.b	(a1),d0                         ; its first letter
.mode:
	andi.w	#$df,d0                         ; upper case
	move.w	d0,d4                           ; d4 = mode letter
	movea.l	d6,a0                           ; the name string: a1 = text, d0 = length
	jsr	rn_string_text_len_212(a6)      ; a1 = name text, d0 = length (085ca)
	cmpi.w	#$64,d5                         ; above 100: error 23
	bhi.s	rt_open_error_number_wrong
	lea	$7ec(a4),a0                     ; channel table
	adda.w	d5,a0                           ; + channel number
	tst.b	(a0)                            ; already open: error 22
	bne.s	rt_open_error_already_open
	lea	dat_device_names(pc),a2         ; the device names
	cmpi.w	#$4,d0                          ; shorter than 4: a file
	bcs.s	rt_open_file
	moveq	#6,d1                           ; 7 devices
	move.l	(a1),d2                         ; d2 = first 4 characters of the name
	andi.l	#$dfdfdfff,d2                   ; upper case except the ':'
.device:
	cmp.l	(a2)+,d2                        ; match?
	dbeq	d1,.device
	bne.s	rt_open_file                    ; no match: open a file
	not.w	d1                              ; device code -7..-1
	move.b	d1,(a0)                         ; into the channel table
	rts

;------------------------------------------------------------------------------
; Data: the device names PRN: LST: AUX: CON: MID: IKB: VID: (4 bytes each, decoded in part as
; instructions) compared with the first 4 characters of an OPEN name.
;------------------------------------------------------------------------------
dat_device_names:
	addq.w	#8,(a2)                         ; "PR" of PRN:
	dc.b	'N:LST:AUX:CON:MID:IKB:'
	addq.w	#3,a1                           ; "VI" of VID:
	dc.w	$443a                           ; "D:"

;------------------------------------------------------------------------------
; Runtime: OPEN of a file: NUL-terminates the name temporarily (byte d5 at d3) and goes by the
; mode letter in d4.
;------------------------------------------------------------------------------
rt_open_file:
	move.l	a0,d6                           ; d6 = the channel's table entry
	tst.w	d0
	bne.s	.name                           ; not empty: use it
	lea	$ad6(a4),a1                     ; empty name
.name:
	lea	0(a1,d0.w),a2                   ; end of the name
	move.b	(a2),d5                         ; keep the byte there
	move.l	a2,d3                           ; d3 = end of the name
	clr.b	(a2)                            ; NUL-terminate the name
	cmpi.b	#$4f,d4                         ; "O"
	beq.s	.output
	cmpi.b	#$52,d4                         ; "R"
	beq.s	rt_open_random
	cmpi.b	#$41,d4                         ; "A"
	beq.s	rt_open_append
	cmpi.b	#$55,d4                         ; "U"
	beq.s	rt_open_update
	cmpi.b	#$49,d4                         ; "I"
	beq.s	.input
	movea.l	d3,a2                           ; unknown mode: put the byte back
	move.b	d5,(a2)
	moveq	#21,d0                          ; error 21 (allowed modes)
	jmp	rn_error_entry(a6)
.input:
	moveq	#61,d0                          ; GEMDOS $3d Fopen
	bra.s	.mode_zero
.output:
	moveq	#60,d0                          ; GEMDOS $3c Fcreate
.mode_zero:
	clr.w	-(sp)                           ; mode/attribute 0

;------------------------------------------------------------------------------
; Runtime: GEMDOS open call: d0 = function, a1 = name, the mode word already pushed.
;------------------------------------------------------------------------------
rt_open_gemdos_call:
	pea	(a1)                            ; file name
	move.w	d0,-(sp)                        ; GEMDOS function
	trap	#1                              ; GEMDOS
	addq.l	#8,sp                           ; drop the arguments

;------------------------------------------------------------------------------
; Runtime: puts back the byte overwritten by the NUL, a0 = the channel's table entry; a negative
; GEMDOS result is raised as the error, otherwise the handle is stored in the table.
;------------------------------------------------------------------------------
rt_open_store_handle:
	movea.l	d3,a2                           ; put back the byte after the name
	move.b	d5,(a2)
	movea.l	d6,a0                           ; a0 = the channel's table entry
	tst.w	d0                              ; GEMDOS error?

rt_open_check_result:
	bpl.s	.handle                         ; handle positive?
	jmp	rn_error_entry(a6)              ; raise it
.handle:
	move.b	d0,(a0)                         ; store the handle
	rts

;------------------------------------------------------------------------------
; Runtime: OPEN "U": Fopen read/write.
;------------------------------------------------------------------------------
rt_open_update:
	move.w	#$2,-(sp)                       ; read/write
	moveq	#61,d0                          ; GEMDOS $3d Fopen
	bra.s	rt_open_gemdos_call

;------------------------------------------------------------------------------
; Runtime: OPEN "A": Fopen read/write, then Fseek to the end of the file.
;------------------------------------------------------------------------------
rt_open_append:
	moveq	#61,d0                          ; GEMDOS $3d Fopen
	move.w	#$2,-(sp)
	pea	(a1)
	move.w	d0,-(sp)
	trap	#1                              ; GEMDOS
	addq.l	#8,sp
	bsr.s	rt_open_store_handle
	move.w	#$2,-(sp)                       ; from the end
	move.w	d0,-(sp)                        ; the handle
	pea	$0.w                            ; offset 0
	move.w	#$42,-(sp)                      ; GEMDOS $42 Fseek
	trap	#1                              ; Fseek
	adda.w	#$a,sp                          ; drop the arguments
	bra.s	rt_open_check_result            ; error or position

;------------------------------------------------------------------------------
; Runtime: OPEN "R": Fopen read/write, Fcreate if that fails, then takes a free random-file
; buffer number 1..10 (the bytes at $b8c(a4) = table + $390 hold those in use; none free:
; error 53) and sets up its record at $b70(a4) + number*128: record length, 0, 0.
;------------------------------------------------------------------------------
rt_open_random:
	pea	(a0)                            ; keep the table entry
	move.l	a1,d4                           ; d4 = name
	move.w	#$2,-(sp)                       ; read/write
	pea	(a1)                            ; name
	move.w	#$3d,-(sp)                      ; GEMDOS $3d Fopen
	trap	#1                              ; Fopen
	addq.l	#8,sp                           ; drop the arguments
	tst.w	d0                              ; opened?
	bpl.s	.opened                         ; opened
	clr.w	-(sp)                           ; attribute 0
	move.l	d4,-(sp)                        ; name
	move.w	#$3c,-(sp)                      ; GEMDOS $3c Fcreate
	trap	#1                              ; Fcreate
	addq.l	#8,sp                           ; drop the arguments
.opened:
	bsr.s	rt_open_store_handle            ; store the handle (error raised)
	movea.l	(sp)+,a0                        ; a0 = channel table entry
	adda.w	#$390,a0                        ; the channel's random buffer number byte
	move.w	$30e(a4),d0                     ; d0 = record length
	lea	$b7c(a4),a1                     ; random buffer numbers of all channels
	moveq	#99,d1                          ; 100 channels
	moveq	#1,d3                           ; d3 = bit mask of numbers in use (bit 0 always)
.used:
	move.b	(a1)+,d2                        ; next buffer number
	beq.s	.next_used                      ; none
	bset	d2,d3                           ; mark it in use
.next_used:
	dbra	d1,.used
	moveq	#10,d1                          ; look for a free number 10..1
.free_buffer:
	btst	d1,d3                           ; number d1 in use?
	dbeq	d1,.free_buffer                 ; no: free (beq ends the search)
	beq.s	.buffer                         ; found one
	moveq	#53,d0                          ; none free: error 53
.raise:
	jmp	rn_error_entry(a6)              ; raise error d0
	moveq	#48,d0                          ; error 48 Record length wrong (no branch here leads to it)
	bra.s	.raise                          ; raise error d0
.buffer:
	move.b	d1,(a0)                         ; the channel's buffer number
	asl.w	#7,d1                           ; * 128
	lea	$b60(a4),a1                     ; random buffer records
	adda.w	d1,a1                           ; a1 = the buffer's record
	move.w	d0,(a1)+                        ; record length
	clr.w	(a1)+                           ; two zero words
	clr.w	(a1)+
	rts

;------------------------------------------------------------------------------
; Runtime: CLOSE #d0 ($99(a6)): clears the channel's table entry and random buffer number
; and Fcloses a file handle (devices are not closed).
;------------------------------------------------------------------------------
rt_close:
	cmpi.w	#$64,d0                         ; channel number below 100?
	bcc.s	.close_done
	lea	$7ec(a4),a0                     ; channel table
	adda.w	d0,a0                           ; + channel number
	move.b	(a0),d1                         ; d1 = handle
	beq.s	.close_done                     ; not open: nothing to do
	clr.b	(a0)                            ; free the entry
	clr.b	$390(a0)                        ; and its random buffer number
	ext.w	d1                              ; handle to a word
	bmi.s	.close_done                     ; device: no Fclose
	move.w	d1,-(sp)                        ; handle
	move.w	#$3e,-(sp)                      ; GEMDOS $3e Fclose
	trap	#1                              ; Fclose
	addq.l	#4,sp                           ; drop the arguments
	tst.w	d0                              ; error?
	bpl.s	.close_done                     ; no
	jmp	rn_error_entry(a6)              ; raise the GEMDOS error
.close_done:
	rts

;------------------------------------------------------------------------------
; Runtime: CLOSE without a number: closes channels 99 down to 0.
;------------------------------------------------------------------------------
rt_close_all:
	moveq	#99,d7                          ; all channels 99..0
.loop:
	move.w	d7,d0                           ; d0 = channel
	jsr	rn_close(a6)                    ; CLOSE #d0 (0732c)
	dbra	d7,.loop                        ; next channel
	rts

;------------------------------------------------------------------------------
; Runtime: LOC(#d0): a relative Fseek by 0, so d0 = the position. 7354 is RELSEEK #d1,d0
; (mode 1); 7358 SEEK #d1,d0 (mode 0, a negative position seeks from the end, mode 2).
; Device channels are skipped; a GEMDOS error is raised.
;------------------------------------------------------------------------------
rt_loc:
	moveq	#0,d1                           ; LOC: offset 0
	exg	d0,d1                           ; d1 = channel, d0 = offset

rt_relseek:
	moveq	#1,d2                           ; RELSEEK: mode 1 (from the current position)
	bra.s	rt_seek_mode_d2

rt_seek:
	moveq	#0,d2                           ; SEEK: mode 0 (from the start)

;------------------------------------------------------------------------------
; Runtime: the Fseek shared by LOC, RELSEEK and SEEK: d1 = channel, d0 = offset, d2 = mode.
; A negative offset in mode 0 becomes mode 2 (from the end). Exit d0 = new position.
;------------------------------------------------------------------------------
rt_seek_mode_d2:
	cmpi.w	#$64,d1                         ; channel below 100?
	bcc.s	.seek_done
	lea	$7ec(a4),a0                     ; channel table
	move.b	0(a0,d1.w),d1                   ; d1 = handle
	ext.w	d1                              ; handle to a word
	bmi.s	.seek_done                      ; device or not open: nothing
	tst.l	d0
	bpl.s	.call                           ; positive offset
	tst.w	d2
	bne.s	.call
	moveq	#2,d2                           ; SEEK to a negative position: from the end
.call:
	move.w	d2,-(sp)                        ; mode
	move.w	d1,-(sp)                        ; handle
	move.l	d0,-(sp)                        ; offset
	move.w	#$42,-(sp)                      ; GEMDOS $42 Fseek
	trap	#1                              ; Fseek
	adda.w	#$a,sp                          ; drop the arguments
	tst.l	d0                              ; error?
	bpl.s	.seek_done
	jmp	rn_error_entry(a6)              ; raise the GEMDOS error
.seek_done:
	rts

;------------------------------------------------------------------------------
; Runtime: CHDRIVE d0: Dsetdrv(d0 - 1) when d0 > 0.
;------------------------------------------------------------------------------
rt_chdrive:
	subq.w	#1,d0                           ; drive 1 = A:
	bmi.s	.drive_done                     ; 0: no change
	move.w	d0,-(sp)                        ; drive number 0 = A:
	move.w	#$e,-(sp)                       ; GEMDOS $0e Dsetdrv
	trap	#1                              ; Dsetdrv
	addq.l	#4,sp                           ; drop the arguments
.drive_done:
	rts

;------------------------------------------------------------------------------
; Runtime: DFREE(d0): Dfree into the buffer at $30e(a4); d0 = free clusters * bytes per sector
; * sectors per cluster (word multiplies).
;------------------------------------------------------------------------------
rt_dfree:
	move.w	d0,-(sp)                        ; drive
	pea	$30e(a4)                        ; DISKINFO buffer
	move.w	#$36,-(sp)                      ; GEMDOS $36 Dfree
	trap	#1                              ; Dfree
	addq.l	#8,sp                           ; drop the arguments
	move.w	$318(a4),d0                     ; bytes per sector
	mulu.w	$31c(a4),d0                     ; * sectors per cluster
	mulu.w	$310(a4),d0                     ; * free clusters
	rts

;------------------------------------------------------------------------------
; Runtime: FILES [path$] [TO name$] and DIR [path$] [TO name$]. 73bc/73c0/73c4 are FILES
; (attribute $17, long listing), 73ca/73ce/73d2 DIR (attribute 0); the entries take neither,
; the path only, or both descriptors (a0 path, a1 TO file; $ad2(a4) stands for the missing
; ones). The path is copied to $94(a4) ("*.*" added for an empty path or a drive only),
; output goes to the screen or a temporary channel opened with "O" ($18a(a6)); Fsfirst/Fsnext
; with the DTA at basepage+$80 print one line per entry: the name (FILES: '*' before a folder,
; then size, time and date). Fsfirst's end codes -33 and -49 end the list quietly.
;------------------------------------------------------------------------------
rt_files:
	lea	$ad2(a4),a0                     ; FILES: no path, no TO

rt_files_path:
	lea	$ad2(a4),a1                     ; FILES path$
	exg	a1,a0                           ; FILES path$ TO name$

rt_files_path_to:
	moveq	#23,d0                          ; attribute $17: folders, hidden, system
	bra.s	rt_dir_files_list

rt_dir:
	lea	$ad2(a4),a0                     ; DIR: no path, no TO

rt_dir_path:
	lea	$ad2(a4),a1                     ; DIR path$
	exg	a1,a0                           ; DIR path$ TO name$

rt_dir_path_to:
	moveq	#0,d0                           ; attribute 0

;------------------------------------------------------------------------------
; Runtime: the directory listing shared by FILES and DIR. (sp) word = attribute (0 = DIR,
; $17 = FILES), a0 = path descriptor, a1 = TO file descriptor (the empty string at $ae2(a4)
; when not given). See the header at 73bc.
;------------------------------------------------------------------------------
rt_dir_files_list:
	move.w	d0,-(sp)                        ; attribute, also the FILES flag
	exg	a1,a0
	move.l	a1,d6                           ; d6 = the TO descriptor
	jsr	rn_string_text_len_212(a6)      ; the path: a1 = text, d0 = length
	lea	$94(a4),a0                      ; the search path buffer
	cmpi.w	#$100,d0                        ; at most 255 characters
	bcs.s	.length
	move.w	#$ff,d0                         ; longer: cut to 255
.length:
	tst.w	d0
	beq.s	.wildcard                       ; empty: "*.*"
	cmpi.w	#$2,d0
	bne.s	.copy_next                      ; 2 characters: maybe a drive
	cmpi.b	#$3a,1(a1)                      ; drive only ("A:")?
	bne.s	.copy_next
	move.w	(a1),(a0)+                      ; copy "A:"
.wildcard:
	move.l	#$2a2e2a00,(a0)+                ; "*.*",0
	bra.s	.output
.copy:
	move.b	(a1)+,(a0)+                     ; copy the path
.copy_next:
	dbra	d0,.copy
	clr.b	(a0)+                           ; NUL
.output:
	movea.l	d6,a0                           ; a0 = TO descriptor
	tst.w	4(a0)                           ; TO name given?
	bne.s	.to_file
	jsr	rn_string_text_len_212(a6)      ; free the empty string
	move.w	#$fffc,$228(a4)                 ; output to the screen
	bra.s	.first
.to_file:
	moveq	#79,d1                          ; "O"
	jsr	rn_open_temp_channel(a6)        ; open the TO file as the temporary channel
.first:
	pea	$94(a4)                         ; Fsfirst: path
	move.w	#$4e,-(sp)                      ; GEMDOS $4e Fsfirst (called after the Fsetdta)
	lea	rn_program_start(a6),a0         ; routine 1 = the program start
	pea	-$80(a0)                        ; basepage + $80: the default DTA
	move.w	#$1a,-(sp)                      ; GEMDOS $1a Fsetdta
	trap	#1                              ; Fsetdta
	addq.l	#6,sp                           ; drop the Fsetdta arguments
	trap	#1                              ; GEMDOS, Fsfirst
	addq.l	#6,sp                           ; drop the function number, the path and attribute stay
.entry:
	tst.l	d0                              ; found one?
	bpl.s	.format
	cmpi.w	#$ffdf,d0                       ; -33 file not found
	beq.s	.end
	cmpi.w	#$ffcf,d0                       ; -49 no more files
	beq.s	.end
	move.w	d0,-(sp)
	jsr	rn_close_temp_channel_if_open(a6) ; close the temporary channel (071ae)
	move.w	(sp)+,d0                        ; d0 = the error
	jmp	rn_error_entry(a6)              ; raise the GEMDOS error
.end:
	addq.l	#2,sp                           ; drop the attribute
	jmp	rn_close_temp_channel_if_open(a6) ; close the temporary channel and return
.format:
	lea	$94(a4),a0                      ; build the line here
	lea	rn_program_start(a6),a2         ; a2 = the DTA
	suba.w	#$80,a2                         ; basepage + $80
	lea	$1e(a2),a1                      ; a1 = file name in the DTA
	tst.w	(sp)                            ; DIR: the name only
	beq.s	.name
	move.b	#$20,(a0)+                      ; FILES: a space before the name
	btst	#$4,$15(a2)                     ; folder attribute?
	beq.s	.name
	move.b	#$2a,-$1(a0)                    ; '*' marks a folder
.name:
	move.b	(a1)+,(a0)+                     ; copy the name
	bne.s	.name
	subq.l	#1,a0                           ; back over the NUL
	tst.w	(sp)                            ; FILES or DIR?
	beq.s	.line_end                       ; DIR: end of line
	moveq	#15,d0                          ; 16 spaces
.pad:
	move.b	#$20,(a0)+
	dbra	d0,.pad
	lea	$a3(a4),a0                      ; size column
	move.l	$1a(a2),d0                      ; file size
	bsr.s	rt_dir_size_digits              ; 8 digits
	tas	d1                              ; any digit written?
	bmi.s	.date_time
	move.b	#$30,-$1(a0)                    ; size 0 shows as '0'
.date_time:
	move.b	#$20,(a0)+
	move.w	$16(a2),d0                      ; DTA time word
	jsr	rn_write_time_word(a6)          ; write it as hh:mm:ss (08a14)
	movea.l	a1,a0                           ; a0 = end of the time text
	move.b	#$20,(a0)+
	move.w	$18(a2),d0                      ; DTA date word
	jsr	rn_write_date_word(a6)          ; write it as dd.mm.yy (08352)
	movea.l	a1,a0                           ; a0 = end of the date text
.line_end:
	move.b	#$d,(a0)+                       ; CR LF
	move.b	#$a,(a0)+
	move.l	a0,d0                           ; length of the line
	lea	$94(a4),a1
	sub.l	a1,d0                           ; a1 = the line
	jsr	rn_print_text(a6)               ; print it (06d6a)
	move.w	#$4f,-(sp)                      ; GEMDOS $4f Fsnext
	trap	#1                              ; Fsnext
	addq.l	#2,sp                           ; drop the function number
	bra.w	.entry                          ; next entry

;------------------------------------------------------------------------------
; Runtime: writes the file size d0 as 8 right-aligned digits at a0 (leading spaces):
; divu 10000 splits it into two groups of 4.
;------------------------------------------------------------------------------
rt_dir_size_digits:
	divu.w	#$2710,d0                       ; first 4 digits
	move.l	d0,-(sp)                        ; keep the remainder (last 4 digits)
	moveq	#0,d1                           ; no digit yet
	bsr.s	rt_dir_three_digits             ; first group: 3 of its 4 digits (the top digit is dropped)
	move.l	(sp)+,d0
	swap	d0                              ; last 4 digits
	ext.l	d0                              ; d0 = 0..9999
	divu.w	#$3e8,d0                        ; thousands
	bsr.s	rt_dir_digit                    ; thousands digit

;------------------------------------------------------------------------------
; Runtime: writes the last 3 of 4 digits of d0 (0..9999 after the thousands) at a0.
;------------------------------------------------------------------------------
rt_dir_three_digits:
	ext.l	d0                              ; d0 = 0..999 after the thousands
	divu.w	#$64,d0                         ; hundreds
	bsr.s	rt_dir_digit
	ext.l	d0                              ; d0 = 0..99
	divu.w	#$a,d0                          ; tens
	bsr.s	rt_dir_digit
	nop                                     ; then the units

;------------------------------------------------------------------------------
; Runtime: writes the digit in d0.w at a0, a space while d1 shows no digit yet; the remainder
; in the high word becomes d0.
;------------------------------------------------------------------------------
rt_dir_digit:
	tst.b	d1                              ; a digit already written?
	bne.s	.digit
	tst.b	d0                              ; leading zero: space
	beq.s	.store
.digit:
	ori.b	#$30,d0                         ; digit character
	st	d1                              ; digits from now on
.store:
	ori.b	#$20,d0                         ; $20 = space; '0'..'9' unchanged
	move.b	d0,(a0)+
	swap	d0                              ; remainder for the next digit
	ext.l	d0
	rts

;------------------------------------------------------------------------------
; Runtime: EXIST(name$): Fopen read; when it opens, closes it and d2 = -1, otherwise d2 = 0.
;------------------------------------------------------------------------------
rt_exist:
	jsr	rn_string_text_len_212(a6)      ; a1 = name, d0 = length
	tst.w	d0
	beq.s	.missing                        ; empty name: false
	lea	0(a1,d0.w),a0                   ; end of the name
	move.b	(a0),d5                         ; keep the byte after the name
	move.l	a0,d6                           ; d6 = end of the name
	clr.b	(a0)                            ; NUL-terminate it
	clr.w	-(sp)                           ; read only
	pea	(a1)                            ; name
	move.w	#$3d,-(sp)                      ; GEMDOS $3d Fopen
	trap	#1                              ; Fopen
	addq.l	#8,sp                           ; drop the arguments
	movea.l	d6,a0                           ; a0 = end of the name
	move.b	d5,(a0)                         ; put the byte back
	tst.w	d0
	bmi.s	.missing                        ; not there: false
	move.w	d0,-(sp)                        ; handle
	move.w	#$3e,-(sp)                      ; GEMDOS $3e Fclose
	trap	#1                              ; Fclose
	addq.l	#4,sp                           ; drop the arguments
	moveq	#-1,d2                          ; TRUE
	rts
.missing:
	moveq	#0,d2                           ; FALSE
	rts

;------------------------------------------------------------------------------
; Runtime: BLOAD name$ (no address: the last BSAVE address, dat_bsave_address); 7572 BLOAD
; name$,d0. Opens a temporary channel "I", Freads up to $ffffff bytes to the address (mouse
; hidden first), closes it; a GEMDOS error is raised after closing.
;------------------------------------------------------------------------------
rt_bload_last_address:
	move.l	dat_bsave_address(pc),d0        ; no address: the last BSAVE address

rt_bload:
	move.l	d0,-(sp)                        ; keep the address
	moveq	#73,d1                          ; "I"
	movea.l	a1,a0                           ; a0 = name descriptor
	jsr	rn_open_temp_channel(a6)        ; open the temporary channel (0717e)
	move.w	$228(a4),d6                     ; d6 = handle
	bmi.s	rt_close_temp_channel           ; device: nothing to read
	move.l	#$ffffff,-(sp)                  ; read up to 16 MB
	move.w	d6,-(sp)
	move.w	#$3f,-(sp)                      ; GEMDOS $3f Fread
	jsr	rn_mouse_hide(a6)               ; hide the mouse once (09d32)
	trap	#1                              ; GEMDOS
	adda.w	#$c,sp                          ; drop the arguments
	tst.l	d0                              ; error?
	bpl.s	rt_close_temp_channel           ; no: close and return
	move.w	d0,-(sp)                        ; keep the error
	bsr.s	rt_close_temp_channel           ; close the temporary channel
	move.w	(sp),d0                         ; d0 = the error
	jmp	rn_error_entry(a6)              ; raise the error

;------------------------------------------------------------------------------
; Runtime: closes the temporary channel ($18b(a6)).
;------------------------------------------------------------------------------
rt_close_temp_channel:
	jmp	rn_close_temp_channel_if_open(a6) ; close the temporary channel (071ae)

; Data: the address of the last BSAVE, used by BLOAD without an address.
dat_bsave_address:
	dc.w	$0000,$0000

;------------------------------------------------------------------------------
; Runtime: BSAVE name$,d1,d0: opens a temporary channel "O", keeps the address in
; dat_bsave_address, writes d0 bytes from it ($211(a6)) and closes the channel.
;------------------------------------------------------------------------------
rt_bsave:
	movem.l	d0-d1,-(sp)                     ; keep length and address
	moveq	#79,d1                          ; "O"
	movea.l	a1,a0                           ; a0 = name descriptor
	jsr	rn_open_temp_channel(a6)        ; open the temporary channel (0717e)
	movem.l	(sp)+,d0/a1                     ; d0 = length, a1 = address
	lea	dat_bsave_address(pc),a0
	move.l	a1,(a0)                         ; kept for BLOAD without an address
	jsr	rn_print_text(a6)               ; write them (06d6a)
	jmp	rn_close_temp_channel_if_open(a6) ; close the temporary channel

;------------------------------------------------------------------------------
; Runtime: plays the Dosound list of the sound channel in d0 as it stands.
;------------------------------------------------------------------------------
rt_sound_play_channel:
	bsr.s	rt_sound_channel_list           ; a1 = list of channel d0

;------------------------------------------------------------------------------
; Runtime: Dosound of the list at a1.
;------------------------------------------------------------------------------
rt_sound_dosound:
	pea	(a1)                            ; the list
	bra.w	rt_dosound_list                 ; XBIOS Dosound

;------------------------------------------------------------------------------
; Runtime: the Dosound list of the channel in a0 (low word): a1 = dat_sound_list_a/b/c for
; channel 1/2/3 (0 counts as 1); d0 keeps a0, its high word the volume.
;------------------------------------------------------------------------------
rt_sound_channel_a0:
	move.l	a0,d0                           ; d0 = a0: channel, volume in the high word

rt_sound_channel_list:
	andi.w	#$3,d0                          ; channel 1..3
	beq.s	.index                          ; 0 counts as 1
	subq.w	#1,d0                           ; 1..3 to 0..2
.index:
	asl.w	#4,d0                           ; 16 bytes per list
	lea	dat_sound_list_a(pc,d0.w),a1    ; a1 = the channel's list
	rts

;------------------------------------------------------------------------------
; Data: Dosound list of sound channel A (16 bytes): reg 1, reg 0 (tone period), reg 8
; (volume), reg 7 = $fe, end; byte 5 = the volume, decoded in part as instructions.
;------------------------------------------------------------------------------
dat_sound_list_a:
	btst	d0,d0                           ; bytes 01 00 00 00: reg 1, reg 0 (tone period A)
	dc.w	$0000
dat_sound_list_a_vol:
	dc.w	$0800,$07fe,$ff00,$0000,$0000,$0000 ; 08 vol (reg 8), 07 fe (mixer), ff 00 (end)

;------------------------------------------------------------------------------
; Data: Dosound list of sound channel B: reg 3, reg 2, reg 9, reg 7 = $fd, end.
;------------------------------------------------------------------------------
dat_sound_list_b:
	btst	d1,d0                           ; bytes 03 00 02 00: reg 3, reg 2 (tone period B)
	dc.w	$0200

dat_sound_list_b_vol:
	btst	d4,d0                           ; 09 vol (reg 9), 07 fd, ff 00
	dc.w	$07fd,$ff00,$0000,$0000,$0000

;------------------------------------------------------------------------------
; Data: Dosound list of sound channel C: reg 5, reg 4, reg 10, reg 7 = $fb, end.
;------------------------------------------------------------------------------
dat_sound_list_c:
	btst	d2,d0                           ; bytes 05 00 04 00: reg 5, reg 4 (tone period C)
	dc.w	$0400
dat_sound_list_c_vol:
	dc.w	$0a00,$07fb,$ff00,$0000,$0000,$0000 ; 0a vol (reg 10), 07 fb, ff 00

;------------------------------------------------------------------------------
; Runtime: SOUND channel,volume (a0 = channel, volume in its high word): sets the volume byte
; and plays the list.
;------------------------------------------------------------------------------
rt_sound_volume:
	move.l	a0,d0                           ; a0 = channel and volume
	bsr.s	rt_sound_channel_list           ; a1 = the channel's list
	swap	d0                              ; volume
	move.b	d0,5(a1)                        ; volume register value
	bra.s	rt_sound_dosound

;------------------------------------------------------------------------------
; Runtime: SOUND with a tone period (routine $191): d0 = period, a0 = channel with the
; volume in its high word. 7626 writes volume (d0 high word) and period (d1) into the
; channel's list at a1 and plays it.
;------------------------------------------------------------------------------
rt_sound_period:
	move.l	d0,d1                           ; d1 = tone period
	bsr.s	rt_sound_channel_a0             ; a1 = the channel's list

rt_sound_set_period:
	swap	d0                              ; volume
	move.b	d0,5(a1)                        ; volume register value
	movep.w	d1,1(a1)                        ; period high and low bytes into the list
	bra.s	rt_sound_dosound                ; play it

;------------------------------------------------------------------------------
; Runtime: SOUND with a note (routines $18f/$190): a0 = channel with the volume in its high
; word, d1 = note. 7638 takes the octave in d0 and keeps it at $a(a1) of the channel's list;
; 7632 uses the octave kept there. The period is dat_tone_periods[note] >> octave.
;------------------------------------------------------------------------------
rt_sound_note_last_octave:
	bsr.s	rt_sound_channel_a0             ; the channel's list
	move.w	$a(a1),d0                       ; octave word kept at $a(a1)

rt_sound_note_octave:
	move.w	d0,d2                           ; d2 = octave
	bsr.s	rt_sound_channel_a0             ; the same list again
	move.w	d2,$a(a1)                       ; keep it for later notes
	ext.w	d1                              ; note number
	add.w	d1,d1                           ; word index
	move.w	dat_tone_periods(pc,d1.w),d1    ; period of the note
	lsr.w	d2,d1                           ; shifted by the octave
	bra.s	rt_sound_set_period             ; write and play

; Data: 26 tone periods ($1fa4, $1ddc, $1c30 ...) indexed by note, decoded in part as
; instructions up to 7680.
dat_tone_periods:
	dc.w	$1fa4,$1ddc,$1c30               ; tone periods: 26 words up to 7680
	move.b	(a2)+,(a5)                      ; tone period words, not code
	move.b	(a4)+,-(a4)                     ; tone period words, not code
	dc.w	$17b4,$165e
	move.b	(a6)+,-(a2)                     ; tone period words, not code
	move.b	$12d0(a6),$11c210c2             ; tone period words, not code
	bset	d7,(a2)                         ; tone period words, not code
	dc.w	$0eee,$0e18
	movep.l	$c8e(a5),d6                     ; tone period words, not code
	bset	d5,(a2)+                        ; tone period words, not code
	btst	d5,$a8f(sp)                     ; tone period words, not code
	dc.w	$09f7
	bchg	d4,$8e1(a0)                     ; tone period words, not code
	dc.w	$0861
	bset	d3,$777(a1)                     ; tone period words, last of them

;------------------------------------------------------------------------------
; Runtime: WAVE enable bits: d0.b = channels on (inverted into the mixer register 7), the high
; byte the noise period (register 6), written into dat_wave_list.
;------------------------------------------------------------------------------
rt_wave_enable:
	lea	dat_wave_list(pc),a0            ; the WAVE list
	not.b	d0                              ; mixer bits are active low
	movep.w	d0,$13(a0)                      ; noise period (reg 6) and mixer (reg 7) values
	rts

;------------------------------------------------------------------------------
; Runtime: WAVE envelope bits: sets bit 4 (envelope) of the volume byte of channels A/B/C for
; bits 0/1/2 of d0, clears it for the others.
;------------------------------------------------------------------------------
rt_wave_envelope:
	lea	dat_sound_list_a(pc),a0         ; channel A list
	moveq	#4,d1                           ; bit 4 = envelope on
	bset	d1,5(a0)                        ; set for A, B, C
	bset	d1,$15(a0)
	bset	d1,$25(a0)
	lsr.b	#1,d0                           ; bit 0: channel A
	bcs.s	.channel_b
	bclr	d1,5(a0)                        ; off for A
.channel_b:
	lsr.b	#1,d0                           ; bit 1: channel B
	bcs.s	.channel_c
	bclr	d1,$15(a0)
.channel_c:
	lsr.b	#1,d0                           ; bit 2: channel C
	bcs.s	.done
	bclr	d1,$25(a0)
.done:
	rts

;------------------------------------------------------------------------------
; Runtime: WAVE envelope shape d0 into register 13 of the envelope list.
;------------------------------------------------------------------------------
rt_wave_shape:
	lea	dat_wave_envelope+1(pc),a0      ; envelope shape value (reg 13)
	move.b	d0,(a0)                         ; envelope shape
	rts

;------------------------------------------------------------------------------
; Runtime: WAVE envelope period d0 (registers 12 and 11), then 76c8 builds dat_wave_list from
; the three channel lists (6 bytes each) and plays it.
;------------------------------------------------------------------------------
rt_wave_period:
	lea	dat_wave_list(pc),a0            ; the WAVE list
	movep.w	d0,$19(a0)                      ; envelope period (reg 12, reg 11)

rt_wave_play:
	lea	dat_wave_list(pc),a0            ; build the WAVE list
	pea	(a0)                            ; pushed for Dosound
	move.l	dat_sound_list_a(pc),(a0)+      ; channel A: tone period and volume
	move.w	dat_sound_list_a_vol(pc),(a0)+
	move.l	dat_sound_list_b(pc),(a0)+      ; channel B
	move.w	dat_sound_list_b_vol(pc),(a0)+
	move.l	dat_sound_list_c(pc),(a0)+      ; channel C
	move.w	dat_sound_list_c_vol(pc),(a0)+

;------------------------------------------------------------------------------
; Runtime: XBIOS Dosound of the list pushed by the caller.
;------------------------------------------------------------------------------
rt_dosound_list:
	move.w	#$20,-(sp)                      ; XBIOS 32 Dosound
	trap	#14                             ; Dosound
	addq.l	#6,sp                           ; drop the arguments
	rts

; Data: the WAVE Dosound list: 18 bytes copied from the channel lists, then reg 6 (noise),
; reg 7 (mixer), and dat_wave_envelope.
dat_wave_list:
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000 ; 18 bytes filled from the channel lists
	dc.w	$0000,$0600,$07ff               ; 18 bytes filled from the channel lists

;------------------------------------------------------------------------------
; Data: the envelope part of the WAVE list: reg 13 shape, reg 12, reg 11 period, end ($ff00);
; decoded in part as instructions.
;------------------------------------------------------------------------------
dat_wave_envelope:
	btst	d6,d0                           ; 0d 00 envelope shape (reg 13)
	dc.w	$0c00                           ; 0c 00 envelope period high (reg 12)
	btst	d5,d0                           ; 0b 00 envelope period low (reg 11)
	dc.w	$ff00                           ; ff 00 end of the list

;------------------------------------------------------------------------------
; Runtime: BMOVE d1,a1,d0: copies d0 bytes from address d1 to a1 (mouse hidden first), down
; from the end when the areas overlap that way; by bytes when any of the addresses or the
; count is odd, otherwise by words (continues past this range's first part).
;------------------------------------------------------------------------------
rt_bmove:
	jsr	rn_mouse_hide(a6)               ; hide the mouse once (09d32)
	movea.l	d1,a0                           ; a0 = source
	move.l	a1,d2                           ; a1 = destination
	or.l	d2,d1                           ; odd address or count: bit 0
	or.l	d0,d1
	exg	a1,a0                           ; a0 = source, a1 = destination
	tst.l	d0                              ; nothing to copy
	ble.s	.done
	lsr.b	#1,d1                           ; anything odd: bytes
	bcc.s	rt_bmove_words
	cmpa.l	a1,a0                           ; source above: copy upwards
	bhi.s	.up_bytes_next                  ; yes: bytes upwards
	adda.l	d0,a0                           ; copy downwards from the end
	adda.l	d0,a1
	bra.s	.down_bytes_next
.down_bytes:
	move.b	-(a0),-(a1)                     ; byte down
.down_bytes_next:
	dbra	d0,.down_bytes                  ; count low word
	subi.l	#$10000,d0                      ; and the high word
	bpl.s	.down_bytes
.done:
	rts
.up_bytes:
	move.b	(a0)+,(a1)+                     ; byte up
.up_bytes_next:
	dbra	d0,.up_bytes
	subi.l	#$10000,d0                      ; and the high word
	bpl.s	.up_bytes
	rts

;------------------------------------------------------------------------------
; Runtime: the word copy of BMOVE: a0 = source, a1 = destination, d0 = count, all even.
; Copies downwards from the end ($eb(a6) = 094d4) when the source is not above the destination,
; otherwise upwards ($ec(a6) = 0955a). Also moves the string area for RESERVE.
;------------------------------------------------------------------------------
rt_bmove_words:
	cmpa.l	a1,a0                           ; even: word copy
	bhi.s	.up_words                       ; source above: copy upwards
	adda.l	d0,a0                           ; copy downwards from the end
	adda.l	d0,a1
	jmp	rn_copy_bytes_backward(a6)      ; word copy downwards (094e0)
.up_words:
	jmp	rn_copy_bytes_forward(a6)       ; word copy upwards (09566)

;------------------------------------------------------------------------------
; Runtime: RESERVE d0: changes the program's memory so that d0 bytes are free. Takes the free
; memory ($58(a6) = 0584a, FRE), rounds the change to 256 bytes, Mfrees the block at $68(a4)
; and Mallocs it again with the new size $6c(a4) (it must come back at the same address), then
; moves the string area ($60(a4)..$64(a4)) up by the change and adds it to every string's
; descriptor address through the back pointer after each string. A failed Malloc takes the old
; size again; both failures raise error 61 (RESERVE error).
;------------------------------------------------------------------------------
rt_reserve:
	move.l	d0,-(sp)                        ; the size wanted free
	jsr	rn_fre(a6)                      ; d0 = free memory (FRE, 0584a)
	move.l	d0,d7                           ; d7 = free memory now
	move.l	(sp)+,d6                        ; d6 = free memory wanted
	move.l	d6,d5
	sub.l	d7,d5                           ; d5 = the change
	addi.l	#$ff,d5                         ; rounded up to 256
	sf	d5                              ; low byte cleared
	move.l	$6c(a4),d4                      ; new size of the memory block
	add.l	d5,d4
	bmi.s	.error                          ; below 0: error
	move.l	$68(a4),-(sp)                   ; the block
	move.w	#$49,-(sp)                      ; GEMDOS $49 Mfree
	trap	#1                              ; Mfree
	addq.l	#6,sp                           ; drop the arguments
	move.l	d4,-(sp)                        ; the new size
	move.w	#$48,-(sp)                      ; GEMDOS $48 Malloc
	trap	#1                              ; Malloc
	addq.l	#6,sp                           ; drop the arguments
	tst.l	d0                              ; address 0?
	beq.s	.failed                         ; failed
	movea.l	$60(a4),a0                      ; a0 = bottom of the string area
	movea.l	$64(a4),a1                      ; a1 = top of the string area
	add.l	d5,$64(a4)                      ; move both up
	add.l	d5,$60(a4)
	move.l	d4,$6c(a4)                      ; new size
	movea.l	a1,a2                           ; a2 walks down from the top
	move.l	a3,d3                           ; keep a3
	bra.s	.next_string
.fix_descriptor:
	movea.l	-(a2),a3                        ; back pointer to the string's descriptor
	add.l	d5,(a3)+                        ; descriptor address + change
	moveq	#0,d0
	move.w	(a3),d0                         ; length, rounded to even
	addq.w	#1,d0
	andi.w	#$fffe,d0
	suba.l	d0,a2                           ; to the string before it
.next_string:
	cmpa.l	a0,a2                           ; still above the bottom?
	bhi.s	.fix_descriptor                 ; fix the next descriptor
	movea.l	d3,a3                           ; restore a3
	move.l	a1,d0                           ; bytes to move
	sub.l	a0,d0
	lea	0(a0,d5.l),a1                   ; destination
	bra.w	rt_bmove_words                  ; move the strings
.failed:
	move.l	$6c(a4),-(sp)                   ; take the old size again
	move.w	#$48,-(sp)
	trap	#1                              ; Malloc
	addq.l	#6,sp                           ; drop the arguments
.error:
	moveq	#61,d0                          ; error 61 RESERVE error
	jmp	rn_error_entry(a6)              ; raise error d0

; Data: the word $00b8 is not code (the RESERVE routine ends at the jmp before).
; 
; Runtime: EXEC mode,name$,cmd$,env$ (Pexec, routine $b7 at 77e6). Pops the return address
; (a2), two string descriptors (d5, d4) and the mode (d6); a0 is the third descriptor. The
; three strings are copied to $94(a4) as NUL-terminated C strings (at most 127 characters
; each, rt_exec_copy_string), the a0 one pushed first (environment), then d5 (command line),
; then d4 (name). d0 = the Pexec result; $11f(a6) (09d5e) is called before and after.
	dc.w	$00b8                           ; word $00b8, not code: EXEC starts at 77e6

rt_exec:
	movea.l	(sp)+,a2                        ; a2 = return address
	move.l	(sp)+,d5                        ; d5 = command line descriptor
	move.l	(sp)+,d4                        ; d4 = name descriptor
	move.w	(sp)+,d6                        ; d6 = Pexec mode
	pea	(a2)                            ; return address back
	lea	$94(a4),a2                      ; the C string buffer
	pea	(a2)                            ; environment pointer
	bsr.s	rt_exec_copy_string             ; copy the a0 string
	movea.l	d5,a0                           ; a0 = command line
	pea	(a2)                            ; command line pointer
	bsr.s	rt_exec_copy_string             ; copy it
	movea.l	d4,a0                           ; a0 = name
	pea	(a2)                            ; name pointer
	bsr.s	rt_exec_copy_string             ; copy it
	move.w	d6,-(sp)                        ; Pexec mode
	move.w	#$4b,-(sp)                      ; GEMDOS $4b Pexec
	jsr	rn_mouse_show(a6)               ; show the mouse (09d5e)
	trap	#1                              ; GEMDOS
	jsr	rn_mouse_show(a6)               ; show the mouse (09d5e)
	adda.w	#$10,sp                         ; drop the arguments
	rts

;------------------------------------------------------------------------------
; Runtime: copies the string at a0 to a2 as a C string, at most 127 characters, NUL after it.
;------------------------------------------------------------------------------
rt_exec_copy_string:
	jsr	rn_string_text_len_212(a6)      ; a1 = text, d0 = length
	cmpi.w	#$80,d0                         ; 128 characters or more?
	bcs.s	.copy_next                      ; no
	moveq	#126,d0                         ; at most 127 characters
.copy:
	move.b	(a1)+,(a2)+                     ; copy a character
.copy_next:
	dbra	d0,.copy
	clr.b	(a2)+                           ; NUL
	rts

;------------------------------------------------------------------------------
; Runtime: FIELD and record errors: 7830 error 54 (field string length changed), 7834 error
; 53 (too many fields), 7838 error 52 (fields larger than the record), 783c error 51 (only one
; FIELD per OPEN "R"), 7840 error 50 (not an "R" file), 7844 error 23, 7848 error 24.
;------------------------------------------------------------------------------
rt_field_error_length_changed:
	moveq	#54,d0                          ; error 54 field string length changed
	bra.s	rt_field_raise_error

rt_field_error_too_many:
	moveq	#53,d0                          ; error 53 too many fields (max. 19)
	bra.s	rt_field_raise_error

rt_field_error_too_long:
	moveq	#52,d0                          ; error 52 fields larger than record length
	bra.s	rt_field_raise_error

rt_field_error_second_field:
	moveq	#51,d0                          ; error 51 only one FIELD per OPEN "R"
	bra.s	rt_field_raise_error

rt_field_error_not_random:
	moveq	#50,d0                          ; error 50 not an "R" file
	bra.s	rt_field_raise_error

rt_field_error_number_wrong:
	moveq	#23,d0                          ; error 23 File # wrong
	bra.s	rt_field_raise_error

rt_field_error_not_open:
	moveq	#24,d0                          ; error 24 File not open

rt_field_raise_error:
	jmp	rn_error_entry(a6)              ; raise error d0

;------------------------------------------------------------------------------
; Runtime: FIELD #d0 start: the channel must be open (error 23/24) as a random file (buffer
; number at table + $390, else error 50 Not an "R"-File). a0 = the buffer record at $b70(a4) +
; number*128: +0 record length, +2 record number, +4 the field list ([width.w][descriptor.l]
; entries, a 0 word after the last), +$7c a non-zero end mark. $10e0(a4) = bytes left in the
; record, $10e2(a4) = where the next field entry goes; a second FIELD gives error 51.
;------------------------------------------------------------------------------
rt_field:
	cmpi.w	#$64,d0                         ; channel number below 100?
	bcc.s	rt_field_error_number_wrong     ; no: error 23
	lea	$7ec(a4),a0                     ; channel table
	adda.w	d0,a0                           ; + channel number
	move.b	(a0),d0                         ; handle
	beq.s	rt_field_error_not_open         ; not open: error 24
	move.b	$390(a0),d0                     ; random buffer number
	beq.s	rt_field_error_not_random       ; not a random file: error 50
	asl.w	#7,d0                           ; * 128
	lea	$b60(a4),a0                     ; buffer records
	adda.l	d0,a0                           ; a0 = the channel's buffer record
	move.w	#$1,$7c(a0)                     ; end mark of the field list
	move.w	(a0)+,$10e0(a4)                 ; bytes left = record length
	beq.s	rt_field_error_not_random       ; record length 0: error 50
	clr.w	(a0)+                           ; record number 0
	move.l	a0,$10e2(a4)                    ; where the next field goes
	tst.w	(a0)                            ; a field list already?
	bne.s	rt_field_error_second_field     ; yes: error 51
	rts

;------------------------------------------------------------------------------
; Runtime: one FIELD item: d1 = width, a0 = the string variable's descriptor. Adds the entry
; (reaching the end mark at +$7c gives error 53, more than 19 fields), takes the width off the
; bytes left (error 52 Fields larger than record length) and gives the variable a string of d1
; spaces ($45(a6) = 08472).
;------------------------------------------------------------------------------
rt_field_item:
	movea.l	$10e2(a4),a1                    ; next field entry
	tst.w	(a1)                            ; the end mark: more than 19 fields
	bne.s	rt_field_error_too_many
	move.w	d1,(a1)+                        ; width
	move.l	a0,(a1)+                        ; descriptor of the string variable
	move.l	a1,$10e2(a4)                    ; next entry
	clr.w	(a1)                            ; end of the list
	sub.w	d1,$10e0(a4)                    ; bytes left in the record
	bmi.s	rt_field_error_too_long         ; not enough left: error 52
	move.w	d1,d0                           ; a string of d1 bytes for the variable (0848a)
	jsr	rn_string_alloc_var(a6)         ; new string, a1 = its text, d0 = length (0848a)
	bra.s	.space_next
.space:
	move.b	#$20,(a1)+                      ; filled with spaces
.space_next:
	dbra	d0,.space
	rts

;------------------------------------------------------------------------------
; Runtime: GET #d0 / PUT #d0 (78ae / 78b6: the next record) and GET #d1,d0 / PUT #d1,d0
; (78be / 78c2: record d0, 1..65536, else error 55). d7 = the GEMDOS function: $3f Fread
; for GET, $40 Fwrite for PUT, kept in $10e0(a4). Selects the channel, finds its buffer record
; (error 50 when it is not random), Fseeks to (record - 1) * length and reads or writes each
; field string in turn; a field whose length was changed gives error 54. A short transfer gives
; error 26 (End of file) or 37 (Disk full), a seek past the end (-64) error 55.
;------------------------------------------------------------------------------
rt_get_next_record:
	move.w	d0,d1                           ; GET #d0: d1 = channel
	moveq	#-1,d0                          ; the next record
	moveq	#63,d7                          ; GEMDOS $3f Fread
	bra.s	rt_record_transfer

rt_put_next_record:
	move.w	d0,d1                           ; PUT #d0: d1 = channel
	moveq	#-1,d0                          ; no record number: the next one
	moveq	#64,d7                          ; GEMDOS $40 Fwrite
	bra.s	rt_record_transfer

rt_get_record:
	moveq	#63,d7                          ; GET with record number
	bra.s	rt_record_number_check

rt_put_record:
	moveq	#64,d7                          ; PUT with record number

;------------------------------------------------------------------------------
; Runtime: GET/PUT with a record number: d0 = record 1..65536 made 0-based; one above a word
; gives error 55. Falls into the transfer with d7 = Fread or Fwrite, d1 = channel.
;------------------------------------------------------------------------------
rt_record_number_check:
	subq.l	#1,d0                           ; 0-based
	moveq	#0,d2                           ; d2 = low word, zero-extended
	move.w	d0,d2
	cmp.l	d0,d2                           ; must fit a word
	bne.w	rt_record_error_number          ; no: error 55

;------------------------------------------------------------------------------
; Runtime: GET/PUT transfer: d0 = 0-based record (-1 = the next), d1 = channel, d7 = $3f
; Fread or $40 Fwrite. See the header at 78ae.
;------------------------------------------------------------------------------
rt_record_transfer:
	move.w	d7,$10e0(a4)                    ; Fread or Fwrite
	move.l	d0,-(sp)                        ; keep the record number
	move.w	d1,d0                           ; d0 = channel
	jsr	rn_select_channel(a6)           ; select channel d1 (07114)
	move.b	$390(a0),d1                     ; random buffer number
	beq.w	rt_field_error_not_random       ; not random: error 50
	asl.w	#7,d1                           ; * 128
	lea	$b60(a4),a0                     ; buffer records
	adda.w	d1,a0                           ; a0 = the channel's buffer record
	move.l	(sp)+,d7                        ; d7 = record number
	bpl.s	.record                         ; a record number given?
	move.w	2(a0),d7                        ; the current record
.record:
	move.w	d7,2(a0)                        ; record number
	addq.w	#1,2(a0)                        ; next record; 65536 wraps: error 55
	beq.s	rt_record_error_number
	mulu.w	(a0),d7                         ; * record length = file position
	pea	4(a0)                           ; the field list
	clr.w	-(sp)                           ; from the start
	move.w	$228(a4),-(sp)                  ; handle
	move.l	d7,-(sp)
	move.w	#$42,-(sp)                      ; GEMDOS $42 Fseek
	trap	#1                              ; Fseek
	adda.w	#$a,sp                          ; drop the arguments
	tst.l	d0                              ; error?
	bmi.s	rt_record_seek_error            ; yes: maybe past the end
	movea.l	(sp)+,a2                        ; a2 = the field list
.field:
	move.w	(a2)+,d7                        ; field width
	beq.s	rt_record_done                  ; end of the list
	movea.l	(a2)+,a0                        ; the descriptor
	movea.l	(a0)+,a1                        ; a1 = text
	cmp.w	(a0),d7                         ; the string's length must be the width
	bne.w	rt_field_error_length_changed   ; no: error 54
	move.l	a2,d6                           ; keep the list pointer
	pea	(a1)                            ; buffer
	ext.l	d7                              ; width to a long
	move.l	d7,-(sp)                        ; count
	move.w	$228(a4),-(sp)                  ; handle
	move.w	$10e0(a4),-(sp)                 ; Fread or Fwrite
	trap	#1                              ; GEMDOS
	adda.w	#$c,sp                          ; drop the arguments
	cmp.l	d0,d7                           ; all transferred?
	beq.s	.field
	tst.l	d0                              ; a GEMDOS error stays as it is
	bmi.s	rt_record_raise_error
	moveq	#26,d0                          ; error 26 End of file reached
	cmpi.w	#$3f,$10e0.w                    ; absolute $10e0.w, not $10e0(a4): this tests some other word
	beq.s	rt_record_raise_error
	moveq	#37,d0                          ; error 37 Disk full

;------------------------------------------------------------------------------
; Runtime: GET/PUT end: 7954 raises error d0, 7958 returns, 795a turns Fseek error -64
; (past the end) into 7960, error 55 (record number wrong).
;------------------------------------------------------------------------------
rt_record_raise_error:
	jmp	rn_error_entry(a6)              ; raise error d0

rt_record_done:
	rts                                     ; all fields done

rt_record_seek_error:
	cmpi.w	#$ffc0,d0                       ; -64: past the end of the file
	bne.s	rt_record_raise_error

rt_record_error_number:
	moveq	#55,d0                          ; error 55 record number wrong
	bra.s	rt_record_raise_error           ; raise it

;------------------------------------------------------------------------------
; Runtime: WRITE of a string: prints it between double quotes ($121(a6) = 06cd4).
;------------------------------------------------------------------------------
rt_write_string:
	pea	(a0)                            ; keep the descriptor
	bsr.s	rt_write_quote                  ; '"'
	movea.l	(sp)+,a0                        ; a0 = descriptor
	jsr	rn_print_string(a6)             ; the string (06cec)

;------------------------------------------------------------------------------
; Runtime: prints '"'.
;------------------------------------------------------------------------------
rt_write_quote:
	moveq	#34,d0                          ; '"'

;------------------------------------------------------------------------------
; Runtime: prints the character in d0 for WRITE ($123(a6) = 06d4a).
;------------------------------------------------------------------------------
rt_write_print_char:
	jmp	rn_print_char(a6)               ; print character d0 (06d62)

;------------------------------------------------------------------------------
; Runtime: prints ',' (between WRITE items).
;------------------------------------------------------------------------------
rt_write_comma:
	moveq	#44,d0                          ; ','
	bra.s	rt_write_print_char

;------------------------------------------------------------------------------
; Runtime: MUL of an integer variable by a float: a0 = the variable, d0-d2 = the factor.
; (a0) is converted to float ($f0(a6)), multiplied (7(a6) = 05ce2), converted back ($f1(a6)).
;------------------------------------------------------------------------------
rt_mul_int_var_float:
	move.l	d0,d3                           ; d3-d5 = the float
	move.l	d1,d4
	move.l	d2,d5
	move.l	(a0),d0                         ; the integer variable
	jsr	rn_long_to_float(a6)            ; integer to float (0632e)
	jsr	rn_float_mul(a6)                ; float multiply (05cfa)
	jsr	rn_float_to_long(a6)            ; float to integer (02b20)
	move.l	d0,(a0)                         ; back into the variable
	rts

;------------------------------------------------------------------------------
; Runtime: DIV of an integer variable by a float: as 7978 with the float divide ($11b(a6) =
; 05d58).
;------------------------------------------------------------------------------
rt_div_int_var_float:
	move.l	d0,d3                           ; d3-d5 = the divisor
	move.l	d1,d4
	move.l	d2,d5
	move.l	(a0),d0                         ; the integer variable
	jsr	rn_long_to_float(a6)            ; integer to float (0632e)
	jsr	rn_float_div(a6)                ; float divide (05d70)
	jsr	rn_float_to_long(a6)            ; float to integer (02b20)
	move.l	d0,(a0)                         ; back into the variable
	rts

;------------------------------------------------------------------------------
; Runtime: SUB of a float variable: a0 = the variable, d0-d2 = the value. Negates the value,
; loads the variable into d3-d5 ($12c(a6) = 05b82), adds (6(a6)) and stores it back
; ($e1(a6) = 05bae). 79ba is MUL (7(a6)), 79c8 DIV (8(a6) = 05d52).
;------------------------------------------------------------------------------
rt_sub_float_var:
	bchg	#$1f,d2                         ; negate the value

;------------------------------------------------------------------------------
; Runtime: ADD of a float variable (routine $1b2): a0 = the variable, d0-d2 = the value.
; Loads the variable into d3-d5 ($12c(a6) = 05b82), adds (6(a6)) and packs the sum back into
; it ($e1(a6) = 05bae). 79a8 (SUB) negates the value first; 79ba MUL multiplies (7(a6)),
; 79c8 DIV divides (8(a6) = 05d52: variable / value).
;------------------------------------------------------------------------------
rt_add_float_var:
	jsr	rn_float_load_d3_d5(a6)         ; variable into d3-d5 (05b9a)
	jsr	rn_float_add(a6)                ; float add (05c18)
	subq.l	#6,a0                           ; back to the variable
	jmp	rn_float_store(a6)              ; pack d0-d2 into it (05bc6)

rt_mul_float_var:
	jsr	rn_float_load_d3_d5(a6)
	jsr	rn_float_mul(a6)                ; float multiply
	subq.l	#6,a0                           ; a0 back at the variable
	jmp	rn_float_store(a6)              ; pack d0-d2 into it (05bc6)

rt_div_float_var:
	jsr	rn_float_load_d3_d5(a6)
	jsr	rn_float_reverse_div(a6)        ; float divide (05d6a)
	subq.l	#6,a0                           ; a0 back at the variable
	jmp	rn_float_store(a6)              ; pack d0-d2 into it (05bc6)

;------------------------------------------------------------------------------
; Runtime: RANDOM(x): INT(RND * x): RND ($54(a6) = 07ccc), multiply, $26(a6) (06292).
;------------------------------------------------------------------------------
rt_random:
	move.l	d0,d3                           ; d3-d5 = x
	move.l	d1,d4
	move.l	d2,d5
	jsr	rn_rnd(a6)                      ; RND (07ce4)
	jsr	rn_float_mul(a6)                ; float multiply
	jmp	rn_float_trunc(a6)              ; 0627a, presumably INT

;------------------------------------------------------------------------------
; Runtime: PI as an unpacked float: $c90fdaa2 $21db, exponent $201.
;------------------------------------------------------------------------------
rt_pi:
	move.l	#$c90fdaa2,d0                   ; pi
	move.w	#$21db,d1
	move.l	#$201,d2
	rts

;------------------------------------------------------------------------------
; Runtime: DEFLINE style d0: a negative style is a user pattern: vsl_udsty (VDI 113) with -d0
; and style 7; then vsl_type (VDI 15).
;------------------------------------------------------------------------------
rt_defline_style_pattern:
	tst.w	d0                              ; negative: user line pattern
	bpl.s	rt_defline_style
	neg.w	d0                              ; pattern = -style
	moveq	#113,d3                         ; VDI 113 vsl_udsty
	bsr.s	rt_vdi_d3_intin_d0              ; set the user line pattern
	moveq	#7,d0                           ; line type 7 = user defined

;------------------------------------------------------------------------------
; Runtime: vsl_type (VDI 15) with intin[0] = d0.
;------------------------------------------------------------------------------
rt_defline_style:
	moveq	#15,d3                          ; VDI 15 vsl_type

;------------------------------------------------------------------------------
; Runtime: VDI call d3 with intin[0] = d0 ($21f(a6) = 0595a).
;------------------------------------------------------------------------------
rt_vdi_d3_intin_d0:
	jmp	rn_vdi_call_opcode_d3(a6)       ; VDI call d3 with intin[0] = d0 (05972)

;------------------------------------------------------------------------------
; Runtime: DEFTEXT height: d0 into ptsin ($40e(a4)), vst_height (VDI 12).
;------------------------------------------------------------------------------
rt_deftext_height:
	move.l	d0,$40e(a4)                     ; ptsin[0..1]
	moveq	#12,d0                          ; VDI 12 vst_height
	bra.s	rt_vdi_one_ptsin

;------------------------------------------------------------------------------
; Runtime: DEFLINE width: d0 swapped into ptsin, vsl_width (VDI 16).
;------------------------------------------------------------------------------
rt_defline_width:
	swap	d0                              ; width into ptsin[0]
	move.l	d0,$40e(a4)
	moveq	#16,d0                          ; VDI 16 vsl_width

;------------------------------------------------------------------------------
; Runtime: VDI call d0 with no intin and one ptsin ($21a(a6) = 05968: d0 opcode, d1 intin
; count, d2 ptsin count).
;------------------------------------------------------------------------------
rt_vdi_one_ptsin:
	moveq	#0,d1                           ; no intin
	moveq	#1,d2                           ; one point
	jmp	rn_vdi_call_intin_ptsin(a6)     ; VDI call (05980)

;------------------------------------------------------------------------------
; Runtime: DEFLINE end styles: d1, d0 swapped; 7a26 vsl_ends (VDI 108) with intin = d0, d1.
;------------------------------------------------------------------------------
rt_defline_ends:
	exg	d0,d1

rt_vsl_ends:
	movem.w	d0-d1,$30e(a4)                  ; intin[0..1]
	moveq	#108,d0                         ; VDI 108 vsl_ends

;------------------------------------------------------------------------------
; Runtime: VDI call d0 with two intin ($30e(a4)) and no ptsin.
;------------------------------------------------------------------------------
rt_vdi_two_intin:
	moveq	#2,d1                           ; two intin
	moveq	#0,d2                           ; no ptsin
	jmp	rn_vdi_call_intin_ptsin(a6)

;------------------------------------------------------------------------------
; Runtime: graphics defaults (start-up and CLEAR): origin $b32(a4) = 0, GRAPHMODE 1
; ($276(a6) = 05958), COLOR 1 ($13c(a6) = 0594c), line type 0 width 1 ends 0, fill colour 1
; interior 1 style 0, text colour 1 effects 0 rotation 0, text alignment 0,0, the clip
; rectangle of the screen (Getrez, dat_clip_sizes, vs_clip 129), marker colour 1 type 1 and
; height 0.
;------------------------------------------------------------------------------
rt_graphics_defaults:
	clr.l	$b32(a4)                        ; origin 0,0
	moveq	#1,d0
	jsr	rn_graphmode(a6)                ; GRAPHMODE 1 (05970)
	moveq	#1,d0
	jsr	rn_color(a6)                    ; COLOR 1 (05964)
	moveq	#0,d0
	bsr.s	rt_defline_style                ; line type 0
	moveq	#1,d0
	bsr.s	rt_defline_width                ; line width 1
	moveq	#0,d0
	moveq	#0,d1
	bsr.s	rt_vsl_ends                     ; line ends 0,0
	moveq	#1,d0
	bsr.s	rt_vsf_color                    ; fill colour 1
	moveq	#1,d0
	bsr.s	rt_vsf_interior                 ; fill interior 1
	moveq	#0,d0
	bsr.s	rt_vsf_style                    ; fill style 0
	moveq	#1,d0
	bsr.s	rt_vst_color                    ; text colour 1
	moveq	#0,d0
	bsr.s	rt_vst_effects                  ; text effects 0
	moveq	#0,d0
	bsr.s	rt_vst_rotation                 ; text rotation 0
	clr.l	$30e(a4)                        ; intin 0,0
	moveq	#39,d0                          ; VDI 39 vst_alignment
	bsr.s	rt_vdi_two_intin
	move.w	#$4,-(sp)
	trap	#14                             ; Getrez, XBIOS 4 Getrez
	addq.l	#2,sp                           ; drop the function number
	asl.w	#2,d0                           ; d0 = resolution * 4
	clr.l	$40e(a4)                        ; clip from 0,0
	move.l	dat_clip_sizes(pc,d0.w),$412(a4) ; to the screen's last x,y
	move.w	#$1,$30e(a4)                    ; clipping on
	move.w	#$81,d0                         ; VDI 129 vs_clip
	moveq	#1,d1                           ; one intin
	moveq	#2,d2                           ; two points
	jsr	rn_vdi_call_intin_ptsin(a6)     ; VDI call (05980)
	moveq	#1,d0
	bsr.s	rt_vsm_color                    ; marker colour 1
	moveq	#1,d0
	bsr.s	rt_vsm_type                     ; marker type 1
	moveq	#0,d0                           ; marker height 0

;------------------------------------------------------------------------------
; Runtime: marker height d0 (routine $223): ptsin[1] = d0, vsm_height (VDI 19). The end of
; the graphics defaults falls into it with 0.
;------------------------------------------------------------------------------
rt_vsm_height:
	move.w	d0,$410(a4)                     ; ptsin[1] = 0
	moveq	#19,d0                          ; VDI 19 vsm_height
	bra.w	rt_vdi_one_ptsin                ; VDI call with one point

;------------------------------------------------------------------------------
; Runtime: vsm_color (VDI 20) with d0; the entries after it set one VDI attribute each with
; intin[0] = d0: 7ab4 vsm_type (18), 7ab8 vst_color (22), 7abc vst_effects (106), 7ac0
; vst_rotation (13), 7ac4 vsf_color (25), 7ac8 vsf_interior (23), 7acc vsf_style (24).
;------------------------------------------------------------------------------
rt_vsm_color:
	moveq	#20,d3                          ; VDI 20 vsm_color

;------------------------------------------------------------------------------
; Runtime: VDI attribute call d3 with intin[0] = d0 ($21f(a6)).
;------------------------------------------------------------------------------
rt_vdi_attribute:
	jmp	rn_vdi_call_opcode_d3(a6)       ; VDI call d3 with intin[0] = d0 (05972)

rt_vsm_type:
	moveq	#18,d3                          ; VDI 18 vsm_type
	bra.s	rt_vdi_attribute

rt_vst_color:
	moveq	#22,d3                          ; VDI 22 vst_color
	bra.s	rt_vdi_attribute

rt_vst_effects:
	moveq	#106,d3                         ; VDI 106 vst_effects
	bra.s	rt_vdi_attribute

rt_vst_rotation:
	moveq	#13,d3                          ; VDI 13 vst_rotation
	bra.s	rt_vdi_attribute

rt_vsf_color:
	moveq	#25,d3                          ; VDI 25 vsf_color
	bra.s	rt_vdi_attribute

rt_vsf_interior:
	moveq	#23,d3                          ; VDI 23 vsf_interior
	bra.s	rt_vdi_attribute

rt_vsf_style:
	moveq	#24,d3                          ; VDI 24 vsf_style
	bra.s	rt_vdi_attribute

; Data: the screen's last x and y for each resolution (319,199 / 639,199 / 639,399) for the
; clip rectangle. Its last word 399 ($018f) and the moveq at 7adc are decoded together as movep.
dat_clip_sizes:
	dc.w	$013f,$00c7,$027f,$00c7,$027f,$018f ; 319,199 / 639,199 / 639,(399 in the next word)

;------------------------------------------------------------------------------
; Runtime: vst_font (VDI 21) with intin[0] = d0 (routine $26f).
;------------------------------------------------------------------------------
rt_vst_font:
	moveq	#21,d3                          ; VDI 21 vst_font
	jmp	rn_vdi_call_opcode_d3(a6)       ; VDI call d3 with intin[0] = d0

;------------------------------------------------------------------------------
; Runtime: PLOT d1,d0: makes the point the first point and draws a one-point polyline from it
; to itself. 7ae8 (LINE end point d1,d0): v_pline (VDI 6) from the first point $856(a4) to
; it, the origin $b32/$b34(a4) added; the end point is kept at $862(a4) for DRAW.
;------------------------------------------------------------------------------
rt_plot:
	exg	d0,d1                           ; d0 = x, d1 = y

rt_plot_xy:
	bsr.s	rt_set_first_point              ; the point is the first point too
	bra.s	rt_line_from_first_point

rt_line_to:
	exg	d0,d1                           ; LINE end point

rt_line_to_xy:
	add.w	$b32(a4),d0                     ; + origin
	add.w	$b34(a4),d1                     ; + origin y

;------------------------------------------------------------------------------
; Runtime: v_pline (VDI 6) from the first point $856(a4) to d0,d1 (origin already added);
; the end point is kept at $862(a4) for DRAW. Shared by PLOT and LINE.
;------------------------------------------------------------------------------
rt_line_from_first_point:
	move.l	$856(a4),$40e(a4)               ; ptsin: first point
	movem.w	d0-d1,$412(a4)                  ; then this point
	move.l	$412(a4),$852(a4)               ; kept for DRAW
	moveq	#6,d0                           ; VDI 6 v_pline
	moveq	#0,d1                           ; no intin
	moveq	#2,d2                           ; two points
	jmp	rn_vdi_call_intin_ptsin(a6)     ; VDI call (05980)

;------------------------------------------------------------------------------
; Runtime: first point d1,d0 of LINE, BOX, CIRCLE ... : the origin added, kept at $866(a4).
;------------------------------------------------------------------------------
rt_first_point:
	exg	d0,d1                           ; d0 = x, d1 = y

rt_set_first_point:
	add.w	$b32(a4),d0                     ; + origin
	add.w	$b34(a4),d1                     ; + origin y
	movem.w	d0-d1,$856(a4)                  ; the first point
	rts

;------------------------------------------------------------------------------
; Runtime: BOX to d1,d0 from the first point: a 5-point v_pline round the rectangle.
;------------------------------------------------------------------------------
rt_box:
	exg	d0,d1                           ; d0 = x, d1 = y

rt_box_xy:
	add.w	$b32(a4),d0                     ; + origin x
	add.w	$b34(a4),d1                     ; + origin y
	movem.w	$856(a4),d2-d3                  ; d2,d3 = first corner
	lea	$40e(a4),a0                     ; 5 points round the rectangle
	move.w	d2,(a0)+                        ; x1,y1
	move.w	d3,(a0)+
	move.w	d0,(a0)+                        ; x2,y1
	move.w	d3,(a0)+
	move.w	d0,(a0)+                        ; x2,y2
	move.w	d1,(a0)+
	move.w	d2,(a0)+                        ; x1,y2
	move.w	d1,(a0)+
	move.w	d2,(a0)+                        ; x1,y1 again
	move.w	d3,(a0)+
	moveq	#6,d0                           ; VDI 6 v_pline
	moveq	#0,d1                           ; no intin
	moveq	#5,d2                           ; five points
	jmp	rn_vdi_call_intin_ptsin(a6)     ; VDI call (05980)

;------------------------------------------------------------------------------
; Runtime: PELLIPSE with radii d1,d0 round the first point: GDP 5 (ellipse) through $245(a6)
; (07b98: v_gdp, VDI 11, sub-opcode d3 into contrl[5]).
;------------------------------------------------------------------------------
rt_pellipse:
	exg	d0,d1                           ; d0 = x radius, d1 = y radius

rt_pellipse_xy:
	move.l	$856(a4),$40e(a4)               ; centre
	movem.w	d0-d1,$412(a4)                  ; radii
	moveq	#5,d3                           ; GDP 5 ellipse
	jmp	rn_vdi_gdp(a6)                  ; v_gdp (07b98)

;------------------------------------------------------------------------------
; Runtime: PELLIPSE with angles d1,d0 (radii $85a(a4)): GDP 7 (elliptical pie).
;------------------------------------------------------------------------------
rt_pellipse_angles:
	exg	d0,d1                           ; d0 = start, d1 = end angle

rt_pellipse_angles_xy:
	movem.w	d0-d1,$30e(a4)                  ; angles into intin
	move.l	$856(a4),$40e(a4)               ; centre
	move.l	$85a(a4),$412(a4)               ; radii
	moveq	#7,d3                           ; GDP 7 elliptical pie
	jmp	rn_vdi_gdp(a6)                  ; v_gdp (07b98)

;------------------------------------------------------------------------------
; Runtime: v_gdp (VDI 11) with sub-opcode d3 ($245(a6)): two intin, two ptsin.
;------------------------------------------------------------------------------
rt_vdi_gdp:
	move.w	d3,$2d6(a4)                     ; GDP sub-opcode into contrl[5]
	moveq	#11,d0                          ; VDI 11 v_gdp
	moveq	#2,d1                           ; two intin
	moveq	#2,d2                           ; two points
	jmp	rn_vdi_call_intin_ptsin(a6)     ; VDI call (05980)

;------------------------------------------------------------------------------
; Runtime: keeps the radii of an ellipse or circle with angles at $86a(a4): 7b8e both
; radii d0, 7b90 x radius d1 and y radius d0 (swapped), 7b92 x d0, y d1.
;------------------------------------------------------------------------------
rt_ellipse_radius_both:
	move.w	d0,d1                           ; y radius = x radius

rt_ellipse_radii:
	exg	d0,d1                           ; d0 = x radius, d1 = y radius

rt_ellipse_radii_xy:
	movem.w	d0-d1,$85a(a4)                  ; radii
	rts

;------------------------------------------------------------------------------
; Runtime: RBOX to d1,d0 (GDP 8 rounded rectangle), 7ba0 PRBOX (GDP 9), 7ba6 PBOX (GDP 1 bar),
; from the first point; the origin is added.
;------------------------------------------------------------------------------
rt_rbox:
	exg	d0,d1                           ; d0 = x, d1 = y

rt_rbox_xy:
	moveq	#8,d3                           ; GDP 8 rounded rectangle
	bra.s	rt_gdp_rectangle

rt_prbox:
	exg	d0,d1                           ; d0 = x, d1 = y

rt_prbox_xy:
	moveq	#9,d3                           ; GDP 9 filled rounded rectangle
	bra.s	rt_gdp_rectangle

rt_pbox:
	exg	d0,d1                           ; d0 = x, d1 = y

rt_pbox_xy:
	moveq	#1,d3                           ; GDP 1 bar

;------------------------------------------------------------------------------
; Runtime: GDP d3 (rounded rectangle, filled rounded rectangle or bar) from the first
; point to d0,d1 with the origin added.
;------------------------------------------------------------------------------
rt_gdp_rectangle:
	add.w	$b32(a4),d0                     ; + origin
	add.w	$b34(a4),d1
	move.l	$856(a4),$40e(a4)               ; first corner
	movem.w	d0-d1,$412(a4)                  ; second corner
	jmp	rn_vdi_gdp(a6)                  ; v_gdp (07b98)

;------------------------------------------------------------------------------
; Runtime: ELLIPSE with radii d1,d0: GDP 6 (elliptical arc) from 0 to 3600.
;------------------------------------------------------------------------------
rt_ellipse:
	exg	d0,d1                           ; d0 = x radius, d1 = y radius

rt_ellipse_xy:
	move.l	$856(a4),$40e(a4)               ; centre
	movem.w	d0-d1,$412(a4)                  ; radii
	move.l	#$e10,$30e(a4)                  ; angles 0 and 3600
	moveq	#6,d3                           ; GDP 6 elliptical arc
	jmp	rn_vdi_gdp(a6)                  ; v_gdp (07b98)

;------------------------------------------------------------------------------
; Runtime: ELLIPSE with angles d1,d0 (radii at $86a(a4)): GDP 6.
;------------------------------------------------------------------------------
rt_ellipse_angles:
	exg	d0,d1                           ; d0 = start, d1 = end angle

rt_ellipse_angles_xy:
	move.l	$856(a4),$40e(a4)               ; centre
	move.l	$85a(a4),$412(a4)               ; radii
	movem.w	d0-d1,$30e(a4)                  ; angles
	moveq	#6,d3                           ; GDP 6 elliptical arc
	jmp	rn_vdi_gdp(a6)                  ; v_gdp (07b98)

;------------------------------------------------------------------------------
; Runtime: PCIRCLE with radius d0: GDP 4 (circle) round the first point.
;------------------------------------------------------------------------------
rt_pcircle:
	lea	$40e(a4),a0                     ; ptsin
	move.l	$856(a4),(a0)+                  ; centre
	clr.l	(a0)+                           ; an empty point
	move.w	d0,(a0)+                        ; radius
	clr.w	(a0)                            ; last y 0
	move.w	#$4,$2d6(a4)                    ; GDP 4 circle
	moveq	#11,d0                          ; VDI 11 v_gdp
	moveq	#3,d2                           ; three points
	jmp	rn_vdi_call_intin_ptsin(a6)     ; VDI call (05980), d1 = intin count from the caller

;------------------------------------------------------------------------------
; Runtime: PCIRCLE with angles d1,d0 (GDP 3 pie); 7c1a CIRCLE with radius d0 (GDP 2 arc,
; 0..3600; the radius is kept at $86a(a4) for the angle forms).
;------------------------------------------------------------------------------
rt_pcircle_angles:
	exg	d0,d1                           ; d0 = start, d1 = end angle

rt_pcircle_angles_xy:
	moveq	#3,d7                           ; GDP 3 pie
	bra.s	rt_gdp_arc_pie

rt_circle:
	move.w	d0,$85a(a4)                     ; radius
	move.w	#$e10,d0                        ; angles 0 and 3600
	moveq	#0,d1                           ; start 0

rt_circle_angles:
	exg	d0,d1                           ; d0 = start, d1 = end angle

rt_circle_angles_xy:
	moveq	#2,d7                           ; GDP 2 arc

;------------------------------------------------------------------------------
; Runtime: GDP d7 (2 arc or 3 pie) round the first point with the radius at $86a(a4): d0,d1
; = start and end angle (intin), ptsin = centre, two empty points, radius.
;------------------------------------------------------------------------------
rt_gdp_arc_pie:
	movem.w	d0-d1,$30e(a4)                  ; angles into intin
	lea	$40e(a4),a0                     ; ptsin
	move.l	$856(a4),(a0)+                  ; centre, two empty points, then the radius
	clr.l	(a0)+
	clr.l	(a0)+
	move.w	$85a(a4),(a0)+                  ; radius
	clr.w	(a0)
	move.w	d7,$2d6(a4)                     ; GDP sub-opcode into contrl[5]
	moveq	#11,d0                          ; VDI 11 v_gdp
	moveq	#4,d2                           ; four points
	moveq	#2,d1                           ; two intin
	jmp	rn_vdi_call_intin_ptsin(a6)     ; VDI call (05980)

;------------------------------------------------------------------------------
; Runtime: FILL d1,d0: v_contourfill (VDI 103) at the point (origin added), colour -1.
;------------------------------------------------------------------------------
rt_fill:
	exg	d0,d1

rt_fill_xy:
	add.w	$b32(a4),d0                     ; + origin
	add.w	$b34(a4),d1                     ; + origin y
	movem.w	d0-d1,$40e(a4)                  ; ptsin: the point
	st	$30e(a4)                        ; fill colour -1
	moveq	#1,d1                           ; one intin
	moveq	#1,d2                           ; one point
	moveq	#103,d0                         ; VDI 103 v_contourfill
	jmp	rn_vdi_call_intin_ptsin(a6)     ; VDI call (05980)

;------------------------------------------------------------------------------
; Runtime: MOUSEX: vq_mouse, d0 = x - origin x. 7c7a MOUSEK: the buttons. 7c84 MOUSEY.
; 7c92 MOUSE: d0 = x, d1 = y, d2 = buttons.
;------------------------------------------------------------------------------
rt_mousex:
	bsr.s	rt_vq_mouse                     ; vq_mouse
	moveq	#0,d0
	move.w	$70e(a4),d0                     ; ptsout x
	sub.w	$b32(a4),d0                     ; - origin x
	rts

rt_mousek:
	bsr.s	rt_vq_mouse                     ; vq_mouse
	move.w	$60e(a4),d0                     ; intout[0] = buttons
	ext.l	d0                              ; to a long
	rts

rt_mousey:
	bsr.s	rt_vq_mouse                     ; vq_mouse
	moveq	#0,d0
	move.w	$710(a4),d0                     ; ptsout y
	sub.w	$b34(a4),d0                     ; - origin y
	rts

rt_mouse:
	bsr.s	rt_vq_mouse                     ; vq_mouse
	moveq	#0,d0
	moveq	#0,d1
	moveq	#0,d2
	move.w	$70e(a4),d0                     ; x
	sub.w	$b32(a4),d0                     ; - origin x
	move.w	$710(a4),d1                     ; y
	sub.w	$b34(a4),d1                     ; - origin y
	move.w	$60e(a4),d2                     ; buttons
	rts

;------------------------------------------------------------------------------
; Runtime: vq_mouse (VDI 124) by a direct trap #2 with the VDI block at 24(a4): intout[0]
; ($60e(a4)) buttons, ptsout $70e/$710(a4) x and y. Shows the mouse first if it is hidden
; ($206(a6) = 09d46).
;------------------------------------------------------------------------------
rt_vq_mouse:
	jsr	rn_mouse_show_if_hidden(a6)     ; show the mouse if hidden (09d52)
	move.w	#$7c,$2cc(a4)                   ; contrl[0] = VDI 124 vq_mouse
	clr.w	$2ce(a4)                        ; contrl[1] = 0 points
	clr.w	$2d2(a4)                        ; contrl[3] = 0 intin
	moveq	#24,d1                          ; the VDI parameter block at 24(a4)
	add.l	a4,d1                           ; d1 = address of the parameter block
	moveq	#115,d0                         ; $73: VDI
	trap	#2                              ; AES/VDI
	rts

;------------------------------------------------------------------------------
; Runtime: RND: XBIOS Random (24 bits) as an unpacked float 0 <= x < 1 in d0-d2 (normalised:
; shifted left until bit 31 is set, the exponent counted down from $1ff).
;------------------------------------------------------------------------------
rt_rnd:
	move.w	#$11,-(sp)                      ; XBIOS 17 Random
	trap	#14                             ; Random
	addq.l	#2,sp                           ; drop the function number
	move.l	d0,d2                           ; d2 = 0 when the value is 0
	beq.s	.done                           ; 0 stays 0.0
	asl.l	#7,d0                           ; 24 random bits to the top
	move.w	#$1ff,d2                        ; exponent below $200: x < 1
	moveq	#0,d1
.normalise:
	add.l	d0,d0                           ; shift until bit 31 is set
	dbmi	d2,.normalise
.done:
	rts

;------------------------------------------------------------------------------
; Runtime: POINT(d1,d0): v_get_pixel (VDI 105) at the point (origin added); d0 = the colour
; index (intout[1], $610(a4)).
;------------------------------------------------------------------------------
rt_point:
	exg	d0,d1                           ; d0 = x, d1 = y

rt_point_xy:
	add.w	$b32(a4),d0                     ; + origin
	add.w	$b34(a4),d1
	movem.w	d0-d1,$40e(a4)                  ; ptsin: the point
	moveq	#105,d0                         ; VDI 105 v_get_pixel
	moveq	#0,d1                           ; no intin
	moveq	#1,d2                           ; one point
	jsr	rn_vdi_call_intin_ptsin(a6)     ; VDI call (05980)
	moveq	#0,d0
	move.w	$610(a4),d0                     ; intout[1] = colour index
	rts

;------------------------------------------------------------------------------
; Runtime: SGET to a string: a0 = the variable; gives it a 32000-byte string ($45(a6)) and
; copies the screen (Logbase) into it. 7d1e SPUT: copies 32000 bytes from the string at a0 to
; the screen. The copy is $ec(a6) (09566) with the mouse hidden.
;------------------------------------------------------------------------------
rt_sget:
	move.w	#$7d00,d0                       ; 32000 bytes
	jsr	rn_string_alloc_var(a6)         ; a string of d0 bytes for the variable (0848a)
	move.l	a1,d3                           ; destination: the string
	move.w	#$3,-(sp)                       ; XBIOS 3 Logbase
	trap	#14                             ; Logbase
	exg	d0,d3                           ; source: the screen
	bra.s	rt_screen_copy

rt_sput:
	move.l	(a0)+,d3                        ; source: the string
	move.w	#$3,-(sp)                       ; XBIOS 3 Logbase
	trap	#14                             ; Logbase

;------------------------------------------------------------------------------
; Runtime: the 32000-byte copy of SGET/SPUT: drops the Logbase argument, d0 = destination,
; d3 = source; mouse hidden, then the memory copy ($ec(a6) = 0955a).
;------------------------------------------------------------------------------
rt_screen_copy:
	addq.l	#2,sp
	movea.l	d0,a1                           ; a1 = destination
	movea.l	d3,a0                           ; a0 = source
	move.l	#$7d00,d0                       ; 32000 bytes
	jsr	rn_mouse_hide(a6)               ; hide the mouse once (09d32)
	jmp	rn_copy_bytes_forward(a6)       ; memory copy (09566)

;------------------------------------------------------------------------------
; Data: an MFDB size line for each resolution: width, height, words per line, planes
; (320,200,20,4 / 640,200,40,2 / 640,400,40,1), decoded as instructions.
;------------------------------------------------------------------------------
dat_screen_mfdb_sizes:
	bchg	d0,d0                           ; 320, 200, then 20, 4 in the next instruction
	dc.w	$00c8
	ori.b	#$4,(a4)
	andi.l	#$c80028,d0                     ; 640, 200, 40, then 2
	dc.w	$0002
	andi.l	#$1900028,d0                    ; 640, 400, 40, then 1
	dc.w	$0001

;------------------------------------------------------------------------------
; Runtime: sets both raster MFDBs ($79a(a4) source, $7c2(a4) destination) to the screen:
; Logbase, the size line of the resolution, format 0 ($21(a6)). Exit d0-d2/d4 = width,
; height, words per line, planes.
;------------------------------------------------------------------------------
rt_screen_mfdbs:
	move.w	#$3,-(sp)                       ; XBIOS 3 Logbase
	trap	#14                             ; Logbase
	move.l	d0,d7                           ; d7 = screen address
	move.w	#$4,-(sp)
	trap	#14                             ; Getrez, XBIOS 4 Getrez
	addq.l	#4,sp                           ; drop both function numbers
	asl.w	#3,d0                           ; 8 bytes per resolution
	movem.w	dat_screen_mfdb_sizes(pc,d0.w),d0-d2/d4 ; d0-d2/d4 = width, height, words per line, planes
	moveq	#0,d3                           ; format 0 (device specific)
	lea	$79a(a4),a0                     ; source MFDB
	move.l	d7,(a0)+                        ; address
	movem.w	d0-d4,(a0)                      ; width, height, words, format, planes
	lea	$7c2(a4),a0                     ; destination MFDB
	move.l	d7,(a0)+                        ; address
	movem.w	d0-d4,(a0)                      ; width, height, words, format, planes
	rts

;------------------------------------------------------------------------------
; Runtime: PUT with nothing to draw (string too short, too many planes, off the screen).
;------------------------------------------------------------------------------
rt_put_nothing:
	rts                                     ; nothing to PUT

;------------------------------------------------------------------------------
; Runtime: PUT x,y,a$[,mode]: d1 = x,y packed, d0 = mode (7d84 sets 3, replace), a0 = the
; string. The string holds width-1, height-1, planes and the raster; anything shorter than 6
; bytes or with more than 4 planes does nothing. The source MFDB is pointed at it, the
; rectangle clipped against the screen, then vro_cpyfm (VDI 109) at 7e46 ($22(a6)) with the
; two MFDBs in contrl.
;------------------------------------------------------------------------------
rt_put_replace:
	moveq	#3,d0                           ; mode 3: replace

rt_put_mode:
	move.w	d0,$30e(a4)                     ; intin[0] = mode
	swap	d1
	move.l	d1,$416(a4)                     ; destination x,y into ptsin[4..5]
	move.l	a0,d6                           ; d6 = string descriptor
	jsr	rn_screen_mfdbs(a6)             ; MFDBs to the screen (07d6a)
	movea.l	d6,a0                           ; a0 = string descriptor
	jsr	rn_string_text_len_212(a6)      ; a1 = text, d0 = length
	cmpi.w	#$6,d0                          ; shorter than the header: nothing
	bcs.s	rt_put_nothing
	move.w	(a1)+,d0                        ; width - 1
	move.w	(a1)+,d1                        ; height - 1
	move.w	(a1)+,d2                        ; planes
	lea	$79a(a4),a2                     ; source MFDB
	move.l	a1,(a2)                         ; its raster: after the header
	cmpi.w	#$4,d2                          ; more than 4 planes: nothing
	bhi.s	rt_put_nothing
	move.w	d2,$e(a2)                       ; planes
	move.w	d1,6(a2)                        ; height - 1
	move.w	d0,d3                           ; width rounded up to 16
	addi.w	#$10,d3
	andi.w	#$fff0,d3
	move.w	d3,4(a2)                        ; width in pixels
	lsr.w	#4,d3                           ; words per line
	move.w	d3,8(a2)                        ; words per line
	lea	$40e(a4),a0                     ; source rectangle 0,0,w-1,h-1
	clr.l	(a0)+                           ; 0,0
	move.w	d0,(a0)+                        ; w-1, h-1
	move.w	d1,(a0)+
	move.w	(a0)+,d4                        ; destination x,y
	move.w	(a0)+,d5
	add.w	d4,d0                           ; right edge
	bmi.s	.put_off_screen
	add.w	d5,d1                           ; bottom edge
	bmi.s	.put_off_screen
	move.w	d0,(a0)+                        ; bottom-right corner
	move.w	d1,(a0)+
	move.w	$7c6(a4),d6                     ; screen width and height
	move.w	$7c8(a4),d7
	subq.w	#1,d6                           ; last x
	subq.w	#1,d7                           ; last y
	cmp.w	d6,d4                           ; starts right of the screen
	bgt.s	.put_off_screen
	cmp.w	d7,d5                           ; or below it
	bgt.s	.put_off_screen
	neg.w	d4                              ; left of the screen: clip
	bmi.s	.clip_y
	move.w	d4,$40e(a4)                     ; source x1 = -x
	clr.w	$416(a4)                        ; destination x 0
.clip_y:
	neg.w	d5                              ; above the screen: clip
	bmi.s	.clip_right
	move.w	d5,$410(a4)                     ; source y1 = -y
	clr.w	$418(a4)                        ; destination y 0
.clip_right:
	sub.w	d6,d0                           ; past the right edge: clip
	bls.s	.clip_bottom
	sub.w	d0,$412(a4)                     ; source x2 - overhang
	sub.w	d0,$41a(a4)                     ; destination x2 - overhang
.clip_bottom:
	sub.w	d7,d1                           ; past the bottom: clip
	bls.s	.check
	sub.w	d1,$414(a4)                     ; source y2 - overhang
	sub.w	d1,$41c(a4)                     ; destination y2 - overhang
.check:
	move.w	$40e(a4),d0                     ; anything left?
	cmp.w	$412(a4),d0                     ; x1 <= x2?
	bhi.s	.put_off_screen                 ; no: nothing
	move.w	$410(a4),d0
	cmp.w	$414(a4),d0                     ; y1 <= y2?
	bls.s	rt_vro_cpyfm                    ; yes: copy
.put_off_screen:
	rts                                     ; nothing to PUT

; Data: word $0022, not code (between the rts and 7e46).
	dc.w	$0022                           ; word $0022, not code

;------------------------------------------------------------------------------
; Runtime: vro_cpyfm (VDI 109, routine $22): one intin (mode at $30e(a4)), four points at
; $40e(a4), the source MFDB $79a(a4) and destination MFDB $7c2(a4) put into contrl.
;------------------------------------------------------------------------------
rt_vro_cpyfm:
	moveq	#109,d0                         ; VDI 109 vro_cpyfm
	moveq	#1,d1                           ; one intin
	moveq	#4,d2                           ; four points
	lea	$79a(a4),a0
	move.l	a0,$2da(a4)                     ; contrl: source MFDB
	lea	$7c2(a4),a0
	move.l	a0,$2de(a4)                     ; contrl: destination MFDB
	jmp	rn_vdi_call_intin_ptsin(a6)     ; VDI call (05980)

;------------------------------------------------------------------------------
; Runtime: GET with a rectangle off the screen: the variable gets an empty string.
;------------------------------------------------------------------------------
rt_get_empty:
	moveq	#0,d0                           ; length 0
	jmp	rn_string_alloc_var(a6)         ; empty string for the variable

;------------------------------------------------------------------------------
; Runtime: GET x1,y1,x2,y2,a$: the corners packed in d0/d1 (pushed), a0 = the variable.
; Sorts the corners, checks them against the screen, sets up the copy to a raster at 0,0 and
; gives the variable a string of 6 + (h+1) * words per line * planes * 2 bytes ($45(a6)) with
; the header width-1, height-1, planes; vro_cpyfm replace ($22(a6)) copies the screen into it.
;------------------------------------------------------------------------------
rt_get:
	movem.l	d0-d1,-(sp)                     ; the corners
	pea	(a0)                            ; keep the variable
	jsr	rn_screen_mfdbs(a6)             ; MFDBs to the screen (07d6a)
	move.w	d4,d2                           ; d2 = planes
	movea.l	(sp)+,a0                        ; a0 = the variable
	move.w	(sp)+,d5                        ; the corners
	move.w	(sp)+,d4                        ; x2
	move.w	(sp)+,d7                        ; y1
	move.w	(sp)+,d6                        ; x1
	cmp.w	d4,d6                           ; order x
	bhi.s	.order_y
	exg	d4,d6                           ; d4 = left, d6 = right
.order_y:
	cmp.w	d5,d7                           ; order y
	bhi.s	.corners
	exg	d5,d7                           ; d5 = top, d7 = bottom
.corners:
	lea	$40e(a4),a1                     ; source rectangle
	movem.w	d4-d7,(a1)                      ; x1,y1,x2,y2
	addq.l	#8,a1                           ; a1 = destination rectangle
	cmp.w	d0,d6                           ; outside the screen: empty string
	bcc.s	rt_get_empty
	cmp.w	d1,d7                           ; bottom edge >= screen height?
	bcc.s	rt_get_empty
	clr.l	(a1)+                           ; destination 0,0
	sub.w	d4,d6                           ; w - 1
	move.w	d6,(a1)+
	sub.w	d5,d7                           ; h - 1
	move.w	d7,(a1)+
	move.w	#$3,$30e(a4)                    ; replace
	lea	$7c6(a4),a1                     ; destination MFDB width
	move.w	d2,-(sp)                        ; header: planes, h-1, w-1
	move.w	d7,-(sp)
	move.w	d6,-(sp)
	addi.w	#$10,d6                         ; rounded up to 16
	andi.w	#$fff0,d6
	move.w	d6,(a1)+                        ; width in pixels
	move.w	d7,(a1)+                        ; h - 1 (as the MFDB height, one short)
	lsr.w	#4,d6                           ; words per line
	move.w	d6,(a1)+                        ; words per line
	move.w	d2,2(a1)                        ; planes
	addq.w	#1,d7                           ; lines
	mulu.w	d6,d7                           ; words per plane
	move.w	d7,d0
	mulu.w	d2,d0                           ; * planes
	add.w	d0,d0                           ; bytes
	addq.w	#6,d0                           ; + the header
	jsr	rn_string_alloc_var(a6)         ; a string of d0 bytes for the variable (0848a)
	move.l	(sp)+,(a1)+                     ; the header
	move.w	(sp)+,(a1)+
	move.l	a1,$7c2(a4)                     ; its raster
	jmp	rn_vro_cpyfm(a6)                ; vro_cpyfm (07e5e)

;------------------------------------------------------------------------------
; Runtime: SPRITE a$ (remove): a string of 74 bytes ($4a, the definition only) was never
; drawn and is left alone; otherwise it must have the full length for the resolution (else
; error 60): Line-A undraw sprite with the save buffer after the definition, then the string is
; cut back to 74 bytes, the rest marked free.
;------------------------------------------------------------------------------
rt_sprite_remove:
	bsr.s	rt_sprite_check                 ; d1 = full length, a1 = text, d0 = length
	cmpi.w	#$4a,d0                         ; 74 bytes: never drawn
	beq.s	.not_drawn
	cmp.w	d1,d0                           ; the full length?
	bne.s	rt_sprite_length_error          ; no: error 60
	lea	$4a(a1),a2                      ; the save buffer
	move.l	a6,d6                           ; Line-A destroys a6
	dc.w	$a00c                           ; Line-A Undraw sprite
	movea.l	d6,a6                           ; a6 back
	movea.l	d7,a0                           ; the descriptor
	movea.l	(a0),a1                         ; a1 = text
	move.w	4(a0),d0                        ; d0 = length
	move.w	#$4a,4(a0)                      ; cut back to 74 bytes
	move.l	a0,$4a(a1)                      ; back pointer after the definition
	adda.w	d0,a1                           ; a1 = end of the string
	subi.w	#$4e,d0                         ; rest of the old string
	ext.l	d0
	neg.l	d0                              ; negative length
	move.l	d0,(a1)                         ; marked free for the garbage collector
.not_drawn:
	rts

;------------------------------------------------------------------------------
; Runtime: error 60 (Sprite string length wrong).
;------------------------------------------------------------------------------
rt_sprite_length_error:
	moveq	#60,d0                          ; error 60 Sprite string length wrong
	jmp	rn_error_entry(a6)              ; raise error d0

;------------------------------------------------------------------------------
; Runtime: SPRITE set-up: d7 = a0 (the descriptor), mouse hidden; d1 = the full sprite
; string length for the resolution (dat_sprite_lengths), a1 = text, d0 = length.
;------------------------------------------------------------------------------
rt_sprite_check:
	move.l	a0,d7                           ; d7 = the descriptor
	jsr	rn_mouse_hide(a6)               ; hide the mouse once (09d32)
	move.w	#$4,-(sp)                       ; XBIOS 4 Getrez
	trap	#14                             ; Getrez, XBIOS 4 Getrez
	addq.l	#2,sp                           ; drop the function number
	add.w	d0,d0                           ; word index
	move.w	dat_sprite_lengths(pc,d0.w),d1  ; full length for the resolution
	movea.l	d7,a0                           ; a0 = the descriptor
	movea.l	(a0)+,a1                        ; a1 = text
	move.w	(a0),d0                         ; d0 = length
	rts

;------------------------------------------------------------------------------
; Data: sprite string length per resolution: 74 + the Line-A save buffer: 340, 212, 148.
; 7f42 starts SPRITE a$,x,y: move.w d0,d4 / move.w d1,d3 (decoded with the last table word).
;------------------------------------------------------------------------------
dat_sprite_lengths:
	bchg	d0,(a4)                         ; $0154 = 340, then $00d4 = 212
	dc.w	$00d4,$0094

;------------------------------------------------------------------------------
; Runtime: SPRITE a$,x,y (routine $173): d0 = y, d1 = x moved into d4/d3; see 7f46.
;------------------------------------------------------------------------------
rt_sprite:
	move.w	d0,d4                           ; d4 = y
	move.w	d1,d3                           ; d3 = x

;------------------------------------------------------------------------------
; Runtime: SPRITE a$,x,y (d3 = x, d4 = y): on first use (74 bytes) the string is copied into a
; new one of the full length ($47(a6) = 084d4), the old one marked free; otherwise the sprite is
; undrawn at its old place. Then Line-A draw sprite at x,y. a6 is saved in d6 around the Line-A
; calls.
;------------------------------------------------------------------------------
	bsr.s	rt_sprite_check                 ; d7 = descriptor, d1 = full length, a1/d0 = the string
	cmpi.w	#$4a,d0                         ; 74 bytes: first use
	beq.s	.first_use
	cmp.w	d1,d0                           ; the full length?
	bne.s	rt_sprite_length_error          ; no: error 60
	move.l	a1,d7                           ; d7 = the definition
	lea	$4a(a1),a2                      ; the save buffer
	move.l	a6,d6                           ; Line-A destroys a6
	dc.w	$a00c                           ; Line-A Undraw sprite, undraw at the old place
.draw:
	movea.l	d7,a0
	lea	$4a(a0),a2                      ; save buffer
	move.w	d3,d0                           ; x
	move.w	d4,d1                           ; y
	dc.w	$a00d                           ; Line-A Draw sprite, Line-A draw sprite
	movea.l	d6,a6                           ; a6 back
	rts
.first_use:
	move.w	d1,d0                           ; d0 = full length
	jsr	rn_temp_string_alloc(a6)        ; new string of the full length (084ec)
	st	4(a0)                           ; sets byte 4(a0) to $ff (a0 from 084d4; purpose unclear)
	movea.l	d7,a2                           ; a2 = the descriptor
	move.l	a1,d7                           ; d7 = the new text
	movea.l	(a2),a0                         ; the old text
	move.l	a2,0(a1,d0.w)                   ; back pointer after the new one
	move.l	a1,(a2)+                        ; the variable takes the new string
	move.w	d0,(a2)                         ; and its length
	moveq	#36,d1                          ; 37 words: the definition
.copy_definition:
	move.w	(a0)+,(a1)+
	dbra	d1,.copy_definition
	move.l	#$ffffffb6,(a0)                 ; old string marked free (-74)
	move.l	a6,d6
	bra.s	.draw                           ; draw it

;------------------------------------------------------------------------------
; Runtime: ALERT icon,text$,button,buttons$,var: builds "[icon][text][buttons]" at $94(a4):
; at most 4 lines of 30 characters and 3 buttons of 8, '[' and ']' left out; d1 = default
; button into intin $74a(a4), the string address in addrin $79a(a4); form_alert (AES 52,
; $21b(a6) = 0591a). Exit d0.l = the button.
;------------------------------------------------------------------------------
rt_alert:
	move.l	a0,d4                           ; d4 = buttons descriptor
	move.l	a1,d5                           ; d5 = text descriptor
	move.w	d1,$74a(a4)                     ; default button: AES intin[0]
	lea	$94(a4),a0                      ; the alert string
	move.l	a0,$79a(a4)                     ; AES addrin[0]
	andi.w	#$3,d0                          ; icon 0..3
	ori.w	#$5b30,d0                       ; "[0".."[3"
	move.w	d0,(a0)+
	move.w	#$5d5b,(a0)+                    ; "]["
	exg	d5,a0                           ; a0 = text descriptor, d5 = string pointer
	jsr	rn_string_text_len_212(a6)      ; the text: a1, d0
	movea.l	d5,a0                           ; a0 = string pointer again
	moveq	#3,d3                           ; at most 4 lines
	moveq	#30,d5                          ; of 30 characters
	bra.s	.text_next
.text_char:
	move.b	(a1)+,d1                        ; next character
	cmpi.b	#$5b,d1                         ; '[' left out
	beq.s	.text_next
	cmpi.b	#$5d,d1                         ; ']' left out
	beq.s	.text_next
	move.b	d1,(a0)+                        ; into the alert string
	cmpi.b	#$7c,d1                         ; '|' starts a new line
	beq.s	.text_line
	dbra	d5,.text_next                   ; line too long: drop the rest
	subq.l	#1,a0                           ; take back the 31st character
	moveq	#0,d5                           ; end of the text
	bra.s	.text_next
.text_line:
	moveq	#30,d5                          ; a new line: 30 characters again
	dbra	d3,.text_next                   ; a fifth line: stop
	subq.l	#1,a0                           ; take back the '|'
	moveq	#0,d0                           ; end of the text
.text_next:
	dbra	d0,.text_char
	move.b	#$5d,(a0)+                      ; "]["
	move.b	#$5b,(a0)+
	exg	d4,a0                           ; a0 = buttons descriptor, d4 = string pointer
	jsr	rn_string_text_len_212(a6)      ; the buttons: a1, d0
	movea.l	d4,a0                           ; a0 = string pointer again
	moveq	#2,d3                           ; at most 3 buttons
	moveq	#8,d4                           ; of 8 characters
	bra.s	.button_next
.button_char:
	move.b	(a1)+,d1                        ; next character
	cmpi.b	#$5b,d1                         ; '[' left out
	beq.s	.button_next
	cmpi.b	#$5d,d1                         ; ']' left out
	beq.s	.button_next
	move.b	d1,(a0)+                        ; into the alert string
	cmpi.b	#$7c,d1                         ; '|' starts the next button
	beq.s	.button_next_one
	dbra	d4,.button_next                 ; button too long: drop the rest
	subq.l	#1,a0                           ; take back the 9th character
	moveq	#0,d4                           ; end of the buttons
	bra.s	.button_next
.button_next_one:
	moveq	#8,d4                           ; a new button: 8 characters again
	dbra	d3,.button_next                 ; a fourth button: stop
	subq.l	#1,a0                           ; take back the '|'
	moveq	#0,d0                           ; end of the buttons
.button_next:
	dbra	d0,.button_char
	move.b	#$5d,(a0)+                      ; "]"
	clr.b	(a0)+                           ; NUL
	moveq	#52,d0                          ; AES 52 form_alert
	jsr	rn_aes_call(a6)                 ; AES call (05932)
	ext.l	d0                              ; d0.l = the button
	rts

;------------------------------------------------------------------------------
; Runtime: FILESELECT path$,name$,var$: path (upper case, at most 100) to $94(a4), name (upper
; case, '\' left out, at most 12) to $15c(a4). The screen is saved in a 32000-byte string at
; $ad8(a4) (SGET, $15d(a6)), fsel_input (AES 90) runs, the screen comes back (SPUT, $15e(a6))
; and that string is marked free. With OK the result is the path up to its last '\' plus the
; name, with Cancel an empty string; it goes into the variable at a0 ($45(a6)).
;------------------------------------------------------------------------------
rt_fileselect:
	move.l	a0,d5                           ; d5 = result variable
	move.l	d1,d4                           ; d4 = name descriptor
	movea.l	a1,a0                           ; a0 = path descriptor
	jsr	rn_string_text_len_212(a6)      ; the path
	lea	$94(a4),a0                      ; path buffer
	move.l	a0,$79a(a4)                     ; AES addrin[0]
	cmpi.w	#$64,d0                         ; at most 100 characters
	bcs.s	.path_next
	moveq	#100,d0                         ; longer: 101 characters copied
.path_char:
	move.b	(a1)+,d1                        ; next character
	cmpi.b	#$61,d1                         ; lower case to upper case
	bcs.s	.path_store
	cmpi.b	#$7a,d1
	bhi.s	.path_store
	subi.b	#$20,d1
.path_store:
	move.b	d1,(a0)+                        ; into the buffer
.path_next:
	dbra	d0,.path_char
	clr.b	(a0)+                           ; NUL
	movea.l	d4,a0                           ; a0 = name descriptor
	jsr	rn_string_text_len_212(a6)      ; the default name
	lea	$15c(a4),a0                     ; name buffer
	move.l	a0,$79e(a4)                     ; AES addrin[1]
	cmpi.w	#$d,d0                          ; at most 12 characters
	bcs.s	.name_next
	bra.s	.name_end                       ; longer: an empty name
.name_char:
	move.b	(a1)+,d1                        ; next character
	cmpi.b	#$61,d1
	bcs.s	.name_store                     ; lower case to upper case
	cmpi.b	#$7a,d1
	bhi.s	.name_store
	subi.b	#$20,d1
.name_store:
	cmpi.b	#$5c,d1                         ; '\' left out
	beq.s	.name_next
	move.b	d1,(a0)+                        ; into the buffer
.name_next:
	dbra	d0,.name_char
.name_end:
	clr.b	(a0)+                           ; NUL
	lea	$ad8(a4),a0                     ; descriptor for the saved screen
	clr.w	4(a0)                           ; empty: SGET makes a new string
	jsr	rn_sget(a6)                     ; SGET into it (07d22)
	moveq	#90,d0                          ; AES 90 fsel_input
	jsr	rn_aes_call(a6)                 ; AES call (05932)
	lea	$adc(a4),a0                     ; length of the saved screen
	clr.w	(a0)                            ; length 0
	movea.l	-(a0),a1                        ; a1 = the saved screen
	move.l	#$ffff8300,$7d00(a1)            ; its end mark: -32000, a free block
	jsr	rn_sput(a6)                     ; SPUT from it (07d36)
	lea	$94(a4),a0                      ; the result is built over the path
	movea.l	a0,a1                           ; a1 = end of the result so far
	move.w	$774(a4),d0                     ; the exit button
	beq.s	.result                         ; Cancel: empty result
.after_backslash:
	movea.l	a0,a1
.find_backslash:
	move.b	(a0)+,d0                        ; find the last '\'
	beq.s	.append_name                    ; end of the path
	cmpi.b	#$5c,d0                         ; '\'?
	bne.s	.find_backslash
	bra.s	.after_backslash                ; a1 = just after it
.append_name:
	lea	$15c(a4),a0                     ; append the name
.append_next:
	move.b	(a0)+,(a1)+                     ; copy the name with its NUL
	bne.s	.append_next
	subq.l	#1,a1                           ; back over the NUL
.result:
	move.l	a1,d0                           ; length of the result
	lea	$94(a4),a0
	sub.l	a0,d0                           ; d0 = length
	movea.l	d5,a0                           ; a0 = the variable
	jsr	rn_string_alloc_var(a6)         ; a string for the variable (0848a)
	lea	$94(a4),a0                      ; the result text
	addq.w	#1,d0                           ; in words
	lsr.w	#1,d0
	bra.s	.copy_result_next
.copy_result:
	move.w	(a0)+,(a1)+                     ; copy a word
.copy_result_next:
	dbra	d0,.copy_result
	rts

;------------------------------------------------------------------------------
; Runtime: DEFFILL with a pattern string: its words into intin (at most 128), vsf_udpat
; (VDI 112), then vsf_interior 4 (user pattern, $21d(a6) = 0595c).
;------------------------------------------------------------------------------
rt_deffill_pattern:
	jsr	rn_string_text_len_212(a6)      ; a1 = text, d0 = length
	lea	$30e(a4),a0                     ; intin
	lsr.w	#1,d0                           ; words
	move.w	d0,d1                           ; d1 = intin count
	cmpi.w	#$80,d0                         ; at most 128
	bcs.s	.pattern_next
	moveq	#127,d0                         ; longer: 128 words
	moveq	#127,d1
.pattern_word:
	move.w	(a1)+,(a0)+                     ; pattern word into intin
.pattern_next:
	dbra	d0,.pattern_word
	moveq	#112,d0                         ; VDI 112 vsf_udpat
	moveq	#0,d2                           ; no ptsin
	jsr	rn_vdi_call_intin_ptsin(a6)     ; VDI call (05980)
	moveq	#4,d3                           ; interior 4: user pattern
	moveq	#23,d0                          ; VDI 23 vsf_interior
	jmp	rn_vdi_call_intin_d3(a6)        ; VDI call d0 with intin[0] = d3 (05974)

;------------------------------------------------------------------------------
; Runtime: DEFMOUSE n: graf_mouse (AES 78) with n & 7.
;------------------------------------------------------------------------------
rt_defmouse_form:
	andi.w	#$7,d0                          ; mouse form 0..7
	move.w	d0,$74a(a4)                     ; AES intin[0]
	moveq	#78,d0                          ; AES 78 graf_mouse
	jmp	rn_aes_call(a6)                 ; AES call (05932)

;------------------------------------------------------------------------------
; Runtime: DEFMOUSE a$: the string's words into intin (at most 128), vsc_form (VDI 111), then
; shows the mouse if hidden ($206(a6)).
;------------------------------------------------------------------------------
rt_defmouse_string:
	jsr	rn_string_text_len_212(a6)      ; a1 = text, d0 = length
	lea	$30e(a4),a0                     ; a0 = intin
	lsr.w	#1,d0                           ; words
	move.w	d0,d1                           ; d1 = intin count
	cmpi.w	#$80,d0
	bcs.s	.form_next
	moveq	#127,d1                         ; longer: 128 words
	moveq	#127,d0
.form_word:
	move.w	(a1)+,(a0)+                     ; form word into intin
.form_next:
	dbra	d0,.form_word
	moveq	#0,d2                           ; no ptsin
	moveq	#111,d0                         ; VDI 111 vsc_form
	jsr	rn_vdi_call_intin_ptsin(a6)     ; VDI call (05980)
	jmp	rn_mouse_show_if_hidden(a6)     ; show the mouse if hidden (09d52)

;------------------------------------------------------------------------------
; Runtime: TEXT at the first point: a0 = the string, d1 = the width for justified text (817a:
; 0, plain; 817c: d1; a negative width spaces the characters, not the words). The characters
; (at most 119) into intin as words after the two spacing flags, v_justified (GDP 10).
;------------------------------------------------------------------------------
rt_text:
	moveq	#0,d1                           ; TEXT: no width

rt_text_width:
	moveq	#0,d6                           ; d6 = width
	move.w	d1,d6
	jsr	rn_string_text_len_212(a6)      ; a1 = text, d0 = length
	cmpi.w	#$78,d0                         ; at most 119 characters
	bcs.s	.length
	moveq	#119,d0
.length:
	move.w	d0,d1                           ; d1 = character count
	lea	$30e(a4),a0                     ; intin
	move.l	d6,d2                           ; spacing flags
	tst.w	d2
	bpl.s	.spacing                        ; positive width: word spacing
	neg.w	d6                              ; negative: character spacing
	swap	d2
.spacing:
	move.l	d2,(a0)+                        ; intin[0..1]
	moveq	#0,d2
	bra.s	.char_next
.char:
	move.b	(a1)+,d2                        ; characters as words
	move.w	d2,(a0)+
.char_next:
	dbra	d0,.char
	clr.w	$414(a4)                        ; ptsin[3] = 0
	move.w	d6,$412(a4)                     ; ptsin[2] = width
	move.l	$856(a4),$40e(a4)               ; ptsin[0..1] = the first point
	addq.w	#2,d1                           ; intin count
	moveq	#3,d2                           ; three points
	moveq	#11,d0                          ; VDI 11 v_gdp
	move.w	#$a,$2d6(a4)                    ; GDP 10 v_justified
	jmp	rn_vdi_call_intin_ptsin(a6)     ; VDI call (05980)

;------------------------------------------------------------------------------
; Runtime: errors 27 (too many points, max. 128), 28 (array must have one dimension),
; 29 (number of points too large for the array).
;------------------------------------------------------------------------------
rt_poly_error_too_many:
	moveq	#27,d0                          ; error 27 too many points
	bra.s	rt_poly_raise_error

rt_poly_error_dimension:
	moveq	#28,d0                          ; error 28 array must have one dimension
	bra.s	rt_poly_raise_error

rt_poly_error_too_few:
	moveq	#29,d0                          ; error 29 number of points too large

rt_poly_raise_error:
	jmp	rn_error_entry(a6)              ; raise error d0

;------------------------------------------------------------------------------
; Runtime: POLYLINE/POLYFILL/POLYMARK with no points: nothing to do.
;------------------------------------------------------------------------------
rt_poly_nothing:
	rts                                     ; no points: nothing

;------------------------------------------------------------------------------
; Runtime: POLYMARK (81d8, v_pmarker 7), POLYFILL (81dc, v_fillarea 9) and POLYLINE (81e0,
; v_pline 6) n,x(),y() [OFFSET]: d0 = n, a0/a1 the arrays, d1 = the offset packed (origin
; added). n of 128 or more: error 27; 0 does nothing. Both arrays must have one dimension and
; at least n elements. The points go into ptsin from float arrays (unpacked and converted,
; $e0(a6), $f1(a6)) or integer arrays (above $88(a4)), offset added.
;------------------------------------------------------------------------------
rt_polymark:
	moveq	#7,d7                           ; VDI 7 v_pmarker
	bra.s	rt_poly_points

rt_polyfill:
	moveq	#9,d7                           ; VDI 9 v_fillarea
	bra.s	rt_poly_points

rt_polyline:
	moveq	#6,d7                           ; VDI 6 v_pline

;------------------------------------------------------------------------------
; Runtime: the point loop shared by POLYMARK, POLYFILL and POLYLINE: d7 = VDI opcode,
; d0 = n, a0/a1 = the y/x array descriptors, d1 = the offset packed. See 81d8.
;------------------------------------------------------------------------------
rt_poly_points:
	swap	d1                              ; offset x into the low word
	add.l	$b32(a4),d1                     ; offset + origin
	swap	d1                              ; back: x in the high word
	cmpi.l	#$80,d0                         ; 128 or more: error 27
	bcc.s	rt_poly_error_too_many
	tst.w	d0                              ; no points
	beq.s	rt_poly_nothing
	move.w	d7,-(sp)                        ; VDI opcode
	move.w	d0,-(sp)                        ; point count
	move.l	d1,$856(a4)                     ; the offset
	exg	a1,a0                           ; a0 = x array, a1 = y array
	cmpa.l	$88(a4),a0                      ; integer arrays lie above $88(a4)
	scc	d6                              ; d6 = $ff for an integer x array
	cmpi.w	#$1,4(a0)                       ; dimensions of the x array
	bne.s	rt_poly_error_dimension         ; no: error 28
	cmpi.w	#$1,4(a1)                       ; dimensions of the y array
	bne.s	rt_poly_error_dimension         ; no: error 28
	movea.l	(a1),a2                         ; a2 = y array data
	cmp.l	(a2)+,d0                        ; number of elements
	bhi.s	rt_poly_error_too_few
	movea.l	(a0)+,a0                        ; a0 = x array data
	cmp.l	(a0)+,d0                        ; fewer elements than points: error 29
	bhi.s	rt_poly_error_too_few
	lea	$40e(a4),a2                     ; ptsin
	tst.b	d6                              ; integer x array?
	bne.s	.int_x_next
	move.w	(sp),-(sp)                      ; count on the stack for the float loop
	bra.s	.float_x_next
.float_x:
	jsr	rn_float_load(a6)               ; unpack the element (05bb2)
	jsr	rn_float_to_long(a6)            ; float to integer (02b20)
	add.w	$858(a4),d0                     ; + x offset
	move.w	d0,(a2)+                        ; x into ptsin
	addq.l	#2,a2                           ; skip the y slot
.float_x_next:
	subq.w	#1,(sp)
	bpl.s	.float_x                        ; next element
	addq.l	#2,sp                           ; drop the count
	bra.s	.y
.int_x:
	move.l	(a0)+,d2                        ; integer element
	add.w	d1,d2                           ; + offset
	move.w	d2,(a2)+                        ; x into ptsin
	addq.l	#2,a2                           ; skip the y slot
.int_x_next:
	dbra	d0,.int_x
.y:
	lea	$40e(a4),a2                     ; back to ptsin
	movea.l	a1,a0                           ; the y array
	movea.l	(a0)+,a0                        ; a0 = y array data
	addq.l	#4,a0                           ; skip the element count
	move.w	(sp),d0                         ; d0 = n
	cmpa.l	$88(a4),a1                      ; integer array?
	bcc.s	.int_y_start
	move.w	d0,-(sp)                        ; count on the stack for the float loop
.float_y:
	jsr	rn_float_load(a6)               ; unpack the element
	jsr	rn_float_to_long(a6)            ; float to integer
	add.w	$856(a4),d0                     ; + y offset
	addq.l	#2,a2                           ; skip the x slot
	move.w	d0,(a2)+                        ; y into ptsin
	subq.w	#1,(sp)
	bne.s	.float_y                        ; next element
	addq.l	#2,sp                           ; drop the count
	bra.s	.call
.int_y_start:
	move.w	$856(a4),d1                     ; + y offset
	bra.s	.int_y_next
.int_y:
	move.l	(a0)+,d2                        ; integer element
	add.w	d1,d2                           ; + y offset
	addq.l	#2,a2                           ; skip the x slot
	move.w	d2,(a2)+                        ; y into ptsin
.int_y_next:
	dbra	d0,.int_y
.call:
	moveq	#0,d1                           ; no intin
	move.w	(sp)+,d2                        ; points
	move.w	(sp)+,d0                        ; opcode
	jmp	rn_vdi_call_intin_ptsin(a6)     ; VDI call (05980)

;------------------------------------------------------------------------------
; Runtime: BITBLT s%(),d%(),p%(): three one-dimensional integer arrays (else error 28):
; d0's array into the source MFDB $79a(a4), a1's into the destination
; $7c2(a4) (address and 5 words each), the 8 coordinates and the mode from a0's into ptsin and intin; vro_cpyfm
; ($22(a6)).
;------------------------------------------------------------------------------
rt_bitblt:
	movea.l	(a1)+,a2                        ; a2 = data of the array at a1
	cmpi.w	#$1,(a1)                        ; one dimension?
	bne.s	.bitblt_bad_array
	movem.l	4(a2),d1-d6                     ; address and 5 words
	move.l	d1,$7c2(a4)                     ; into the MFDB at $7d2(a4)
	movem.w	d2-d6,$7c6(a4)
	movea.l	d0,a1                           ; the array at d0
	movea.l	(a1)+,a2                        ; a2 = its data
	cmpi.w	#$1,(a1)
	bne.s	.bitblt_bad_array
	movem.l	4(a2),d1-d6                     ; address and 5 words
	move.l	d1,$79a(a4)                     ; into the MFDB at $7aa(a4)
	movem.w	d2-d6,$79e(a4)
	movea.l	(a0)+,a2                        ; a2 = data of the array at a0
	cmpi.w	#$1,(a0)                        ; one dimension?
	bne.s	.bitblt_bad_array
	movem.l	4(a2),d0-d7/a0                  ; 8 coordinates and the mode
	movem.w	d0-d7,$40e(a4)
	move.w	a0,$30e(a4)                     ; intin[0] = mode
	jmp	rn_vro_cpyfm(a6)                ; vro_cpyfm (07e5e)
.bitblt_bad_array:
	moveq	#28,d0                          ; error 28
	jmp	rn_error_entry(a6)              ; raise error d0

;------------------------------------------------------------------------------
; Runtime: DRAW: the points of a DRAW statement into ptsin, the last point $852(a4) first.
;------------------------------------------------------------------------------
rt_draw_from_last:
	lea	$40e(a4),a0                     ; ptsin
	move.l	$852(a4),(a0)+                  ; the last point first

;------------------------------------------------------------------------------
; Runtime: DRAW with d7 points on the stack: d2 = the point count.
;------------------------------------------------------------------------------
rt_draw_points:
	move.w	d7,d2                           ; points + 1
	addq.w	#1,d2                           ; one more for the last point
	bra.s	rt_draw_pline

;------------------------------------------------------------------------------
; Runtime: DRAW TO / DRAW with d7 points packed as longs on the stack (one point is drawn
; from the last point, as two); they are added to the origin, put into ptsin from a0, the last
; one kept at $862(a4), then v_pline (VDI 6). The return address is taken off first and pushed
; back over the points.
;------------------------------------------------------------------------------
rt_draw:
	lea	$40e(a4),a0                     ; ptsin
	cmpi.w	#$1,d7                          ; one point: draw from the last point
	bne.s	.count
	move.l	(sp),-(sp)                      ; duplicate the return address
	move.l	8(sp),4(sp)                     ; the point twice: a one-point line
	moveq	#2,d7                           ; two points
.count:
	move.w	d7,d2                           ; d2 = point count

;------------------------------------------------------------------------------
; Runtime: the DRAW v_pline: d7 = points on the stack under the return address, d2 = ptsin
; point count, a0 = where they go in ptsin. Moves the points into ptsin with the origin
; added, keeps the last at $862(a4) and calls v_pline (VDI 6).
;------------------------------------------------------------------------------
rt_draw_pline:
	movea.l	(sp)+,a2                        ; return address
	move.w	d7,d6
	asl.w	#2,d6                           ; 4 bytes a point
	adda.w	d6,sp                           ; drop them
	movea.l	sp,a1                           ; a1 = past the points
	subq.w	#1,d7                           ; count - 1 for dbra
.point:
	move.l	-(a1),d0                        ; point, x in the high word
	swap	d0
	add.l	$b32(a4),d0                     ; + origin
	move.l	d0,(a0)+                        ; into ptsin
	dbra	d7,.point                       ; next point
	move.l	d0,$852(a4)                     ; kept for the next DRAW
	pea	(a2)                            ; return address back
	moveq	#6,d0                           ; VDI 6 v_pline
	moveq	#0,d1                           ; no intin
	jmp	rn_vdi_call_intin_ptsin(a6)     ; VDI call (05980)

;------------------------------------------------------------------------------
; Runtime: writes a GEMDOS date word as dd.mm.yyyy at a0 ($89(a6)): day and month with
; $8b(a6) (089d4), the year (+1980) as century and year with $8a(a6) (089d2).
;------------------------------------------------------------------------------
rt_write_date_word:
	movea.l	a0,a1                           ; a1 = the buffer
	move.w	d0,d1                           ; d1 = the date word
	andi.w	#$1f,d0                         ; day
	jsr	rn_two_digits(a6)               ; two digits (089d4)
	move.b	#$2e,(a1)+                      ; '.'
	move.w	d1,d0
	lsr.w	#5,d0                           ; month bits to the bottom
	andi.w	#$f,d0                          ; month
	jsr	rn_two_digits(a6)               ; two digits (089d4)
	move.b	#$2e,(a1)+                      ; '.'
	rol.w	#7,d1                           ; year bits to the bottom
	andi.l	#$7f,d1
	addi.l	#$7bc,d1                        ; + 1980
	divu.w	#$64,d1                         ; century and year in century
	jsr	rn_two_digits_d1(a6)            ; century: two digits (089d2)
	swap	d1                              ; remainder: year in the century
	jmp	rn_two_digits_d1(a6)            ; year: two digits

;------------------------------------------------------------------------------
; Runtime: SETTIME: a0 = the date string "dd.mm.yy[yy]", a1 = the time string "hh:mm[:ss]".
; The date (day <= 31, month <= 12, year <= 2107; two-digit years 80..99 are 1980.., 0..79 2000..)
; is set with Tsetdate, the time with Tsettime; a part that does not parse is skipped.
;------------------------------------------------------------------------------
rt_settime:
	move.l	a1,d6                           ; keep the time string
	jsr	rn_string_text_len_212(a6)      ; the date string
	moveq	#31,d2                          ; day <= 31
	bsr.w	rt_settime_number
	ble.s	.time                           ; bad day: go on to the time
	move.w	d1,d3                           ; d3 = day in bits 0-4
	cmpi.b	#$2e,(a1)+                      ; '.'
	bne.s	.time
	subq.w	#1,d0                           ; count the '.'
	beq.s	.time                           ; nothing after it
	moveq	#12,d2                          ; month <= 12
	bsr.w	rt_settime_number
	ble.s	.time                           ; bad month
	asl.w	#5,d1                           ; month into bits 5-8
	or.w	d1,d3
	cmpi.b	#$2e,(a1)+                      ; '.'
	bne.s	.time                           ; no '.': skip the date
	subq.w	#1,d0                           ; count the '.'
	beq.s	.time                           ; nothing after it
	move.w	#$83b,d2                        ; year <= 2107
	bsr.s	rt_settime_number
	bmi.s	.time                           ; bad year
	subi.w	#$7bc,d1                        ; - 1980
	bpl.s	.year                           ; 1980 or later
	addi.w	#$7bc,d1                        ; before 1980: a two-digit year?
	cmpi.w	#$7f,d1
	bhi.s	.time                           ; above 127: no date
	subi.w	#$50,d1                         ; 80..99: 1980..1999
	bpl.s	.year
	addi.w	#$64,d1                         ; 0..79: 2000..2079
.year:
	ror.w	#7,d1                           ; year into bits 9-15
	or.w	d1,d3
	move.w	d3,-(sp)                        ; the date word
	move.w	#$2b,-(sp)                      ; GEMDOS $2b Tsetdate
	trap	#1                              ; Tsetdate
	addq.l	#4,sp                           ; drop the arguments
.time:
	movea.l	d6,a0                           ; the time string
	jsr	rn_string_text_len_212(a6)      ; a1 = text, d0 = length
	moveq	#23,d2                          ; hours <= 23
	bsr.s	rt_settime_number
	bmi.s	.done                           ; bad hours: nothing set
	ror.w	#5,d1                           ; hours into bits 11-15
	move.w	d1,d3
	cmpi.b	#$3a,(a1)                       ; ':'
	bne.s	.minutes
	addq.l	#1,a1                           ; skip it
	subq.w	#1,d0                           ; count it
	beq.s	.done                           ; nothing after it
.minutes:
	moveq	#59,d2                          ; minutes <= 59
	bsr.s	rt_settime_number
	bmi.s	.done                           ; bad minutes: nothing set
	asl.w	#5,d1                           ; minutes into bits 5-10
	or.w	d1,d3
	cmpi.b	#$3a,(a1)                       ; ':'?
	bne.s	.seconds
	addq.l	#1,a1                           ; skip it
	subq.w	#1,d0                           ; count it
	beq.s	.set_time                       ; no seconds
.seconds:
	moveq	#59,d2                          ; seconds <= 59
	bsr.s	rt_settime_number
	bmi.s	.set_time                       ; bad seconds: set what there is
	lsr.w	#1,d1                           ; seconds / 2 into bits 0-4
	or.w	d1,d3
.set_time:
	move.w	d3,-(sp)                        ; the time word
	move.w	#$2d,-(sp)                      ; GEMDOS $2d Tsettime
	trap	#1                              ; Tsettime
	addq.l	#4,sp                           ; drop the arguments
.done:
	rts

;------------------------------------------------------------------------------
; Runtime: reads a number from a1 (d0 = characters left) for SETTIME: at most d2 (for d2 < 100
; two digits), stopping before '.' or ':'. Exit d1 = the value, -1 when it is bad; flags of d1.
;------------------------------------------------------------------------------
rt_settime_number:
	moveq	#0,d1                           ; d1 = value
	moveq	#0,d4                           ; d4 = next character
	subq.w	#1,d0                           ; no characters left
	bmi.s	.bad
	move.b	(a1)+,d1                        ; first character
	subi.b	#$30,d1                         ; first digit
	cmpi.b	#$9,d1                          ; a digit?
	bhi.s	.bad                            ; no: bad
	subq.w	#1,d0                           ; one character used
	bpl.s	.digit                          ; more to come
.bad:
	moveq	#-1,d1                          ; bad: -1
	rts
.digit:
	move.b	(a1)+,d4                        ; next character
	cmpi.b	#$2e,d4                         ; '.' ends the number
	beq.s	.separator
	cmpi.b	#$3a,d4                         ; ':' ends the number
	beq.s	.separator
	subi.b	#$30,d4                         ; a digit?
	cmpi.b	#$9,d4
	bhi.s	.bad                            ; no: bad
	mulu.w	#$a,d1                          ; * 10 + digit
	add.w	d4,d1
	cmp.w	d2,d1                           ; above the maximum: bad
	bhi.s	.bad
	cmpi.w	#$64,d2                         ; two digits unless the maximum is 100 or more
	bcs.s	.end                            ; maximum below 100: two digits only
	subq.w	#1,d0                           ; one character used
	bpl.s	.digit                          ; more digits
.end:
	tst.w	d1                              ; value, flags set
	rts
.separator:
	subq.l	#1,a1                           ; leave the separator
	addq.w	#1,d0                           ; that character not used
	tst.w	d1                              ; value, flags set
	rts

;------------------------------------------------------------------------------
; Runtime: gives the string variable whose descriptor is at a0 a string of d0 bytes ($45(a6)).
; Exit a1 = the text. When the length is the same the old text is kept; otherwise the old one is
; marked free (the long after it becomes minus its size) and a new block of the length + 4 (the
; back pointer to the descriptor), even, is taken below $60(a4). Below the top of the control
; stack (a3) the garbage collector runs ($203(a6)); still no room: error 8 Out of memory.
; Length 0 takes no memory; a negative length is error 10 String too long.
;------------------------------------------------------------------------------
rt_string_alloc_var:
	move.w	4(a0),d1                        ; length of the old string
	beq.s	rt_string_alloc_new             ; none: take a new one
	movea.l	(a0),a1                         ; a1 = old text
	cmp.w	d0,d1                           ; same length: keep it
	beq.s	rt_string_alloc_done
	addq.w	#1,d1                           ; old length, even
	andi.b	#$fe,d1
	adda.w	d1,a1                           ; a1 = its back pointer
	neg.w	d1
	ext.l	d1
	move.l	d1,(a1)                         ; free mark: minus the size

;------------------------------------------------------------------------------
; Runtime: takes a new string block of d0 bytes below $60(a4) for the descriptor at a0.
;------------------------------------------------------------------------------
rt_string_alloc_new:
	movea.l	$60(a4),a1                      ; bottom of the string area
	moveq	#0,d1
	move.w	d0,d1                           ; d1 = length
	ble.s	rt_string_alloc_empty           ; 0 or negative
	addq.w	#5,d1                           ; + back pointer, even
	andi.b	#$fe,d1
	suba.l	d1,a1                           ; a1 = start of the new block
	cmpa.l	a3,a1                           ; below the control stack top?
	bcs.s	rt_string_alloc_collect         ; yes: garbage collect

rt_string_alloc_set:
	move.l	a1,(a0)                         ; descriptor: address
	move.w	d0,4(a0)                        ; and length
	move.l	a0,-$4(a1,d1.l)                 ; back pointer to the descriptor
	move.l	a1,$60(a4)                      ; new bottom

rt_string_alloc_done:
	rts

;------------------------------------------------------------------------------
; Runtime: length 0: only the descriptor's length is set.
;------------------------------------------------------------------------------
rt_string_alloc_empty:
	bmi.s	.too_long                       ; negative: too long
	move.w	d0,4(a0)                        ; length 0
	rts
.too_long:
	moveq	#10,d0                          ; error 10 String too long
	jmp	rn_error_entry(a6)

;------------------------------------------------------------------------------
; Runtime: no room: garbage collection ($203(a6)) and one more try, then error 8.
;------------------------------------------------------------------------------
rt_string_alloc_collect:
	jsr	rn_string_garbage_collect(a6)   ; garbage collection (08504)
	movea.l	$60(a4),a1                      ; bottom of the string area
	suba.l	d1,a1                           ; a1 = start of the new block
	cmpa.l	a3,a1                           ; still below the control stack top?
	bcc.s	rt_string_alloc_set             ; no: room now
	moveq	#8,d0                           ; error 8 Out of memory
	jmp	rn_error_entry(a6)              ; raise error d0

;------------------------------------------------------------------------------
; Runtime: a temporary string of d0 bytes ($47(a6)): takes the first free descriptor of the
; 101 at $884(a4) (6 bytes each, free = negative length) and gives it a block as 8472 does.
; Exit a0 = the descriptor, a1 = the text. None free: error 97 (no text for it in the message
; list).
;------------------------------------------------------------------------------
rt_temp_string_alloc:
	lea	$874(a4),a0                     ; the temporary descriptors
	moveq	#100,d1                         ; 101 of them

rt_temp_string_find:
	tst.w	4(a0)                           ; free (negative length)?
	bmi.s	rt_string_alloc_new

rt_temp_string_next:
	addq.l	#6,a0
	dbra	d1,rt_temp_string_find          ; next descriptor
	moveq	#97,d0                          ; error 97
	jmp	rn_error_entry(a6)              ; raise error d0

;------------------------------------------------------------------------------
; Runtime: string garbage collection ($203(a6)). Walks the string area from its top $64(a4)
; down to $60(a4): each block ends with a long, the back pointer to its descriptor (live) or
; minus its size (free). From the first free block on, the live strings are moved up over the
; free space, their back pointers and descriptor addresses updated; $60(a4) becomes the new
; bottom. Keeps all registers.
;------------------------------------------------------------------------------
rt_string_garbage_collect:
	movem.l	d0/a0-a3,-(sp)                  ; keep the registers
	movea.l	$64(a4),a0                      ; a0 = top of the string area
	movea.l	$60(a4),a2                      ; a2 = bottom
.scan:
	movea.l	a0,a1                           ; a1 = where live strings go
	cmpa.l	a0,a2                           ; reached the bottom: nothing free
	beq.s	.gc_done
	move.l	-(a0),d0                        ; the long at the block's end
	bmi.s	.skip_free                      ; negative: a free block
	movea.l	d0,a3                           ; a3 = its descriptor
	movea.l	(a3),a0                         ; live: skip down to its start
	bra.s	.scan
.skip_free:
	adda.l	d0,a0                           ; skip the free block
	cmpa.l	a0,a2                           ; reached the bottom?
	beq.s	.new_bottom
.move:
	move.l	-(a0),d0                        ; next block
	bmi.s	.skip_free
	move.l	d0,-(a1)                        ; back pointer moved up
	movea.l	d0,a3                           ; a3 = its descriptor
	move.w	4(a3),d0                        ; length
	subq.w	#1,d0                           ; in words
	lsr.w	#1,d0
.move_word:
	move.w	-(a0),-(a1)                     ; move the text up
	dbra	d0,.move_word
	move.l	a1,(a3)                         ; the descriptor's new address
	cmpa.l	a0,a2                           ; reached the bottom?
	bne.s	.move                           ; no: next block
.new_bottom:
	move.l	a1,$60(a4)                      ; new bottom of the string area
.gc_done:
	movem.l	(sp)+,d0/a0-a3
	rts

;------------------------------------------------------------------------------
; Runtime: INKEY$: Crawio($ff). No key: the empty string (the descriptor at $ae2(a4)); a key
; with an ASCII code: CHR$ of it ($42(a6) = 08562); otherwise a 2-byte string 0, scan code
; ($48(a6)).
;------------------------------------------------------------------------------
rt_inkey:
	move.w	#$ff,-(sp)                      ; read a key, no wait
	move.w	#$6,-(sp)                       ; GEMDOS 6 Crawio
	trap	#1                              ; Crawio
	addq.l	#4,sp                           ; drop the arguments
	tst.l	d0                              ; d0 = 0: no key
	beq.s	.no_key                         ; no key
	tst.b	d0                              ; ASCII code in the low byte
	beq.s	.special_key                    ; no ASCII code
	jmp	rn_chr(a6)                      ; CHR$ (0857a)
.special_key:
	lea	$95(a4),a0                      ; 2-byte string: 0, scan code
	swap	d0                              ; scan code from the high word
	move.b	d0,(a0)                         ; second byte: the scan code
	clr.b	-(a0)                           ; first byte: 0
	moveq	#2,d0                           ; 2 bytes
	jmp	rn_temp_string_copy(a6)         ; temporary string from a0 (085b4)
.no_key:
	lea	$ad2(a4),a0                     ; the empty string
	rts

;------------------------------------------------------------------------------
; Runtime: CHR$(d0): 1-byte temporary string ($48(a6) = 0859c) from $94(a4). 856e MKI$(d0)
; (2 bytes), 857a MKL$(d0) (4 bytes), 8586 MKF$ (the float packed, $f3(a6) = 061be, 6 bytes).
;------------------------------------------------------------------------------
rt_chr:
	lea	$94(a4),a0                      ; 1 byte
	move.b	d0,(a0)
	moveq	#1,d0                           ; 1 byte
	jmp	rn_temp_string_copy(a6)         ; temporary string from a0 (085b4)

rt_mki:
	lea	$94(a4),a0
	move.w	d0,(a0)                         ; 2 bytes
	moveq	#2,d0
	jmp	rn_temp_string_copy(a6)         ; temporary string from a0 (085b4)

rt_mkl:
	lea	$94(a4),a0
	move.l	d0,(a0)                         ; 4 bytes
	moveq	#4,d0
	jmp	rn_temp_string_copy(a6)         ; temporary string from a0 (085b4)

rt_mkf:
	jsr	rn_float_round_packed(a6)       ; pack the float (061d6)
	lea	$98(a4),a0                      ; 6 bytes
	move.w	d1,(a0)                         ; low word
	move.l	d0,-(a0)                        ; high long
	moveq	#6,d0
	jmp	rn_temp_string_copy(a6)         ; temporary string from a0 (085b4)

;------------------------------------------------------------------------------
; Runtime: STR$ of the float d0-d2: formats it ($f8(a6) = 060da) and makes a temporary string
; of it. 859c ($48(a6)): a temporary string of the d0 bytes at a0 ($47(a6), copied by words).
;------------------------------------------------------------------------------
rt_str:
	jsr	rn_float_to_string(a6)          ; format the float (060f2): a0 = text, d0 = length

rt_temp_string_copy:
	move.l	a0,d2                           ; the source
	jsr	rn_temp_string_alloc(a6)        ; temporary of d0 bytes (084ec)
	movea.l	d2,a2                           ; a2 = source
	subq.w	#1,d0                           ; length 0?
	bmi.s	.temp_done                      ; yes: nothing to copy
	lsr.w	#1,d0                           ; in words
.temp_copy:
	move.w	(a2)+,(a1)+
	dbra	d0,.temp_copy
.temp_done:
	rts

;------------------------------------------------------------------------------
; Runtime: the text of a string ($212(a6)): a0 = its descriptor. Exit a1 = text, d0.l = length.
; A temporary (a descriptor below $ad2(a4)) is freed as it is read: its descriptor is marked
; free (st) and its block gets the free mark; the text stays readable until the next string
; is made.
;------------------------------------------------------------------------------
rt_string_text_len:
	moveq	#0,d0                           ; length high word 0
	lea	$ad2(a4),a1                     ; end of the temporary descriptors
	cmpa.l	a1,a0                           ; a variable's descriptor?
	bcc.s	.variable
	movea.l	(a0)+,a1                        ; a1 = text
	move.w	(a0),d0                         ; d0 = length
	st	(a0)                            ; temporary: descriptor free
	beq.s	.free_done                      ; empty: no block
	move.l	d0,d1                           ; length, even
	addq.w	#1,d1
	andi.b	#$fe,d1
	move.l	d1,d2                           ; free mark: minus the size
	neg.l	d2
	move.l	d2,0(a1,d1.w)
.free_done:
	rts
.variable:
	movea.l	(a0)+,a1                        ; a variable: text and length only
	move.w	(a0),d0
	rts

;------------------------------------------------------------------------------
; Runtime: ASC(a$): d0 = the first byte, 0 for an empty string. 85ea CVI(a$) (a word, 0 when
; shorter than 2), 85fa CVL(a$) (a long), 860a CVF(a$) (6 bytes unpacked, $f2(a6), 0.0 when
; shorter).
;------------------------------------------------------------------------------
rt_asc:
	jsr	rn_string_text_len_212(a6)      ; a1 = text, d0 = length
	tst.w	d0                              ; empty?
	beq.s	.asc_done                       ; yes: d0 = 0
	moveq	#0,d0
	move.b	(a1),d0                         ; first byte
.asc_done:
	rts

rt_cvi:
	jsr	rn_string_text_len_212(a6)
	subq.w	#2,d0                           ; at least 2 bytes?
	bmi.s	.cvi_short                      ; shorter: 0
	move.w	(a1),d0                         ; d0 = the word
	rts
.cvi_short:
	moveq	#0,d0                           ; too short: 0
	rts

rt_cvl:
	jsr	rn_string_text_len_212(a6)
	subq.w	#4,d0                           ; at least 4 bytes?
	bmi.s	.cvl_short                      ; shorter: 0
	move.l	(a1),d0                         ; d0 = the long
	rts
.cvl_short:
	moveq	#0,d0                           ; too short: 0
	rts

rt_cvf:
	jsr	rn_string_text_len_212(a6)
	subq.l	#6,d0                           ; at least 6 bytes?
	bmi.s	.cvf_short                      ; shorter: 0.0
	move.l	(a1)+,d0                        ; d0 = first long
	move.w	(a1),d1                         ; d1 = last word
	jmp	rn_float_unpack(a6)             ; unpack d0/d1 ($f2(a6), not identified in this range)
.cvf_short:
	moveq	#0,d2                           ; 0.0
	rts

;------------------------------------------------------------------------------
; Runtime: an empty temporary string ($47(a6) with length 0).
;------------------------------------------------------------------------------
rt_temp_string_empty:
	moveq	#0,d0                           ; length 0
	jmp	rn_temp_string_alloc(a6)        ; temporary (084ec)

;------------------------------------------------------------------------------
; Runtime: a string constant that follows the call ([length.w][characters]): returns past it
; and makes a temporary string of it ($48(a6)). 8624 for an even length, 8630 an odd length
; (one pad byte).
;------------------------------------------------------------------------------
rt_string_const_even:
	movea.l	(sp)+,a0                        ; a0 = the constant after the call
	move.w	(a0)+,d0                        ; length
	pea	0(a0,d0.w)                      ; return past the characters
	jmp	rn_temp_string_copy(a6)         ; temporary string from them (085b4)

rt_string_const_odd:
	movea.l	(sp)+,a0
	move.w	(a0)+,d0
	pea	1(a0,d0.w)                      ; odd length: one pad byte
	jmp	rn_temp_string_copy(a6)

;------------------------------------------------------------------------------
; Runtime: PRINT of a string constant that follows the call: returns past it and prints it
; ($211(a6)); 863c even, 864a odd length.
;------------------------------------------------------------------------------
rt_print_const_even:
	moveq	#0,d0                           ; length high word 0
	movea.l	(sp)+,a1                        ; a1 = the constant after the call
	move.w	(a1)+,d0                        ; d0 = length
	pea	0(a1,d0.l)                      ; return past it
	jmp	rn_print_text(a6)               ; print it (06d6a)

rt_print_const_odd:
	moveq	#0,d0
	movea.l	(sp)+,a1
	move.w	(a1)+,d0                        ; d0 = length
	pea	1(a1,d0.l)                      ; odd length: one pad byte
	jmp	rn_print_text(a6)               ; print it (06d6a)

;------------------------------------------------------------------------------
; Runtime: string assignment: a0 = the source descriptor, a1 = the variable's. A variable
; source (at or above $ad2(a4)) is copied into a new string of the same length ($45(a6)); a
; temporary is taken over instead: the variable's old string is marked free, the descriptor
; gets the temporary's text and length, the temporary descriptor is freed and the back pointer
; after the text is pointed at the variable.
;------------------------------------------------------------------------------
rt_string_assign:
	lea	$ad2(a4),a2                     ; end of the temporary descriptors
	cmpa.l	a2,a0                           ; source a temporary?
	bcs.s	.take_temp
	exg	a1,a0                           ; a0 = the variable
	pea	(a1)                            ; keep the source
	move.w	4(a1),d0                        ; source length
	jsr	rn_string_alloc_var(a6)         ; a string of that length for the variable (0848a)
	movea.l	(sp)+,a2                        ; a2 = source descriptor
	movea.l	(a2)+,a2                        ; source text
	addq.w	#1,d0                           ; in words
	lsr.w	#1,d0
	bra.s	.assign_copy_next
.assign_copy:
	move.w	(a2)+,(a1)+                     ; copy a word
.assign_copy_next:
	dbra	d0,.assign_copy
	rts
.take_temp:
	movea.l	(a1)+,a2                        ; the variable's old string
	move.w	(a1),d0                         ; d0 = old length
	beq.s	.free_temp                      ; none
	ext.l	d0
	addq.w	#1,d0                           ; old length, even
	andi.w	#$fffe,d0
	move.l	d0,d1                           ; even length
	neg.l	d1                              ; minus the size
	move.l	d1,0(a2,d0.l)                   ; free mark after it
.free_temp:
	movea.l	(a0)+,a2                        ; the temporary's text
	move.w	(a0),d0
	st	(a0)                            ; temporary descriptor free
	move.w	d0,(a1)                         ; the variable's length
	beq.s	.assign_done
	move.l	a2,-(a1)                        ; and address
	addq.w	#1,d0
	andi.l	#$fffe,d0
	move.l	a1,0(a2,d0.l)                   ; back pointer to the variable
.assign_done:
	rts

;------------------------------------------------------------------------------
; Runtime: string compare ($16(a6)): a0 and a1 the descriptors (temporaries are freed).
; Compares the bytes of the shorter length, then the lengths; exit flags for a0's string
; against a1's (unsigned).
;------------------------------------------------------------------------------
rt_string_compare:
	moveq	#0,d0                           ; length high words 0
	lea	$ad2(a4),a2                     ; end of the temporary descriptors
	move.l	a2,d2                           ; d2 = end of the temporaries
	movea.l	(a0)+,a2                        ; a2 = first text
	move.w	(a0),d0                         ; d0 = first length
	cmpa.l	d2,a0                           ; a temporary?
	bcc.s	rt_strcmp_second
	st	(a0)                            ; free its descriptor
	move.l	d0,d7                           ; d7 = length
	beq.s	rt_strcmp_second                ; empty: no block
	addq.w	#1,d7                           ; + 1 ...

;------------------------------------------------------------------------------
; Runtime: string compare, first string a temporary: d7 = its length + 1 made even, the
; free mark (minus the size) written after its text.
;------------------------------------------------------------------------------
rt_strcmp_free_first:
	andi.b	#$fe,d7                         ; ... even
	move.l	d7,d6
	neg.l	d6                              ; minus the size
	move.l	d6,0(a2,d7.w)                   ; free mark after the text

;------------------------------------------------------------------------------
; Runtime: string compare, the second string (a1): its text to a0, length to d1, freed if
; a temporary; then the byte compare of the shorter length and the length compare.
;------------------------------------------------------------------------------
rt_strcmp_second:
	moveq	#0,d1                           ; length high word 0
	movea.l	(a1)+,a0                        ; a0 = second text
	move.w	(a1),d1                         ; d1 = second length
	cmpa.l	d2,a1                           ; a temporary?
	bcc.s	.lengths                        ; no
	st	(a1)                            ; free its descriptor
	move.l	d1,d7                           ; d7 = length
	beq.s	.lengths                        ; empty: no block
	addq.w	#1,d7                           ; + 1, even
	andi.b	#$fe,d7
	move.l	d7,d6
	neg.l	d6                              ; minus the size
	move.l	d6,0(a0,d7.w)                   ; free mark after the text
.lengths:
	move.w	d0,d2                           ; the shorter length
	cmp.w	d1,d2
	bcs.s	.compare                        ; first shorter: d2 = first length
	move.w	d1,d2                           ; else the second length
.compare:
	moveq	#0,d3
	bra.s	.byte_next
.byte:
	cmpm.b	(a0)+,(a2)+                     ; first - second, byte by byte
.byte_next:
	dbne	d2,.byte
	bne.s	.done                           ; a difference
	cmp.w	d1,d0                           ; equal so far: by length
.done:
	rts

;------------------------------------------------------------------------------
; Runtime: string comparisons as booleans in d2 (-1 / 0): 8708 =, 8712 <>, 871c <, 8726 <=,
; 8730 >, 873a >= (string compare $16(a6), then scc).
;------------------------------------------------------------------------------
rt_string_eq:
	jsr	rn_string_compare(a6)           ; string compare (086c6)
	seq	d2                              ; =
	ext.w	d2                              ; word boolean -1 / 0
	rts

rt_string_ne:
	jsr	rn_string_compare(a6)
	sne	d2                              ; <>
	ext.w	d2                              ; word boolean -1 / 0
	rts

rt_string_lt:
	jsr	rn_string_compare(a6)
	scs	d2                              ; <
	ext.w	d2                              ; word boolean -1 / 0
	rts

rt_string_le:
	jsr	rn_string_compare(a6)
	sls	d2                              ; <=
	ext.w	d2                              ; word boolean -1 / 0
	rts

rt_string_gt:
	jsr	rn_string_compare(a6)
	shi	d2                              ; >
	ext.w	d2                              ; word boolean -1 / 0
	rts

rt_string_ge:
	jsr	rn_string_compare(a6)
	scc	d2                              ; >=
	ext.w	d2                              ; word boolean -1 / 0
	rts

;------------------------------------------------------------------------------
; Runtime: LEFT$(a$) (1 character): CHR$ of the first byte; an empty string is returned as it
; is. 8756 RIGHT$(a$): the last byte.
;------------------------------------------------------------------------------
rt_left_one:
	tst.w	4(a0)                           ; empty: return it
	beq.s	.left_empty
	jsr	rn_string_text_len_212(a6)      ; a1 = text
	move.b	(a1),d0                         ; first byte
	jmp	rn_chr(a6)                      ; CHR$ (0857a)
.left_empty:
	rts                                     ; a0 = the empty string

rt_right_one:
	tst.w	4(a0)
	beq.s	.right_empty
	jsr	rn_string_text_len_212(a6)      ; a1 = text, d0 = length
	move.b	-$1(a1,d0.w),d0                 ; last byte
	jmp	rn_chr(a6)                      ; CHR$ (0857a)
.right_empty:
	rts                                     ; a0 = the empty string

;------------------------------------------------------------------------------
; Runtime: LEFT$(a$,n): a1 = a$, d0 = n. n at least the length: a$ itself (a0); otherwise a
; temporary of n bytes copied from the start, and a$ is freed if it was a temporary.
;------------------------------------------------------------------------------
rt_left:
	movea.l	a1,a0                           ; a0 = a$
	cmp.w	4(a0),d0                        ; n at least the length: a$ itself
	bcc.s	.whole
	move.l	a0,d5                           ; d5 = a$
	jsr	rn_temp_string_alloc(a6)        ; temporary of n bytes (084ec)
	movea.l	d5,a2                           ; a2 = a$ descriptor
	movea.l	(a2),a2                         ; a$'s text
	addq.w	#1,d0
	lsr.w	#1,d0                           ; in words
	bra.s	.left_copy_next
.left_copy:
	move.w	(a2)+,(a1)+                     ; copy a word
.left_copy_next:
	dbra	d0,.left_copy
	exg	d5,a0                           ; a0 = a$, d5 = the result
	jsr	rn_string_text_len_212(a6)      ; free a$ if temporary (085ca)
	movea.l	d5,a0                           ; a0 = the result
.whole:
	rts                                     ; a0 = the result

;------------------------------------------------------------------------------
; Runtime: RIGHT$(a$,n): as LEFT$ but the last n bytes.
;------------------------------------------------------------------------------
rt_right:
	movea.l	a1,a0                           ; a0 = a$
	cmp.w	4(a0),d0                        ; n at least the length: a$ itself
	bcc.s	rt_right_done
	move.l	a0,d5                           ; d5 = a$
	jsr	rn_temp_string_alloc(a6)        ; temporary of n bytes
	movea.l	d5,a2                           ; a2 = a$ descriptor
	move.w	4(a2),d4                        ; a$'s length
	movea.l	(a2),a2                         ; a2 = a$ text
	adda.w	d4,a2                           ; end of a$
	adda.w	d0,a1                           ; end of the result
	bra.s	.right_copy_next
.right_copy:
	move.b	-(a2),-(a1)                     ; copy backwards
.right_copy_next:
	dbra	d0,.right_copy

;------------------------------------------------------------------------------
; Runtime: RIGHT$ end: frees a$ if it was a temporary (085ca) and returns the result in a0.
;------------------------------------------------------------------------------
rt_right_free_source:
	exg	d5,a0                           ; a0 = a$, d5 = the result
	jsr	rn_string_text_len_212(a6)      ; free a$ if temporary
	movea.l	d5,a0                           ; a0 = the result

rt_right_done:
	rts                                     ; a0 = the result

;------------------------------------------------------------------------------
; Runtime: MID$(a$,start) (87be, the rest of the string) and MID$(a$,start,n) (87c4: d0 = n,
; d1 = start, a1 = a$). Start 0 counts as 1; past the end gives an empty string; n is cut to
; what is left. The result is a temporary.
;------------------------------------------------------------------------------
rt_mid_rest:
	move.w	4(a1),d1                        ; no count: the length
	exg	d0,d1                           ; d0 = count, d1 = start

rt_mid:
	movea.l	a1,a0                           ; a0 = a$
	tst.w	d1                              ; start 0?
	bne.s	.start                          ; start 0 counts as 1
	moveq	#1,d1
.start:
	move.w	4(a0),d2                        ; characters from the start on
	sub.w	d1,d2                           ; - start
	bcs.s	.past_end                       ; past the end
	addq.w	#1,d2                           ; + 1: characters from start on
	cmp.w	d2,d0                           ; cut the count
	bls.s	.take
	move.w	d2,d0
.take:
	move.l	a0,d5                           ; d5 = a$
	subq.w	#1,d1                           ; 0-based start
	move.w	d1,-(sp)
	jsr	rn_temp_string_alloc(a6)        ; temporary of d0 bytes
	movea.l	d5,a2                           ; a2 = a$ descriptor
	movea.l	(a2),a2                         ; a2 = a$ text
	adda.w	(sp)+,a2                        ; + start
	bra.s	.copy_next
.copy:
	move.b	(a2)+,(a1)+                     ; copy a byte
.copy_next:
	dbra	d0,.copy
	exg	d5,a0                           ; a0 = a$, d5 = the result
	jsr	rn_string_text_len_212(a6)      ; free a$ if temporary
	movea.l	d5,a0                           ; a0 = the result
	rts
.past_end:
	moveq	#0,d0                           ; empty result
	bra.s	.take

;------------------------------------------------------------------------------
; Runtime: string concatenation: a temporary of both lengths with a1's text then a0's text;
; both sources are freed if temporary.
;------------------------------------------------------------------------------
rt_string_concat:
	move.l	a0,d4                           ; d4 = a0's descriptor
	move.l	a1,d5                           ; d5 = a1's descriptor
	move.w	4(a0),d0                        ; first length
	add.w	4(a1),d0                        ; + second
	jsr	rn_temp_string_alloc(a6)        ; temporary for both (084ec)
	movea.l	d5,a2                           ; a1's string first
	move.l	(a2)+,d0                        ; d0 = text
	movea.w	(a2),a2                         ; a2 = length
	exg	d0,a2                           ; a2 = text, d0 = length
	bra.s	.copy_first_next
.copy_first:
	move.b	(a2)+,(a1)+                     ; copy a byte
.copy_first_next:
	dbra	d0,.copy_first
	movea.l	d4,a2                           ; then a0's
	move.l	(a2)+,d0                        ; d0 = text
	movea.w	(a2),a2                         ; a2 = length
	exg	d0,a2                           ; a2 = text, d0 = length
	bra.s	.copy_second_next
.copy_second:
	move.b	(a2)+,(a1)+                     ; copy a byte
.copy_second_next:
	dbra	d0,.copy_second
	exg	d5,a0                           ; a0 = a1's string, d5 = the result
	jsr	rn_string_text_len_212(a6)      ; free both if temporary
	movea.l	d4,a0                           ; a0 = a0's string
	jsr	rn_string_text_len_212(a6)
	movea.l	d5,a0                           ; a0 = the result
	rts

;------------------------------------------------------------------------------
; Runtime: VAL?(a$): d0 = the number of characters VAL can use.
;------------------------------------------------------------------------------
rt_val_used:
	bsr.s	rt_val                          ; VAL: a0 = characters used
	move.l	a0,d0                           ; d0 = characters used
	rts

;------------------------------------------------------------------------------
; Runtime: VAL(a$): the string is NUL-terminated for the parse, leading spaces skipped.
; &H/&O/&X (and & alone for hex) are read here as 32-bit integers and converted ($f0(a6));
; anything else goes to the decimal parser ($f4(a6) = 05e6a). Exit d0-d2 = the value (0 when
; nothing could be read or on overflow), a0 = the number of characters used.
;------------------------------------------------------------------------------
rt_val:
	jsr	rn_string_text_len_212(a6)      ; a1 = text, d0 = length
	movea.l	a1,a0
	pea	(a0)                            ; keep the start
	adda.w	d0,a1                           ; end of the text
	cmpa.l	a0,a1                           ; nothing?
	beq.s	.empty                          ; empty
	move.b	(a1),-(sp)                      ; keep the byte after it
	clr.b	(a1)                            ; NUL-terminate
.skip_spaces:
	cmpi.b	#$20,(a0)+                      ; skip spaces
	beq.s	.skip_spaces
	cmpi.b	#$26,-(a0)                      ; '&'
	beq.s	.prefix
	jsr	rn_text_to_float(a6)            ; decimal parse (05e82)
	move.b	(sp)+,(a1)                      ; put the byte back
.used:
	suba.l	(sp)+,a0                        ; characters used
	tst.w	d2                              ; parse failed?
	bpl.s	.val_done
.zero:
	moveq	#0,d2                           ; 0, nothing used
	movea.l	d2,a0
.val_done:
	rts
.empty:
	moveq	#0,d2                           ; empty: 0
	bra.s	.used
.prefix:
	addq.l	#1,a0                           ; after the '&'
	moveq	#0,d0                           ; d0 = value
	moveq	#-2,d2                          ; d2 = digit count - 2
	moveq	#0,d1
	move.b	(a0)+,d1                        ; the letter after '&'
	cmpi.b	#$61,d1                         ; upper case
	bcs.s	.base
	subi.b	#$20,d1
.base:
	cmpi.b	#$4f,d1                         ; 'O' octal
	beq.s	.octal
	cmpi.b	#$58,d1                         ; 'X' binary
	beq.s	.binary
	cmpi.b	#$48,d1                         ; 'H' hex
	beq.s	.hex
	subq.l	#1,a0                           ; no letter: hex digits follow
.hex:
	addq.w	#1,d2                           ; count a digit
	move.b	(a0)+,d1                        ; next character
	cmpi.b	#$61,d1                         ; upper case
	bcs.s	.hex_digit
	subi.b	#$20,d1
.hex_digit:
	cmpi.b	#$46,d1                         ; above 'F': end
	bhi.s	.number_end
	subi.b	#$30,d1                         ; '0'..
	bmi.s	.number_end                     ; below '0': end
	cmpi.b	#$9,d1                          ; 0-9
	bls.s	.hex_add
	subq.b	#7,d1                           ; A-F
	cmpi.b	#$9,d1                          ; between '9' and 'A': end
	bls.s	.number_end
.hex_add:
	cmpi.l	#$fffffff,d0                    ; would overflow 32 bits
	bhi.s	.overflow
	asl.l	#4,d0                           ; * 16 + digit
	or.b	d1,d0
	bra.s	.hex                            ; next
.overflow:
	moveq	#-1,d2                          ; overflow: bad
.number_end:
	move.b	(sp)+,(a1)                      ; put the byte back
	subq.l	#1,a0                           ; back to the character that ended it
	suba.l	(sp)+,a0                        ; characters used
	tst.w	d2                              ; no digits (d2 still negative)?
	bmi.s	.zero                           ; no digits or overflow: 0
	jmp	rn_long_to_float(a6)            ; integer to float (0632e)
.octal:
	addq.w	#1,d2                           ; count a digit
	move.b	(a0)+,d1                        ; next character
	subi.b	#$30,d1
	cmpi.b	#$7,d1                          ; 0-7
	bhi.s	.number_end                     ; not octal: end
	cmpi.l	#$1fffffff,d0                   ; would overflow
	bhi.s	.overflow
	asl.l	#3,d0                           ; * 8 + digit
	or.b	d1,d0
	bra.s	.octal                          ; next
.binary:
	addq.w	#1,d2                           ; count a digit
	move.b	(a0)+,d1                        ; next character
	subi.b	#$30,d1
	lsr.b	#1,d1                           ; 0 or 1 into X
	bne.s	.number_end
	addx.l	d0,d0                           ; shift the bit in; carry: overflow
	bcc.s	.binary                         ; no overflow: next
	bra.s	.overflow

;------------------------------------------------------------------------------
; Runtime: start of BIN$/HEX$/OCT$ ($87(a6)): a0 = a1 = the buffer $94(a4); for 0 it returns
; "0" directly to the caller's caller.
;------------------------------------------------------------------------------
rt_radix_start:
	lea	$94(a4),a0                      ; the buffer
	movea.l	a0,a1                           ; a1 = write pointer
	tst.l	d0
	bne.s	.not_zero                       ; not 0
	addq.l	#4,sp                           ; drop the return to the caller
	move.b	#$30,(a1)                       ; "0"
	moveq	#1,d0                           ; 1 character
	jmp	rn_temp_string_copy(a6)         ; temporary string from a0
.not_zero:
	rts

;------------------------------------------------------------------------------
; Runtime: BIN$(d0): the bits from the highest 1 down as '0'/'1'.
;------------------------------------------------------------------------------
rt_bin:
	jsr	rn_radix_start(a6)              ; buffer, 0 handled
	moveq	#31,d2                          ; 32 bits
.bin_skip:
	add.l	d0,d0                           ; skip leading zeros
	dbcs	d2,.bin_skip                    ; stop at the first 1
.bin_digit:
	moveq	#24,d1                          ; '0' + the bit (X)
	addx.b	d1,d1
	move.b	d1,(a1)+                        ; into the buffer
	add.l	d0,d0                           ; next bit into X
	dbra	d2,.bin_digit
	move.l	a1,d0                           ; length
	sub.l	a0,d0                           ; d0 = length
	jmp	rn_temp_string_copy(a6)         ; temporary string from a0 (085b4)

;------------------------------------------------------------------------------
; Runtime: HEX$(d0) (routine $6e): the nibbles from the first non-zero one, as 0-9 and A-F,
; a temporary string. 0 is "0" ($87(a6)).
;------------------------------------------------------------------------------
rt_hex:
	jsr	rn_radix_start(a6)
	moveq	#7,d2                           ; 8 nibbles
.hex_skip:
	rol.l	#4,d0                           ; skip leading zero nibbles
	move.b	d0,d1                           ; the top nibble
	andi.b	#$f,d1
	dbne	d2,.hex_skip
.hex_out:
	andi.b	#$f,d1
	ori.b	#$30,d1                         ; digit
	cmpi.b	#$39,d1                         ; A-F
	bls.s	.hex_store
	addq.b	#7,d1                           ; 'A'-'F'
.hex_store:
	move.b	d1,(a1)+                        ; into the buffer
	rol.l	#4,d0                           ; next nibble
	move.b	d0,d1
	dbra	d2,.hex_out
	move.l	a1,d0
	sub.l	a0,d0                           ; d0 = length
	jmp	rn_temp_string_copy(a6)         ; temporary string from a0 (085b4)

;------------------------------------------------------------------------------
; Runtime: OCT$(d0): the top 2 bits, then 3-bit groups, from the first non-zero one.
;------------------------------------------------------------------------------
rt_oct:
	jsr	rn_radix_start(a6)              ; buffer, 0 handled
	moveq	#10,d2                          ; 11 octal digits
	rol.l	#2,d0                           ; top 2 bits first
	move.b	d0,d1                           ; the top 2 bits
	andi.b	#$3,d1
	bra.s	.oct_skip_next
.oct_skip:
	rol.l	#3,d0                           ; skip leading zero groups
	move.b	d0,d1
	andi.b	#$7,d1
.oct_skip_next:
	dbne	d2,.oct_skip
.oct_out:
	andi.b	#$7,d1
	ori.b	#$30,d1                         ; digit
	move.b	d1,(a1)+
	rol.l	#3,d0                           ; next group
	move.b	d0,d1
	dbra	d2,.oct_out
	move.l	a1,d0
	sub.l	a0,d0                           ; d0 = length
	jmp	rn_temp_string_copy(a6)         ; temporary string from a0 (085b4)

;------------------------------------------------------------------------------
; Runtime: writes d1 as two decimal digits at a1 ($8a(a6)); 89bc ($8b(a6)) writes d0.
;------------------------------------------------------------------------------
rt_two_digits_d1:
	move.w	d1,d0                           ; the value in d1

rt_two_digits:
	ext.l	d0                              ; 0..99
	divu.w	#$a,d0                          ; tens and units
	ori.l	#$20302030,d0                   ; to ASCII
	move.b	d0,(a1)+                        ; tens
	swap	d0
	move.b	d0,(a1)+                        ; units
	rts

;------------------------------------------------------------------------------
; Runtime: TIME$: Tgettime, as "hh:mm:ss" ($88(a6) = 089fc), an 8-byte temporary string.
;------------------------------------------------------------------------------
rt_time_str:
	move.w	#$2c,-(sp)                      ; GEMDOS $2c Tgettime
	trap	#1                              ; Tgettime
	addq.l	#2,sp                           ; drop the function number
	lea	$94(a4),a0                      ; a0 = the buffer
	jsr	rn_write_time_word(a6)          ; hh:mm:ss (08a14)
	moveq	#8,d0                           ; 8 characters
	jmp	rn_temp_string_copy(a6)         ; temporary string from a0 (085b4)

;------------------------------------------------------------------------------
; Runtime: DATE$: Tgetdate, as "dd.mm.yyyy" ($89(a6) = 0833a), a 10-byte temporary string.
;------------------------------------------------------------------------------
rt_date_str:
	move.w	#$2a,-(sp)                      ; GEMDOS $2a Tgetdate
	trap	#1                              ; Tgetdate
	addq.l	#2,sp                           ; drop the function number
	lea	$94(a4),a0                      ; a0 = the buffer
	jsr	rn_write_date_word(a6)          ; dd.mm.yyyy (08352)
	moveq	#10,d0                          ; 10 characters
	jmp	rn_temp_string_copy(a6)         ; temporary string from a0 (085b4)

;------------------------------------------------------------------------------
; Runtime: writes a GEMDOS time word as hh:mm:ss at a0 ($88(a6)).
;------------------------------------------------------------------------------
rt_write_time_word:
	movea.l	a0,a1                           ; a1 = write pointer
	move.w	d0,d1                           ; d1 = the time word
	rol.w	#5,d0                           ; hours (bits 11-15)
	andi.w	#$1f,d0
	jsr	rn_two_digits(a6)               ; two digits (089d4)
	move.b	#$3a,(a1)+                      ; ':'
	move.w	d1,d0
	lsr.w	#5,d0                           ; minutes bits to the bottom
	andi.w	#$3f,d0                         ; minutes
	jsr	rn_two_digits(a6)               ; two digits (089d4)
	move.b	#$3a,(a1)+                      ; ':'
	andi.w	#$1f,d1                         ; seconds / 2
	add.w	d1,d1                           ; * 2: seconds
	jmp	rn_two_digits_d1(a6)            ; two digits (089d2)

;------------------------------------------------------------------------------
; Runtime: SPACE$(d0): STRING$ of spaces. 8a2c STRING$(d1,d0): a temporary of d1 bytes of the
; character d0.
;------------------------------------------------------------------------------
rt_space:
	move.w	d0,d1                           ; d1 = count
	moveq	#32,d0                          ; space

rt_string_char:
	move.w	d0,d6                           ; d6 = the character
	move.w	d1,d0                           ; d0 = count
	jsr	rn_temp_string_alloc(a6)        ; temporary of d0 bytes (084ec)
	bra.s	.fill_next
.fill:
	move.b	d6,(a1)+                        ; fill
.fill_next:
	dbra	d0,.fill
	rts

;------------------------------------------------------------------------------
; Runtime: STRING$(d1,a$): a$ repeated d1 times (0: empty, 1: a$ itself); more than 32767
; bytes is error 10.
;------------------------------------------------------------------------------
rt_string_repeat:
	move.w	d1,d0                           ; d0 = count
	beq.s	.none                           ; 0: empty
	cmpi.w	#$1,d0
	beq.s	.string_done                    ; 1: a$ itself
	move.w	d0,d5                           ; d5 = repeats
	move.w	4(a0),d4                        ; d4 = a$'s length
	mulu.w	d4,d0                           ; total length
	beq.s	.string_done                    ; a$ empty: itself
	cmpi.l	#$7fff,d0                       ; more than 32767: error 10
	bhi.s	.too_long
	move.l	a0,d3                           ; keep a$
	jsr	rn_temp_string_alloc(a6)        ; temporary of d0 bytes
	subq.w	#1,d4                           ; d4 = length - 1 for dbra
	bra.s	.repeat
.copy:
	move.b	(a2)+,(a1)+                     ; copy a byte of a$
	dbra	d0,.copy
.repeat:
	move.w	d4,d0                           ; d0 = length - 1
	movea.l	d3,a2                           ; a$'s text again
	movea.l	(a2),a2
	dbra	d5,.copy                        ; d5 = repeats
	exg	d3,a0                           ; a0 = a$, d3 = the result
	jsr	rn_string_text_len_212(a6)      ; free a$ if temporary
	movea.l	d3,a0                           ; a0 = the result
.string_done:
	rts
.none:
	jsr	rn_string_text_len_212(a6)      ; free a$ if temporary
	moveq	#0,d0                           ; length 0
	jmp	rn_temp_string_alloc(a6)        ; empty temporary
.too_long:
	moveq	#10,d0                          ; error 10 String too long
	jmp	rn_error_entry(a6)              ; raise error d0

;------------------------------------------------------------------------------
; Runtime: DIR$(d0): Dgetpath of drive d0 as a temporary string.
;------------------------------------------------------------------------------
rt_dir_str:
	move.w	d0,-(sp)                        ; drive
	pea	$94(a4)                         ; buffer
	move.w	#$47,-(sp)                      ; GEMDOS $47 Dgetpath
	trap	#1                              ; Dgetpath
	addq.l	#8,sp                           ; drop the arguments
	lea	$94(a4),a0                      ; a0 = the path
	movea.l	a0,a1
.path_end:
	tst.b	(a1)+                           ; find the NUL
	bne.s	.path_end
	move.l	a1,d0                           ; d0 = length + 1
	sub.l	a0,d0
	subq.l	#1,d0                           ; d0 = length
	jmp	rn_temp_string_copy(a6)         ; temporary string from a0

;------------------------------------------------------------------------------
; Runtime: UPPER$(a$): a temporary is changed in place, a variable copied into a new
; temporary. a-z and the accented letters of dat_upper_accents become upper case.
;------------------------------------------------------------------------------
rt_upper:
	moveq	#0,d0
	lea	$ad2(a4),a1                     ; end of the temporary descriptors
	move.w	4(a0),d0                        ; d0 = length
	beq.s	.upper_done                     ; empty: as it is
	cmpa.l	a1,a0                           ; a temporary: change in place
	bcc.s	.copy_variable
	movea.l	(a0),a1                         ; a1 = text, written in place
	movea.l	a1,a2                           ; a2 = read pointer
	bra.s	.convert
.copy_variable:
	move.l	a0,d5                           ; d5 = a$
	jsr	rn_temp_string_alloc(a6)        ; new temporary of the length
	movea.l	d5,a2                           ; a2 = a$ descriptor
	movea.l	(a2),a2                         ; a2 = a$ text
.convert:
	move.l	a0,d4                           ; d4 = the result descriptor
	subq.w	#1,d0                           ; count - 1 for dbra
.char:
	move.b	(a2)+,d1                        ; next byte
	bpl.s	.letter                         ; ASCII
	moveq	#13,d3                          ; 14 accented letters
	lea	dat_upper_accents(pc),a0
.accent:
	cmp.b	(a0)+,d1                        ; find it
	dbeq	d3,.accent
	bne.s	.store                          ; not in the table: unchanged
	move.b	$d(a0),d1                       ; its upper-case form 14 bytes on
.letter:
	cmpi.b	#$61,d1                         ; a-z
	bcs.s	.store
	cmpi.b	#$7a,d1
	bhi.s	.store
	subi.b	#$20,d1                         ; to upper case
.store:
	move.b	d1,(a1)+                        ; into the result
	dbra	d0,.char                        ; next byte
	movea.l	d4,a0                           ; a0 = the result
.upper_done:
	rts

; Data: 14 lower-case accented Atari characters ($81 $82 $84 $85 $86 $87 $91 $94 $a4 $b0 $b1
; $b3 $b4 $c0) followed by their upper-case forms, decoded as instructions; 8b20 is code again.
dat_upper_accents:
	dc.w	$8182                           ; $81 $82 (lower case ...)
	or.l	d5,d2                           ; accent table bytes, not code
	or.l	d7,d3                           ; accent table bytes, not code
	sub.l	d0,(a4)                         ; accent table bytes, not code
	dc.w	$a4b0                           ; Line-A function $4b0
	dc.w	$b1b3                           ; accent table bytes
	cmpa.w	d0,a2                           ; accent table bytes, not code
	sub.l	(a0),d5                         ; $9a $90 (upper case ...)
	dc.w	$8eb6,$8f80                     ; accent table bytes
	sub.l	(a1)+,d1                        ; accent table bytes, not code
	dc.w	$a5b7                           ; Line-A function $5b7
	dc.w	$b8b2                           ; accent table bytes
	cmpa.l	d1,a2                           ; accent table bytes, not code

;------------------------------------------------------------------------------
; Runtime: INSTR: 8b20 without a start, 8b22 start in d1, 8b24 start in d0. Looks for the
; string at a0 in the string at a1 from the start; exit d0 = the position (1 = first), 0 when
; not found. Both strings are freed if temporary.
;------------------------------------------------------------------------------
rt_instr:
	moveq	#0,d1                           ; INSTR without a start

rt_instr_start_d1:
	move.l	d1,d0                           ; start in d1

rt_instr_start:
	move.l	d0,d6                           ; start in d0
	move.l	a1,d5                           ; a1 = the string searched
	jsr	rn_string_text_len_212(a6)      ; the string looked for
	move.l	a1,d3                           ; d3 = text looked for
	move.l	d0,d4                           ; d4 = its length
	movea.l	d5,a0                           ; a0 = string searched
	jsr	rn_string_text_len_212(a6)      ; the string searched
	movea.l	d3,a0                           ; a0 = text looked for, a1 = text searched
	move.l	d4,d1                           ; d1 = length looked for, d0 = length searched
	subq.l	#1,d6                           ; 0-based start
	bpl.s	.search
	moveq	#0,d6                           ; below 1 counts as 1
.search:
	cmp.w	d1,d0                           ; searched string longer?
	bls.s	.not_longer
	ext.l	d0
	cmp.l	d0,d6                           ; start at or past the end
	bcc.s	.start_at_end
	tst.w	d1                              ; empty search string: the start
	beq.s	.result
	sub.w	d1,d0                           ; positions to try
	sub.w	d6,d0
	blt.s	.not_found
	adda.w	d6,a1                           ; from the start
	subq.w	#1,d1                           ; length looked for - 1
	move.l	a0,d5                           ; d5 = text looked for
	move.l	a1,d7                           ; d7 = position in the text searched
.position:
	addq.l	#1,d6                           ; position (1-based)
	move.w	d1,d3
.compare:
	cmpm.b	(a0)+,(a1)+                     ; compare
	dbne	d3,.compare
	beq.s	.result                         ; found
	addq.l	#1,d7                           ; next position
	movea.l	d5,a0                           ; restart the compare
	movea.l	d7,a1
	dbra	d0,.position                    ; more positions
.not_found:
	moveq	#0,d0                           ; not found: 0
	rts
.start_at_end:
	bne.s	.not_found                      ; start past the end: not found
	tst.w	d1                              ; start at the end: only "" is found
	bne.s	.not_found
	addq.l	#1,d2                           ; d2, not d6: the result stays the start - 1
	bra.s	.result
.not_longer:
	bne.s	.not_found                      ; searched shorter: not found
	subq.w	#1,d1
	bmi.s	.at_one                         ; both empty: found at 1
.compare_all:
	cmpm.b	(a0)+,(a1)+                     ; same length: compare all
	dbne	d1,.compare_all
	bne.s	.not_found                      ; a difference: not found
.at_one:
	moveq	#1,d6                           ; found at 1
.result:
	move.l	d6,d0                           ; d0 = position
	rts

;------------------------------------------------------------------------------
; Runtime: one-name GEMDOS file calls: KILL (8b94, $41 Fdelete), MKDIR (8b98, $39 Dcreate),
; RMDIR (8b9c, $3a Ddelete), CHDIR (8ba0, $3b Dsetpath). The name is NUL-terminated
; temporarily; an empty name points at a 0 byte inside the jmp at loc_08be4. A GEMDOS error is
; raised.
;------------------------------------------------------------------------------
rt_kill:
	moveq	#65,d0                          ; GEMDOS $41 Fdelete
	bra.s	rt_file_name_call

rt_mkdir:
	moveq	#57,d0                          ; GEMDOS $39 Dcreate
	bra.s	rt_file_name_call

rt_rmdir:
	moveq	#58,d0                          ; GEMDOS $3a Ddelete
	bra.s	rt_file_name_call

rt_chdir:
	moveq	#59,d0                          ; GEMDOS $3b Dsetpath

;------------------------------------------------------------------------------
; Runtime: the GEMDOS call with one name for KILL/MKDIR/RMDIR/CHDIR: d0 = function, a0 = the
; name descriptor. See 8b94.
;------------------------------------------------------------------------------
rt_file_name_call:
	move.w	d0,-(sp)                        ; keep the function
	jsr	rn_string_text_len_212(a6)      ; a1 = name, d0 = length
	move.w	(sp)+,d7                        ; d7 = function
	tst.w	d0                              ; empty name?
	bne.s	.name
	lea	rt_file_op_error+2(pc),a1       ; empty: a 0 byte in the jmp below
.name:
	lea	0(a1,d0.w),a0                   ; end of the name
	move.b	(a0),-(sp)                      ; keep the byte after the name
	pea	(a0)                            ; and its address
	clr.b	(a0)                            ; NUL-terminate
	pea	(a1)                            ; name
	move.w	d7,-(sp)                        ; function
	trap	#1                              ; GEMDOS, the GEMDOS call
	addq.l	#6,sp                           ; drop function and name
	movea.l	(sp)+,a0                        ; a0 = end of the name
	move.b	(sp)+,(a0)                      ; put the byte back
	tst.l	d0                              ; error?
	bpl.s	rt_file_op_done

;------------------------------------------------------------------------------
; Runtime: raises the GEMDOS error in d0. The jmp's second word $0002 (rn_002) supplies
; the 0 byte used as an empty name by 8bae.
;------------------------------------------------------------------------------
rt_file_op_error:
	jmp	rn_error_entry(a6)              ; raise the GEMDOS error

rt_file_op_done:
	rts

;------------------------------------------------------------------------------
; Runtime: NAME a1$ AS a0$: Frename of the old name (a1's string) to the new (a0's), both
; NUL-terminated temporarily; an empty name is the empty string at $ae2(a4).
;------------------------------------------------------------------------------
rt_name_as:
	move.l	a1,d6                           ; keep the a1 descriptor
	jsr	rn_string_text_len_212(a6)      ; the new name (a0)
	move.l	a1,d5                           ; d5 = new name text
	move.l	d0,d4                           ; d4 = its length
	movea.l	d6,a0                           ; a0 = the a1 descriptor
	jsr	rn_string_text_len_212(a6)      ; the old name (a1)
	movea.l	d5,a0                           ; a0 = new name
	tst.w	d0                              ; old name empty?
	bne.s	.old_name
	lea	$ad2(a4),a1                     ; empty: $ad2(a4)
.old_name:
	tst.w	d4                              ; new name empty?
	bne.s	.terminate
	lea	$ad2(a4),a0
.terminate:
	lea	0(a0,d4.w),a2                   ; NUL-terminate the new name
	move.b	(a2),d3                         ; keep the byte after it
	move.l	a2,d4                           ; and its address
	clr.b	(a2)
	lea	0(a1,d0.w),a2                   ; and the old name
	move.b	(a2),d5                         ; keep the byte after it
	move.l	a2,d6                           ; and its address
	clr.b	(a2)
	pea	(a0)                            ; new name
	pea	(a1)                            ; old name
	clr.w	-(sp)                           ; reserved word 0
	move.w	#$56,-(sp)                      ; GEMDOS $56 Frename
	trap	#1                              ; Frename
	adda.w	#$c,sp                          ; drop the arguments
	movea.l	d6,a0                           ; put the bytes back
	move.b	d5,(a0)
	movea.l	d4,a0
	move.b	d3,(a0)
	tst.b	d0                              ; error? (low byte only)
	bpl.s	.rename_done
	jmp	rn_error_entry(a6)              ; raise error d0
.rename_done:
	rts

;------------------------------------------------------------------------------
; Runtime: PAUSE d0: waits d0 fiftieths of a second, watching TIMER ($39(a6) = 06c48).
;------------------------------------------------------------------------------
rt_pause:
	ext.l	d0
	asl.l	#2,d0                           ; * 4: 200 Hz ticks
	move.l	d0,d3                           ; d3 = ticks to wait
	jsr	rn_timer(a6)                    ; TIMER (06c60)
	add.l	d0,d3                           ; end time
.wait:
	jsr	rn_timer(a6)
	cmp.l	d0,d3                           ; not reached yet
	bpl.s	.wait                           ; d3 - now >= 0: wait on
	rts

;------------------------------------------------------------------------------
; Runtime: presumably CHAIN name$: shel_write (AES 121) with the name and the command line at
; basepage+$80, all three flags 1; when the AES accepts it the program ends ($201(a6) = 05904),
; otherwise error 11.
;------------------------------------------------------------------------------
rt_chain:
	jsr	rn_string_text_len_212(a6)      ; a1 = name, d0 = length
	tst.w	d0                              ; empty name?
	bne.s	.name
	lea	$ad6(a4),a1                     ; empty name
.name:
	move.l	a1,$79a(a4)                     ; AES addrin[0] = name
	adda.w	d0,a1                           ; end of the name
	move.b	(a1),d3                         ; keep the byte there
	move.l	a1,d4                           ; and its address
	clr.b	(a1)                            ; NUL-terminate
	lea	rn_program_start(a6),a0         ; routine 1 = program start
	suba.w	#$80,a0                         ; basepage + $80: the command line
	move.l	a0,$79e(a4)                     ; AES addrin[1]
	moveq	#1,d0
	move.w	d0,$74a(a4)                     ; intin[0..2] = 1
	move.w	d0,$74c(a4)
	move.w	d0,$74e(a4)
	moveq	#121,d0                         ; AES 121 shel_write
	jsr	rn_aes_call(a6)                 ; AES call (05932)
	movea.l	d4,a0
	move.b	d3,(a0)                         ; put the byte back
	tst.w	$772(a4)                        ; AES intout[0]
	beq.s	.failed
	jmp	rn_end_program(a6)              ; end the program (0591c)
.failed:
	moveq	#11,d0                          ; error 11
	jmp	rn_error_entry(a6)              ; raise error d0

;------------------------------------------------------------------------------
; Runtime: CVS(a$): a 4-byte single (24-bit mantissa, sign and 7-bit exponent biased 64 in the
; last byte) to an unpacked float; 0.0 when shorter than 4. 8cac CVD(a$): the same from 8 bytes.
;------------------------------------------------------------------------------
rt_cvs:
	jsr	rn_string_text_len_212(a6)      ; a1 = text, d0 = length
	moveq	#0,d2                           ; d2 = 0: 0.0 when the string is too short
	subq.w	#4,d0                           ; at least 4 bytes?
	bmi.s	.cvs_done                       ; shorter than 4: 0.0
	move.l	(a1),d0                         ; mantissa and exponent byte
	moveq	#0,d1                           ; low mantissa word 0: a single has 24 bits
	move.b	d0,d2                           ; exponent byte
	move.b	d1,d0                           ; clear it from the mantissa
	ext.w	d2                              ; sign into bit 31
	ext.l	d2                              ; sign bit 31 from bit 7 of the exponent byte
	andi.w	#$7f,d2                         ; exponent
	addi.w	#$1bf,d2                        ; bias 64 to bias $200
.cvs_done:
	rts

;------------------------------------------------------------------------------
; Runtime: CVD(a$): an 8-byte double (48-bit mantissa, then the exponent word: sign in bit 7,
; 7-bit exponent biased 64) to an unpacked float d0-d2; 0.0 when shorter than 8.
;------------------------------------------------------------------------------
rt_cvd:
	jsr	rn_string_text_len_212(a6)      ; a1 = text, d0 = length
	moveq	#0,d2                           ; d2 = 0: 0.0 when the string is too short
	subq.w	#8,d0                           ; at least 8 bytes?
	bmi.s	.cvd_done                       ; shorter than 8: 0.0
	move.l	(a1)+,d0                        ; mantissa high long
	move.w	(a1)+,d1                        ; mantissa low word
	move.w	(a1)+,d2                        ; exponent word
	ext.w	d2                              ; sign from bit 7
	ext.l	d2                              ; sign bit 31 from bit 7
	andi.w	#$7f,d2                         ; 7-bit exponent
	addi.w	#$1bf,d2                        ; bias 64 to bias $200
.cvd_done:
	rts

;------------------------------------------------------------------------------
; Runtime: unpacked float d0-d2 to the CVS/CVD form: exponent - $1bf (underflow 0, overflow
; the largest), sign into bit 7 of the exponent byte; a0 = the buffer $94(a4).
;------------------------------------------------------------------------------
rt_float_to_mks:
	subi.w	#$1bf,d2                        ; bias $200 to bias 64
	bpl.s	.overflow_check                 ; underflow: 0
	moveq	#0,d2                           ; underflow: exponent 0
	moveq	#0,d0                           ; and mantissa 0
	moveq	#0,d1                           ; low word 0
.overflow_check:
	cmpi.w	#$7f,d2                         ; fits 7 bits?
	bls.s	.sign                           ; yes: keep it
	move.w	#$7f,d2                         ; overflow: the largest
	moveq	#-1,d0                          ; all mantissa bits set
	moveq	#-1,d1                          ; low word too
.sign:
	tst.l	d2                              ; negative?
	bpl.s	.buffer                         ; positive: no sign bit
	ori.b	#$80,d2                         ; sign into bit 7
.buffer:
	lea	$94(a4),a0                      ; the buffer
	rts

;------------------------------------------------------------------------------
; Runtime: MKS$ of the float: 4 bytes. 8d00 MKD$: 8 bytes.
;------------------------------------------------------------------------------
rt_mks:
	bsr.s	rt_float_to_mks                 ; d0-d2 to MKS form, a0 = the buffer at $94(a4)
	move.l	d0,(a0)                         ; mantissa
	move.b	d2,3(a0)                        ; exponent byte last
	moveq	#4,d0                           ; 4 bytes
	jmp	rn_temp_string_copy(a6)         ; temporary string of the d0 bytes at a0 ($48(a6))

;------------------------------------------------------------------------------
; Runtime: MKD$ of the float d0-d2: the 8-byte form (mantissa long and word, exponent word)
; as a temporary string.
;------------------------------------------------------------------------------
rt_mkd:
	bsr.s	rt_float_to_mks                 ; d0-d2 to MKS form, a0 = the buffer at $94(a4)
	move.l	d0,(a0)                         ; mantissa high long
	move.w	d1,4(a0)                        ; mantissa low word
	move.w	d2,6(a0)                        ; exponent word last
	moveq	#8,d0                           ; 8 bytes
	jmp	rn_temp_string_copy(a6)         ; temporary string of the d0 bytes at a0 ($48(a6))

;------------------------------------------------------------------------------
; Runtime: frees all temporary strings still in use (the descriptors at $884(a4)): each gets
; the free mark after its text.
;------------------------------------------------------------------------------
rt_free_temp_strings:
	lea	$874(a4),a0                     ; the temporary descriptors
	moveq	#99,d3                          ; 100
.find_used:
	movea.l	(a0)+,a1                        ; find one in use
	move.w	(a0)+,d1                        ; d1 = its length: negative marks a free descriptor
	dbpl	d3,.find_used                   ; until one in use (length not negative)
	bmi.s	.done                           ; none left
	st	-$2(a1)                         ; the byte 2 before the text, not -$2(a0): the descriptor stays
	addq.w	#1,d1                           ; length, even
	andi.w	#$fffe,d1                       ; even
	moveq	#0,d2                           ; d2 = length as a long
	move.w	d1,d2                           ; d2 = -(even length)
	neg.l	d2                              ; negative: free block of that size
	move.l	d2,0(a1,d1.w)                   ; free mark after the text
	dbra	d3,.find_used                   ; next descriptor
.done:
	rts

;------------------------------------------------------------------------------
; Runtime: LSET a1$=a0$: the source copied into the variable's own text from the left, padded
; with spaces; the variable's length does not change.
;------------------------------------------------------------------------------
rt_lset:
	move.l	a1,d6                           ; keep the variable's descriptor
	jsr	rn_string_text_len_212(a6)      ; the source: a1, d0
	movea.l	d6,a2                           ; a2 = the variable's descriptor
	movea.l	(a2)+,a0                        ; the variable's text
	move.w	(a2),d1                         ; and length
	cmp.w	d1,d0                           ; source shorter?
	bcc.s	.lset_part_next                 ; source at least as long: copy only d1 bytes
	sub.w	d0,d1                           ; spaces after it
	bra.s	.lset_copy_next                 ; copy d0 bytes, then pad d1
.lset_copy:
	move.b	(a1)+,(a0)+                     ; copy a byte
.lset_copy_next:
	dbra	d0,.lset_copy                   ; d0 bytes of the source
	bra.s	.lset_pad_next                  ; then the padding
.lset_pad:
	move.b	#$20,(a0)+                      ; pad with spaces
.lset_pad_next:
	dbra	d1,.lset_pad
	rts
.lset_part:
	move.b	(a1)+,(a0)+                     ; source longer: cut
.lset_part_next:
	dbra	d1,.lset_part
	rts

;------------------------------------------------------------------------------
; Runtime: RSET a1$=a0$: as LSET but right-aligned: spaces first, then the source; a longer
; source is cut to the variable's length. a1 = the variable's descriptor, a0 = the source.
;------------------------------------------------------------------------------
rt_rset:
	move.l	a1,d6                           ; keep the variable's descriptor
	jsr	rn_string_text_len_212(a6)      ; the source: a1 = text, d0 = length
	movea.l	d6,a2                           ; a2 = the variable's descriptor
	movea.l	(a2)+,a0                        ; the variable's text
	move.w	(a2),d1                         ; and length
	cmp.w	d1,d0                           ; source shorter?
	bcc.s	.rset_part_next                 ; no: copy only d1 bytes
	sub.w	d0,d1                           ; spaces before it
	bra.s	.rset_pad_next                  ; pad d1 spaces, then copy d0 bytes
.rset_pad:
	move.b	#$20,(a0)+                      ; space before the text
.rset_pad_next:
	dbra	d1,.rset_pad
	bra.s	.rset_copy_next                 ; then the source
.rset_copy:
	move.b	(a1)+,(a0)+                     ; copy a byte
.rset_copy_next:
	dbra	d0,.rset_copy
	rts
.rset_part:
	move.b	(a1)+,(a0)+                     ; source longer: cut
.rset_part_next:
	dbra	d1,.rset_part
	rts

;------------------------------------------------------------------------------
; Runtime: MID$(a1$,d1)=a0$ (8d98) and MID$(a1$,d0,d1)=a0$ (8d9e): copies the source into the
; variable's text from the start position, at most d1 bytes and not past its end.
;------------------------------------------------------------------------------
rt_mid_assign:
	move.w	d1,-(sp)                        ; start
	moveq	#-1,d1                          ; no count
	bra.s	rt_mid_assign_body              ; common part

;------------------------------------------------------------------------------
; Runtime: MID$(a1$,d0,d1)=a0$ with a count: d0 = start, d1 = count; continues at
; rt_mid_assign_body.
;------------------------------------------------------------------------------
rt_mid_assign_count:
	move.w	d0,-(sp)                        ; start

rt_mid_assign_body:
	move.w	d1,-(sp)                        ; count
	move.l	a1,d6                           ; keep the variable's descriptor
	jsr	rn_string_text_len_212(a6)      ; the source: a1, d0
	movea.l	d6,a2                           ; a2 = the variable's descriptor
	movea.l	(a2)+,a0                        ; the variable's text
	move.w	(a2),d1                         ; and length
	move.w	(sp)+,d3                        ; d3 = count
	move.w	(sp)+,d4                        ; d4 = start
	subq.w	#1,d4                           ; position from 0
	adda.w	d4,a0                           ; to the start position
	sub.w	d4,d1                           ; bytes from there
	bls.s	.mid_done                       ; start past the end: nothing
	cmp.w	d3,d1                           ; cut to the count
	bls.s	.mid_limit                      ; fewer bytes there than the count: keep
	move.w	d3,d1                           ; cut to the count
.mid_limit:
	cmp.w	d1,d0                           ; and to the source
	bls.s	.mid_copy_next                  ; source not longer than that: copy all of it
	move.w	d1,d0                           ; the source is shorter: copy it all
	bra.s	.mid_copy_next
.mid_copy:
	move.b	(a1)+,(a0)+                     ; copy a byte
.mid_copy_next:
	dbra	d0,.mid_copy
.mid_done:
	rts

;------------------------------------------------------------------------------
; Runtime: string garbage collection that also adds d0 to every back pointer at or above a0
; ($1f0(a6)): used when the descriptors there (string arrays) have moved up by d0.
;------------------------------------------------------------------------------
rt_string_collect_moved_up:
	movem.l	a1-a3,-(sp)                     ; keep a1-a3
	moveq	#-2,d4                          ; even-mask (not used here)
	move.l	a0,d2                           ; d2 = where descriptors moved
	movea.l	$64(a4),a0                      ; top of the string area
	movea.l	$60(a4),a2                      ; bottom
.grow_scan:
	movea.l	a0,a1                           ; a1 = where the next block goes (moved up to here)
	cmpa.l	a0,a2                           ; reached the bottom?
	beq.s	.grow_done
	move.l	-(a0),d1                        ; the block's end long
	movea.l	d1,a3                           ; a3 = back pointer: the descriptor
	bmi.s	.grow_skip_free                 ; free block
	cmp.l	d2,d1                           ; descriptor moved?
	bcs.s	.grow_live                      ; no: back pointer unchanged
	add.l	d0,(a0)                         ; back pointer + d0
.grow_live:
	movea.l	(a3),a0                         ; skip to the start (descriptor still at a3)
	bra.s	.grow_scan                      ; next block
.grow_skip_free:
	adda.l	d1,a0                           ; skip the free block (d1 is minus its size)
	cmpa.l	a0,a2                           ; reached the bottom?
	beq.s	.grow_done
.grow_move:
	move.l	-(a0),d1                        ; block end long below the current block
	bmi.s	.grow_skip_free                 ; free: skip it
	move.l	d1,-(a1)                        ; back pointer moved up
	movea.l	d1,a3                           ; a3 = the descriptor
	cmp.l	d2,d1                           ; descriptor moved?
	bcs.s	.grow_copy                      ; no: unchanged
	add.l	d0,(a1)                         ; + d0 for a moved descriptor
.grow_copy:
	move.w	4(a3),d1                        ; length in words
	subq.w	#1,d1                           ; (length + 1) / 2 words, minus one for dbra
	lsr.w	#1,d1                           ; the text moved up word by word
.grow_word:
	move.w	-(a0),-(a1)                     ; one word
	dbra	d1,.grow_word
	move.l	a1,(a3)                         ; the descriptor's new address
	cmpa.l	a0,a2                           ; reached the bottom?
	bne.s	.grow_move                      ; next block
.grow_done:
	move.l	a1,$60(a4)                      ; new bottom
	movem.l	(sp)+,a1-a3                     ; restore a1-a3
	rts

;------------------------------------------------------------------------------
; Runtime: string garbage collection after removing d0 bytes of descriptors at a0 ($1f1(a6)):
; strings whose descriptors lay in the removed part are dropped, back pointers above it are
; lowered by d0.
;------------------------------------------------------------------------------
rt_string_collect_removed:
	movem.l	a1-a3,-(sp)                     ; keep a1-a3
	moveq	#-2,d4                          ; even-mask
	move.l	a0,d2                           ; d2 = start of the removed descriptors
	move.l	d2,d3                           ; d3 = their end
	add.l	d0,d3                           ; d3 = end of the removed descriptors
	movea.l	$64(a4),a0                      ; a0 = top of the string area
	movea.l	$60(a4),a2                      ; a2 = its bottom
.shrink_scan:
	movea.l	a0,a1                           ; a1 = where the next block goes
	cmpa.l	a0,a2                           ; reached the bottom?
	beq.s	.shrink_done                    ; done
	move.l	-(a0),d1                        ; block end long: back pointer or -size
	bmi.s	.shrink_skip_free               ; free block: skip it
	movea.l	d1,a3                           ; a3 = the descriptor
	cmp.l	d2,d1                           ; below the removed part: unchanged
	bls.s	.shrink_live                    ; at or below the removed part: unchanged
	cmp.l	d3,d1                           ; above it: lowered
	bhi.s	.shrink_above                   ; above it: lowered
	movea.l	(a3),a0                         ; inside: the string is dropped
	bra.s	.shrink_check_end               ; inside: the string is skipped
.shrink_above:
	sub.l	d0,(a0)                         ; back pointer - d0
.shrink_live:
	movea.l	(a3),a0                         ; skip to the text start (descriptor still at a3)
	bra.s	.shrink_scan                    ; next block
.shrink_skip_free:
	adda.l	d1,a0                           ; skip the free block
.shrink_check_end:
	cmpa.l	a0,a2                           ; reached the bottom?
	beq.s	.shrink_done
.shrink_move:
	move.l	-(a0),d1                        ; next block end long
	bmi.s	.shrink_skip_free               ; free: skip it
	move.l	d1,-(a1)                        ; back pointer moved up
	movea.l	d1,a3                           ; a3 = the descriptor
	cmp.l	d2,d1                           ; at or below the removed part?
	bls.s	.shrink_copy                    ; below: unchanged
	cmp.l	d3,d1                           ; above it?
	bhi.s	.shrink_move_down               ; above: lowered
	moveq	#1,d1                           ; inside: skip the string
	add.w	4(a3),d1                        ; + length
	and.b	d4,d1                           ; even
	suba.l	d1,a0                           ; a0 below the dropped string
	addq.l	#4,a1                           ; and take its back pointer back
	bra.s	.shrink_check_end               ; next block
.shrink_move_down:
	sub.l	d0,(a1)                         ; back pointer - d0
.shrink_copy:
	move.w	4(a3),d1                        ; length in words
	subq.w	#1,d1                           ; (length + 1) / 2 words, minus one for dbra
	lsr.w	#1,d1                           ; words
.shrink_word:
	move.w	-(a0),-(a1)                     ; one word
	dbra	d1,.shrink_word
	move.l	a1,(a3)                         ; the descriptor's new address
	cmpa.l	a0,a2                           ; reached the bottom?
	bne.s	.shrink_move                    ; next block
.shrink_done:
	move.l	a1,$60(a4)                      ; new bottom of the string area
	movem.l	(sp)+,a1-a3                     ; restore a1-a3
	rts

;------------------------------------------------------------------------------
; Runtime: OPTION BASE 1: writes subq.l #1 ($5380 d0, $5381 d1, $5383 d3) over the nops of the
; array routines (symbols $249..$263(a6)). 8eac OPTION BASE 0: writes nops back.
;------------------------------------------------------------------------------
rt_option_base_1:
	move.w	#$5380,d0                       ; subq.l #1,d0
	move.w	#$5381,d1                       ; subq.l #1,d1
	move.w	#$5383,d3                       ; subq.l #1,d3
	bra.s	rt_option_base_patch            ; write them into the routines

;------------------------------------------------------------------------------
; Runtime: OPTION BASE 0: the nop ($4e71) back into every index adjustment of the array
; routines.
;------------------------------------------------------------------------------
rt_option_base_0:
	move.w	#$4e71,d0                       ; nop
	move.w	d0,d1                           ; nop for d1
	move.w	d0,d3                           ; nop for d3

;------------------------------------------------------------------------------
; Runtime: OPTION BASE common part: d0, d1 and d3 written over the index adjustments.
;------------------------------------------------------------------------------
rt_option_base_patch:
	move.w	d0,rn_float_array_get_1d_249(a6) ; patch the routines' index adjustment
	move.w	d0,rn_int_array_get_1d_24b(a6)  ; 1-d integer read
	move.w	d0,rn_bool_array_get_1d_24c(a6) ; 1-d boolean read
	move.w	d0,rn_float_array_address_1d_24a(a6) ; 1-d float address
	move.w	d3,rn_float_array_put_1d_base(a6) ; d3: the 1-d store routines' index
	move.w	d3,rn_int_array_put_1d_base(a6) ; 1-d integer store
	move.w	d3,rn_bool_array_put_1d_base(a6) ; 1-d boolean store
	move.w	d3,rn_string_array_put_1d_base(a6) ; 1-d string store
	move.w	d0,rn_dim_base_first(a6)        ; DIM: first bound
	move.w	d0,rn_dim_base_store(a6)        ; DIM: stored bounds
	move.w	d1,rn_dim_base_next(a6)         ; DIM: the other bounds (d1)
	move.w	d0,rn_array_index_read_base_first(a6) ; index check for reading: first index
	move.w	d0,rn_array_index_read_base_next(a6) ; and the next indices
	move.w	d3,rn_array_index_write_base_first(a6) ; index check for stores: first index (d3)
	move.w	d3,rn_array_index_write_base_next(a6) ; and the next indices
	rts

; Data: the word $0258 before this routine is not code (decoded with the nop as andi.w); the
; other array routines below have such words $0259..$025f too, purpose not worked out.
; Runtime: float array element a(d0) of a one-dimensional array: a1 = the array descriptor
; ([data address][dimensions]); the data starts with the element count. Exit d0-d2 unpacked.
; The nop becomes subq.l #1,d0 under OPTION BASE 1. Errors: 16 index too large, 18 wrong
; number of indices, 15 array not dimensioned.
	dc.w	$0258                           ; word $0258 (not code), then nop: subq.l #1,d0 under OPTION BASE 1

;------------------------------------------------------------------------------
; Runtime routine $102: a(d0) of a one-dimensional float array, a1 = the descriptor; its nop
; is the OPTION BASE adjustment (subq.l #1,d0 under BASE 1). Exit d0-d2 unpacked.
;------------------------------------------------------------------------------
rt_float_array_get_1d:
	nop                                     ; OPTION BASE adjustment: subq.l #1,d0 under BASE 1

;------------------------------------------------------------------------------
; Runtime routine $258: as $102 without the OPTION BASE adjustment.
;------------------------------------------------------------------------------
rt_float_array_get_1d_raw:
	movea.l	(a1)+,a0                        ; a0 = array data
	cmpi.w	#$1,(a1)                        ; one dimension?
	bne.s	rt_array_dims_error             ; not one: error 18 or 15
	cmp.l	(a0)+,d0                        ; index below the element count?
	bcc.s	rt_array_index_error            ; too large: error 16
	add.l	d0,d0                           ; * 6
	adda.l	d0,a0                           ; a0 + index * 2
	add.l	d0,d0                           ; index * 4
	adda.l	d0,a0                           ; a0 + index * 6
	move.l	(a0)+,d0                        ; unpack the element
	move.w	(a0),d1                         ; exponent and low mantissa word
	move.l	d0,d2                           ; d2 = sign bit (bit 31)
	bset	#$1f,d0                         ; the implied top mantissa bit
	move.w	d1,d2                           ; the 10-bit exponent
	andi.w	#$3ff,d2                        ; into d2
	sub.w	d2,d1                           ; mantissa low bits only in d1
	rts

; Data: word $00ed, not code.
	dc.w	$00ed                           ; word $00ed, not code

;------------------------------------------------------------------------------
; Runtime: array errors: 8f20 ($100(a6)) error 16, 8f26 ($ff(a6)) error 18 or 15, each first
; pushing a2 (the return address of the store routines).
;------------------------------------------------------------------------------
rt_array_index_error_a2:
	pea	(a2)                            ; $100(a6) enters here

;------------------------------------------------------------------------------
; Runtime: error 16 (Array index too large).
;------------------------------------------------------------------------------
rt_array_index_error:
	moveq	#16,d0                          ; error 16 Array index too large
	bra.s	rt_array_error_exit

;------------------------------------------------------------------------------
; Runtime routine $ff: pushes a2 (the store routines' return address), then error 18 or 15.
;------------------------------------------------------------------------------
rt_array_dims_error_a2:
	pea	(a2)                            ; $ff(a6) enters here

;------------------------------------------------------------------------------
; Runtime: error 18 (Wrong number of indices), or 15 (Array not dimensioned) when the
; descriptor's dimension word at (a1) is 0.
;------------------------------------------------------------------------------
rt_array_dims_error:
	moveq	#18,d0                          ; error 18 Wrong number of indices
	tst.w	(a1)                            ; dimension word 0?
	bne.s	rt_array_error_exit             ; no dimensions
	moveq	#15,d0                          ; error 15 Array not dimensioned

;------------------------------------------------------------------------------
; Runtime: array errors: runtime error d0.
;------------------------------------------------------------------------------
rt_array_error_exit:
	jmp	rn_error_entry(a6)              ; runtime error d0

; Runtime: integer array element a%(d0) into d0 (one dimension); errors through $ed/$ee(a6).
	dc.w	$0259                           ; word $0259 (not code), then the nop

;------------------------------------------------------------------------------
; Runtime: a%(d0) of a one-dimensional integer array: a1 = the array descriptor; exit d0 =
; the element. The nop is subq.l #1,d0 under OPTION BASE 1; 8f38 ($259) skips it.
;------------------------------------------------------------------------------
rt_int_array_get_1d:
	nop                                     ; OPTION BASE adjustment

;------------------------------------------------------------------------------
; Runtime routine $259: as $106 (a%(d0)) without the OPTION BASE adjustment.
;------------------------------------------------------------------------------
rt_int_array_get_1d_raw:
	movea.l	(a1)+,a0                        ; a0 = array data
	cmpi.w	#$1,(a1)                        ; one dimension?
	bne.s	.int_read_indices               ; not one: error 18 or 15
	cmp.l	(a0)+,d0                        ; index below the element count?
	bcc.s	.int_read_index                 ; too large: error 16
	add.l	d0,d0                           ; * 4
	add.l	d0,d0                           ; index * 4
	move.l	0(a0,d0.l),d0                   ; the element
	rts
.int_read_indices:
	jmp	rn_array_dims_error(a6)         ; wrong indices ($ed(a6), presumably 08f28)
.int_read_index:
	jmp	rn_array_index_error(a6)        ; index too large ($ee(a6), presumably 08f22)

; Runtime: boolean array element a!(d0) into d2 (-1 / 0): bit d0 & 7 of byte d0 >> 3.
	dc.w	$025a                           ; word $025a (not code), then the nop

;------------------------------------------------------------------------------
; Runtime: a!(d0) of a one-dimensional boolean array: a1 = the descriptor; exit d2 = -1 or 0.
; The nop is the OPTION BASE adjustment; 8f5a ($25a) skips it.
;------------------------------------------------------------------------------
rt_bool_array_get_1d:
	nop                                     ; OPTION BASE adjustment

;------------------------------------------------------------------------------
; Runtime routine $25a: as $108 (a!(d0)) without the OPTION BASE adjustment.
;------------------------------------------------------------------------------
rt_bool_array_get_1d_raw:
	movea.l	(a1)+,a0                        ; a0 = array data
	cmpi.w	#$1,(a1)                        ; one dimension?
	bne.s	.bool_read_indices              ; not one: error 18 or 15
	cmp.l	(a0)+,d0                        ; index below the element count?
	bcc.s	.bool_read_index                ; too large: error 16
	move.w	d0,d1                           ; bit number
	lsr.l	#3,d0                           ; byte number
	btst	d1,0(a0,d0.l)                   ; test the bit
	sne	d2                              ; TRUE / FALSE
	ext.w	d2                              ; -1 or 0
	rts
.bool_read_index:
	jmp	rn_array_index_error(a6)        ; error 16 (08f3a)
.bool_read_indices:
	jmp	rn_array_dims_error(a6)         ; error 18/15 (08f40)

; Runtime: the address of float element a(d0) in a0.
	dc.w	$025b                           ; word $025b (not code), then the nop

;------------------------------------------------------------------------------
; Runtime: the address of the float element a(d0) of a one-dimensional array in a0; a1 =
; the descriptor. The nop is the OPTION BASE adjustment; 8f80 ($25b) skips it.
;------------------------------------------------------------------------------
rt_float_array_address_1d:
	nop                                     ; OPTION BASE adjustment

;------------------------------------------------------------------------------
; Runtime routine $25b: as $104 (address of a(d0)) without the OPTION BASE adjustment.
;------------------------------------------------------------------------------
rt_float_array_address_1d_raw:
	movea.l	(a1)+,a0                        ; a0 = array data
	cmpi.w	#$1,(a1)                        ; one dimension?
	bne.s	.float_addr_indices             ; not one: error 18 or 15
	cmp.l	(a0)+,d0                        ; index below the element count?
	bcc.s	.float_addr_index               ; too large: error 16
	add.l	d0,d0                           ; index * 2
	adda.l	d0,a0                           ; a0 + index * 2
	add.l	d0,d0                           ; index * 4
	adda.l	d0,a0                           ; a0 + index * 6
	rts                                     ; a0 = the element
.float_addr_index:
	jmp	rn_array_index_error(a6)        ; error 16 (08f3a)
.float_addr_indices:
	jmp	rn_array_dims_error(a6)         ; error 18/15 (08f40)

; Runtime: a(index) = d0-d2 for a float array: the return address and then the index are on
; the stack; the value is rounded and packed into the element; returns by jmp (a2).
	dc.w	$025c                           ; word $025c (not code); 8fa0: a2 = return address

;------------------------------------------------------------------------------
; Runtime routine $160: a(index) = d0-d2 for a one-dimensional float array: a2 = the return
; address and d3 = the index from the stack, a1 = the descriptor; returns by jmp (a2).
;------------------------------------------------------------------------------
rt_float_array_put_1d:
	movea.l	(sp)+,a2                        ; a2 = return address
	move.l	(sp)+,d3                        ; d3 = index

;------------------------------------------------------------------------------
; Runtime routine $24d: the OPTION BASE nop of the 1-d float store (subq.l #1,d3 under BASE 1).
;------------------------------------------------------------------------------
rt_float_array_put_1d_base:
	nop                                     ; nop: subq.l #1,d3 under OPTION BASE 1

;------------------------------------------------------------------------------
; Runtime routine $25c: the 1-d float store without the OPTION BASE adjustment, d3 = index.
;------------------------------------------------------------------------------
rt_float_array_put_1d_raw:
	movea.l	(a1)+,a0                        ; a0 = array data
	cmpi.w	#$1,(a1)                        ; one dimension?
	bne.s	.float_store_indices            ; not one: error 18 or 15
	cmp.l	(a0)+,d3
	bcc.s	.float_store_index
	add.l	d3,d3                           ; * 6
	adda.l	d3,a0                           ; a0 + index * 2
	add.l	d3,d3                           ; index * 4
	adda.l	d3,a0                           ; a0 + index * 6: the element
	andi.w	#$fc00,d1                       ; exponent into the last word
	or.w	d2,d1                           ; low bits = exponent
	tst.l	d2                              ; sign in bit 31 of d2
	bmi.s	.float_store_sign               ; negative: keep the top bit
	bclr	#$1f,d0                         ; positive: clear the top bit
.float_store_sign:
	move.l	d0,(a0)+                        ; mantissa long
	move.w	d1,(a0)                         ; low mantissa bits and exponent
	jmp	(a2)                            ; return
.float_store_indices:
	jmp	rn_array_dims_error_a2(a6)      ; error 18/15 (08f3e)
.float_store_index:
	jmp	rn_array_index_error_a2(a6)     ; error 16 (08f38)

; Runtime: a%(index) = d0 for an integer array (index on the stack).
	dc.w	$025d                           ; word $025d (not code); code from 8fe4

;------------------------------------------------------------------------------
; Runtime: a%(index) = d0 for a one-dimensional integer array: a2 = the return address and
; d3 = the index are taken from the stack; 8fe8 is the OPTION BASE nop, 8fea skips it.
;------------------------------------------------------------------------------
rt_int_array_put_1d:
	movea.l	(sp)+,a2                        ; a2 = return address
	move.l	(sp)+,d3                        ; d3 = index

;------------------------------------------------------------------------------
; Runtime routine $24f: the OPTION BASE nop of the 1-d integer store.
;------------------------------------------------------------------------------
rt_int_array_put_1d_base:
	nop                                     ; OPTION BASE adjustment: subq.l #1,d3 under BASE 1

;------------------------------------------------------------------------------
; Runtime routine $25d: the 1-d integer store without the OPTION BASE adjustment.
;------------------------------------------------------------------------------
rt_int_array_put_1d_raw:
	movea.l	(a1)+,a0                        ; a0 = array data
	cmpi.w	#$1,(a1)                        ; one dimension?
	bne.s	.int_store_indices              ; not one: error 18 or 15
	cmp.l	(a0)+,d3                        ; index below the element count?
	bcc.s	.int_store_index                ; too large: error 16
	add.l	d3,d3                           ; * 4
	add.l	d3,d3                           ; offset of the element
	move.l	d0,0(a0,d3.l)                   ; store
	jmp	(a2)                            ; return
.int_store_indices:
	jmp	rn_array_dims_error_a2(a6)      ; error 18/15 (08f3e)
.int_store_index:
	jmp	rn_array_index_error_a2(a6)     ; error 16 (08f38)

; Runtime: a!(index) = d2 for a boolean array: sets or clears the bit.
	dc.w	$025e                           ; word $025e (not code); code from 900a

;------------------------------------------------------------------------------
; Runtime: a!(index) = d2 for a one-dimensional boolean array: return address and index
; from the stack; 900e is the OPTION BASE nop, 9010 skips it.
;------------------------------------------------------------------------------
rt_bool_array_put_1d:
	movea.l	(sp)+,a2                        ; a2 = return address
	move.l	(sp)+,d3                        ; d3 = index

;------------------------------------------------------------------------------
; Runtime routine $250: the OPTION BASE nop of the 1-d boolean store.
;------------------------------------------------------------------------------
rt_bool_array_put_1d_base:
	nop                                     ; OPTION BASE adjustment: subq.l #1,d3 under BASE 1

;------------------------------------------------------------------------------
; Runtime routine $25e: the 1-d boolean store without the OPTION BASE adjustment.
;------------------------------------------------------------------------------
rt_bool_array_put_1d_raw:
	movea.l	(a1)+,a0                        ; a0 = array data
	cmpi.w	#$1,(a1)                        ; one dimension?
	bne.s	.bool_store_indices             ; not one: error 18 or 15
	cmp.l	(a0)+,d3                        ; index below the element count?
	bcc.s	.bool_store_index               ; too large: error 16
	move.w	d3,d4                           ; d4 = bit number (btst/bset use the low 3 bits)
	lsr.l	#3,d3                           ; byte number
	tst.w	d2                              ; TRUE?
	beq.s	.bool_store_clear               ; FALSE: clear the bit
	bset	d4,0(a0,d3.l)                   ; set the bit
	jmp	(a2)                            ; return
.bool_store_clear:
	bclr	d4,0(a0,d3.l)                   ; clear the bit
	jmp	(a2)                            ; return
.bool_store_index:
	jmp	rn_array_index_error_a2(a6)     ; error 16 (08f38)
.bool_store_indices:
	jmp	rn_array_dims_error_a2(a6)      ; error 18/15 (08f3e)

; Runtime: a$(index) = the string at a0: the element's descriptor in a1, then the string
; assignment ($e6(a6) = 08658).
	dc.w	$025f                           ; word $025f (not code); code from 903a

;------------------------------------------------------------------------------
; Runtime: a$(index) = the string a0 for a one-dimensional string array: return address and
; index from the stack; 903e is the OPTION BASE nop, 9040 skips it.
;------------------------------------------------------------------------------
rt_string_array_put_1d:
	movea.l	(sp)+,a2                        ; a2 = return address
	move.l	(sp)+,d3                        ; d3 = index

;------------------------------------------------------------------------------
; Runtime routine $24e: the OPTION BASE nop of the 1-d string store.
;------------------------------------------------------------------------------
rt_string_array_put_1d_base:
	nop                                     ; OPTION BASE adjustment: subq.l #1,d3 under BASE 1

;------------------------------------------------------------------------------
; Runtime routine $25f: the 1-d string store without the OPTION BASE adjustment.
;------------------------------------------------------------------------------
rt_string_array_put_1d_raw:
	cmpi.w	#$1,4(a1)                       ; one dimension?
	bne.s	.string_store_indices           ; not one: error 18 or 15
	movea.l	(a1),a1                         ; a1 = array data
	cmp.l	(a1)+,d3                        ; index below the element count?
	bcc.s	.string_store_index             ; too large: error 16
	add.l	d3,d3                           ; * 6: the element's descriptor
	adda.l	d3,a1                           ; a1 + index * 2
	add.l	d3,d3                           ; index * 4
	adda.l	d3,a1                           ; a1 + index * 6
	pea	(a2)                            ; return address for the assignment
	jmp	rn_string_assign(a6)            ; string assignment (08670)
.string_store_index:
	jmp	rn_array_index_error_a2(a6)     ; error 16 (08f38)
.string_store_indices:
	jmp	rn_array_dims_error_a2(a6)      ; error 18/15 (08f3e)

;------------------------------------------------------------------------------
; Runtime: DIM of one array: d7 = number of dimensions (9064: one), d0 = the first bound, the
; others on the stack, a1 = the array descriptor. The element count is the product of the
; bounds + 1 (more than 16 bits each: error 17); already dimensioned: error 14. Float arrays
; (descriptor below $88(a4)) take 6 bytes an element, integer (below $8c(a4)) 4, boolean a bit.
; Room is made at the end of the array area $5c(a4) ($1f0(a6) and $e9(a6)), the bounds + 1
; are stored before the data, the data cleared; error 8 when it does not fit.
;------------------------------------------------------------------------------
rt_dim_one:
	moveq	#1,d7                           ; one dimension

;------------------------------------------------------------------------------
; Runtime routine $159: DIM with d7 dimensions, d0 = the first bound, the others on the stack,
; a1 = the array descriptor (see rt_dim_one above).
;------------------------------------------------------------------------------
rt_dim:
	move.l	d0,d6                           ; d6 = first bound

;------------------------------------------------------------------------------
; Runtime routine $255: DIM's OPTION BASE nop for the first bound (patched by OPTION BASE).
;------------------------------------------------------------------------------
rt_dim_base_first:
	nop                                     ; nop: patched by OPTION BASE
	move.w	d7,d4                           ; 4 bytes a dimension on the stack
	asl.w	#2,d4                           ; stack bytes of the other bounds
	addq.l	#1,d0                           ; count = bound + 1
	moveq	#0,d5                           ; d5 = offset of the bound on the stack

rt_dim_count_loop:
	addq.w	#4,d5                           ; next dimension
	cmp.w	d5,d4                           ; all bounds multiplied?
	beq.s	rt_dim_allocate                 ; yes: allocate
	move.l	0(sp,d5.w),d1                   ; its bound

;------------------------------------------------------------------------------
; Runtime routine $257: DIM's OPTION BASE nop for the other bounds (subq.l #1,d1).
;------------------------------------------------------------------------------
rt_dim_base_next:
	nop                                     ; nop: patched by OPTION BASE
	addq.l	#1,d1                           ; count of this dimension
	move.l	d0,d2                           ; both must fit 16 bits
	or.l	d1,d2                           ; bits 16-31 of either
	swap	d2                              ; into the low word
	mulu.w	d1,d0                           ; count * (bound + 1)
	tst.w	d2                              ; both fitted 16 bits?
	beq.s	rt_dim_count_loop               ; yes: next dimension

rt_dim_too_large:
	moveq	#17,d0                          ; error 17 Dim index too large

rt_dim_error:
	jmp	rn_error_entry(a6)              ; runtime error d0

rt_dim_allocate:
	tst.l	d0                              ; no elements: error 17
	beq.s	rt_dim_too_large
	tst.w	4(a1)                           ; already dimensioned?
	beq.s	.dim_type
	moveq	#14,d0                          ; error 14 Array dimensioned twice
	bra.s	rt_dim_error
.dim_type:
	cmpa.l	$88(a4),a1                      ; float array?
	bcs.s	.dim_float                      ; below the integer arrays: float or string, 6 bytes
	cmpa.l	$8c(a4),a1                      ; integer array?
	bcs.s	.dim_integer                    ; below the boolean arrays: integer, 4 bytes
	moveq	#15,d2                          ; boolean: words of 16 bits
	add.l	d2,d0                           ; count + 15
	lsr.l	#4,d0                           ; / 16: words
	bra.s	.dim_bytes
.dim_float:
	move.l	d0,d1                           ; float: * 3
	add.l	d0,d0                           ; * 2
	bcs.s	.dim_out_of_memory              ; overflow: out of memory
	add.l	d1,d0                           ; + * 1: * 3 words
	bcc.s	.dim_bytes                      ; no overflow: bytes
.dim_out_of_memory:
	moveq	#8,d0                           ; error 8 Out of memory
	bra.s	rt_dim_error
.dim_integer:
	add.l	d0,d0                           ; integer: * 2
	bcs.s	.dim_out_of_memory              ; overflow: out of memory
.dim_bytes:
	add.l	d0,d0                           ; * 2: bytes
	bcs.s	.dim_out_of_memory              ; overflow: out of memory
	move.l	d0,d1                           ; d1 = data bytes
	add.l	d5,d0                           ; + the bound longs
	bcs.s	.dim_out_of_memory              ; overflow: out of memory
	movea.l	(sp),a2                         ; return address
	move.l	d6,(sp)                         ; first bound in its place
	movem.l	d1/a1,-(sp)                     ; data size and descriptor
	move.l	d0,-(sp)                        ; total size
	movea.l	$5c(a4),a0                      ; end of the array area
	jsr	rn_string_collect_moved_up(a6)  ; move the string back pointers (08de8)
	move.l	(sp)+,d0                        ; d0 = total size
	jsr	rn_array_make_room(a6)          ; make room (094aa)
	movem.l	(sp)+,d2/a1                     ; d2 = data bytes, a1 = descriptor
	move.l	a0,(a1)+                        ; descriptor: data address
	move.w	d7,(a1)+                        ; and dimensions
	bra.s	rt_dim_store_next               ; store the bounds, last first

rt_dim_store_bound:
	move.l	(sp)+,d0                        ; bound

;------------------------------------------------------------------------------
; Runtime routine $256: DIM's OPTION BASE nop for the bounds stored before the data.
;------------------------------------------------------------------------------
rt_dim_base_store:
	nop                                     ; nop: patched by OPTION BASE
	addq.l	#1,d0                           ; + 1: element count
	move.l	d0,(a0)+                        ; element count before the data

rt_dim_store_next:
	subq.w	#4,d5                           ; next bound (from the last)
	bpl.s	rt_dim_store_bound              ; until all bounds are stored
	moveq	#0,d1                           ; clear the data
	lsr.l	#2,d2                           ; in longs
	bcc.s	.dim_clear_next                 ; no odd word
	move.w	d1,(a0)+                        ; odd word
	bra.s	.dim_clear_next
.dim_clear:
	move.l	d1,(a0)+                        ; clear a long
.dim_clear_next:
	subq.l	#1,d2                           ; count longs
	bpl.s	.dim_clear                      ; until all are cleared
	jmp	(a2)                            ; return

;------------------------------------------------------------------------------
; Runtime: float array element of a multi-dimensional array: $ea(a6) (09172) checks the
; indices and gives a0, d0 = the element number; exit d0-d2 unpacked, returns by jmp (a2).
; 9132: integer element in d0. 9142: boolean element in d2. 9156: the address of a float
; element in a0.
;------------------------------------------------------------------------------
rt_float_array_get:
	movea.l	(sp)+,a2                        ; return address
	jsr	rn_array_index_read(a6)         ; check the indices (09172)
	add.l	d0,d0                           ; * 6
	adda.l	d0,a0                           ; a0 + number * 2
	add.l	d0,d0                           ; number * 4
	adda.l	d0,a0                           ; a0 + number * 6
	move.l	(a0)+,d0                        ; unpack the element
	move.w	(a0),d1                         ; exponent and low mantissa word
	move.l	d0,d2                           ; d2 = sign bit (bit 31)
	bset	#$1f,d0                         ; the implied top mantissa bit
	move.w	d1,d2                           ; the 10-bit exponent
	andi.w	#$3ff,d2                        ; into d2
	sub.w	d2,d1                           ; mantissa low bits only in d1
	jmp	(a2)                            ; return

;------------------------------------------------------------------------------
; Runtime: a%(i,j..) of a multi-dimensional integer array: index check ($ea(a6)), exit d0 =
; the element; returns by jmp (a2).
;------------------------------------------------------------------------------
rt_int_array_get:
	movea.l	(sp)+,a2                        ; return address
	jsr	rn_array_index_read(a6)         ; index check (09172): a0 = data, d0 = element number
	add.l	d0,d0                           ; * 4
	add.l	d0,d0                           ; * 4
	move.l	0(a0,d0.l),d0                   ; the element
	jmp	(a2)                            ; return

;------------------------------------------------------------------------------
; Runtime: a!(i,j..) of a multi-dimensional boolean array: exit d2 = -1 or 0; returns by
; jmp (a2).
;------------------------------------------------------------------------------
rt_bool_array_get:
	movea.l	(sp)+,a2                        ; a2 = return address
	jsr	rn_array_index_read(a6)         ; index check (09172)
	move.w	d0,d1                           ; bit number
	lsr.l	#3,d0                           ; byte number
	btst	d1,0(a0,d0.l)                   ; the bit
	sne	d2                              ; TRUE / FALSE
	ext.w	d2                              ; as a word
	jmp	(a2)                            ; return

;------------------------------------------------------------------------------
; Runtime: the address of the float element a(i,j..) in a0; returns by jmp (a2).
;------------------------------------------------------------------------------
rt_float_array_address:
	movea.l	(sp)+,a2                        ; a2 = return address
	jsr	rn_array_index_read(a6)         ; index check (09172)
	add.l	d0,d0                           ; number * 2
	adda.l	d0,a0                           ; a0 + number * 2
	add.l	d0,d0                           ; number * 4
	adda.l	d0,a0                           ; a0 + number * 6: the element
	jmp	(a2)                            ; return

;------------------------------------------------------------------------------
; Runtime: index check of a multi-dimensional array element for reading ($ea(a6)): a1 = the
; array descriptor, d7 = the number of indices given, d0 = the first index, the others on the
; stack after the return address. The dimensions must match ($ff(a6), error 18/15); each index
; is checked against its element count and the element number built; the nops become
; subq.l #1 under OPTION BASE 1. Exit a0 = the first element, d0 = the element number; returns
; by jmp (a1). The first index out of range goes to $ff(a6) (error 18, not 16), and the later
; ones use bhi, so an index equal to the count passes.
;------------------------------------------------------------------------------
rt_array_index_read:
	movea.l	(a1)+,a0                        ; a0 = array data
	cmp.w	(a1),d7                         ; as many indices as dimensions?
	bne.s	rt_array_index_read_dims        ; not the same: error
	movea.l	(sp)+,a1                        ; return address

;------------------------------------------------------------------------------
; Runtime routine $260: the OPTION BASE nop for the first index of rt_array_index_read.
;------------------------------------------------------------------------------
rt_array_index_read_base_first:
	nop                                     ; nop: subq.l #1,d0 under OPTION BASE 1
	move.l	(a0)+,d5                        ; element count of the first dimension
	cmp.l	d5,d0                           ; first index below its count?
	bcs.s	rt_array_index_read_count       ; in range

rt_array_index_read_dims:
	jmp	rn_array_dims_error_a2(a6)      ; wrong indices (08f3e); also the first index out of range

rt_array_index_read_large:
	jmp	rn_array_index_error_a2(a6)     ; index too large (08f38)

rt_array_index_read_next:
	move.l	(a0)+,d5                        ; element count of this dimension
	move.w	d5,d6                           ; d6 = element count (16 bits)
	mulu.w	d0,d6                           ; number so far * count
	move.l	(sp)+,d0                        ; next index

;------------------------------------------------------------------------------
; Runtime routine $261: the OPTION BASE nop for the next indices of rt_array_index_read.
;------------------------------------------------------------------------------
rt_array_index_read_base_next:
	nop                                     ; nop: patched by OPTION BASE
	cmp.l	d5,d0                           ; bhi: an index equal to the count passes
	bhi.s	rt_array_index_read_large       ; above the count: error 16
	add.l	d6,d0                           ; element number

rt_array_index_read_count:
	subq.w	#1,d7                           ; one index fewer to do
	bne.s	rt_array_index_read_next        ; more indices
	jmp	(a1)                            ; return

;------------------------------------------------------------------------------
; Runtime: a(i,j..) = d0-d2 for a float array: index check $ef(a6) (091f8), then packed into
; the element ($e1(a6) = 05bae); returns by jmp (a2). 91a8: integer element = d0. 91b8:
; boolean element = d2. 91d2: string element = the string at a0 ($e6(a6) = 08658).
;------------------------------------------------------------------------------
rt_float_array_put:
	movea.l	(sp)+,a2                        ; a2 = return address
	jsr	rn_array_index_write(a6)        ; index check (091f8)
	add.l	d3,d3                           ; * 6
	adda.l	d3,a0                           ; a0 + number * 2
	add.l	d3,d3                           ; number * 4
	adda.l	d3,a0                           ; a0 + number * 6: the element
	pea	(a2)                            ; return address for the pack
	jmp	rn_float_store(a6)              ; pack d0-d2 into (a0) (05bc6)

;------------------------------------------------------------------------------
; Runtime: a%(i,j..) = d0 for a multi-dimensional integer array; returns by jmp (a2).
;------------------------------------------------------------------------------
rt_int_array_put:
	movea.l	(sp)+,a2                        ; a2 = return address
	jsr	rn_array_index_write(a6)        ; index check (091f8): a0 = data, d3 = element number
	add.l	d3,d3                           ; * 4
	add.l	d3,d3                           ; * 4
	move.l	d0,0(a0,d3.l)                   ; store
	jmp	(a2)                            ; return

;------------------------------------------------------------------------------
; Runtime: a!(i,j..) = d2 for a multi-dimensional boolean array; returns by jmp (a2).
;------------------------------------------------------------------------------
rt_bool_array_put:
	movea.l	(sp)+,a2                        ; a2 = return address
	jsr	rn_array_index_write(a6)        ; index check (091f8)
	move.w	d3,d4                           ; bit number
	lsr.l	#3,d3                           ; byte number
	tst.w	d2                              ; TRUE?
	bne.s	.bool_set                       ; TRUE: set the bit
	bclr	d4,0(a0,d3.l)                   ; clear the bit
	jmp	(a2)                            ; return
.bool_set:
	bset	d4,0(a0,d3.l)                   ; set the bit
	jmp	(a2)                            ; return

;------------------------------------------------------------------------------
; Runtime: a$(i,j..) = the string at a0 for a multi-dimensional string array: the string
; assignment ($e6(a6)) into the element's descriptor; returns by jmp (a2).
;------------------------------------------------------------------------------
rt_string_array_put:
	move.l	a0,d0                           ; d0 = source descriptor
	movea.l	(sp)+,a2                        ; a2 = return address
	jsr	rn_array_index_write(a6)        ; index check (091f8)
	add.l	d3,d3                           ; * 6: the element's descriptor
	adda.l	d3,a0                           ; a0 + number * 2
	add.l	d3,d3                           ; number * 4
	adda.l	d3,a0                           ; a0 + number * 6: the element
	movea.l	d0,a1                           ; a1 = source descriptor
	exg	a1,a0                           ; a0 = source, a1 = element
	pea	(a2)                            ; return address for the assignment
	jmp	rn_string_assign(a6)            ; string assignment (08670)

;------------------------------------------------------------------------------
; Runtime: index check for stores ($ef(a6)): as 9166 with the first index in d3 (taken from
; the stack after the return address). Exit a0 = the first element, d3 = the element number.
;------------------------------------------------------------------------------
rt_array_index_write:
	movea.l	(a1)+,a0                        ; a0 = array data
	cmp.w	(a1),d7                         ; as many indices as dimensions?
	bne.s	rt_array_index_write_dims       ; not the same: error
	movea.l	(sp)+,a1                        ; return address
	move.l	(sp)+,d3                        ; first index

;------------------------------------------------------------------------------
; Runtime routine $262: the OPTION BASE nop for the first index of rt_array_index_write.
;------------------------------------------------------------------------------
rt_array_index_write_base_first:
	nop                                     ; nop: patched by OPTION BASE
	move.l	(a0)+,d5                        ; element count of the first dimension
	cmp.l	d5,d3                           ; first index in range?
	bcs.s	rt_array_index_write_count      ; in range

rt_array_index_write_dims:
	jmp	rn_array_dims_error_a2(a6)      ; wrong indices (08f3e); also the first index out of range

rt_array_index_write_large:
	jmp	rn_array_index_error_a2(a6)     ; index too large (08f38)

rt_array_index_write_next:
	move.l	(a0)+,d5                        ; element count of this dimension
	move.w	d5,d6                           ; d6 = element count (16 bits)
	mulu.w	d3,d6                           ; number so far * count
	move.l	(sp)+,d3                        ; next index

;------------------------------------------------------------------------------
; Runtime routine $263: the OPTION BASE nop for the next indices of rt_array_index_write.
;------------------------------------------------------------------------------
rt_array_index_write_base_next:
	nop                                     ; nop: patched by OPTION BASE
	cmp.l	d5,d3                           ; bhi: an index equal to the count passes
	bhi.s	rt_array_index_write_large      ; above the count: error 16
	add.l	d6,d3                           ; + the index: element number

rt_array_index_write_count:
	subq.w	#1,d7                           ; one index fewer to do
	bne.s	rt_array_index_write_next       ; more indices
	jmp	(a1)                            ; return

;------------------------------------------------------------------------------
; Runtime: SWAP of two 4-byte variables: d0 and a1 their addresses.
;------------------------------------------------------------------------------
rt_swap_long:
	movea.l	d0,a0                           ; exchange the longs
	move.l	(a0),d0                         ; d0 = the first long
	move.l	(a1),(a0)                       ; second into the first
	move.l	d0,(a1)                         ; first into the second
	rts

;------------------------------------------------------------------------------
; Runtime: SWAP of two booleans: d0/d1 and d3/d4 address and bit of each. A simple variable
; (address below $88(a4)) first gets the word $0100 and bit 0; the bits are exchanged when they
; differ. The second test compares d1 (the first bit number) with $88(a4), not the second
; address, so the second boolean is always treated as a simple variable.
;------------------------------------------------------------------------------
rt_swap_bool:
	movea.l	d0,a0                           ; first boolean
	cmpa.l	$88(a4),a0                      ; a simple variable?
	bcc.s	.swap_second                    ; not a simple variable: keep d1
	move.w	#$100,(a0)                      ; word $0100, bit 0
	moveq	#0,d1                           ; bit 0
.swap_second:
	movea.l	d3,a1                           ; second boolean
	cmp.l	$88(a4),d1                      ; compares d1, not a1: never taken (see the header)
	bcc.s	.swap_bits                      ; never taken (see the header)
	move.w	#$100,(a1)                      ; word $0100: bit 0 of the high byte
	moveq	#0,d4                           ; bit 0
.swap_bits:
	btst	d1,(a0)                         ; first bit set?
	beq.s	.swap_first_clear               ; first clear
	btst	d4,(a1)                         ; second set too?
	beq.s	.swap_done
.swap_flip:
	bchg	d1,(a0)                         ; different: flip both
	bchg	d4,(a1)                         ; second bit flipped
.swap_done:
	rts
.swap_first_clear:
	btst	d4,(a1)                         ; second set?
	bne.s	.swap_flip                      ; different: flip both
	rts

;------------------------------------------------------------------------------
; Runtime: SWAP of two strings: d0 and a1 the descriptors; address and length are exchanged
; and both back pointers after the texts are pointed at their new descriptors.
;------------------------------------------------------------------------------
rt_swap_string_pointer:
	movea.l	d0,a0                           ; first descriptor

;------------------------------------------------------------------------------
; Runtime: SWAP of two strings: a0 and a1 the descriptors; address and length are exchanged
; and both back pointers after the texts are pointed at their new descriptors. 9256 takes the
; first descriptor from d0.
;------------------------------------------------------------------------------
rt_swap_string:
	movea.l	(a0),a2                         ; a2 = first text
	move.l	(a1),(a0)+                      ; exchange the addresses
	move.l	a2,(a1)+                        ; first text into the second
	moveq	#0,d2                           ; d2 = first length
	move.w	(a0),d2                         ; and the lengths
	move.w	(a1),(a0)                       ; second length into the first
	move.w	d2,(a1)                         ; first length into the second
	beq.s	.swap_string_second             ; empty: no back pointer
	subq.l	#4,a1                           ; a1 = second descriptor
	addq.w	#1,d2                           ; even length
	andi.w	#$fffe,d2                       ; the back pointer follows the text
	move.l	a1,0(a2,d2.l)                   ; back pointer to the second descriptor
.swap_string_second:
	move.w	(a0),d2                         ; the first descriptor's new length
	beq.s	.swap_string_done               ; empty: no back pointer
	movea.l	-(a0),a2                        ; a0 = first descriptor, a2 = its new text
	addq.w	#1,d2                           ; even length
	andi.w	#$fffe,d2                       ; the back pointer follows the text
	move.l	a0,0(a2,d2.l)                   ; back pointer to the first descriptor
.swap_string_done:
	rts

;------------------------------------------------------------------------------
; Runtime: VARPTR of an element of a one-dimensional array ($ea(a6)): 9286 float element (d0 =
; its address), 9298 string element (d0 = the string's address from its descriptor), 92ac
; integer element, 92bc boolean element (d0 = the byte, d1 = the bit).
;------------------------------------------------------------------------------
rt_varptr_float_element_1d:
	moveq	#1,d7                           ; one index

;------------------------------------------------------------------------------
; Runtime: VARPTR of a float array element: d7 = the number of indices (9286: one), index
; check ($ea(a6)); exit d0 = the element's address. Returns by jmp (a2).
;------------------------------------------------------------------------------
rt_varptr_float_element:
	movea.l	(sp)+,a2                        ; return address
	jsr	rn_array_index_read(a6)         ; index check (09172)
	add.l	d0,d0                           ; * 6
	adda.l	d0,a0                           ; a0 + index * 2
	add.l	d0,d0                           ; index * 4
	add.l	a0,d0                           ; d0 = element address
	jmp	(a2)

;------------------------------------------------------------------------------
; Runtime routine $267: VARPTR of a one-dimensional string array element (d7 = 1).
;------------------------------------------------------------------------------
rt_varptr_string_element_1d:
	moveq	#1,d7                           ; one index

;------------------------------------------------------------------------------
; Runtime: VARPTR of a string array element: exit d0 = the text address from the element's
; descriptor (9298: one index). Returns by jmp (a2).
;------------------------------------------------------------------------------
rt_varptr_string_element:
	movea.l	(sp)+,a2                        ; a2 = return address
	jsr	rn_array_index_read(a6)         ; index check (09172)
	add.l	d0,d0                           ; index * 2
	adda.l	d0,a0                           ; a0 + index * 2
	add.l	d0,d0                           ; index * 4
	adda.l	d0,a0                           ; a0 + index * 6: the descriptor
	move.l	(a0),d0                         ; the string's address
	jmp	(a2)                            ; return

;------------------------------------------------------------------------------
; Runtime routine $269: VARPTR of a one-dimensional integer array element (d7 = 1).
;------------------------------------------------------------------------------
rt_varptr_int_element_1d:
	moveq	#1,d7                           ; one index

;------------------------------------------------------------------------------
; Runtime: VARPTR of an integer array element: exit d0 = its address (92ac: one index).
; Returns by jmp (a2).
;------------------------------------------------------------------------------
rt_varptr_int_element:
	movea.l	(sp)+,a2                        ; a2 = return address
	jsr	rn_array_index_read(a6)         ; index check (09172)
	add.l	d0,d0                           ; * 4
	add.l	d0,d0                           ; * 4
	add.l	a0,d0                           ; d0 = element address
	jmp	(a2)                            ; return

;------------------------------------------------------------------------------
; Runtime routine $271: VARPTR of a one-dimensional boolean array element (d7 = 1).
;------------------------------------------------------------------------------
rt_varptr_bool_element_1d:
	moveq	#1,d7                           ; one index

;------------------------------------------------------------------------------
; Runtime: VARPTR of a boolean array element: exit d0 = the byte's address, d1 = the bit
; (92bc: one index). Returns by jmp (a2).
;------------------------------------------------------------------------------
rt_varptr_bool_element:
	movea.l	(sp)+,a2                        ; a2 = return address
	jsr	rn_array_index_read(a6)         ; index check (09172)
	move.w	d0,d1                           ; d1 = bit
	lsr.l	#3,d0                           ; byte number
	add.l	a0,d0                           ; d0 = the byte's address
	jmp	(a2)                            ; return

;------------------------------------------------------------------------------
; Runtime: the number of elements of the array whose descriptor is at a0 ($94(a6)): the
; product of the element counts stored before the data. Exit d0 = the count (0 when not
; dimensioned), a1 = the first element, a0 = the descriptor + 4.
;------------------------------------------------------------------------------
rt_array_element_count:
	moveq	#0,d0                           ; d0 = 0 when not dimensioned
	movea.l	(a0)+,a1                        ; a1 = array data
	move.w	(a0),d2                         ; dimensions
	beq.s	.count_done                     ; not dimensioned: 0
	move.l	(a1)+,d0                        ; first element count
	subq.l	#1,d2                           ; dimensions after the first
	bra.s	.count_next                     ; multiply in the others
.count_bound:
	move.l	(a1)+,d1                        ; next element count
	mulu.w	d1,d0                           ; * the next one
.count_next:
	dbra	d2,.count_bound                 ; more dimensions
.count_done:
	rts

;------------------------------------------------------------------------------
; Runtime: the variable type of the address d0 by the area table at $70(a4)..$90(a4) (the
; starts of the 8 variable areas: float, string, integer, boolean, then the four array kinds).
; Exit d0 = the type 0..7, -1 when the address is outside or not on an element boundary
; (6 bytes, integers 4, booleans 2).
;------------------------------------------------------------------------------
rt_pointer_type:
	lea	$90(a4),a0                      ; end of the area table
	move.l	d0,d1                           ; d1 = the address
	moveq	#7,d0                           ; 8 areas
	cmp.l	(a0),d1                         ; past the last area
	bcc.s	.pointer_bad                    ; at or past the end: not a variable
.pointer_area:
	cmp.l	-(a0),d1                        ; find the area holding d1
	dbcc	d0,.pointer_area                ; down to the first area
	bcs.s	.pointer_bad                    ; below the first
	sub.l	(a0),d1                         ; offset in the area
	cmpi.w	#$2,d0                          ; integer
	beq.s	.pointer_integer                ; integers: 4-byte steps
	cmpi.w	#$3,d0                          ; boolean
	beq.s	.pointer_boolean                ; booleans
	divu.w	#$6,d1                          ; 6-byte elements
	swap	d1                              ; remainder into the low word
	tst.w	d1                              ; on an element?
	beq.s	.pointer_done                   ; yes: d0 = the type
.pointer_bad:
	moveq	#-1,d0                          ; not a variable: -1
.pointer_done:
	rts
.pointer_boolean:
	andi.b	#$1,d1                          ; boolean: even
.pointer_integer:
	andi.b	#$3,d1                          ; integer: a multiple of 4
	beq.s	.pointer_done                   ; on an element: d0 = the type
	bra.s	.pointer_bad                    ; not on an element

;------------------------------------------------------------------------------
; Runtime: rts of ERASE for an array that is not dimensioned.
;------------------------------------------------------------------------------
rt_erase_not_dimensioned:
	rts

;------------------------------------------------------------------------------
; Runtime: ERASE a(): a0 = the array descriptor. Clears its dimension count, drops its data
; and bounds (strings of a string array through $1f1(a6) = 08e28), lowers the data address of
; every array descriptor above it ($80(a4)..$90(a4)), moves the memory above down over it
; ($ec(a6) = 0955a) and lowers $5c(a4) and a3.
;------------------------------------------------------------------------------
rt_erase:
	jsr	rn_array_element_count(a6)      ; element count, a1 = data (092d8)
	tst.w	(a0)                            ; not dimensioned: nothing
	beq.s	rt_erase_not_dimensioned        ; not dimensioned: nothing
	clr.w	(a0)                            ; no dimensions now
	move.l	-(a0),d6                        ; d6 = start of the data with its bounds
	cmpa.l	$8c(a4),a0                      ; boolean array?
	bcc.s	.erase_boolean                  ; boolean array
	cmpa.l	$88(a4),a0                      ; float or string array?
	bcs.s	.erase_float                    ; float or string array
	add.l	d0,d0                           ; integer: * 4
	add.l	d0,d0                           ; integer: * 2
	bra.s	.erase_size                     ; * 2 again: bytes
.erase_boolean:
	addi.l	#$f,d0                          ; boolean: bytes, even
	lsr.l	#3,d0                           ; / 8: bytes
	bclr	#$0,d0                          ; even
	bra.s	.erase_size
.erase_float:
	add.l	d0,d0                           ; float/string: * 6
	move.l	d0,d1                           ; d1 = * 2
	add.l	d0,d0                           ; * 4
	add.l	d1,d0                           ; + * 2: * 6
.erase_size:
	lea	0(a1,d0.l),a2                   ; a2 = end of the data
	move.l	a2,d0                           ; d0 = bytes removed
	sub.l	d6,d0                           ; d0 = bytes removed (bounds and data)
	movem.l	d0/a2,-(sp)                     ; keep size and end
	movea.l	d6,a0                           ; a0 = start of the removed part
	jsr	rn_string_collect_removed(a6)   ; drop the strings, fix back pointers (08e40)
	movem.l	(sp)+,d7/a2                     ; d7 = bytes removed
	movea.l	$80(a4),a0                      ; the array descriptors
	move.l	$90(a4),d0                      ; to the end of the area table
.erase_fix_descriptor:
	movea.l	(a0)+,a1                        ; data address
	move.w	(a0)+,d1                        ; d1 = dimensions
	beq.s	.erase_next_descriptor          ; not dimensioned
	cmpa.l	a2,a1                           ; below the removed part
	bcs.s	.erase_next_descriptor          ; below the removed part: unchanged
	sub.l	d7,-$6(a0)                      ; lowered
.erase_next_descriptor:
	cmp.l	a0,d0                           ; descriptor end
	bhi.s	.erase_fix_descriptor           ; more descriptors
	move.l	a3,d0                           ; bytes above it
	sub.l	a2,d0                           ; d0 = bytes from the end of the removed part to a3
	movea.l	a2,a0                           ; move from the end of the removed part
	movea.l	d6,a1                           ; to its start
	sub.l	d7,$5c(a4)                      ; array area end lowered
	suba.l	d7,a3                           ; control stack lowered
	jmp	rn_copy_bytes_forward(a6)       ; memory copy (09566)

;------------------------------------------------------------------------------
; Runtime: ARRAYFILL a(),x: the float d0-d2 packed ($f3(a6) = 061be) into every element.
; 93b8: integer array, d0. 93d0: boolean array, d2 (whole words of 0 or -1).
;------------------------------------------------------------------------------
rt_arrayfill_float:
	jsr	rn_float_round_packed(a6)       ; pack the float (061d6)
	move.l	d0,d5                           ; d5 = mantissa long
	move.w	d1,d6                           ; d6 = low mantissa and exponent word
	jsr	rn_array_element_count(a6)      ; element count, a1 = data (092d8)
	bra.s	.fill_float_next                ; count down
.fill_float:
	move.l	d5,(a1)+                        ; one element
	move.w	d6,(a1)+                        ; low mantissa and exponent word
.fill_float_next:
	dbra	d0,.fill_float                  ; low word of the count
	subi.l	#$10000,d0                      ; high word of the count
	bpl.s	.fill_float                     ; more elements
	rts

;------------------------------------------------------------------------------
; Runtime: ARRAYFILL a%(),d0: every element of the integer array a0 set to d0.
;------------------------------------------------------------------------------
rt_arrayfill_int:
	move.l	d0,d6                           ; the value
	jsr	rn_array_element_count(a6)      ; element count, a1 = data (092d8)
	bra.s	.fill_int_next                  ; count down
.fill_int:
	move.l	d6,(a1)+                        ; one element
.fill_int_next:
	dbra	d0,.fill_int                    ; low word of the count
	subi.l	#$10000,d0                      ; high word
	bpl.s	.fill_int                       ; more elements
	rts

;------------------------------------------------------------------------------
; Runtime: ARRAYFILL a!(),d2: whole words of 0 or -1 written over the boolean array a0.
;------------------------------------------------------------------------------
rt_arrayfill_bool:
	move.w	d2,d6                           ; boolean value
	beq.s	.fill_bool_start                ; FALSE: 0
	moveq	#-1,d6                          ; TRUE: all bits
.fill_bool_start:
	jsr	rn_array_element_count(a6)      ; element count, a1 = data (092d8)
	addq.l	#7,d0                           ; count in words
	lsr.l	#4,d0                           ; count bits / 16 words; carry set when count % 16 >= 8
	bcc.s	.fill_bool_next                 ; no carry: dbra over the words
.fill_bool:
	move.w	d6,(a1)+                        ; one word
.fill_bool_next:
	dbra	d0,.fill_bool                   ; low word of the count
	subi.l	#$10000,d0                      ; high word
	bpl.s	.fill_bool                      ; more words
	rts

;------------------------------------------------------------------------------
; Runtime: number assignment through a pointer (*x): a1 = the address. In the integer area
; ($78(a4)..$7c(a4), 4-aligned) d0-d2 is converted ($f1(a6)) and stored; in the boolean area
; (to $80(a4), even) the word d2; in the float area ($70(a4)..$74(a4), on a 6-byte element) the
; float is packed ($e1(a6)). Anywhere else: error 64 (Pointer (*x) error).
;------------------------------------------------------------------------------
rt_pointer_assign_number:
	cmpa.l	$78(a4),a1                      ; integer area or above?
	bcc.s	.poke_not_float                 ; integer, boolean or above
	cmpa.l	$74(a4),a1                      ; string area?
	bcc.s	rt_pointer_error                ; string area or above: error
	move.l	a1,d3                           ; offset in the float area
	sub.l	$70(a4),d3                      ; offset in the float area
	bmi.s	rt_pointer_error                ; below it: error
	divu.w	#$6,d3                          ; on a 6-byte element?
	swap	d3                              ; on an element?
	tst.w	d3                              ; on an element?
	bne.s	rt_pointer_error                ; no: error
	movea.l	a1,a0                           ; pack d0-d2 into (a0) (05bc6)
	jmp	rn_float_store(a6)              ; pack d0-d2 into (a0) (05bc6)
.poke_not_float:
	cmpa.l	$7c(a4),a1                      ; boolean area or above?
	bcc.s	.poke_boolean                   ; yes
	move.l	a1,d3                           ; offset in the integer area
	sub.l	$78(a4),d3                      ; offset in the integer area
	andi.b	#$3,d3                          ; a multiple of 4?
	bne.s	rt_pointer_error                ; no: error
	jsr	rn_float_to_long(a6)            ; float to integer (02b20)
	move.l	d0,(a1)                         ; store it
	rts
.poke_boolean:
	cmpa.l	$80(a4),a1                      ; past the boolean area
	bcc.s	rt_pointer_error                ; past it: error
	move.l	a1,d3                           ; boolean address must be even
	andi.b	#$1,d3                          ; even?
	bne.s	rt_pointer_error                ; odd: error
	move.w	d2,(a1)                         ; store the boolean
	rts

;------------------------------------------------------------------------------
; Runtime: error 64 (Pointer (*x) error).
;------------------------------------------------------------------------------
rt_pointer_error:
	moveq	#64,d0                          ; error 64 Pointer (*x) error
	jmp	rn_error_entry(a6)              ; runtime error d0

;------------------------------------------------------------------------------
; Runtime: string assignment through a pointer: a1 must be a descriptor in the string area
; ($74(a4)..$78(a4), 6-byte steps), then the string assignment ($e6(a6)); else error 64.
;------------------------------------------------------------------------------
rt_pointer_assign_string:
	cmpa.l	$78(a4),a1                      ; past the string area
	bcc.s	rt_pointer_error                ; past it: error
	move.l	a1,d3                           ; offset in the string area
	sub.l	$74(a4),d3                      ; offset in the string area
	bmi.s	rt_pointer_error                ; below it: error
	divu.w	#$6,d3                          ; on a descriptor?
	swap	d3                              ; remainder
	tst.w	d3                              ; on a descriptor?
	bne.s	rt_pointer_error                ; no: error 64
	jmp	rn_string_assign(a6)            ; string assignment (08670)

;------------------------------------------------------------------------------
; Data: word $015a, not code (decoded as bchg).
;------------------------------------------------------------------------------
	bchg	d0,(a2)+                        ; word $015a, not code

;------------------------------------------------------------------------------
; Runtime: SWAP of an array with one given by pointer: a0 = the array descriptor, d0 = the
; pointer. a0 must lie in one of the array descriptor areas ($80(a4)..$8c(a4)) and d0 on a
; 6-byte step of the same area (else error 64); the two descriptors are exchanged. The offset
; is compared with the next area's start address, not its size.
;------------------------------------------------------------------------------
rt_swap_array_pointer:
	movea.l	d0,a1                           ; a1 = the pointer
	lea	$8c(a4),a2                      ; the boolean array area start
	cmpa.l	(a2),a0                         ; find the array area of a0
	bcc.s	.swap_array_area                ; in the boolean array area
	cmpa.l	-(a2),a0                        ; string array area?
	bcc.s	.swap_array_area                ; in the integer array area
	cmpa.l	-(a2),a0                        ; integer array area? (order of areas from $80(a4) up)
	bcc.s	.swap_array_area                ; in the string array area
	cmpa.l	-(a2),a0                        ; float array area?
	bcs.s	rt_pointer_error                ; not an array: error
.swap_array_area:
	sub.l	(a2),d0                         ; offset of the pointer in it
	cmp.l	4(a2),d0                        ; compared with the next area's start
	bcc.s	rt_pointer_error                ; past it: error
	divu.w	#$6,d0                          ; on a descriptor?
	swap	d0                              ; remainder into the low word
	tst.w	d0                              ; on a descriptor?
	bne.s	rt_pointer_error                ; no: error 64
	move.l	a0,d0                           ; a0 = the array descriptor

;------------------------------------------------------------------------------
; Runtime: SWAP of two arrays: a0 (9490) or d0 (948e) and a1 the descriptors; address and
; dimension word are exchanged (the bounds stay with the data).
;------------------------------------------------------------------------------
rt_swap_array_from_d0:
	movea.l	d0,a0                           ; a0 = first descriptor

;------------------------------------------------------------------------------
; Runtime routine $15a: SWAP of the arrays whose descriptors are at a0 and a1.
;------------------------------------------------------------------------------
rt_swap_array:
	move.l	(a0),d0                         ; exchange the descriptors
	move.l	(a1),(a0)+                      ; second into the first
	move.l	d0,(a1)+                        ; first into the second
	move.w	(a0),d0                         ; the dimension words
	move.w	(a1),(a0)                       ; exchanged
	move.w	d0,(a1)                         ; likewise
	rts

;------------------------------------------------------------------------------
; Runtime: makes d0 bytes of room at the end of the array area ($e9(a6)): the memory from
; $5c(a4) up to a3 (the control stack) is moved up by d0 ($eb(a6) = 094d4, from the end),
; $5c(a4) and a3 are raised. Garbage collection when it would reach $60(a4), then error 8.
; Exit a0 = the room, d0 = its size.
;------------------------------------------------------------------------------
rt_array_make_room:
	move.l	d0,d1                           ; d1 = room wanted
	movea.l	a3,a0                           ; a0 = top of the control stack
	lea	0(a0,d0.l),a1                   ; new top
	cmpa.l	$60(a4),a1                      ; below the string area?
	bcs.s	.room                           ; room: move
	jsr	rn_string_garbage_collect(a6)   ; garbage collection (08504)
	cmpa.l	$60(a4),a1                      ; room now?
	bcc.s	.no_room                        ; still no room
.room:
	move.l	a0,d0                           ; bytes to move: array end .. a3
	sub.l	$5c(a4),d0                      ; minus the end of the array area
	jsr	rn_copy_bytes_backward(a6)      ; copy from the end (094e0)
	movea.l	$5c(a4),a0                      ; a0 = the room
	add.l	d1,$5c(a4)                      ; array area end raised
	adda.l	d1,a3                           ; control stack raised
	move.l	d1,d0                           ; d0 = size of the room
	rts
.no_room:
	moveq	#8,d0                           ; error 8 Out of memory
	jmp	rn_error_entry(a6)              ; runtime error d0

;------------------------------------------------------------------------------
; Runtime routine $eb (copied into compiled programs; also called by the compiler at $04b2a):
; copy d0.l bytes downwards, from below a0 to below a1 (move -(a0),-(a1)).
; The low bits of d0 select 1, 2, 4, 8, 16 and 32 byte moves, then 128-byte blocks
; (bit 6 enters the loop half way); only the low word of the block count is used.
; Exit: a0/a1 lowered by d0, d0 = -1.
;------------------------------------------------------------------------------
rt_copy_bytes_backward:
	lsr.l	#1,d0                           ; bit 0 of the count: one byte
	bcc.s	.bwd_byte_done                  ; bit clear: no single byte
	move.b	-(a0),-(a1)                     ; one byte
.bwd_byte_done:
	lsr.l	#1,d0                           ; bit 1: one word
	bcc.s	.bwd_word_done                  ; bit clear: no word
	move.w	-(a0),-(a1)                     ; one word
.bwd_word_done:
	lsr.l	#1,d0                           ; bit 2: one long
	bcc.s	.bwd_long_done                  ; bit clear: no long
	move.l	-(a0),-(a1)                     ; one long
.bwd_long_done:
	lsr.l	#1,d0                           ; bit 3: two longs
	bcc.s	.bwd_eight_done                 ; bit clear: skip
	move.l	-(a0),-(a1)                     ; two longs
	move.l	-(a0),-(a1)
.bwd_eight_done:
	lsr.l	#1,d0                           ; bit 4: four longs
	bcc.s	.bwd_sixteen_done               ; bit clear: skip
	move.l	-(a0),-(a1)                     ; four longs
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
.bwd_sixteen_done:
	lsr.l	#1,d0                           ; bit 5: eight longs
	bcc.s	.bwd_thirtytwo_done             ; bit clear: skip
	move.l	-(a0),-(a1)                     ; eight longs
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
.bwd_thirtytwo_done:
	lsr.l	#1,d0                           ; bit 6: half a 128-byte block, d0 = number of whole blocks
	bcc.s	.bwd_block_next                 ; bit 6 clear: whole blocks only
	bra.s	.bwd_half_block                 ; enter the block loop half way
.bwd_block_loop:
	move.l	-(a0),-(a1)                     ; 128 bytes per pass
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
.bwd_half_block:
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
.bwd_block_next:
	dbra	d0,.bwd_block_loop              ; only the low word of the block count is used
	rts

;------------------------------------------------------------------------------
; Runtime routine $ec: copy d0.l bytes upwards from a0 to a1 (move (a0)+,(a1)+),
; same bit-by-bit scheme as routine $eb. Exit: a0/a1 raised by d0.
;------------------------------------------------------------------------------
rt_copy_bytes_forward:
	lsr.l	#1,d0                           ; bit 0 of the count: one byte
	bcc.s	.fwd_byte_done                  ; bit clear: no single byte
	move.b	(a0)+,(a1)+                     ; one byte
.fwd_byte_done:
	lsr.l	#1,d0                           ; bit 1: one word
	bcc.s	.fwd_word_done                  ; bit clear: no word
	move.w	(a0)+,(a1)+                     ; one word
.fwd_word_done:
	lsr.l	#1,d0                           ; bit 2: one long
	bcc.s	.fwd_long_done                  ; bit clear: no long
	move.l	(a0)+,(a1)+                     ; one long
.fwd_long_done:
	lsr.l	#1,d0                           ; bit 3: two longs
	bcc.s	.fwd_eight_done                 ; bit clear: skip
	move.l	(a0)+,(a1)+                     ; two longs
	move.l	(a0)+,(a1)+
.fwd_eight_done:
	lsr.l	#1,d0                           ; bit 4: four longs
	bcc.s	.fwd_sixteen_done               ; bit clear: skip
	move.l	(a0)+,(a1)+                     ; four longs
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
.fwd_sixteen_done:
	lsr.l	#1,d0                           ; bit 5: eight longs
	bcc.s	.fwd_thirtytwo_done             ; bit clear: skip
	move.l	(a0)+,(a1)+                     ; eight longs
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
.fwd_thirtytwo_done:
	lsr.l	#1,d0                           ; bit 6: half a block, d0 = number of 128-byte blocks
	bcc.s	.fwd_block_next                 ; bit 6 clear: whole blocks only
	bra.s	.fwd_half_block                 ; bit 6 set: enter the block loop half way
.fwd_block_loop:
	move.l	(a0)+,(a1)+                     ; 128 bytes per pass
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
.fwd_half_block:
	move.l	(a0)+,(a1)+                     ; the second 64 bytes of a block
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
.fwd_block_next:
	dbra	d0,.fwd_block_loop              ; next block; only the low word of the block count is used
	rts

;------------------------------------------------------------------------------
; Runtime routine $b1: Bconstat(d0) - input status of BIOS device d0 (INP?).
;------------------------------------------------------------------------------
rt_bconstat:
	move.w	d0,-(sp)                        ; device number
	move.w	#$1,-(sp)                       ; Bconstat
	trap	#13                             ; Bconstat
	addq.l	#4,sp                           ; drop the two words
	rts                                     ; d0 = -1 ready, 0 not

;------------------------------------------------------------------------------
; Runtime routine $b2: Bcostat(d0) - output status of BIOS device d0 (OUT?).
;------------------------------------------------------------------------------
rt_bcostat:
	move.w	d0,-(sp)                        ; device number
	move.w	#$8,-(sp)                       ; Bcostat
	trap	#13                             ; Bcostat
	addq.l	#4,sp                           ; drop the two words
	rts                                     ; d0 = -1 ready, 0 not

;------------------------------------------------------------------------------
; Runtime routine $61: INP(d0) - Bconin from BIOS device d0.
; On the console a key with ASCII 0 returns its scan code with bit 7 set.
; A negative d0 only returns Bconstat of device -d0. Exit: d0.l = byte.
;------------------------------------------------------------------------------
rt_inp:
	move.w	d0,-(sp)                        ; device; a negative number only asks for the status
	bmi.s	.inp_status_only                ; negative: status only
	move.w	#$2,-(sp)                       ; Bconin
	trap	#13                             ; Bconin
	move.l	(sp)+,d1                        ; d1 = device number back from the stack
	subq.w	#2,d1                           ; console (device 2)?
	bne.s	.inp_mask_byte                  ; not the console
	tst.w	d0                              ; ASCII 0: special key
	bne.s	.inp_mask_byte                  ; a real ASCII code
	swap	d0                              ; take the scan code instead
	ori.b	#$80,d0                         ; and mark it with bit 7
.inp_mask_byte:
	andi.l	#$ff,d0                         ; result is one byte
	rts
.inp_status_only:
	neg.w	(sp)                            ; device = -d0
	move.w	#$1,-(sp)                       ; Bconstat
	trap	#13                             ; Bconstat
	addq.l	#4,sp                           ; drop the arguments
	rts                                     ; d0 = -1 ready, 0 not

;------------------------------------------------------------------------------
; Runtime routines $c6 (entry $9626, whole rest of line, sets $86a) and
; $c5 (entry $962a, next comma-separated item): take the next INPUT item from
; the line buffer $f8(a4), position $86c(a4). With no line buffered it prints
; '? ' on the console (channel $22a = -4) and calls $40 to read a line.
; A quoted item runs to the closing quote before CR or ','.
; Exit: string descriptor at $ae8(a4) (address) / $adc(a4) (length), a1 =
; address; an odd-address item is first moved down one byte to an even one.
;------------------------------------------------------------------------------
rt_input_rest_of_line:
	st	$86a(a4)                        ; $c6: take the rest of the line (LINE INPUT)

;------------------------------------------------------------------------------
; Runtime routine $c5: the next comma-separated INPUT item (see rt_input_rest_of_line).
;------------------------------------------------------------------------------
rt_input_next_item:
	move.w	$86c(a4),d0                     ; $c5: position in the line buffer, 0 = no line read
	bne.s	.item_parse                     ; a line is buffered: take the next item
	tst.b	$86e(a4)                        ; prompt already printed ($86e negative)?
	bmi.s	.item_read_line                 ; prompt printed: just read the line
	cmpi.w	#$fffc,$22a(a4)                 ; channel -4, the console?
	bne.s	.item_read_line                 ; not the console: no prompt
	moveq	#63,d0                          ; '?'
	jsr	rn_print_char(a6)               ; routine $123: print character d0
	moveq	#32,d0                          ; ' '
	jsr	rn_print_char(a6)               ; print it
	move.w	#$8000,$86e(a4)                 ; mark the prompt as printed
.item_read_line:
	jsr	rn_input_read_line(a6)          ; routine $40: read a line into $f8(a4)
.item_parse:
	lea	$f8(a4),a0                      ; a0 = line buffer
	move.w	$86c(a4),d0                     ; d0 = position of the item
	move.w	d0,d1                           ; d1 = start of the item
	tst.b	$86a(a4)                        ; whole rest of the line wanted?
	bmi.w	.item_rest_scan                 ; LINE INPUT: everything up to CR
	cmpi.b	#$22,0(a0,d0.w)                 ; item starts with a quote?
	bne.s	.item_plain                     ; no quote: plain item
	addq.w	#1,d1                           ; the text starts after the quote
.item_quoted_scan:
	addq.w	#1,d0                           ; next character
	cmpi.b	#$22,0(a0,d0.w)                 ; closing quote?
	beq.s	.item_quote_found               ; found
	cmpi.b	#$d,0(a0,d0.w)                  ; end of line before it
	bne.s	.item_quoted_scan               ; not yet
	bra.s	.item_line_used                 ; no closing quote: the rest of the line
.item_quote_found:
	cmpi.b	#$d,1(a0,d0.w)                  ; quote at the end of the line
	beq.s	.item_line_used                 ; quote ends the line
	cmpi.b	#$2c,1(a0,d0.w)                 ; quote followed by ','
	bne.s	.item_quoted_scan               ; a quote inside the item: go on
	move.w	d0,$86c(a4)                     ; next item starts after the quote and the comma
	addq.w	#2,$86c(a4)                     ; + 2: past the quote and the comma
	bra.s	.item_descriptor                ; make the descriptor
.item_line_used:
	clr.w	$86c(a4)                        ; line used up, read a new one next time
.item_descriptor:
	adda.w	d1,a0                           ; a0 = item start, d0 = its length
	sub.w	d1,d0                           ; d0 = length
	movea.l	a0,a1                           ; a1 = item text
	move.l	a0,d1                           ; item at an odd address?
	bclr	#$0,d1                          ; clear bit 0
	beq.s	.item_store                     ; even already
	movea.l	d1,a1                           ; move it one byte down to an even address
	move.w	d0,d2                           ; d2 = byte count
	bra.s	.item_align_next                ; dbra count
.item_align_loop:
	move.b	(a0)+,(a1)+                     ; one byte down
.item_align_next:
	dbra	d2,.item_align_loop             ; all bytes
	movea.l	d1,a1                           ; a1 = the even start
.item_store:
	lea	$adc(a4),a0                     ; temporary string descriptor $ad8/$adc(a4)
	move.w	d0,(a0)                         ; length
	move.l	a1,-(a0)                        ; address
	rts
.item_plain:
	subq.w	#1,d0                           ; unquoted item: up to ',' or CR
.item_plain_scan:
	addq.w	#1,d0                           ; next character
	cmpi.b	#$d,0(a0,d0.w)                  ; end of line
	beq.s	.item_line_used                 ; end of the line
	cmpi.b	#$2c,0(a0,d0.w)                 ; comma ends the item
	bne.s	.item_plain_scan                ; not yet
	move.w	d0,$86c(a4)                     ; next item starts after the comma
	addq.w	#1,$86c(a4)                     ; + 1: past the comma
	bra.s	.item_descriptor                ; make the descriptor
.item_rest_loop:
	addq.w	#1,d0                           ; next character
.item_rest_scan:
	cmpi.b	#$d,0(a0,d0.w)                  ; LINE INPUT: everything up to CR
	bne.s	.item_rest_loop                 ; not yet
	sf	$86a(a4)                        ; clear the LINE INPUT flag
	bra.s	.item_line_used                 ; line used up

;------------------------------------------------------------------------------
; Runtime routine $c8: INPUT into an integer variable: one numeric item read ($c7), then
; truncated to a long in d0 ($f1, error 2 when out of range).
;------------------------------------------------------------------------------
rt_input_int:
	jsr	rn_input_number(a6)             ; routine $c7: read a number
	jmp	rn_float_to_long(a6)            ; routine $f1

;------------------------------------------------------------------------------
; Runtime: wrong numeric INPUT on the screen: the line is dropped (item position 0) and the
; bell rung on the console, then the item is read again at rt_input_number.
;------------------------------------------------------------------------------
rt_input_number_retry:
	clr.w	$86c(a4)                        ; wrong input: read a new line
	move.w	#$7,-(sp)                       ; bell (7)
	move.w	#$2,-(sp)                       ; on the console (device 2)
	move.w	#$3,-(sp)                       ; Bconout
	trap	#13                             ; Bconout
	addq.l	#6,sp                           ; drop the three words

;------------------------------------------------------------------------------
; Runtime routine $c7 (also reached as $c9): read one INPUT item ($c5) and convert it with
; VAL ($35) to d0-d2; anything but spaces after the number is an error. On channels -4/-1
; (screen) it rings the bell and asks again (rt_input_number_retry), elsewhere error 25
; 'Input wrong|not numeric'.
;------------------------------------------------------------------------------
rt_input_number:
	jsr	rn_input_next_item(a6)          ; routine $c5: next INPUT item
	pea	(a1)                            ; keep the item's start
	jsr	rn_val(a6)                      ; routine $35: convert the text to a number
	move.l	a0,d3                           ; d3 = characters converted (not used further)
	adda.l	(sp)+,a0                        ; a0 = end of the converted characters
	beq.s	.num_bad_input                  ; nothing converted: wrong
.num_skip_spaces:
	cmpi.b	#$20,-(a1)                      ; step back over trailing spaces
	beq.s	.num_skip_spaces                ; another space
	cmpa.l	a0,a1                           ; something else left after the number?
	bcs.s	.num_ok                         ; end of the number reached: all right
.num_bad_input:
	cmpi.w	#$fffc,$22a(a4)                 ; console channel -4: ask again
	beq.s	rt_input_number_retry           ; ask again
	cmpi.w	#$ffff,$22a(a4)                 ; screen channel -1: ask again
	beq.s	rt_input_number_retry           ; ask again
	moveq	#25,d0                          ; error 25 'Input wrong|not numeric'
	jmp	rn_error_entry(a6)              ; runtime error
.num_ok:
	rts                                     ; d0-d2 = the number

;------------------------------------------------------------------------------
; Runtime routine $40: read one line from channel $22a(a4) into $f8(a4).
; Channel -4 (CON) uses the line editor $4c, channel -1 the editor $4b;
; other channels read byte by byte (rt_read_channel_byte, d6 = handle or
; BIOS device - 6) until LF, the buffer end $1f7(a4), or a ',' outside
; quotes when not LINE INPUT ($86a clear). The last byte becomes CR.
; Exit: $86c(a4) = 0, $228(a4) = the channel.
;------------------------------------------------------------------------------
rt_input_read_line:
	move.w	$22a(a4),d6                     ; d6 = channel
	move.w	d6,-(sp)                        ; kept for $228(a4)
	ext.l	d6                              ; as a long: negative for BIOS devices
	bpl.s	.line_from_file                 ; file handle: read bytes
	addq.w	#6,d6                           ; -6..-1 becomes BIOS device 0..5
	cmpi.w	#$2,d6                          ; channel -4 (CON:)?
	bne.s	.line_check_screen              ; not the console
	jsr	rn_line_edit(a6)                ; routine $4c: line editor, codes from $20
	bra.s	.line_done                      ; done
.line_check_screen:
	cmpi.w	#$5,d6                          ; channel -1?
	bne.s	.line_from_file                 ; any other device: byte by byte
	jsr	rn_line_edit_all(a6)            ; routine $4b: line editor, all codes
	bra.s	.line_done                      ; done
.line_from_file:
	lea	$f8(a4),a0                      ; line buffer
.line_byte_loop:
	bsr.s	rt_read_channel_byte            ; read one byte to (a0)+
	lea	$1f7(a4),a1                     ; buffer end
	cmpa.l	a1,a0                           ; buffer full?
	beq.s	.line_terminate                 ; full: end the line
	cmpi.b	#$a,d0                          ; LF ends the line
	beq.s	.line_terminate                 ; LF: end of line
	tst.b	$86a(a4)                        ; LINE INPUT keeps commas
	bne.s	.line_byte_loop                 ; LINE INPUT: go on
	cmpi.b	#$2c,d0                         ; a comma ends the item ...
	bne.s	.line_byte_loop                 ; not a comma: go on
	cmpi.b	#$22,$f8(a4)                    ; ... unless the item is in quotes
	bne.s	.line_terminate                 ; item not quoted: the comma ends it
	cmpi.b	#$22,-$1(a0)                    ; a quote before the comma?
	bne.s	.line_terminate                 ; no: the comma ends it
	lea	$f9(a4),a1                      ; only the opening quote so far: go on
	cmpa.l	a0,a1                           ; the comma right after the opening quote?
	beq.s	.line_byte_loop                 ; the opening quote right before: go on
.line_terminate:
	move.b	#$d,-(a0)                       ; CR in place of the last byte
.line_done:
	clr.w	$86c(a4)                        ; item position 0
	move.w	(sp)+,$228(a4)                  ; remember the channel
	rts

;------------------------------------------------------------------------------
; Runtime: read one byte from channel d6 to (a0)+. d6 < 0 is a BIOS
; device (routine $49 enters at $97be, Bconin), d6 >= 0 a GEMDOS handle
; (routine $4a enters at $97d4, Fread 1 byte). Exit: d0 = byte; end of file
; gives error 26, a GEMDOS error goes to the error routine.
;------------------------------------------------------------------------------
rt_read_channel_byte:
	tst.l	d6                              ; BIOS device or GEMDOS handle?
	bpl.s	rt_read_file_byte               ; GEMDOS handle

;------------------------------------------------------------------------------
; Runtime routine $49: Bconin from BIOS device d6 into (a0)+; error on a negative result.
;------------------------------------------------------------------------------
rt_read_bios_byte:
	pea	(a0)                            ; routine $49: BIOS device in d6
	move.w	d6,-(sp)                        ; device number
	move.w	#$2,-(sp)                       ; Bconin
	trap	#13                             ; Bconin
	addq.l	#4,sp                           ; drop device and function
	movea.l	(sp)+,a0                        ; a0 = buffer pointer back
	move.b	d0,(a0)+                        ; store the byte
	tst.l	d0                              ; Bconin returned an error?
	bmi.s	rt_read_byte_error              ; negative = error
	rts                                     ; d0 = the byte

;------------------------------------------------------------------------------
; Runtime routine $4a: Fread of one byte from GEMDOS handle d6 into (a0)+; d0 = the byte,
; error 26 at the end of the file.
;------------------------------------------------------------------------------
rt_read_file_byte:
	pea	(a0)                            ; routine $4a: buffer address
	pea	$1.w                            ; one byte
	move.w	d6,-(sp)                        ; GEMDOS handle
	move.w	#$3f,-(sp)                      ; Fread
	trap	#1                              ; Fread
	addq.l	#8,sp                           ; drop handle and function
	movea.l	(sp)+,a0                        ; a0 = the buffer address back
	tst.l	d0                              ; GEMDOS error?
	bmi.s	rt_read_byte_error              ; GEMDOS error
	subq.l	#1,d0                           ; one byte read?
	bne.s	.end_of_file                    ; nothing read: end of file
	move.b	(a0)+,d0                        ; d0 = the byte
	rts
.end_of_file:
	moveq	#26,d0                          ; error 26 'End of file reached'

;------------------------------------------------------------------------------
; Runtime: error exit of the channel byte read: runtime error d0.
;------------------------------------------------------------------------------
rt_read_byte_error:
	jmp	rn_error_entry(a6)              ; error routine

;------------------------------------------------------------------------------
; Runtime routine $be: CRSLIN - cursor row from $5a, as a long in d0.
;------------------------------------------------------------------------------
rt_crslin:
	jsr	rn_cursor_get(a6)               ; routine $5a: d0 = column, d1 = row
	ext.l	d1                              ; row as a long
	move.l	d1,d0                           ; d0 = CRSLIN
	rts

;------------------------------------------------------------------------------
; Runtime routine $bf: CRSCOL - cursor column from $5a, as a long in d0.
;------------------------------------------------------------------------------
rt_crscol:
	jsr	rn_cursor_get(a6)               ; routine $5a
	ext.l	d0                              ; d0 = CRSCOL
	rts

;------------------------------------------------------------------------------
; Runtime: cursor position inside a GEM output window: d0 = column
; $870(a4)+1, d1 = row $872(a4)+1. Used by routine $5a.
;------------------------------------------------------------------------------
rt_window_cursor_get:
	move.w	$870(a4),d0                     ; window cursor column (0-based)
	move.w	$872(a4),d1                     ; and row
	addq.w	#1,d0                           ; 1-based
	addq.w	#1,d1                           ; 1-based
	rts                                     ; d0 = column, d1 = row

;------------------------------------------------------------------------------
; Runtime: set the window text cursor: $870/$872(a4) = d0-1/d1-1.
;------------------------------------------------------------------------------
rt_window_cursor_set:
	subq.w	#1,d0                           ; 0-based
	subq.w	#1,d1                           ; 0-based
	move.w	d0,$870(a4)                     ; store the 0-based window cursor
	move.w	d1,$872(a4)                     ; 0-based row
	rts                                     ; d0/d1 = column/row

;------------------------------------------------------------------------------
; Runtime: VDI escape (opcode 5) with sub-function d0 in contrl[5]
; ($2d6(a4)); d1 = intin count, d2 = ptsin count, via VDI routine $21a.
;------------------------------------------------------------------------------
rt_vdi_escape:
	move.w	d0,$2d6(a4)                     ; contrl[5] = escape sub-function
	moveq	#5,d0                           ; VDI opcode 5, escape
	jmp	rn_vdi_call_intin_ptsin(a6)     ; routine $21a: VDI call d0, d1 intin, d2 ptsin

;------------------------------------------------------------------------------
; Runtime routine $5a: get cursor position, d0 = column, d1 = row (1-based).
; In a GEM window ($b36(a4) set) from rt_window_cursor_get, else
; vq_curaddress (escape 15), intout at $61e(a4).
;------------------------------------------------------------------------------
rt_cursor_get:
	move.w	$b36(a4),d2                     ; printing into a GEM window?
	bne.s	rt_window_cursor_get            ; in a window: its cursor
	moveq	#15,d0                          ; vq_curaddress
	moveq	#0,d1                           ; no intin
	moveq	#0,d2                           ; no ptsin
	bsr.s	rt_vdi_escape                   ; VDI escape 15
	move.w	$610(a4),d0                     ; intout[1] = column
	move.w	$60e(a4),d1                     ; intout[0] = row
	rts                                     ; d0 = column, d1 = row

;------------------------------------------------------------------------------
; Runtime routine $db: as $59 with d0/d1 swapped (row first).
;------------------------------------------------------------------------------
rt_cursor_set_row_first:
	exg	d0,d1                           ; row first

;------------------------------------------------------------------------------
; Runtime routine $59: set cursor, d0 = column, d1 = row: window cursor
; when in a window, else vs_curaddress (escape 11, intin row/column).
;------------------------------------------------------------------------------
rt_cursor_set:
	move.w	$b36(a4),d2                     ; in a window?
	bne.s	rt_window_cursor_set            ; in a window: its cursor
	move.w	d0,$310(a4)                     ; intin[1] = column
	move.w	d1,$30e(a4)                     ; intin[0] = row
	moveq	#11,d0                          ; vs_curaddress
	moveq	#2,d1                           ; 2 intin
	moveq	#0,d2                           ; no ptsin
	bra.s	rt_vdi_escape                   ; VDI escape 11

;------------------------------------------------------------------------------
; Runtime routines $4d/$4b/$4c: line editor on the console, used by INPUT,
; LINE INPUT and FORM INPUT. Entries: $4d ($9854, d6 = length of the text
; already in $f8(a4), d0 = max length), $4b ($985a, max 255, all characters),
; $4c ($9862, max 255, characters from $20). $864 = length shown, $866 =
; lowest accepted code, $868 = max length, $85e/$860 = start column/row.
; d6 = length, d7 = cursor. Keys: cursor left/right, up = start, down = end,
; Backspace, Delete, Return/Enter end the line (CR stored after the text).
; Exit: d0 = key that ended the input; CR LF is printed.
;------------------------------------------------------------------------------
rt_line_edit_text:
	clr.w	$866(a4)                        ; $4d: lowest accepted code 0, d0 = max, d6 = text length
	bra.s	rt_line_edit_start              ; d6 and d0 as given

;------------------------------------------------------------------------------
; Runtime routine $4b: line editor with max 255 characters, all codes accepted.
;------------------------------------------------------------------------------
rt_line_edit_all:
	moveq	#-1,d0                          ; $4b: max 255
	clr.w	$866(a4)                        ; lowest accepted code 0
	bra.s	rt_line_edit_empty              ; empty line

;------------------------------------------------------------------------------
; Runtime routine $4c: line editor with max 255 characters, codes from $20.
;------------------------------------------------------------------------------
rt_line_edit:
	moveq	#-1,d0                          ; $4c: max 255
	move.w	#$20,$866(a4)                   ; lowest accepted code $20

rt_line_edit_empty:
	moveq	#0,d6                           ; nothing typed yet

rt_line_edit_start:
	move.w	d6,$864(a4)                     ; length last shown
	andi.w	#$ff,d0                         ; max length at most 255
	move.w	d0,$868(a4)                     ; max length
	jsr	rn_cursor_get(a6)               ; routine $5a: cursor position
	move.w	d0,$85e(a4)                     ; start column
	move.w	d1,$860(a4)                     ; start row
	move.w	d1,$862(a4)                     ; row last drawn on
	moveq	#0,d7                           ; cursor at the start
	bra.s	.edit_show                      ; draw the line once before the first key
.edit_key_loop:
	bsr.w	rt_editor_get_key               ; wait for a key
	tst.b	d0                              ; ASCII code 0: special key
	bne.s	.edit_ascii                     ; a real ASCII code
	swap	d0                              ; scan code
	cmpi.b	#$4b,d0                         ; cursor left
	beq.s	.edit_left
	cmpi.b	#$4d,d0                         ; cursor right
	beq.s	.edit_right
	cmpi.b	#$50,d0                         ; cursor down: to the end
	beq.s	.edit_end
	cmpi.b	#$48,d0                         ; cursor up: to the start
	bne.s	.edit_key_loop                  ; no other special key: next key
	moveq	#0,d7                           ; up: cursor to the start
.edit_show:
	bra.s	.edit_redraw                    ; show the line
.edit_left:
	subq.w	#1,d7                           ; one to the left; at the start ...
	bpl.s	.edit_redraw                    ; not at the start: show
.edit_right:
	addq.w	#1,d7                           ; ... back again; one to the right
	cmp.w	d6,d7                           ; not past the end
	bls.s	.edit_redraw                    ; not past the end: show
.edit_end:
	move.w	d6,d7                           ; cursor to the end
	bra.s	.edit_redraw                    ; show
.edit_ascii:
	lea	$f8(a4),a0                      ; a0 = the line buffer
	cmpi.b	#$d,d0                          ; Return ends
	beq.s	.edit_finish                    ; Return
	cmpi.b	#$a,d0                          ; Enter ends
	beq.s	.edit_finish                    ; Enter
	cmpi.b	#$8,d0                          ; Backspace
	beq.s	.edit_backspace                 ; Backspace
	cmpi.b	#$7f,d0                         ; Delete
	beq.s	.edit_delete                    ; Delete
	cmp.w	$866(a4),d0                     ; below the lowest accepted code: ignore
	bcs.s	.edit_key_loop                  ; control code not accepted
	cmp.w	$868(a4),d6                     ; line full?
	beq.s	.edit_full                      ; full
	cmp.w	d6,d7                           ; cursor not at the end: insert
	bne.s	.edit_insert                    ; in the middle: insert
.edit_store_char:
	move.b	d0,0(a0,d7.w)                   ; store the character at the cursor
	addq.w	#1,d7                           ; cursor one on
	addq.w	#1,d6                           ; one character more
.edit_redraw:
	bsr.w	rt_editor_redraw                ; show the line
	bra.s	.edit_key_loop                  ; next key
.edit_full:
	bsr.w	rt_editor_bell                  ; line full: bell
	bra.s	.edit_key_loop                  ; wait for the next key
.edit_finish:
	move.b	#$d,0(a0,d6.w)                  ; CR after the text
	move.w	d0,-(sp)                        ; keep the end key
	moveq	#-1,d7                          ; no cursor
	bsr.w	rt_editor_redraw                ; draw the line without the cursor
	moveq	#13,d0                          ; CR
	bsr.w	rt_editor_put_console           ; print CR on the console
	moveq	#10,d0                          ; LF
	bsr.w	rt_editor_put_console           ; print LF on the console
	move.w	(sp)+,d0                        ; d0 = key that ended the input
	rts
.edit_insert:
	lea	0(a0,d7.w),a1                   ; make room at the cursor
	lea	1(a0,d6.w),a2                   ; a2 = one past the end of the text
.edit_shift_up:
	move.b	-(a2),1(a2)                     ; move the text up one byte
	cmpa.l	a1,a2                           ; down to the cursor
	bne.s	.edit_shift_up                  ; until the cursor
	bra.s	.edit_store_char                ; then store the character
.edit_delete:
	cmp.w	d6,d7                           ; Delete: at the end nothing to do
	beq.s	.edit_redraw                    ; at the end: nothing
	addq.w	#1,d7                           ; delete the character at the cursor
.edit_backspace:
	tst.w	d7                              ; Backspace at the start: nothing
	beq.w	.edit_key_loop                  ; at the start: nothing
	subq.w	#1,d7                           ; cursor back one
	subq.w	#1,d6                           ; one character less
	cmp.w	d6,d7                           ; was the last character
	beq.s	.edit_redraw                    ; last character: just redraw
	lea	1(a0,d7.w),a1                   ; a1 = after the deleted character
	lea	1(a0,d6.w),a2                   ; a2 = after the end of the text
.edit_shift_down:
	move.b	(a1)+,-$2(a1)                   ; move the text down one byte
	cmpa.l	a1,a2                           ; up to the end
	bne.s	.edit_shift_down                ; to the end of the text
	bra.s	.edit_redraw                    ; redraw the line

rt_editor_key_return:
	rts                                     ; shared return

;------------------------------------------------------------------------------
; Runtime: read a key for the line editor. Alternate+key gives the
; scan code with bit 7 set; Ctrl-S then a key toggles bit 7 of that key;
; Ctrl-A then decimal digits enters a character by its code.
; Exit: d0 = key (ASCII 0 = special key, scan code in the high word).
;------------------------------------------------------------------------------
rt_editor_get_key:
	bsr.s	rt_console_key_in               ; wait for a key
	tst.b	d0                              ; ASCII 0?
	bne.s	.key_check_ctrl_s               ; a real ASCII code
	btst	#$1b,d0                         ; Alternate held (kbshift bit 3 in bit 27)?
	beq.s	rt_editor_key_return            ; no Alternate: the special key as it is
	swap	d0                              ; scan code ...
	bset	#$7,d0                          ; ... with bit 7 set
.key_check_ctrl_s:
	cmpi.b	#$13,d0                         ; Ctrl-S: next key with bit 7 toggled
	bne.s	.key_check_ctrl_a               ; not Ctrl-S
	bsr.s	rt_console_key_in               ; the next key
	bchg	#$7,d0                          ; toggle bit 7 of the key
.key_check_ctrl_a:
	cmpi.b	#$1,d0                          ; Ctrl-A: code given in decimal
	bne.s	.key_return                     ; not Ctrl-A: return the key
	moveq	#0,d5                           ; d5 = code being built
.key_digit_loop:
	bsr.s	rt_console_key_in               ; next digit
	subi.b	#$30,d0                         ; digit value
	cmpi.b	#$9,d0                          ; not a digit: done
	bhi.s	.key_code_done                  ; not a digit: done
	mulu.w	#$a,d5                          ; value * 10 + digit
	add.w	d0,d5                           ; + the digit
	cmpi.w	#$1a,d5                         ; stop once the value is 26 or more
	bcs.s	.key_digit_loop                 ; below 26: next digit
.key_code_done:
	move.w	d5,d0                           ; d0 = the code
.key_return:
	rts

;------------------------------------------------------------------------------
; Runtime: Bconin(2), wait for a console key. Exit: d0 = scan/ASCII.
;------------------------------------------------------------------------------
rt_console_key_in:
	move.w	#$2,-(sp)                       ; Bconin(2)
	move.w	#$2,-(sp)                       ; console
	trap	#13                             ; Bconin
	addq.l	#4,sp                           ; drop device and function
	rts                                     ; d0 = scan code (high word) and ASCII

;------------------------------------------------------------------------------
; Runtime: print d0 through routine $123 on channel -1 (raw screen),
; keeping d3-d7. loc_099b6 does the same for channel d1.
;------------------------------------------------------------------------------
rt_editor_put_raw:
	moveq	#-1,d1                          ; channel -1: raw screen output

rt_editor_put_channel:
	move.w	d1,$228(a4)                     ; output channel for routine $123
	movem.w	d3-d7,-(sp)                     ; keep d3-d7
	jsr	rn_print_char(a6)               ; routine $123: print character d0
	movem.w	(sp)+,d3-d7                     ; restore d3-d7
	rts

;------------------------------------------------------------------------------
; Runtime: redraw the edited line: cursor to $86e/$860, print the
; text raw with the character at the cursor in reverse (ESC p / ESC q),
; then a reversed space if the cursor is at the end and a blank to
; erase a deleted character. If the line scrolled the screen, the start
; row $860(a4) moves up one.
;------------------------------------------------------------------------------
rt_editor_redraw:
	move.w	$85e(a4),d0                     ; start column/row of the line
	move.w	$860(a4),d1                     ; start row
	jsr	rn_cursor_set(a6)               ; routine $59: set the cursor
	moveq	#0,d5                           ; d5 = index of the character drawn
.redraw_loop:
	cmp.w	d5,d7                           ; at the cursor?
	bne.s	.redraw_char                    ; not the cursor position
	moveq	#27,d0                          ; ESC p: reverse on
	bsr.s	rt_editor_put_console           ; print it
	moveq	#112,d0                         ; 'p'
	bsr.s	rt_editor_put_console           ; ESC p printed
.redraw_char:
	lea	$f8(a4),a0                      ; a0 = the line buffer
	cmp.w	d5,d6                           ; end of the text?
	beq.s	.redraw_end                     ; end of the text
	move.b	0(a0,d5.w),d0                   ; the character
	bsr.s	rt_editor_put_raw               ; printed raw, control codes shown as glyphs
	cmp.w	d5,d7                           ; at the cursor?
	bne.s	.redraw_next                    ; not the cursor character
	bsr.s	rt_editor_reverse_off           ; reverse off after the cursor character
.redraw_next:
	addq.w	#1,d5                           ; next character
	bra.s	.redraw_loop                    ; draw it
.redraw_end:
	moveq	#32,d0                          ; a space, erasing a deleted character
	bsr.s	rt_editor_put_console           ; print it on the console
	bsr.s	rt_editor_reverse_off           ; reverse off
	cmp.w	d5,d7                           ; cursor at the end?
	bne.s	.redraw_check_scroll            ; not at the end
	moveq	#32,d0                          ; space after the reversed cursor
	bsr.s	rt_editor_put_console           ; print it
.redraw_check_scroll:
	jsr	rn_cursor_get(a6)               ; routine $5a: where did the output end?
	cmp.w	$864(a4),d6                     ; text not shorter than before ...
	bcs.s	.redraw_save                    ; shorter: no scroll check
	subq.w	#1,d0                           ; ... cursor in column 1 ...
	bne.s	.redraw_save                    ; not in column 1: no scroll
	cmp.w	$862(a4),d1                     ; ... and on the same row: the screen scrolled
	bne.s	.redraw_save                    ; other row: no scroll
	subq.w	#1,$860(a4)                     ; so the line now starts one row higher
.redraw_save:
	move.w	d1,$862(a4)                     ; remember the row and the length
	move.w	d6,$864(a4)                     ; length shown
	rts                                     ; d6 = text length, $862(a4) = row

;------------------------------------------------------------------------------
; Runtime: print ESC q (reverse off) on the console.
;------------------------------------------------------------------------------
rt_editor_reverse_off:
	moveq	#27,d0                          ; ESC
	bsr.s	rt_editor_put_console           ; print it
	moveq	#113,d0                         ; 'q': reverse off

;------------------------------------------------------------------------------
; Runtime: print d0 on channel -4 (console, VT52 codes acted on).
;------------------------------------------------------------------------------
rt_editor_put_console:
	moveq	#-4,d1                          ; channel -4: console
	bra.s	rt_editor_put_channel           ; print d0 on channel d1

;------------------------------------------------------------------------------
; Runtime: ring the bell (print 7 on the console).
;------------------------------------------------------------------------------
rt_editor_bell:
	moveq	#7,d0                           ; bell
	bra.s	rt_editor_put_console           ; print it

;------------------------------------------------------------------------------
; Runtime routine $6d: READ a string item: copy the next NUL-terminated
; DATA item from $aee(a4)+$ae2(a4) to $f8(a4), advance $ae2. Past the
; end ($ae6) error 34 'Out of data'. Exit: descriptor $ad8/$adc(a4).
;------------------------------------------------------------------------------
rt_read_data_string:
	lea	$f8(a4),a1                      ; copy target: line buffer
	move.l	a1,d0                           ; d0 = target start
	movea.l	$ade(a4),a0                     ; DATA area
	move.l	$ae2(a4),d1                     ; offset of the next item
	cmp.l	$ae6(a4),d1                     ; past the end of the DATA?
	bcc.s	.data_out                       ; past the end: error 34
	adda.l	d1,a0                           ; a0 = the item
.data_copy:
	move.b	(a0)+,(a1)+                     ; copy the NUL-terminated item
	bne.s	.data_copy                      ; up to the NUL
	suba.l	d0,a1                           ; bytes copied including the NUL
	exg	d0,a1                           ; d0 = bytes copied, a1 = target start
	add.l	d0,$ae2(a4)                     ; DATA pointer to the next item
	subq.l	#1,d0                           ; length without the NUL
	lea	$adc(a4),a0                     ; temporary string descriptor
	move.w	d0,(a0)                         ; length
	move.l	a1,-(a0)                        ; address: descriptor $ad8/$adc(a4) = the item
	rts                                     ; a0 = the descriptor
.data_out:
	moveq	#34,d0                          ; error 34 'Out of data'

rt_read_data_error:
	jmp	rn_error_entry(a6)              ; runtime error d0

;------------------------------------------------------------------------------
; Runtime routines $7b/$7a: READ a numeric item: $6d then VAL ($35);
; text left after the number is error 35 'Data not numeric'.
;------------------------------------------------------------------------------
rt_read_data_number:
	jsr	rn_read_data_string(a6)         ; routine $6d: read the item text
	jsr	rn_val(a6)                      ; routine $35: VAL
	tst.b	(a1)                            ; conversion stopped at the end?
	bne.s	.data_not_numeric               ; text left: not numeric
	rts                                     ; d0-d2 = the number
.data_not_numeric:
	moveq	#35,d0                          ; error 35 'Data not numeric'
	bra.s	rt_read_data_error              ; runtime error

;------------------------------------------------------------------------------
; Runtime routine $7c: READ into an integer variable: a numeric item ($7a), then truncated
; to a long in d0 ($f1, error 2 when out of range).
;------------------------------------------------------------------------------
rt_read_data_int:
	jsr	rn_read_data_number(a6)         ; routine $7a: READ numeric
	jmp	rn_float_to_long(a6)            ; routine $f1

;------------------------------------------------------------------------------
; Runtime routine $71: INP(#n): one byte from channel d0 read as a one-byte string
; (INPUT$ through $5f), then its code as the result ($37).
;------------------------------------------------------------------------------
rt_inp_channel:
	move.l	d0,d1                           ; has no effect, d1 is set next
	moveq	#1,d1                           ; one byte
	jsr	rn_input_string_channel(a6)     ; routine $5f: INPUT$ from channel d0
	jmp	rn_asc(a6)                      ; routine $37: code of the first character

;------------------------------------------------------------------------------
; Runtime routines $5e ($9a86, keyboard, channel -4) and $5f ($9a8c,
; channel d0 0..100): INPUT$(d1 bytes). The handle comes from the channel
; table $7ec(a4); 0 = error 24 'File not open', above 100 error 23.
; A string of d1 bytes is made with $47 (a0 = descriptor, a1 = text);
; routine $18c enters at $9aba after that. Handles >= 0 use Fread
; (short read = error 26), devices read byte by byte with Bconin.
; Exit: a0 = string descriptor.
;------------------------------------------------------------------------------
rt_input_string_keyboard:
	move.l	d0,d1                           ; byte count
	moveq	#-4,d0                          ; channel -4: the keyboard
	bra.s	rt_input_string_handle          ; read like INPUT$ from a channel

;------------------------------------------------------------------------------
; Runtime routine $5f: INPUT$(d1,#d0): d1 bytes from channel d0 (0-100) as a new string.
;------------------------------------------------------------------------------
rt_input_string_channel:
	moveq	#100,d2                         ; channel number above 100?
	cmp.l	d2,d0                           ; above 100?
	bhi.s	rt_input_string_bad_channel     ; above 100: error 23
	lea	$7ec(a4),a0                     ; channel table: handle per channel
	move.b	0(a0,d0.w),d0                   ; d0 = the channel's handle byte
	ext.w	d0                              ; negative bytes are devices
	beq.s	rt_input_string_not_open        ; 0 = not open

rt_input_string_handle:
	move.w	d0,d6                           ; d6 = handle
	addq.w	#1,d0                           ; handle -1 ...
	bne.s	.inputs_allocate                ; not -1: as it is
	moveq	#-4,d6                          ; ... means the console
.inputs_allocate:
	move.w	d1,d0                           ; length
	ext.l	d0                              ; as a long
	jsr	rn_temp_string_alloc(a6)        ; routine $47: new string of d0 bytes, a1 = text

;------------------------------------------------------------------------------
; Runtime routine $18c: reads d0 bytes from handle/device d6 into the string text a1 (a0 =
; its descriptor), as INPUT$ after the string is made.
;------------------------------------------------------------------------------
rt_input_string_read:
	move.l	a0,d5                           ; routine $18c enters here; keep the descriptor
	tst.w	d6                              ; handle or device?
	bmi.s	rt_input_string_device          ; BIOS device
	pea	(a1)                            ; buffer = the new string's text
	move.l	d0,-(sp)                        ; count
	move.w	d6,-(sp)                        ; handle
	move.w	#$3f,-(sp)                      ; Fread
	trap	#1                              ; Fread, Fread(handle, count, text)
	addq.l	#4,sp                           ; drop handle and function
	cmp.l	(sp)+,d0                        ; all bytes read?
	bne.s	.inputs_short                   ; short read
	addq.l	#4,sp                           ; drop the buffer address
	movea.l	d5,a0                           ; a0 = descriptor
	rts
.inputs_short:
	tst.l	d0                              ; GEMDOS error number as it is
	bmi.s	rt_input_string_error           ; GEMDOS error
	moveq	#26,d0                          ; error 26 'End of file reached'

rt_input_string_error:
	jmp	rn_error_entry(a6)              ; runtime error d0

rt_input_string_bad_channel:
	moveq	#23,d0                          ; error 23 'File # wrong'
	bra.s	rt_input_string_error           ; runtime error

rt_input_string_not_open:
	moveq	#24,d0                          ; error 24 'File not open'
	bra.s	rt_input_string_error           ; runtime error

rt_input_string_device:
	addq.w	#6,d6                           ; -6..-1 becomes BIOS device 0..5
	move.l	a3,d4                           ; keep a3 (the control stack)
	movea.l	a1,a3                           ; a3 = write pointer into the text
	move.l	d0,d7                           ; d7 = bytes to read
	bra.s	.inputs_device_next             ; count down from d7
.inputs_device_loop:
	move.w	d6,-(sp)                        ; BIOS device
	move.w	#$2,-(sp)                       ; Bconin
	trap	#13                             ; Bconin, Bconin
	addq.l	#4,sp                           ; drop device and function
	move.b	d0,(a3)+                        ; store the byte
.inputs_device_next:
	tst.l	d0                              ; loop, stopping on a BIOS error
	dbmi	d7,.inputs_device_loop          ; next byte while no error
	subi.l	#$10000,d7                      ; high word of the count
	bpl.s	.inputs_device_loop             ; more bytes
	movea.l	d5,a0                           ; a0 = the string's descriptor
	movea.l	d4,a3                           ; a3 back
	rts                                     ; a0 = the string's descriptor

;------------------------------------------------------------------------------
; Runtime routines $73 (LOF, $9b08) and $72 (EOF, $9b14) for channel d0.
; LOF returns the file length, EOF -1 when the position is at the end.
;------------------------------------------------------------------------------
rt_lof:
	bsr.s	rt_file_length_position         ; d5 = length, d6 = position
	bmi.s	rt_file_result_zero             ; closed or a device: 0
	move.l	d5,d0                           ; LOF
	rts                                     ; d0 = LOF

;------------------------------------------------------------------------------
; Runtime: d0 = 0 result of LOF/EOF for a closed or device channel.
;------------------------------------------------------------------------------
rt_file_result_zero:
	moveq	#0,d0                           ; result 0
	rts                                     ; d0 = result

;------------------------------------------------------------------------------
; Runtime routine $72: EOF(#d0): -1 when the file position is at its length, else 0.
;------------------------------------------------------------------------------
rt_eof:
	bsr.s	rt_file_length_position         ; d5 = length, d6 = position
	bmi.s	rt_file_result_zero             ; closed or a device: 0
	cmp.l	d5,d6                           ; position at the end?
	bne.s	rt_file_result_zero             ; not at the end: 0
	moveq	#-1,d0                          ; EOF true
	rts                                     ; d0 = -1

;------------------------------------------------------------------------------
; Runtime: error 23 (File # wrong).
;------------------------------------------------------------------------------
rt_file_number_error:
	moveq	#23,d0                          ; error 23 'File # wrong'
	jmp	rn_error_entry(a6)              ; runtime error

;------------------------------------------------------------------------------
; Runtime: d0 = channel (>= 100 is error 23). For an open file:
; d6 = current position, d5 = length (Fseek 1, Fseek 2, Fseek back).
; A closed or device channel returns from here through rt_file_result_zero
; with d0 = 0 (so the caller's bmi is not taken). d7 = handle.
;------------------------------------------------------------------------------
rt_file_length_position:
	moveq	#100,d2                         ; channel 100 or more
	cmp.l	d2,d0                           ; 100 or more?
	bcc.s	rt_file_number_error            ; 100 or more: error 23
	lea	$7ec(a4),a0                     ; channel table
	move.b	0(a0,d0.w),d7                   ; d7 = handle
	ble.s	rt_file_result_zero             ; not open or a device: result 0
	ext.w	d7                              ; handle as a word
	move.w	#$1,-(sp)                       ; from the current position
	move.w	d7,-(sp)                        ; handle
	clr.l	-(sp)                           ; offset 0
	move.w	#$42,-(sp)                      ; Fseek(0, handle, 1)
	trap	#1                              ; Fseek
	adda.w	#$a,sp                          ; drop the arguments
	tst.l	d0                              ; error?
	bmi.s	.seek_error                     ; GEMDOS error
	move.l	d0,d6                           ; d6 = current position
	move.w	#$2,-(sp)                       ; from the end
	move.w	d7,-(sp)                        ; handle
	clr.l	-(sp)                           ; offset 0
	move.w	#$42,-(sp)                      ; Fseek(0, handle, 2)
	trap	#1                              ; Fseek
	adda.w	#$a,sp                          ; drop the arguments
	move.l	d0,d5                           ; d5 = file length
	bmi.s	.seek_error                     ; GEMDOS error
	clr.w	-(sp)                           ; from the start
	move.w	d7,-(sp)                        ; handle
	move.l	d6,-(sp)                        ; the old position
	move.w	#$42,-(sp)                      ; Fseek(position, handle, 0): back again
	trap	#1                              ; Fseek
	adda.w	#$a,sp                          ; drop the arguments
	tst.l	d0                              ; error?
	bmi.s	.seek_error                     ; GEMDOS error
	rts                                     ; d5 = length, d6 = position (flags: not negative)
.seek_error:
	jmp	rn_error_entry(a6)              ; GEMDOS error

;------------------------------------------------------------------------------
; Runtime routines $19c (FORM INPUT n AS a$, $9b80, default text = the string a0) and $19b
; (FORM INPUT n,a$, $9b86, empty). a0 = string variable, d1 = max length. Selects the screen for
; input ($10b), copies up to the max length of the default into $f8(a4), runs the line editor
; $4d, then assigns the result to the variable with $e6.
;------------------------------------------------------------------------------
rt_form_input_as:
	move.w	4(a0),d6                        ; $19c: default text length
	bra.s	rt_form_input_body              ; common part

;------------------------------------------------------------------------------
; Runtime routine $19b: FORM INPUT d1,a$ without a default text.
;------------------------------------------------------------------------------
rt_form_input:
	moveq	#0,d6                           ; $19b: no default text

rt_form_input_body:
	pea	(a0)                            ; string variable
	move.b	d1,-(sp)                        ; max length
	move.w	d6,-(sp)                        ; default text length
	jsr	rn_select_screen(a6)            ; routine $10b: input and output on the screen (channel -4)
	move.w	(sp)+,d6                        ; d6 = default text length
	moveq	#0,d0                           ; d0 = max length
	move.b	(sp)+,d0                        ; d0 = max length
	beq.s	.form_assign                    ; max 0: empty result
	tst.w	d6                              ; default text?
	beq.s	.form_edit                      ; no default: edit an empty line
	movea.l	(sp),a0                         ; the variable's descriptor
	movea.l	(a0)+,a1                        ; a1 = its text
	move.w	d6,d1                           ; d1 = default length
	cmp.w	d0,d1                           ; default longer than the max?
	bcs.s	.form_copy_length               ; shorter: copy it all
	move.w	d0,d1                           ; then only the max
.form_copy_length:
	move.w	d1,d6                           ; d6 = length shown at the start
	lea	$f8(a4),a0                      ; into the line buffer
	bra.s	.form_copy_next                 ; dbra count
.form_copy_loop:
	move.b	(a1)+,(a0)+                     ; copy the default text
.form_copy_next:
	dbra	d1,.form_copy_loop              ; d1 bytes
.form_edit:
	jsr	rn_line_edit_text(a6)           ; routine $4d: line editor, d6 = length shown
	lea	$f8(a4),a1                      ; find the CR at the end
	moveq	#-1,d0                          ; d0 = length of the result
.form_find_cr:
	addq.w	#1,d0                           ; next character
	cmpi.b	#$d,0(a1,d0.w)                  ; CR ends the text
	bne.s	.form_find_cr                   ; not yet
.form_assign:
	lea	$adc(a4),a0                     ; temporary descriptor = result
	move.w	d0,(a0)                         ; length
	move.l	a1,-(a0)                        ; address: a1 = the line buffer
	movea.l	(sp)+,a1                        ; a1 = the variable
	jmp	rn_string_assign(a6)            ; routine $e6: assign the string

;------------------------------------------------------------------------------
; Runtime routine $98: ERR - byte $b48(a4) as a long in d0.
;------------------------------------------------------------------------------
rt_err:
	move.b	$b48(a4),d0                     ; ERR
	ext.w	d0                              ; as a word
	ext.l	d0                              ; as a long: d0 = ERR
	rts

;------------------------------------------------------------------------------
; Runtime routine $a0: return the byte of runtime routine $1ff
; (at $9ed8) as a long in d0; it looks like FATAL.
;------------------------------------------------------------------------------
rt_fatal:
	move.b	rn_fatal_byte(a6),d0            ; the byte of routine $1ff
	ext.w	d0                              ; as a word
	ext.l	d0                              ; as a long
	rts

;------------------------------------------------------------------------------
; Runtime routines $1bc (d0 = 0, install) and $1bd (d0 = -1, remove):
; enter routine $1bb.
;------------------------------------------------------------------------------
rt_bombs_install:
	moveq	#0,d0                           ; $1bc: install
	bra.s	rt_bombs_vectors                ; remove (d0 = -1)

;------------------------------------------------------------------------------
; Runtime routine $1bd: put the exception vectors and etv_critic back (d0 = -1 into $1bb).
;------------------------------------------------------------------------------
rt_bombs_remove:
	moveq	#-1,d0                          ; $1bd: remove

;------------------------------------------------------------------------------
; Runtime routine $1bb (the Bombs option): d0 = 0 installs handlers
; for exception vectors 2-9 (only where the old vector's top byte is 0)
; and a new etv_critic, saving the old ones; d0 <> 0 puts them back
; through Supexec(rt_restore_exception_vectors).
;------------------------------------------------------------------------------
rt_bombs_vectors:
	tst.w	d0                              ; remove?
	beq.s	.bombs_install                  ; 0: install
	pea	rt_restore_exception_vectors(pc) ; restore the vectors in supervisor mode
	move.w	#$26,-(sp)                      ; Supexec
	trap	#14                             ; Supexec
	addq.l	#6,sp                           ; drop the arguments
	rts
.bombs_install:
	clr.l	-(sp)                           ; Super(0)
	move.w	#$20,-(sp)                      ; Super(0): supervisor mode
	trap	#1                              ; Super
	addq.l	#6,sp                           ; drop the arguments; d0 = the old supervisor stack
	lea	rt_saved_ssp(pc),a0             ; keep the old supervisor stack
	move.l	d0,(a0)                         ; kept in rt_saved_ssp
	lea	$8.w,a0                         ; bus error vector
	lea	rt_saved_exception_vectors(pc),a1 ; save area
	lea	rt_exception_entries(pc),a2     ; entry for vector 2
	moveq	#7,d0                           ; vectors 2 to 9
.bombs_vector_loop:
	move.b	(a0),d1                         ; top byte of the vector
	move.l	(a0),(a1)+                      ; save the old vector
	tst.b	d1                              ; top byte not 0: leave this vector alone
	beq.s	.bombs_vector_next              ; top byte not 0: keep the old one
	move.l	a2,(a0)                         ; install our entry
.bombs_vector_next:
	addq.l	#4,a0                           ; next vector
	addq.l	#6,a2                           ; next entry, 6 bytes on
	dbra	d0,.bombs_vector_loop           ; all 8 vectors
	lea	rt_critic_old_jump+2(pc),a1     ; save the old etv_critic in the jmp operand
	move.l	$404.w,(a1)                     ; etv_critic
	lea	rt_critic_handler(pc),a1        ; install the critical error handler
	move.l	a1,$404.w                       ; etv_critic
	move.l	rt_saved_ssp(pc),-(sp)          ; old supervisor stack
	move.w	#$20,-(sp)                      ; Super: back to user mode
	trap	#1                              ; Super
	addq.l	#6,sp                           ; drop the arguments
	rts

;------------------------------------------------------------------------------
; Runtime: supervisor routine that restores vectors 2-9 and etv_critic.
;------------------------------------------------------------------------------
rt_restore_exception_vectors:
	movem.l	rt_saved_exception_vectors(pc),d0-d7 ; the 8 saved vectors
	movem.l	d0-d7,$8.w                      ; bus error vector, back into vectors 2-9
	move.l	rt_critic_old_jump+2(pc),$404.w ; etv_critic, and the old critical error handler
	rts

; Runtime data: the 8 saved exception vectors ($8-$24).
rt_saved_exception_vectors:
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000 ; 8 longs: saved vectors 2-9
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000

; Runtime data: saved supervisor stack from Super(0).
rt_saved_ssp:
	dc.w	$0000,$0000                     ; long: saved supervisor stack

;------------------------------------------------------------------------------
; Runtime: exception entries, 6 bytes each, for vectors 2 to 9.
; Each pushes its vector number. The common code writes a TOS-style
; dump ($380 = $12345678, registers at $384, vector number/usp/frame at
; $3c4), reloads the runtime registers a4-a7, lowers the interrupt mask,
; returns to user mode and reports error 100 + vector number (102-109).
;------------------------------------------------------------------------------
rt_exception_entries:
	pea	$2.w                            ; bus error
	bra.s	.exception_common               ; to the common code
	pea	$3.w                            ; address error
	bra.s	.exception_common               ; to the common code
	pea	$4.w                            ; illegal instruction
	bra.s	.exception_common               ; to the common code
	pea	$5.w                            ; division by zero
	bra.s	.exception_common               ; to the common code
	pea	$6.w                            ; CHK
	bra.s	.exception_common               ; to the common code
	pea	$7.w                            ; TRAPV
	bra.s	.exception_common               ; to the common code
	pea	$8.w                            ; bus error vector, privilege violation
	bra.s	.exception_common               ; to the common code
	pea	$9.w                            ; trace
.exception_common:
	move.l	#$12345678,$380.w               ; proc_lives, TOS post-mortem dump: magic in proc_lives
	movem.l	d0-d7/a0-a6,$384.w              ; proc_dregs, registers
	move.l	(sp)+,d0                        ; vector number
	lea	$3c4.w,a0                       ; proc_enum
	movea.w	d0,a3                           ; a3 = vector number
	ror.l	#8,d0                           ; vector number in the top byte
	move.l	d0,(a0)+                        ; proc_enum: vector number in the top byte
	move.l	usp,a1                          ; user stack pointer
	move.l	a1,(a0)+                        ; proc_usp
	movem.l	(sp),d0-d7                      ; first 8 longs of the exception frame
	movem.l	d0-d7,(a0)                      ; proc_stk: the first 16 words of the frame
	movem.l	rt_saved_registers_a4(pc),a4-sp ; runtime registers a4-a7 back
	andi.w	#$f3ff,sr                       ; lower the interrupt mask
	move.w	#$1,$452.w                      ; vblsem, VBL handling on again
	move.l	rt_saved_ssp(pc),-(sp)          ; old supervisor stack
	move.w	#$20,-(sp)                      ; Super: back to user mode
	trap	#1                              ; Super
	moveq	#100,d0                         ; error 100 + vector: 102-109 'n bombs'
	add.w	a3,d0                           ; + vector number
	bra.w	rt_error                        ; report error d0

;------------------------------------------------------------------------------
; Runtime: etv_critic handler: show the mouse again, then jump to the
; old handler (address patched into rt_critic_old_jump).
;------------------------------------------------------------------------------
rt_critic_handler:
	movem.l	d3-d7/a3-a6,-(sp)               ; show the mouse before TOS asks its question
	bsr.s	rt_mouse_show                   ; show the mouse
	movem.l	(sp)+,d3-d7/a3-a6               ; restore the registers

;------------------------------------------------------------------------------
; Runtime: jmp to the previous etv_critic handler; operand patched.
;------------------------------------------------------------------------------
rt_critic_old_jump:
	jmp	$0                              ; old etv_critic; operand written by $1bb
	rts

;------------------------------------------------------------------------------
; Runtime routines $16b/$1ba: ALERT - form_alert, d0 = default button
; (intin $74a(a4)), a0 = alert text (addrin $79a(a4)); AES 52.
;------------------------------------------------------------------------------
rt_form_alert:
	move.l	a0,$79a(a4)                     ; addrin[0] = alert text
	move.w	d0,$74a(a4)                     ; intin[0] = default button
	moveq	#52,d0                          ; form_alert
	jmp	rn_aes_call(a6)                 ; routine $21b: AES call d0

;------------------------------------------------------------------------------
; Runtime routines $208 ($9d22, also sets the lock $227(a4)) and $205
; ($9d26): hide the mouse with Line-A $a00a unless $226(a4) says it is
; hidden already.
;------------------------------------------------------------------------------
rt_mouse_hide_lock:
	st	$227(a4)                        ; $208: lock the mouse hidden

;------------------------------------------------------------------------------
; Runtime routine $205: hide the mouse (Line-A $a00a) unless $226(a4) says it is hidden.
;------------------------------------------------------------------------------
rt_mouse_hide:
	tas	$226(a4)                        ; $205: hidden already?
	bne.s	.hide_done                      ; hidden already
	movem.l	d0-d2/a0-a2,-(sp)               ; keep the registers Line-A changes
	dc.w	$a00a                           ; Line-A Hide mouse, Line-A hide mouse
	movem.l	(sp)+,d0-d2/a0-a2               ; restore them
.hide_done:
	rts                                     ; hidden now

;------------------------------------------------------------------------------
; Runtime routine $15f: Line-A hide mouse and set $226(a4).
;------------------------------------------------------------------------------
rt_hidem:
	dc.w	$a00a                           ; Line-A Hide mouse, Line-A hide mouse
	st	$226(a4)                        ; mark hidden
	rts

;------------------------------------------------------------------------------
; Runtime routine $209: clear the lock $227(a4) and show the mouse.
;------------------------------------------------------------------------------
rt_mouse_unlock_show:
	sf	$227(a4)                        ; $209: unlock
	bra.s	rt_mouse_show                   ; show it

;------------------------------------------------------------------------------
; Runtime routine $206: show the mouse when it was hidden ($226) and
; is not locked ($227).
;------------------------------------------------------------------------------
rt_mouse_show_if_hidden:
	tst.b	$227(a4)                        ; locked: leave it
	bne.s	rt_mouse_return                 ; locked: leave it
	tst.b	$226(a4)                        ; not hidden: nothing to do
	beq.s	rt_mouse_return                 ; not hidden: nothing to do

;------------------------------------------------------------------------------
; Runtime routine $11f: Line-A show mouse, with intin[0] = 0 from
; rt_mouse_show_intin; clears $226(a4). Routine $11e is the move.l at
; $9d5a: the start-up writes the Line-A intin pointer address into its
; operand ($87654321 is a placeholder).
;------------------------------------------------------------------------------
rt_mouse_show:
	movem.l	d0-d2/a0-a2,-(sp)               ; keep the registers Line-A changes
	lea	rt_mouse_show_intin(pc),a0      ; intin[0] = 0: show at once

;------------------------------------------------------------------------------
; Runtime routine $11e: the move.l whose operand the start-up sets to the Line-A intin
; pointer address; part of rt_mouse_show.
;------------------------------------------------------------------------------
rt_mouse_show_intin_patch:
	move.l	a0,$87654321                    ; routine $11e: operand = Line-A intin pointer
	dc.w	$a009                           ; Line-A Show mouse, Line-A show mouse
	clr.b	$226(a4)                        ; mark shown
	movem.l	(sp)+,d0-d2/a0-a2               ; restore them

rt_mouse_return:
	rts

; Runtime data: word 0, intin for Line-A show mouse (always show).
rt_mouse_show_intin:
	dc.w	$0000                           ; Line-A intin: word 0

; Runtime routine $213 (data): the program counter saved by the
; break test, reported as the error PC.
rt_error_pc:
	dc.w	$0000,$0000                     ; routine $213: long, error PC

;------------------------------------------------------------------------------
; Runtime: the break test proper (routine 2 branches here): saves the caller's PC and a3,
; checks BREAK off and Shift+Ctrl+Alternate, calls ON BREAK GOSUB or stops with error -128,
; and shows the mouse again when a routine left it hidden.
;------------------------------------------------------------------------------
rt_break_test:
	move.l	(sp),rn_error_pc(a6)            ; PC in the compiled program
	move.l	a3,$232(a4)                     ; a3 at the time
	move.w	$b38(a4),d0                     ; BREAK off ($b38.w negative)?
	bmi.s	rt_break_check_mouse            ; BREAK off: only the mouse check

;------------------------------------------------------------------------------
; Runtime routine $1c8: the kbshift read of the break test; the start-up patches the address
; of the kbshift byte into its operand.
;------------------------------------------------------------------------------
rt_break_kbshift:
	move.b	$e1b.w,d0                       ; routine $1c8: kbshift address patched by the start-up
	andi.w	#$e,d0                          ; Shift, Ctrl and Alternate ...
	cmpi.b	#$e,d0                          ; ... all held?
	beq.s	rt_break_handler                ; held: break

rt_break_check_mouse:
	tst.w	$226(a4)                        ; mouse hidden or locked?
	bne.s	rt_break_show_mouse             ; yes: show it again
	rts                                     ; nothing to show: back to the program

rt_break_handler:
	move.l	$b38(a4),d0                     ; ON BREAK GOSUB address
	beq.s	rt_break_stop                   ; none: stop the program
	st	$b38(a4)                        ; no new break while in the handler
	movea.l	d0,a0                           ; a0 = the handler
	move.l	$b38(a4),-(sp)                  ; keep the value
	jsr	rn_gosub(a6)                    ; routine $204: GOSUB a0
	move.l	(sp)+,d0                        ; d0 = the value before
	cmp.l	$b38(a4),d0                     ; handler did not change it?
	bne.s	rt_break_show_mouse             ; changed: leave it
	sf	$b38(a4)                        ; then break is allowed again

rt_break_show_mouse:
	tst.b	$227(a4)                        ; show the mouse unless it is locked
	beq.s	rt_mouse_show_if_hidden         ; not locked: show it if hidden
	rts                                     ; locked: back to the program

rt_break_stop:
	moveq	#-128,d0                        ; error -128: break
	clr.l	$b3c(a4)                        ; ON ERROR switched off
	bra.s	rt_error                        ; to the error routine

;------------------------------------------------------------------------------
; Runtime routine 2: the break test of Stop ever (jsr (a6) in compiled
; code; a6 most likely points here, with the error entry at 2(a6)).
; Saves the caller's PC in $213 and a3 in $232(a4); with BREAK not off
; ($b38(a4).w >= 0) and Shift+Ctrl+Alt held (kbshift address patched
; into routine $1c8 at $9d8c) it calls the ON BREAK GOSUB handler
; $b38(a4) through $204, or stops with error -128. Also shows the mouse
; again when a runtime routine hid it.
;------------------------------------------------------------------------------
rt_break_test_entry:
	bra.s	rt_break_test                   ; routine 2: the break test (jsr (a6))

;------------------------------------------------------------------------------
; Runtime routine $10f, the error routine (jmp 2(a6) with d0 = error
; number): reload a3-a7 from routine 4, ERR $b48(a4) = d0, error PC
; $b40(a4), call a pending ON ERROR GOSUB ($b3c) once through $204.
; Otherwise builds '[1][text| PC>$xxxxxx][Abort]' at $94(a4): the text
; from the error table after rt_error_text_link (number byte, text, NUL,
; ended by $7f) or 'Error # nnn', shows it with ALERT ($16b), then ends
; the program with routine $201.
;------------------------------------------------------------------------------
rt_error:
	movem.l	rt_saved_registers(pc),a3-sp    ; registers from routine 4
	move.b	d0,$b48(a4)                     ; ERR
	move.l	$232(a4),$236(a4)               ; a3 at the error
	move.l	rt_error_pc(pc),$b40(a4)        ; error PC
	seq	$1ff(a4)                        ; $1ff(a4) set when the PC is 0
	move.l	$b3c(a4),d0                     ; ON ERROR GOSUB?
	beq.s	.error_text                     ; no ON ERROR
	clr.l	$b3c(a4)                        ; only once
	movea.l	d0,a0                           ; a0 = the handler
	jsr	rn_gosub(a6)                    ; routine $204: GOSUB a0
.error_text:
	move.b	$b48(a4),d0                     ; error number
	lea	$94(a4),a0                      ; alert text buffer
	move.l	#$5b315d5b,(a0)+                ; '[1]['
	lea	rt_error_texts(pc),a1           ; error texts (routine $1b8, if copied)
	moveq	#127,d1                         ; $7f ends the table
.error_find:
	cmp.b	(a1),d1                         ; table end?
	beq.s	.error_number                   ; table end: no text, 'Error # nnn'
	cmp.b	(a1)+,d0                        ; the number byte matches?
	beq.s	.error_copy_text                ; found: copy the text
.error_skip_text:
	tst.b	(a1)+                           ; skip the text
	bne.s	.error_skip_text                ; to the NUL
	bra.s	.error_find                     ; next entry
.error_number:
	lea	rt_text_error_number(pc),a1     ; no text: 'Error # '
.error_copy_prefix:
	move.b	(a1)+,(a0)+                     ; copy 'Error # '
	bne.s	.error_copy_prefix              ; up to its NUL
	subq.l	#1,a0                           ; back over the NUL
	ext.w	d0                              ; negative error number?
	bpl.s	.error_digits                   ; positive
	move.b	#$2d,(a0)+                      ; '-'
	neg.w	d0                              ; its value
.error_digits:
	ext.l	d0                              ; as a long for divu
	divu.w	#$64,d0                         ; hundreds
	ori.b	#$30,d0                         ; digit
	move.b	d0,(a0)+                        ; store it
	swap	d0                              ; remainder
	ext.l	d0                              ; as a long
	divu.w	#$a,d0                          ; tens
	ori.b	#$30,d0                         ; digit
	move.b	d0,(a0)+                        ; store it
	swap	d0                              ; remainder
	ori.b	#$30,d0                         ; units
	move.b	d0,(a0)+                        ; store it
	bra.s	.error_add_pc                   ; then the PC
.error_copy_text:
	move.b	(a1)+,(a0)+                     ; copy the error text
	bne.s	.error_copy_text                ; up to the NUL
	subq.l	#1,a0                           ; back over the NUL
.error_add_pc:
	lea	rt_text_pc(pc),a1               ; '| PC>$'
.error_copy_pc:
	move.b	(a1)+,(a0)+                     ; copy '| PC>$'
	bne.s	.error_copy_pc                  ; up to the NUL
	subq.l	#1,a0                           ; back over the NUL
	move.l	$b40(a4),d0                     ; error PC
	bsr.s	rt_hex_six_digits               ; as 6 hex digits
	lea	rt_text_abort_button(pc),a1     ; '][Abort]'
.error_copy_abort:
	move.b	(a1)+,(a0)+                     ; copy '][Abort]' with its NUL
	bne.s	.error_copy_abort               ; up to the NUL
	lea	$94(a4),a0                      ; the alert text
	moveq	#1,d0                           ; default button 1
	jsr	rn_form_alert(a6)               ; routine $16b: ALERT
	jmp	rn_end_program(a6)              ; routine $201: end the program

;------------------------------------------------------------------------------
; Runtime: Cconws(a0). No routine-table entry points here and nothing branches to it; it
; looks unused.
;------------------------------------------------------------------------------
	pea	(a0)                            ; the text
	move.w	#$9,-(sp)                       ; Cconws
	trap	#1                              ; Cconws
	addq.l	#6,sp                           ; drop the arguments
	rts

;------------------------------------------------------------------------------
; Runtime: write the low 24 bits of d0 as 6 hex digits at (a0)+.
;------------------------------------------------------------------------------
rt_hex_six_digits:
	swap	d0                              ; bits 16-23 first
	bsr.s	rt_hex_byte                     ; two digits
	rol.l	#8,d0                           ; bits 8-15 into the low byte
	bsr.s	rt_hex_byte                     ; then 8-15
	rol.l	#8,d0                           ; then 0-7

;------------------------------------------------------------------------------
; Runtime: write the low byte of d0 as 2 hex digits at (a0)+.
;------------------------------------------------------------------------------
rt_hex_byte:
	move.l	d0,-(sp)                        ; keep d0
	lsr.b	#4,d0                           ; high nibble
	bsr.s	rt_hex_digit                    ; first digit
	move.l	(sp),d0                         ; d0 back
	bsr.s	rt_hex_digit                    ; low nibble
	move.l	(sp)+,d0                        ; d0 back, (a0) past the two digits
	rts

;------------------------------------------------------------------------------
; Runtime: write the low nibble of d0 as one hex digit at (a0)+.
;------------------------------------------------------------------------------
rt_hex_digit:
	andi.w	#$f,d0                          ; nibble to '0'..'9' ...
	ori.b	#$30,d0                         ; to an ASCII digit
	cmpi.b	#$39,d0                         ; above '9'?
	bls.s	.hex_store                      ; 0-9
	addq.b	#7,d0                           ; ... or 'A'..'F'
.hex_store:
	move.b	d0,(a0)+                        ; store the digit
	rts                                     ; a0 past the digit

; Runtime data: texts of the error alert.
rt_text_pc:
	dc.b	'| PC>$',0                      ; '| PC>$'
rt_text_error_number:
	dc.b	'Fehler # ',0                   ; 'Error # '
rt_text_abort_button:
	dc.b	'][Abbruch]',0                  ; '][Abort]'
rt_fatal_byte:
	dc.w	$0000

; Runtime routine 4 (data): the start-up saves a3-a7 here
; (movem.l a3-sp,4(a6)); 4(a6) is the saved procedure stack pointer a3.
; The error routine and the exception entries reload the registers here.
rt_saved_registers:
	dc.w	$0000,$0000                     ; saved a3: 4(a6)
rt_saved_registers_a4:
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000 ; saved a4, a5, a6, sp

;------------------------------------------------------------------------------
; Runtime routine $154: CLEAR. Only allowed with the procedure stack
; empty (a3 = $5c(a4)), else error 40 'Clear not allowed in For-Next-loops
; or Procedures'. Resets the DATA pointer $ae2, the string space
; ($58/$5c/$60/$64(a4)) and zeroes the variables from $70(a4) to $8c(a4).
;------------------------------------------------------------------------------
rt_clear:
	cmpa.l	$5c(a4),a3                      ; procedure stack empty?
	bne.s	.clear_not_allowed              ; no: error 40
	clr.l	$ae2(a4)                        ; RESTORE: DATA pointer to the start
	movea.l	$58(a4),a3                      ; a3 = procedure stack base
	move.l	a3,$5c(a4)                      ; procedure stack empty
	move.l	$64(a4),$60(a4)                 ; string space reset
	movea.l	$70(a4),a0                      ; variable area start
	move.l	$8c(a4),d0                      ; variable area end
	sub.l	a0,d0                           ; bytes
	lsr.l	#2,d0                           ; longs
.clear_loop:
	clr.l	(a0)+                           ; zero the variables
	dbra	d0,.clear_loop                  ; low word of the count
	subi.l	#$10000,d0                      ; high word of the count
	bpl.s	.clear_loop                     ; more longs
	rts
.clear_not_allowed:
	moveq	#40,d0                          ; error 40 'Clear not allowed ...'
	jmp	rn_error_entry(a6)              ; runtime error

; Runtime data: dc.w $01b9, the dependency word that makes routine $1b9
; (the table end) follow. The error texts start at $9f2a (routine $1b8,
; copied with the Errors option): error number byte, text with '|'
