;------------------------------------------------------------------------------
; Runtime routine $bb: MENU n,mode for a menu item. d0 = mode: bit 0 =
; state, bit 1 = 0 menu_icheck (AES 31) / 1 menu_ienable (AES 32);
; d1 = item number counted over the strings of the tree built by MENU
; a$() (objects from $18da(a4); a non-G_STRING object counts twice).
; Does nothing without a menu ($aea(a4) = 0). The word $00ba at $ac46
; is a dependency marker (needs routine $ba).
;------------------------------------------------------------------------------
rt_menu_item_state:
	moveq	#0,d2                           ; d2 = state bit
	lsr.w	#1,d0                           ; bit 0 of the mode

rt_menu_item_state_bit:
	addx.w	d2,d2                           ; d2 = state 0/1 from X
	move.w	d2,$74c(a4)                     ; intin[1] = state
	andi.w	#$1,d0                          ; bit 1 of the mode ...

rt_menu_item_opcode:
	addi.w	#$1f,d0                         ; ... gives 31 menu_icheck or 32 menu_ienable
	addq.w	#2,d1                           ; item number + 2
	moveq	#12,d2                          ; d2 = object index, items from object 12

rt_menu_item_tree:
	move.l	$aea(a4),$79a(a4)               ; addrin[0] = menu tree
	beq.s	rt_menu_item_done               ; no menu: nothing to do

rt_menu_item_scan:
	lea	$18ca(a4),a0                    ; object 12

rt_menu_item_next:
	btst	#$5,9(a0)                       ; LASTOB: end of the tree
	bne.s	rt_menu_item_last               ; last object reached
	cmpi.w	#$1c,6(a0)                      ; G_STRING counts once ...
	beq.s	.item_count_string              ; G_STRING: once
	subq.w	#1,d1                           ; ... anything else twice
.item_count_string:
	subq.w	#1,d1                           ; count it
	beq.s	rt_menu_item_call               ; reached the item
	adda.w	#$18,a0                         ; next object
	addq.w	#1,d2                           ; its object index
	bra.s	rt_menu_item_next               ; next object

rt_menu_item_call:
	move.w	d2,$74a(a4)                     ; intin[0] = object index
	jmp	rn_aes_call(a6)                 ; routine $21b: AES call

rt_menu_item_last:
	subq.w	#1,d1                           ; the last object: count it once more

rt_menu_item_last_test:
	beq.s	rt_menu_item_call               ; reached: call for the last object too

rt_menu_item_done:
	rts
	dc.w	$00ba                           ; dependency marker: needs routine $ba

;------------------------------------------------------------------------------
; Runtime routine $bd: MENU OFF - menu_tnormal (AES 33) on every
; selected title, from object 3. $ab30 dc.w $00ba is a dependency
; marker (needs $ba); $ab32 dc.w $00a3 is the next block's marker.
;------------------------------------------------------------------------------
rt_menu_off:
	move.l	$aea(a4),$79a(a4)               ; addrin[0] = menu tree
	beq.s	rt_menu_off_done                ; no menu
	moveq	#2,d3                           ; titles from object 3

rt_menu_off_start:
	lea	$17da(a4),a0                    ; object 2

rt_menu_off_next:
	adda.w	#$18,a0                         ; next object
	addq.w	#1,d3                           ; its index

rt_menu_off_test:
	btst	#$0,$b(a0)                      ; title shown selected?
	beq.s	.off_next_title                 ; not selected
	move.w	d3,$74a(a4)                     ; intin[0] = title
	move.w	#$1,$74c(a4)                    ; intin[1] = 1: normal
	moveq	#33,d0                          ; menu_tnormal
	move.l	a0,d6                           ; keep a0 over the AES call
	jsr	rn_aes_call(a6)                 ; AES menu_tnormal
	movea.l	d6,a0                           ; a0 back
.off_next_title:
	cmp.w	(a0),d3                         ; up to the parent's last child
	bcs.s	rt_menu_off_next                ; more titles

rt_menu_off_done:
	rts
	dc.w	$00ba,$00a3                     ; dependency marker: needs routine $ba

;------------------------------------------------------------------------------
; Runtime routine $bc: MENU KILL: clears the 6 ON MENU handlers ($b4a-$b5e(a4)), then
; removes the menu bar and rebuilds the template tree (rt_menu_reset_tree, which follows).
;------------------------------------------------------------------------------
rt_menu_kill:
	lea	$b4a(a4),a0                     ; ON MENU handlers
	moveq	#5,d0                           ; 6 ON MENU handlers ($b4a-$b5e)
.kill_clear_loop:
	clr.l	(a0)+                           ; cleared
	dbra	d0,.kill_clear_loop             ; all 6

;------------------------------------------------------------------------------
; Runtime: remove the menu bar (menu_bar(tree,0), AES 30) if one is
; shown and rebuild the template object tree at $17ba(a4): 100 objects
; of 24 bytes, root G_IBOX the size of the screen, bar G_BOX, 8 titles
; G_TITLE and the drop-down parent box. $aee(a4) = end of the text
; area at $2f2a(a4).
;------------------------------------------------------------------------------
rt_menu_reset_tree:
	lea	$2f1a(a4),a0                    ; end of the menu text area
	move.l	a0,$aee(a4)                     ; the text store ends here
	move.l	$aea(a4),$79a(a4)               ; menu shown?
	beq.s	.reset_build                    ; none: only build the tree
	clr.w	$74a(a4)                        ; intin[0] = 0: remove the bar
	moveq	#30,d0                          ; menu_bar
	jsr	rn_aes_call(a6)                 ; AES menu_bar(tree,0)
	clr.l	$aea(a4)                        ; no menu tree
.reset_build:
	lea	$17aa(a4),a0                    ; object array, 24 bytes each
	moveq	#1,d0                           ; ob_next of object 0
	moveq	#-1,d1                          ; ob_head = ob_tail = -1
	moveq	#16,d2                          ; ob_width 0, ob_height 16
.reset_object_loop:
	move.w	d0,(a0)+                        ; ob_next
	move.l	d1,(a0)+                        ; ob_head, ob_tail
	move.w	#$1c,(a0)+                      ; ob_type G_STRING
	clr.l	(a0)+                           ; ob_flags, ob_state
	clr.l	(a0)+                           ; ob_spec
	clr.l	(a0)+                           ; ob_x, ob_y
	move.l	d2,(a0)+                        ; ob_width, ob_height
	addq.w	#1,d0                           ; next object
	cmpi.w	#$65,d0                         ; 100 objects
	bne.s	.reset_object_loop              ; all 100
	lea	$17aa(a4),a0                    ; object 0, the root
	move.w	d1,(a0)+                        ; ob_next -1
	move.w	#$1,(a0)+                       ; ob_head 1
	move.w	#$b,(a0)+                       ; ob_tail 11
	move.w	#$19,(a0)+                      ; G_IBOX
	addq.l	#8,a0                           ; skip flags, state, ob_spec
	clr.l	(a0)+                           ; ob_x = ob_y = 0
	move.w	$b2a(a4),(a0)+                  ; width of the screen
	move.w	#$190,(a0)+                     ; height 400
	move.w	#$b,(a0)+                       ; object 1, the bar: ob_next 11
	move.w	#$2,(a0)+                       ; ob_head 2
	move.w	#$2,(a0)+                       ; ob_tail 2
	move.w	#$14,(a0)+                      ; G_BOX
	addq.l	#6,a0                           ; skip ob_type's flags and state
	move.w	#$1100,(a0)+                    ; ob_spec $00001100
	addq.l	#4,a0                           ; skip the rest of ob_spec, ob_x and ob_y
	move.w	$b2a(a4),(a0)+                  ; width of the screen
	move.w	#$12,(a0)+                      ; height 18
	move.w	#$1,(a0)+                       ; object 2, the title box: ob_next 1
	move.w	#$3,(a0)+                       ; ob_head 3
	move.w	#$b,(a0)+                       ; ob_tail, set to the last title by MENU a$()
	move.w	#$19,(a0)+                      ; G_IBOX
	addq.l	#8,a0                           ; skip flags, state, ob_spec
	move.w	#$10,(a0)+                      ; x 16
	clr.w	(a0)+                           ; y 0
	move.w	$b2a(a4),d0                     ; width of the screen - 16
	subi.w	#$10,d0                         ; width - 16
	move.w	d0,(a0)+                        ; ob_width
	move.w	#$13,(a0)+                      ; height 19
	moveq	#7,d0                           ; 8 more objects
.reset_title_loop:
	move.w	#$20,6(a0)                      ; G_TITLE
	move.w	#$13,$16(a0)                    ; height 19
	adda.w	#$18,a0                         ; next object
	dbra	d0,.reset_title_loop            ; objects 3-10
	clr.w	(a0)+                           ; object 11, the drop-down parent: ob_next 0
	move.w	#$c,(a0)+                       ; ob_head 12
	movea.l	a0,a2                           ; a2 = its ob_tail, set when the items are built
	addq.w	#2,a0                           ; skip ob_tail
	move.w	#$19,(a0)+                      ; G_IBOX
	addq.l	#8,a0                           ; skip flags, state and ob_spec
	move.l	$b26(a4),(a0)+                  ; x/y of the desktop work area
	move.w	$b2a(a4),(a0)+                  ; width of the screen
	move.w	#$12c,(a0)+                     ; height 300
	rts

;------------------------------------------------------------------------------
; Runtime: error 28 'Array must have|one dimension'.
;------------------------------------------------------------------------------
rt_menu_array_error:
	moveq	#28,d0                          ; error 28 'Array must have|one dimension'
	jmp	rn_error_entry(a6)              ; runtime error

;------------------------------------------------------------------------------
; Runtime: next element of the MENU string array; the element count
; is the long at 4(sp) (in the caller's frame). Exit: a0 = text,
; d0 = length, or d0 = 0 / Z set at the end.
;------------------------------------------------------------------------------
rt_menu_next_string:
	subq.l	#1,4(sp)                        ; one element less
	bmi.s	.array_end                      ; no more elements
	movea.l	(a3)+,a0                        ; element address
	move.w	(a3)+,d0                        ; element length
	rts                                     ; Z clear: a string
.array_end:
	moveq	#0,d0                           ; array used up
	rts                                     ; Z set: the end

;------------------------------------------------------------------------------
; Runtime routine $ba: MENU a$() - build a menu tree from the string
; array a0 and show it. Titles up to the first empty string go into
; objects 3.. as ' text ' (max 10 characters); each title's items follow
; until the next empty string, in a G_BOX of their widest width; an
; item starting with '-' is DISABLED. At most 11 titles and 99 objects
; (else error 62 'MENU error'). Texts are stored from $211e(a4). In
; colour resolutions y/height values are halved. Ends with menu_bar
; (AES 30, intin 1). a3-a5 are kept in routine 4 meanwhile.
;------------------------------------------------------------------------------
rt_menu_array:
	pea	(a0)                            ; string array descriptor
	bsr.w	rt_menu_reset_tree              ; start with the template tree
	movem.l	a3-a5,rn_saved_registers(a6)    ; a3-a5 into routine 4 while they are used
	movea.l	(sp)+,a0                        ; a0 = the descriptor
	movea.l	(a0)+,a3                        ; a3 = array data
	cmpi.w	#$1,(a0)                        ; one dimension?
	bne.s	rt_menu_array_error             ; not one: error 28
	move.l	(a3)+,-(sp)                     ; element count, kept on the stack
	moveq	#3,d6                           ; first title object
	moveq	#12,d7                          ; first drop-down object
	lea	$210e(a4),a5                    ; a5 = text store
	moveq	#0,d5                           ; d5 = x of the next title
.menu_title_loop:
	bsr.s	rt_menu_next_string             ; next title
	beq.w	rt_menu_finish_tree             ; empty string: end of the menu
	cmpi.w	#$a,d0                          ; titles at most 10 characters
	bcs.s	.menu_title_length              ; shorter: keep
	moveq	#10,d0                          ; cut to 10
.menu_title_length:
	move.w	d0,d1                           ; d1 = title length
	move.w	d6,d2                           ; title object d6
	mulu.w	#$18,d2                         ; * 24 bytes
	lea	$17b6(a4),a1                    ; ob_spec of object 0
	adda.l	d2,a1                           ; a1 = the title's ob_spec
	move.l	a5,(a1)+                        ; ob_spec = text
	move.w	d5,(a1)+                        ; ob_x
	move.b	#$20,(a5)+                      ; ' ' in front
	subq.w	#1,d0                           ; dbra count
.menu_title_copy:
	move.b	(a0)+,(a5)+                     ; copy the title
	cmpa.l	$aee(a4),a5                     ; text store full?
	dbcc	d0,.menu_title_copy             ; until the end or the store is full
	bcc.w	.menu_full                      ; full: MENU error
	move.b	#$20,(a5)+                      ; ' ' after
	clr.b	(a5)+                           ; NUL
	addq.w	#2,d1                           ; width = (length + 2) * 8
	mulu.w	#$8,d1                          ; * 8 pixels
	move.w	d1,2(a1)                        ; ob_width
	move.w	d7,d0                           ; drop-down box object d7
	mulu.w	#$18,d0                         ; * 24 bytes
	lea	$17aa(a4),a1                    ; object 0
	adda.l	d0,a1                           ; a1 = the box object
	move.w	d7,(a2)                         ; object 11's ob_tail / previous box's ob_next
	movea.l	a1,a2                           ; a2 = this box
	move.w	d7,(a1)+                        ; ob_next
	bsr.w	rt_menu_next_object             ; next object
	move.w	d7,(a1)+                        ; ob_head = first item
	move.w	d7,(a1)+                        ; ob_tail
	move.w	#$14,(a1)+                      ; G_BOX
	clr.l	(a1)+                           ; flags, state 0
	move.l	#$ff1100,(a1)+                  ; ob_spec $00ff1100
	move.w	d5,d0                           ; x = title x + 16
	addi.w	#$10,d0                         ; + 16
	move.w	d0,(a1)+                        ; ob_x of the box
	add.w	d1,d5                           ; next title further right
	addq.l	#6,a1                           ; skip y, width and height
	moveq	#0,d4                           ; d4 = widest item
	moveq	#0,d3                           ; d3 = item row
.menu_item_loop:
	bsr.w	rt_menu_next_string             ; next item
	beq.s	.menu_box_done                  ; empty string: end of this title
	move.w	d0,d1                           ; d1 = item length
	move.l	a5,$c(a1)                       ; ob_spec = text
	move.w	d3,d2                           ; y = row * 16
	asl.w	#4,d2                           ; * 16
	move.w	d2,$12(a1)                      ; ob_y
	subq.w	#1,d0                           ; dbra count
	cmpi.b	#$2d,(a0)                       ; '-' at the start?
	bne.s	.menu_item_copy                 ; no '-'
	bset	#$3,$b(a1)                      ; DISABLED
.menu_item_copy:
	move.b	(a0)+,(a5)+                     ; copy the item
	cmpa.l	$aee(a4),a5                     ; text store full?
	dbcc	d0,.menu_item_copy              ; until the end or the store is full
	bcc.s	.menu_full                      ; full: MENU error
	clr.b	(a5)+                           ; NUL
	asl.w	#3,d1                           ; width = length * 8
	cmp.w	d1,d4                           ; widest so far?
	bhi.s	.menu_item_width                ; no
	move.w	d1,d4                           ; d4 = widest so far
.menu_item_width:
	adda.w	#$18,a1                         ; next object
	addq.w	#1,d7                           ; its object index
	addq.w	#1,d3                           ; next row
	bra.s	.menu_item_loop                 ; next item
.menu_box_done:
	move.w	(a2),-$18(a1)                   ; last item points back to the box
	subq.w	#1,d7                           ; d7 = the last item
	move.w	d7,4(a2)                        ; ob_tail of the box
	asl.w	#4,d3                           ; height = rows * 16
	move.w	d3,$16(a2)                      ; ob_height of the box
	movea.l	a2,a0                           ; a0 = the box
.menu_box_widths:
	move.w	d4,$14(a0)                      ; all items get the widest width
	adda.w	#$18,a0                         ; next object
	cmpa.l	a1,a0                           ; up to the last item
	bls.s	.menu_box_widths                ; up to the last item
	bsr.s	rt_menu_next_object             ; next object for the next box
	addq.w	#1,d6                           ; next title
	cmpi.w	#$b,d6                          ; at most 11 titles
	bcs.w	.menu_title_loop                ; next title
.menu_full:
	bra.w	rt_menu_error                   ; full: MENU error

;------------------------------------------------------------------------------
; Runtime: next object index d7; 99 or more is the MENU error.
;------------------------------------------------------------------------------
rt_menu_next_object:
	addq.w	#1,d7                           ; next object
	cmpi.w	#$63,d7                         ; 99 objects at most
	bcc.w	rt_menu_error                   ; too many: MENU error
	rts                                     ; d7 = the new object

;------------------------------------------------------------------------------
; Runtime: finish the menu tree, store it at $afa(a4) and show it.
;------------------------------------------------------------------------------
rt_menu_finish_tree:
	addq.l	#4,sp                           ; drop the element count
	lea	$17aa(a4),a0                    ; object 0
	subq.w	#1,d6                           ; last title
	move.w	d6,$34(a0)                      ; ob_tail of the title box
	move.w	(a2),$10c(a0)                   ; object 11's ob_tail = the last box
	mulu.w	#$18,d6                         ; * 24 bytes
	move.w	#$2,0(a0,d6.l)                  ; last title's ob_next = 2, its parent
	move.w	#$b,(a2)                        ; last box's ob_next = 11, its parent
	mulu.w	#$18,d7                         ; * 24 bytes: d7 is one past the last object
	bset	#$5,-$f(a0,d7.l)                ; LASTOB on the last object
	move.w	d5,$44(a0)                      ; width of the title box; 0 = no titles
	beq.s	rt_menu_error                   ; no titles: MENU error
	lea	$17aa(a4),a0                    ; object 0
	move.l	a0,$79a(a4)                     ; addrin[0] = tree
	move.l	a0,$aea(a4)                     ; the menu tree
	move.w	#$1,$74a(a4)                    ; intin[0] = 1: show
	move.w	#$4,-(sp)                       ; Getrez
	trap	#14                             ; Getrez, Getrez
	addq.l	#2,sp                           ; drop the function number
	subq.w	#2,d0                           ; high resolution?
	beq.s	.finish_show                    ; high resolution: keep the sizes
	lea	$17aa(a4),a0                    ; object 0
	lea	$108(a0),a1                     ; the first 11 objects keep their y
.finish_halve_loop:
	cmpa.l	a1,a0                           ; objects 0-10?
	beq.s	.finish_halve_height            ; yes: only the height
	lsr.w	$12(a0)                         ; halve y (rounded up)
	bcc.s	.finish_halve_height            ; even: no rounding
	addq.w	#1,$12(a0)                      ; round up
.finish_halve_height:
	lsr.w	$16(a0)                         ; halve the height (rounded up)
	bcc.s	.finish_halve_next              ; even: no rounding
	addq.w	#1,$16(a0)                      ; round up
.finish_halve_next:
	adda.w	#$18,a0                         ; next object
	btst	#$5,-$f(a0)                     ; up to LASTOB
	beq.s	.finish_halve_loop              ; no: next object
.finish_show:
	moveq	#30,d0                          ; menu_bar
	movem.l	rn_saved_registers(a6),a3-a5    ; a3-a5 back
	jmp	rn_aes_call(a6)                 ; AES menu_bar(tree,1)

;------------------------------------------------------------------------------
; Runtime: error 62 'MENU error', with a3-a5 reloaded from routine 4.
;------------------------------------------------------------------------------
rt_menu_error:
	moveq	#62,d0                          ; error 62 'MENU error'
	movem.l	rn_saved_registers(a6),a3-a5    ; a3-a5 back
	jmp	rn_error_entry(a6)              ; runtime error

; Runtime routines $d0 ($add8, timer 0) and $1f2 ($adda, timer d0):
; ON MENU. $add6 dc.w $00ba is the dependency marker. Calls evnt_multi
; (AES 25) for keyboard, button, both mouse boxes, messages and timer
; with the parameters from $b72..$b7a(a4), message buffer $2f2e(a4);
; copies intout to $112a(a4) and $2f3e(a4), then calls the handlers
; through $204: message (MN_SELECTED -> ON MENU GOSUB $b4a, else ON MENU
; MESSAGE $b5e), box 1 $b56, box 2 $b5a, button $b52, key $b4e.
	dc.w	$00ba                           ; dependency marker: needs routine $ba

;------------------------------------------------------------------------------
; Runtime routine $d0: ON MENU with timer 0.
;------------------------------------------------------------------------------
rt_on_menu:
	moveq	#0,d0                           ; $d0: timer 0

;------------------------------------------------------------------------------
; Runtime routine $1f2: ON MENU with timer d0 (ms): one evnt_multi and the handlers called.
;------------------------------------------------------------------------------
rt_on_menu_timer:
	move.l	d0,d5                           ; $1f2: timer d0, high word first
	swap	d5                              ; d5 = timer: low word, high word
	lea	$74a(a4),a0                     ; intin
	move.w	#$3f,(a0)+                      ; events: keyboard, button, M1, M2, message, timer
	lea	$b62(a4),a1                     ; mouse box 1 and 2 parameters
	movem.l	(a1)+,d0-d4                     ; d0-d4 = box 1 (flag, x, y, w, h) and box 2 start
	move.w	(a1)+,(a0)+                     ; intin[1..3] = button clicks, mask, state
	move.w	(a1)+,(a0)+                     ; mouse button mask
	move.w	(a1)+,(a0)+                     ; mouse button state
	movem.l	d0-d5,(a0)                      ; intin[4..15] = boxes and timer
	lea	$2f2e(a4),a0                    ; message buffer
	move.l	a0,$79a(a4)                     ; addrin[0]
	moveq	#25,d0                          ; evnt_multi
	jsr	rn_aes_call(a6)                 ; AES evnt_multi
	movem.w	$772(a4),d0-d6                  ; intout: events, mouse x/y, button, shift, key, clicks
	movem.w	d0-d6,$111a(a4)                 ; copy at $112a(a4), its use is not in this range
	movem.w	d0-d6,$2f3e(a4)                 ; and at $2f4e(a4): MENU(9) to MENU(15)
	clr.w	$2f2c(a4)                       ; MENU(0) = 0
.event_dispatch:
	bclr	#$4,d0                          ; message event?
	bne.s	.event_message                  ; message
	bclr	#$2,d0                          ; mouse box 1?
	bne.s	.event_box_one                  ; mouse box 1
	bclr	#$3,d0                          ; mouse box 2?
	bne.s	.event_box_two                  ; mouse box 2
	bclr	#$1,d0                          ; button?
	bne.s	.event_button                   ; button
	bclr	#$0,d0                          ; keyboard?
	bne.s	.event_key                      ; keyboard
	rts                                     ; done
.event_message:
	cmpi.w	#$a,$2f2e(a4)                   ; MN_SELECTED?
	beq.s	.event_menu_item                ; a menu item: ON MENU GOSUB
	move.l	$b5e(a4),d3                     ; ON MENU MESSAGE GOSUB
	bra.s	.event_call
.event_key:
	move.l	$b4e(a4),d3                     ; ON MENU KEY GOSUB
	bra.s	.event_call
.event_button:
	move.l	$b52(a4),d3                     ; ON MENU BUTTON GOSUB
	bra.s	.event_call
.event_box_one:
	move.l	$b56(a4),d3                     ; ON MENU IBOX/OBOX GOSUB, box 1
	bra.s	.event_call
.event_box_two:
	move.l	$b5a(a4),d3                     ; box 2
	bra.s	.event_call
.event_menu_item:
	move.w	$2f34(a4),d1                    ; msg[3] = title object
	subq.w	#3,d1                           ; item number from the title ...
	add.w	d1,d1                           ; two per title (title and box)
	addq.w	#1,d1                           ; + 1
	move.w	$2f36(a4),d0                    ; msg[4] = item object
	lea	$17aa(a4),a0                    ; object 0
.event_count_strings:
	cmpi.w	#$1c,6(a0)                      ; ... plus the strings before the item
	bne.s	.event_count_next               ; not a string
	addq.w	#1,d1                           ; one more string
.event_count_next:
	adda.w	#$18,a0                         ; next object
	subq.w	#1,d0                           ; up to the item
	bne.s	.event_count_strings            ; more objects
	move.w	d1,$2f2c(a4)                    ; MENU(0)
	move.l	$b4a(a4),d3                     ; ON MENU GOSUB
.event_call:
	ble.s	.event_next                     ; no handler
	move.w	d0,-(sp)                        ; keep the remaining events
	movea.l	d3,a0                           ; a0 = the handler
	jsr	rn_gosub(a6)                    ; routine $204: GOSUB a0
	move.w	(sp)+,d0                        ; d0 = the remaining events
.event_next:
	bra.s	.event_dispatch                 ; next event

;------------------------------------------------------------------------------
; Runtime routine $a6: MENU(n): n = -1 gives the address of the object
; tree, else the word $2f2e(a4)+2*(n-1) (MENU(0) is $2f2c, the item).
;------------------------------------------------------------------------------
rt_menu_value:
	add.w	d0,d0                           ; MENU(-1)?
	bmi.s	.menu_value_tree                ; -1: the tree address
	lea	-$2(a4,d0.w),a0                 ; word n-1 of the message buffer
	moveq	#0,d0                           ; the word as a long
	move.w	$2f2e(a0),d0                    ; d0 = MENU(n)
	rts                                     ; done
.menu_value_tree:
	lea	$17aa(a4),a0                    ; the object tree
	move.l	a0,d0                           ; d0 = its address
	rts                                     ; done

;------------------------------------------------------------------------------
; Runtime routine $cc: ON MENU BUTTON ... GOSUB: handler d7 to $b62,
; clicks/mask from d1 (halves swapped) to $b86, state d0 to $b8a.
;------------------------------------------------------------------------------
rt_on_menu_button:
	move.l	d7,$b52(a4)                     ; ON MENU BUTTON GOSUB handler
	swap	d1                              ; clicks and mask in the right order
	move.l	d1,$b76(a4)                     ; clicks and mask
	move.w	d0,$b7a(a4)                     ; state
	rts                                     ; done

;------------------------------------------------------------------------------
; Runtime routines $cd (enter, flag 0) and $ce ($aec8, leave, flag 1): ON MENU IBOX/OBOX
; n,x,y,w,h GOSUB. a0 = n: odd n uses the second mouse box ($b6c, handler $b5a), even n the
; first ($b62, handler $b56). a1 = x/y (halves swapped), d1 = w, d0 = h, d7 = handler.
;------------------------------------------------------------------------------
rt_on_menu_box_enter:
	moveq	#0,d6                           ; $cd: enter the box
	bra.s	rt_on_menu_box_store            ; common part

;------------------------------------------------------------------------------
; Runtime routine $ce: ON MENU OBOX: as $cd with flag 1 (leave the box).
;------------------------------------------------------------------------------
rt_on_menu_box_leave:
	moveq	#1,d6                           ; $ce: leave the box

rt_on_menu_box_store:
	move.l	a0,d5                           ; d5 = box number
	lsr.w	#1,d5                           ; box number odd?
	bcc.s	.box_first                      ; even: the first box
	lea	$b6c(a4),a0                     ; second mouse box
	move.l	d7,$b5a(a4)                     ; its handler
	bra.s	.box_store                      ; store the box
.box_first:
	lea	$b62(a4),a0                     ; first mouse box
	move.l	d7,$b56(a4)                     ; its handler
.box_store:
	move.w	d6,(a0)+                        ; enter/leave flag
	move.l	a1,d6                           ; x/y
	swap	d6                              ; halves in order
	move.l	d6,(a0)+                        ; x, y
	move.w	d1,(a0)+                        ; width
	move.w	d0,(a0)+                        ; height
	rts                                     ; done

;------------------------------------------------------------------------------
; Runtime routine $214: window system start: work area of the desktop
; (wind_get 0,WF_WORKXYWH) to $b36(a4), centre to $b3e(a4), clears the
; 4 title and 4 info buffers at $2f8e(a4) ($50 bytes each).
; Routine $d1 enters at $b078: compute the 4 window rectangles in the
; table at $b02(a4) (12 bytes: handle, kind, x, y, w, h) from the
; centre and wind_set WF_CURRXYWH (AES 105) for the open ones.
;------------------------------------------------------------------------------
rt_window_system_init:
	moveq	#4,d0                           ; intin[0] = 0, intin[1] = 4: desktop, WF_WORKXYWH
	move.l	d0,$74a(a4)                     ; intin[0..1]
	moveq	#104,d0                         ; wind_get
	jsr	rn_aes_call(a6)                 ; AES wind_get
	movem.w	$774(a4),d0-d3                  ; work area of the desktop
	movem.w	d0-d3,$b26(a4)                  ; kept at $b36(a4)
	lsr.w	#1,d2                           ; half the width ...
	lsr.w	#1,d3                           ; ... and height
	add.w	d2,d0                           ; centre x
	add.w	d3,d1                           ; centre y
	movem.w	d0-d1,$b2e(a4)                  ; centre of the 4 windows
	lea	$2f7e(a4),a0                    ; title buffers, $50 bytes each
	move.w	#$2000,(a0)                     ; ' ' NUL
	move.w	(a0),$50(a0)                    ; title 2
	move.w	(a0),$a0(a0)                    ; title 3
	move.w	(a0),$f0(a0)                    ; title 4

;------------------------------------------------------------------------------
; Runtime routine $d1: the 4 window rectangles from the desktop and the centre $b2e(a4),
; wind_set WF_CURRXYWH for the open windows.
;------------------------------------------------------------------------------
rt_window_layout:
	lea	$af6(a4),a0                     ; $d1: rectangles of the 4 windows
	movem.w	$b26(a4),d0-d5                  ; desktop x, y, w, h, centre x, y
	move.w	d4,d6                           ; left width
	sub.w	d0,d6                           ; left width
	move.w	d5,d7                           ; top height
	sub.w	d1,d7                           ; top height
	sub.w	d6,d2                           ; right width
	sub.w	d7,d3                           ; bottom height
	move.w	d0,(a0)+                        ; window 1: top left
	move.w	d1,(a0)+                        ; y
	move.w	d6,(a0)+                        ; left width
	move.w	d7,(a0)+                        ; top height
	addq.l	#4,a0                           ; skip to the next entry's x
	move.w	d4,(a0)+                        ; window 2: top right
	move.w	d1,(a0)+                        ; y
	move.w	d2,(a0)+                        ; right width
	move.w	d7,(a0)+                        ; top height
	addq.l	#4,a0                           ; skip to the next entry's x
	move.w	d0,(a0)+                        ; window 3: bottom left
	move.w	d5,(a0)+                        ; centre y
	move.w	d6,(a0)+                        ; left width
	move.w	d3,(a0)+                        ; bottom height
	addq.l	#4,a0                           ; skip to the next entry's x
	move.w	d4,(a0)+                        ; window 4: bottom right
	move.w	d5,(a0)+                        ; centre y
	move.w	d2,(a0)+                        ; right width
	move.w	d3,(a0)+                        ; bottom height
	lea	$af2(a4),a1                     ; window table, 12 bytes each
	moveq	#3,d7                           ; 4 windows
.layout_set_loop:
	lea	$74a(a4),a0                     ; intin
	move.w	(a1)+,(a0)+                     ; intin[0] = handle
	beq.s	.layout_next                    ; not open
	move.w	#$5,(a0)+                       ; WF_CURRXYWH
	move.l	2(a1),(a0)+                     ; the new rectangle
	move.l	6(a1),(a0)+                     ; width and height
	moveq	#105,d0                         ; wind_set
	move.l	a1,d6                           ; keep a1 over the AES call
	jsr	rn_aes_call(a6)                 ; AES wind_set
	movea.l	d6,a1                           ; a1 back
.layout_next:
	adda.w	#$a,a1                          ; next window entry
	dbra	d7,.layout_set_loop             ; all 4
	rts

;------------------------------------------------------------------------------
; Runtime routine $d2: OPENW n without position; n = 0 does nothing.
; Moves the centre to the corner of window n's quarter and opens it.
;------------------------------------------------------------------------------
rt_openw:
	move.w	d0,-(sp)                        ; keep n
	subq.w	#1,d0                           ; OPENW 0: nothing
	bmi.s	rt_openw_drop_return            ; 0: drop n and return
	move.w	d0,d4                           ; window index
	movem.w	$b26(a4),d0-d3                  ; desktop rectangle
	lsr.w	#1,d4                           ; odd index: left edge ...
	bcs.s	.openw_corner_y                 ; odd: the left edge
	add.w	d2,d0                           ; ... else right edge
.openw_corner_y:
	lsr.w	#1,d4                           ; index 2/3: top edge ...
	bcs.s	rt_openw_at_centre              ; set: the top edge
	add.w	d3,d1                           ; ... else bottom edge
	bra.s	rt_openw_at_centre              ; open at that corner

;------------------------------------------------------------------------------
; Runtime routine $d3: OPENW n,x,y. n = 0 sets the output origin
; $b32(a4) on the desktop; else the centre moves to x,y (when on the
; screen) and window n opens.
;------------------------------------------------------------------------------
rt_openw_at:
	exg	d0,d1                           ; x in d0, y in d1
	move.w	a1,-(sp)                        ; keep n
	bne.s	rt_openw_check_position         ; OPENW n with n <> 0
	movem.w	d0-d1,-(sp)                     ; OPENW 0,x,y: desktop output ...
	bsr.s	rt_window_desktop               ; desktop work area as the output area
	move.l	(sp)+,$b32(a4)                  ; ... with the origin at x,y

rt_openw_drop_return:
	addq.l	#2,sp                           ; drop n
	rts

;------------------------------------------------------------------------------
; Runtime: output to the desktop (handle 0): its work area becomes the output area.
;------------------------------------------------------------------------------
rt_window_desktop:
	clr.w	$74a(a4)                        ; handle 0: the desktop
	bra.w	rt_window_get_work              ; wind_get WF_WORKXYWH of the desktop

rt_openw_check_position:
	cmp.w	$b2a(a4),d0                     ; x on the screen?
	bhi.s	rt_openw_drop_return            ; off the screen: nothing
	cmp.w	$b2c(a4),d1                     ; y on the screen?
	bhi.s	rt_openw_drop_return            ; off the screen: nothing

rt_openw_at_centre:
	movem.w	d0-d1,$b2e(a4)                  ; new centre
	jsr	rn_window_layout(a6)            ; routine $d1: new window rectangles
	move.w	(sp)+,d0                        ; n

;------------------------------------------------------------------------------
; Runtime routine $d4 (entry $afe4, d0 = window number): open window
; n (1-4) or bring it to the top: wind_create (AES 100) with NAME/INFO
; in the kind when a title/info line is set, wind_set WF_NAME/WF_INFO,
; wind_open (AES 101); then text output goes into its work area.
;------------------------------------------------------------------------------
rt_window_open:
	subq.w	#1,d0                           ; $d4: window index
	bmi.s	rt_window_desktop               ; 0: desktop
	andi.w	#$3,d0                          ; windows 1-4 only
	move.w	d0,d7                           ; d7 = index for the title buffer
	lea	$af2(a4),a0                     ; window table entry
	mulu.w	#$c,d0                          ; * 12 bytes
	adda.w	d0,a0                           ; a0 = the window's table entry
	mulu.w	#$50,d7                         ; its title buffer
	lea	$2f7e(a4),a1                    ; title buffers
	adda.l	d7,a1                           ; a1 = its title buffer
	move.l	a1,d7                           ; d7 = title address
	move.w	2(a0),d0                        ; window kind
	andi.b	#$ee,d0                         ; NAME and INFO bits off
	tst.b	(a1)                            ; a title?
	beq.s	.openw_info_test                ; no title
	addq.b	#1,d0                           ; NAME
.openw_info_test:
	tst.b	$140(a1)                        ; an info line?
	beq.s	.openw_kind_store               ; no info line
	bset	#$4,d0                          ; INFO
.openw_kind_store:
	move.w	d0,2(a0)                        ; the kind back into the table
	lea	$74a(a4),a1                     ; intin[0] = handle
	move.w	(a0)+,(a1)                      ; handle
	bne.s	rt_window_top                   ; already open: bring it to the top
	move.w	(a0)+,(a1)+                     ; intin[0] = kind
	pea	(a0)                            ; keep a0 (at x/y of the entry)
	move.l	$b26(a4),(a1)+                  ; full size: the desktop work area
	move.l	$b2a(a4),(a1)+                  ; desktop width and height
	moveq	#100,d0                         ; wind_create
	jsr	rn_aes_call(a6)                 ; AES wind_create
	move.w	$772(a4),d0                     ; handle
	movea.l	(sp),a0                         ; a0 = x/y of the entry
	move.w	d0,-$4(a0)                      ; into the window table
	lea	$74a(a4),a0                     ; intin
	move.w	d0,(a0)+                        ; intin[0] = handle
	move.w	#$2,(a0)+                       ; WF_NAME
	move.l	d7,(a0)+                        ; the title
	moveq	#105,d0                         ; wind_set
	jsr	rn_aes_call(a6)                 ; AES wind_set
	move.w	#$3,$74c(a4)                    ; WF_INFO
	addi.l	#$140,$74e(a4)                  ; the info line, $140 further on
	moveq	#105,d0                         ; wind_set
	jsr	rn_aes_call(a6)                 ; AES wind_set
	movea.l	(sp)+,a0                        ; a0 = x/y of the entry
	lea	$74c(a4),a1                     ; the window's rectangle
	move.l	(a0)+,(a1)+                     ; width and height
	move.l	(a0)+,(a1)+                     ; x, y, w, h into intin[1..4]
	moveq	#101,d0                         ; wind_open
	bra.s	rt_window_aes                   ; open it, then use its work area

;------------------------------------------------------------------------------
; Runtime: wind_set(handle $74a, WF_TOP), then rt_window_get_work.
;------------------------------------------------------------------------------
rt_window_top:
	move.w	#$a,$74c(a4)                    ; WF_TOP

;------------------------------------------------------------------------------
; Runtime: wind_set with intin from $75a(a4), then the work area as the output area.
;------------------------------------------------------------------------------
rt_window_set:
	moveq	#105,d0                         ; wind_set

rt_window_aes:
	jsr	rn_aes_call(a6)                 ; routine $21b: AES call

;------------------------------------------------------------------------------
; Runtime: wind_get(handle $74a, WF_WORKXYWH) and make the work area
; the output area: origin $b32, rectangle $2f60, clip $40e/$2f6a,
; $b36 = in a window, vs_clip on (VDI 129).
;------------------------------------------------------------------------------
rt_window_get_work:
	move.w	#$4,$74c(a4)                    ; WF_WORKXYWH
	moveq	#104,d0                         ; wind_get
	jsr	rn_aes_call(a6)                 ; AES wind_get
	movem.w	$774(a4),d0-d3                  ; work area x, y, w, h

rt_window_use_work:
	movem.w	d0-d1,$b32(a4)                  ; output origin
	movem.w	d0-d3,$2f60(a4)                 ; output rectangle
	subq.w	#1,d2                           ; width - 1
	subq.w	#1,d3                           ; height - 1
	add.w	d0,d2                           ; x2, y2
	add.w	d1,d3                           ; y2 = y + h - 1
	movem.w	d0-d3,$40e(a4)                  ; clip rectangle in ptsin
	movem.w	d0-d3,$2f6a(a4)                 ; and kept
	st	$b36(a4)                        ; text goes into a window
	st	$2f5e(a4)                       ; no ESC pending

rt_window_set_clip:
	st	$30e(a4)                        ; intin[0] <> 0: clipping on
	move.w	#$81,d0                         ; vs_clip
	moveq	#1,d1                           ; 1 intin, 2 ptsin
	moveq	#2,d2                           ; 2 ptsin
	jmp	rn_vdi_call_intin_ptsin(a6)     ; VDI vs_clip

;------------------------------------------------------------------------------
; Runtime: close windows 3,2,1,0 and use the desktop. No routine
; number points here and the code before ends with jmp; looks unused.
;------------------------------------------------------------------------------
	moveq	#3,d0                           ; close windows 4 to 1
	bsr.s	rt_window_close_index           ; close window 4
	moveq	#2,d0                           ; window 3
	bsr.s	rt_window_close_index           ; close window 3
	moveq	#1,d0                           ; window 2
	bsr.s	rt_window_close_index           ; close window 2
	moveq	#0,d0                           ; window 1
	bsr.s	rt_window_close_index           ; close window 1
	movem.w	$2f6a(a4),d0-d3                 ; last output rectangle, y then set to 0
	moveq	#0,d1                           ; y = 0
	bra.s	rt_window_use_work              ; make that the output area

;------------------------------------------------------------------------------
; Runtime routine $d5: CLOSEW n (1-4); n = 0 goes back to the desktop.
; sub_0b23e: wind_close/wind_delete (AES 102/103) on window index d0,
; then output goes to the top window (wind_get WF_TOP) or the desktop.
;------------------------------------------------------------------------------
rt_closew:
	subq.w	#1,d0                           ; CLOSEW 0: desktop
	bmi.s	rt_window_none_open             ; 0: desktop
	andi.w	#$3,d0                          ; window index

;------------------------------------------------------------------------------
; Runtime: close window index d0 (0-3): wind_close and wind_delete, then output to the top
; window or the desktop.
;------------------------------------------------------------------------------
rt_window_close_index:
	mulu.w	#$c,d0                          ; window table entry
	lea	$af2(a4),a0                     ; window table
	adda.l	d0,a0                           ; a0 = the window's entry
	move.w	(a0),$74a(a4)                   ; intin[0] = handle
	beq.s	rt_window_close_return          ; not open
	clr.w	(a0)                            ; mark it closed
	moveq	#102,d0                         ; wind_close
	jsr	rn_aes_call(a6)                 ; AES wind_close
	moveq	#103,d0                         ; wind_delete
	jsr	rn_aes_call(a6)                 ; AES wind_delete
	move.w	#$a,$74c(a4)                    ; WF_TOP
	moveq	#104,d0                         ; wind_get
	jsr	rn_aes_call(a6)                 ; AES wind_get WF_TOP
	move.w	d0,$74a(a4)                     ; d0 = intout[0], the AES result, not the top handle in intout[1]
	bne.w	rt_window_get_work              ; output goes there

;------------------------------------------------------------------------------
; Runtime: no window open: output to the desktop, clipping off the window.
;------------------------------------------------------------------------------
rt_window_none_open:
	clr.w	$74a(a4)                        ; no window: desktop
	bsr.w	rt_window_get_work              ; the desktop's work area as the output area
	sf	$b36(a4)                        ; not in a window
	clr.l	$40e(a4)                        ; clip and origin cleared
	clr.l	$b32(a4)                        ; origin 0
	bra.s	rt_window_set_clip              ; clipping set again with the cleared rectangle

rt_window_close_return:
	rts

;------------------------------------------------------------------------------
; Runtime routine $d6: CLEARW n - top window n and clear its work
; area, cursor home.
;------------------------------------------------------------------------------
rt_clearw:
	subq.w	#1,d0                           ; CLEARW 0: nothing
	bmi.s	rt_clearw_return                ; 0: nothing
	andi.w	#$3,d0                          ; windows 1-4 only
	mulu.w	#$c,d0                          ; window table entry
	lea	$af2(a4),a0                     ; window table
	move.w	0(a0,d0.l),$74a(a4)             ; intin[0] = handle
	beq.s	rt_clearw_return                ; not open
	bsr.w	rt_window_top                   ; bring it to the top

;------------------------------------------------------------------------------
; Runtime: text cursor home in the window and clear the work area.
;------------------------------------------------------------------------------
rt_window_clear_home:
	clr.l	$870(a4)                        ; cursor column and row 0
	bra.w	rt_window_clear_work            ; clear the work area

rt_clearw_return:
	rts

;------------------------------------------------------------------------------
; Runtime routine $d7: print d0.l characters from a1 into the GEM
; output window with v_gtext (VDI 8), character cell size from
; vqt_attributes (VDI 38). With d6 <> 2 the characters are drawn raw;
; else CR, LF, BS, Bell and ESC E (clear) / ESC p / ESC q (text effects
; bit 3, vst_effects) are acted on. Wraps and scrolls inside the window.
;------------------------------------------------------------------------------
rt_window_print_text:
	pea	(a3)                            ; keep a3
	movea.l	a1,a3                           ; a3 = text
	move.l	d0,d7                           ; d7 = count
	cmpi.w	#$2,d6                          ; channel 2 acts on control codes
	sne	$b37(a4)                        ; $b37 set: draw every code
	moveq	#38,d0                          ; vqt_attributes
	jsr	rn_vdi_call(a6)                 ; routine $21c: VDI call variant
	move.w	$618(a4),$2f68(a4)              ; text effects
	move.w	$712(a4),d4                     ; character cell width
	move.w	$714(a4),d5                     ; and height
	movem.w	$2f64(a4),d0-d1                 ; work area width and height
	move.w	$870(a4),d2                     ; cursor column outside the window?
	mulu.w	d4,d2                           ; x of the cursor
	cmp.w	d0,d2                           ; beyond the width?
	bls.s	.print_clamp_row                ; inside: keep
	divu.w	d4,d0                           ; last column
	subq.w	#1,d0                           ; 0-based
	move.w	d0,$870(a4)                     ; cursor on the last column
.print_clamp_row:
	move.w	$872(a4),d2                     ; cursor row outside the window?
	mulu.w	d5,d2                           ; y of the cursor
	cmp.w	d1,d2                           ; below the bottom?
	bls.s	rt_window_print_escape_done     ; inside: start
	divu.w	d5,d1                           ; last row
	subq.w	#1,d1                           ; 0-based
	move.w	d1,$872(a4)                     ; cursor on the last row
	bra.s	rt_window_print_escape_done     ; start

rt_window_print_char:
	moveq	#0,d0                           ; next character
	move.b	(a3)+,d0                        ; d0 = the character
	tst.b	$b37(a4)                        ; draw everything?
	bne.s	rt_window_print_glyph           ; raw: draw it
	tas	$2f5e(a4)                       ; no ESC pending?
	bmi.s	rt_window_print_control         ; no ESC pending: an ordinary code
	cmpi.b	#$45,d0                         ; ESC E: clear
	beq.s	rt_window_print_esc_e           ; ESC E
	move.w	$2f68(a4),d1                    ; effects
	bset	#$3,d1                          ; ESC p: bit 3 on
	cmpi.b	#$70,d0                         ; ESC p?
	beq.s	.print_effects                  ; ESC p
	bclr	#$3,d1                          ; ESC q: bit 3 off
	cmpi.b	#$71,d0                         ; ESC q? anything else is ignored
	bne.s	rt_window_print_skip            ; not ESC q: ignore
.print_effects:
	move.w	d1,$2f68(a4)                    ; new effects
	moveq	#106,d0                         ; vst_effects
	jsr	rn_vdi_call_intin_d1(a6)        ; routine $243: VDI call variant

rt_window_print_escape_done:
	bra.s	rt_window_print_skip

rt_window_print_esc_e:
	bsr.w	rt_window_clear_home            ; clear the window, cursor home
	bra.s	rt_window_print_skip

rt_window_print_control:
	cmpi.b	#$20,d0                         ; printable?
	bcc.s	rt_window_print_glyph           ; printable: draw it
	cmpi.b	#$1b,d0                         ; ESC: next code is an escape
	sne	$2f5e(a4)                       ; $2f5e = 0 while an ESC is pending
	beq.s	rt_window_print_skip            ; ESC: skip it
	cmpi.b	#$d,d0                          ; CR
	beq.w	rt_window_print_return          ; CR
	cmpi.b	#$a,d0                          ; LF
	beq.s	rt_window_print_linefeed        ; LF
	cmpi.b	#$7,d0                          ; Bell
	beq.w	rt_window_print_bell            ; Bell
	cmpi.b	#$8,d0                          ; Backspace
	bne.s	rt_window_print_next            ; any other control code: ignored
	subq.w	#1,$870(a4)                     ; column - 1 ...
	bpl.s	rt_window_print_skip            ; still in the window
	clr.w	$870(a4)                        ; ... not below 0

rt_window_print_skip:
	bra.s	rt_window_print_next

rt_window_print_glyph:
	move.w	d0,$30e(a4)                     ; intin[0] = character
	move.w	$870(a4),d0                     ; x = column * cell width + origin
	mulu.w	d4,d0                           ; * cell width
	add.w	$b32(a4),d0                     ; + origin x
	move.w	d0,$40e(a4)                     ; ptsin[0]
	move.w	$872(a4),d0                     ; y = (row + 1) * cell height - 1 + origin
	addq.w	#1,d0                           ; row + 1
	mulu.w	d5,d0                           ; * cell height
	subq.w	#1,d0                           ; - 1: the baseline
	add.w	$b34(a4),d0                     ; + origin y
	move.w	d0,$410(a4)                     ; ptsin[1]
	moveq	#8,d0                           ; v_gtext
	moveq	#1,d1                           ; 1 intin, 1 ptsin
	moveq	#1,d2                           ; 1 ptsin
	jsr	rn_vdi_call_intin_ptsin(a6)     ; VDI v_gtext
	addq.w	#1,$870(a4)                     ; next column
	move.w	d4,d0                           ; width of the columns so far
	mulu.w	$870(a4),d0                     ; x of the next column
	cmp.w	$2f64(a4),d0                    ; still inside the window?
	bcs.s	rt_window_print_next            ; inside: next character
	clr.w	$870(a4)                        ; wrap: column 0

rt_window_print_linefeed:
	addq.w	#1,$872(a4)                     ; next row
	move.w	d5,d6                           ; bottom of the next row
	mulu.w	$872(a4),d6                     ; = (row + 1) * height ...
	subq.w	#1,d6                           ; ... - 1
	add.w	d5,d6                           ; + one more row
	sub.w	$2f66(a4),d6                    ; below the bottom of the window?
	bls.s	rt_window_print_next            ; not below: next character
	subq.w	#1,$872(a4)                     ; stay on the last row and scroll
	bsr.s	rt_window_scroll_line           ; scroll the work area up one line

rt_window_print_next:
	dbra	d7,rt_window_print_char         ; count, 32 bits
	subi.l	#$10000,d7                      ; high word of the count
	bpl.w	rt_window_print_char            ; more characters
	movea.l	(sp)+,a3                        ; a3 back
	rts

rt_window_print_return:
	clr.w	$870(a4)                        ; CR: column 0
	bra.s	rt_window_print_next            ; next character

;------------------------------------------------------------------------------
; Runtime: scroll the window work area up one character line
; (raster copy with routines $21/$22, mode 3) and clear the last line.
;------------------------------------------------------------------------------
rt_window_scroll_line:
	move.w	#$3,$30e(a4)                    ; intin[0] = 3: S_ONLY
	movem.l	d4-d5/d7/a3,-(sp)               ; keep d4, d5, d7, a3
	lea	$40e(a4),a0                     ; ptsin source/target rectangles
	sub.w	d5,d6                           ; d6 less two line heights, kept at $42e(a4)
	sub.w	d5,d6                           ; minus two line heights
	move.w	d6,$10(a0)                      ; kept at $42e(a4)
	movem.w	$2f6a(a4),d0-d3                 ; window rectangle
	movem.w	d0-d3,(a0)                      ; as source ...
	movem.w	d0-d3,8(a0)                     ; ... and target
	add.w	d5,2(a0)                        ; source one line lower
	sub.w	d5,$e(a0)                       ; target one line shorter
	jsr	rn_screen_mfdbs(a6)             ; routine $21: raster copy set-up
	jsr	rn_vro_cpyfm(a6)                ; routine $22: raster copy
	clr.w	$30e(a4)                        ; mode 0: clear
	lea	$40e(a4),a0                     ; the last line
	move.w	6(a0),d0                        ; target y2
	move.w	d0,$e(a0)                       ; into the first rectangle's y2
	add.w	$10(a0),d0                      ; + d6
	addq.w	#3,d0                           ; + 3
	move.w	d0,2(a0)                        ; y1 of the cleared line
	move.w	d0,$a(a0)                       ; in both rectangles
	bra.s	rt_window_blit_clear            ; clear it

;------------------------------------------------------------------------------
; Runtime: clear the whole window work area (raster mode 0).
;------------------------------------------------------------------------------
rt_window_clear_work:
	movem.l	d4-d5/d7/a3,-(sp)               ; whole work area
	lea	$40e(a4),a0                     ; ptsin
	movem.l	$2f6a(a4),d0-d1                 ; window rectangle
	move.l	d0,(a0)+                        ; as source ...
	move.l	d1,(a0)+                        ; x2, y2
	move.l	d0,(a0)+                        ; ... and target
	move.l	d1,(a0)+                        ; x2, y2
	jsr	rn_screen_mfdbs(a6)             ; routine $21: raster copy set-up

;------------------------------------------------------------------------------
; Runtime: raster copy with mode 0 (clear) of the rectangles at $41e(a4), registers restored.
;------------------------------------------------------------------------------
rt_window_blit_clear:
	clr.w	$30e(a4)                        ; mode 0: clear
	jsr	rn_vro_cpyfm(a6)                ; routine $22: raster copy
	movem.l	(sp)+,d4-d5/d7/a3               ; restore d4, d5, d7, a3
	rts

;------------------------------------------------------------------------------
; Runtime: Bell in the window output: Bconout(2,7), then the next character.
;------------------------------------------------------------------------------
rt_window_print_bell:
	move.w	d0,-(sp)                        ; Bell
	move.w	#$2,-(sp)                       ; on the console
	move.w	#$3,-(sp)                       ; Bconout
	trap	#13                             ; Bconout
	addq.l	#6,sp                           ; drop the arguments
	bra.w	rt_window_print_next            ; next character

; Runtime data: dependency marker words $00da, $00a3 (block $af94)
; and $00a3 (block $b32e), the last two decoded as an ori.l. Then
; runtime routines $d8 (INFOW n,a$, $b330) and $d9 (TITLEW n,a$,
; $b336): store up to 78 characters in the info/title buffer of window
; n at $2f8e(a4), set INFO/NAME in its kind, and wind_set WF_INFO/WF_NAME
; if it is open.
	dc.w	$00da,$00a3,$00a3               ; data: dependency marker $00da

;------------------------------------------------------------------------------
; Runtime routine $d8: INFOW n,a$: d0 = 3 (WF_INFO), d2 = 4 (the info buffers and the INFO
; bit 4), then rt_window_text_set.
;------------------------------------------------------------------------------
rt_infow:
	moveq	#3,d0                           ; $d8 (INFOW): WF_INFO
	moveq	#4,d2                           ; info buffers 4 further on
	bra.s	rt_window_text_set              ; common part

;------------------------------------------------------------------------------
; Runtime routine $d9: TITLEW n,a$ (d0 = 2, WF_NAME; d2 = 0, the title buffers and the NAME
; bit 0); $d8 (INFOW) enters above with 3/4. d1 = window number, a0 = the string.
;------------------------------------------------------------------------------
rt_titlew:
	moveq	#2,d0                           ; $d9 (TITLEW): WF_NAME
	moveq	#0,d2                           ; title buffers

;------------------------------------------------------------------------------
; Runtime: TITLEW/INFOW common part: d0 = WF_ code, d1 = window number, d2 = buffer offset
; (0 title, 4 info) and also the kind bit (0 NAME, 4 INFO), a0 = the string.
;------------------------------------------------------------------------------
rt_window_text_set:
	subq.w	#1,d1                           ; window number
	bmi.s	.title_done                     ; 0: nothing
	andi.w	#$3,d1                          ; windows 1-4 only
	move.w	d2,-(sp)                        ; buffer offset, WF_ code, window index
	move.w	d0,-(sp)                        ; WF_ code
	move.w	d1,-(sp)                        ; window index
	jsr	rn_string_text_len_212(a6)      ; routine $212: a1 = text, d0 = length
	move.w	d0,d4                           ; d4 = text length
	movem.w	(sp)+,d0-d2                     ; d0 = index, d1 = WF_ code, d2 = 0/4
	move.w	d0,d3                           ; buffer number index + 0/4
	add.w	d2,d3                           ; + 0 or 4
	mulu.w	#$50,d3                         ; * 80 bytes
	lea	$2f7e(a4),a0                    ; buffer
	adda.l	d3,a0                           ; a0 = the buffer
	mulu.w	#$c,d0                          ; * 12 bytes
	lea	$af2(a4),a2                     ; window table entry
	adda.l	d0,a2                           ; a2 = the window entry
	move.w	(a2)+,$74a(a4)                  ; intin[0] = handle
	move.w	d1,$74c(a4)                     ; intin[1] = WF_NAME/WF_INFO
	move.l	a0,$74e(a4)                     ; intin[2/3] = text
	tst.w	d4                              ; empty: no NAME/INFO
	beq.s	.title_copy_next                ; empty: just the NUL
	bset	d2,1(a2)                        ; NAME (bit 0) or INFO (bit 4) in the kind
	cmpi.w	#$4e,d4                         ; at most 78 characters
	bcs.s	.title_copy_next                ; below: keep the length
	moveq	#77,d4                          ; cut to 78
.title_copy_loop:
	move.b	(a1)+,(a0)+                     ; copy the text
.title_copy_next:
	dbra	d4,.title_copy_loop             ; d4 bytes
	clr.b	(a0)+                           ; NUL NUL
	clr.b	(a0)+                           ; NUL
	tst.w	$74a(a4)                        ; window open?
	beq.s	.title_done                     ; not open
	btst	d2,1(a2)                        ; and with that element?
	beq.s	.title_done                     ; without NAME/INFO: no wind_set
	moveq	#105,d0                         ; wind_set
	bra.w	rt_window_set                   ; AES wind_set
.title_done:
	rts

;------------------------------------------------------------------------------
; Runtime routine $1c1: drop one frame from the procedure stack a3
; (its size byte is in front of the long) and save a3 in routine 4.
;------------------------------------------------------------------------------
rt_drop_procedure_frame:
	subq.l	#4,a3                           ; back over the long
	moveq	#0,d0                           ; size byte as a word
	move.b	(a3),d0                         ; frame size byte
	suba.w	d0,a3                           ; drop the frame
	move.l	a3,rn_saved_registers(a6)       ; save a3 in routine 4
	rts

;------------------------------------------------------------------------------
; Runtime routine $cf: ON x GOSUB. The return address points at a
; table of d7 longs; x = d0. Out of range continues after the table;
; else the call returns behind the table and the target is called with
; $204 (a zero entry does nothing). $b3d0 dc.w $0204 is the dependency
; marker; routine $204 follows directly.
;------------------------------------------------------------------------------
rt_on_gosub:
	movea.l	(sp)+,a0                        ; return address = table of d7 longs
	cmp.l	d7,d0                           ; x above the count?
	bhi.s	.on_gosub_skip                  ; too large: skip
	asl.w	#2,d0                           ; x * 4
	beq.s	.on_gosub_skip                  ; x = 0
	asl.w	#2,d7                           ; table size
	pea	0(a0,d7.w)                      ; return behind the table
	move.l	-$4(a0,d0.w),d0                 ; target x
	bne.s	.on_gosub_target                ; 0: no call
	rts                                     ; zero entry: continue behind the table
.on_gosub_skip:
	asl.w	#2,d7                           ; table size
	jmp	0(a0,d7.w)                      ; continue behind the table
	dc.w	$0204                           ; dependency marker: needs routine $204, which follows
.on_gosub_target:
	movea.l	d0,a0                           ; a0 = target

;------------------------------------------------------------------------------
; Runtime routine $204: GOSUB a0 - push the return address onto the
; procedure stack a3 (garbage collection $203 if full, then error 8),
; save a3 in routine 4, jmp (a0).
;------------------------------------------------------------------------------
rt_gosub:
	movea.l	$60(a4),a1                      ; procedure stack limit
	subq.l	#4,a1                           ; room for one long
	cmpa.l	a1,a3                           ; room for a long?
	bcc.s	.gosub_no_room                  ; no room: garbage collection
.gosub_push:
	move.l	(sp)+,(a3)+                     ; return address onto the procedure stack
	move.l	a3,rn_saved_registers(a6)       ; save a3 in routine 4
	jmp	(a0)                            ; call
.gosub_no_room:
	jsr	rn_string_garbage_collect(a6)   ; routine $203: garbage collection
	movea.l	$60(a4),a1                      ; check again
	subq.l	#4,a1                           ; room for one long
	cmpa.l	a1,a3                           ; room now?
	bcs.s	.gosub_push                     ; room now
	moveq	#8,d0                           ; error 8 'Out of memory'
	jmp	rn_error_entry(a6)              ; runtime error

;------------------------------------------------------------------------------
; Runtime routine $1fe: RETURN - pop longs from a3: a positive one is
; the return address; negative ones are LOCAL save records that put
; the old value back, tagged in the top bits: $80 float (6 bytes),
; $a0 string (descriptor and back-link), $c0 long, $e0 word.
;------------------------------------------------------------------------------
rt_return:
	move.l	-(a3),d3                        ; pop
	bmi.s	.return_local                   ; negative: LOCAL record
	movea.l	d3,a1                           ; a1 = return address
	move.l	a3,rn_saved_registers(a6)       ; save a3 in routine 4
	jmp	(a1)                            ; return
.return_local:
	movea.l	d3,a1                           ; a1 = variable address
	add.l	d3,d3                           ; bit 30?
	bmi.s	.return_long_or_word            ; set: long or word
	add.l	d3,d3                           ; bit 29?
	bmi.s	.return_string                  ; set: string
	move.w	-(a3),(a1)                      ; $80: float, 6 bytes back
	move.l	-(a3),-(a1)                     ; old mantissa (a1 is the address of the 6 bytes + 4)
	bra.s	rt_return                       ; next long
.return_long_or_word:
	add.l	d3,d3                           ; bit 29?
	bmi.s	.return_word                    ; set: word
	move.l	-(a3),(a1)                      ; $c0: long back
	bra.s	rt_return                       ; next long
.return_word:
	move.w	-(a3),(a1)                      ; $e0: word back
	bra.s	rt_return                       ; next long
.return_string:
	move.l	a1,d3                           ; $a0: string, d3 = descriptor address
	andi.l	#$ffffff,d3                     ; the address without the tag
	movea.l	(a1)+,a2                        ; current text
	move.w	(a1),d4                         ; current length
	beq.s	.return_string_old              ; empty: nothing to free
	ext.l	d4                              ; mark the current text free:
	addq.w	#1,d4                           ; + 1
	andi.w	#$fffe,d4                       ; even offset of the back-link
	move.l	d4,d5                           ; d5 = size
	neg.l	d5                              ; -size
	move.l	d5,0(a2,d4.l)                   ; free mark after the text
.return_string_old:
	move.w	-(a3),d4                        ; old length
	movea.l	-(a3),a2                        ; old text
	move.w	d4,(a1)                         ; length back
	beq.s	rt_return                       ; empty: no text, no back-link
	move.l	a2,-(a1)                        ; text back
	ext.l	d4                              ; even length
	addq.w	#1,d4                           ; + 1
	andi.w	#$fffe,d4                       ; even offset
	move.l	d3,0(a2,d4.l)                   ; back-link to the descriptor
	bra.s	rt_return                       ; next long

;------------------------------------------------------------------------------
; Runtime routines $17a (LOCAL x%, $b458, value 0) and $17e (value d0):
; save the long at a0 on a3 with tag $c0, then set it.
;------------------------------------------------------------------------------
rt_local_long_zero:
	moveq	#0,d0                           ; value 0

;------------------------------------------------------------------------------
; Runtime routine $17e: LOCAL of a long variable a0 with the value d0 (record tagged $c0).
;------------------------------------------------------------------------------
rt_local_long:
	movea.l	$60(a4),a1                      ; procedure stack limit
	subq.l	#8,a1                           ; room for two longs
	cmpa.l	a1,a3                           ; room?
	bcc.s	.local_long_no_room             ; no room
.local_long_push:
	move.l	(a0),(a3)+                      ; old value
	move.l	a0,(a3)+                        ; variable address ...
	move.b	#$c0,-$4(a3)                    ; ... tagged $c0: long
	move.l	d0,(a0)                         ; new value
	rts
.local_long_no_room:
	jsr	rn_string_garbage_collect(a6)   ; routine $203: garbage collection
	movea.l	$60(a4),a1                      ; check again
	subq.l	#8,a1                           ; room for two longs
	cmpa.l	a1,a3                           ; room now?
	bcs.s	.local_long_push                ; room now?
	moveq	#90,d0                          ; error 90 'LOCAL error'
	jmp	rn_error_entry(a6)              ; runtime error

;------------------------------------------------------------------------------
; Runtime routines $17b ($b486, value 0) and $17f (value d2): save the
; word at a0 on a3 with tag $e0, then set it (LOCAL of a word variable).
;------------------------------------------------------------------------------
rt_local_word_zero:
	moveq	#0,d2                           ; value 0

;------------------------------------------------------------------------------
; Runtime routine $17f: LOCAL of a word variable a0 with the value d2 (record tagged $e0).
;------------------------------------------------------------------------------
rt_local_word:
	movea.l	$60(a4),a1                      ; procedure stack limit
	subq.l	#6,a1                           ; room for a word and a long
	cmpa.l	a1,a3                           ; room?
	bcc.s	.local_word_no_room             ; no room
.local_word_push:
	move.w	(a0),(a3)+                      ; old value
	move.l	a0,(a3)+                        ; variable address ...
	move.b	#$e0,-$4(a3)                    ; ... tagged $e0: word
	move.w	d2,(a0)                         ; new value
	rts
.local_word_no_room:
	jsr	rn_string_garbage_collect(a6)   ; routine $203: garbage collection
	movea.l	$60(a4),a1                      ; check again
	subq.l	#6,a1                           ; room for a word and a long
	cmpa.l	a1,a3                           ; room now?
	bcs.s	.local_word_push                ; room now?
	moveq	#90,d0                          ; error 90 'LOCAL error'
	jmp	rn_error_entry(a6)              ; runtime error

;------------------------------------------------------------------------------
; Runtime routines $178 (LOCAL x, value 0.0) and $17c ($b4ba, value
; d0-d2 rounded to the 6-byte float format): save the 6-byte float at
; a0 on a3 with tag $80, then set it.
;------------------------------------------------------------------------------
rt_local_float_zero:
	moveq	#0,d0                           ; value 0.0
	moveq	#0,d1                           ; mantissa low 0
	bra.s	rt_local_float_push             ; save and set

;------------------------------------------------------------------------------
; Runtime routine $17c: LOCAL x = d0-d2: the float rounded and packed into the 6-byte form,
; then saved and set at rt_local_float_push.
;------------------------------------------------------------------------------
rt_local_float:
	addi.w	#$200,d1                        ; round the mantissa ...
	bcc.s	.local_float_pack               ; no carry
	addq.l	#1,d0                           ; ... carry into the high long
	bcc.s	.local_float_pack               ; no carry out
	roxr.l	#1,d0                           ; overflow: shift back ...
	roxr.w	#1,d1                           ; into the low word
	tst.w	d2                              ; ... and raise the exponent
	beq.s	.local_float_pack               ; zero: stays zero
	addq.w	#1,d2                           ; exponent + 1
.local_float_pack:
	andi.w	#$3ff,d2                        ; 10-bit exponent
	andi.w	#$fc00,d1                       ; into the low word
	or.w	d2,d1                           ; d1 = low mantissa bits and exponent
	tst.l	d2                              ; positive?
	bmi.s	rt_local_float_push             ; negative: keep the sign bit
	bclr	#$1f,d0                         ; clear the sign

;------------------------------------------------------------------------------
; Runtime: LOCAL of a float: the 6 bytes at a0 pushed on a3 with the address + 4 tagged $80,
; then d0/d1 (packed) stored; error 90 when there is no room after a garbage collection.
;------------------------------------------------------------------------------
rt_local_float_push:
	movea.l	$60(a4),a1                      ; procedure stack limit
	suba.w	#$a,a1                          ; room for 10 bytes
	cmpa.l	a1,a3                           ; room for 10 bytes?
	bcc.s	.local_float_no_room            ; no room: garbage collection
.local_float_push:
	move.l	(a0)+,(a3)+                     ; old value, 6 bytes
	move.w	(a0),(a3)+                      ; low mantissa and exponent
	move.l	a0,(a3)+                        ; variable address + 4 ...
	move.b	#$80,-$4(a3)                    ; ... tagged $80: float
	move.w	d1,(a0)                         ; new value
	move.l	d0,-(a0)                        ; mantissa: a0 back at the variable
	rts
.local_float_no_room:
	jsr	rn_string_garbage_collect(a6)   ; routine $203: garbage collection
	movea.l	$60(a4),a1                      ; check again
	suba.w	#$a,a1                          ; room for 10 bytes
	cmpa.l	a1,a3                           ; room now?
	bcs.s	.local_float_push               ; room now
	moveq	#90,d0                          ; error 90 'LOCAL error'
	jmp	rn_error_entry(a6)              ; runtime error

;------------------------------------------------------------------------------
; Runtime routines $179 ($b514) and $17d ($b518): LOCAL a$ - save the
; descriptor at a0 on a3 with tag $a0, empty the variable, then give it
; the value a1 ($179 first copies a0 when it is the temporary $ad2(a4)).
; Back-links at the end of the string data are kept up to date.
;------------------------------------------------------------------------------
rt_local_string_empty:
	lea	$ad2(a4),a1                     ; value is the temporary string?

;------------------------------------------------------------------------------
; Runtime routine $17d: LOCAL a$ = a1$: the descriptor at a0 saved (tag $a0), the variable
; emptied and given the value a1.
;------------------------------------------------------------------------------
rt_local_string:
	cmpa.l	a0,a1                           ; the value is the variable itself?
	bne.s	.local_string_room              ; not the same: no copy
	pea	(a0)                            ; keep the descriptor
	move.w	4(a0),d0                        ; its length
	jsr	rn_temp_string_alloc(a6)        ; routine $47: new string space, a1 = text
	movea.l	(sp),a2                         ; copy the temporary text there
	movea.l	(a2),a2                         ; a2 = its text
	addq.w	#1,d0                           ; length in words, rounded up
	lsr.w	#1,d0                           ; words
	bra.s	.local_string_copy_next         ; dbra count
.local_string_copy_loop:
	move.w	(a2)+,(a1)+                     ; copy a word
.local_string_copy_next:
	dbra	d0,.local_string_copy_loop      ; all words
	movea.l	a0,a1                           ; a1 = the copy's descriptor
	movea.l	(sp)+,a0                        ; a0 = the variable
.local_string_room:
	movea.l	$60(a4),a2                      ; procedure stack limit
	suba.w	#$a,a2                          ; room for 10 bytes
	cmpa.l	a2,a3                           ; room?
	bcc.s	.local_string_no_room           ; room for 10 bytes?
.local_string_push:
	move.l	a3,d1                           ; position of this record
	movea.l	(a0)+,a2                        ; old text
	move.l	a2,(a3)+                        ; saved
	move.w	(a0),d0                         ; old length
	clr.w	(a0)                            ; variable now empty
	move.w	d0,(a3)+                        ; saved
	subq.l	#4,a0                           ; a0 = the descriptor
	move.l	a0,(a3)+                        ; descriptor address ...
	move.b	#$a0,-$4(a3)                    ; ... tagged $a0: string
	ext.l	d0                              ; old text had a back-link?
	beq.s	.local_string_value             ; old string empty: no back-link
	addq.w	#1,d0                           ; + 1
	andi.w	#$fffe,d0                       ; even offset
	move.l	d1,0(a2,d0.l)                   ; now pointing at this record
.local_string_value:
	lea	$ad2(a4),a2                     ; value from the temporary area?
	cmpa.l	a2,a1                           ; the value's descriptor below $ad2(a4)?
	bcs.s	.local_string_take              ; yes, a temporary: take its text over
	pea	(a1)                            ; keep the value's descriptor
	move.w	4(a1),d0                        ; length of the value
	jsr	rn_string_alloc_var(a6)         ; routine $45: string space for the variable
	movea.l	(sp)+,a2                        ; a2 = the value's descriptor
	movea.l	(a2),a2                         ; a2 = its text
	addq.w	#1,d0                           ; length in words, rounded up
	lsr.w	#1,d0                           ; words
	bra.s	.local_string_value_next        ; dbra count
.local_string_value_loop:
	move.w	(a2)+,(a1)+                     ; copy a word
.local_string_value_next:
	dbra	d0,.local_string_value_loop     ; all words
	rts
.local_string_take:
	movea.l	(a1)+,a2                        ; take over the value's text
	move.l	a2,(a0)                         ; into the variable
	move.w	(a1),d0                         ; its length
	st	(a1)                            ; the value descriptor is used up
	move.w	d0,4(a0)                        ; length
	ext.l	d0                              ; as a long
	beq.s	.local_string_done              ; empty: no back-link
	addq.w	#1,d0                           ; + 1
	andi.w	#$fffe,d0                       ; even offset
	move.l	a0,0(a2,d0.l)                   ; back-link to the variable
.local_string_done:
	rts
.local_string_no_room:
	jsr	rn_string_garbage_collect(a6)   ; routine $203: garbage collection
	movea.l	$60(a4),a2                      ; check again
	suba.w	#$a,a2                          ; room for 10 bytes
	cmpa.l	a2,a3                           ; room now?
	bcs.s	.local_string_push              ; room now
	moveq	#90,d0                          ; error 90 'LOCAL error'
	jmp	rn_error_entry(a6)              ; runtime error

;------------------------------------------------------------------------------
; Runtime routine $177: empty the string variable a0 and mark its old
; text free (-size at the back-link).
;------------------------------------------------------------------------------
rt_string_release:
	movea.l	(a0)+,a1                        ; text
	move.w	(a0),d0                         ; length
	beq.s	.release_done                   ; already empty
	clr.w	(a0)                            ; variable empty
	ext.l	d0                              ; as a long
	addq.w	#1,d0                           ; even offset of the back-link
	andi.w	#$fffe,d0                       ; even
	move.l	d0,d1                           ; d1 = -size
	neg.l	d1                              ; free mark
	move.l	d1,0(a1,d0.w)                   ; -size: free
.release_done:
	rts

;------------------------------------------------------------------------------
; Runtime routine $75: MIN of the floats d0-d2 and d3-d5 (d2/d5 = sign
; and exponent): the smaller ends in d0-d2.
;------------------------------------------------------------------------------
rt_min_float:
	move.l	d5,d6                           ; signs equal?
	eor.l	d2,d6                           ; d6 bit 31 = signs differ
	bpl.s	.min_same_sign                  ; same sign
	tst.l	d2                              ; first negative: it is smaller
	bmi.s	.min_keep_first                 ; first negative: it is smaller
	bra.s	.min_take_second                ; first positive, second negative: take the second
.min_same_sign:
	cmp.w	d2,d5                           ; exponents
	bne.s	.min_compare                    ; exponents differ
	cmp.l	d0,d3                           ; mantissa high
	bne.s	.min_compare                    ; differ: decide
	cmp.w	d1,d4                           ; mantissa low
	beq.s	.min_keep_first                 ; equal: keep the first
.min_compare:
	bcs.s	.min_second_smaller             ; second smaller in size
	tst.l	d2                              ; second larger in size: keep the first if positive
	bpl.s	.min_keep_first                 ; positive: keep the first
.min_take_second:
	move.l	d3,d0                           ; take the second number
	move.w	d4,d1                           ; mantissa low
	move.l	d5,d2                           ; sign and exponent
	rts
.min_second_smaller:
	tst.l	d2                              ; second smaller in size: take it if positive
	bpl.s	.min_take_second                ; negative: keep the first
.min_keep_first:
	rts

;------------------------------------------------------------------------------
; Runtime routine $76: MAX of the floats d0-d2 and d3-d5, into d0-d2.
;------------------------------------------------------------------------------
rt_max_float:
	move.l	d5,d6                           ; signs equal?
	eor.l	d2,d6                           ; d6 bit 31 = signs differ
	bpl.s	.max_same_sign                  ; same sign
	tst.l	d2                              ; first positive: it is larger
	bpl.s	.max_keep_first                 ; first positive: it is larger
	bra.s	.max_take_second                ; first negative, second positive: take the second
.max_same_sign:
	cmp.w	d2,d5                           ; exponents
	bne.s	.max_compare                    ; differ: decide
	cmp.l	d0,d3                           ; mantissa high
	bne.s	.max_compare                    ; differ: decide
	cmp.w	d1,d4                           ; mantissa low
	beq.s	.max_keep_first                 ; equal: keep the first
.max_compare:
	bhi.s	.max_second_smaller             ; second larger in size
	tst.l	d2                              ; second smaller in size: keep the first if positive
	bpl.s	.max_keep_first                 ; positive: keep the first
.max_take_second:
	move.l	d3,d0                           ; take the second number
	move.w	d4,d1                           ; mantissa low
	move.l	d5,d2                           ; sign and exponent
	rts
.max_second_smaller:
	tst.l	d2                              ; second larger in size: take it if positive
	bpl.s	.max_take_second                ; negative: keep the first
.max_keep_first:
	rts

;------------------------------------------------------------------------------
; Runtime routines $78 ($b632, d7 = 0) and $77 ($b636, d7 = -1): MIN$/
; MAX$ of the strings a0 and a1. Exit: $212 on the chosen string
; (a1 = text, d0 = length), a0 = the other descriptor.
;------------------------------------------------------------------------------
rt_min_string:
	moveq	#0,d7                           ; $78: the smaller string
	bra.s	rt_min_max_string               ; compare

;------------------------------------------------------------------------------
; Runtime routine $77: MAX$ of the strings a0 and a1 (d7 = -1).
;------------------------------------------------------------------------------
rt_max_string:
	moveq	#-1,d7                          ; $77: the larger string

rt_min_max_string:
	move.l	a0,d0                           ; descriptors
	move.l	a1,d3                           ; d3 = second descriptor
	move.w	4(a0),d1                        ; lengths
	move.w	4(a1),d4                        ; d4 = second length
	movea.l	(a0),a0                         ; texts
	movea.l	(a1),a1                         ; a1 = second text
	move.w	d1,d5                           ; compare up to the shorter length
	cmp.w	d4,d5                           ; the shorter
	bcs.s	.strcmp_lengths                 ; the first
	move.w	d4,d5                           ; the second
.strcmp_lengths:
	moveq	#0,d6                           ; d6 = 0, not used further
	bra.s	.strcmp_next                    ; dbne count
.strcmp_loop:
	cmpm.b	(a0)+,(a1)+                     ; compare bytes
.strcmp_next:
	dbne	d5,.strcmp_loop                 ; until a byte differs
	bne.s	.strcmp_decide                  ; a byte differs: decide by it
	cmp.w	d1,d4                           ; equal so far: the shorter is smaller
.strcmp_decide:
	bhi.s	.strcmp_select                  ; second larger: keep the first
	exg	d0,d3                           ; else the second
.strcmp_select:
	tst.b	d7                              ; smaller wanted?
	beq.s	.strcmp_result                  ; larger wanted: the other one
	exg	d0,d3                           ; the other one
.strcmp_result:
	movea.l	d0,a0                           ; a0 = the chosen descriptor
	jsr	rn_string_text_len_212(a6)      ; routine $212: a1 = text, d0 = length
	movea.l	d3,a0                           ; a0 = the other descriptor
	rts

;------------------------------------------------------------------------------
; Runtime routine $1a1: unwind the whole procedure stack down to $5c(a4), restoring LOCAL
; variables; a0 = where to continue (pushed and returned to).
;------------------------------------------------------------------------------
rt_unwind_all:
	move.l	a0,-(sp)                        ; keep the return address
.unwind_all_loop:
	cmpa.l	$5c(a4),a3                      ; procedure stack empty?
	beq.s	rt_unwind_done                  ; empty
	bsr.s	rt_unwind_one_entry             ; pop one entry
	bra.s	.unwind_all_loop                ; until it is empty

;------------------------------------------------------------------------------
; Runtime routine $1a0: RESUME - unwind a3 to its value at the error
; ($236(a4)) and return to the error PC $b40(a4); below the stack base
; error 92 'Resume (next) not possible'.
;------------------------------------------------------------------------------
rt_resume:
	cmpa.l	$236(a4),a3                     ; back at the error's stack level?
	bne.s	rt_resume_unwind                ; not yet: pop one
	move.l	a3,rn_saved_registers(a6)       ; save a3 in routine 4
	move.l	$b40(a4),(sp)                   ; return to the error PC

;------------------------------------------------------------------------------
; Runtime: rts shared by rt_unwind_all and rt_resume.
;------------------------------------------------------------------------------
rt_unwind_done:
	rts

;------------------------------------------------------------------------------
; Runtime: RESUME below the error's level: one entry popped, then the test again; error 92
; when the stack base is passed.
;------------------------------------------------------------------------------
rt_resume_unwind:
	bsr.s	rt_unwind_one_entry             ; pop one entry
	cmpa.l	$5c(a4),a3                      ; still above the stack base?
	bcc.s	rt_resume                       ; still above the base: again
	moveq	#92,d0                          ; error 92 'Resume (next) not possible'
	jmp	rn_error_entry(a6)              ; runtime error

;------------------------------------------------------------------------------
; Runtime: pop one procedure-stack entry: skip frames (size byte), restore LOCAL records;
; stops after a return address. Unlike RETURN it restores long and word records to -(a1), 4 or
; 2 bytes below the variable (the float record holds the address + 4, the others the address).
;------------------------------------------------------------------------------
rt_unwind_one_entry:
	move.l	-(a3),d3                        ; pop
	bmi.s	.unwind_local                   ; negative: LOCAL record
	move.b	(a3),d0                         ; frame size byte
	beq.s	.unwind_return_found            ; 0: a return address, done
	ext.w	d0                              ; as a word
	suba.w	d0,a3                           ; drop the frame
	bra.s	rt_unwind_one_entry             ; next entry
.unwind_return_found:
	rts
.unwind_local:
	movea.l	d3,a1                           ; variable address
	add.l	d3,d3                           ; bit 30?
	bmi.s	.unwind_long_or_word            ; set: $c0 or $e0
	add.l	d3,d3                           ; bit 29?
	bmi.s	.unwind_string                  ; set: $a0 string
	move.w	-(a3),(a1)                      ; $80: float back
	move.l	-(a3),-(a1)                     ; mantissa (a1 = the address + 4)
	bra.s	rt_unwind_one_entry             ; next entry
.unwind_long_or_word:
	add.l	d3,d3                           ; bit 29?
	bmi.s	.unwind_word                    ; set: $e0 word
	move.l	-(a3),-(a1)                     ; $c0: long back, but to -(a1): 4 bytes below the variable
	bra.s	rt_unwind_one_entry             ; next entry
.unwind_word:
	move.w	-(a3),-(a1)                     ; $e0: word back, but to -(a1): 2 bytes below the variable
	bra.s	rt_unwind_one_entry             ; next entry
.unwind_string:
	lsr.l	#2,d3                           ; $a0: string, descriptor address
	movea.l	(a1)+,a2                        ; a2 = current text
	move.w	(a1),d4                         ; d4 = current length
	beq.s	.unwind_string_old              ; empty: nothing to free
	ext.l	d4                              ; mark the current text free
	addq.w	#1,d4                           ; + 1
	andi.w	#$fffe,d4                       ; even offset
	move.l	d4,d5                           ; d5 = -size
	neg.l	d5                              ; negative
	move.l	d5,0(a2,d4.l)                   ; free mark
.unwind_string_old:
	move.w	-(a3),d4                        ; old descriptor back
	movea.l	-(a3),a2                        ; old text
	move.w	d4,(a1)                         ; length back
	beq.s	rt_unwind_one_entry             ; empty: no text, no back-link
	move.l	a2,-(a1)                        ; text back
	ext.l	d4                              ; as a long
	addq.w	#1,d4                           ; + 1
	andi.w	#$fffe,d4                       ; even offset
	move.l	d3,0(a2,d4.l)                   ; back-link
	bra.s	rt_unwind_one_entry             ; next entry

;------------------------------------------------------------------------------
; Runtime routine $1a2: drop frames from a3 up to the next LOCAL record or return address
; (the return address is taken off, a LOCAL record is left), save a3 in routine 4. a0 = where to
; continue.
;------------------------------------------------------------------------------
rt_pop_frames:
	move.l	a0,-(sp)                        ; keep the return address
.pop_frames_loop:
	move.l	-(a3),d3                        ; pop
	bmi.s	.pop_frames_local               ; LOCAL record: stop, keep it
	move.b	(a3),d0                         ; frame size byte
	beq.s	.pop_frames_save                ; 0: return address, taken off
	ext.w	d0                              ; as a word
	suba.w	d0,a3                           ; drop the frame
	bra.s	.pop_frames_loop                ; next entry
.pop_frames_local:
	addq.l	#4,a3                           ; put the record back
.pop_frames_save:
	move.l	a3,rn_saved_registers(a6)       ; save a3 in routine 4
	rts

;------------------------------------------------------------------------------
; Runtime routine $1be: RESUME NEXT - walk the table of code bytes per
; line that follows the DATA ($ade+$ae6, word aligned) from routine 3+2
; until it reaches the error PC, then RESUME ($1a0) at the next line.
;------------------------------------------------------------------------------
rt_resume_next:
	movea.l	$b40(a4),a0                     ; error PC
	move.l	$ade(a4),d0                     ; DATA address + size ...
	add.l	$ae6(a4),d0                     ; + DATA size
	addq.l	#1,d0                           ; + 1
	andi.w	#$fffe,d0                       ; ... word aligned: code bytes per line
	movea.l	d0,a1                           ; a1 = the table of line lengths
	lea	rn_runtime_routine_table(a6),a2 ; routine 3, +2 below: taken as the first line's code
	addq.l	#2,a2                           ; + 2
.next_line_loop:
	cmpa.l	a2,a0                           ; at the error line?
	beq.s	.next_line_found                ; found
	adda.w	(a1)+,a2                        ; next line start
	bra.s	.next_line_loop                 ; next line
.next_line_found:
	adda.w	(a1),a2                         ; start of the following line
	move.l	a2,$b40(a4)                     ; becomes the PC to resume at
	jmp	rn_resume(a6)                   ; routine $1a0: RESUME

;------------------------------------------------------------------------------
; Runtime routines $1ab ($b73c, start PRINT USING with format string
; a0: $22c(a4) = descriptor, $230(a4) = position 0), $1ae ($b74c, print
; the rest of the format), $1af ($b764, the rest and a new line with
; $125), $1ad ($b76a, a string item: _ ! & \..\) and $1ac ($b820, a
; number: # . , + - * $ ^^^^ _; too wide gives '%' and the plain number).
;------------------------------------------------------------------------------
rt_using_start:
	move.l	a0,$22c(a4)                     ; format string descriptor
	clr.w	$230(a4)                        ; position in the format
	rts                                     ; done

; Runtime data: 'E+000 ', exponent text of the number being formatted.
rt_using_exponent_text:
	dc.w	$452b                           ; data 'E+000 ' (decoded as dc.w and move.w)
	move.w	$20(a0,d3.w),d0                 ; data '000 ' (not code)

;------------------------------------------------------------------------------
; Runtime routine $1ae: print the rest of the PRINT USING format from the position reached
; ($211).
;------------------------------------------------------------------------------
rt_using_print_rest:
	movea.l	$22c(a4),a0                     ; format string
	jsr	rn_string_text_len_212(a6)      ; routine $212: a1 = text, d0 = length
	adda.w	$230(a4),a1                     ; from the position reached
	sub.w	$230(a4),d0                     ; characters left
	ble.s	.rest_done                      ; nothing left
	jmp	rn_print_text(a6)               ; routine $211: print d0 characters at a1
.rest_done:
	rts                                     ; done

;------------------------------------------------------------------------------
; Runtime routine $1af: the rest of the PRINT USING format, then a new line ($125).
;------------------------------------------------------------------------------
rt_using_print_rest_newline:
	bsr.s	rt_using_print_rest             ; rest of the format
	jmp	rn_print_crlf(a6)               ; routine $125: new line

;------------------------------------------------------------------------------
; Runtime routine $1ad: PRINT USING of the string a0: literal format characters are printed
; up to the next field: '!' first character, '&' the whole string, '\..\' a field as wide as
; the backslashes and what is between (padded with spaces); '_' prints the next character
; literally; no field left prints '?' and the string.
;------------------------------------------------------------------------------
rt_using_string:
	pea	(a0)                            ; string to print
.string_loop:
	movea.l	$22c(a4),a0                     ; format
	movea.l	(a0)+,a1                        ; a1 = format text
	move.w	(a0),d2                         ; length
	move.w	$230(a4),d1                     ; position
	addq.w	#1,$230(a4)                     ; next position
	cmp.w	d2,d1                           ; format used up?
	bcc.w	.string_no_field                ; used up: no field
	move.b	0(a1,d1.w),d0                   ; next format character
	cmpi.b	#$5f,d0                         ; '_': next one literally
	beq.s	.string_escape                  ; '_'
	cmpi.b	#$21,d0                         ; '!': first character
	beq.s	.string_first_char              ; '!'
	cmpi.b	#$26,d0                         ; '&': whole string
	beq.s	.string_whole                   ; '&'
	cmpi.b	#$5c,d0                         ; '\': field \..\
	beq.s	.string_field                   ; backslash
.string_literal:
	jsr	rn_print_char(a6)               ; routine $123: print character d0
	bra.s	.string_loop                    ; next format character
.string_escape:
	addq.w	#1,$230(a4)                     ; skip the '_'
	move.b	1(a1,d1.w),d0                   ; the character after it
	bra.s	.string_literal                 ; printed literally
.string_first_char:
	movea.l	(sp)+,a0                        ; a0 = the string
	jsr	rn_string_text_len_212(a6)      ; routine $212: a1 = text, d0 = length
	tst.w	d0                              ; empty?
	bne.s	.string_first_print             ; empty string ...
	moveq	#32,d0                          ; ... prints a space
	jmp	rn_print_char(a6)               ; print it
.string_first_print:
	move.b	(a1),d0                         ; its first character
	jmp	rn_print_char(a6)               ; print it
.string_whole:
	movea.l	(sp)+,a0                        ; a0 = the string
	jmp	rn_print_string(a6)             ; routine $121: print the string a0
.string_field_cut:
	move.l	d1,d0                           ; only the field width
	jmp	rn_print_text(a6)               ; routine $211: print d0 characters at a1
.string_field:
	moveq	#1,d0                           ; field width: the two backslashes ...
.string_field_scan:
	addq.w	#1,d0                           ; ... and what is between
	addq.w	#1,d1                           ; next format character
	cmp.w	d2,d1                           ; end of the format?
	bcc.s	.string_field_end               ; yes: the field ends there
	cmpi.b	#$5c,0(a1,d1.w)                 ; closing backslash?
	bne.s	.string_field_scan              ; not yet
.string_field_end:
	addq.w	#1,d1                           ; past it
	move.w	d1,$230(a4)                     ; position after the field
	movea.l	(sp)+,a0                        ; a0 = the string
	move.l	d0,-(sp)                        ; keep the width
	jsr	rn_string_text_len_212(a6)      ; routine $212: a1 = text, d0 = length
	move.l	(sp)+,d1                        ; d1 = field width
	cmp.w	d0,d1                           ; string at least as long as the field?
	bls.s	.string_field_cut               ; not shorter: print the field width only
	sub.w	d0,d1                           ; spaces after the string
	ext.l	d0                              ; length as a long
	move.l	d1,-(sp)                        ; keep the number of spaces
	jsr	rn_print_text(a6)               ; routine $211: print the string
	move.l	(sp)+,d0                        ; d0 = number of spaces
	jmp	rn_print_spc(a6)                ; routine $128: print d0 spaces
.string_no_field:
	moveq	#63,d0                          ; no field in the format: '?'
	jsr	rn_print_char(a6)               ; print it
	movea.l	(sp)+,a0                        ; a0 = the string
	jmp	rn_print_string(a6)             ; routine $121: print the string

;------------------------------------------------------------------------------
; Runtime: PRINT USING number does not fit: '%' and the number printed plainly ($120).
;------------------------------------------------------------------------------
rt_using_too_wide:
	moveq	#37,d0                          ; number too wide: '%'
	jsr	rn_print_char(a6)               ; print it
	movem.l	(sp)+,d0-d2                     ; the number back
	jmp	rn_print_float(a6)              ; routine $120: print the number plainly

;------------------------------------------------------------------------------
; Runtime routine $1ac: PRINT USING of the number d0-d2: literals up to the next field, then
; the field scanned (d3 places before the point, d4 after, d5 '^' characters, d6 flags '*', '$',
; sign), the number formatted ($f7), rounded, placed at $15b(a4) in a zero-filled buffer and
; printed with fill (spaces or '*'), '$' and sign.
;------------------------------------------------------------------------------
rt_using_number:
	movem.l	d0-d2,-(sp)                     ; the number
.number_loop:
	movea.l	$22c(a4),a0                     ; format
	movea.l	(a0)+,a1                        ; a1 = format text
	move.w	(a0),d2                         ; d2 = format length
	move.w	$230(a4),d1                     ; position
	addq.w	#1,$230(a4)                     ; next position
	cmp.w	d2,d1                           ; format used up?
	bcc.s	rt_using_too_wide               ; used up: no number field
	move.b	0(a1,d1.w),d0                   ; d0 = format character
	cmpi.b	#$5f,d0                         ; '_': next one literally
	beq.s	.number_escape                  ; '_'
	moveq	#0,d3                           ; d3 digits before the point
	moveq	#0,d4                           ; d4 digits after it
	moveq	#0,d5                           ; d5 exponent characters
	moveq	#0,d6                           ; d6 flags: 0 '*', 1 '$', 2 sign, 15 minus
	cmpi.b	#$2b,d0                         ; '+' sign field
	beq.s	.number_sign                    ; '+'
	cmpi.b	#$2d,d0                         ; '-' sign field
	beq.s	.number_sign                    ; '-'
	cmpi.b	#$2a,d0                         ; '*' fill
	beq.s	.number_star                    ; '*'
	cmpi.b	#$24,d0                         ; '$'
	beq.s	.number_dollar                  ; '$'
	cmpi.b	#$23,d0                         ; '#' digit
	beq.s	.number_digit                   ; '#'
.number_literal:
	jsr	rn_print_char(a6)               ; routine $123: print character d0
	bra.s	.number_loop                    ; next format character
.number_escape:
	addq.w	#1,$230(a4)                     ; skip the '_'
	move.b	1(a1,d1.w),d0                   ; the character after it
	bra.s	.number_literal                 ; printed literally
.number_star:
	bset	#$0,d6                          ; flag 0: '*' fill
	bra.s	.number_digit                   ; and a digit place
.number_sign:
	bset	#$2,d6                          ; flag 2: sign field
	bra.s	.number_scan                    ; no digit place
.number_dollar:
	bset	#$1,d6                          ; flag 1: '$'
.number_digit:
	addq.w	#1,d3                           ; one more place before the point
.number_scan:
	addq.w	#1,d1                           ; next format character
	cmp.w	d2,d1                           ; end of the format?
	bcc.w	.number_convert                 ; yes: convert
	move.b	0(a1,d1.w),d0                   ; d0 = format character
	cmpi.b	#$5f,d0                         ; '_'?
	bne.s	.number_scan_char               ; no
	addq.w	#1,d1                           ; skip it and the next
	bra.s	.number_scan                    ; next character
.number_scan_char:
	cmpi.b	#$23,d0                         ; '#'?
	beq.s	.number_digit                   ; '#': a digit place
	cmpi.b	#$24,d0                         ; '$'?
	beq.s	.number_dollar                  ; '$'
	cmpi.b	#$2a,d0                         ; '*'?
	beq.s	.number_star                    ; '*'
	cmpi.b	#$2c,d0                         ; ',' takes a place but no digit
	beq.s	.number_scan                    ; ',': a place, no digit
	cmpi.b	#$5e,d0                         ; '^' exponent
	beq.s	.number_exponent                ; '^': exponent
	cmpi.b	#$2b,d0                         ; '+' after the digits?
	beq.s	.number_trailing_sign           ; '+' after the digits
	cmpi.b	#$2d,d0                         ; '-' after the digits?
	beq.s	.number_trailing_sign           ; '-' after the digits
	cmpi.b	#$2e,d0                         ; '.' decimal point
	bne.s	.number_convert                 ; anything else ends the field
	moveq	#-1,d4                          ; digits after the point
.number_decimals:
	addq.w	#1,d4                           ; one more digit after the point
	addq.w	#1,d1                           ; next format character
	cmp.w	d2,d1                           ; end of the format?
	bcc.s	.number_convert                 ; yes: convert
	move.b	0(a1,d1.w),d0                   ; d0 = format character
	cmpi.b	#$23,d0                         ; '#'?
	beq.s	.number_decimals                ; another digit
	cmpi.b	#$5e,d0                         ; '^'?
	beq.s	.number_exponent                ; '^'
	cmpi.b	#$2b,d0                         ; '+'?
	beq.s	.number_trailing_sign           ; '+'
	cmpi.b	#$2d,d0                         ; '-'?
	beq.s	.number_trailing_sign           ; '-'
	cmpi.b	#$5f,d0                         ; '_'?
	bne.s	.number_convert                 ; anything else ends the field
	addq.w	#1,d1                           ; skip it
	bra.s	.number_decimals                ; next character
.number_exponent:
	addq.w	#1,d5                           ; one exponent place
	addq.w	#1,d1                           ; next format character
	cmp.w	d2,d1                           ; end of the format?
	bcc.s	.number_convert                 ; yes: convert
	move.b	0(a1,d1.w),d0                   ; d0 = format character
	cmpi.b	#$5e,d0                         ; another '^'?
	beq.s	.number_exponent                ; another '^'
	cmpi.b	#$2b,d0                         ; '+'?
	beq.s	.number_trailing_sign           ; '+'
	cmpi.b	#$2d,d0                         ; '-'?
	bne.s	.number_convert                 ; anything else ends the field
.number_trailing_sign:
	bset	#$2,d6                          ; flag 2: sign field
.number_convert:
	movea.w	d1,a1                           ; a1 = end of the field
	movem.l	(sp),d0-d2                      ; d0-d2 = the number
	movem.l	d3-d6/a1,-(sp)                  ; keep the field layout and its end
	jsr	rn_float_to_digits(a6)          ; routine $f7: float to digit text
	movem.l	(sp),d3-d5                      ; d3-d5 back
	move.l	d4,d1                           ; digits wanted
	bsr.w	rt_using_round_digits           ; round to them
	lea	rt_using_exponent_text(pc),a1   ; keep the exponent characters
	move.l	$c(a0),(a1)+                    ; 'E+00' of the formatted exponent kept
	move.b	$10(a0),(a1)+                   ; and the last exponent digit
	movem.l	(sp)+,d3-d6/a1                  ; the field layout back
	move.w	d3,d1                           ; field width
	add.w	d4,d1                           ; + after the point
	add.w	d5,d1                           ; + exponent places
	cmpi.w	#$12c,d1                        ; more than 300 places?
	bhi.w	rt_using_too_wide               ; too wide
	cmpi.b	#$2d,(a0)+                      ; minus sign in the text?
	bne.s	.number_sign_done               ; positive
	bset	#$f,d6                          ; flag 15: negative
.number_sign_done:
	lea	$94(a4),a2                      ; work buffer
	moveq	#49,d2                          ; 200 zero bytes
.number_clear_loop:
	clr.l	(a2)+                           ; clear a long
	dbra	d2,.number_clear_loop           ; 50 longs
	moveq	#49,d2                          ; then 200 '0' characters
.number_zero_loop:
	move.l	#$30303030,(a2)+                ; four '0' characters
	dbra	d2,.number_zero_loop            ; 50 longs
	lea	$15b(a4),a2                     ; position of the units digit
	tst.w	d5                              ; with an exponent field ...
	bne.s	.number_place                   ; yes: no shift
	suba.w	d0,a2                           ; ... else shifted by the exponent
.number_place:
	moveq	#10,d2                          ; 11 digit characters
.number_copy_digits:
	move.b	(a0)+,(a2)+                     ; copy a digit
	dbra	d2,.number_copy_digits          ; 11 of them
.number_pad_zero:
	move.b	#$30,(a2)+                      ; pad with '0' up to the zero area
	tst.b	(a2)                            ; until the '0' characters
	beq.s	.number_pad_zero                ; still the cleared area
	lea	$15c(a4),a2                     ; units digit
	tst.b	-(a2)                           ; the units place empty?
	bne.s	.number_find_start              ; no
	move.b	#$30,(a2)                       ; at least '0'
.number_find_start:
	tst.b	-(a2)                           ; back to the first digit
	bne.s	.number_find_start              ; until a zero byte
	btst	#$2,d6                          ; sign field present?
	bne.s	.number_dollar_test             ; yes: the sign is printed there
	tst.w	d6                              ; negative?
	bpl.s	.number_dollar_test             ; positive
	move.b	#$2d,(a2)                       ; '-' in front
	subq.l	#1,a2                           ; a2 before it
.number_dollar_test:
	btst	#$1,d6                          ; '$' wanted?
	beq.s	.number_field_start             ; no
	move.b	#$24,(a2)                       ; '$' in front
.number_field_start:
	lea	$15b(a4),a2                     ; a2 computed here is replaced at once by the lea below
	adda.w	d4,a2                           ; + places after the point
	tst.w	d5                              ; exponent field?
	beq.s	.number_lead_fill               ; no
	suba.w	d3,a2                           ; - places before the point
	addq.l	#1,a2                           ; + 1
.number_lead_fill:
	lea	$15c(a4),a2                     ; after the units digit
	tst.w	d5                              ; exponent field?
	beq.s	.number_check_fit               ; no: check the width
	moveq	#0,d3                           ; no places before the point
	tst.b	-$1(a2)                         ; a digit before the units place?
	beq.s	.number_fill_char               ; no: fill
	addq.w	#1,d3                           ; one place
.number_check_fit:
	suba.w	d3,a2                           ; start of the field
	tst.b	-$1(a2)                         ; digits beyond the field?
	bne.s	.number_too_wide                ; too wide
.number_fill_char:
	moveq	#32,d7                          ; fill with spaces ...
	btst	#$0,d6                          ; '*' fill?
	beq.s	.number_fill_loop               ; no: spaces
	moveq	#42,d7                          ; ... or '*'
.number_fill_loop:
	tst.b	(a2)                            ; fill the leading zero bytes
	bne.s	rt_using_output_number          ; reached the number: print it
	move.b	d7,(a2)+                        ; fill
	bra.s	.number_fill_loop               ; next byte
.number_too_wide:
	move.w	a1,$230(a4)                     ; too wide: back to the start of the field
	bra.w	rt_using_too_wide               ; print '%' and the number

;------------------------------------------------------------------------------
; Runtime: digit count d1 (+ exponent d0 when no ^ field) + 1,
; then routine $1c3 (rounding of the digit string).
;------------------------------------------------------------------------------
rt_using_round_digits:
	tst.w	d5                              ; with an exponent: d1 digits
	bne.s	.round_count                    ; exponent field: the digits only
	add.w	d0,d1                           ; else digits + exponent
.round_count:
	addq.w	#1,d1                           ; + 1
	jmp	rn_round_digits_count_d1(a6)    ; routine $1c3: round the digit text

;------------------------------------------------------------------------------
; Runtime: output a PRINT USING number: put the exponent in, then
; walk the format field again printing digits, ',', '.', signs.
;------------------------------------------------------------------------------
rt_using_output_number:
	lea	$15b(a4),a2                     ; units digit
	tst.w	d5                              ; exponent field?
	beq.s	.output_start                   ; no exponent field
	suba.w	d3,a2                           ; back by the places before the point
	sub.w	d5,d1                           ; less the exponent places
	lea	rt_using_exponent_text(pc),a0   ; exponent text: 'E'
	move.b	(a0)+,1(a2,d1.w)                ; 'E'
	move.b	(a0)+,2(a2,d1.w)                ; its sign
	cmpi.b	#$5,d5                          ; five exponent characters?
	beq.s	.output_exp_five                ; five: the hundreds digit too
	subq.w	#1,d1                           ; four characters: one place less
	addq.l	#1,a0                           ; skip the hundreds digit
	bra.s	.output_exp_rest                ; then tens and units
.output_exp_five:
	move.b	(a0)+,3(a2,d1.w)                ; hundreds
.output_exp_rest:
	move.b	(a0)+,4(a2,d1.w)                ; tens and units
	move.b	(a0)+,5(a2,d1.w)                ; units
	adda.w	d3,a2                           ; forward again
.output_start:
	suba.w	d3,a2                           ; a2 = before the first place of the field
	movea.l	$22c(a4),a0                     ; format text
	adda.l	(a0),a1                         ; end of the field
	pea	(a1)                            ; kept at 6(sp)
	move.w	d6,-(sp)                        ; flags
	pea	1(a2)                           ; next digit
	subq.w	#1,$230(a4)                     ; back to the start of the field
.output_loop:
	movea.l	$22c(a4),a0                     ; the format string
	movea.l	(a0)+,a1                        ; a1 = format text
	adda.w	$230(a4),a1                     ; + the position
	addq.w	#1,$230(a4)                     ; next position
	cmpa.l	6(sp),a1                        ; end of the field?
	beq.s	.output_done                    ; field done
	move.b	(a1)+,d0                        ; next format character
	cmpi.b	#$5f,d0                         ; '_' literally
	beq.s	.output_escape                  ; '_'
	cmpi.b	#$2c,d0                         ; ','
	beq.s	.output_comma                   ; ','
	cmpi.b	#$2e,d0                         ; '.'
	beq.s	.output_char                    ; '.' printed as it is
	cmpi.b	#$2b,d0                         ; '+'
	beq.s	.output_plus_field              ; '+'
	cmpi.b	#$2d,d0                         ; '-'
	beq.s	.output_minus_field             ; '-'
	movea.l	(sp)+,a2                        ; anything else: the next digit
	move.b	(a2)+,d0                        ; the digit
	pea	(a2)                            ; digit pointer back on the stack
.output_char:
	jsr	rn_print_char(a6)               ; routine $123: print character d0
	bra.s	.output_loop                    ; next format character
.output_comma:
	movea.l	(sp),a2                         ; a digit printed before?
	cmpi.b	#$30,-(a2)                      ; the byte before the digit: a digit printed?
	bcc.s	.output_char                    ; then ','
	move.b	(a2),d0                         ; else the fill character
	bra.s	.output_char                    ; print it
.output_escape:
	addq.w	#1,$230(a4)                     ; skip the '_'
	move.b	(a1)+,d0                        ; the character after it
	bra.s	.output_char                    ; print it
.output_minus_field:
	moveq	#32,d0                          ; positive under '-': space
.output_plus_field:
	tst.w	4(sp)                           ; negative?
	bpl.s	.output_char                    ; positive: '+' or the space
	moveq	#45,d0                          ; '-'
	bra.s	.output_char                    ; print it
.output_done:
	adda.w	#$16,sp                         ; drop the work values
	subq.w	#1,$230(a4)                     ; position back on the end of the field

;------------------------------------------------------------------------------
; Runtime: the last rts of the PRINT USING number code and the end of
; the runtime; the compiler uses this address + 2 as the table start.
;------------------------------------------------------------------------------
rt_last_return:
	rts                                     ; end of the runtime; table at +2

; Compiler data: the runtime routine table, decoded as instructions up
; to $d176. One block per routine group, from loc_05724 on, in order:
;   n,offset   routine n starts at block+offset (n > 0)
;   0,offset   the word at block+offset is a routine number this block
;              needs (the jsr n(a6) displacements and dc.w markers)
;   $ffff,len  end of the block; the next starts len ($7fff mask) later
; sub_047d4 builds the offset table at bss_end+$b0, sub_04812 marks a
; routine and what it needs. It ends at bas_file_handle ($d028).
runtime_routine_table:
	dc.w	$0001                           ; routine table (data): 1 at +0, needs at +$68, +$70 ...

